P.entries["quest:92466"] = {n="Call of Earth",s="In Call of Earth sammeln Anwärter, was ihr Lehrmeister von ihnen verlangt. Ihr Einsatz zeigt, ob sie bereit sind, ihre Ausbildung fortzusetzen.",h="In Call of Earth sammeln Anwärter, was ihr Lehrmeister von ihnen verlangt.",kw={"call of earth","entschlossenheit","erde","elemente","schamane","geister","prüfung"},ang={["class:Shaman"]="Als Schamane beweist Ihr Eure Entschlossenheit, bevor Ihr tiefere Einblicke in die Zwiesprache mit den Geistern von Stein und Erde erlangt.",["faction:Horde"]="In der Horde begegnet Ihr schamanischen Prüfungen wie Call of Earth als grundlegendem Ritus für jene, die einen spirituellen Weg beschreiten."},sec={{t="Eine Prüfung der Entschlossenheit",b="Ein Anwärter stellt sich einer Prüfung seiner Entschlossenheit, wenn der Lehrmeister bestimmte Materialien verlangt. Das Sammeln prüft Geduld und Ausdauer. Indem der Schüler die Forderungen der Erde erfüllt, zeigt er die nötige Stärke, um mit ihrer beständigen Macht Zwiesprache zu halten."},{t="Der nächste Schritt",b="Wenn der Anwärter mit den geforderten Opfergaben zurückkehrt, erkennt der Lehrmeister seine Zähigkeit. Der Schüler hat während der Prüfung standgehalten und ist bereit für den nächsten Schritt seiner spirituellen Ausbildung."}},faq={{q="Was ist Call of Earth?",a="Call of Earth verlangt von spirituellen Anwärtern, geforderte Gegenstände zu sammeln und ihr Durchhaltevermögen zu beweisen, bevor sie in ihrer Ausbildung voranschreiten.",al={"was ist call of earth","call of earth quest"}},{q="Was beweist das Bestehen dieser Prüfung?",a="Das Bestehen der Prüfung zeigt Eurem Mentor Eure Zähigkeit und Entschlossenheit. Es beweist, dass Eure Konzentration für größere spirituelle Verantwortung ausreicht.",al={"was wurde bewiesen","zähigkeit und entschlossenheit"}},{q="Was geschieht nach dem Abschluss von Call of Earth?",a="Nach Call of Earth hält Euer Lehrmeister Euch für bereit für den nächsten Schritt auf dem Weg zur Zwiesprache mit den Elementen.",al={"wie geht es weiter","nächste quest"}},{q="Warum muss ein Anwärter mit der Erde Zwiesprache halten?",a="Ein Anwärter beweist Ausdauer, bevor er mit Erdgeistern Zwiesprache hält, deren Wesen Beständigkeit und Stärke widerspiegelt.",al={"warum erde","bedeutung der erdgeister"}},{q="Wer wacht über Call of Earth?",a="Ein spiritueller Lehrer oder schamanischer Mentor führt Anwärter durch die Prüfung und beurteilt ihre Disziplin und Bereitschaft, sich mit den Geistern zu verbinden.",al={"wer vergibt diese quest","call of earth lehrmeister"}},{q="Wer darf sich dieser Prüfung stellen?",a="Call of Earth prüft jene, die lernen, sich auf die Elemente einzustimmen.",al={"kann jeder call of earth absolvieren","ist call of earth für schamanen"}}},fp="13,139,17.238.0,13.185.0,26.123.0,43.147.0,48.110.0,40.111.0,31.139.0,40.72.0"}
P.entries["quest:92467"] = {n="Call of Earth",s="An der Anhöhe der Geister trinkt Ihr ein Earth Sapta und begegnet einem elementaren Führer. Die Stärke der Erde mag Euch helfen, die Winde erneut zu suchen.",h="An der Anhöhe der Geister trinkt Ihr ein Earth Sapta und begegnet einem elementaren Führer.",kw={"call of earth","earth sapta","elemente","vier winde","anhöhe der geister","schamane","geister"},ang={["class:Shaman"]="Als Schamane nutzt Ihr Saptas, um Euren Geist auf ein Element einzustimmen und Zwiesprache mit dessen Geistern zu halten.",["race:Skyborne"]="Als Skyborne treibt Ihr womöglich hoch oben in einem endlosen Wolkenmeer umher und seid den vier Winden entfremdet. Die Erde gibt Euch eine feste Grundlage für Euer Verständnis."},sec={{t="Das Wesen der Saptas",b="Schamanen trinken Saptas, um ihren Blick für die elementare Welt zu öffnen. Jedes Gebräu stimmt einen sterblichen Geist auf ein Reich ein und offenbart Geister, die gewöhnlich verborgen bleiben. Nur wer genügend Entschlossenheit besitzt, kann ihre Macht ertragen. Ausgewählte Praktizierende hüten das Wissen um diese Gebräue."},{t="Die Anhöhe der Geister",b="Ihr reist nach Nordosten durch einen Pass zur Anhöhe der Geister, wo Anwärter Zwiesprache mit der Erde halten. Saptas werden nur an heiligen Stätten getrunken. Auf geweihtem Boden lässt Euch der Trank den Schleier durchdringen und sehen, was die Geister offenbaren wollen."},{t="Stärke der Erde",b="Nachdem Ihr das Earth Sapta getrunken habt, begrüßt Euch ein elementarer Führer als Kind der vier Winde. Ihr wollt erfahren, warum sie fortgegangen sind. Der Erdgeist kann die Beweggründe der Windgeister nicht erklären, lehrt Euch aber Stärke und standhafte Entschlossenheit.\n\nSelbst hoch oben, inmitten eines endlosen Wolkenmeers, müsst Ihr Euch zuerst in der Erde verankern. Erst dann könnt Ihr wieder mit den Winden sprechen."}},faq={{q="Was ist ein Earth Sapta?",a="Ein Earth Sapta ist ein magisches Gebräu, das Euren Geist auf das Element Erde einstimmt. Mit genügend Entschlossenheit könnt Ihr Elementargeister sehen, die gewöhnlichen Blicken verborgen bleiben.",al={"was ist earth sapta","sapta erklärung","was bewirkt sapta"}},{q="Wo muss das Earth Sapta getrunken werden?",a="Trinkt das Earth Sapta an der Anhöhe der Geister, die Ihr nach Nordosten durch einen Pass erreicht. Saptas werden nur auf heiligem Boden getrunken.",al={"wo earth sapta trinken","anhöhe der geister lage","wo ist die anhöhe der geister"}},{q="Warum dürfen Saptas nur an heiligen Orten getrunken werden?",a="Saptas sind mächtige Gebräue, die sterbliche Geister mit den Elementen verbinden. Die schamanische Tradition verlangt, sie an heiligen Stätten zu trinken, um Zwiesprache mit den Geistern zu halten.",al={"warum sapta an heiligem ort trinken","sapta überall trinken möglich"}},{q="Warum spricht der Geist den Suchenden als „Kind der vier Winde“ an?",a="Der Erdgeist begrüßt Euch als Kind der vier Winde, weil Ihr erfahren wollt, warum die Winde fortgegangen sind.",al={"wer ist das kind der vier winde","warum kind der vier winde"}},{q="Warum sind die Geister der Winde fortgegangen?",a="Selbst der Erdgeist an der Anhöhe der Geister weiß nicht, warum sich die Windgeister zurückgezogen haben oder wohin sie gegangen sind.",al={"warum gingen die winde fort","wohin gingen die winde"}},{q="Wie hilft die Zwiesprache mit der Erde dabei, die Verbindung zu den Winden wiederherzustellen?",a="Die Erde lehrt Stärke und Entschlossenheit. Selbst inmitten eines endlosen Wolkenmeers bleibt Ihr mit der Erde verbunden. Ihre Standhaftigkeit zu erlernen, ist der erste Schritt, um wieder mit den vier Winden zu sprechen.",al={"warum zuerst die erde","wie hilft die erde mit den winden"}}},fp="13,133,23.267.0,19.241.0,21.381.1,23.161.0,39.114.0,47.154.0,70.111.0,39.123.0,72.194.0"}
P.entries["quest:92468"] = {n="Call of Earth",s="Ein Erdgeist schickt Euch mit einem Splitter Rohquarz zu Windshaper Boros im Thendalhain. Dort wird der Splitter zum Herzstück Eures ersten Erdtotems und leitet Euer Studium der Elementarkräfte ein.",h="Ein Erdgeist schickt Euch mit einem Splitter Rohquarz zu Windshaper Boros im Thendalhain.",kw={"call of earth","erdtotem","elemente","rohquarz","schamane","thendalhain","windshaper boro","windshaper boros"},ang={["class:Shaman"]="Als Schamane beginnt Eure Zwiesprache mit den Elementarkräften, sobald Ihr Euer erstes Totem erhaltet. Es gibt Euch einen greifbaren Fokus für erdgebundene Zauber und Riten.",["race:Skyborne"]="Als Skyborne beginnt Ihr Eure Rückkehr zu den Winden, indem Ihr die Erde meistert und Euch in ihren festen Grundfesten verankert."},sec={{t="Die Gabe der Erde",b="Ein Erdgeist gibt Euch einen Splitter Rohquarz als Beweis Eurer Zwiesprache. Er schickt Euch mit dem Splitter zu Windshaper Boros im Thendalhain. Selbst das kleinste Bruchstück kann überdauern. Die Geister gewähren jenen Gunst und Respekt, die Geduld, Widerstandskraft und Weisheit zeigen."},{t="Die vier Elemente und das Totem",b="Windshaper Boros setzt den Rohquarz als Herzstück in Euer Erdtotem ein. Er erinnert Euch daran, dass der Pfad der Elemente aus vier Teilen besteht. Vielleicht sehnt Ihr Euch danach, die Lieder des Windes zu hören und zu singen. Doch Meisterschaft beginnt mit dem Verständnis aller vier Kräfte, angefangen beim unnachgiebigen Boden unter Euren Füßen."}},faq={{q="Wer ist Windshaper Boros?",a="Windshaper Boros, auch Boro genannt, lebt im Thendalhain. Als erfahrener Praktizierender und Handwerker lehrt er Initianten, die Elementargeister zu verstehen, und formt aus elementaren Gaben ihre Totems als Fokus.",al={"wer ist boro","windshaper boros standort","wo ist der thendalhain"}},{q="Wozu dient der Rohquarz?",a="Ein Erdgeist gibt Euch den Rohquarz als Beweis Eurer Begegnung und Zwiesprache. Windshaper Boros verwendet ihn als Grundlage und Herzstück Eures Erdtotems.",al={"was ist rohquarz","splitter der erde","quarz verwendung"}},{q="Warum ist ein Erdtotem notwendig?",a="Ein Erdtotem gibt Euch einen persönlichen Fokus, um mit Erdgeistern Zwiesprache zu halten und Erdzauber zu kanalisieren. Es kennzeichnet Euch als Initianten und verankert Euch in den elementaren Grundfesten der Welt.",al={"was bewirkt ein erdtotem","zweck des totems","warum ein totem nötig ist"}},{q="Warum muss man mit der Erde Zwiesprache halten, bevor man mit den Winden spricht?",a="Die Winde sind nur ein Teil des elementaren Gleichgewichts der Welt. Bevor Ihr nach ihren Liedern sucht, studiert Ihr alle vier Elemente, beginnend mit der Beständigkeit, Geduld und Stärke der Erde.",al={"warum mit der erde beginnen","suche nach den winden","alle vier elemente"}},{q="Wo liegt der Thendalhain?",a="Der Thendalhain ist das Heiligtum, in dem Windshaper Boros sich um elementare Angelegenheiten kümmert und Novizen am Anfang ihres schamanischen Weges unterweist.",al={"wo ist der thendalhain","thendalhain gebiet"}},{q="Welche Weisheit vermittelt der Erdgeist?",a="Der Erdgeist lehrt, dass selbst der kleinste Stein überdauern kann, wenn Größeres zerfällt. Für gegenseitigen Respekt und Einklang verlangt er Geduld, innere Stärke und das Streben nach Weisheit.",al={"was die elemente verlangen","philosophie der erde"}}},fp="13,200,16.270.0,31.290.0,24.205.0,40.156.0,32.191.0,63.180.0,31.136.0,41.202.0"}
P.entries["quest:92469"] = {n="Return to Rorian",s="Yala Windwatcher schickt Euch mit dringenden Nachrichten vom Einsatzort nach Thendalhain. Nachdem Ihr geholfen habt, die Aufrührer auf der Insel Zephras zurückzudrängen, berichtet sie, dass die Al'Aketh die örtlichen Windgeister aufgewiegelt haben.",h="Yala Windwatcher schickt Euch mit dringenden Nachrichten vom Einsatzort nach Thendalhain.",kw={"al'aketh","kult","rorian","steinkreise","thendalhain","windgeister","yala windwatcher","insel zephras"},ang={["class:Druid"]="Als Druide teilt Ihr die Pflicht, Thendalhain zu verteidigen und den Frieden an den heiligen Stätten der Insel Zephras zu bewahren.",["class:Shaman"]="Als Schamane wisst Ihr, dass die Al'Aketh das Gleichgewicht der Elemente bedrohen, indem sie gezielt Windgeister aufwiegeln."},sec={{t="Ein besorgniserregender Bericht",b="Yala Windwatcher bleibt auf der Insel Zephras, um sich den verbliebenen Feinden zu stellen. Sie schickt Euch nach Thendalhain mit der Nachricht, dass die Al'Aketh nicht länger nur im Verborgenen agieren."},{t="Eskalation an den Steinkreisen",b="Rorian the Dayseeker erklärt, dass die Anführer von Thendalhain die Al'Aketh schon seit einiger Zeit aus der Ferne beobachten. Nun haben die Kultisten einheimische Windgeister nahe den Steinkreisen aufgewiegelt. Das stellt eine beunruhigende Eskalation dar, und die Anführer können nicht länger aus der Ferne zusehen."}},faq={{q="Wer schickt Euch zu Rorian?",a="Nachdem Ihr geholfen habt, die feindlichen Aufrührer niederzuschlagen, die das Gebiet bedrohen, schickt Yala Windwatcher Euch zu Rorian, um Bericht zu erstatten.",al={"questgeber","wer startet return to rorian","yala windwatcher"}},{q="Wo befindet sich Rorian the Dayseeker?",a="Rorian the Dayseeker befindet sich in Thendalhain, wo die Anführer des Hains die Angelegenheiten auf der Insel Zephras beaufsichtigen.",al={"wo ist rorian","rorians standort","thendalhain rorian"}},{q="Wer sind die Al'Aketh?",a="Die Al'Aketh sind ein Kult auf der Insel Zephras. Die Anführer des Hains beobachteten sie still aus der Ferne, doch seit sie jüngst Windgeister nahe den Steinkreisen aufwiegelten, sind sie eine akute Bedrohung.",al={"was ist der kult","wer sind die al'aketh","al'aketh kult"}},{q="Warum überraschten Rorian die Nachrichten nicht?",a="Rorian und die Anführer des Hains wussten bereits von den Bewegungen des Kults auf der Insel. Bislang beobachteten sie ihn still, statt sich ihm direkt entgegenzustellen.",al={"wusste rorian bescheid","rorians reaktion","warum nicht überraschend"}},{q="Was geschieht, nachdem Ihr Rorian Bericht erstattet habt?",a="Nachdem Rorian Euren Bericht gehört und Euch für Eure Hilfe für Thendalhain gedankt hat, schickt er Euch zu Aetheen of the Gales, einem Mitglied des Council of Elders, das Euch beobachtet hat.",al={"nächste quest","was folgt auf return to rorian","nach return to rorian"}},{q="Warum blieb Yala zurück?",a="Yala Windwatcher bleibt am Ort des Konflikts, um sich um etwaige Nachzügler zu kümmern, während sie Euch mit den dringenden Nachrichten vorausschickt.",al={"warum bleibt yala","wohin ging yala","yala windwatchers rolle"}}},fx={aa0b8ee2={q="Warum schickt Euch Yala Windwatcher zu Rorian?",a="Yala muss die Führung im Thendalhain unverzüglich über die bestätigte Präsenz des Al'Aketh-Kults alarmieren. Während sie zurückbleibt, um die Nachzügler im Feld abzufertigen, muss Rorian the Dayseeker vor den Eskalationen des Kults und ihrer Aufwiegelung der lokalen Geister gewarnt werden, damit der Hain eine Reaktion koordinieren kann.",al={"warum rorian berichten","yala windwatcher motiv","warum will yala rorian informieren"}}},fp="16,202,13.176.0,33.264.1,35.115.0,38.100.0,21.192.0,41.160.0,44.171.1,25.117.0"}
P.entries["quest:92470"] = {n="Foul Matriarch",s="In den Höhlen südlich von Thendal prüft Aetheen of the Gales neue Initianden im Kampf gegen die Ursera. Sie müssen die Rudel ausdünnen und ihre Höhlenmutter Urs'anah töten, um zu beweisen, dass sie größeren Gefahren auf der Insel Zephras gewachsen sind.",h="In den Höhlen südlich von Thendal prüft Aetheen of the Gales neue Initianden im Kampf gegen die Ursera.",kw={"aetheen of the gales","foul matriarch","höhle von thendal","thendalhain","thendal","urs'anah","ursera","insel zephras"},ang={["class:Hunter"]="Als Jäger stellt Ihr Euer Wissen über Bestien und Eure Entschlossenheit auf die Probe, wenn Ihr eine wilde Matriarchin in ihrer Höhle aufspürt.",["race:Skyborne"]="Als Skyborne-Initiand zeigt Ihr durch den Sieg über Landraubtiere wie Urs'anah, dass Ihr Euch an Land selbst behaupten könnt. Ihr seid bereit, Euch über Eure abgeschiedenen Anfänge hinauszuwagen."},sec={{t="Eine Prüfung der Entschlossenheit",b="Rund um Thendal beobachtet Aetheen of the Gales, wie Neuankömmlinge Fuß fassen. Zeigt ein Initiand früh Geschick, schickt Aetheen ihn für einen gefährlichen Übergangsritus in die südlichen Höhlen. Dort dünnt er die örtlichen Urserarudel aus und stellt sich der Brutmutter, die den Dorfrand bedroht."},{t="Die Bedrohung durch Urs'anah",b="Die örtlichen Waldläufer wissen, wie wild die Ursera sind, doch Urs'anah ist die größte Bedrohung für die Zuflucht. Tief in der Höhle von Thendal lenkt die furchterregende Matriarchin ihre Aasfresser und bewacht ihren Bau. Ihr abgetrennter Kopf beweist, dass ein Abenteurer wilden Bestien gewachsen und bereit ist, sich über den anfänglichen Hain hinauszuwagen."}},faq={{q="Wer erteilt den Auftrag, Urs'anah zu töten?",a="Aetheen of the Gales erteilt die Prüfung in Thendal. Aetheen beobachtet vielversprechende Neuankömmlinge, die Einheimischen wie Rorian aufgefallen sind, und prüft dann ihren Mut mit einer gefährlichen Jagd.",al={"wer vergibt foul matriarch","foul matriarch questgeber","wer ist aetheen of the gales"}},{q="Wo sind Urs'anah und die aasfressenden Ursera zu finden?",a="Urs'anah und die aasfressenden Ursera leben in Höhlen südlich und südwestlich von Thendal, in den Hügeln des Thendalhains. Der Bau der Matriarchin liegt tief in der Höhle.",al={"urs'anah fundort","wo ist ursanah","ursera höhle zephras","höhle von thendal lage"}},{q="Was ist ein Ursera?",a="Ursera sind aggressive, bärenartige Raubtiere, die in den wilderen Felsregionen der Insel Zephras heimisch sind. Ihre aasfressenden Rudel können sich gefährlich nahe an Siedlungen wie Thendal niederlassen.",al={"was ist ein ursera","ursera hintergrundgeschichte","sind ursera bären"}},{q="Was bedeutet der Abschluss dieser Jagd für einen Abenteurer?",a="Urs'anah zu töten ist ein Übergangsritus. Indem der Jäger eingedrungene Kultisten und die gefährlichsten Wildtiere des Hains bezwingt, beweist er seine Bereitschaft, die Zuflucht Thendal zu verlassen und auf der Insel Zephras größere Verantwortung zu übernehmen.",al={"warum ursanah töten","bedeutung von foul matriarch"}}},fx={["03aee340"]={q="Warum schickt Euch Aetheen of the Gales gegen die Matriarchin?",a="Aetheen of the Gales hat Euren Fortschritt beobachtet und fordert einen Beweis Eurer Entschlossenheit. Sie muss wissen, ob Ihr die Stärke und Standhaftigkeit besitzt, um die weitaus größeren Gefahren zu überleben, die auf der Insel Zephras warten. Das Erlegen der gefährlichen Matriarchin beweist, dass Ihr fähig seid, über die Sicherheit von Thendal hinauszutreten und der Insel in tieferen, tückischeren Prüfungen zu dienen.",al={"warum will aetheen urs'anah tot","aetheen motiv","warum urs'anah töten"}},["30b9798a"]={q="Wofür wird der Kopf von Urs'anah verwendet?",a="Der Kopf dient als unbestreitbarer physischer Beweis für das Ableben der Matriarchin. Urs'anah ist eine berüchtigte Muttertier-Anführerin, die den lokalen Waldläufern bekannt ist, und Aetheen wird nichts weniger als ihren abgetrennten Kopf akzeptieren, um zu bestätigen, dass die gefährliche Bestie tatsächlich erlegt wurde.",al={"nutzen kopf von urs'anah","warum kopf von urs'anah behalten","zweck kopf von ursanah"}},a1adff34={q="Wer ist Urs'anah?",a="Urs'anah ist die wilde Matriarchin und das Muttertier der lokalen Ursera, die in den Höhlen südlich von Thendal hausen. Den Waldläufern der Insel bekannt und gefürchtet, befehligt sie das Aasfresser-Rudel, was sie zur primären Bedrohung unter den Raubtieren des Hains macht.",al={"wer ist ursanah","was ist urs'anah","urs'anah lore"}}},fp="14,220,17.293.0,22.297.0,38.181.0,54.169.0,18.178.0,57.242.0"}
P.entries["quest:92471"] = {n="Aetheen of the Gales",s="Auf der Insel Zephras suchen junge Abenteurer nach ihren ersten bestandenen Prüfungen Aetheen of the Gales im Thendalhain auf. Dort stellt sich die nächste Generation ihrem Urteil.",h="Auf der Insel Zephras suchen junge Abenteurer nach ihren ersten bestandenen Prüfungen Aetheen of the Gales im...",kw={"aetheen of the gales","council of elders","rorian the dayseeker","shen'dorei","thendalhain","insel zephras"},sec={{t="Ein Maß für Potenzial",b="Junge Novizen auf der Insel Zephras übernehmen erste Aufgaben, die ihre Entschlossenheit und ihren Geist prüfen. Die Mentoren der Insel halten nach jenen Ausschau, die bereit sind, ihre Heimat mitzuverteidigen. Rorian the Dayseeker erkennt Jugendliche, die für größere Verantwortung bereit sind."},{t="Die Windleserin des Thendalhains",b="Im Thendalhain liest Aetheen of the Gales die Luftströmungen. Sie gehört dem Council of Elders an, der die Insel Zephras regiert, und beurteilt junge Shen'dorei an der Schwelle zum Erwachsensein. Wenn Ihr Euch bei ihr meldet, führt Euch das über kleinere Aufgaben am Rand der Insel hinaus zu Bedrohungen für die Gemeinschaft."}},faq={{q="Wer ist Aetheen of the Gales?",a="Aetheen of the Gales gehört zu den Anführern auf der Insel Zephras und ist Mitglied ihres Council of Elders. Im Thendalhain liest sie die Winde und beurteilt heranwachsende Shen'dorei, um festzustellen, ob sie bereit sind, ihre Heimat zu verteidigen.",al={"wer ist aetheen","aetheen of the gales rolle","aetheen zephras"}},{q="Warum schickt Rorian Spieler zu Aetheen?",a="Nach ihren ersten Aufgaben schickt Rorian the Dayseeker fähige und widerstandsfähige Novizen zu Aetheen. Sie beurteilt ihre Fähigkeiten und weist ihnen größere Herausforderungen zu, denen sich die Insel stellen muss.",al={"warum aetheen treffen","rorian schickt zu aetheen","zweck dieser quest"}},{q="Wo ist Aetheen of the Gales zu finden?",a="Aetheen of the Gales ist im Thendalhain auf der Insel Zephras zu finden. Dort liest sie die Winde und beaufsichtigt die Prüfungen, mit denen die Jugendlichen der Insel ins Erwachsenenalter eintreten.",al={"aetheen aufenthaltsort","wo ist aetheen","thendalhain aetheen"}},{q="Was ist der Council of Elders?",a="Der Council of Elders regiert die Shen'dorei auf der Insel Zephras. Aetheen und die anderen Ratsoberhäupter kümmern sich um das Überleben, die Führung und die Einsatzbereitschaft ihrer Gemeinschaft.",al={"council of elders zephras","wer regiert zephras"}},{q="Was geschieht, nachdem man sich bei Aetheen gemeldet hat?",a="Sobald Aetheen einen jungen Abenteurer für bereit hält, der Insel Zephras zu dienen, überträgt sie ihm ernsthafte Aufgaben gegen Gefahren in der umliegenden Wildnis, darunter aggressive Wildtiere und üble Matriarchinnen.",al={"nächste quest nach aetheen","was will aetheen"}},{q="Was bedeutet es für Shen'dorei auf der Insel Zephras, erwachsen zu werden?",a="Für junge Shen'dorei auf der Insel Zephras bedeutet Erwachsenwerden, sich in körperlichen und magischen Prüfungen zu beweisen. Sie zeigen einem Ältesten der Insel wie Aetheen, dass sie dienen können, bevor sie diese Pflicht übernehmen.",al={"shen'dorei erwachsenwerden","zephras erwachsenwerden"}}},fx={d6e78b3c={q="Warum braucht Rorian gerade Euch, damit Ihr mit Aetheen sprecht?",a="Eure frühen Aufgaben auf der gesamten Insel wurden stillschweigend als Prüfungen behandelt, um Eure Tatkraft zu messen. Die Insel Zephras steht vor ernsthaften Herausforderungen, und ihre Anführer brauchen fähige, temperamentvolle junge Shen'dorei, die ihr Coming of Age begehen, um vorzutreten und ihrem Volk zu helfen. Nachdem Ihr Eure Kompetenz bewiesen habt, hat Rorian Euch als jemanden ausgewählt, der bereit für eine direkte Beurteilung durch die Älteste Aetheen ist.",al={"warum ich aetheen of the gales","warum wählt rorian mich","warum zu aetheen schicken"}}},fp="20,159,22.226.0,32.303.0,28.215.0,45.180.0,40.145.0,30.160.0,40.184.0,62.200.0"}
P.entries["quest:92472"] = {n="The Next Step",s="Älteste Aetheen wendet sich nach Süden, nachdem die Bestien nahe Thendal bezwungen sind. Die Eiferer des Al'Aketh-Kults bedrohen Shen'dar.",h="Älteste Aetheen wendet sich nach Süden, nachdem die Bestien nahe Thendal bezwungen sind.",kw={"aetheen of the gales","al'aketh-kult","al'akir","constable aonda","shen'dar","der himmelswall","thendal","insel zephras"},ang={["class:Shaman"]="Als Schamane kennt Ihr die Gefahr, wenn Sterbliche Elementarfürsten wie Al'Akir blind verehren. Sein unberechenbares Wesen verlangt oft Unterwerfung statt Gleichgewicht.",["race:Skyborne"]="Für die Skyborne bedeutet der Kampf gegen die Al'Aketh, sich einem elementaren Fanatismus entgegenzustellen, der überall in ihrer Heimat auf der Insel Zephras Siedlungen bedroht."},sec={{t="Abschied von Thendal",b="Älteste Aetheen of the Gales sieht die Gefahr auf der ganzen Insel Zephras wachsen. Die Raubtiere und Matriarchinnen der nördlichen Wildnis sind bezwungen, doch das war nur das kleinere Übel. Abgelegene Siedlungen brauchen noch immer Verteidiger."},{t="Der drohende Schatten des Kults",b="Der Al'Aketh-Kult ist die größte Gefahr im Süden von Zephras. Seine skrupellosen Eiferer verehren Windlord Al'Akir, den Herrscher des Himmelswalls im Elementarreich. Ihre wachsende Macht bedroht Shen'dar. Aetheen schickt Reisende die Straße nach Süden entlang, vorbei an Wegelagerern im Hochland, um der örtlichen Wache von Constable Aonda beizustehen."}},faq={{q="Wohin führt diese Reise?",a="Die Straße führt von Thendal nach Süden durch das Shen'darhochland nach Shen'dar. Constable Aonda leitet die Verteidigung des Dorfes.",al={"wohin geht es","nächster anlaufpunkt","reiseziel"}},{q="Wer ist Constable Aonda?",a="Constable Aonda hat in Shen'dar die zivile und militärische Befehlsgewalt inne. Der Constable wahrt die Ordnung und schützt das Dorf vor der wachsenden Bedrohung durch Kultisten.",al={"constable aonda","wer ist aonda"}},{q="Was ist der Al'Aketh-Kult?",a="Die Al'Aketh sind skrupellose Eiferer auf der Insel Zephras, die Windlord Al'Akir, den Herrscher des Himmelswalls, verehren. Ihre wachsende Macht bedroht die Siedlungen der Insel.",al={"wer sind die al'aketh","geschichte des al'aketh-kults","kultisten"}},{q="Wer ist Al'Akir?",a="Windlord Al'Akir herrscht über die Lüfte und gebietet über den Himmelswall. Luftelementare verehren ihn, und der Al'Aketh-Kult betet ihn fanatisch an.",al={"wer ist alakir","windlord","herrscher des himmelswalls"}},{q="Warum schickt Älteste Aetheen Reisende aus Thendal fort?",a="Nachdem die unmittelbaren Bedrohungen rund um Thendal gebannt sind, schickt Aetheen bewährte Verteidiger nach Shen'dar. Der Vormarsch des Al'Aketh-Kults gefährdet die Insel weit mehr als die Schwierigkeiten rund um Thendal.",al={"warum thendal verlassen","aetheens ziel"}},{q="Welche Gefahren lauern auf der Straße nach Shen'dar?",a="Der Pfad nach Süden führt durch das Shen'darhochland. Al'Aketh Ambushers und abtrünnige Kultschläger drangsalieren Reisende, die zwischen den Siedlungen der Insel unterwegs sind.",al={"gefahren auf der straße","reise nach süden","gefahr im hochland"}}},fp="13,134,23.226.0,30.315.0,29.140.0,23.152.0,26.157.0,15.133.0,56.194.0,52.145.0"}
P.entries["quest:92473"] = {n="Aggressive Encroachment",s="Beim Dorf bedrohen nun hungernde Ursera die Siedlung. Valreaa Valewind fordert eine Ausdünnung, nachdem eine Bestie am Ahnenbaum beinahe ein Kind angegriffen hätte.",h="Beim Dorf bedrohen nun hungernde Ursera die Siedlung.",kw={"klauen","ahnenbaum","übergriffe","magere ursera","thendalhain","ursera","valreaa valewind"},ang={["class:Druid"]="Als Druide erkennt Ihr, dass sich das Gleichgewicht des Hains verschiebt. Die plötzliche Aggressivität und Unterernährung der Ursera deuten auf eine verborgene Störung im örtlichen Ökosystem hin.",["class:Hunter"]="Als Jäger wisst Ihr, dass hungernde Raubtiere ihre natürliche Scheu vor Siedlungen verlieren können, wenn eine Hungersnot sie dazu treibt."},sec={{t="Verzweifelte Raubtiere",b="Ursera aus Bauen südwestlich des Dorfes sind zu einer Gefahr für seine Bewohner geworden. Ein hungriges Jungtier gelangte an den Fuß des zentralen Ahnenbaums und hätte beinahe ein spielendes Kind zerfleischt. Die Waldläufer der Siedlung töteten die Bestie, bevor jemand verletzt wurde."},{t="Ausdünnung im Hain",b="Die Waldläufer glauben, dass Hunger die Ursera in bewohnte Gebiete treibt. Sie haben angeordnet, die magersten Bestien zu töten, die im Thendalhain vor ihren Bauen umherstreifen. Die Waldläufer des Hains hoffen, so weitere Übergriffe zu verhindern, während sie nach der Ursache für die Not der Wildtiere suchen."}},faq={{q="Wer bietet Aggressive Encroachment an?",a="Valreaa Valewind, eine Anführerin der Waldläufer, bietet die Aufgabe an. Sie wacht über den Hain und schützt die nahegelegene Siedlung vor Raubtieren.",al={"wer vergibt aggressive encroachment","questgeber","valreaa valewind quest"}},{q="Warum streifen die Ursera so nahe am Dorf umher?",a="Die Ursera hungern und sind verzweifelt. Der Hunger treibt sie weit über ihre üblichen Jagdgründe hinaus und in die Siedlung.",al={"warum ursera angreifen","aggressivität der ursera","warum sind ursera wütend"}},{q="Wo sind die mageren Ursera zu finden?",a="Magere Ursera streifen im Thendalhain südwestlich des Dorfes umher, vor den Eingängen der Baue statt tief in der Höhle.",al={"wo sind magere ursera","ursera fundort","thendalhain bären"}},{q="Welche Beinahetragödie gab den Anlass für diese Ausdünnung?",a="Ein heranwachsender Ursera gelangte zum Ahnenbaum in der Dorfmitte und versuchte, einen spielenden kleinen Jungen anzugreifen. Waldläufer töteten die Bestie gerade noch rechtzeitig, um ihn zu retten.",al={"ursera greifen jungen an","was geschah im dorf","junge beim ahnenbaum"}},{q="Warum verhalten sich die Ursera so unberechenbar?",a="Die Ursera sind ungewöhnlich aggressiv geworden, doch die Waldläufer wissen nicht, was ihre Nahrungsknappheit oder die Verhaltensänderung verursacht hat.",al={"was hat sich bei ursera verändert","warum ursera hungern"}},{q="Welchen Beweis verlangt Valreaa Valewind?",a="Valreaa Valewind verlangt sechs Scrawny Ursera Claws von den unterernährten Bestien, die im Hain umherstreifen, als Beweis dafür, dass die gefährlichen Raubtiere erledigt wurden.",al={"was sammeln","aggressive encroachment questziel"}}},fp="23,153,19.242.0,17.281.0,35.147.0,53.121.0,38.116.0,37.164.0,43.126.0,41.156.0"}
P.entries["quest:92474"] = {n="Falling With Style",s="In Thendal schickt Myriaal Mistwake junge Skyborne von einem Wachturm, um ihre Fallkünste zu erproben. Sie gleiten hinab zu Rorian the Dayseeker.",h="In Thendal schickt Myriaal Mistwake junge Skyborne von einem Wachturm, um ihre Fallkünste zu erproben.",kw={"falling with style","myriaal mistwake","rorian the dayseeker","langsamer fall","thendal","gehen auf luft","wachturm","insel zephras"},ang={["race:Skyborne"]="Als Skyborne lernt Ihr, Euren Fall zu verlangsamen, und hört die Debatte darüber, wie vorsichtig Eure natürliche Magie des Gehens auf Luft einzusetzen ist."},sec={{t="Ein Sprung vom Turm",b="Hoch über Thendal auf der Insel Zephras lädt Myriaal Mistwake junge Skyborne ein, ihr Erbe mit einem gewagten Sprung zu erproben. Sie ermuntert Neuankömmlinge, vom Sims des Wachturms zu treten und ihrer Gabe zu vertrauen, einen Fall zu verlangsamen. Die Übung ist spielerisch, bereitet sie aber darauf vor, auf Luft zu gehen, wenn jenseits des Hains Gefahr droht."},{t="Unterschiedliche Gemüter",b="Myriaal liebt plötzliche Abstiege, die Zuschauer erschrecken, während Rorian the Dayseeker zur Vorsicht mahnt. Wenn Neulinge hinabgleiten und vor ihm landen, warnt er, dass ein sorgloser Umgang mit ihrer Magie Reisende in Gefahr hilflos zurücklassen könnte. Dennoch räumt er ein, dass kontrollierte Übung innerhalb des Dorfes ihren Platz hat."}},faq={{q="Welchen Zweck hat diese Quest?",a="Mit dem Sprung üben unerfahrene Skyborne, mithilfe ihrer natürlichen Magie einen langsamen Fall aus der Höhe zu kontrollieren.",al={"was bewirkt diese quest","falling with style zweck","warum diese quest machen"}},{q="Wer vergibt die Quest und wo?",a="Myriaal Mistwake vergibt sie auf dem hölzernen Wachturm über Thendal auf der Insel Zephras.",al={"questgeber","wo beginnt falling with style","wer vergibt falling with style"}},{q="Vor wem landet Ihr?",a="Ihr landet in der Nähe von Rorian the Dayseeker, den Myriaal mit dem Sprung zu erschrecken hofft.",al={"bei wem landen","wer ist rorian","falling with style abgeben"}},{q="Warum ärgert sich Rorian über den Sprung?",a="Rorian meint, Skyborne sollten ihre natürliche Magie diszipliniert einsetzen, statt sie für Streiche zu verschwenden, die Leute erschrecken.",al={"warum ist rorian wütend","rorians reaktion","warum schimpft rorian"}},{q="Welche Fähigkeit wird geübt?",a="Ihr übt Gehen auf Luft, die Gabe der Skyborne, die einen Fall verlangsamt und Verletzungen beim Landen verhindert.",al={"welche fähigkeit wird benutzt","gehen auf luft quest","volksfähigkeit der skyborne"}},{q="Wo findet das statt?",a="Die Übung findet in Thendal auf der Insel Zephras statt, dem angestammten Startgebiet der Skyborne.",al={"questort","wo liegt thendal","welches gebiet ist das"}}},fx={fb92945d={q="Warum lässt Myriaal Mistwake Euch vom Wachturm springen?",a="Myriaal Mistwake betrachtet den Sprung als eine spielerische Herausforderung, um Euch dabei zu helfen, Eure angeborene Fähigkeit zu trainieren, auf der Luft zu wandeln, aber sie hat auch ein schelmisches Motiv: Sie möchte Rorian the Dayseeker erschrecken und sich köstlich amüsieren, wenn er sich aufregt.",al={"warum will myriaal das","myriaal mistwake motiv","warum vom turm springen"}}},fp="18,151,21.318.0,27.303.0,34.105.0,30.91.0,28.80.0,32.125.0,32.95.0,27.103.0"}
P.entries["quest:92479"] = {n="A Scribbled Letter",s="In der Abtei von Nordhain erhalten Abenteurer nach Kämpfen mit nahegelegenen Kobolden eine Vorladung von Tordrin Stemblade. Sie ruft vielversprechende Rekruten zu seiner Ausbildung, während Sturmwind wachsenden Gefahren gegenübersteht.",h="In der Abtei von Nordhain erhalten Abenteurer nach Kämpfen mit nahegelegenen Kobolden eine Vorladung von...",kw={"a scribbled letter","jägerlehrer","koboldlager","abtei von nordhain","nordhaintal","gekritzelter brief","tordrin stemblade"},ang={["class:Hunter"]="Tordrin Stemblade bildet Jäger in der Abtei von Nordhain aus. Er bemerkt, wie sich die Zeiten geändert haben, da neue Völker zum Bogen greifen, um Sturmwind gegen Bestien und Ungeziefer zu verteidigen.",["faction:Alliance"]="Die Ausbildung fähiger Verteidiger in der Abtei von Nordhain hilft, den Wald von Elwynn gegen vordringende Kobolde und andere wachsende Bedrohungen für Sturmwind zu sichern."},sec={{t="Eine Vorladung nach Nordhain",b="Nach Kämpfen mit Koboldlagern im Tal erhalten Abenteurer in der Abtei von Nordhain einen hastig verfassten Brief mit dem Siegel von Tordrin Stemblade. Er bittet sie, ihm unverzüglich Beachtung zu schenken, bevor sie sich anderen Angelegenheiten widmen. Die Vorladung führt angehende Recken auf das geschützte Gelände der Abtei, wo sie unter fachkundiger Anleitung ausgebildet werden."},{t="Anleitung in gefährlichen Zeiten",b="Tordrin Stemblade sagt, die Zeiten hätten sich geändert. Unvertraute Völker greifen nun zu den Waffen, um das Reich zu verteidigen. Während die Wildnis um Nordhain von Tag zu Tag gefährlicher wird, bietet er Reisenden bei Tag und Nacht seinen Rat an. Er begleitet sie dabei, ihre Fertigkeiten zu meistern und den bedrängten Menschen von Sturmwind zu helfen."}},faq={{q="Was ist der Gekritzelte Brief?",a="Nach Kämpfen mit Koboldlagern erhalten Abenteurer in der Abtei von Nordhain einen Brief mit dem Siegel von Tordrin Stemblade. Er weist sie an, seine Anleitung und Ausbildung im Tal zu suchen.",al={"was ist der gekritzelte brief","gekritzelter brief quest","brief von tordrin"}},{q="Wer hat den Brief geschickt?",a="Tordrin Stemblade hat den Brief geschickt. Er ist ein örtlicher Lehrer in der Abtei von Nordhain, wo er angehende Abenteurer in ihrem Handwerk unterweist.",al={"wer hat den brief geschickt","wer hat den brief geschrieben","verfasser gekritzelter brief"}},{q="Wo ist Tordrin Stemblade zu finden?",a="Tordrin Stemblade ist in der Abtei von Nordhain im Nordhaintal zu finden. Er bleibt dort bei Tag und Nacht, bereit, Reisenden Unterweisung und Rat anzubieten.",al={"wo ist tordrin stemblade","tordrins standort","tordrin stemblade finden"}},{q="Warum hat Tordrin Stemblade den Brief geschickt?",a="Nachdem sich ein Abenteurer gegen die örtlichen Kobolde bewährt hat, schickt Tordrin Nachricht, damit dieser eine angemessene Ausbildung erhält. Er will ihn auf die wachsenden Gefahren vorbereiten, die Nordhains Bewohner und das übrige Reich von Sturmwind bedrohen.",al={"warum hat tordrin einen brief geschickt","tordrin stemblades absicht","warum die vorladung"}},{q="Welche Bedrohungen betreffen Nordhain derzeit?",a="Das Nordhaintal wird von Vorstößen aus aggressiven Koboldlagern und gefährlichen menschenfressenden Bestien bedroht, die durch die umliegenden Wälder streifen. Als Antwort versammeln örtliche Lehrmeister fähige Kämpfer und bilden sie aus.",al={"welche bedrohungen gibt es in nordhain","gefahren in der abtei von nordhain","kobolde nordhain"}},{q="Was bietet Tordrin Stemblade nach Erhalt des Briefes an?",a="Tordrin bietet fortlaufend Ausbildung und Anleitung an. Er fordert Abenteurer auf, sich mit der Gegend vertraut zu machen und den Einheimischen bei den vielen Problemen des Königreichs zu helfen.",al={"was bietet tordrin an","tordrins ausbildung","was geschieht nach dem treffen mit tordrin"}}},fp="18,193,23.303.0,26.296.0,27.177.0,20.140.0,37.153.0,42.232.0,48.187.0,61.156.0"}
P.entries["quest:92481"] = {n="A Student of the Arcane",s="Auf der Insel Zephras ruft Rorian the Dayseeker angehende Zauberwirker zu A Student of the Arcane. Nachdem die Neulinge sich bewährt haben, begutachten sie einen Leuchtenden Rückrufkristall und melden sich bei Dorii Brightwhisper, der örtlichen Mentorin.",h="Auf der Insel Zephras ruft Rorian the Dayseeker angehende Zauberwirker zu A Student of the Arcane.",kw={"dorii brightwhisper","leuchtender rückrufkristall","magierquest","rorian the dayseeker","student of the arcane","thendalhain","vuldren","insel zephras"},ang={["class:Mage"]="Als Magier beginnt hier Eure Ausbildung bei Dorii Brightwhisper. Euer Weg in der Magie hilft dabei, längst verlorene arkane Geheimnisse aus den Wolken zurückzugewinnen.",["race:Skyborne"]="Als Skyborne wisst Ihr, dass Jahrtausende der Abgeschiedenheit in den Wolken die arkanen Traditionen schwinden ließen. Junge Lehrlinge spielen eine zentrale Rolle bei der Erneuerung des Erbes Eures Volkes."},sec={{t="Eine Botschaft im Kristall",b="Nachdem angehende Magier bei den lästigen Vuldren nahe Thendalhain geholfen haben, erhalten sie ein merkwürdiges Artefakt: einen Leuchtenden Rückrufkristall. Dorii Brightwhisper, die Arkanlehrerin der Insel, hat ihn zurückgelassen. Seine aufgezeichnete Botschaft prüft die Eignung eines Initianden und heißt ihn zu einem tieferen Studium der Magie willkommen."},{t="Das Arkane wiederentdecken",b="Dorii Brightwhisper sagt, dass die Beherrschung des Arkanen in ihrem Volk langsam geschwunden ist. Jahrtausendelang lebte ihr Volk abgeschieden hoch in den Wolken. Deshalb sieht Dorii in jedem neuen Magiekundigen einen Pionier, der verlorenes Wissen zurückgewinnen und das einst mächtige magische Erbe ihres Volkes wiederherstellen kann."}},faq={{q="Was ist der Leuchtende Rückrufkristall?",a="Der Leuchtende Rückrufkristall ist ein kleiner magischer Fokus, den Dorii Brightwhisper Rorian the Dayseeker anvertraut hat. Er enthält eine eingeschriebene Botschaft, die junge Lehrlinge in die Grundlagen arkaner Kommunikation einführt.",al={"rückrufkristall","kristallbotschaft","was bewirkt der kristall"}},{q="Wer ist Dorii Brightwhisper?",a="Dorii Brightwhisper ist die örtliche Magierlehrerin im Gebäude hinter Rorian the Dayseeker in Thendalhain auf der Insel Zephras. Dorii unterweist junge Magier, die die uralten arkanen Traditionen ihres Volkes zurückgewinnen wollen.",al={"wer ist dorii","magierlehrerin zephras","dorii aufenthaltsort"}},{q="Warum ist die arkane Magie unter dem Volk von Zephras geschwunden?",a="Wie Dorii erklärt, schwand die arkane Magie allmählich während der Jahrtausende, die ihr Volk abgeschieden hoch in den Wolken lebte. Dorii und andere Lehrkräfte bilden neue Novizen aus, damit sie nach dem Verlorenen suchen und es zurückgewinnen.",al={"warum schwand die magie","skyborne arkane überlieferungen","verlorene arkane magie"}},{q="Wer vergibt diese Quest?",a="Rorian the Dayseeker bietet diese Quest in Thendalhain auf der Insel Zephras an, nachdem ein angehender Magier Harmony in Balance abgeschlossen hat.",al={"questgeber","wer beginnt a student of the arcane","rorian quest"}},{q="Wo kann ich Dorii Brightwhisper finden?",a="Dorii Brightwhisper lebt im Gebäude direkt hinter Rorian the Dayseeker in Thendalhain.",al={"dorii brightwhisper aufenthaltsort","wo ist die magierlehrerin","dorii finden"}},{q="Welche Voraussetzung muss vor Beginn dieser Quest erfüllt werden?",a="Schließt zuerst Harmony in Balance ab, bei der Ihr Euch für Rorian the Dayseeker um das örtliche Vuldrenproblem kümmert.",al={"voraussetzung","voraussetzungen","welche quest kommt vorher"}}},fx={["1ed09f17"]={q="Warum schickt Euch Rorian the Dayseeker zu Dorii?",a="Rorian übermittelt lediglich eine dringende Nachricht, die für Euch bestimmt ist. Während Ihr die nahegelegene Vuldren-Bedrohung bekämpft habt, hat Dorii Brightwhisper einen Erinnerungskristall hinterlassen, der speziell für Eure Aufmerksamkeit beschriftet ist. Rorian stellt sicher, dass Ihr den Kristall erhaltet, und leitet Euch direkt zur Magierausbilderin des Hains, damit Euer arkanes Potenzial nicht ungenutzt bleibt.",al={"warum schickt rorian euch","rorian the dayseeker motiv","warum mit dorii brightwhisper sprechen"}},ab250928={q="Warum möchte Dorii Brightwhisper gerade Euch ausbilden?",a="Die arkanen Künste haben unter Eurem Volk über Jahrtausende, die abgeschieden in den Wolken verbracht wurden, nachgelassen. Nachdem Ihr Eure Kompetenz gegen lokale Bedrohungen bewiesen habt, sieht Dorii Brightwhisper in Euch die rohe Fähigkeit, die erforderlich ist, um dieses verlorene Erbe zurückzugewinnen. Sie sucht angehende Magier, die die arkane Magie aktiv erforschen und meistern können, anstatt altes Wissen in Vergessenheit geraten zu lassen.",al={"warum ich a student of the arcane","warum mich ausbilden","warum will dorii mich"}}},fp="23,217,20.301.0,24.270.0,35.210.0,27.215.0,55.213.0,21.118.0,37.101.0,63.111.0"}
P.entries["quest:92482"] = {n="The Way of the Hunter",s="Junge Jäger im Thendalhain beginnen ihre Ausbildung, nachdem sie die örtlichen Vuldren zurückgedrängt haben. Nun ruft Rorian the Dayseeker sie zu Tai'ree Farsight, um ihre förmliche Unterweisung zu beginnen.",h="Junge Jäger im Thendalhain beginnen ihre Ausbildung, nachdem sie die örtlichen Vuldren zurückgedrängt haben.",kw={"jägerlehrer","rorian the dayseeker","gekritzelte notiz","tai'ree farsight","the way of the hunter","thendalhain","vuldren","zephras"},ang={["class:Hunter"]="Als Jäger auf der Insel Zephras beginnt Ihr Eure förmliche Ausbildung bei Tai'ree Farsight."},sec={{t="Ein Ruf zur Jagd",b="Nachdem sie die störenden Vuldren am Rand des Thendalhains dezimiert haben, kehren junge Jäger zurück und erfahren, dass ihre praktischen Fertigkeiten Aufmerksamkeit erregt haben. Rorian the Dayseeker überreicht ihnen eine gekritzelte Vorladung von Tai'ree Farsight, der ansässigen Jägerlehrerin des Hains. Für unerfahrene Waldläufer, die sich auf die Erkundung der Insel Zephras vorbereiten, leitet dieses Treffen den Übergang von der Inselverteidigung zur Kampf- und Überlebensausbildung ein."},{t="Die Unterweisung durch Tai'ree",b="Nahe der Dorfmitte empfängt Tai'ree Farsight vielversprechende Schüler mit strengem Realismus. In ungezähmter Natur zu bestehen, erfordert scharfe Sinne und blitzschnelle Reflexe. Ihre Anleitung schöpft aus langjähriger Erfahrung und gibt den Fährtenlesern der Insel eine Grundlage, um ihre Treffsicherheit und Überlebensfertigkeiten zu verfeinern."}},faq={{q="Wer bietet diese Aufgabe an?",a="Nachdem Ihr Rorian the Dayseeker in 'Harmony in Balance' mit der örtlichen Vuldrenplage geholfen habt, bietet er diese Ausbildung im Thendalhain auf der Insel Zephras an.",al={"wer vergibt the way of the hunter","questgeber","rorian quest"}},{q="Wer ist Tai'ree Farsight?",a="Tai'ree Farsight ist die ansässige Jägerlehrerin nahe der Mitte des Thendalhains. Sie wacht über die Ausbildung und Disziplin angehender Scharfschützen und Fährtenleser der Insel.",al={"wo ist tai'ree","jägerlehrer thendalhain","tai'ree farsight standort"}},{q="Wozu dient die Gekritzelte Notiz?",a="Die Gekritzelte Notiz ist eine Nachricht, die Tai'ree Farsight hinterlässt, während Ihr Euch um die Vuldren kümmert. Sie fordert Euch auf, sie auf dem Dorfplatz aufzusuchen, um mit der weiterführenden Ausbildung zu beginnen.",al={"gekritzelte notiz","was steht in der notiz","jägernotiz"}},{q="Wo spielt diese Quest?",a="Dies spielt sich vollständig im Thendalhain ab, einer Vorpostensiedlung auf der Insel Zephras.",al={"questgebiet","jägerquest ort","wo ist der thendalhain"}},{q="Welche Voraussetzung muss vor dieser Quest erfüllt werden?",a="Bevor Ihr Tai'ree trefft, müsst Ihr 'Harmony in Balance' für Rorian the Dayseeker abschließen. Dort beweist Ihr Eure grundlegenden Fähigkeiten, indem Ihr Euch um die aggressiven Vuldren nahe dem Hain kümmert.",al={"voraussetzung für the way of the hunter","wie freischalten","vorherige quest"}},{q="Was lehrt Tai'ree Farsight neue Jäger?",a="Tai'ree Farsight dient Euch als Klassenlehrerin. Im Gespräch mit ihr lernt Ihr die Grundgedanken des Fährtenlesens auf der Insel kennen und erhaltet Zugang zu grundlegenden Jägerfähigkeiten und Kampftechniken.",al={"was macht tai'ree","warum mit tai'ree sprechen"}}},fx={bb563a7d={q="Warum schickt Euch Rorian the Dayseeker zu Tai'ree Farsight?",a="Während Ihr unterwegs wart, um die Vuldren-Bedrohung zu bewältigen, hat die Jägerausbilderin des Dorfes, Tai'ree Farsight, speziell eine Notiz hinterlassen, in der sie darum bittet, mit Euch zu sprechen. Rorian übermittelt lediglich die Nachricht und weist Euch den Weg dorthin, wo sie im Thendalhain wartet, damit Ihr mit der Verfeinerung Eurer kriegerischen Fähigkeiten beginnen könnt.",al={"warum schickt rorian euch","rorian motiv way of the hunter","warum tai'ree farsight besuchen"}}},fp="21,173,21.403.0,23.307.0,21.153.0,24.164.0,42.181.0,33.86.0,54.184.0,45.185.0"}
P.entries["quest:92483"] = {n="At Home in the Shadows",s="Rorian schickt Euch zu Akeri Duskblade im Thendalhain, wo die Schurkenausbildung beginnt. Die Vorladung markiert den Übergang von Dorfaufgaben zu Heimlichkeit und Kampf.",h="Rorian schickt Euch zu Akeri Duskblade im Thendalhain, wo die Schurkenausbildung beginnt.",kw={"akeri duskblade","at home in the shadows","schurkenquest","schurkenlehrer","rorian the dayseeker","einfache notiz","thendalhain","insel zephras"},ang={["class:Rogue"]="Als Schurke beginnt Ihr Eure formelle Ausbildung auf der Insel Zephras, wenn Ihr Akeri Duskblade im Wachturm des Thendalhains trefft."},sec={{t="Eine zwielichtige Einladung",b="Akeri Duskblade hat bemerkt, wie junge Schurken Bedrohungen rund um den Thendalhain begegnen. Der Schurkenlehrer des Hains meidet ein offenes Treffen in der Siedlung, also schickt er eine Notiz über Rorian the Dayseeker. Obwohl Akeri seine Gründe für sich behält, erkennt Rorian, dass er die Fertigkeiten kennt, die ein Schurke jenseits der geschützten Grenzen des Hains braucht."},{t="Lehren im Wachturm",b="Akeri Duskblade wartet im Wachturm des Dorfes im Thendalhain. Er beurteilt die Trittsicherheit und Aufmerksamkeit jedes Neuankömmlings und warnt dann, dass unbedachte Schritte jenseits des Hains in ein frühes Grab führen können. Wer seiner Prüfung standhält, beginnt die formelle Ausbildung in Heimlichkeit, Präzision und Überleben auf der Insel Zephras."}},faq={{q="Wer vergibt die Quest At Home in the Shadows?",a="Rorian the Dayseeker übergibt Euch Akeris Vorladung im Thendalhain auf der Insel Zephras, nachdem Ihr Harmony in Balance abgeschlossen habt.",al={"wer startet at home in the shadows","questgeber at home in the shadows","rorian quest"}},{q="Wo kann ich Akeri Duskblade finden?",a="Akeri Duskblade wartet im Wachturm des Dorfes im Thendalhain auf der Insel Zephras.",al={"akeri duskblade standort","wo ist akeri duskblade","akeri finden"}},{q="Was ist die einfache Notiz, die während der Quest übergeben wird?",a="Akeri Duskblades einfache Notiz bittet vielversprechende Schurken, ihn aufzusuchen. Lest sie, bevor Ihr mit Akeri sprecht.",al={"einfache notiz zephras","was ist die notiz","einfache notiz lesen"}},{q="Ist diese Quest für alle Klassen verfügbar?",a="Nein. Die Ausbildung ist für Schurken gedacht, die ihr Handwerk im Thendalhain erlernen.",al={"können andere klassen diese quest machen","ist at home in the shadows nur für schurken","klassenvoraussetzung"}},{q="Was lehrt Akeri Duskblade?",a="Akeri Duskblade lehrt die örtlichen Schurken im Thendalhain Heimlichkeit, List und Klingenkunst, wenn sie ihre Reise über die Insel Zephras beginnen.",al={"akeri duskblade rolle","wer ist akeri","schurkenlehrer thendalhain"}},{q="Welche Quest muss zuvor abgeschlossen werden?",a="Schließt zuerst Harmony in Balance für Rorian the Dayseeker ab. Dann übergibt er Euch Akeris Notiz.",al={"at home in the shadows voraussetzung","vorherige quest","at home in the shadows freischalten"}}},fx={["776f9cb3"]={q="Warum schickt Euch Rorian the Dayseeker zu Akeri Duskblade?",a="Nachdem Ihr Eure Kompetenz durch die Bewältigung der lokalen Vuldren-Bedrohung bewiesen habt, übermittelt Rorian lediglich eine Vorladung. Akeri Duskblade, die ansässige Schurkenausbilderin des Hains, hat speziell darum gebeten, Euch zu sehen, und eine Notiz für Eure Aufmerksamkeit hinterlassen. Rorian erkennt, dass ein angehender Schurke eine angemessene Ausbildung von jemandem benötigt, der für dieses Handwerk geeignet ist, und merkt spielerisch an, dass Ihr und die zwielichtige Duskblade wahrscheinlich gut miteinander auskommen werdet.",al={"rorian motive","warum zu akeri schicken","warum mit akeri duskblade sprechen"}},["4629917d"]={q="Warum braucht Rorian Euch, anstatt sich selbst mit Akeri zu befassen?",a="Akeri Duskblade hat persönlich nach Euch gefragt, nicht nach Rorian oder den Wächtern des Hains. Ihr habt den Pfad eines Schurken gewählt, und Akeri ist die lokale Mentorin, die für die Ausbildung derjenigen verantwortlich ist, die aus dem Schatten heraus agieren. Die Vorladung soll Eure Wachsamkeit prüfen, Eure Instinkte schärfen und Euch darauf vorbereiten, außerhalb der Sicherheit des Thendalhains zu überleben.",al={"warum ich akeri duskblade","warum will akeri mich sehen","warum will schurkenausbilderin mich"}}},fp="22,157,18.326.0,25.286.0,43.118.0,33.85.0,47.101.0,39.69.0,32.135.0,48.91.0"}
P.entries["quest:92484"] = {n="Embracing the Elements",s="Im Thendalhain ruft Rorian the Dayseeker junge Schamanen dazu auf, ihre Elementarausbildung zu beginnen. Windshaper Boros Nachricht berichtet von einem Schweigen zwischen dem Volk und den Geistern der Winde.",h="Im Thendalhain ruft Rorian the Dayseeker junge Schamanen dazu auf, ihre Elementarausbildung zu beginnen.",kw={"embracing the elements","summender rückrufkristall","rorian the dayseeker","schamane","geister der vier winde","thendalhain","windshaper boro","insel zephras"},ang={["class:Shaman"]="Als Schamane begegnet Ihr Windshaper Boro zur förmlichen Unterweisung und erfahrt, dass die elementaren Winde verstummt sind. Schamanen widmen sich der Wiederherstellung der Gemeinschaft mit ihnen.",["faction:Horde"]="Als Reisender der Horde auf der Insel Zephras begegnet Ihr den Elementarrufern der Insel und erfahrt von ihrem Ringen um die Geister. Das Schweigen der Geister prägt ihre Ausbildung."},sec={{t="Ein Ruf zu den Elementen",b="Rorian the Dayseeker kommt zu Euch, nachdem Ihr mit den Vuldren rund um das Dorf geholfen habt. Windshaper Boro hat während Eurer Abwesenheit einen summenden Rückrufkristall hinterlassen. Seine Nachricht ruft Euch ins Zentrum des Hains, wo die förmliche Elementarausbildung beginnt."},{t="Die schweigenden Winde",b="Windshaper Boro erzählt Euch, dass die Geister der vier Winde vor Jahren jegliche Verständigung eingestellt haben. Sie haben die einstige Gemeinschaft mit dem Volk aufgegeben. Nun erforschen die Schamanen von Zephras die Natur und üben hart, in der Hoffnung, das Schweigen zu überwinden und wieder mit den Geistern zu sprechen."}},faq={{q="Wer vergibt die Quest Embracing the Elements?",a="Nachdem Ihr mit dem örtlichen Vuldrenproblem geholfen habt, schickt Rorian the Dayseeker Euch vom Thendalhain auf der Insel Zephras aus los.",al={"embracing the elements questgeber","wer startet embracing the elements"}},{q="Wo befindet sich Windshaper Boro?",a="Nahe dem Zentrum des Thendalhains auf der Insel Zephras bildet Windshaper Boro die Schamanen der Siedlung aus.",al={"windshaper boro standort","wo ist boro","windshaper boro finden"}},{q="Warum haben die Elementargeister aufgehört, mit den Menschen hier zu sprechen?",a="Windshaper Boro sagt, die Geister der vier Winde hätten vor Jahren aufgehört zu sprechen und das Volk verlassen. Die örtlichen Schamanen wissen nicht, warum, doch sie forschen in der Hoffnung, diese Verbindung wiederherzustellen.",al={"warum schweigen die winde","geister der vier winde schweigen","was geschah mit den windgeistern"}},{q="Was ist der Summende Rückrufkristall?",a="Windshaper Boro hat den summenden Rückrufkristall hinterlassen, während Ihr unterwegs wart, um der Siedlung zu helfen. Ihn zu untersuchen signalisiert, dass Ihr bereit seid, unter seiner Anleitung mit der Elementarausbildung zu beginnen.",al={"summender rückrufkristall","rückrufkristall zephras"}},{q="Welche vorausgesetzte Quest führt zu Embracing the Elements?",a="Harmony in Balance kommt zuerst. Ihr kümmert Euch um die Vuldren, die in der Umgebung Unruhe stiften.",al={"embracing the elements vorquest","was kommt vor embracing the elements"}},{q="Welche Rolle spielt Windshaper Boro im Thendalhain?",a="Windshaper Boro bildet die Schamanen des Thendalhains aus. Er lehrt neue Schüler die Gemeinschaft mit den Elementen und vermittelt ihnen Wissen über die Natur.",al={"was macht boro","windshaper boro rolle"}}},fx={["52185878"]={q="Warum schickt Euch Rorian the Dayseeker zu Windshaper Boro?",a="Während Ihr unterwegs wart, um die Vuldren-Probleme des Hains zu lösen, hat Windshaper Boro speziell einen Rückrufkristall für Euch in Rorians Obhut hinterlassen. Rorian reicht den Kristall einfach nur weiter und weist Euch den Weg zu Boro in der Nähe des Dorfzentrums, damit Ihr lernen könnt, den Pfad der Elemente zu beschreiten.",al={"warum will rorian das erledigt haben","rorian boro quest warum","warum summenden rückrufkristall untersuchen"}}},fp="22,190,25.245.0,16.285.0,43.113.0,33.100.0,63.180.0,35.179.0,56.90.0,53.126.0"}
P.entries["quest:92485"] = {n="A Student of Nature",s="Auf der Insel Zephras beginnt A Student of Nature mit einem Ruf an Druidenneulinge. Nachdem sie geholfen haben, die örtliche Harmonie wiederherzustellen, ruft Xyton Silverwind sie unter die Äste von Thendalhain, um das natürliche Gleichgewicht der Insel kennenzulernen.",h="Auf der Insel Zephras beginnt A Student of Nature mit einem Ruf an Druidenneulinge.",kw={"druide","gefaltetes pergament","rorian the dayseeker","thendalhain","vuldren","xyton silverwind","insel zephras"},ang={["class:Druid"]="Als Druide beginnt Ihr bei Xyton Silverwind eine lebenslange Ausbildung in den Künsten der Wildnis, des Fangzahns und des Astes."},sec={{t="Ein Ruf aus dem Hain",b="Nachdem örtliche Unruhen durch übereifrige Wildtiere beigelegt sind, überbringt Rorian the Dayseeker jungen Initianden einen persönlichen Ruf. Das gefaltete Pergament wurde von Xyton Silverwind hinterlassen. Es lädt angehende Druiden ein, vorzutreten und die tieferen Geheimnisse der Wildnis zu ergründen, denn ihre natürlichen Talente haben die Aufmerksamkeit der Hainältesten geweckt."},{t="Hüter des Gleichgewichts",b="Die Begegnung mit Xyton Silverwind auf der unteren Ebene des großen Baumes in Thendalhain ist der erste Schritt eines Neulings auf dem Weg seiner Berufung. Für Silverwind bilden die Pflanzen und Tiere der Insel Zephras ein vielschichtiges, lebendiges Ganzes, das ständige Pflege und ein wachsam gehütetes Gleichgewicht braucht. Der Pfad von Fangzahn, Klaue, Feder und Ast verlangt nach dauerhafter Anleitung, und diese Begegnung beginnt ein Leben voller Fürsorge."}},faq={{q="Wer schickt den Spieler zu Xyton Silverwind?",a="Nachdem Ihr geholfen habt, die unbändigen vuldren rund um den Hain zu bändigen, überreicht Rorian the Dayseeker Euch ein gefaltetes Pergament, das Euch zu Xyton Silverwind schickt.",al={"wer vergibt a student of nature","questgeber","rorian"}},{q="Wo befindet sich Xyton Silverwind?",a="Xyton Silverwind befindet sich im Erdgeschoss des großen Baumes in Thendalhain, direkt hinter Rorian the Dayseeker auf der Insel Zephras.",al={"xyton silverwind standort","wo ist xyton","druidenlehrer standort"}},{q="Was ist der Zweck dieser Quest?",a="A Student of Nature macht Druidenneulinge mit Xyton Silverwind bekannt, ihrem wichtigsten Lehrer und Wegweiser bei der Bewahrung des natürlichen Gleichgewichts der Insel Zephras.",al={"warum diese quest machen","questziel","beginn der druidenausbildung"}},{q="Was lehrt Xyton Silverwind Druidenneulinge über die Insel Zephras?",a="Silverwind lehrt, dass die Pflanzen und Tiere der Insel miteinander verbunden sind und durch die Disziplinen von Fangzahn, Klaue, Feder und Ast aktive Pflege und Ausgleich brauchen.",al={"was sagt xyton","zephras naturgleichgewicht","druidenrolle zephras"}},{q="Welche Voraussetzung muss erfüllt sein, bevor dieser Ruf eintrifft?",a="Initianden schließen zuerst Harmony in Balance für Rorian the Dayseeker ab und kümmern sich um die unbändigen vuldren, bevor sie Silverwinds Nachricht erhalten.",al={"vorausgesetzte quest","vorherige quest","vor a student of nature"}},{q="Was steht im Gefalteten Pergament?",a="Das gefaltete Pergament ist eine Nachricht, die Xyton Silverwind hinterlassen hat. Sie weist den vielversprechenden jungen Druiden an, ihn zur weiteren Ausbildung unter dem Blätterdach des großen Baumes aufzusuchen.",al={"gefaltetes pergament nachricht","silverwinds nachricht","was steht auf dem pergament"}}},fx={caa97f7a={q="Warum schickt Euch Rorian the Dayseeker zu Xyton Silverwind?",a="Während Ihr unterwegs wart, um die örtliche Vuldren-Bedrohung abzuwenden, hat der ansässige Druidenausbilder Xyton Silverwind eine Nachricht für Euch hinterlassen. Rorian agiert als Vermittler, um sicherzustellen, dass vielversprechende Eingeweihte die richtige Unterweisung erhalten. Er drängt Euch dazu, Silverwinds Rat zu befolgen, damit Ihr die druidischen Künste meistern und das natürliche Gleichgewicht bewahren könnt.",al={"rorians beweggrund","warum schickt er mich zu silverwind","warum gibt rorian euch ein gefaltetes pergament"}}},fp="19,216,24.341.0,22.376.0,41.144.0,34.125.0,34.140.0,66.167.0,66.146.0,46.164.0"}
P.entries["quest:92489"] = {n="Power Overwhelming",s="High Sorcerer Andromath schickt Hilfe aus Sturmwind nach Dalaran, wo arkane Macht gefährlich geworden ist. Die Kirin Tor bauen hinter geschlossenen Grenzen ihre Stadt wieder auf, und ein Manaelementar bedroht ihre Arbeit.",h="High Sorcerer Andromath schickt Hilfe aus Sturmwind nach Dalaran, wo arkane Macht gefährlich geworden ist.",kw={"arkane energie","archimonde","dalaran","high sorcerer andromath","kirin tor","manaelementar","power overwhelming","sturmwind"},ang={["class:Mage"]="Als Magier wisst Ihr, dass die Kirin Tor Eurer Berufung nahestehen und dass instabile arkane Erscheinungen Dalaran gefährden.",["faction:Alliance"]="Als Verbündeter der Kirin Tor wisst Ihr, dass Sturmwind seine Bande zu ihnen stärken möchte, indem es Dalaran beim Wiederaufbau hilft."},sec={{t="Eine Stadt in Abgeschiedenheit",b="Nachdem Archimonde Dalaran im Dritten Krieg zerstört hatte, zogen sich die Kirin Tor zurück. Einst kamen Gelehrte und Zauberer aus aller Welt an die Tore der Stadt. Nun halten die überlebenden Magier Außenstehende fern, während sie ihre zerstörte Stadt hinter geschlossenen Grenzen wieder aufbauen."},{t="Ungebändigte arkane Kräfte",b="Während die Kirin Tor Dalaran wiederherstellen, ist arkane Energie gefährlich geworden. Unstete Energieströme treten aus, geraten außer Kontrolle und nehmen die Gestalt von Wesen aus reinem Mana an. High Sorcerer Andromath fürchtet, innere Unruhen könnten die Erholung der Stadt zunichtemachen, oder Dalaran könnte seine alten Bande zur Allianz aufgeben. Deshalb entsendet er Streiter aus Sturmwind, um das Manaelementar zu bezwingen und die Kirin Tor daran zu erinnern, dass ihre Verbündeten ihnen weiterhin beistehen."}},faq={{q="Was ist die Quest Power Overwhelming?",a="High Sorcerer Andromath schickt Hilfe aus Sturmwind, während die Kirin Tor Dalaran wieder aufbauen. Ein Manaelementar, entstanden aus ungebändigter arkaner Energie, bedroht ihre Arbeit.",al={"was ist power overwhelming","power overwhelming quest","dalaran manaelementar quest"}},{q="Wer vergibt diese Quest?",a="High Sorcerer Andromath bittet Streiter in Sturmwind, nach Dalaran zu reisen und den Kirin Tor beizustehen.",al={"wer vergibt power overwhelming","andromath quest","wo beginnt power overwhelming"}},{q="Warum ist Dalaran zurückgezogen und misstrauisch?",a="Archimonde verwüstete Dalaran während des Dritten Krieges. Während die Kirin Tor ihre Heimat wieder aufbauen, bleiben die überlebenden Magier gegenüber Außenstehenden misstrauisch.",al={"warum ist dalaran abgeschottet","was ist mit dalaran geschehen","warum sind dalarans magier misstrauisch"}},{q="Was verursacht die Unruhen in Dalaran?",a="Unstete arkane Energie ist während Dalarans Wiederaufbau außer Kontrolle geraten und hat feindselige Manaelementare gebildet.",al={"dalaran arkaner ausbruch","warum gibt es manaelementare in dalaran","was geht in dalaran vor"}},{q="Was ist das Manaelementar?",a="Ein Manaelementar ist ein Wesen aus reinem Mana. Sein Auftauchen zeigt, dass die arkane Störung, die Dalaran bedroht, stärker ist, als erste Berichte vermuten ließen.",al={"was ist das manaelementar","dalaran elementar hintergrundgeschichte","wesen aus reinem mana"}},{q="Warum schickt Sturmwind Hilfe nach Dalaran?",a="Die Kirin Tor sind seit Langem Verbündete der Allianz. High Sorcerer Andromath schickt Hilfe, weil er fürchtet, Dalaran könnte in seiner verwundbaren Lage im Chaos versinken oder die Allianz verlassen.",al={"warum hilft sturmwind dalaran","warum kümmert sich die allianz um dalaran"}}},fp="18,189,19.248.0,21.415.0,37.155.0,21.101.0,41.133.0,43.118.0,27.156.0,41.171.0"}
P.entries["quest:92514"] = {n="Welcome to Shen'dar Village",s="In Shen'dar werden Neuankömmlinge zur Ältesten und zur Gastwirtin geschickt. Örtliche Spannungen prägen das Grenzland ebenso wie eine wachsende Bedrohung durch Banditen.",h="In Shen'dar werden Neuankömmlinge zur Ältesten und zur Gastwirtin geschickt.",kw={"banditen","coriella calmbreeze","der hohe orden","illaya amberwind","shen'dar","geisterberührt","welcome to shen'dar village","windformer"},ang={["class:Shaman"]="Als Schamane könnt Ihr die schwache statische Ladung in der Luft um geisterberührte Windformer wie Illaya Amberwind in Shen'dar spüren."},sec={{t="Erste Schritte in Shen'dar",b="Neuankömmlinge in Shen'dar lernen zuerst die Menschen kennen, die dort den Alltag lenken. Wer von den Geistern berührt wurde, wird zu Älteste Illaya Amberwind nahe dem Dorfplatz geschickt. Coriella Calmbreeze begrüßt Besucher im Gasthaus des Dorfes, wo Unterkunft und Vorräte erhältlich sind. Diese Begegnungen helfen Reisenden, die Bräuche des Dorfes kennenzulernen, bevor sie zu den Waffen greifen."},{t="Fraktionen und Grenzlandnöte",b="Streitigkeiten in Shen'dar bleiben gesittet, obwohl die Windformer und der Hohe Orden uneins sind. Ihre weltanschaulichen Spannungen durchziehen die Region, doch beide Gruppen wissen, dass das Überleben Vorrang hat. Banditen dringen in das Gebiet vor. Diese Gefahr gibt dem Dorf Anlass, kleinere Streitigkeiten beiseitezulegen."}},faq={{q="Welchen Zweck hat die Quest „Welcome to Shen'dar Village“ in Shen'dar?",a="„Welcome to Shen'dar Village“ führt Neuankömmlinge zu den Menschen, die Shen'dar leiten und der Siedlung dienen. Reisende werden zur ansässigen Windformerältesten und zur Gastwirtin des Dorfes geschickt, bevor sie bei örtlichen Problemen wie Banditen helfen.",al={"was ist die quest in shen'dar","questübersicht welcome to shen'dar village","was gibt es in shen'dar zu tun"}},{q="Wer ist Illaya Amberwind?",a="Illaya Amberwind ist die Windformerälteste von Shen'dar. Sie befindet sich nahe dem Dorfzentrum und leitet jene an, die von den Geistern berührt wurden, während vor Ort politische Spannungen herrschen.",al={"wer ist illaya amberwind","illaya amberwind aufenthaltsort","windformerälteste shen'dar"}},{q="Wer ist Coriella Calmbreeze?",a="Coriella Calmbreeze führt das Gasthaus von Shen'dar und bietet Reisenden und Einheimischen Unterkunft, Ruhe und Vorräte.",al={"wer ist coriella calmbreeze","shen'dar gastwirtin","wo ist das gasthaus in shen'dar"}},{q="Wer sind die Windformer?",a="Die Windformer sind von den Geistern berührte Praktizierende, die eine statische Ladung in der Luft um sie herum kennzeichnet. Sie und der Hohe Orden pflegen in Shen'dar trotz ihrer Spannungen und der überregionalen Bedrohungen einen gesitteten Umgang.",al={"was sind windformer","geisterberührte windformer hintergrundgeschichte","hoher orden gegen windformer"}},{q="Welche Spannungen bestehen zwischen dem Hohen Orden und den Windformern?",a="Der Hohe Orden und die Windformer stehen in einem politischen und weltanschaulichen Konflikt. In Shen'dar wahren beide Seiten den Frieden und kümmern sich um gemeinsame, dringendere Anliegen.",al={"was ist der hohe orden","konflikt in shen'dar","spannungen zwischen hohem orden und windformern"}},{q="Mit welchen Problemen hat Shen'dar derzeit zu kämpfen?",a="Shen'dar hat mit örtlichen Banditen im Umland sowie dem philosophischen Streit zwischen den Windformern und dem Hohen Orden zu kämpfen.",al={"probleme in shen'dar","welche bedrohung besteht für shen'dar","banditen in shen'dar"}}},fp="27,136,23.361.0,29.291.0,61.234.0,24.155.0,27.112.0,24.221.0,63.168.0,51.146.0"}
P.entries["quest:92515"] = {n="The Problem With Prideclaws",s="Das Dorf im Shen'darhochland wird von Prideclaws, Banditen und Kultisten bedroht. Die Bestien drängen auf die Siedlung zu, und ihre Dezimierung schützt die Menschen und liefert zugleich nützliche Pelze.",h="Das Dorf im Shen'darhochland wird von Prideclaws, Banditen und Kultisten bedroht.",kw={"dezimierung","prideclaw pelze","prideclaws","shen'dar","shen'darhochland","the problem with prideclaws","dorfgrenzen"},ang={["class:Hunter"]="Als Jäger ist Euch das Aufspüren und Dezimieren von Raubtieren nahe Siedlungen vertraut. Prideclaws in solcher Zahl verlangen dennoch Respekt."},sec={{t="Wachsende Gefahr aus der Wildnis",b="Prideclaws drängen auf das Dorf im Shen'darhochland zu. Banditen durchstreifen die Hügel, und wahnsinnige Kultisten machen der Region zu schaffen. Den Dorfbewohnern droht von mehreren Seiten Gefahr. Während die Bestien dreister werden und ihr Revier ausweiten, gerät die Siedlung immer mehr in ihre Reichweite."},{t="Die Grenzen sichern",b="Die Dorfbewohner haben eine Dezimierung organisiert, bevor die umherstreifenden Raubtiere Haustiere oder Kinder verschleppen können. Die Prideclaws von den Grenzen zurückzudrängen hilft, die Siedlung zu schützen. Ihre robusten Pelze liefern den Dorfhandwerkern außerdem Material für nützliche Waren."}},faq={{q="Was sind Prideclaws?",a="Prideclaws sind wilde Raubtiere der Hügel und des Hochlands von Shen'dar. Ihre Pelze sind wertvoll, und ihre wachsende Zahl bringt sie näher an Siedlungen heran.",al={"was sind prideclaws","prideclaw hintergrund","prideclaws"}},{q="Wo sind die Prideclaws zu finden?",a="Prideclaws durchstreifen die Hügel des Shen'darhochlands. Ihre wachsende Zahl führt sie näher an das örtliche Dorf und seine Bewohner heran.",al={"wo ist diese quest","wo leben prideclaws","prideclaw fundort"}},{q="Warum müssen die Prideclaws zum Schutz des Dorfes dezimiert werden?",a="Banditen und wahnsinnige Kultisten bedrohen die Region bereits. Mit wachsender Zahl nähern sich die Prideclaws dem Dorf und gefährden Kinder und Haustiere.",al={"warum prideclaws töten","warum prideclaws dezimieren","gefahr für das dorf"}},{q="Was geschieht mit den Pelzen der Prideclaws?",a="Die Dorfhandwerker verarbeiten die Pelze der Prideclaws zu praktischen Waren und Versorgungsgütern.",al={"was geschieht mit den pelzen","prideclaw pelzverwendung","zweck der pelze"}},{q="Welche anderen Bedrohungen suchen die umliegenden Hügel heim?",a="Umherziehende Banditen und unberechenbare Kultisten machen neben den wilden Prideclaws die Hügel rund um die Siedlung unsicher.",al={"andere bedrohungen shendar","was bedroht das dorf sonst noch","örtliche bedrohungen"}},{q="Wie sehen die Einheimischen die Prideclaws?",a="Der Dorfbewohner, der die Dezimierung beaufsichtigt, findet Prideclaws recht niedlich, selbst hinter bewaffneten Wachen. Dennoch gilt es, das Dorf zu schützen, bevor ein Unglück geschieht.",al={"wer vergibt the problem with prideclaws","gedanken des questgebers"}}},fp="27,188,21.276.0,20.237.0,20.157.0,33.131.0,48.159.0,43.74.0,48.109.0,38.162.0"}
P.entries["quest:92516"] = {n="Hippogryph Harassment",s="Nahe Shen'dar bringt Hippogryph Harassment Reisende in Gefahr. Ein wilder Schwarm nistet südöstlich des Dorfes im Shen'darhochland und greift Reisende auf der nahen Straße an. Ihr sollt seine Jungen, Beschützer und Matriarchin töten, damit Reisende sicher passieren können.",h="Nahe Shen'dar bringt Hippogryph Harassment Reisende in Gefahr.",kw={"hippogryph","hippogryph harassment","hippogryphenmatriarchin","hippogryphenbeschützer","hippogryphenjunges","kalimdor","matriarchin","shen'darhochland","shen'dar"},ang={["class:Druid"]="Als Druide sucht Ihr Einklang mit der Wildnis. Ihr könnt diese Dezimierung als bedauerliche Notwendigkeit betrachten, um das Gleichgewicht wiederherzustellen, nachdem die Bestien begonnen haben, Reisende zu jagen.",["class:Hunter"]="Als Jäger versteht Ihr die Raubinstinkte fliegender Bestien und die Rangordnung eines wilden Schwarms. Die Matriarchin zu töten, ist der sicherste Weg, die Angriffslust des Schwarms zu brechen.",["race:NightElf"]="Als Nachtelf verehrt Ihr Hippogryphen als heilige Gefährten von Elune. Einen aggressiven wilden Schwarm zu dezimieren, ist eine bedrückende Aufgabe, wenn die Wildnis mit der Sicherheit der Reisenden in Konflikt gerät."},sec={{t="Gefahr auf der Straße",b="Reisenden nahe Shen'dar droht Gefahr aus den Lüften. Ein wilder Schwarm nistet südöstlich der Siedlung im Shen'darhochland. In ganz Kalimdor gelten Hippogryphen als edle Bestien, und manche sind an elfische Reiter gebunden. Ungezähmte Schwärme verteidigen ihr Revier jedoch erbittert.\n\nWagen und allein reisende Wanderer auf den Pfaden darunter sind zum Ziel von Hinterhalten aus der Luft geworden. Die Angriffe behindern die Durchreise und könnten das Dorf abschneiden, wenn den Kreaturen nicht Einhalt geboten wird."},{t="Den Schwarm dezimieren",b="Um die Gefahr zu beenden, muss der Schwarm an seinen Nistgründen im Shen'darhochland bekämpft werden. Damit die Höhenstraßen sicher werden, tötet die Jungen, bevor sie ausgewachsen sind, und bezwingt die wachsamen Beschützer, die die Grenzen bewachen.\n\nDie Matriarchin lenkt die Angriffe auf Vorbeireisende. Erst wenn das Nest angegriffen wird und sie fällt, können Reisende die Straßen wieder sicher nutzen."}},faq={{q="Warum greifen die Hippogryphen Reisende nahe Shen'dar an?",a="Die Hippogryphen haben südöstlich von Shen'dar im Shen'darhochland Nistgründe angelegt. Ihr Revier liegt neben der Hauptreiseroute, und sie greifen alle an, die sich nähern, um ihre Brut und Jagdgründe zu verteidigen.",al={"warum hippogryphen angreifen","warum sind hippogryphen feindselig","hippogryph harassment ursache"}},{q="Wo befindet sich der Hippogryphenschwarm?",a="Der Schwarm nistet südöstlich von Shen'dar im Shen'darhochland. Sein Nistplatz liegt oberhalb der Straße, wo sich die Jungen, Beschützer und die Matriarchin zwischen Klippen und Bergkämmen versammeln.",al={"wo sind die hippogryphen","hippogryphen fundort","shen'darhochland lage"}},{q="Welche Hippogryphen müssen getötet werden, um die Aufgabe abzuschließen?",a="Damit Reisende wieder sicher passieren können, tötet acht Hippogryphenjunge, sechs kräftige Hippogryphenbeschützer und die Hippogryphenmatriarchin, die den Nistplatz im Shen'darhochland beherrscht.",al={"welche hippogryphen töten","hippogryph harassment ziele","hippogryphen aufgabenziele"}},{q="Wer führt den Hippogryphenschwarm an?",a="Eine mächtige Hippogryphenmatriarchin führt den Schwarm im Shen'darhochland an. Sie beherrscht den Nistplatz und lenkt die Verteidigung der Nistgründe südöstlich von Shen'dar, weshalb sie sterben muss, um die Straße vom Schwarm zu befreien.",al={"wer führt die hippogryphen an","hippogryphenmatriarchin","hippogryphenanführer"}},{q="Warum müssen die Hippogryphenjungen getötet werden?",a="Die Jungen sichern das künftige Wachstum und die weitere Ausbreitung des Schwarms. Sie zusammen mit den ausgewachsenen Beschützern zu töten, verhindert, dass der Schwarm rasch wieder zu Kräften kommt oder die örtlichen Landstraßen dauerhaft in Angst und Schrecken versetzt.",al={"warum hippogryphenjunge töten","warum junge hippogryphen angreifen","hippogryphenjunge dezimieren"}},{q="Sind diese Hippogryphen zahm oder mit jemandem verbündet?",a="Nein. Es sind wilde, ungezähmte Kreaturen, die sich aus eigenem Antrieb einen Nistplatz im Shen'darhochland geschaffen haben. Anders als die disziplinierten Reittiere der Nachtelfen betrachtet dieser wilde Schwarm jeden vorbeiziehenden Humanoiden als Eindringling oder Beute, die in sein Revier vordringt.",al={"sind die hippogryphen gezähmt","sind das hippogryphen der nachtelfen","freundliche hippogryphen"}},{q="Welche Gefahr stellen diese Hippogryphen für die örtliche Siedlung dar?",a="Der Schwarm nistet oberhalb der Straße, die von Shen'dar nach Südosten führt. Die Bestien stürzen sich auf Versorgungskarren, Boten und umherziehende Reisende, gefährden sichere Reisen über Land und drohen, das Dorf vom Umland abzuschneiden.",al={"welche bedrohung stellen hippogryphen dar","gefahr für shen'dar","warum sind hippogryphen ein problem"}}},fp="21,267,17.465.0,17.357.0,66.235.0,38.181.0,53.165.0,42.231.0,41.232.0,49.257.0,62.250.0"}
P.entries["quest:92517"] = {n="The Criminal Element",s="Die Highlands Bandits terrorisieren das Shen'darhochland von einer Höhle hinter einem Wasserfall aus. Ein neuer Kult ist eingetroffen, und die örtlichen Verteidiger sind überlastet. Deshalb braucht es Hilfe von außen gegen den Anführer der Bande, „Badwind“ Bennic.",h="Die Highlands Bandits terrorisieren das Shen'darhochland von einer Höhle hinter einem Wasserfall aus.",kw={"badwind bennic","bennic","kult","highlands bandits","shen'darhochland","the criminal element","höhle hinter dem wasserfall"},ang={["class:Rogue"]="Als Schurke wisst Ihr, dass verborgene Höhlen hinter Wasserfällen typische Banditenverstecke sind. „Badwind“ Bennic und seine Leute lassen die nötige Vorsicht vermissen, um den Blicken der Einheimischen zu entgehen und ihrem Zorn zu entkommen."},sec={{t="Gesetzlose hinter den Fällen",b="Die Highlands Bandits haben ihren Unterschlupf in einer verborgenen Höhle hinter einem Wasserfall im Norden des Shen'darhochlands eingerichtet. Ihr Anführer, „Badwind“ Bennic, befehligt Halsabschneider, die den Einheimischen schon lange vor der Ankunft eines rätselhaften Kults zusetzten. Seitdem ist ihre Gesetzlosigkeit zu Terror angewachsen. Die örtlichen Verteidiger sind überlastet und können keine Kräfte entbehren, also werdet Ihr entsandt, um die Bande zu zerschlagen und Bennic zu Fall zu bringen."},{t="Wandel in den Schatten",b="Nachdem „Badwind“ Bennic ausgeschaltet ist, verlieren die Highlands Bandits ihren Einfluss, und die Einheimischen erhalten eine kurze Atempause. Doch überlebende Gesetzlose könnten bei dem nahegelegenen Kult Zuflucht suchen. Nimmt er diese erfahrenen Wegelagerer auf, könnten seine Reihen anwachsen und die Bedrohung in der gesamten Region verschärfen."}},faq={{q="Wer ist „Badwind“ Bennic?",a="„Badwind“ Bennic führt die Highlands Bandits von einer verborgenen Höhle hinter einem Wasserfall im Shen'darhochland aus an. Seine Bande plagt die Gegend schon lange, und die jüngsten Unruhen haben sie zu einem noch größeren Schrecken gemacht.",al={"wer ist badwind bennic","bennic","badwind"}},{q="Wo verstecken sich die Highlands Bandits?",a="Die Highlands Bandits verstecken sich in einer Höhle hinter einem Wasserfall im Norden des Shen'darhochlands.",al={"wo sind die banditen","standort der banditenhöhle","höhle hinter dem wasserfall"}},{q="Was ist das für ein Kult, von dem in der Gegend die Rede ist?",a="Der Kult ist eine neue, beunruhigende Gruppierung, deren Anhänger sich im südlich gelegenen Falaath Village sammeln und deren Zahl wächst. Die Banditen waren schon vor der Ankunft des Kults hier, doch seine Gegenwart hat die Region gefährlicher gemacht. Die örtlichen Streitkräfte befürchten, dass überlebende Banditen bei dem Kult Zuflucht suchen und seine Reihen verstärken könnten.",al={"welcher kult","verbindung zum kult","wer ist der kult"}},{q="Warum können die örtlichen Streitkräfte die Banditen nicht selbst bekämpfen?",a="Die örtlichen Streitkräfte sind durch den aufkommenden Kult überlastet und haben nicht genug Leute, um die Banditen zu vertreiben. Bennic zu Fall zu bringen und seine Bande zu zerstreuen, beseitigt eine akute Bedrohung in der Region.",al={"warum die banditen töten","banditenproblem"}},{q="Was geschieht mit den Banditen, nachdem Bennic besiegt ist?",a="Mit Bennics Niederlage wird der Unterschlupf der Banditen zerschlagen, doch überlebende Gesetzlose könnten bei dem nahegelegenen Kult Schutz suchen und seine bereits beunruhigende Anhängerzahl vergrößern.",al={"was geschieht mit überlebenden banditen","sind alle banditen gestorben"}},{q="Wo spielt sich dieser Konflikt ab?",a="Die Highlands Bandits durchstreifen das Shen'darhochland, wo sie eine verborgene Höhle hinter einem Wasserfall als Unterschlupf nutzen.",al={"wo liegt das shen'darhochland","shen'darhochland"}}},fp="20,221,24.398.0,22.278.1,24.206.0,39.95.0,39.323.0,53.187.0,53.159.0,36.100.0"}
P.entries["quest:92519"] = {n="Ward Restocking",s="Doktor Gregory Victor fehlen in Hammerfall Heilmittel, Gegengifte und Elixiere für die Krankenstation. Die fehlenden Tonika sind auf Go'Sheks Hof.",h="Doktor Gregory Victor fehlen in Hammerfall Heilmittel, Gegengifte und Elixiere für die Krankenstation.",kw={"apotheker jorell","arathihochland","doktor gregory victor","go'sheks hof","hammerfall","verpackte tonika","ward restocking"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass Hammerfall regelmäßige Lieferungen von Tonika und Medizin benötigt. Sie helfen seinen Soldaten, Verteidigern und Reisenden, den Bedrohungen im Arathihochland standzuhalten.",["race:Undead"]="Als Untoter wisst Ihr, dass Apotheker Jorell die Präsenz der Royal Apothecary Society nach Arathi trägt. Sein unberechenbares Verhalten und seine giftigen Experimente auf Go'Sheks Hof frustrieren selbst seine Verbündeten."},sec={{t="Engpass auf der Krankenstation",b="Doktor Gregory Victor versorgt Hammerfalls Verwundete und Kranke auf der Krankenstation. Der nahe gelegene Apotheker der Verlassenen beliefert die Krankenstation gewöhnlich mit Heilmitteln, Gegengiften und Elixieren. Als diese Lieferungen ausbleiben, wendet sich Victor an fähige Reisende, um die Vorräte der Klinik aufzufüllen."},{t="Der Einsiedler von Go'Sheks Hof",b="Apotheker Jorell arbeitet in einer engen Hütte auf Go'Sheks Hof, südlich und westlich von Hammerfall. Doktor Victor sagt, Jorell sei oft abwesend. Der exzentrische Chemiker der Verlassenen vernachlässigt womöglich seine Pflichten oder erliegt seinen eigenen giftigen Mixturen. Kuriere, die die verpackten Tonika holen sollen, dürften die Medizin dort vorfinden, ob Jorell nun anwesend ist oder nicht."}},faq={{q="Wer bietet die Quest Ward Restocking an?",a="Doktor Gregory Victor leitet Hammerfalls medizinische Abteilung und Krankenstation. Wenn die regelmäßigen Lieferungen ausbleiben, bittet er zuverlässige Reisende, Vorräte zu beschaffen.",al={"wer vergibt ward restocking","questgeber ward restocking","doktor gregory victor quest"}},{q="Wo befindet sich Apotheker Jorell?",a="Apotheker Jorell arbeitet in einer kleinen Hütte auf Go'Sheks Hof, südlich und etwas westlich von Hammerfall an der Straße im Arathihochland.",al={"wo ist apotheker jorell","jorells labor standort","wo tonika finden"}},{q="Warum schickt Doktor Gregory Victor Euch zu Go'Sheks Hof?",a="Doktor Gregory Victor schickt Euch zu Go'Sheks Hof, weil Apotheker Jorell eine dringend benötigte Kiste mit Gegengiften und Elixieren nicht an Hammerfalls Krankenstation geliefert hat.",al={"warum zu go'sheks hof gehen","was ist auf go'sheks hof"}},{q="Welche Vorräte benötigt die Krankenstation?",a="Die Krankenstation benötigt eine Kiste mit Verpackten Tonika, die Apotheker Jorells Gegengifte und Elixiere enthält. Sie werden die schwindenden Vorräte von Hammerfalls Krankenstation auffüllen.",al={"was sind verpackte tonika","welche gegenstände abholen"}},{q="Warum hat Apotheker Jorell die Vorräte nicht selbst geliefert?",a="Doktor Gregory Victor vermutet, dass Jorell sich beim Brauen von Mixturen in seiner schlecht belüfteten Hütte erneut vergiftet oder seine Pflichten gegenüber der Krankenstation vernachlässigt hat.",al={"was ist mit jorell passiert","ist jorell tot","warum hat jorell nicht geliefert"}},{q="Wohin müssen die Vorräte geliefert werden?",a="Bringt die Kiste mit Tonika von Go'Sheks Hof zu Doktor Gregory Victor auf der Krankenstation in Hammerfall.",al={"wohin kommen die tonika","bei wem ward restocking abgeben"}}},fp="15,140,22.273.0,27.333.0,37.154.0,35.137.0,56.170.0,38.166.0,60.161.0,37.102.0"}
P.entries["quest:92528"] = {n="Among the Faithful",s="In Falaath Village bewegt Ihr Euch unter den Getreuen von Al'Akir im Shen'darhochland. Ihre wachsenden Reihen und ihre Sturmmagie werden genau beobachtet, während ihre Anführer zusammenkommen und Pläne schmieden, die nahe Siedlungen und Außenposten bedrohen.",h="In Falaath Village bewegt Ihr Euch unter den Getreuen von Al'Akir im Shen'darhochland.",kw={"al'akir","among the faithful","falaath village","lorthuna","shen'darhochland","himmelspriester aanders","westlicher wachturm","windlord"},ang={["class:Priest"]="Als Priester folgt Ihr vertrauten Glaubensrichtungen des Heiligen oder des Schattens. In Falaath Village folgen die Kultisten Himmelspriestern, die Al'Akir dem Windlord ergeben sind und die urtümliche Kraft des Sturms kanalisieren.",["class:Shaman"]="Als Schamane kennt Ihr die elementaren Kräfte, die der Kult von Al'Akir verehrt und durch seine Beherrschung der Sturmenergien befehligt."},sec={{t="Infiltration von Falaath Village",b="Ihr betretet Falaath Village im Shen'darhochland als eifriger Rekrut unter den Getreuen von Al'Akir. Die Kultisten prahlen damit, dass ihre Reihen wachsen. Sie behaupten, ihre Hingabe verleihe dem Sturm seine Gestalt und seinen Zorn. Neuankömmlinge werden gewöhnlich zur Überprüfung zu Himmelspriester Aanders geschickt, doch ein unerwartetes Treffen im Gasthaus des Dorfes unterbricht diesen Ablauf."},{t="Der geheime Gast",b="Himmelspriester Aanders empfängt einen hochrangigen Gast im Norden des Ortes. Während er beschäftigt ist, könnt Ihr Euch ohne seine Aufsicht durch die Siedlung bewegen. Wenn Ihr die Anführer belauscht, erfahrt Ihr ihren unmittelbaren Plan: einen koordinierten militärischen Vorstoß durch das Shen'darhochland."},{t="Lorthunas Plan",b="Lorthuna ist der geheimnisvolle Gast im Gasthaus und die oberste Befehlshaberin des gesamten Kults. Ihre Anwesenheit deutet auf einen heftigen Angriff gegen Shen'dar und den westlichen Wachturm hin. Shen'dar ist eindeutig ein Bevölkerungszentrum. Doch örtliche Späher verstehen weder, warum der abgelegene Aussichtsturm ein Ziel ist, noch was hinter der sturmgetriebenen Offensive des Kults steckt."}},faq={{q="Wer sind die Getreuen von Al'Akir?",a="Die Getreuen von Al'Akir sind ein Kult, der dem Windlord Al'Akir ergeben ist. Sie sind rund um Falaath Village im Shen'darhochland ansässig, wirken Sturmmagie und unterstehen Lorthuna.",al={"wer sind die getreuen von alakir","was ist das für ein kult","alakir kult"}},{q="Wer ist Himmelspriester Aanders?",a="Himmelspriester Aanders ist ein ranghoher Offizier des Kults in Falaath Village. Er prüft neue Rekruten und nimmt sie auf, ist jedoch während Eurer Infiltration damit beschäftigt, einen wichtigen Gast im Gasthaus des Dorfes zu empfangen.",al={"wer ist himmelspriester aanders","aanders","typ für die kultprüfung"}},{q="Wer ist Lorthuna?",a="Lorthuna ist die oberste Anführerin des Kults von Al'Akir. Ihre heimliche Anwesenheit im Gasthaus von Falaath Village offenbart, dass der Kult eine unmittelbar bevorstehende Offensive unter höchster Führung im Hochland vorbereitet.",al={"wer ist lorthuna","kultanführerin lorthuna","gast im gasthaus"}},{q="Warum nimmt der Kult den westlichen Wachturm ins Visier?",a="Der Kult plant gleichzeitige Angriffe auf Shen'dar und den westlichen Wachturm. Das Dorf ist ein nachvollziehbares Ziel, doch die Rolle des Wachturms bei dem Angriff bleibt den Verteidigern des Hochlands ein Rätsel.",al={"warum den wachturm angreifen","westlicher wachturm kult","ziele des kults"}},{q="Wo spielt sich das ab?",a="Falaath Village liegt im Shen'darhochland. Es ist ein wichtiger Stützpunkt und Aufmarschplatz für die Getreuen von Al'Akir und ihre neuen Rekruten.",al={"wo liegt falaath village","falaath village lage"}},{q="Welche Absichten verfolgt der Kult im Shen'darhochland?",a="Der Kult will seinen Einfluss ausweiten und Sturmmagie im gesamten Shen'darhochland entfesseln. Unter Lorthunas Führung richtet sich sein unmittelbar bevorstehender Angriff gegen Shen'dar und den westlichen Wachturm.",al={"welche ziele hat der kult im shen'darhochland","kultpläne shen'dar"}}},fp="18,227,28.348.0,16.267.1,17.364.2,32.176.0,25.204.0,16.188.0,49.208.0,27.137.0,57.197.0"}
P.entries["quest:92529"] = {n="Falaath Village",s="In Falaath Village sammeln sich gezeichnete Rekruten, um die Gunst des Windfürsten zu suchen. Sie kommen aus Shen'dar, um sich bei Missionar Jasaan zu melden und sich den Gläubigen anzuschließen.",h="In Falaath Village sammeln sich gezeichnete Rekruten, um die Gunst des Windfürsten zu suchen.",kw={"al'akir","falaath village","mal von akir","missionar jasaan","sania silverstream","shen'dar","shen'dorei","windfürst"},ang={["class:Shaman"]="Als Schamane sucht Ihr Harmonie mit den Elementargeistern. Die Gläubigen nähern sich Al'Akir durch Buße und religiöse Hingabe, in der Hoffnung, die Winde zurückzugewinnen, die sie verlassen haben.",["race:Skyborne"]="Als Shen'dorei, der seine Verbindung zu den Winden wiederherstellen will, schließt Ihr Euch den Gläubigen in Falaath Village in gemeinsamer Reue an. Dort hofft Ihr, Al'Akirs Gunst zurückzugewinnen."},sec={{t="Reue für den Windfürsten",b="In Shen'dar erzählt Sania Silverstream, ihr Volk sei hochmütig geworden und habe die Gaben der Luft als selbstverständlich angesehen. Die Windgeister verließen sie, und Stillstand folgte. Nun erhalten reuige Rekruten das Mal von Akir und reisen nach Falaath Village. Dort schließen sie sich anderen an, die hoffen, durch ihre Taten der Reue die Gunst des Windes zurückzugewinnen."},{t="Die Mission in Falaath",b="In Falaath Village heißt Missionar Jasaan Initianden willkommen, die das Mal von Akir tragen. Jasaan sieht jeden neuen Akolythen als Segen der vier Winde. Wer ankommt, kann die elementare Gnade von Al'Akir suchen."}},faq={{q="Was ist die Quest Falaath Village?",a="Gezeichnete Rekruten reisen von Shen'dar nach Falaath Village und melden sich bei Missionar Jasaan. Dort suchen sie Gemeinschaft mit den Gläubigen.",al={"was ist die quest falaath village","falaath village überblick","falaath village quest"}},{q="Wer ist Missionar Jasaan?",a="Missionar Jasaan ist ein Akolyth nahe dem Eingang von Falaath Village. Jasaan heißt Rekruten willkommen, die Sania Silverstream entsandt hat, um Al'Akirs Segen zu suchen.",al={"wer ist missionar jasaan","jasaan hintergrundgeschichte","falaath missionar"}},{q="Wer ist Sania Silverstream?",a="Sania Silverstream ist eine der Gläubigen in Shen'dar. Sie gibt neuen Rekruten das Mal von Akir und weist ihnen den Weg nach Falaath Village.",al={"wer ist sania silverstream","sania hintergrundgeschichte","schwester sania"}},{q="Warum verehren die Shen'dorei Al'Akir?",a="Die Anhänger glauben, ihr Volk sei hochmütig geworden und habe die Gaben der Winde als selbstverständlich angesehen. Die Geister verließen sie, und durch Taten der Reue versuchen sie, Al'Akirs Gunst zurückzugewinnen.",al={"warum alakir verehren","windfürst alakir verehrung","wer ist der windfürst"}},{q="Was ist das Mal von Akir?",a="Das Mal von Akir ist ein Zeichen, das Sania Silverstream Rekruten in Shen'dar gibt. Es kennzeichnet sie als Mitglieder der Glaubensgemeinschaft, bevor sie Falaath Village betreten.",al={"was ist das mal von akir","verlorenes mal von akir","rekruten mal"}},{q="Wer sind die in der Quest erwähnten Shen'dorei?",a="Die Shen'dorei, von denen Sania spricht, sind Elfen, denen Stillstand droht, seit die Windgeister ihnen ihre Gunst entzogen haben. Einige suchen Sühne durch Hingabe an die Elemente.",al={"wer sind die shendorei","shen dorei hintergrundgeschichte"}}},fp="15,158,27.338.0,22.204.0,34.143.0,25.150.0,26.139.0,43.190.0,25.162.0,46.157.0"}
P.entries["quest:92532"] = {n="The Warrior's Path",s="Rorian the Dayseeker schickt Euch zu Klingenmeisterin Ren in Thendal. Sie bietet jungen Kriegern Unterweisung und Disziplin, damit sie ihr Volk verteidigen können.",h="Rorian the Dayseeker schickt Euch zu Klingenmeisterin Ren in Thendal.",kw={"klingenmeisterin ren","zusammengeknüllte notiz","rorian the dayseeker","thendal","pfad des kriegers","wachturm","insel zephras"},ang={["class:Warrior"]="Als Krieger beginnt Ihr Eure Kampfausbildung in Thendal mit Klingenmeisterin Ren als Eurer Mentorin."},sec={{t="Ein Ruf zum Wachturm",b="Nachdem Ihr in der Nähe das Gleichgewicht wiederhergestellt habt, kehrt Ihr zu Rorian the Dayseeker in Thendal zurück. Die Klingenmeisterin des Dorfes ist auf Euch aufmerksam geworden, und Rorian überreicht Euch eine Zusammengeknüllte Notiz, die Ren selbst verfasst hat. Sie bittet Euch, direkt zu ihr zu kommen.\n\nRen wartet im Wachturm des Dorfes, hoch über der Siedlung. Von dort aus beobachtet sie die Grenzen der Insel und die Rekruten, die sie eines Tages verteidigen könnten."},{t="Der Mantel des Schutzes",b="Im Wachturm lehrt Euch Klingenmeisterin Ren, dass zum Kampf mehr gehört als rohe Kraft. Ein Krieger muss führen, standhalten und schützen, während die Welt immer ungewisser wird. Ren verspricht, Euch zu führen, während Ihr Eure Fähigkeiten verfeinert. Ihre strenge Ausbildung bereitet Euch auf die größeren Gefahren vor, die Eure Heimat bedrohen."}},faq={{q="Wer schickt mich zu Klingenmeisterin Ren?",a="Nachdem Ihr Eure Arbeit in Thendal erledigt habt, schickt Euch Rorian the Dayseeker zu Klingenmeisterin Ren. Ren hat Rorian gebeten, Euch nach Eurer Rückkehr zu ihrem Wachturm zu schicken.",al={"wer beginnt die quest","questgeber","rorians rolle"}},{q="Wo finde ich Klingenmeisterin Ren?",a="Klingenmeisterin Ren wartet im Wachturm von Thendal auf der Insel Zephras. Sie wacht über das Dorf und bildet unerfahrene Kämpfer aus.",al={"wo ist klingenmeisterin ren","rens standort","wachturm von thendal"}},{q="Was ist die Zusammengeknüllte Notiz?",a="Die Zusammengeknüllte Notiz ist Klingenmeisterin Rens persönliche Aufforderung, zu ihr zu kommen, überbracht von Rorian. Sie fordert Euch auf, sie zu lesen und Euch zur Kampfausbildung im Wachturm von Thendal zu melden.",al={"zusammengeknüllte notiz","was steht in der notiz","rens notiz"}},{q="Was lehrt Klingenmeisterin Ren junge Krieger?",a="Klingenmeisterin Ren lehrt Wachsamkeit, Führung und Schutz. Krieger brauchen den Willen, sich zwischen die Gefahr und ihr Volk zu stellen, während sich die Welt wandelt und die Gefahren zunehmen.",al={"rens lehren","was lehrt ren","aufgabe der krieger"}},{q="Ist diese Quest für die Kriegerausbildung auf der Insel Zephras erforderlich?",a="Dabei lernt Ihr Klingenmeisterin Ren kennen, Eure Klassenlehrerin in Thendal, und erfahrt, wohin Ihr zurückkehren könnt, um Kampftechniken zu erlernen.",al={"muss ich das machen","einführung beim kriegerlehrer","ist es pflicht"}},{q="Was meint Ren mit „Mögen die Winde Euch leiten“?",a="Rens Segen spiegelt die Kultur der Insel Zephras wider. Er wünscht Reisenden sicheres Geleit, einen klaren Geist und Glück in fremden und gefährlichen Landen.",al={"mögen die winde euch leiten bedeutung","windzitat","rens abschied"}}},fx={["2d8c1194"]={q="Warum schickt mich Rorian the Dayseeker zu Blademaster Ren?",a="Blademaster Ren hat Rorian persönlich gebeten, Euch zum Wachturm zu schicken, sobald Ihr nach Thendal zurückgekehrt seid. Da sich die Welt im Wandel befindet und gefahrvolle Prüfungen bevorstehen, erkennt Ren, dass aufstrebende Krieger engagierte Kampfausbildung und Führung benötigen, wenn Euer Volk die kommenden Gefahren überstehen soll. Rorian kommt Ren einfach nur zuvor, um sicherzustellen, dass Ihr die Ausbildung erhaltet, die Ihr benötigt.",al={"warum schickt mich rorian","rorians beweggrund","warum blademaster ren finden"}}},fp="18,146,27.382.0,24.302.0,37.160.0,33.138.0,26.167.0,47.165.0,60.128.0,48.140.0"}
P.entries["quest:92544"] = {n="Al'Aketh Thugs",s="In den Tempelruinen nahe dem Thendalhain bedrohen Al'Aketh-Kultisten Reisende. Auf Befehl von Hohepriesterin Lorthuna vom Schrein von Akir entsandt, drangsalieren sie Wanderer und zwingen Rekruten in ihre Reihen. Hanaa Nightwind bittet Euch, ihre Macht zu brechen und ihren Anführer zu töten.",h="In den Tempelruinen nahe dem Thendalhain bedrohen Al'Aketh-Kultisten Reisende.",kw={"al'aketh-schläger","al'aketh-neophyt","al'aketh thugs","hanaa nightwind","hohepriesterin lorthuna","malduko cloudcrush","schrein von akir","thendalhain"},sec={{t="Kultschläger in den Ruinen",b="Unmittelbar südwestlich des Thendalhains sind uralte Tempelruinen für Reisende gefährlich geworden. Die Al'Aketh haben das Gelände besetzt und überfallen Menschen nahe dem Hain. Die in der Nähe stationierten Rangers vermuten, dass Hohepriesterin Lorthuna die Schläger vom Schrein von Akir entsandt hat. Sie schikanieren die Menschen und zwingen sie, sich dem Kult zu unterwerfen."},{t="Malduko Cloudcrush, brutaler Kultanführer",b="In den Ruinen herrscht Malduko Cloudcrush mit Gewalt und Furcht. Schläger und frisch indoktrinierte Neophyten gehorchen ihm und machen den Tempel zu einem aggressiven Außenposten vor den Toren des Thendalhains. Hanaa Nightwind hofft, dass Cloudcrushs Tod und die Zerstreuung seiner Anhänger das Selbstvertrauen des Kults erschüttern werden. Es wird ihnen als Warnung dienen, dass Zwang in diesen Landen nicht geduldet wird."}},faq={{q="Wer sind die Al'Aketh?",a="Die Al'Aketh sind ein fanatischer Kult, der auf Zephras sein Unwesen treibt. Hohepriesterin Lorthuna führt sie vom Schrein von Akir aus. Ihre Anhänger zwingen Reisende und Bewohner mit Einschüchterung und Gewalt zum Beitritt.",al={"was sind die al'aketh","al'aketh-kult","wer sind alaketh"}},{q="Warum greifen die Kultisten den Thendalhain an?",a="Die Kultisten haben ihr Lager in Tempelruinen südwestlich des Thendalhains aufgeschlagen. Dort überfallen sie Reisende, die das Gebiet verlassen, und terrorisieren Menschen auf der Straße. Sie hoffen, die Einheimischen dazu zu drängen, sich dem Kult zu unterwerfen.",al={"warum sind kultisten hier","warum thendalhain","motiv der kultisten"}},{q="Wer ist Malduko Cloudcrush?",a="Malduko Cloudcrush führt das Lager der Al'Aketh in den Tempelruinen an. Hanaa Nightwind nennt ihn ein Ungeheuer. Er befehligt die Schläger und Neophyten, die auf den nahen Straßen Menschen überfallen.",al={"malduko","cloudcrush","wer ist malduko cloudcrush"}},{q="Wer ist Hanaa Nightwind?",a="Hanaa Nightwind ist eine Ranger, die den Thendalhain bewacht. Sie bleibt auf ihrem Posten an der Straße und warnt Reisende vor dem nahen Hinterhalt. Sie ist auf fähige Abenteurer angewiesen, um die Bedrohung zu beseitigen.",al={"hanaa","hanaa nightwind","questgeber"}},{q="Wer hat diese Kultisten zu den Ruinen geschickt?",a="Hanaa vermutet, dass Hohepriesterin Lorthuna die Kultisten vom Schrein von Akir entsandt hat. Lorthuna beaufsichtigt dort die Aktivitäten des Kults.",al={"wer befehligt sie","kultführer","wer hat malduko geschickt"}},{q="Was findet sich noch in der Nähe der Tempelruinen?",a="Eine aktive Ley Line liegt in den uralten Ruinen am südwestlichen Ende des Gebiets, neben dem Lager der Al'Aketh.",al={"ruinen ley line","geheimnis der tempelruinen","ruinen im südwesten"}}},fx={b63e8692={q="Warum möchte Hanaa Nightwind, dass die Al'Aketh Thugs beseitigt werden?",a="Die Al'Aketh-Kultisten haben ihr Lager gefährlich nah am Thendalhain aufgeschlagen, belästigen Reisende auf den Straßen und versuchen, die örtliche Bevölkerung in ihre eifernde Gefolgschaft zu zwingen. Ranger Hanaa Nightwind will ihren Einfluss in den Ruinen im Südwesten brechen und ein blutiges, unmissverständliches Zeichen setzen, das die überlebenden Kultisten dazu zwingt, die Gegend zu verlassen.",al={"warum die alaketh thugs töten","hanaa nightwinds beweggrund","warum die tempelruinen säubern"}},b6ccde37={q="Warum kann Hanaa Nightwind sich nicht selbst um die Kultisten kümmern?",a="Hanaa muss auf ihrem Posten bleiben, um Wache zu halten und ahnungslose Reisende, die Thendal verlassen, zu warnen, bevor sie in den Hinterhalt der Kultisten laufen. Obwohl es all ihre Zurückhaltung erfordert, nicht selbst in die Ruinen zu marschieren, kann sie ihre Pflicht am Rande des Hains nicht vernachlässigen.",al={"warum braucht mich hanaa","warum kämpft hanaa nicht gegen sie","warum ich alaketh thugs"}}},fp="14,276,29.322.0,18.370.0,21.201.0,45.206.0,26.168.0,23.188.0,37.122.0,45.117.0"}
P.entries["quest:92550"] = {n="Havoc in the Highlands",s="Im Hochland geht Shen'dar gegen die Streitkräfte der Al'Aketh in Falaath Village vor. Seine Verteidiger wollen einen Angriff verhindern, bevor er beginnt, und ihre Heimat schützen.",h="Im Hochland geht Shen'dar gegen die Streitkräfte der Al'Aketh in Falaath Village vor.",kw={"al'aketh","kommandant cyclas","falaath village","havoc in the highlands","lebende blitze","sania silverstream","shen'dar","sturmbeschwörer"},ang={["class:Shaman"]="Als Schamane wisst Ihr, dass Sturmbeschwörer der Al'Aketh und ihre herbeibeschworenen Lebenden Blitze über die Elemente gebieten. Die Kultisten verdrehen Wind und Sturm zu Waffen fanatischer Aggression."},sec={{t="Ein Präventivschlag",b="Fanatische Kultisten bereiten einen Angriff auf Shen'dar vor. Deshalb entsendet Euch die Führung in die Ruinen von Falaath Village, um zuerst zuzuschlagen, bevor die Streitkräfte der Al'Aketh ihren Angriff beginnen können."},{t="Angriff auf Falaath Village",b="Eiferer der Al'Aketh sammeln sich in Falaath Village und gebieten über chaotische Elementarmacht. Ihr durchbrecht ihre Reihen, indem Ihr Sturmbeschwörer der Al'Aketh besiegt und Lebende Blitze zerschlagt. Dann spürt Ihr Kommandant Cyclas auf und enthauptet ihn."},{t="Sicherung des Hochlands",b="Kommandant Cyclas ist tot, und seine Vorhut ist vernichtet. Shen'dar gewinnt eine lebenswichtige Atempause. Während die Bürger zu den Waffen greifen, schleicht sich Sania Silverstream unbemerkt aus der Stadt. Sie flieht, während die örtliche Verteidigung an Stärke gewinnt."}},faq={{q="Was ist Havoc in the Highlands?",a="Shen'dar führt einen Präventivschlag gegen Kultisten der Al'Aketh in den Ruinen von Falaath Village aus. Seine Verteidiger hoffen, einen Angriff zu verhindern, bevor er beginnt.",al={"havoc in the highlands quest","was ist havoc in the highlands","hochland quest"}},{q="Wer bedroht Shen'dar?",a="Die Al'Aketh bedrohen Shen'dar. Sie verehren elementare Stürme und schicken Sturmbeschwörer, gebundene Lebende Blitze und ihren Anführer Kommandant Cyclas ins Feld.",al={"wer sind die feinde","welcher kult ist das","wer greift shen'dar an"}},{q="Wo sammeln sich die Kultisten?",a="Die Kultisten sammeln sich in den Ruinen von Falaath Village. Kommandant Cyclas und seine Anhänger der Al'Aketh nutzen sie als Aufmarschgelände.",al={"wo ist kommandant cyclas","falaath village ruinen","wohin gehen"}},{q="Wer ist Kommandant Cyclas?",a="Kommandant Cyclas führt die Streitkräfte der Al'Aketh an, die sich in den Ruinen von Falaath Village versammelt haben. Sie bereiten ihren Marsch auf Shen'dar vor.",al={"wer ist kommandant cyclas","cyclas hintergrundgeschichte","cyclas kult"}},{q="Warum floh Sania Silverstream aus Shen'dar?",a="Sania Silverstream schleicht sich aus Shen'dar, kurz bevor sich dessen Verteidiger sammeln. Vermutlich flieht sie, nachdem sie sieht, wie die Einwohner zu den Waffen greifen und ihre Verteidigung organisieren.",al={"sania silverstream auf der flucht","warum ging sania fort","wer ist sania silverstream"}},{q="Gelingt es durch den Schlag, Shen'dar zu sichern?",a="Shen'dar wendet die unmittelbare Bedrohung ab, indem es die vordersten Reihen der Kultisten zerschlägt und Kommandant Cyclas enthauptet. Zurückkehrende Eiferer werden das Hochland zum Widerstand bereit vorfinden.",al={"hat shen'dar überlebt","folgen des angriffs","ist shen'dar sicher"}}},fp="22,163,19.185.0,26.214.0,22.231.1,31.145.0,36.153.0,31.128.0,24.119.0,49.163.0,53.179.0"}
P.entries["quest:92551"] = {n="Gestohlene Versorgungsgüter",s="Karawanen ins Shen'darhochland werden überfallen, und ihre gestohlenen Waren sammeln sich in Falaath Village. Nahrung und Windsteine werden in den Hochlandsiedlungen knapp, sodass manche Himmelsgeborene dem Hungertod nahe sind.",h="Karawanen ins Shen'darhochland werden überfallen, und ihre gestohlenen Waren sammeln sich in Falaath Village.",kw={"al'aketh","karawanen","wachtmeister","falaath village","shen'darhochland","himmelsgeborene","gestohlene vorräte","windsteine"},ang={["race:Skyborne"]="Die Überfälle unterbrechen die Lebensader zwischen dem Hochland und dem Tiefland. Ohne regelmäßige Lieferungen von Nahrung und Windsteinen leiden die Himmelsgeborenen in den Städten Hunger."},sec={{t="Überfälle auf die Lebensader",b="Seit Monaten greifen Räuber Karawanen auf der Straße zwischen dem Tiefland und dem Shen'darhochland an. Ihre Wagen transportieren Nahrung und Windsteine, auf die die Hochlandsiedlungen angewiesen sind. Da immer weniger Lieferungen ankommen, kämpfen die Stadtbewohner ums Überleben, und manche stehen kurz vor dem Hungertod."},{t="Das Lager in Falaath",b="Die Al'Aketh machen gewöhnliche Banditen für die Angriffe verantwortlich. Doch die verschwundenen Vorräte tauchen immer wieder in Falaath Village auf, wo die Al'Aketh die gestohlenen Bündel lagern. Die zurückgeholten Waren gehen an die örtlichen Behörden und den Wachtmeister, die sie direkt an die bedürftigsten Himmelsgeborenen weiterleiten."}},faq={{q="Welche Vorräte wurden aus den Karawanen gestohlen?",a="Karawanen zwischen dem Tiefland und dem Hochland transportierten Nahrung und Windsteine. Regelmäßige Lieferungen helfen dabei, die örtlichen Stadtbewohner zu ernähren und zu versorgen.",al={"was wurde gestohlen","geraubte vorräte","welche waren wurden gestohlen"}},{q="Wer ist für die Überfälle auf die Karawanen verantwortlich?",a="Die Al'Aketh überfallen die Versorgungskarawanen seit Monaten. Sie geben gewöhnlichen Banditen die Schuld, doch gestohlene Bündel tauchen immer wieder in Falaath Village auf.",al={"wer hat die vorräte gestohlen","wer hat die karawanen überfallen","karawanenangreifer"}},{q="Wo werden die gestohlenen Vorräte gelagert?",a="Die Al'Aketh lagern die gestohlenen Vorratsbündel in Falaath Village im Shen'darhochland.",al={"wo sind die vorräte","wo vorräte finden","lagerorte gestohlener vorräte"}},{q="Warum werden diese Versorgungskarawanen angegriffen?",a="Die Karawanen transportieren Nahrung und Windsteine zwischen dem Tiefland und dem Hochland. Durch die Überfälle fehlen den örtlichen Himmelsgeborenen Vorräte, während sich Waren aus dem Hochland in Falaath Village sammeln.",al={"warum windsteine und nahrung stehlen","warum karawanenüberfälle"}},{q="Was geschieht mit den Vorräten, sobald sie zurückgeholt wurden?",a="Sobald die Vorräte zurückgeholt wurden, gehen sie an den örtlichen Wachtmeister und die Behörden. Diese verteilen sie an die Stadtbewohner, die Nahrung und Hilfe am dringendsten benötigen.",al={"wer bekommt die vorräte zurück","umverteilung der vorräte","was geschieht nach der rückholung"}},{q="Warum geben die Al'Aketh Banditen die Schuld an den Überfällen?",a="Die Al'Aketh geben umherziehenden Banditen die Schuld, um die Verantwortung von sich zu weisen. Doch gestohlene Fracht taucht immer wieder in ihrer Siedlung in Falaath Village auf.",al={"warum banditen beschuldigen","al aketh banditen ausrede"}}},fp="15,213,30.272.0,17.274.0,44.135.0,44.138.0,46.93.0,45.171.0,53.144.0,48.134.0"}
P.entries["quest:92553"] = {n="Restocking the Larders",s="Im Shen'darhochland von Zephras braucht ein Dorfkoch Hilfe, um die Lebensmittelvorräte gefüllt zu halten. Gefahren halten die Dorfbewohner vom Sammeln ab, also bittet der Koch Euch um Eier und Schreiterfleisch.",h="Im Shen'darhochland von Zephras braucht ein Dorfkoch Hilfe, um die Lebensmittelvorräte gefüllt zu halten.",kw={"kochkunst","restocking the larders","shen'darhochland","kleine eier","schreiterfleisch","ursera-talg","zephras"},ang={["profession:Cooking"]="Als Koch sammelt Ihr beim Beschaffen von Schreiterfleisch und kleinen Eiern praktische Erfahrung und erhaltet Rezepte, die auf die Tierwelt von Zephras abgestimmt sind."},sec={{t="Gefahren im Hochland",b="Zunehmende Gefahren erschweren das Leben im Shen'darhochland. Die Dorfbewohner können sich nicht mehr gefahrlos zum Sammeln oder Jagen in die Wildnis wagen, und die gemeinschaftlichen Vorräte sind beinahe leer. Daher verlassen sich die örtlichen Köche auf Reisende, die den wilden Pfaden trotzen und helfen, die Siedlung zu ernähren."},{t="Nahrung und Trost",b="Der Koch bittet Euch, bei den Wildtieren des Hochlands Schreiterfleisch und frische kleine Eier zu beschaffen. Dafür teilt der Koch sein Wissen über das heimische Wild und die dazugehörigen Rezepte. In Ursera-Talg gebratene kleine Eier spenden Trost, dazu getrocknete Friedensblume für eine geruhsame Pfeife."}},faq={{q="Welche Vorräte werden für Restocking the Larders benötigt?",a="Der örtliche Koch braucht drei kleine Eier und acht Stücke Schreiterfleisch, um das Dorf zu ernähren, während Gefahren die gewöhnlichen Sammler in ihren Häusern halten.",al={"restocking larders ziel","was für restocking larders sammeln"}},{q="Wo sind die Zutaten zu finden?",a="Wildtiere im gesamten Shen'darhochland auf Zephras liefern das Schreiterfleisch und die kleinen Eier.",al={"wo schreiterfleisch auf zephras finden","eier fundorte shendar"}},{q="Warum wird die Nahrung im Dorf knapp?",a="Zunehmende Gefahren machen das Jagen und Sammeln für gewöhnliche Dorfbewohner zu gefährlich, sodass die Lebensmittelvorräte zur Neige gehen.",al={"warum nahrung auf zephras benötigt","warum hungert das dorf shendar"}},{q="Welche Belohnung bietet der Koch für die Nahrung?",a="Der Koch bietet im Austausch für frische Vorräte Kochtipps, Techniken und Unterricht in heimischen Rezepten.",al={"was bietet der questgeber","quest kochkunstausbildung"}},{q="Was sind das Shen'darhochland und Zephras?",a="Das Shen'darhochland liegt auf Zephras, wo die Einheimischen wachsenden Bedrohungen trotzen, während sie versuchen, ihren Alltag zu bestreiten.",al={"was ist zephras","wo liegt das shen'darhochland"}},{q="Wie bereitet der Koch die Eier zu?",a="Der Koch brät frisch gesammelte kleine Eier in Ursera-Talg, eine Wohltat auf Zephras.",al={"kochgeheimnis talg","wie werden eier auf zephras zubereitet"}}},fp="22,187,24.271.0,22.247.0,52.134.0,35.100.0,39.111.0,45.106.0,44.116.0,35.82.0"}
P.entries["quest:92579"] = {n="To Valanaar",s="Aonda schickt einen dringenden Bericht quer über die Insel nach Valanaar, wo sich die Friedensbewahrer auf eine wachsende Bedrohung vorbereiten. Ihre Anführerin, Valennia Stormfist, muss ihre Leute rüsten, während der Konflikt mit dem Kult näher rückt.",h="Aonda schickt einen dringenden Bericht quer über die Insel nach Valanaar, wo sich die Friedensbewahrer auf...",kw={"aonda","kult","friedensbewahrer","shen'dar","to valanaar","valanaar","valennia stormfist"},sec={{t="Eine dringende Botschaft",b="Nachdem Ihr geholfen habt, Shen'dar und seinen Pylon zu verteidigen, vertraut Aonda Euch eine dringende Nachricht für Valennia Stormfist an. Valanaar liegt am südöstlichen Rand der Insel, wo die Friedensbewahrer unter Valennias Befehl ihr Hauptquartier haben. Aonda warnt, dass die friedlichen Tage zu Ende gehen. Valennia muss ihre Leute auf einen unvermeidlichen Zusammenstoß mit dem aggressiven, sich ausbreitenden Kult vorbereiten."},{t="Der aufziehende Sturm",b="Die Friedensbewahrer vermieden einen direkten Konflikt mit dem geheimnisvollen Kult, bis dessen Übergriffe die Spannungen auf die Spitze trieben. Nachdem sie Aondas Bericht gelesen hat, weiß Valennia, dass sie ihre verbliebenen Kräfte sammeln und eine Verteidigung planen müssen. Der Kult könnte seine Aufmerksamkeit auf Valanaar selbst richten."}},faq={{q="Wer schickt Euch nach Valanaar?",a="Aonda, eine Hochländerin in Shen'dar, schickt Euch nach Valanaar. Nachdem Ihr geholfen habt, das Dorf und den Pylon vor der drohenden Gefahr durch die Kultisten zu sichern, vertraut sie Euch einen dringenden schriftlichen Bericht an, den Ihr quer über die Insel bringen sollt.",al={"wer vergibt to valanaar","questgeber to valanaar","wer schickt mich nach valanaar"}},{q="Wer ist Valennia Stormfist?",a="Valennia Stormfist führt die Friedensbewahrer der Insel von ihrem Hauptquartier in Valanaar aus. Sie ist für die örtliche Verteidigung und Ordnung zuständig, einschließlich der Maßnahmen gegen die aggressive Ausbreitung des Kults.",al={"wer ist valennia stormfist","valennia anführerin","valennia"}},{q="Was ist Valanaar?",a="Valanaar ist eine Siedlung am südöstlichen Rand der Insel. Sie ist der Stützpunkt der Friedensbewahrer unter Valennia Stormfist sowie ein Zufluchtsort und Treffpunkt für die Bewohner.",al={"was ist valanaar","wo ist valanaar","valanaar lage"}},{q="Welchen Zweck hat Aondas Bericht?",a="Aondas Bericht beschreibt die wachsende Bedrohung durch den Kult und die Ereignisse, die Shen'dar und seinen Pylon in Gefahr brachten. Die Friedensbewahrer vermieden einen direkten Konflikt, doch die rasche Ausbreitung des Kults macht einen Zusammenstoß unvermeidlich. Valanaar muss seine Verteidigung vorbereiten.",al={"warum bericht überbringen","was ist aondas bericht","was steht im brief"}},{q="Welche Gefahr stellt der Kult für die Insel dar?",a="Der Bericht warnt davor, dass sich ein unbenannter Kult rasch auf der Insel ausbreitet. Die Friedensbewahrer hielten Abstand, um einen offenen Krieg zu vermeiden, doch die jüngsten aggressiven Vorstöße des Kults gegen Orte wie Shen'dar machen einen Konflikt unausweichlich.",al={"welcher kult to valanaar","wer ist der kult","kult bedrohung insel"}},{q="Was geschieht, sobald Ihr Valanaar erreicht?",a="Wenn Valennia die düsteren Nachrichten erhält, muss sie sich mit ihren verbliebenen Friedensbewahrern beraten und eine Verteidigung gegen künftige Angriffe des Kults planen. Während sie ihre Pläne abstimmt, lädt sie Reisende ein, den Bewohnern rund um Valanaar zu helfen.",al={"was nach berichtsübergabe tun","was nach to valanaar"}}},fp="11,206,18.368.0,19.279.1,26.207.0,26.191.0,17.167.0,38.241.0,45.248.0,37.226.0"}
P.entries["quest:92595"] = {n="The Windshapers",s="Unter den Windgeistern suchen die Windformer einen Weg, Zephras und die Shen'dorei am Leben zu erhalten. Illaya Amberwind heißt neue Rekruten für ihre Arbeit willkommen, während sich im Himmelswall Gefahren zusammenbrauen.",h="Unter den Windgeistern suchen die Windformer einen Weg, Zephras und die Shen'dorei am Leben zu erhalten.",kw={"al'aketh","illaya amberwind","shen'dorei","skysight","der himmelswall","windformer","zephras"},ang={["class:Shaman"]="Als Schamane könnt Ihr durch Eure Ausbildung mit den Elementen Zwiesprache halten, doch skysight kann auch bei anderen auftreten. Die Windformer teilen diese spirituelle Pflicht mit jenen, die die Elemente anrufen.",["race:Skyborne"]="Als Skyborne wisst Ihr, dass die Windformer inmitten der Gefahren des Himmelswalls und von Zephras um das Überleben und die Heimat der Shen'dorei kämpfen."},sec={{t="Auftrag der Windformer",b="Illaya Amberwind heißt neue Rekruten bei den Windformern willkommen, die mit den Windgeistern Zwiesprache halten und die Shen'dorei beschützen. Der Orden sucht jene mit angeborener spiritueller Wahrnehmung. Sie hoffen, die wachsende Kluft zwischen ihrem Volk und den Elementarkräften zu schließen, die ihr Luftreich erhalten. Jeder Windformer trägt diese Bürde."},{t="Prüfungen auf Zephras",b="Die Al'Aketh stiften Unruhe im Himmelswall, und die Elementarebene birgt ihre eigenen Gefahren. Die Windformer glauben, dass Zephras nur bestehen und die Shen'dorei den Sturm nur überstehen können, wenn sie ihre Verbindung zu den Geistern der Winde wiederherstellen."}},faq={{q="Wer sind die Windformer?",a="Die Windformer halten Zwiesprache mit den Windgeistern und beschützen die Shen'dorei. Unter Illaya Amberwinds Führung suchen sie Menschen mit der Gabe skysight, um ihre Verbindung zu den Geistern wiederherzustellen und ihre bedrohte Heimat zu bewahren.",al={"wer sind die windformer","windformer fraktion","was tun die windformer"}},{q="Was ist skysight?",a="Skysight ist eine angeborene spirituelle Empfänglichkeit, die es einer Person ermöglicht, sich mit den Elementen der Luft zu verbinden. Eine förmliche Schamanenausbildung ist nicht nötig, doch die Beherrschung von skysight ist unerlässlich, um die Geister der Winde zu erreichen.",al={"was ist skysight","skysight hintergrundgeschichte"}},{q="Wer ist Illaya Amberwind?",a="Illaya Amberwind führt die Windformer und erkennt spirituelle Gaben in Reisenden. Sie heißt jene mit skysight willkommen und erklärt die Arbeit des Ordens, die Gefahr für Zephras und die Prüfungen, denen sich die Shen'dorei stellen müssen.",al={"wer ist illaya","illaya amberwind"}},{q="Was ist Zephras?",a="Zephras ist ein Land oder eine Siedlung in den Lüften, die schwere Entbehrungen und innere Unruhen durchleidet. Die Windformer kämpfen darum, Zephras zu beschützen und ihrem Volk dort eine Zukunft zu bewahren.",al={"was ist zephras","zephras hintergrundgeschichte"}},{q="Wer sind die Al'Aketh?",a="Die Al'Aketh sind eine feindselige Fraktion im Inneren, die den Windformern und den Shen'dorei zusetzt. Ihre Bedrohung verschärft die Gefahren des Überlebens im Himmelswall.",al={"wer sind die al'aketh","alaketh bedrohung"}},{q="Wer sind die Shen'dorei?",a="Die Shen'dorei sind das Volk, das die Windformer zu beschützen suchen. Die Al'Aketh und die gefährlichen Bedingungen im Himmelswall bedrohen ihr Überleben, weshalb die Windformer es durch die Wiederherstellung des Gleichgewichts mit den Winden sichern wollen.",al={"wer sind die shendorei","shen'dorei hintergrundgeschichte"}}},fp="15,176,26.326.0,17.239.0,24.217.0,17.209.0,24.217.0,16.171.0,21.150.0,23.209.0"}
P.entries["quest:92596"] = {n="The High Order",s="Auf Zephras erklärt Rathiril Sunlance Neuankömmlingen, warum die Shen'dorei nun auf sich allein gestellt sind. Ihre elementaren Wohltäter sind fort, also wenden sich diese Nachfahren der Hochgeborenen von Eldre'Thalas uralter Arkanmagie zu, um ihr Volk zu schützen.",h="Auf Zephras erklärt Rathiril Sunlance Neuankömmlingen, warum die Shen'dorei nun auf sich allein gestellt sind.",kw={"al'aketh","arkan","eldre'thalas","hochgeborene","rathiril sunlance","shen'dorei","der hohe orden","zephras"},ang={["class:Mage"]="Rathiril sagt, dass selbst Abenteurer ohne förmliche Magierausbildung starke arkane Auren in sich tragen. Ihre gemeinsame Magie ist ein angeborenes Erbe, nicht nur eine erlernte Disziplin.",["race:Skyborne"]="Als Skyborne stammt Ihr von den uralten Hochgeborenen von Eldre'Thalas ab. Ihr müsst Eure arkanen Gaben meistern, um auf eigenen Füßen zu stehen, da Eure elementaren Schutzherren nun fort sind."},sec={{t="Ein Volk auf sich gestellt",b="Die Shen'dorei auf Zephras arbeiten daran, ihre Stärke zurückzuerlangen und ihren eigenen Weg zu wählen. Lange Zeit beschützten elementare Wohltäter sie. Nun sind diese Schutzherren fort, und das Volk ist inneren Unruhen und Gefahren aus seiner Umgebung ausgesetzt. Rathiril Sunlance sucht nach arkanbegabten Personen, die helfen, ihr Volk zu bewahren und aus eigener Kraft stärker zu werden."},{t="Das Erbe von Eldre'Thalas",b="Die Shen'dorei tragen das Erbe von Eldre'Thalas und einen angeborenen Quell arkaner Energie in sich. Selbst jene, die nie förmlich in der Zauberei ausgebildet wurden, besitzen diese Macht. Der Hohe Orden sieht es als Bestimmung der Nachfahren der Hochgeborenen an, diese uralten Gaben zu nutzen. Mit ihnen hoffen die Shen'dorei, den Al'Aketh in ihren eigenen Reihen zu widerstehen und den vielen Bedrohungen ihrer Heimat auf Zephras zu begegnen."}},faq={{q="Was ist der Hohe Orden?",a="Unter den Shen'dorei auf Zephras setzt sich der Hohe Orden für das Überleben ihres Volkes ein. Gegründet von Nachfahren der Hochgeborenen von Eldre'Thalas, will er ihre uralten arkanen Gaben nutzen, damit ihre Gesellschaft sich verteidigen und eigenständig fortbestehen kann.",al={"wer ist der hohe orden","was ist der hohe orden","zweck des hohen ordens"}},{q="Wer ist Rathiril Sunlance?",a="Rathiril Sunlance ist ein Elf, der mit dem Hohen Orden auf Zephras verbunden ist. Er unterrichtet Neuankömmlinge über die örtlichen arkanen Energien, die Notlage der Shen'dorei und ihren Entschluss, ohne ihre früheren elementaren Schutzherren zu überleben.",al={"wer ist rathiril","rathiril sunlance hintergrund","sunlance"}},{q="Was ist Zephras?",a="Zephras ist eine schwebende Insel im Himmelswall, auf der Rathiril Sunlance und die Seinen heute leben. Arkane Energien erfüllen die Insel, und die Shen'dorei stehen Gefahren innerhalb ihres Volkes und der Ungewissheit gegenüber, wie sicher sie vor äußeren Bedrohungen sind.",al={"wo ist der hohe orden","was ist zephras","zephras hintergrund"}},{q="Wer sind die Shen'dorei?",a="Die Shen'dorei sind elfische Nachfahren der Hochgeborenen aus Eldre'Thalas. Sie leben heute auf Zephras, haben eine angeborene Verbindung zur Arkanmagie und streben danach, auf eigenen Füßen zu stehen.",al={"wer sind die shendorei","shen dorei","shendorei hintergrund"}},{q="Wer waren die elementaren Wohltäter?",a="Die elementaren Wohltäter waren mächtige Elementarwesen, die den Shen'dorei einst halfen und sie beschützten. Sie sind fort, also muss sich das Volk von Zephras auf seine eigene Magie und seinen Einfallsreichtum verlassen.",al={"wer sind die elementare","elementare schutzherren","elementare wohltäter"}},{q="Was sind die Al'Aketh?",a="Die Al'Aketh sind eine innere Fraktion oder Bedrohung, die die Shen'dorei auf Zephras gefährdet. Der Hohe Orden organisiert die Verteidigung unter anderem, um solchen Bedrohungen von innen zu begegnen.",al={"was ist alaketh","al aketh bedrohung","innere bedrohungen zephras"}},{q="Welche Verbindung besteht zwischen dem Hohen Orden und Eldre'Thalas?",a="Die Vorfahren der Shen'dorei kamen aus Eldre'Thalas, der uralten Stadt der Hochgeborenen in Kalimdor, die vielen in den Jahren nach dem Dritten Krieg als Düsterbruch bekannt war. Der Hohe Orden ehrt dieses Erbe, indem er ihre uralten arkanen Gaben bewahrt und nutzt.",al={"eldrethalas verbindung","stammen sie aus düsterbruch","ursprünge der hochgeborenen"}}},fp="14,225,21.364.0,22.360.0,23.242.0,25.214.0,16.225.0,23.168.0,35.191.0,22.164.0,63.241.0"}
P.entries["quest:92597"] = {n="Reading the Ley Lines",s="Auf der Insel Zephras suchen junge Skyborne nach den arkanen Strömungen unter ihren Füßen. Falorne Fallwind schickt sie in den Thendalhain, um die Macht zu spüren, die durch die Elementarebene aufsteigt.",h="Auf der Insel Zephras suchen junge Skyborne nach den arkanen Strömungen unter ihren Füßen.",kw={"al'aketh","falorne fallwind","hochgeborene","kraftlinien","reading the ley lines","skyborne","thendalhain","die menhire von thendal","windformer","insel zephras"},ang={["class:Mage"]="Als Magier könnt Ihr freiliegende Kraftlinien inmitten elementarer Stürme als Quelle roher Macht nutzen.",["race:Skyborne"]="Als Skyborne erweckt Ihr Euer angeborenes Erbe der Hochgeborenen und lernt, unterirdische Kraftlinienenergie in Eure Zauber zu leiten."},sec={{t="Arkane Strömungen der Elementarebene",b="Unter der Insel Zephras verlaufen Kraftlinien, selbst durch die Elementarebene. Seltsame Elementare und die feindseligen Al'Aketh durchstreifen die Insel, während diese verborgenen Strömungen zur Oberfläche aufsteigen. Wer die nötige Abstammung und das Wissen besitzt, sie zu kanalisieren, findet durch die freiliegenden Linien Zugang zu roher arkaner Macht."},{t="Das Erbe der Hochgeborenen",b="Falorne Fallwind drängt die Initianden, ihr Erbe der Hochgeborenen anzunehmen, statt die Gunst von Windgeistern zu suchen. Die örtlichen Windformer und die Al'Aketh wenden sich gleichermaßen an solche Geister. Fallwind glaubt, das Überleben inmitten der rauen Mächte der Elementarebene hänge davon ab, die arkane Kraft unter der Erde zu meistern, statt fremde Kreaturen um Gnade zu bitten."},{t="Die Menhire von Thendal",b="Nordöstlich der Siedlung markieren die uralten Menhire im Thendalhain einen mächtigen Schnittpunkt von Kraftlinien. Tosende Winde und Al'Aketh-Konvertiten umgeben diesen ungeschützten Ort. Dort können Initianden ihre Sinne auf den Puls der Kraftlinie einstimmen und das volle Potenzial ihrer natürlichen Volksfähigkeiten entfesseln."}},faq={{q="Wer vergibt die Quest Reading the Ley Lines?",a="Falorne Fallwind auf der Insel Zephras überträgt jungen Skyborne diesen Ritus, während sie lernen, ihre angestammte arkane Macht zu kanalisieren.",al={"questgeber","falorne fallwind","wer startet reading the ley lines"}},{q="Wo befindet sich die Kraftlinie?",a="Die Kraftlinie liegt nordöstlich der Siedlung, bei den Menhiren von Thendal im Thendalhain, inmitten feindseliger Elementare und Al'Aketh-Konvertiten.",al={"kraftlinie fundort","wo liegt der thendalhain","menhire von thendal fundort"}},{q="Warum gibt es Kraftlinien in der Elementarebene?",a="Selbst in der Elementarebene verlaufen arkane Kanäle unter der Erde. Die Kraftlinien haben begonnen, die Oberfläche zu durchbrechen, und gewähren den Skyborne direkten Zugang zu mächtigen Strömungen.",al={"arkane magie in der elementarebene","kraftlinien elementarebene hintergrund"}},{q="Wie steht Falorne Fallwind zu den Windformern?",a="Falorne verachtet die Verehrung der Luftgeister durch die Windformer. Er sieht darin schwaches Flehen zu gleichgültigen Elementarwesen, keinen Deut besser als die Anbetung der Al'Aketh.",al={"falorne über windformer","windformer hintergrund","windformer gegen hochgeborene"}},{q="Welche Fähigkeit wird benötigt, um die Kraftlinie zu kanalisieren?",a="Ihr setzt die Volksfähigkeit der Skyborne Read Ley Line ein, während Ihr am Energieschnittpunkt bei den Menhiren steht.",al={"read ley line fähigkeit","wie wird read ley line eingesetzt","verwendete volksfähigkeit"}},{q="Welchen Nutzen bringt das Anzapfen von Kraftlinien?",a="Das Anzapfen einer freiliegenden Kraftlinie leitet rohe arkane Energie in den Anwender und steigert seine magischen Kräfte. Die Auswirkungen unterscheiden sich je nach Beschaffenheit des Kanals.",al={"was bewirken kraftlinien","vorteile von kraftlinien"}}},fx={e5a629f0={q="Warum möchte Falorne Fallwind, dass Ihr die Leylinien lest?",a="Falorne glaubt, dass die Rückbesinnung auf Euer Erbe der Hochgeborenen und das direkte Anzapfen der arkanen Leylinien der einzige Weg zur Rettung Eures Volkes in der Elementarebene ist. Er betrachtet Gruppen wie die Windformer und die Al'Aketh mit Verachtung, da sie sich vor gleichgültigen elementaren Wesenheiten erniedrigen. In seinen Augen erfordert das Überleben das Meistern verborgener Magie, anstatt sich auf launische Geister zu verlassen.",al={"falorne fallwinds beweggrund","warum leylinien lesen","falorne fallwind leylinien warum"}}},fp="21,171,38.291.0,16.349.0,23.302.0,42.118.0,30.142.0,49.174.0,47.161.0,49.114.0,49.147.0"}
P.entries["quest:92598"] = {n="The Gift of Skysight",s="Auf der Insel Zephras führt Ventaari Brightwish junge Windformer an die Himmelssicht heran. An einer Elementarkonvergenz erwecken sie ihre Wahrnehmung und lauschen den Geistern.",h="Auf der Insel Zephras führt Ventaari Brightwish junge Windformer an die Himmelssicht heran.",kw={"elementarkonvergenz","elementargeister","himmelssicht","hinkelsteine","thendalhain","ventaari brightwish","windformer","zephras"},ang={["class:Shaman"]="Als Schamane kennt Ihr eine Elementarkonvergenz als heiligen Boden, an dem die Grenze zwischen sterblichem Willen und den Elementarebenen dünner wird.",["faction:Horde"]="Als Mitglied der Horde verlasst Ihr Euch auf die Voraussicht der Windformer, um den unerforschten Gefahren der Insel Zephras zu begegnen.",["race:Skyborne"]="Als Skyborne erbt Ihr die Himmelssicht von elementaren Schutzpatronen. Sie verankert Eure kulturelle und spirituelle Identität."},sec={{t="Eine heilige Wahrnehmung",b="Windformer werden mit einem Band zu den elementaren Kräften geboren, die ihre Welt formen. Die heilige Fähigkeit dieses Bandes nennen sie Himmelssicht. Diese Gabe stimmt die Sinne der Sterblichen auf das Reich der Geister ein und überbrückt die Kluft zwischen den Lebenden und dem Unsichtbaren. In der Wildnis kann ein Windformer diese innere Sicht hervorrufen. Nahe konzentrierter Macht wird das Band stärker und bringt Segnungen und Weisheit, die von den Geistern zugeflüstert wird."},{t="Die Konvergenz im Thendalhain",b="Nordöstlich der Siedlung markieren uralte Hinkelsteine eine Elementarkonvergenz im Thendalhain. An solchen Orten sammeln sich rohe Energien, und Geister verweilen dort. Ventaari Brightwish schickt Novizen dorthin, um ihre spirituelle Stärke auf die Probe zu stellen. Die Himmelssicht wächst mit der Übung, wie eine Fähigkeit des Körpers oder Geistes. Windformer müssen lernen, die wechselnden Vorzeichen der Elemente zu deuten, denn das Überleben ihres Volkes hängt davon ab."}},faq={{q="Welchen Zweck hat diese Quest?",a="Ventaari Brightwish schickt angehende Windformer zu einer Elementarkonvergenz, deren Macht ihre Himmelssicht schärft.",al={"gabe der himmelssicht zweck","warum diese quest machen","himmelssicht üben"}},{q="Wer ist Ventaari Brightwish?",a="Ventaari Brightwish leitet und unterweist junge Windformer auf der Insel Zephras und lehrt sie, ihr elementares Erbe zu ehren und zu verfeinern.",al={"ventaari","wer ist ventaari brightwish","brightwish"}},{q="Was ist eine Elementarkonvergenz?",a="Eine Elementarkonvergenz sammelt spirituelle Energie, oft um uralte Hinkelsteine herum. Elementargeister verweilen dort, und Kräfte wie die Himmelssicht werden stärker.",al={"was ist eine elementarkonvergenz","elementarkonvergenz hintergrund","thendalhain konvergenz"}},{q="Wo liegt die Elementarkonvergenz?",a="Die Elementarkonvergenz liegt zwischen den Hinkelsteinen im Thendalhain, nordöstlich der Siedlung auf der Insel Zephras.",al={"wo ist die konvergenz","thendalhain lage","hinkelsteine standort"}},{q="Kann die Himmelssicht überall eingesetzt werden?",a="Ein Windformer kann die Himmelssicht überall hervorrufen. An einer Elementarkonvergenz vertieft sich ihre Kraft, und Geister in der Nähe können weitere Einsichten gewähren.",al={"himmelssicht überall einsetzbar","himmelssicht außerhalb der konvergenz","wo himmelssicht einsetzen"}},{q="Warum gilt die Himmelssicht als überlebenswichtig?",a="Die Himmelssicht lässt Sterbliche Elementargeister wahrnehmen und die Warnungen der Elemente beachten. Ventaari sagt, diese Sicht sei unerlässlich, um Gefahren zu begegnen und ihr Volk zu bewahren.",al={"warum ist himmelssicht wichtig","himmelssicht überleben","elemente überleben"}}},fx={d2ee972c={q="Warum möchte Ventaari Brightwish, dass Ihr Skysight an der Konvergenz einsetzt?",a="Ventaari Brightwish möchte Euch in Eurem angeborenen Erbe als Windformer ausbilden. Wie ein Muskel muss Skysight an Orten der Macht wie der Elementarkonvergenz trainiert werden, damit Ihr lernt, die Distanz zwischen der sterblichen und der spirituellen Welt zu überbrücken. Sie glaubt, dass die Kommunikation mit den Geistern und das Achten darauf, was die Elemente Eurem Volk mitteilen, entscheidend für Euer Überleben ist.",al={"warum will ventaari das","ventaari brightwishs beweggrund","warum hier skysight nutzen"}}},fp="20,163,19.399.0,32.398.0,34.114.0,27.131.0,33.163.0,43.119.0,30.136.0,50.163.0"}
P.entries["quest:926"] = {n="Fehlerhafter Kraftstein",s="Überall im Brachland ruhen fehlerhafte Steine voller arkaner Energie auf Ritualtischen. Ihre Schöpfer ließen sie instabil, und kurz nachdem sie bewegt werden, zehren sie ihre Kraft auf.",h="Überall im Brachland ruhen fehlerhafte Steine voller arkaner Energie auf Ritualtischen.",kw={"arkan","brachland","fehlerhafter kraftstein","kraftsteine","ritualtisch","instabile magie"},ang={["faction:Horde"]="Als Mitglied der Horde wacht Ihr über arkane Merkwürdigkeiten, die über das Brachland verstreut sind. Die Zauberei von Schurken könnte Eure Versorgungswege bedrohen."},sec={{t="Instabiles Handwerk",b="Überall im Brachland bergen fehlerhafte Kraftsteine arkane Essenz in beschädigten Strukturen. Ihre Schöpfer ließen sie instabil, sodass sie wenige Augenblicke nach einer Berührung zu inerter Materie zerfallen."},{t="Selbstzehrende Energie",b="Ein Stein beginnt seine Kraft aufzuzehren, sobald er den Ritualtisch verlässt, auf dem er ruht. Seine Energie verbrennt zu schnell, als dass jemand ihn weit tragen könnte."}},faq={{q="Was ist ein Fehlerhafter Kraftstein?",a="Der Stein birgt rohe magische Kraft, doch seine absichtlichen Fehler lassen ihn sich rasch selbst verzehren, sobald er bewegt wird.",al={"fehlerhafter kraftstein","was ist dieser stein","geschichte des kraftsteins"}},{q="Können die Steine dauerhaft bewahrt werden?",a="Nein. Sobald sie von den Tischen getrennt werden, die sie stabilisieren, brechen die magischen Matrizen der Steine zusammen und ihre Energie versiegt rasch.",al={"fehlerhaften stein behalten","kann er gelagert werden","stein bewahren"}},{q="Wer verwendet diese Steine?",a="Der Orc Ak'Zeloth bereitet die Steine vor, und Abenteurer der Horde tragen sie zum Altar des Feuers auf dem Glutnebelgipfel. Dort stören sie die Verbindung des Demon Seed zur Brennenden Legion.",al={"wer erschuf die kraftsteine","wer fertigte sie","schöpfer der steine"}},{q="Warum interessiert sich die Horde für sie?",a="Die Horde setzt die Steine gegen die Brennende Legion ein. Ak'Zeloth bereitete sie für Neeru Feuerklinge vor, sodass ein Stein am Altar des Feuers auf dem Glutnebelgipfel die Verbindung des Demon Seed zur Legion brechen kann.",al={"interesse der horde","warum will die horde das"}}},fp="18,171,22.187.0,21.150.0,29.102.0,40.128.0,22.182.0,35.206.0"}
P.entries["quest:9260"] = {n="Erforscht die Geißel von Sturmwind",s="Leutnant Orrin ruft Sturmwinds Verteidiger auf, die gegen die Stadt vorrückenden Streitkräfte der Geißel zurückzudrängen. Nekropolen ragen jenseits ihrer Mauern auf, und er bittet die Verteidiger, Necrotic Stones zu sammeln und die Runen rund um feindliche Lager zu untersuchen.",h="Leutnant Orrin ruft Sturmwinds Verteidiger auf, die gegen die Stadt vorrückenden Streitkräfte der Geißel...",kw={"argentumdämmerung","invasion","lich king","leutnant orrin","nekropole","necrotic stones","runenkreise","geißel","sturmwind"},ang={["class:Paladin"]="Als Paladin stellt Ihr Euch der Geißel vor Sturmwind. Ihr könnt heiligen Zorn gegen ihre Runen richten und die Menschen des Königreichs beschützen.",["class:Priest"]="Als Priester könnt Ihr das verzerrte Flüstern in den Runen untersuchen und mehr über die Shadow Magic erfahren, die die Fronttruppen der Geißel verbindet.",["faction:Alliance"]="Für die Allianz geht es bei der Verteidigung von Sturmwinds Toren ums Überleben. Die Geißel hat selbst diese südliche Festung erreicht."},sec={{t="Untote vor der Hauptstadt",b="Streitkräfte der Geißel haben die Außenbezirke von Sturmwind erreicht. Nekropolen schweben am Himmel, während Untote und Kultisten nahe der größten Bastion des Königreichs Fuß fassen. Leutnant Orrin versammelt Verteidiger außerhalb der Stadt, um die Feinde zurückzudrängen, bevor sie die Hauptstadt bedrohen."},{t="Die flüsternden Runen",b="Leuchtende Runen zeichnen sich im Erdreich rund um die Lager der Geißel ab, doch ihr Zweck bleibt unklar. Die Kreise knistern vor Magie, die jener der Nekropolen gleicht, und tragen ein unheimliches Flüstern in sich. Leutnant Orrin kann nur vermuten, wer diese unnatürlichen Stimmen hört, wenn überhaupt jemand."}},faq={{q="Wer ist Leutnant Orrin?",a="Leutnant Orrin ist ein Offizier, der Sturmwinds Verteidigung koordiniert. Er arbeitet mit der Argentumdämmerung zusammen und organisiert örtliche Kämpfer, um Informationen zu sammeln und Stützpunkte der Geißel nahe der Stadt zu zerschlagen.",al={"orrin","leutnant orrin","wer vergibt diese quest"}},{q="Warum greift die Geißel Sturmwind an?",a="Der Lich King hat Nekropolen und Invasionstruppen durch ganz Azeroth entsandt, um Schrecken zu verbreiten und die Reihen der Untoten zu vergrößern. Sturmwind ist eine bedeutende Festung der Lebenden, weshalb die Geißel die Stadt zum Ziel gemacht hat.",al={"warum geißel hier","invasion der geißel in sturmwind","warum sturmwind angreifen"}},{q="Was sind die leuchtenden Runenkreise?",a="Die Geißel hat leuchtende Runenkreise nahe ihren Lagern angelegt. Sie pulsieren vor dunkler Magie und tragen unnatürliches Flüstern in sich, doch ihr Zweck bleibt unbekannt.",al={"runenkreise","leuchtende runen","was bewirken die kreise"}},{q="Was sind Dim Necrotic Stones?",a="Dim Necrotic Stones sind magische Gegenstände, die niedere Streitkräfte der Geißel bei sich tragen. In ihnen haftet nekrotische Energie, und sie sind für die Argentumdämmerung von Interesse.",al={"dunkler nekrotischer stein","necrotic stones","was sind necrotic stones"}},{q="Welche Rolle spielt die Argentumdämmerung bei dieser Mission?",a="Die Argentumdämmerung ist ein unabhängiger Orden, der die Geißel bekämpft, wo immer sie auftaucht. Leutnant Orrin arbeitet mit dem Orden zusammen, um Informationen und Steine für dessen Krieg gegen die Armeen des Lich King zu beschaffen.",al={"argentumdämmerung","verbindung zur argentumdämmerung"}},{q="Ist es gefährlich, sich den Runenkreisen zu nähern?",a="Die Kreise verströmen beunruhigende Energie und misstönendes Flüstern. Vorsichtige Späher können sich ihnen nähern und etwas über die Verständigung der Geißel erfahren, ohne den Verstand zu verlieren.",al={"sind die runen sicher","flüstern in den runen"}}},fx={c2a78be7={q="Warum möchte Leutnant Orrin, dass dies untersucht wird?",a="Die Geißel hat ihre untoten Streitkräfte direkt vor den Toren von Sturmwind unter einer unheilvoll schwebenden Nekropole entfesselt. Leutnant Orrin weiß, dass die Stadt es sich nicht leisten kann, untätig zuzusehen, während sich Invasoren vor der Haustür versammeln. Er muss dringend die seltsame Magie hinter ihren leuchtenden Runenkreisen verstehen und ihre Reihen lichten, bevor die Untoten direkt vor den Mauern des Königreichs dauerhaft Fuß fassen.",al={"warum will orrin das erledigt haben","leutnant orrins beweggrund","warum die geißel untersuchen"}},["9cb0511c"]={q="Gegen wen werdet Ihr außerhalb von Sturmwind in den Kampf geschickt?",a="Ihr kämpft gegen die einfallenden Streitkräfte der Geißel, die sich unter der Nekropole direkt vor der Stadt versammelt haben. Diese untoten Sturmtruppen und Abscheulichkeiten haben ein Lager vor den Toren von Sturmwind errichtet, um im Namen des Lichkönigs Chaos zu säen und das Königreich zu bedrohen.",al={"gegen wen kämpfe ich","wer sind die feinde vor sturmwind","welche geißel ist draußen"}}},fp="36,219,33.265.0,20.249.0,24.195.0,39.206.0,35.155.0,29.139.0,52.202.0,44.164.0"}
P.entries["quest:9261"] = {n="Erforscht die Geißel von Eisenschmiede",s="Die Geißel bedrängt Eisenschmiedes Tore, und Leutnant Nevell ruft Verteidiger herbei. Untote Truppen sammeln sich unter einer schwebenden Nekropole, während leuchtende Runenkreise ihre Lager markieren.",h="Die Geißel bedrängt Eisenschmiedes Tore, und Leutnant Nevell ruft Verteidiger herbei.",kw={"argentumdämmerung","dunkler nekrotischer stein","dun morogh","erforscht die geißel von eisenschmiede","eisenschmiede","lich king","leutnant nevell","nekropole","runenkreis","geißel"},ang={["class:Paladin"]="Als Paladin stellt Ihr Euch der Geißel entgegen, den Feinden des Heiligen Lichts. Ihr seid aufgerufen, die bösartige Runenmagie des Lich King zu untersuchen und seine willenlosen Diener zu vernichten.",["class:Priest"]="Als Priester wisst Ihr, dass das Flüstern in den Runenkreisen den Verstand gewöhnlicher Soldaten bedrohen könnte. Ihm zu widerstehen erfordert geistige Stärke.",["faction:Alliance"]="Als Soldat der Allianz wisst Ihr, dass Eisenschmiede eine wichtige Stütze für Handel und Krieg ist. Ein Stützpunkt der Untoten vor seinen Toren bedroht die Versorgungswege in den gesamten Östlichen Königreichen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Fäulnis, die sich über Dun Moroghs reinen Schnee ausbreitet, ein Frevel ist. Der Bergeingang ist die Schwelle Eurer Heimat."},sec={{t="Tod an den Bergtoren",b="Leutnant Nevell und die Argentumdämmerung beobachten die Untoten am Bergeingang von Eisenschmiede. Nekropolen schweben über Dun Moroghs eisigen Höhen, fern von Lordaeron und den Plagued Lands des Nordens. Sie wollen die Geißel aufhalten, bevor sie die Festung der Bronzebärte erreicht."},{t="Unheilige Inschriften",b="Unter der Nekropole liegen Lager der Untoten. Leuchtende Runenkreise und pulsierende nekrotische Steine markieren den Boden, und Späher nahe den Kreisen hören dunkle Stimmen in der umgebenden Magie. Leutnant Nevell glaubt, dass die Kreise Botschaften übermitteln, weiß jedoch nicht, mit wem die Geißel Kontakt aufnimmt."}},faq={{q="Wer ist Leutnant Nevell?",a="Leutnant Nevell ist ein Offizier der Argentumdämmerung, der in Eisenschmiede stationiert ist, um die Verteidigung gegen die Geißel zu koordinieren. Er bittet Verteidiger, nekrotische Steine zu sammeln und den Zweck der unheiligen Siegel rund um die Lager der Eindringlinge zu ergründen.",al={"nevell","leutnant nevell","questgeber"}},{q="Warum greift die Geißel Eisenschmiede an?",a="Truppen der Geißel lagern unter einer Nekropole vor Eisenschmiede. Leutnant Nevell bittet Verteidiger, ihre Reihen zu lichten und die seltsamen Runenkreise in der Nähe zu untersuchen.",al={"geißel vor eisenschmiede","warum untote in dun morogh","invasion von eisenschmiede"}},{q="Was sind Dunkle nekrotische Steine?",a="Dunkle nekrotische Steine werden den Eindringlingen der Geißel abgenommen und als Beweis für erschlagene Untote zur Argentumdämmerung gebracht.",al={"nekrotische steine","dunkler nekrotischer stein","geißelsteine"}},{q="Welchen Zweck haben die leuchtenden Runenkreise?",a="Die leuchtenden Runenkreise erscheinen in der Nähe von Truppen der Geißel. Leutnant Nevell bittet Euch, ihren Zweck zu untersuchen.",al={"runenkreise","leuchtende kreise","was sind die runen"}}},fx={["4916b51d"]={q="Warum möchte Leutnant Nevell, dass dies untersucht wird?",a="Da die Geißel vor den Toren von Eisenschmiede marschiert und eine Nekropole drohend über ihnen schwebt, weigern sich Leutnant Nevell und die Argentumdämmerung, untätig zu bleiben. Seltsame, mit unheiliger Magie leuchtende Runenkreise sind in der Nähe der untoten Lager vor den Toren aufgetaucht. Nevell weiß, dass diese Rituale eine düstere Bedeutung haben, und er braucht Euch, um aufzudecken, welche finsteren Mächte die Invasoren kanalisieren, bevor die Stadt einer noch größeren Katastrophe gegenübersteht.",al={"nevells beweggrund","warum geißel eisenschmiede untersuchen","warum will nevell das erledigt haben"}},f222933f={q="Gegen wen werdet Ihr geschickt, um außerhalb von Eisenschmiede zu kämpfen?",a="Ihr werdet gegen die Vorhut der Geißel geschickt, die direkt vor den Toren von Eisenschmiede lagert. Unter dem Befehl des Lichkönigs entsandt und von einer schwebenden Nekropole unterstützt, versuchen diese untoten Schrecken, Dun Morogh in Angst und Schrecken zu versetzen und das Zwergenkönigreich zu belagern.",al={"gegen wen kämpfen","geißel ziele eisenschmiede","gegen wen kämpfe ich"}}},fp="36,188,27.275.0,19.288.1,25.231.0,39.162.0,29.120.0,49.110.0"}
P.entries["quest:9262"] = {n="Erforscht die Geißel von Darnassus",s="In Darnassus ruft Leutnant Beitha um Hilfe, während Lager der Geißel bedrohlich nahe rücken. Die Argentumdämmerung braucht Verteidiger, die gegen die Untoten vorgehen und herausfinden, wozu die Runen vor den Toren dienen.",h="In Darnassus ruft Leutnant Beitha um Hilfe, während Lager der Geißel bedrohlich nahe rücken.",kw={"argentumdämmerung","beitha","darnassus","lich king","nekropole","nekrotischer stein","runenkreis","geißel","teldrassil","untoter"},ang={["class:Druid"]="Als Druide seht Ihr Nekromantie und verwesendes Fleisch auf Teldrassil als eine Verderbnis, die auszumerzen Ihr geschworen habt.",["class:Priest"]="Als Priester stellt Ihr Euch verderbten nekromantischen Runen und dem Flüstern, das durch das dunkle Netzwerk der Geißel dringt.",["faction:Alliance"]="Als Mitglied der Allianz beteiligt Ihr Euch an der Verteidigung von Darnassus gegen die Invasionsstreitmacht des Lich King.",["race:NightElf"]="Als Kaldorei seht Ihr die Nekropolen und Untoten nahe dem heiligen Boden Teldrassils als eine Entweihung, die getilgt werden muss."},sec={{t="Eine Seuche am Weltbaum",b="Die Geißel hat Teldrassil erreicht. Schwebende Nekropolen ragen über Invasionslagern nahe Darnassus auf, und Ghule, Skelette und andere untote Schrecken strömen aus ihnen hervor. Leutnant Beitha von der Argentumdämmerung koordiniert die Verteidigung der Stadt. Sie ruft Freiwillige auf, den Angriff zu verlangsamen und Informationen zu sammeln, bevor die Untoten die Heimat der Nachtelfen überrennen."},{t="Flüstern in den Runen",b="Nahe den Lagern der Geißel bittet Leutnant Beitha die Verteidiger, Dunkle nekrotische Steine von erschlagenen Geißelanhängern zu sammeln und die leuchtenden Runenkreise am Boden zu untersuchen. Ihr Flüstern erreicht jeden, der sich ihnen nähert. Die Kreise übermitteln Botschaften, doch Beitha weiß nicht, mit wem die Geißel Kontakt aufnimmt."}},faq={{q="Wer ist Leutnant Beitha?",a="Leutnant Beitha ist eine in Darnassus stationierte Offizierin der Argentumdämmerung. Sie organisiert den Widerstand gegen die Geißel und bittet die Verteidiger, deren Reihen zu lichten und ihre nekromantischen Vorrichtungen zu untersuchen.",al={"wer vergibt erforscht die geißel von darnassus","beitha questgeberin","leutnant beitha hintergrundgeschichte"}},{q="Warum greift die Geißel Darnassus an?",a="Truppen der Geißel lagern vor Darnassus unter einer Nekropole. Leutnant Beitha bittet die Verteidiger, deren Reihen zu lichten und nahe gelegene Runenkreise zu untersuchen.",al={"warum sind untote in darnassus","invasion von teldrassil","lich king greift nachtelfen an"}},{q="Was sind die leuchtenden Runenkreise vor der Stadt?",a="Die leuchtenden Runenkreise liegen nahe den Truppen der Geißel. Leutnant Beitha bittet Euch, ihren Zweck zu ergründen.",al={"runen der geißel darnassus","runenkreise vor darnassus","was sind die invasionsrunen"}},{q="Was sind Dunkle nekrotische Steine?",a="Dunkle nekrotische Steine stammen von den Invasoren der Geißel. Die Verteidiger bringen sie der Argentumdämmerung als Beweis für erschlagene Untote.",al={"nekrotische steine","was bewirken nekrotische steine","dunkler nekrotischer stein hintergrundgeschichte"}},{q="Wer finanziert oder leitet die Gegenwehr in Darnassus?",a="Die Argentumdämmerung koordiniert die Untersuchung durch Leutnant Beitha. Der Orden hat sich dem Kampf gegen die Geißel verschrieben.",al={"wer leitet die verteidigung von darnassus","argentumdämmerung darnassus"}},{q="Kann es Euch schaden, den Runenkreisen zu lauschen?",a="Niemand kennt ihre genauen Auswirkungen. Beitha bittet die Verteidiger, die seltsame Energie rund um die Kreise zu untersuchen.",al={"runenkreise flüstern","runenkreis stimmen gefahr"}}},fx={["39b377fd"]={q="Warum möchte Leutnant Beitha, dass dies erledigt wird?",a="Der Lichkönig hat eine untote Invasion direkt vor die Tore von Teldrassil geschickt, verankert durch eine drohende Nekropole über Darnassus. Leutnant Beitha und die Argentumdämmerung weigern sich, untätig zuzusehen, während sich Abscheulichkeiten vor den Stadttoren versammeln. Sie braucht Euch, um ihre Reihen zu lichten, den Druck auf die Hauptstadt zu verringern, Beweise für ihre Vernichtung zu erbringen und den dunklen Zweck der leuchtenden Runenkreise aufzudecken, die ihr Lager stärken.",al={"beithas beweggrund","warum die geißel untersuchen","warum braucht beitha das erledigt"}},a5f671f0={q="Gegen wen werdet Ihr geschickt, um außerhalb von Darnassus zu kämpfen?",a="Ihr werdet gegen die einfallenden Streitkräfte der Geißel ausgesandt, die ein Lager direkt außerhalb von Darnassus aufgeschlagen haben. Diese untoten Sklaven und Abscheulichkeiten wurden direkt vom Lichkönig unter dem Schatten einer schwebenden Nekropole eingesetzt, um einen Stützpunkt zu errichten und die Hauptstadt der Nachtelfen zu bedrohen.",al={"gegen wen kämpfe ich","was ist die geißel außerhalb von darnassus","wer sind die invasoren"}}},fp="36,187,26.352.0,21.290.1,25.185.0,39.160.0,52.111.0,29.113.0,52.118.0,44.109.0"}
P.entries["quest:9263"] = {n="Erforscht die Geißel von Orgrimmar",s="Vor Orgrimmar setzt die Geißel ihren Angriff unter einer schwebenden Nekropole fort. Lieutenant Dagel ruft Verteidiger dazu auf, die Untoten abzuwehren, nekrotische Steine zu bergen und mit nekromantischer Energie geladene Runenkreise zu untersuchen. Der Angriff bringt den Einfluss des Lichkönigs bis nach Durotar.",h="Vor Orgrimmar setzt die Geißel ihren Angriff unter einer schwebenden Nekropole fort.",kw={"argentumdämmerung","dagel","durotar","invasion","lichkönig","nekrotischer stein","orgrimmar","runenkreis","geißel"},ang={["faction:Horde"]="Eine Streitmacht der Geißel, die in Sichtweite von Orgrimmars Türmen lagert, ist eine Beleidigung, die die Horde nicht dulden kann. Jeder vereidigte Champion hat die Pflicht, Durotar vor den Dienern des Lichkönigs zu verteidigen.",["race:Orc"]="Die Orcs haben Durotars trockenen roten Boden durch Entbehrungen und Blut erkämpft. Sie werden nicht zulassen, dass geistlose Monstrositäten die Heimat verderben, die sie mit bloßen Händen geschaffen haben.",["race:Undead"]="Für die Verlassenen weckt die Geißel Erinnerungen an ihre einstige Versklavung. Die Eindringlinge zu zerschmettern ist ein persönlicher Rachefeldzug gegen den fortwährenden Einfluss des Lichkönigs."},sec={{t="Untote vor den Toren",b="Die Geißel bedroht nun Länder fern von Lordaeron und dem Eis des Nordens. Ihre schwebenden Nekropolen werfen Schatten über Azeroth, selbst über Durotar. Streitkräfte der Untoten haben sich an Orgrimmars Schwelle versammelt und Lager errichtet, die die Hauptstadt der Horde bedrohen. Lieutenant Dagel und die Argentumdämmerung koordinieren die Verteidigung und rufen örtliche Champions auf, die Eindringlinge zurückzudrängen, bevor sie eine Belagerung festigen können."},{t="Nekrotische Relikte und dunkles Flüstern",b="Trübe nekrotische Steine und leuchtende Runenkreise liegen im Lager der Geißel. Die Kreise umgeben das Lager und tragen dieselbe dunkle Macht wie die Nekropole darüber. Wer in die Runen tritt, hört unnatürliche Stimmen durch den Äther hallen. Die Stimmen deuten auf eine Art der Verständigung hin, doch Dagel weiß nicht, wen sie erreichen."}},faq={{q="Warum greift die Geißel Orgrimmar an?",a="Streitkräfte der Geißel lagern vor Orgrimmar unter einer Nekropole. Lieutenant Dagel ruft Verteidiger dazu auf, ihre Reihen zu lichten und die nahen Runenkreise zu untersuchen.",al={"warum geißel orgrimmar","untote vor org","lichkönig greift orgrimmar an"}},{q="Wer ist Lieutenant Dagel?",a="Lieutenant Dagel ist ein Offizier, der gemeinsam mit der Argentumdämmerung Verteidiger gegen die Invasion mobilisiert. Nahe der Bedrohung weist Dagel Kämpfer an, die Untoten zu erschlagen und ihre arkanen Werkzeuge zu untersuchen.",al={"lieutenant dagel","dagel questgeber","wer ist dagel"}},{q="Was sind die trüben nekrotischen Steine?",a="Trübe nekrotische Steine werden den Eindringlingen der Geißel abgenommen und der Argentumdämmerung als Beweis dafür gebracht, dass Untote erschlagen wurden.",al={"nekrotische steine","was sind trübe nekrotische steine","trübe steine"}},{q="Was sind die leuchtenden Runenkreise vor der Stadt?",a="Die leuchtenden Kreise bergen dieselbe seltsame Energie wie die nahen Untoten und die Nekropole. Dagel bittet Verteidiger, ihren Zweck zu ergründen.",al={"runenkreise","leuchtende runen org","geißelkreise"}},{q="Warum ist die Argentumdämmerung in Durotar beteiligt?",a="Die Argentumdämmerung ist ein unabhängiger Orden, der sich der Vernichtung der Geißel verschrieben hat, wo immer sie auftaucht. Der Orden arbeitet mit Verteidigern der Horde zusammen, um Orgrimmars Grenzen vor der Invasion zu schützen.",al={"argentumdämmerung in orgrimmar","warum argentumdämmerung hier","argentumdämmerung horde"}},{q="Ist die Nekropole über der Stadt gefährlich?",a="Die Nekropole ragt über dem Lager der Geißel auf und teilt dessen seltsame Energie. Ihre Gegenwart macht die Bedrohung durch die Untoten nahe der Stadt besorgniserregend.",al={"schwebende zitadelle org","nekropole über durotar"}}},fx={["4fe35d0b"]={q="Warum möchte Leutnant Dagel, dass die Geißel untersucht wird?",a="Da sich die Schergen des Lichkönigs unter einer unheilvollen Nekropole direkt vor den Toren von Orgrimmar versammeln, weiß Leutnant Dagel, dass die Stadt nicht untätig bleiben kann. Er fürchtet, welche üble Magie die Invasoren in ihren Lagern zusammenbrauen. Indem er den Zweck ihrer seltsamen, leuchtenden Runenkreise entschlüsselt und die eindringende Horde dezimiert, hofft Dagel, wichtige Vital Intelligence über die dunklen Pläne der Geißel zu sammeln und eine katastrophale Belagerung von Durotar abzuwenden.",al={"warum will dagel das","dagels beweggrund","warum die geißel untersuchen"}},["76cd191d"]={q="Gegen wen werdet Ihr außerhalb von Orgrimmar in den Kampf geschickt?",a="Ihr werdet gegen die vordringenden untoten Streitkräfte geschickt, die vom Lichkönig entsandt wurden und unter einer schwebenden Nekropole ein Lager direkt außerhalb von Orgrimmar aufgeschlagen haben. Diese gedankenlosen Abscheulichkeiten und faulen Schlurfer sind Teil einer koordinierten Invasion, die Kalimdor bedroht und üble arkane Stützpunkte in der Wüste errichtet, um die Verteidigung der Horde zu untergraben und Durotar in Angst und Schrecken zu versetzen.",al={"gegen wen kämpfen wir","geißelfeinde vor orgrimmar","wen töte ich für dagel"}}},fp="36,274,19.396.0,33.327.1,39.164.0,24.201.0,33.120.0,52.136.0,43.181.0,49.135.0"}
P.entries["quest:92640"] = {n="Desperate Times",s="Valennia Stormfist wartet in Valanaar mit einem Plan, den Kult an seinem Schrein anzugreifen. Lorthuna muss dort aufgehalten werden, doch zuerst müssen die Windformer und der Hohe Orden ihre tiefen Spannungen beilegen.",h="Valennia Stormfist wartet in Valanaar mit einem Plan, den Kult an seinem Schrein anzugreifen.",kw={"kult","desperate times","der hohe orden","lorthuna","schrein","valanaar","valennia stormfist","windformer"},sec={{t="Ein direkter Angriff",b="Dem Kult kann auf offenem Feld nicht gefahrlos begegnet werden, also brauchen die Verteidiger einen kühneren Plan. Sie werden den Schrein des Kults angreifen, statt eine lange Schlacht auf ungünstigem Gelände zu schlagen. Wenn sie Lorthuna ausschalten, bevor sie ihren Teil am großen Vorhaben des Kults vollendet, können sie die Bedrohung an ihrer Quelle entscheidend schwächen."},{t="Entzweite Fraktionen vereinen",b="In Valanaar hat Valennia Stormfist einige Zeit damit verbracht, einen Angriff auf den Schrein zu planen. Der Angriff erfordert erhebliche Verstärkung und die vereinten Kräfte der Fraktionen. Doch schwere politische Spannungen entzweien weiterhin die Windformer und den Hohen Orden und gefährden ihr Bündnis."}},faq={{q="Wer ist Valennia Stormfist?",a="Valennia Stormfist befindet sich in Valanaar, wo sie einen Angriff auf den Schrein des Kults geplant hat. Der Angriff hängt von der Zusammenarbeit rivalisierender Fraktionen ab.",al={"wer ist valennia","valennia stormfist","wo ist valennia"}},{q="Wer ist Lorthuna?",a="Lorthuna ist eine Schlüsselfigur des feindlichen Kults. Sie leitet ein entscheidendes Vorhaben am Schrein und ist deshalb das Ziel des geplanten Angriffs.",al={"wer ist lorthuna","lorthunas geschichte","kultanführerin lorthuna"}},{q="Warum muss der Schrein direkt angegriffen werden?",a="Der Kult kann auf offenem Feld nicht gefahrlos bekämpft werden. Der Plan sieht vor, den Schrein anzugreifen und Lorthuna aufzuhalten, bevor ihr Vorhaben gelingt.",al={"warum den schrein angreifen","grund für den kultangriff"}},{q="Was steht zwischen den Windformern und dem Hohen Orden?",a="Zwischen den Windformern und dem Hohen Orden herrschen große Spannungen. Keine der beiden Fraktionen kann den Angriff auf den Schrein allein durchführen, also müssen beide zusammenarbeiten.",al={"spannungen hoher orden windformer","warum kämpfen die fraktionen","streit der windformer"}},{q="Wo liegt Valanaar?",a="In Valanaar koordiniert Valennia Stormfist den Plan und sammelt Verbündete für einen Angriff auf den Schrein des Kults.",al={"wo liegt valanaar","valanaar lage"}},{q="Was ist das übergeordnete Ziel dieser Mission?",a="Das Ziel ist, Valennia Stormfist in Valanaar zu finden, die Einzelheiten ihres geplanten Angriffs zu erfahren und die Zusammenarbeit der entzweiten Fraktionen zu sichern.",al={"desperate times ziel","was ist der plan in desperate times"}}},fp="15,195,15.304.0,24.282.0,26.153.0,16.140.0,41.140.0,61.148.0,18.121.0,41.150.0"}
P.entries["quest:92642"] = {n="Disrupting Logistics",s="Im Böenbeerentiefland führen Al'Aketh-Kultisten einen Großangriff. Ihre Heiler halten die Schläger im Kampf, und die Verteidiger brauchen Hilfe, bevor ihre Linien zusammenbrechen.",h="Im Böenbeerentiefland führen Al'Aketh-Kultisten einen Großangriff.",kw={"al'aketh","schläger","kultisten","disrupting logistics","böenbeerentiefland","heiler","valennia"},ang={["class:Priest"]="Als Priester wisst Ihr, wie Heilung eine Angriffslinie aufrechterhalten kann. Die Heiler der Al'Aketh sind die tragende Säule des Kultistenangriffs.",["class:Rogue"]="Als Schurke wisst Ihr, wie wertvoll es ist, hinter die feindlichen Linien zu schleichen, um Heiler auszuschalten und Verstärkung zu stören."},sec={{t="Eine verzweifelte Verteidigung",b="Ein heftiger Angriff trifft die Verteidiger oberhalb des Böenbeerentieflands. Feindliche Streitkräfte sammeln sich, und die örtlichen Linien stehen kurz vor dem Zusammenbruch. Die Befehlshaber erwarteten erhebliche Verstärkung von Valennia, doch sie müssen sich auf jede fähige Hand verlassen, die eintrifft. Schläge gegen die Unterstützung des Feindes könnten der einzige Weg sein, die Verteidigung aufrechtzuerhalten."},{t="Die Kultistenlinie durchbrechen",b="Al'Aketh-Schläger rücken in Reihen vor, unterstützt von Heilern, die ihre Wunden versorgen. Im Böenbeerentiefland kann das Ausschalten dieser Heiler den Vorstoß der Kultisten brechen. Das gibt den Verteidigern die Chance, sich neu zu formieren und die Invasion zurückzuschlagen."}},faq={{q="Was ist die Quest Disrupting Logistics?",a="Disrupting Logistics ist eine verzweifelte Verteidigung gegen den Angriff der Al'Aketh im Böenbeerentiefland. Ein einzelner Verteidiger braucht Hilfe dabei, die feindliche Unterstützung an der Front auszuschalten, bevor die Verteidigung zusammenbricht.",al={"was ist disrupting logistics","disrupting logistics quest","böenbeerentiefland quest"}},{q="Wer sind die Al'Aketh-Kultisten, die das Tiefland angreifen?",a="Al'Aketh-Kultisten greifen das Böenbeerentiefland mit Schlägern und Heilern an. Ihre geordnete Front ist auf Heilung angewiesen, um den Druck auf die örtlichen Verteidiger aufrechtzuerhalten.",al={"wer sind alaketh","wer greift das böenbeerentiefland an","wer sind die kultisten"}},{q="Warum werden gezielt die Heiler der Al'Aketh angegriffen?",a="Die Heiler der Al'Aketh halten die Kämpfer der Vorhut im Vormarsch. Sie auszuschalten könnte den Schwung des Angriffs brechen und den Verteidigern die Chance geben, sich neu zu formieren und die Kultisten zurückzudrängen.",al={"warum heiler töten","warum alaketh-heiler angreifen"}},{q="Wo findet dieser Angriff statt?",a="Der Angriff findet im Böenbeerentiefland statt, unmittelbar unterhalb des Verteidigungspostens am Fuß des Hügels. Al'Aketh-Schläger und ihre Heiler haben das Tiefland überrannt und treiben ihren Angriff voran.",al={"wo ist das böenbeerentiefland","böenbeerentiefland lage"}},{q="Wer ist Valennia?",a="Valennia scheint Hilfe und Verstärkung zu organisieren. Der Verteidiger ist erbost darüber, dass Valennia nur einen Abenteurer gegen einen gewaltigen Angriff geschickt hat.",al={"wer ist valennia","valennia verstärkung"}},{q="Wer befehligt die Verteidigung gegen die Al'Aketh?",a="Ein bedrängter Verteidiger ruft um Hilfe, während seine Leute kurz vor der Niederlage gegen die Al'Aketh stehen. Der Verteidiger verehrt „die Winde“ und braucht jede Streitmacht, die das Blatt wenden kann.",al={"wer vergibt disrupting logistics","wer sind meine leute die standhalten"}}},fp="20,178,19.351.0,25.239.0,39.198.0,53.171.0,51.183.0,35.192.0,16.146.0,46.183.0"}
P.entries["quest:92643"] = {n="The Turncoat",s="Ein Kultist der Al'Aketh bietet an, überzulaufen und die Pläne des Kults für die Insel zu enthüllen. Ihr werdet entsandt, um ihn aus einem abgelegenen Rückzugsort im Hochland nordwestlich von Valanaar zu holen, wo das Treffen eine Falle sein könnte.",h="Ein Kultist der Al'Aketh bietet an, überzulaufen und die Pläne des Kults für die Insel zu enthüllen.",kw={"al'aketh","kultist","überläufer","hochland","the turncoat","valanaar"},ang={["class:Rogue"]="Infiltration, Überlaufen und Hinterhalte sind einem Schurken vertraut. Kultisten, die sich abwenden, riskieren Schweigen oder eine Klinge. Die Attentäter draußen zeigen, wie Geheimhaltung im Hochland beide Seiten treffen kann."},sec={{t="Ein gebrochener Eid",b="Ein Kultist aus den Reihen der Al'Aketh behauptet, die wahren Absichten des Kults für die Insel zu kennen. Er bietet an, überzulaufen, verlangt aber verbindliche Schutzgarantien. Der Kult hütet seine Pläne streng, also könnte eine Kontaktaufnahme die Gefahr wert sein."},{t="Das Versteck im Hochland",b="Der Überläufer wartet allein in einem abgelegenen Anwesen im Hochland nordwestlich von Valanaar. Ihr müsst ihn mit Vorsicht aufsuchen. Das Treffen könnte ein Hinterhalt der Al'Aketh sein, um jene hervorzulocken, die in den Angelegenheiten des Kults herumschnüffeln."},{t="Stille im Hochland",b="Der Überläufer liegt tot in dem abgelegenen Haus im Hochland. Attentäter haben ihn aufgespürt und zugeschlagen, bevor eine Eskorte eintreffen konnte. Draußen zeugen gefallene Attentäter von den Geschehnissen. Ein Schimmer am Körper des toten Überläufers deutet darauf hin, dass er eine Antwort hinterlassen hat."}},faq={{q="Wer ist der Überläufer?",a="Der Überläufer war ein ehemaliges Mitglied des Kults der Al'Aketh, das behauptete, die wahren Absichten des Kults für die Insel zu kennen. Er bot an, überzulaufen und sein Wissen im Austausch gegen Schutz preiszugeben.",al={"wer ist der überläufer","wer war der überläufer","identität des überläufers"}},{q="Was sind die Al'Aketh?",a="Die Al'Aketh sind ein rätselhafter Kult, der in der Region tätig ist. Ihre Pläne für die Insel bleiben hinter Geheimhaltung und Fanatismus verborgen, weshalb die örtlichen Behörden viel riskieren, um gesprächsbereite Überläufer zu erreichen.",al={"wer sind die al'aketh","kult der al'aketh","was sind die al'aketh"}},{q="Wo versteckt sich der Überläufer?",a="Der Überläufer versteckte sich in einem abgelegenen Anwesen im Hochland nordwestlich von Valanaar. Dort wartete er auf eine Eskorte und vertraute auf die Schutzversprechen.",al={"wo versteckt sich der überläufer","aufenthaltsort des überläufers","wo ist der überläufer zu finden"}},{q="Was ist mit dem Überläufer geschehen?",a="Als jemand das abgelegene Anwesen im Hochland erreichte, hatten Attentäter den Überläufer bereits aufgespürt und getötet. Er wurde tot im Haus gefunden und konnte nicht mehr befragt werden.",al={"was ist mit dem überläufer geschehen","ist der überläufer gestorben","wer hat den überläufer getötet"}},{q="Was hat der Überläufer hinterlassen?",a="Nachdem die Attentäter draußen beseitigt waren, fiel ein Glitzern am Körper des toten Überläufers auf. Der glänzende Gegenstand blieb zurück und könnte einen Hinweis auf die Geheimnisse bergen, die er mit sich trug.",al={"welcher glänzende gegenstand","glänzender gegenstand des überläufers","schimmernde reflexion am körper"}},{q="Warum hat der Kultist beschlossen, überzulaufen?",a="Der Kultist behauptet, die wahren Absichten der Al'Aketh für die Insel zu kennen, und wird nur mit Schutzgarantien überlaufen. Was ihn dazu bewog, den Kult zu verlassen, ist nicht bekannt.",al={"warum ist der kultist übergelaufen","beweggrund des überläufers","warum die al'aketh verraten"}}},fp="12,206,13.233.0,20.213.0,24.246.1,20.188.0,21.197.0,29.147.0,30.166.0,35.168.0,37.171.0"}
P.entries["quest:92644"] = {n="Unfortunate News",s="Ihr findet den Überläufer tot vor, bevor er sprechen kann. Unter seinem Leichnam liegt ein beschädigter blauer Kristall, den Ihr zu High Elder Talanaanis Shadowsong in Valanaar bringt.",h="Ihr findet den Überläufer tot vor, bevor er sprechen kann.",kw={"kultist","leuchtender kristall","shadowsong","talanaanis shadowsong","überläufer","unfortunate news","valanaar"},ang={["class:Mage"]="Als Magier erkennt Ihr den beschädigten, blau leuchtenden Kristall möglicherweise als Artefakt. High Elder Shadowsong ermittelt zu den Kultisten und nimmt den Kristall an sich, um ihn zu untersuchen."},sec={{t="Ein gescheitertes Treffen",b="Ihr erreicht den Treffpunkt und findet den überlaufenden Kultisten bereits erschlagen vor. Sein Leichnam ist noch warm. Darunter liegt ein kleiner, blau leuchtender Kristall, beschädigt, aber noch immer summend. Ihr bringt ihn zu High Elder Talanaanis Shadowsong in Valanaar."},{t="Shadowsongs Ermittlungen",b="Ihr kehrt allein nach Valanaar zurück und berichtet High Elder Talanaanis Shadowsong, dass der Überläufer starb, bevor er aussagen konnte. Der Verlust eines lebenden Kontakts ist ein schwerer Rückschlag. Doch der beschädigte blaue Kristall erregt die Aufmerksamkeit des High Elders. Er findet ihn interessant und nimmt ihn Euch ab."}},faq={{q="Was ist die Quest Unfortunate News?",a="Ihr findet den überlaufenden Kultisten tot vor, bevor er sprechen kann. Unter seinem Leichnam liegt ein beschädigter, blau leuchtender Kristall, den Ihr zu High Elder Talanaanis Shadowsong bringt.",al={"was ist unfortunate news","unfortunate news quest","unfortunate news wow forever"}},{q="Wer war der überlaufende Kultist?",a="Der Überläufer war ein Kultist, den Ihr treffen solltet. Er wurde getötet, bevor er sprechen oder fliehen konnte, und hinterließ einen noch warmen Leichnam und einen beschädigten Kristall.",al={"wer ist der tote überläufer","wer starb in unfortunate news","überlaufender kultist"}},{q="Wer ist High Elder Shadowsong?",a="Talanaanis Shadowsong ist ein Elf und der High Elder in Valanaar. Er leitet die Ermittlungen zu den Kultisten und erhält den beschädigten Kristall, der unter dem Leichnam des Überläufers lag.",al={"wer ist shadowsong in valanaar","wo ist talanaanis shadowsong","talanaanis shadowsong"}},{q="Was ist der beschädigte blaue Kristall?",a="Der beschädigte blaue Kristall ist ein kleiner, leuchtender Kristall, der unter dem gefallenen Überläufer gefunden wird. High Elder Shadowsong findet ihn interessant und nimmt ihn Euch ab.",al={"was ist der leuchtende kristall","blauer kristall vom kultisten","beschädigter kristall unfortunate news"}},{q="Wo spielt diese Quest?",a="In Valanaar lebt High Elder Talanaanis Shadowsong. Ihr kehrt mit Eurem Bericht und dem geborgenen Kristall dorthin zurück.",al={"wo ist valanaar","valanaar standort","unfortunate news abgeben"}},{q="Wie hängt diese Quest mit The Turncoat zusammen?",a="Diese Quest folgt auf The Turncoat, in der Ihr aufbrecht, um den überlaufenden Kultisten zu finden. Ihr kommt zu spät, um ihn zu retten.",al={"welche quest kommt vor unfortunate news","unfortunate news vorgängerquest","the turncoat quest"}}},fp="16,164,19.232.0,26.275.1,35.166.0,29.160.0,29.166.0,33.153.0,33.120.0,44.112.0"}
P.entries["quest:92645"] = {n="Breaking the Breaker",s="Im Böenbeerentiefland setzen Kultisten die Verteidiger schwer unter Druck. Kommandantin Belguilos führt den Angriff von ihrer Hangvilla aus an, und sie dort anzugreifen könnte die einzige Überlebenschance der Verteidiger sein.",h="Im Böenbeerentiefland setzen Kultisten die Verteidiger schwer unter Druck.",kw={"belguilos","breaking the breaker","kommandantin belguilos","kultkommandantin","böenbeerentiefland","friedensbewahrerin","die brecherin","villa"},ang={["class:Warrior"]="Als Krieger stellt Ihr Euch Kommandantin Belguilos, einer ehemaligen Friedensbewahrerin, die als „die Brecherin“ gefürchtet wird.",["race:Skyborne"]="Die Verteidiger rufen die vier Winde an, den Helden zu segnen, nachdem die Kultisten aufgehalten wurden."},sec={{t="Eine verzweifelte Verteidigung",b="Kultisten greifen das Böenbeerentiefland an und treiben die örtlichen Verteidiger an den Rand des Untergangs. Sie zurückzuschlagen scheint nahezu unmöglich, solange Kommandantin Belguilos den Angriff lenkt. Alle fürchten sie als „die Brecherin“.\n\nIhre Villa ist die Basis der Operation. Sie dort zu erschlagen ist gefährlich, beinahe selbstmörderisch, doch Untätigkeit besiegelt den Untergang der Verteidiger."},{t="Die gefallene Friedensbewahrerin",b="Bevor sie die Kultisten befehligte, sorgte Belguilos als Friedensbewahrerin für Ordnung. Schon damals fanden die Menschen in ihrem Umfeld etwas zutiefst Beunruhigendes an ihrem Auftreten. Als sich der Einfluss des Kults unkontrolliert ausbreitete, verschrieb sie sich dessen Extremismus. Jetzt befehligt sie die Kultisten und verbreitet Schrecken."}},faq={{q="Wer ist Belguilos die Brecherin?",a="Belguilos, genannt „die Brecherin“, befehligt den Angriff der Kultisten. Bevor sie sich dem Kult anschloss, diente sie als Friedensbewahrerin, doch schon damals wirkte sie auf die Menschen in ihrem Umfeld beunruhigend.",al={"wer ist belguilos","wer ist die brecherin","kultkommandantin"}},{q="Wo ist Kommandantin Belguilos zu finden?",a="Kommandantin Belguilos befindet sich in der Villa am Fuß des Hügels im Böenbeerentiefland. Von dort aus koordiniert sie den Angriff der Kultisten auf die örtlichen Verteidiger.",al={"wo ist belguilos","belguilos aufenthaltsort","wo ist die brecherin zu finden"}},{q="Warum muss Belguilos ausgeschaltet werden?",a="Der Ansturm der Kultisten lässt sich kaum abwehren, solange Belguilos ihn lenkt. Ihre Ausschaltung zerschlägt die Führung des Kults und gibt den Verteidigern eine echte Überlebenschance.",al={"warum belguilos töten","grund für den kultangriff","warum ist die brecherin gefährlich"}},{q="Welche Vergangenheit hatte Belguilos, bevor sie sich dem Kult anschloss?",a="Bevor sich der Einfluss des Kults unkontrolliert ausbreitete, diente Belguilos als Friedensbewahrerin. Jene, die sie kannten, fanden schon damals etwas zutiefst Beunruhigendes an ihr.",al={"was war belguilos früher","war belguilos gut","friedensbewahrerin kultistin"}},{q="Welche Bedeutung hat der Segen der vier Winde?",a="Der Segen der vier Winde ist ein Ausdruck tiefer Erleichterung und Dankbarkeit unter den Verteidigern, nachdem der furchterregenden Kultkommandantin endgültig Einhalt geboten wurde.",al={"vier winde bedeutung","wer sagt die vier winde mögen euch segnen"}},{q="Was ist das Böenbeerentiefland?",a="Das Böenbeerentiefland ist ein umkämpftes Gebiet, in dem der Angriff des Kults stattfindet. Kommandantin Belguilos ist in einer Villa am Fuß des Hügels zu finden.",al={"was ist das böenbeerentiefland","wo ist die brecherin-quest"}}},fp="20,195,19.329.0,22.276.0,29.175.0,39.158.0,33.180.0,50.158.0,59.166.0,32.144.0"}
P.entries["quest:92646"] = {n="Confront Lorthuna",s="Elaadrin Evengale und Ayessa Dawnsinger verfolgen Hohepriesterin Lorthuna durch ein Portal in die Türme der Rohashi über Zephras. Sie bitten um Eure Hilfe, bevor sie der Gerechtigkeit entkommen oder ihre Macht stärken kann.",h="Elaadrin Evengale und Ayessa Dawnsinger verfolgen Hohepriesterin Lorthuna durch ein Portal in die Türme der...",kw={"ayessa dawnsinger","confront lorthuna","elaadrin evengale","hohepriesterin lorthuna","lorthuna","muln","die türme der rohashi","valennia","windformer","zephras"},ang={["class:Priest"]="Als Priester stellt Ihr Euch Hohepriesterin Lorthuna, einer verderbten geistlichen Anführerin inmitten der Türme. Der Kampf gegen sie hat Gewicht für jene, die sich gegen dunkle Lehren wehren.",["class:Shaman"]="Als Schamane habt auch Ihr ein spirituelles Interesse an der Arbeit der Windformer, das Gleichgewicht der Elemente auf Zephras zu wahren. Ihr könnt dazu beitragen, dass diese Harmonie trotz Lorthunas Bedrohung bestehen bleibt."},sec={{t="Verfolgung in die Türme",b="Hohepriesterin Lorthuna flieht durch ein mystisches Tor in die Türme der Rohashi über Zephras. Ein verletzter Verbündeter bleibt an der Schwelle des Portals zurück. Elaadrin Evengale und Ayessa Dawnsinger folgen ihr in die Höhen und bitten um Eure Hilfe, bevor sie der Gerechtigkeit entkommt oder ihre Macht stärkt."},{t="Der Preis der Schlacht",b="Nach dem Zusammenstoß in den Türmen brauchen Valennia und ihre überlebenden Streitkräfte die Fürsorge eines Heilers. Sie werden zur Residenz des Obersten Ältesten eskortiert, um sich dort zu erholen. Lorthuna ist ihnen im Kampf begegnet, und die Koalition ist angeschlagen, während ihre Ressourcen kaum noch ausreichen."},{t="Eine schutzlose Insel",b="Nach der Schlacht berät sich Muln über die Windformer und ihre fortlaufende Mission, bevor er zum Festland von Azeroth aufbricht. Zephras bleibt äußerst verwundbar. Die zurückgebliebenen Anführer müssen dringend die Verteidigung gegen die Gefahren planen, die die Insel weiterhin bedrohen."}},faq={{q="Wer ist Hohepriesterin Lorthuna?",a="Hohepriesterin Lorthuna ist eine mächtige Widersacherin, die durch ein Portal in die Türme der Rohashi über Zephras flieht. Ayessa Dawnsinger und Elaadrin Evengale verfolgen sie dorthin.",al={"wer ist lorthuna","was ist lorthuna","geschichte von hohepriesterin lorthuna"}},{q="Was sind die Türme der Rohashi?",a="Die Türme der Rohashi sind Höhen über der Insel Zephras. Hohepriesterin Lorthuna flieht durch ein Portal dorthin, und ihre Verfolger folgen ihr.",al={"was sind die türme der rohashi","wohin führt das portal","lage der türme der rohashi"}},{q="Wer verfolgte Lorthuna durch das Portal?",a="Elaadrin Evengale und Ayessa Dawnsinger verfolgen Hohepriesterin Lorthuna durch das Portal, als sie in die Türme flieht. Sie bitten um Eure Hilfe.",al={"wer verfolgte lorthuna","ayessa und elaadrin","wer betritt das portal"}},{q="Was geschah mit Valennia und ihren Streitkräften?",a="Valennia und ihre überlebenden Streitkräfte brauchen nach den Kämpfen sofortige Versorgung. Heiler kümmern sich um sie, und sie werden zur Residenz des Obersten Ältesten eskortiert, um sich dort zu erholen.",al={"wer ist valennia","was geschah mit valennia","valennias streitkräfte"}},{q="Welche Rolle spielt Muln bei diesen Ereignissen?",a="Muln ist ein mit den Windformern verbundener Verbündeter, der nach Beratungen über ihre Zukunft und ihre fortlaufende Mission zum Festland von Azeroth aufbricht.",al={"wer ist muln","muln verlässt zephras","wohin ging muln"}},{q="Ist die Insel Zephras sicher, nachdem Lorthuna gestellt wurde?",a="Zephras bleibt nach der Konfrontation äußerst verwundbar. Seine Anführer müssen dringend die Verteidigung gegen die Gefahren planen, die die Insel bedrohen.",al={"was geschieht mit zephras","ist zephras jetzt sicher","zustand der insel zephras"}}},fp="17,204,23.295.0,22.248.1,25.257.1,31.169.0,28.138.0,37.141.0,41.156.0,36.134.0,59.146.0"}
P.entries["quest:92679"] = {n="Blood Tithe",s="In Valanaar sucht Alvarion Windfield Hilfe für den Obsthain, der seine Familie ernährt. Schmerzen halten den Skyborne-Bauern von seiner Arbeit ab, also schickt er Reisende nach Westen zu seiner Frau Aamelia, die ihren Hof im Tiefland bewirtschaftet.",h="In Valanaar sucht Alvarion Windfield Hilfe für den Obsthain, der seine Familie ernährt.",kw={"aamelia windfield","alvarion windfield","blood tithe","skyborne","valanaar","obsthain der windfields"},ang={["race:Skyborne"]="Als Skyborne-Bauer leidet Alvarion Windfield und ruft verzweifelt um Hilfe. Seine Not zeigt, womit Skyborne jenseits von Valanaar zu kämpfen haben."},sec={{t="Eine Bitte in Valanaar",b="Alvarion Windfield ist von seinem Gehöft nach Valanaar gekommen, um fähige Kämpfer zu finden. Seine Schmerzen zeichnen ihn sichtbar, und er fürchtet um die Lebensgrundlage, die sein Hof ihm bietet. Er bittet Euch, nach Westen ins Tiefland zu reisen, wo seine Frau Aamelia den Obsthain ihrer Familie bewirtschaftet."},{t="Unheil im Tiefland",b="Der Obsthain der Windfields liegt im Tiefland westlich von Valanaar. Alvarion ist zu krank, um den Hof zu bewirtschaften, also trägt Aamelia Windfield dessen Lasten allein. Erreicht das westliche Tal, findet heraus, was den Obsthain bedroht, und steht der Familie mit Eurer Stärke bei."}},faq={{q="Wer ist Alvarion Windfield?",a="Alvarion Windfield ist ein Skyborne-Bauer in Valanaar, der Kämpfer sucht, um sein Zuhause zu schützen. Obwohl ihn starke Schmerzen plagen, schickt er Reisende zu seiner Frau Aamelia in ihrem Obsthain.",al={"wer ist alvarion","alvarion windfield hintergrundgeschichte","wer vergibt blood tithe"}},{q="Wo liegt der Obsthain der Windfields?",a="Der Obsthain der Windfields liegt im Tiefland westlich von Valanaar. Alvarion schickt Reisende dorthin, um seine Frau Aamelia Windfield zu finden, die die Verteidigung des Hofes leitet.",al={"wo liegt der obsthain der windfields","aamelia windfield aufenthaltsort","wie findet man den obsthain"}},{q="Warum hat Alvarion Schmerzen?",a="Woran Alvarion leidet, ist unbekannt, als Reisende ihm begegnen. Heftige, entkräftende Schmerzen plagen ihn beim Sprechen und verleihen seiner Bitte um Hilfe Dringlichkeit.",al={"warum hat alvarion schmerzen","was fehlt alvarion","alvarion schmerzen"}},{q="Wer ist Aamelia Windfield?",a="Aamelia Windfield ist Alvarions Frau und bewirtschaftet den Obsthain ihrer Familie westlich von Valanaar. Er schickt hilfsbereite Reisende zu ihr, damit sie ihr helfen, ihr Land zu verteidigen.",al={"wer ist aamelia","aamelia windfield hintergrundgeschichte","alvarions frau"}},{q="Was ist die Aufgabe in Blood Tithe?",a="Alvarion Windfield sucht in Valanaar Hilfe für seinen bedrängten Hof. Er bittet Euch, seine Frau Aamelia in ihrem Obsthain im Tiefland zu finden.",al={"blood tithe questzusammenfassung","worum geht es in blood tithe","hof unter beschuss valanaar"}},{q="Welche Bedeutung hat Valanaar hier?",a="Valanaar ist eine Siedlung, in der Reisende und Skyborne zusammenkommen. Alvarion kommt dorthin, um fähige Kämpfer zu finden, die seinen Obsthain aus der Gefahr retten.",al={"valanaar hintergrundgeschichte","wo spielt blood tithe","was ist valanaar"}}},fp="11,208,18.270.0,23.239.0,26.183.0,39.163.0,24.149.0,25.143.0,32.131.0,37.139.0"}
P.entries["quest:92682"] = {n="Make Yourself Useful",s="Im Obsthain der Windfields nehmen Ferauus Banditen Sturmäpfel, bevor ihnen ihr Anteil zusteht. Einige hungrige Gesetzlose sind aus der Reihe getanzt, um die Bäume vorzeitig abzuernten. Vertreibt sie, und der Obsthainhüter wird Euch respektieren.",h="Im Obsthain der Windfields nehmen Ferauus Banditen Sturmäpfel, bevor ihnen ihr Anteil zusteht.",kw={"banditen","ferauu","hungrige banditen","make yourself useful","obsthain","reife sturmäpfel","sturmäpfel","obsthain der windfields"},ang={["class:Rogue"]="Als Schurke erkennt Ihr die mangelnde Disziplin unter unerfahrenen Dieben, wenn Banditen ihre Bande verraten, um vorzeitig Sturmäpfel zu stehlen."},sec={{t="Ärger im Obsthain der Windfields",b="Der Obsthain der Windfields gibt Ferauus Banditen regelmäßig einen Anteil seiner Obsternte. Ferauu führt die Bande an, doch einige Gesetzlose können seinen geplanten Besuch nicht abwarten. Sie schleichen sich vorzeitig in den Obsthain, um Sturmäpfel für sich selbst zu pflücken."},{t="Diebe unter Dieben",b="Der Obsthainpfleger spannt ehrgeizige Neuankömmlinge ein, bevor Ferauu eintrifft. Der Hüter bittet Euch, die reifen Sturmäpfel zu sichern und hungrige Banditen zu vertreiben, die unerlaubt zwischen den Bäumen umherstreifen. Sie haben sich hinter Ferauus Rücken seinen Anteil genommen. Der Hüter sagt, Ferauu würde sie dafür vermutlich hinrichten."}},faq={{q="Wer ist Ferauu?",a="Ferauu führt die Banditen an, die regelmäßig einen Anteil der Ernte des Obsthains der Windfields verlangen. Er führt seine Bande mit erbarmungsloser Disziplin, doch einige hungrige Banditen haben sich hinter seinem Rücken vorzeitig eingeschlichen.",al={"wer ist ferauu","ferauu hintergrundgeschichte","ferauu banditenanführer"}},{q="Was ist der Obsthain der Windfields?",a="Der Obsthain der Windfields ist ein örtlicher Bauernhof, auf dem Sturmäpfel angebaut werden. Ferauus Banditen verlangen einen Teil seiner Obsternte und lassen dafür den Obsthain in Frieden.",al={"was ist der obsthain der windfields","obsthain der windfields hintergrundgeschichte","sturmapfelhain"}},{q="Warum schleichen hungrige Banditen um die Sturmapfelbäume?",a="Hungrige Banditen aus Ferauus Bande sind vor der geplanten Abholung der Ernte in den Obsthain eingedrungen, um Sturmäpfel für sich selbst zu stehlen. Sie sind aus der Reihe getanzt und haben sich an der Ernte vergriffen, deshalb bittet Euch der Obsthainhüter, sie zu vertreiben.",al={"warum hungrige banditen töten","warum sind banditen im obsthain","hungrige banditen hintergrundgeschichte"}},{q="Was sind Sturmäpfel?",a="Sturmäpfel sind eine Obstsorte, die im Obsthain der Windfields angebaut wird. Sie ernähren die Menschen und bilden den Erntetribut, den Ferauus Banditen verlangen.",al={"was sind sturmäpfel","reife sturmäpfel"}},{q="Weiß Ferauu, dass seine Banditen sich in den Obsthain schleichen?",a="Ferauu weiß nicht, dass diese Banditen vorzeitig gekommen sind. Der Obsthainhüter sagt, sie hätten eigenmächtig gehandelt, und Ferauu würde sie vermutlich hinrichten, wenn er sie dabei ertappte, vor seiner Ankunft Obst zu nehmen.",al={"weiß ferauu von den banditen","verrat an ferauu"}},{q="Wer gibt Euch den Auftrag Make Yourself Useful?",a="Der Obsthainpfleger bietet Euch im Obsthain der Windfields Arbeit an und beobachtet die Baumhaine von einem nahen Fenster aus. Wenn dreiste Neuankömmlinge Arbeit oder Essen suchen, stellt der Hüter ihren Mut auf die Probe, indem er Euch gegen die eingedrungenen Banditen schickt.",al={"wer vergibt make yourself useful","make yourself useful questgeber"}}},fp="20,208,28.224.0,21.298.0,14.193.0,26.153.0,53.219.0,21.125.0,59.175.0,40.230.0"}
P.entries["quest:92683"] = {n="Flatterfliegenstaub",s="Im Böenbeerentiefland weckt Flutterfly Dust das Interesse eines Siedlers. Reisende sammeln den Staub von riesigen Flutterflies, während Banditen jeden bedrohen, der sich allein auf die Felder wagt.",h="Im Böenbeerentiefland weckt Flutterfly Dust das Interesse eines Siedlers.",kw={"banditen","flutterfly","flutterfly dust","flatterfliegenklatsche","böenbeerentiefland","obsthain","flügelstaub"},sec={{t="Die Riesen von Gustberry",b="Riesige Flutterflies treiben durch die äußeren Felder und Obsthaine des Böenbeerentieflands. Ihre Flügel geben feinen Staub ab, und Ihr könnt ihn in großen Mengen sammeln. Siedler in der Nähe wollen das Pulver für praktische Zwecke im Haushalt. Doch die Insekten bleiben wild."},{t="Klatschen und Schütteln",b="Eine Flatterfliegenklatsche bringt den Staub mit einem wuchtigen Schlag zum Rieseln. Die meisten Flutterflies geraten in Panik, fliegen auf und schütteln Haufen von Pulver ab. Manche drehen sich um und schlagen zurück, wenn sie provoziert werden. Meist sind sie friedfertig."},{t="Verschwiegene Verwendungen",b="Das Sammeln des Staubs ist eine schmutzige Angelegenheit, und er haftet wochenlang an Kleidung und Ausrüstung. Der Siedler erwartet die Lieferung sehnsüchtig, denn Banditen machen einsame Ausflüge auf die Felder zu gefährlich. Fragt Ihr nach dem Zweck des Pulvers, spricht der Bewohner nur vage von allerlei Kram und Zeug."}},faq={{q="Wofür wird der Staub der Flutterflies verwendet?",a="Der Bewohner sagt, der Staub habe praktische Verwendungen im Haushalt, bleibt aber vage über seinen Zweck und nennt ihn allerlei Kram und Zeug.",al={"was ist der staub der flutterflies","verwendung von flutterfly-staub","wofür ist der staub"}},{q="Wo sind Flutterflies zu finden?",a="Riesige Flutterflies streifen durch die äußeren Felder nahe dem örtlichen Obsthain, besonders im Böenbeerentiefland. Banditen in der Nähe machen das Sammeln dort für jeden gefährlich, der allein unterwegs ist.",al={"wo sind flutterflies","fundort der flutterflies","insekten im böenbeerentiefland"}},{q="Sind Flutterflies aggressiv?",a="Flutterflies sind meist friedfertig und fliehen, wenn sie gestört werden. Manche verteidigen sich, wenn sie geschlagen oder provoziert werden, und geben dann ihren Flügelstaub ab.",al={"sind flutterflies gefährlich","greifen flutterflies an","verhalten der flutterflies"}},{q="Wie wird der Staub der Flutterflies gesammelt?",a="Mit einer Flatterfliegenklatsche versetzt Ihr den übergroßen Insekten einen kräftigen Schlag. Als Reaktion schütteln manche ihr Hinterteil und verstreuen Haufen von Flügelstaub, die Ihr sammeln könnt.",al={"wie bekommt man staub","flatterfliegenklatsche","staub der flutterflies sammeln"}},{q="Warum braucht der Bewohner jemanden, der den Staub für ihn sammelt?",a="Der Bewohner lebt allein und kann das Gehöft nicht ohne Weiteres verlassen, um den Staub zu sammeln. Banditen im umliegenden Tiefland machen einen Ausflug weit hinaus auf die Felder zu gefährlich.",al={"warum wird hilfe gebraucht","banditenbedrohung in gustberry","warum fragt der auftraggeber"}},{q="Warum weicht der Bewohner Fragen zum wahren Zweck des Staubs aus?",a="Der Bewohner weigert sich, die Verwendung des Staubs im Haushalt zu erklären, und tut Fragen mit Gerede von Zeug und Kram ab. Sein Zweck bleibt ungeklärt.",al={"warum so geheim","geheimes staubrezept"}}},fp="15,184,23.244.0,19.200.0,21.277.0,33.122.0,29.170.0,28.135.0,33.151.0,59.169.0,58.144.0"}
P.entries["quest:92684"] = {n="Ornery Ornery Galestriders",s="Im Böenbeerentiefland bedrohen Galestriders die magere Ernte eines Obstbauern, indem sie Stormapples plündern. Vertreibt die dreistesten Vögel, um die verbliebenen Früchte zu retten, und bringt Lendenstücke fürs Abendessen heim.",h="Im Böenbeerentiefland bedrohen Galestriders die magere Ernte eines Obstbauern, indem sie Stormapples plündern.",kw={"galestrider","böenbeerentiefland","tiefland-galestrider","obstgarten","übellaunige galestriders","stormapples","lendenstück"},ang={["class:Hunter"]="Achtet als Jäger auf die kräftigen Tritte und das aggressive Wesen der Tiefland-Galestriders. Sie unterscheiden sich von ihren Verwandten im Hochland.",["profession:Cooking"]="Tiefland-Galestriders liefern nahrhafte Lendenstücke für eine sättigende warme Mahlzeit, eine willkommene Abwechslung zu mageren Ernten und Obst."},sec={{t="Verteidigung des Obstgartens",b="Eine magere Ernte hat den Bauern im Böenbeerentiefland kaum Vorräte gelassen. Nun reißen wilde Galestriders reife Stormapples von den Zweigen der Obstbäume und bedrohen die verbliebenen Früchte. Der Bauer braucht jemanden, der die dreistesten Vögel vertreibt oder erlegt, bevor die Ernte verloren ist."},{t="Schrecken des Tieflands",b="Tiefland-Galestriders sind größer und übellauniger als ihre Verwandten im Hochland. Seid vorsichtig in der Nähe dieser hoch aufragenden Vögel, Reisender; ein kräftiger Tritt kann einen Kämpfer schwer verletzen oder töten. Ihre Lendenstücke bieten hungrigen Einheimischen eine seltene, sättigende Mahlzeit."}},faq={{q="Warum bereiten die Galestriders dem Bauern Probleme?",a="Galestriders plündern den Obstgarten auf der Suche nach Stormapples. Da die Ernte ohnehin mager ausfällt, bedroht ihr Fraß die örtliche Nahrungsversorgung.",al={"was stehlen galestriders","warum galestriders töten","stormapples im obstgarten"}},{q="Wie gefährlich sind Tiefland-Galestriders?",a="Tiefland-Galestriders sind größer und aggressiver als ihre Verwandten im Hochland. Ihre kräftigen Tritte können einen unachtsamen Reisenden töten.",al={"wie gefährlich sind galestriders","angriffe von galestriders","sind galestriders stark"}},{q="Was will der Bauer von den Galestriders?",a="Der Bauer möchte, dass Reisende aggressive Tiefland-Galestriders erlegen und ihre Lendenstücke fürs Abendessen sammeln.",al={"galestrider-fleisch","was lassen galestriders fallen","quest für lendenstücke"}},{q="Wo sind diese Galestriders zu finden?",a="Übellaunige Tiefland-Galestriders durchstreifen das Böenbeerentiefland, besonders nahe Gehöften und Obstgärten, wo sie nach Stormapples suchen.",al={"wo sind galestriders zu finden","galestrider-fundort","böenbeerentiefland"}},{q="Wie unterscheiden sich Tiefland-Galestriders von Hochland-Galestriders?",a="Tiefland-Galestriders sind größer und übellauniger als ihre Verwandten im Hochland. Ihre Tritte können einen Reisenden schwer verletzen.",al={"hochland- und tiefland-galestriders im vergleich","galestrider-arten"}},{q="Was sind Stormapples?",a="Stormapples sind Obstfrüchte, die in der Region angebaut werden. Da die Ernte knapp ausfällt, müssen die verbliebenen Bäume vor Galestriders auf Nahrungssuche geschützt werden.",al={"was sind stormapples","obstgartenernte"}}},fp="26,213,21.253.0,15.241.0,57.126.0,40.136.0,48.109.0,35.132.0,63.120.0,21.141.0"}
P.entries["quest:92685"] = {n="The Hills Have Eyes",s="Aamelia droht im Böenbeerentiefland ein Banditenangriff, und Ferauus Überfall rückt näher. Sie schickt Reisende zu einem Angriff auf ein Lager in den nördlichen Hügeln, bevor sich die Banditen sammeln.",h="Aamelia droht im Böenbeerentiefland ein Banditenangriff, und Ferauus Überfall rückt näher.",kw={"aamelia","banditenmasken","blutverschmierte banditenmasken","ferauu","böenbeerentiefland","wegelagererbanditen","the hills have eyes"},ang={["profession:Tailoring"]="Aamelia scherzt grimmig darüber, aus blutverschmierten Banditenmasken eine Decke für Ferauu zu nähen."},sec={{t="Ein Präventivschlag",b="Aamelia steht im Böenbeerentiefland ein Angriff bevor. Ferauu führt die Gesetzlosen an, die ihren Hof bedrohen. Sie bittet Euch, ihr Lager in den Hügeln im Norden anzugreifen. Lichtet die Reihen der Wegelagerer, bevor sie sich sammeln, und Aamelia hofft, ihren Angriff zu schwächen und vor ihrer Ankunft Zeit zu gewinnen."},{t="Neue Hoffnung und Vergeltung",b="Aamelia bittet Euch, blutverschmierte Masken der gefallenen Wegelagerer als Beweis für den Hinterhalt zurückzubringen. Grimmig scherzt sie darüber, sie zu einer Decke für Ferauu zusammenzunähen. Sie freut sich, dass ihre Peiniger auf erbitterten Widerstand gestoßen sind.\n\nDer Angriff auf das nördliche Lager beendet Wochen hoffnungslosen Wartens. Aamelia hat neuen Mut, sich Ferauu und seiner Hauptbande entgegenzustellen, wenn sie eintreffen."}},faq={{q="Was ist „The Hills Have Eyes“?",a="Aamelia bittet Reisende, ein Banditenlager in den nördlichen Hügeln anzugreifen, bevor Ferauus Wegelagerer ihren Hof überfallen. Außerdem bittet sie um blutverschmierte Masken der gefallenen Banditen.",al={"hills have eyes quest","was ist diese quest","was ist the hills have eyes"}},{q="Wer vergibt die Quest „The Hills Have Eyes“?",a="Aamelia erteilt den Auftrag auf ihrem Hof im Böenbeerentiefland. Nach wochenlangem Warten auf die Banditen fürchtet sie deren Angriff.",al={"wer vergibt the hills have eyes","wer ist aamelia","questgeberin aamelia"}},{q="Wer ist Ferauu?",a="Ferauu führt die Wegelagererbanditen im Böenbeerentiefland an. Seine Bande bedroht Aamelias Hof und bereitet einen Angriff vor.",al={"wer ist ferauu","ferauu boss","banditenanführer ferauu"}},{q="Wo befinden sich die Wegelagererbanditen?",a="Wegelagererbanditen haben überall im Böenbeerentiefland Lager, darunter ein kleines Lager in den Hügeln direkt nördlich von Aamelias Hof.",al={"böenbeerentiefland banditen","wo sind die banditen","banditenlager hügel"}},{q="Warum will Aamelia blutverschmierte Banditenmasken?",a="Aamelia bittet um blutverschmierte Masken als Beweis für den Hinterhalt. Der Angriff auf das Banditenlager hilft, vor Ferauus Angriff die Kräfteverhältnisse auszugleichen.",al={"warum masken sammeln","warum blutverschmierte masken","wofür sind die masken"}},{q="Was geschieht nach Abschluss der Quest?",a="Nach dem Angriff auf das Lager in den Hügeln schöpft Aamelia Hoffnung für ihren Hof. Ferauu und seine verbliebenen Banditen können jeden Augenblick eintreffen, und sie muss sich ihrem Angriff stellen.",al={"was geschieht nach the hills have eyes","nächste quest aamelia","ferauus angriff"}}},fp="19,175,19.295.0,28.357.1,28.177.0,40.136.0,14.130.0,41.136.0,49.140.0,40.161.0"}
P.entries["quest:92693"] = {n="Standing Our Ground",s="Aamelia Windfield gibt Euch eine letzte Chance, nach Valanaar zurückzuweichen, bevor die Banditen näher rücken. Ihr habt den örtlichen Verteidigern bei den Vorbereitungen geholfen, doch der bevorstehende Kampf scheint noch immer aussichtslos.",h="Aamelia Windfield gibt Euch eine letzte Chance, nach Valanaar zurückzuweichen, bevor die Banditen näher...",kw={"aamelia windfield","banditenanführer","banditen","aussichtsloser kampf","standing our ground","valanaar"},sec={{t="Ein verzweifeltes letztes Gefecht",b="Aamelia Windfield gibt Euch eine letzte Chance, sicher nach Valanaar zurückzukehren. Ihr habt den örtlichen Verteidigern geholfen, sich auf die Banditen vorzubereiten, doch der bevorstehende Kampf verheißt nichts Gutes. Werdet Ihr ihnen beistehen oder vor dem Zusammenstoß gehen?"},{t="Dem Banditenanführer entgegentreten",b="Wenn Ihr Eure Bereitschaft signalisiert, zieht Ihr mit Aamelia Windfield los, um Euch dem Banditenanführer zu stellen. Der Sieg über den Briganten beendet die unmittelbare Bedrohung. Aamelia ringt nach Atem, fassungslos und erleichtert, dass ihr Wagnis gelungen ist."}},faq={{q="Wer vergibt die Quest Standing Our Ground?",a="Aamelia Windfield gibt Euch eine letzte Chance zum Rückzug, bevor Ihr Euch dem Banditenanführer stellt.",al={"wer vergibt standing our ground","questgeber standing our ground","standing our ground npc"}},{q="Gegen wen kämpft Ihr in Standing Our Ground?",a="Ihr stellt Euch dem Banditenanführer, der die örtlichen Verteidiger bedroht. Aamelia nimmt ihren Mut zusammen und tritt dem Anführer mit Euch entgegen.",al={"wer ist der banditenanführer standing our ground","standing our ground boss","banditenanführer standing our ground"}},{q="Welche Rolle spielt Valanaar bei dieser Quest?",a="Valanaar ist die nahe gelegene Siedlung, in die Aamelia Euch den Rückzug anbietet, falls Ihr im Kampf nicht Euer Leben riskieren wollt.",al={"wo liegt valanaar standing our ground","standing our ground rückzugsort","valanaar quest"}},{q="Warum bezeichnet Aamelia die Schlacht als aussichtslos?",a="Aamelia und ihre Gefährten glauben, dass die Chancen gegen sie stehen. Sie sehen die Konfrontation als verzweifeltes letztes Gefecht, und ohne Hilfe von außen scheint ein Überleben fast unmöglich.",al={"warum ist standing our ground aussichtslos","standing our ground geschichte","aamelia windfield kampf"}},{q="Was geschieht nach der Konfrontation?",a="Der Banditenanführer ist besiegt. Aamelia Windfield ist fassungslos und erleichtert, dass die Tortur vorüber ist, und versucht mühsam, ihr rasendes Herz zu beruhigen.",al={"was geschieht nach dem sieg über den banditenanführer standing our ground","standing our ground abgeben","überlebt aamelia"}},{q="Was führt zu diesem letzten Gefecht?",a="Ihr habt den Verteidigern geholfen, sich auf die Bedrohung durch die Banditen vorzubereiten, und ihnen so vor der letzten Konfrontation eine Chance gegeben.",al={"standing our ground voraussetzungen","quests vor standing our ground"}}},fp="19,181,22.219.0,29.228.1,40.89.0,40.122.0,43.129.0,53.169.0,44.139.0,34.117.0"}
P.entries["quest:92698"] = {n="What Is My Purpose?",s="Auf den Feldern des Obsthains wandert ein Malfunctioning Cyclone Construct ziellos umher. Seit Jahrzehnten wiederholt es seine bruchstückhaften Worte, seit die Windelementare fortgingen. Aamelia Windfield weiß, woran sich die Einheimischen aus seiner Vergangenheit erinnern.",h="Auf den Feldern des Obsthains wandert ein Malfunctioning Cyclone Construct ziellos umher.",kw={"aamelia windfield","alvarion","konstrukt","zyklonkonstrukt","malfunctioning cyclone construct","obsthain","was ist meine bestimmung","windelementare","windformer"},ang={["class:Shaman"]="Als Schamane interessiert Ihr Euch vielleicht für den Verfall des Konstrukts. Örtliche Berichte bringen seine Vernachlässigung und sein Versagen mit dem Fortgang der Windelementare in Verbindung.",["profession:Engineering"]="Als Ingenieur findet Ihr die alten Mechanismen des Konstrukts vielleicht faszinierend. Ihre Logik läuft nach Jahrhunderten des Verschleißes ohne Wartung noch immer in Schleifen."},sec={{t="Das wandernde Konstrukt",b="Ein Malfunctioning Cyclone Construct schreitet durch die Felder, gefangen in einer fehlerhaften Schleife. Unter seiner Panzerung erklingen gedämpfte Wortfetzen, die immer wieder Fehler und Fragen nach seiner Bestimmung wiederholen. Nach Jahrzehnten der Einsamkeit sind seine alten Anweisungen beschädigt oder vergessen. Es wirkt imposant, bedroht aber niemanden, der vorbeikommt. Seine stockende Stimme trägt über den Boden, während es ziellos umherwandert."},{t="Vergessene Arbeit und die Windformer",b="Aamelia Windfield sagt, das Konstrukt durchstreife die Felder seit Jahrzehnten, offenbar seit die Windelementare fortgingen. Alvarion vermutete, es habe vor Jahrhunderten Ernten zu fernen Märkten gebracht oder Vieh gehütet, bevor das Land zum Obsthain wurde. Die Windformer bauten und warteten in früheren Zeitaltern Zyklonkonstrukte. Die Arbeiter des Obsthains haben darüber gesprochen, sie um die Reparatur der Maschine zu bitten, doch die Angelegenheit schien nie dringend. So streift es weiter umher, weitgehend unbeachtet."}},faq={{q="Was ist das Malfunctioning Cyclone Construct?",a="Das Malfunctioning Cyclone Construct ist eine uralte gepanzerte Maschine, die durch die hiesigen Felder wandert. Einst warteten die Windformer es, doch nach Jahrzehnten ohne Pflege ist es verfallen. Unter seiner Panzerung wiederholt es abgehackte Worte und Fehlermeldungen und fragt nach seiner Bestimmung.",al={"was ist das konstrukt","zyklonkonstrukt","riesiges konstrukt auf den feldern"}},{q="Wer ist Aamelia Windfield?",a="Aamelia Windfield lebt nahe dem Obsthain. Sie sagt, das Konstrukt schreite seit Jahrzehnten durch die Felder, offenbar seit die Windelementare fortgingen. Einst kümmerten sich die Windformer um solche Maschinen.",al={"aamelia windfield","wer ist aamelia","nsc im obsthain"}},{q="Was war die ursprüngliche Bestimmung des Konstrukts?",a="Die ursprüngliche Bestimmung des Konstrukts ist unbekannt. Aamelia Windfield sagt, Alvarion habe vermutet, es könnte vor Jahrhunderten Ernten zum Markt gebracht oder Vieh gehütet haben, bevor der Obsthain entstand.",al={"bestimmung des konstrukts","was hat das konstrukt getan","aufgabe des konstrukts"}},{q="Wer sind die Windformer?",a="Die Windformer sind eine uralte Gruppe, die Zyklonkonstrukte baute und wartete. Hiesige Landarbeiter haben darüber gesprochen, sie um Hilfe zu bitten, doch das Konstrukt hat bisher keinen Anlass zu dringender Sorge gegeben.",al={"windformer","wer hat das konstrukt gebaut","wer wartet zyklonkonstrukte"}},{q="Warum wiederholt das Konstrukt Wortfetzen?",a="Das Konstrukt wiederholt Wortfetzen, weil sein Betrieb gestört ist. Seit Jahrzehnten hat sich niemand darum gekümmert, seit die Windelementare fortgingen. Es stellt Fragen nach seiner Bestimmung und meldet Fehler.",al={"warum spricht das konstrukt","funktionsfehler konstrukt","was sagt es"}},{q="Warum haben die Einheimischen das Konstrukt weder repariert noch zerlegt?",a="Die Einheimischen haben das Konstrukt weder repariert noch zerlegt, weil es friedlich zwischen den Bäumen und Feldfrüchten des Obsthains umherwandert und keine Bedrohung darstellt. Aamelia Windfield und andere Bewohner haben darüber gesprochen, die Windformer um seine Wartung zu bitten, doch ein dringender Bedarf bestand bisher nicht.",al={"warum das konstrukt ignorieren","warum das konstrukt nicht reparieren","ist das konstrukt gefährlich"}},{q="Wer ist Alvarion?",a="Alvarion ist ein Einheimischer, den Aamelia Windfield erwähnt, wenn sie über die Vergangenheit des Konstrukts spricht. Er vermutete, es könnte einst Ernten zum Markt gebracht oder Vieh gehütet haben, bevor das Land zum Obsthain wurde.",al={"alvarion","wer ist alvarion","alvarions theorie"}}},fp="19,220,23.373.0,35.470.0,45.276.0,25.191.0,42.187.0,24.182.0,48.216.0,60.264.0,16.201.0"}
P.entries["quest:92699"] = {n="The Supreme Magister",s="In Valanaar führt Elaadrin Evengale Neuankömmlinge zum Hohen Orden. Von einer Hütte im Südosten der Siedlung aus sucht der Orden Verbündete gegen feindselige Windformer und einen nahen Kult.",h="In Valanaar führt Elaadrin Evengale Neuankömmlinge zum Hohen Orden.",kw={"arkan","kult","elaadrin evengale","der hohe orden","rathiril","the supreme magister","valanaar","windformer"},ang={["class:Mage"]="Als Magier tragt Ihr eine arkane Aura, die Elaadrin erkennt. Er schätzt die seltene Begabung und Entschlossenheit, die nötig sind, um das Arkane zu meistern und Eure Heimat zu bewahren."},sec={{t="Der Hohe Orden von Valanaar",b="Vielversprechende Neuankömmlinge in Valanaar werden an den Hohen Orden verwiesen. Supreme Magister Elaadrin Evengale führt ihn von einer Hütte im äußersten Südosten der Siedlung aus. Er beobachtet Neuankömmlinge genau und sucht nach Stärke, Entschlossenheit und einer arkanen Aura, um den Gefahren zu begegnen, die ihre Heimat bedrohen."},{t="Verfeindete Fraktionen und drohende Kulte",b="Der Frieden in Valanaar ist zerbrechlich. Der Hohe Orden und die Windformer sind erbitterte Feinde, weshalb Neuankömmlinge gewarnt werden, sich von den Windformern fernzuhalten, damit keine Gewalt auf den Straßen ausbricht. Ein gefährlicher Kult lauert in der Nähe. Angesichts der Bedrohungen außerhalb der Stadt können sich ihre Anführer kein Blutvergießen innerhalb ihrer Mauern leisten."}},faq={{q="Wer ist Elaadrin Evengale?",a="Elaadrin Evengale führt den Hohen Orden als dessen Supreme Magister. Von einer Hütte im Südosten Valanaars aus sucht er Menschen mit arkaner Begabung und der Entschlossenheit, ihre Heimat zu verteidigen.",al={"wer ist elaadrin evengale","elaadrin evengale","wer ist der supreme magister"}},{q="Wo ist Elaadrin Evengale zu finden?",a="Elaadrin Evengale und seine Anhänger wirken von einer Hütte im äußersten Südosten Valanaars aus.",al={"wo ist supreme magister","wo ist elaadrin evengale zu finden","standort der hütte in valanaar"}},{q="Was ist der Hohe Orden?",a="Der Hohe Orden ist eine arkane Organisation in Valanaar unter der Führung von Supreme Magister Elaadrin Evengale. Seine Mitglieder setzen arkane Macht ein, um ihre Heimat zu verteidigen, doch ihre Zahl schwindet und die Spannungen in der Siedlung nehmen zu.",al={"was ist der hohe orden","geschichte des hohen ordens"}},{q="Warum gibt es einen Konflikt zwischen dem Hohen Orden und den Windformern?",a="Der Hohe Orden und die Windformer sind erbitterte Rivalen in Valanaar. Die örtlichen Anführer drängen sie, einander fernzubleiben und Gewalt auf den Straßen zu verhindern, besonders angesichts der Kultaktivitäten, die die Siedlung bedrohen.",al={"warum kämpfen der hohe orden und die windformer","konflikt mit den windformern","spannungen in valanaar"}},{q="Wer ist Rathiril?",a="Rathiril verweist vielversprechende Neuankömmlinge durch magische Schreiben an den Hohen Orden in Valanaar. Diese Nachrichten machen Elaadrin Evengale auf Menschen mit beachtlichem Potenzial aufmerksam.",al={"wer ist rathiril","rathirils schreiben"}},{q="Welcher Kult bedroht Valanaar?",a="Ein geheimnisvoller Kult, der in der Umgebung Valanaars aktiv ist, bedroht die Siedlung. Die örtlichen Obrigkeiten bemühen sich, Konflikte zwischen Gruppen wie dem Hohen Orden und den Windformern beizulegen, um Valanaar zu schützen.",al={"welcher kult ist in valanaar","kultbedrohung in valanaar"}}},fp="20,192,26.282.0,32.298.0,25.178.0,37.84.0,23.227.0,65.198.0,16.163.0,29.190.0"}
P.entries["quest:927"] = {n="Das moosumschlungene Herz",s="Nahe dem Al'Amethsee untersucht Denalan ein Herz, das Faulmoos dem Scheusal entnommen wurde. Dunkles, öliges Moos bedeckt den Kern, doch er schlägt weiter, nachdem er aus dem Holzkoloss geschnitten wurde.",h="Nahe dem Al'Amethsee untersucht Denalan ein Herz, das Faulmoos dem Scheusal entnommen wurde.",kw={"faulmoos dem scheusal","seuche","verderbnis","denalan","al'amethsee","moosumschlungenes herz","teldrassil","holzkoloss"},ang={["class:Druid"]="Als Druide hegt Ihr großes Interesse an einem schlagenden, verseuchten Herz wie diesem. Ihr wollt herausfinden, ob sich seine Verderbnis läutern lässt oder auf tiefere Fäulnis hindeutet.",["profession:Herbalism"]="Als Pflanzenkundiger erkennt Ihr, dass der ölige Bewuchs auf diesem Kern unnatürlich ist. Er widerspricht gewöhnlichen botanischen Eigenschaften, indem er ein herausgetrenntes Herz am Leben hält.",["race:NightElf"]="Als Kaldorei seht Ihr, wie der junge Weltbaum Teldrassil verderbte, aggressive Holzkolosse wie Faulmoos hervorbringt. Ihre Seuche ist ein ernüchterndes Zeichen dafür, dass Eure neue Heimat an einer schleichenden Krankheit leidet."},sec={{t="Ein schlagender Kern",b="Das Herz von Faulmoos dem Scheusal schlägt weiter, nachdem es aus dem Holzkoloss geschnitten wurde. Dunkles, öliges Moos verdeckt fast den gesamten Kern, doch in seinem Inneren hält ein langsamer Rhythmus an. Dieser Puls deutet auf eine Verderbnis hin, die über gewöhnliche Fäulnis in Teldrassils wilden Pflanzen hinausgeht."},{t="Denalans Untersuchung",b="Denalan untersucht die heimische Pflanzenwelt nahe dem Al'Amethsee, und das Herz weckt sein lebhaftes Interesse. Er erkennt die beunruhigende Verderbnis darin. Holzkolosse sollten sanftmütige Wesen sein, die mit den Ästen des Weltbaums verbunden sind, doch dieser Kern trägt eine bösartige Seuche in sich.\n\nBesorgt über das Gesehene und begierig, es zu verstehen, plant Denalan, das Organ einzupflanzen und zu untersuchen. Er hofft zu erfahren, wie übles Moos im Boden der Insel Wurzeln schlägt."}},faq={{q="Woher stammt das Moosumschlungene Herz?",a="Das Herz stammt von Faulmoos dem Scheusal, einem großen, stark verderbten Holzkoloss, der durch Teldrassils Wildnis streift.",al={"woher bekommt man das herz","moosumschlungenes herz beute","faulmoos dem scheusal herz"}},{q="Warum schlägt das Herz noch?",a="Dunkles, öliges Moos scheint das Herz mit unnatürlicher Lebenskraft am Leben zu halten. Obwohl es aus dem Holzkoloss geschnitten wurde, schlägt es langsam und gleichmäßig weiter.",al={"warum pulsiert das herz","noch schlagendes herz","holzkoloss herzschlag"}},{q="Wer ist Denalan?",a="Denalan ist ein Nachtelf und Naturforscher, der eine Baumschule nahe dem Al'Amethsee pflegt. Er untersucht Teldrassils Pflanzenwelt, ihre Sprösslinge und die schleichende Verderbnis, die die Holzkolosse der Insel befällt.",al={"wer ist denalan","wo ist denalan","denalan standort"}},{q="Was wird Denalan mit dem Herz tun?",a="Denalan plant, das Herz in ein verzaubertes Pflanzgefäß einzupflanzen, damit es sprießen kann. Indem er das üble Moos isoliert, hofft er, die Ursache des verseuchten Wachstums aufzudecken.",al={"was geschieht mit dem herz","planting the heart quest","denalan herzforschung"}},{q="Was sollten Holzkolosse eigentlich sein?",a="Holzkolosse sind von Natur aus friedliche Pflanzenelementare, die dem Wald entstammen. Dunkle Mächte und unnatürliche Verderbnis haben viele von ihnen in ganz Teldrassil wahnsinnig und aggressiv gemacht.",al={"was sind holzkolosse","holzkoloss hintergrundgeschichte","sind holzkolosse böse"}},{q="Ist die Verderbnis am Herz magisch oder natürlich?",a="Das ölige, üble Moos deutet auf eine unnatürliche Seuche in Teldrassils heimischen Pflanzen hin, statt auf gewöhnlichen Verfall in der Wildnis.",al={"ist das moos magisch","ursprung des üblen mooses","teldrassil moosseuche"}}},fp="21,166,14.241.0,21.405.0,43.120.0,31.138.0,15.184.0,36.156.0,36.158.0,50.119.0"}
P.entries["quest:92700"] = {n="The Grand Skyseer",s="In Valanaar suchen die Windformer nach Reisenden mit spiritueller Sicht. Sie schicken Euch zu Ayessa Dawnsinger in ihre Hütte, während Rivalitäten und ein bedrohlicher Kult die Siedlung belasten.",h="In Valanaar suchen die Windformer nach Reisenden mit spiritueller Sicht.",kw={"ayessa dawnsinger","elder amberwind","der hohe orden","shen'dar","himmelssicht","the grand skyseer","valanaar","windformer","zephras"},ang={["class:Druid"]="Als Druide könntet Ihr unter den Windformern Gleichgesinnte finden. Sie spüren spirituelle Auren und beobachten feine Veränderungen am Himmel.",["class:Shaman"]="Als Schamane könntet Ihr in Ayessa Dawnsinger eine wichtige Ansprechpartnerin finden. Sie erkennt Reisende, die mit den Geistern im Einklang stehen und in spirituellen Dingen begabt sind."},sec={{t="Ankunft in Valanaar",b="Ihr kommt in Valanaar an und werdet zur zentralen Hütte geschickt. Dort versammeln sich die Windformer unter Grand Skyseer Ayessa Dawnsinger. Elder Amberwind hat von Euren Taten in Shen'dar gehört und heißt Euch unter jenen willkommen, die mit den Geistern im Einklang stehen. Gefahren bedrängen die Stadt von außen und innen, also bewegt Euch vorsichtig durch ihr zerbrechliches politisches Gefüge."},{t="Rivalitäten und drohende Kulte",b="Der Frieden in Valanaar hängt an einem seidenen Faden. Die Windformer und der Hohe Orden stehen einander offen feindlich gegenüber, und Straßenkämpfe bedrohen die Siedlung. Auch ein schattenhafter Kult bedroht die Region. Die örtlichen Anführer haben beiden Fraktionen befohlen, Abstand voneinander zu halten und sich dieser gemeinsamen Gefahr zu stellen, statt um Gebiete zu kämpfen."},{t="Die schwindende Himmelssicht",b="Grand Skyseer Ayessa Dawnsinger sagt, dass die Himmelssicht unter den Bewohnern von Zephras selten wird. Wer mit einer starken Aura und im Einklang mit den Geistern eintrifft, ist ein unverzichtbarer Verbündeter. Die Windformer brauchen diese Reisenden, während sie ihr Land durch schwere Zeiten führen."}},faq={{q="Wer ist die Grand Skyseer?",a="Ayessa Dawnsinger führt die Windformer in Valanaar als ihre spirituelle Wegweiserin. Sie empfängt Reisende in der Hütte nahe dem Zentrum der Siedlung, besonders jene, die mit den Geistern im Einklang stehen und die seltene Gabe der Himmelssicht besitzen.",al={"wer ist die grand skyseer","ayessa dawnsinger wer ist sie","wer ist ayessa"}},{q="Wo ist Ayessa Dawnsinger zu finden?",a="Ayessa Dawnsinger ist in der Hütte der Windformer nahe dem Zentrum von Valanaar zu finden. Sie erwartet Reisende aus Shen'dar, die von Elder Amberwind Kunde über ihre jüngsten Taten mitbringen.",al={"wo ayessa dawnsinger finden","wo ist die hütte der grand skyseer","ayessa standort valanaar"}},{q="Wer sind die Windformer?",a="Die Windformer sind eine spirituelle Gemeinschaft in Valanaar, die dort von Grand Skyseer Ayessa Dawnsinger angeführt wird. Sie erforschen den Himmel und treten mit den Geistern in Verbindung, während die Spannungen mit dem Hohen Orden groß sind.",al={"was sind die windformer","windformer fraktion valanaar"}},{q="Warum geraten die Windformer mit dem Hohen Orden aneinander?",a="Die Windformer und der Hohe Orden streiten über die Windgeister. Der Hohe Orden misstraut deren Beweggründen und will die Kräfte des Himmelswalls verstehen. Die Windformer vertrauen den Elementaren und empfinden diese Zweifel als Beleidigung. Gewalt auf den Straßen ist verboten, besonders da ein Kult die Region bedroht.",al={"windformer hoher orden konflikt","warum ist der hohe orden wütend auf die windformer","hoher orden valanaar"}},{q="Was ist die Gabe der Himmelssicht?",a="Himmelssicht ist eine seltene spirituelle Wahrnehmung, die nur wenige Bewohner von Zephras besitzen. Sie lässt sie spirituelle Auren spüren und mit unsichtbaren Kräften in Verbindung treten. Ayessa sagt, dass die Gabe immer seltener wird, wodurch ihre Träger in diesen schweren Zeiten unverzichtbar sind.",al={"was ist himmelssicht","himmelssicht gabe zephras"}},{q="Wer ist Elder Amberwind?",a="Elder Amberwind ist ein angesehener Ältester in Shen'dar. Elder Amberwind beurteilt Reisende und schickt Kunde über ihre Taten und ihren Einklang mit den Geistern nach Valanaar. Der Älteste verweist die Würdigen an Grand Skyseer Ayessa Dawnsinger.",al={"wer ist elder amberwind","amberwind shen'dar"}}},fp="17,185,19.340.0,27.313.0,19.244.0,25.226.0,37.185.0,24.199.0,49.292.0,29.232.0,23.222.0"}
P.entries["quest:92701"] = {n="To Valanaar",s="In Valanaar muss sich Valennia Stormfist der wachsenden Bedrohung durch den Kult stellen. Aonda schickt dringende Neuigkeiten aus Shen'dar, wo das Dorf und sein Pylon verteidigt wurden.",h="In Valanaar muss sich Valennia Stormfist der wachsenden Bedrohung durch den Kult stellen.",kw={"aonda","kult","friedenshüter","pylon","shen'dar","to valanaar","valanaar","valennia stormfist"},sec={{t="Botschaft aus Shen'dar",b="Nachdem Shen'dar und sein Pylon verteidigt wurden, schickt Aonda einen vertrauenswürdigen Boten quer über die Insel. Die Botschaft ist für Valanaar am südöstlichen Rand der Insel bestimmt. Dort muss die Kommandantin der Friedenshüter erfahren, wie schnell der Kult vordringt."},{t="Der aufziehende Sturm",b="Valennia Stormfist und ihre Friedenshüter versuchen seit Langem, einen offenen Konflikt mit dem Kult zu vermeiden, der sich auf der Insel ausbreitet. Doch die Ereignisse in Shen'dar markieren einen Wandel. Der Einfluss des Kults wächst, und Valennia kann einem Zusammenstoß nicht länger ausweichen. Ihre schwindende Truppe muss Valanaar auf einen Angriff vorbereiten."}},faq={{q="Wer ist Valennia Stormfist?",a="Valennia Stormfist befehligt die in Valanaar stationierten Friedenshüter. Sie ist mit dem Schutz der Inselbewohner betraut, während ihre kleine Garnison mit zunehmenden Aktivitäten des Kults konfrontiert ist.",al={"wer ist valennia stormfist","valennia","anführerin der friedenshüter"}},{q="Wer ist Aonda?",a="Aonda ist eine Hochländerin, die in Shen'dar stationiert ist. Nachdem sie einen Pylon gesichert und das Dorf gegen Kultisten verteidigt hat, vertraut sie einem Reisenden ihren schriftlichen Bericht für Valennia an.",al={"wer hat den bericht geschickt","gewitzte hochländerin","aonda"}},{q="Was ist Valanaar?",a="Valanaar liegt am südöstlichen Rand der Insel. Es ist der Stützpunkt von Valennia Stormfist und den Friedenshütern, die die Inselbewohner verteidigen.",al={"was ist valanaar","wo liegt valanaar","lage von valanaar"}},{q="Was ist das für ein Kult, der die Insel bedroht?",a="Ein rasch wachsender Kult breitet sich auf der Insel aus und dringt in Siedlungen und zu heiligen Pylonen vor. Die Friedenshüter vermieden einst direkte Zusammenstöße, doch nun müssen sich die Verteidiger von Valanaar auf den Kampf vorbereiten.",al={"welcher kult","wer greift an","ausbreitung des kults"}},{q="Was ist Shen'dar?",a="Shen'dar ist ein Dorf nahe einem lebenswichtigen Pylon auf der Insel. Seine Bewohner haben kürzlich Kultisten zurückgeschlagen, um das Dorf und den Pylon zu schützen, und seine Anführer pflegen enge Verbindungen zu den Friedenshütern in Valanaar.",al={"was ist shendar","shen'dar","dorf am pylon"}},{q="Was steht in Aondas Bericht?",a="Aondas schriftlicher Bericht schildert die Verteidigung von Shen'dar und seinem Pylon. Er warnt Valennia, dass sich der Kult zu schnell ausbreitet, als dass sich ein direkter Konflikt noch vermeiden ließe.",al={"was steht in aondas bericht","inhalt des schriftlichen berichts","was steht im brief"}}},fp="11,154,22.249.0,19.303.0,26.173.0,13.170.0,17.143.0,40.200.0,17.194.0,36.162.0"}
P.entries["quest:92703"] = {n="Deliver the News",s="Am Obsthain der Windfields lässt Aamelia ausrichten, dass ihre Familie in Sicherheit ist. Alvarion wartet in Valanaar, wohin er ging, um Hilfe zu suchen.",h="Am Obsthain der Windfields lässt Aamelia ausrichten, dass ihre Familie in Sicherheit ist.",kw={"aamelia","alvarion windfield","konstrukt","deliver the news","obsthain","der himmelswall","valanaar","windfield","windformer"},ang={["race:Skyborne"]="Als Skyborne hört Ihr, wie Alvarion sich an die Helden erinnert, die sein Volk vor seiner Ankunft im Himmelswall aus Geschichten kannte. Die Erinnerung an sie ruft die Wurzeln und das Erbe Eures Volkes vor der Migration wach."},sec={{t="Erleichterung am Obsthain",b="Aamelia dankt Euch dafür, dass Ihr den Obsthain der Windfields gerettet habt. Ihr Zuhause ist sicher, doch Alvarion Windfield ist nach Valanaar gegangen, um dort um Hilfe zu flehen. Er muss erfahren, dass seine Familie und sein Zuhause außer Gefahr sind."},{t="Ein Geheimnis für die Zukunft",b="Aamelia bittet Alvarion, nach seiner Genesung einen fähigen Windformer zu finden. Ein Konstrukt ist am Obsthain zurückgeblieben, und ein Experte muss es untersuchen, um sicherzustellen, dass es keine Bedrohung darstellt.\n\nAamelia erwartet ein Kind. Sie bittet Euch, Alvarion die Neuigkeit zu verschweigen, bis er wohlbehalten persönlich nach Hause zurückkehrt."},{t="Ein Held in Valanaar",b="Alvarion Windfield wird von Gefühlen überwältigt, als Ihr ihm erzählt, dass seine Familie und sein Zuhause in Sicherheit sind. Er ging nach Valanaar in dem Glauben, seine Suche nach Hilfe sei eine verzweifelte, beinahe vergebliche Hoffnung. Euer Erfolg erinnert ihn an die legendären Helden, die seinem Volk aus der Zeit vor seiner Ankunft im Himmelswall in Erinnerung geblieben waren. Im Zuhause der Familie Windfield seid Ihr fortan immer willkommen."}},faq={{q="Was ist die Quest Deliver the News?",a="Aamelia bittet Euch, nach Valanaar zu gehen und ihrem Partner Alvarion Windfield zu sagen, dass sie in Sicherheit und die Gefahr am Obsthain vorüber ist.",al={"deliver the news quest","was ist deliver the news","wer vergibt deliver the news"}},{q="Wer ist Alvarion Windfield?",a="Alvarion Windfield lebt im Himmelswall und erholt sich in Valanaar. Er brach in die Stadt auf, um Hilfe für den Obsthain seiner Familie zu suchen, und fürchtete vor Eurer Ankunft, alle Hoffnung sei verloren.",al={"wer ist alvarion windfield","wo ist alvarion","alvarion aufenthaltsort"}},{q="Wer ist Aamelia?",a="Aamelia lebt auf dem Hof der Familie Windfield und kümmert sich gemeinsam mit Alvarion um den Obsthain. Dankbar für Eure Hilfe bittet sie Euch, ihm in Valanaar die Nachricht zu überbringen, dass sie in Sicherheit sind.",al={"wer ist aamelia","questgeberin aamelia"}},{q="Was hält Aamelia vor Alvarion geheim?",a="Aamelia erzählt Euch, dass sie ein Kind erwartet. Sie bittet Euch, Alvarion die Neuigkeit zu verschweigen, bis er wieder auf den Beinen ist und nach Hause zurückkehrt.",al={"was ist aamelias geheimnis","aamelia berührt ihren bauch","ist aamelia schwanger"}},{q="Warum möchte Aamelia einen Windformer zum Obsthain holen lassen?",a="Aamelia möchte, dass Alvarion nach seiner Genesung einen Windformer zum Obsthain bringt. Der Fachmann kann dort ein Konstrukt untersuchen und sicherstellen, dass es keine Gefahr für ihre wachsende Familie darstellt.",al={"warum windformer konstrukt","welches konstrukt erwähnt aamelia","windfield konstrukt"}},{q="Wo spielt diese Quest?",a="Die Geschichte führt Euch vom Obsthain der Windfields nach Valanaar, einer Siedlung im Himmelswall, in der diese Siedler ein Zuhause gefunden haben.",al={"wo spielt deliver the news","valanaar himmelswall quest"}}},fp="16,125,21.196.0,23.287.1,18.337.0,35.135.0,26.168.0,15.161.0,44.134.0,58.181.0,33.126.0"}
P.entries["quest:92706"] = {n="WANTED: Bruuz",s="Bruuz bedroht die Schiffe, die Ratschets Hafen beleben. Gazlowe hat ein Kopfgeld auf den riesigen Hai ausgesetzt, der an den Docks umherstreift und den Küstenhandel stört.",h="Bruuz bedroht die Schiffe, die Ratschets Hafen beleben.",kw={"brachland","kopfgeld","bruuz","rückenflosse","gazlowe","ratschet","hai","steamwheedle"},ang={["class:Hunter"]="Als Jäger könnt Ihr Eure Geduld und Treffsicherheit an Bruuz erproben, einem riesigen Raubtier der Gewässer.",["profession:Cooking"]="Als Koch könntet Ihr frisches Fleisch von einem so großen Hai wie Bruuz aus den Küstengewässern verwerten. Gazlowe will nur die Rückenflosse als Beweis für die Tötung."},sec={{t="Schrecken in der Bucht",b="Ratschet ist Kalimdors wichtigstes neutrales Tor zu den Östlichen Königreichen. Sein Handel hängt von Handelsschiffen ab. Seit Kurzem streift ein riesiger Hai namens Bruuz durch die Bucht. Hafenarbeiter gaben ihm diesen Namen, nachdem er begonnen hatte, kleine Boote, Seeleute und nahe den Docks entladene Fracht anzugreifen. Der Hai stört den Hafenbetrieb und gefährdet die Schiffe, die Ratschet versorgen."},{t="Gazlowes Kopfgeld",b="Gazlowe hat öffentlich ein Kopfgeld ausgesetzt, damit Schiffe seinen Hafen nicht aus Angst vor dem Hai meiden. Der Aushang ruft Angler auf und verspricht eine saftige Belohnung. Um sie einzufordern, müsst Ihr Bruuz erlegen und die Rückenflosse des Hais als Beweis zurückbringen."}},faq={{q="Wer ist Bruuz?",a="Bruuz ist ein riesiger, aggressiver Hai, der nahe Ratschets Hafendocks jagt. Hafenarbeiter gaben ihm seinen Namen nach seinen Angriffen auf Seeleute und kleine Schiffe.",al={"was ist bruuz","bruuz hai","wer ist bruuz der hai"}},{q="Warum hat Gazlowe ein Kopfgeld auf Bruuz ausgesetzt?",a="Bruuz stört die Schifffahrt und den Handel, die Ratschets Wirtschaft antreiben. Gazlowe bietet Geld für den Kadaver des Hais, um die Geschäfte an den Docks zu schützen.",al={"warum bruuz töten","gazlowe hai quest","warum bruuz' flosse verlangt wird"}},{q="Wo ist Bruuz gewöhnlich zu finden?",a="Bruuz durchstreift die Gewässer vor Ratschet im Brachland, oft nahe den wichtigsten Hafenstegen und der Hafeneinfahrt.",al={"bruuz fundort","wo ist bruuz","bruuz finden"}},{q="Welchen Beweis verlangt Gazlowe für die Tötung?",a="Gazlowe verlangt Bruuz' Rückenflosse als Beweis dafür, dass der Hai erlegt wurde, bevor er das Kopfgeld auszahlt.",al={"bruuz abgeben","was gazlowe bringen","bruuz' rückenflosse"}},{q="Können Abenteurer sowohl der Allianz als auch der Horde diesen Kopfgeldauftrag annehmen?",a="Ja. Ratschet wird vom neutralen Steamwheedle Cartel geführt, und Gazlowe heißt fähige Abenteurer beider Fraktionen willkommen, die sich um den Hai kümmern.",al={"ist gesucht bruuz neutral","kann die horde gesucht bruuz machen","kann die allianz bruuz machen"}},{q="Warum richtet sich der Kopfgeldaushang ausdrücklich an Angler?",a="Der Aushang erklärt nicht, warum er sich an Angler richtet. Er beginnt mit „Aufruf an alle Angler!“ und verspricht eine saftige Belohnung für Bruuz' Flosse.",al={"aufruf an alle angler bruuz","ist das eine angelquest"}}},fp="13,145,19.347.0,16.231.0,13.141.0,39.144.0,29.107.0,45.101.0,57.140.0,50.139.0"}
P.entries["quest:92708"] = {n="A Grand Adventure",s="Auf der Insel Zephras suchen Ayessa Dawnsinger und die Windformer einen Weg, ihre Heimat zu retten. Die Insel liegt im Himmelswall, wo Windgeister ohne Erklärung verschwunden sind.",h="Auf der Insel Zephras suchen Ayessa Dawnsinger und die Windformer einen Weg, ihre Heimat zu retten.",kw={"a grand adventure","ayessa dawnsinger","azeroth","der himmelswall","windgeister","windformer","insel zephras"},ang={["race:Skyborne"]="Als Skyborne des Himmelswalls steht Ihr vor einer großen Veränderung. Ihr verlasst Eure elementare Heimat, um auf Azeroth Rettung für die Insel Zephras zu suchen."},sec={{t="Die Krise auf der Insel Zephras",b="Windgeister sind von der Insel Zephras verschwunden, und die Probleme werden immer größer. Die Windformer haben die Störungen untersucht und Wahrheiten über ihre vermissten Verwandten und das Schicksal ihrer elementaren Heimat aufgedeckt. Ayessa Dawnsinger bittet Euch, ihre Erkenntnisse zu beherzigen und Euch auf ein Unterfangen vorzubereiten, wie es noch keines gab."},{t="Ein Wagnis jenseits des Himmelswalls",b="Ayessa Dawnsinger glaubt, dass dem Himmelswall die Macht und das Wissen fehlen, um die Insel Zephras zu retten. Sie ist zu dem Schluss gekommen, dass die Rettung unten liegt, in der Welt der Sterblichen auf Azeroth. Ihre Heimat zu verlassen, bricht mit der Tradition. Die Zukunft der Insel hängt von jenen ab, die bereit sind, sich ins Unbekannte zu wagen."}},faq={{q="Was ist die Quest A Grand Adventure?",a="Ayessa Dawnsinger bittet um Hilfe, da Windgeister von der Insel Zephras verschwinden. Die Windformer glauben, dass sie sich über den Himmelswall hinaus nach Azeroth wagen müssen, um ihre Heimat zu retten.",al={"was ist diese quest","grand adventure quest","was ist a grand adventure"}},{q="Wer ist Ayessa Dawnsinger?",a="Ayessa Dawnsinger gehört zu den Windformern auf der Insel Zephras. Sie untersucht die Krise und bittet fähige Abenteurer, die Erkenntnisse der Windformer zu beherzigen.",al={"wer ist ayessa","dawnsinger","wer ist ayessa dawnsinger"}},{q="Welche Krise spielt sich auf der Insel Zephras ab?",a="Windgeister sind ohne Erklärung von der Insel Zephras verschwunden. Die Windformer untersuchen die Störungen und suchen einen Weg, ihre Heimat zu retten.",al={"was ist die krise auf der insel zephras","was geschah auf der insel zephras","zephras problem"}},{q="Wer sind die Windformer?",a="Die Windformer untersuchen die Störungen und das Verschwinden der Windgeister, die die Insel Zephras bedrohen.",al={"wer sind die windformer","windformer zephras"}},{q="Warum müssen die Windformer nach Azeroth reisen?",a="Ayessa Dawnsinger glaubt, dass dem Himmelswall die Macht und das Wissen fehlen, um die Insel Zephras zu retten. Sie glaubt, dass sie unten auf Azeroth nach Rettung suchen müssen.",al={"warum nach azeroth reisen","warum den himmelswall verlassen","weg zur rettung"}},{q="Was ist der Himmelswall?",a="Der Himmelswall ist das elementare Heimatreich der Windformer und der Insel Zephras, über der Welt der Sterblichen auf Azeroth.",al={"was ist der himmelswall","wo ist der himmelswall"}}},fp="17,165,26.318.0,24.283.1,36.158.0,25.150.0,44.145.0,24.95.0,49.142.0,16.107.0"}
P.entries["quest:92709"] = {n="A Grand Adventure",s="In Valanaar bittet Elaadrin Evengale Euch, die Pläne des Hohen Ordens anzuhören. Seine Suche nach uralter Magie könnte die Zukunft der Insel Zephras prägen.",h="In Valanaar bittet Elaadrin Evengale Euch, die Pläne des Hohen Ordens anzuhören.",kw={"a grand adventure","uralte magie","elaadrin evengale","der hohe orden","hochgeborene","kirin tor","valanaar","insel zephras"},sec={{t="Ein verlorenes Erbe",b="Elaadrin spricht von Eurer Hochgeborenen-Abstammung und den jungen Leuten, die helfen könnten, ihre Heimat zu retten. Der Hohe Orden sucht nach der uralten Magie seiner Ahnen und nach dem, was über viele Jahrtausende verloren ging."},{t="Der Weg voraus",b="Elaadrin sagt, Azeroth sei der Schlüssel zur Suche. Die Kirin Tor werden dem Hohen Orden den Weg weisen. Während seine Mitglieder ihre Abreise vorbereiten, könnt Ihr mit anderen in Valanaar sprechen. Viele brauchen Hilfe bei ihrer Arbeit."}},faq={{q="Wer bittet mich zuzuhören?",a="Elaadrin Evengale in Valanaar bittet Euch, die Pläne des Hohen Ordens anzuhören.",al={"wer ist elaadrin","elaadrin evengale","wer möchte sprechen"}},{q="Was versucht der Hohe Orden wiederzuentdecken?",a="Der Hohe Orden sucht nach der uralten Magie seiner Ahnen und nach dem, was über viele Jahrtausende verloren ging.",al={"wonach suchen sie","uralte magie","pläne des hohen ordens"}},{q="Warum sucht der Hohe Orden nach uralter Magie?",a="Elaadrin sagt, die Wiederentdeckung uralter Magie sei der Schlüssel, um die Geheimnisse der Insel Zephras zu lüften und ihre Zukunft zu sichern.",al={"warum uralte magie","zephras retten","zukunft der insel"}},{q="Wer wird ihnen den Weg weisen?",a="Elaadrin sagt, die Kirin Tor werden dem Hohen Orden den Weg weisen.",al={"kirin tor","wer führt sie","azeroth plan"}},{q="Was kann ich tun, während sie ihre Abreise vorbereiten?",a="Während sie ihre Abreise vorbereiten, könnt Ihr mit anderen Mitgliedern des Hohen Ordens in Valanaar sprechen. Die meisten brauchen Hilfe bei ihrer Arbeit.",al={"hilfe in valanaar","andere mitglieder des hohen ordens","was als nächstes"}}},fp="17,139,15.193.0,13.195.1,27.72.0,44.90.0,43.111.0,27.61.0,42.124.0"}
P.entries["quest:92727"] = {n="The Missing Scholar",s="Fillion Flamebreeze wird vermisst, seit er aufbrach, um atmosphärische Magie auf Zephras zu erforschen. Der Hohe Orden schickte den Gelehrten zum Shen'darhochland, und die Sorge wächst, da von der Straße aus Valanaar keine Nachricht über seine Rückkehr kommt.",h="Fillion Flamebreeze wird vermisst, seit er aufbrach, um atmosphärische Magie auf Zephras zu erforschen.",kw={"blutbefleckte tasche","fillion flamebreeze","der hohe orden","shen'darhochland","the missing scholar","valanaar","windgetragene magie","zephras"},ang={["class:Mage"]="Als Magier teilt Ihr Flamebreezes Neugier auf die windgetragenen arkanen Strömungen, die sich im Hochland von Zephras sammeln.",["race:Skyborne"]="Als Skyborne wisst Ihr, dass die Winde und die atmosphärische Magie von Zephras von großem Interesse sind. Verborgene Gefahren machen das Gelände selbst für Gelehrte gefährlich."},sec={{t="Der Auftrag des Hohen Ordens",b="Der Hohe Orden sammelt und bewahrt Wissen auf ganz Zephras. Doch die Feldforschung auf der Insel ist gefährlich geworden. Fillion Flamebreeze brach zum Shen'darhochland auf, um atmosphärische Arkanphänomene zu untersuchen, meldete sich jedoch nie zurück. Seine Kollegen fürchten nun, dass ihn die Gefahren entlang der Grenzstraßen das Leben gekostet haben."},{t="Spuren auf der Weststraße",b="Fillion Flamebreeze verließ Valanaar und reiste nach Westen zum Shen'darhochland. Dort wollte er windgetragene Magie untersuchen, die sich zwischen den Gipfeln sammelt. Er verschwand, bevor er sein Ziel erreichte. Bei einer Suche entlang des Weges findet sich nur seine persönliche Tasche im Schmutz. Getrocknetes Blut befleckt sie, und es bestehen ernste Zweifel an seinem Überleben."}},faq={{q="Wer ist Fillion Flamebreeze?",a="Fillion Flamebreeze ist ein Gelehrter des Hohen Ordens auf Zephras. Er brach auf, um windgetragene Magie im Shen'darhochland zu untersuchen, und verschwand dann auf dem Weg.",al={"wer ist fillion flamebreeze","fillion flamebreeze hintergrund","wer ist the missing scholar"}},{q="Was ist Fillion Flamebreeze zugestoßen?",a="Fillion Flamebreeze erreichte sein Ziel nie. Seine zurückgelassene Tasche liegt an der westlichen Straße zum Shen'darhochland, mit seinem aufgestickten Namen und getrockneten Blutspritzern, die auf einen Angriff hindeuten.",al={"was ist fillion zugestoßen","ist fillion gestorben","fillion flamebreeze schicksal"}},{q="Was ist der Hohe Orden?",a="Der Hohe Orden sammelt und bewahrt Wissen auf ganz Zephras. Wilde magische Phänomene und Bedrohungen entlang der Straßen haben seine Arbeit gefährlicher gemacht.",al={"auftrag des hohen ordens","was macht der hohe orden","hoher orden zephras"}},{q="Warum reiste Fillion zum Shen'darhochland?",a="Fillion Flamebreeze reiste zum Shen'darhochland, um ungewöhnliche windgetragene Magie aufzuzeichnen, die sich in Teilen des Hochlands sammelt und sie durchströmt.",al={"wohin wollte fillion","windmagie shendar","warum ging er ins hochland"}},{q="Wo wurde Fillion Flamebreeze zuletzt gesehen?",a="Fillion Flamebreezes blutbefleckte Tasche liegt an der Straße, die von Valanaar westwärts zum Shen'darhochland hinaufführt.",al={"wo ist die tasche","fillions tasche fundort","straße von valanaar"}},{q="Was ist die windgetragene Magie des Shen'darhochlands?",a="Windgetragene Magie besteht aus atmosphärischen arkanen Strömungen, die sich auf natürliche Weise an bestimmten hoch gelegenen Orten auf Zephras sammeln. Das Shen'darhochland ist ein zentrales Forschungsgebiet der Arkanforschung.",al={"was ist windgetragene magie zephras","windmagie hochland"}}},fp="19,224,24.308.0,26.321.1,27.158.0,37.214.0,23.152.0,53.139.0,40.129.0,54.177.0"}
P.entries["quest:92741"] = {n="Unwelcome Visitors",s="Im Schattenwindwald drängen Kreischlinge zum Waldrand. Iaadaria Bitterwind in Valanaar bittet Reisende, ihre Krallen für den Hohen Orden zu sammeln.",h="Im Schattenwindwald drängen Kreischlinge zum Waldrand.",kw={"alchemistische eigenschaften","iaadaria bitterwind","schattenwindwald","kreischling","kreischlingskralle","der hohe orden","unwelcome visitors","valanaar"},ang={["class:Druid"]="Als Druide könnt Ihr die plötzliche Vermehrung und Ausbreitung der Kreischlinge als Störung im Schattenwindwald erkennen. Rasches Handeln ist nötig, um das natürliche Gleichgewicht des Waldes wiederherzustellen.",["class:Hunter"]="Als Jäger könnt Ihr die überzähligen Kreischlinge im Schattenwindwald aufspüren und ihren Bestand ausdünnen. Ihr übernehmt die Arbeit von Wildhütern und Fallenstellern, eine Pflicht, die der Hohe Orden geringschätzt."},sec={{t="Der Ansturm der Kreischlinge",b="Der Schattenwindwald ist ein gefährliches Waldgebiet, das gewöhnliche Abenteurer nicht betreten dürfen. Nun haben sich seine Kreischlinge in nie gekannter Zahl vermehrt. Sie drängen zum Waldrand und dehnen ihre Jagdgebiete über das Blätterdach hinaus aus. Wenn sie sich weiter ausbreiten, droht besiedelten Landen und Reiserouten eine wachsende Gefahr."},{t="Bestandsregulierung für die Forschung",b="In Valanaar erkennt Iaadaria Bitterwind vom Hohen Orden in der wachsenden Zahl der Kreischlinge sowohl Gefahr als auch eine Gelegenheit. Der Orden überlässt Schädlingsbekämpfung und Fallenstellen gewöhnlich anderen. Doch Kreischlingskrallen besitzen seltene alchemistische Eigenschaften, die eine Ausnahme lohnenswert machen. Reisende werden gebeten, den Schattenwindwald zu betreten und acht Krallen zurückzubringen. So kann der Hohe Orden zum Schutz der Region beitragen und die Reagenzien untersuchen."}},faq={{q="Wer vergibt die Quest Unwelcome Visitors?",a="Iaadaria Bitterwind erteilt den Auftrag in Valanaar. Sie ist Forscherin beim Hohen Orden und bittet Reisende, Kreischlinge in der Nähe zu jagen und Materialien für ihre alchemistischen Studien zu sammeln.",al={"wer vergibt unwelcome visitors","unwelcome visitors questgeber","wo unwelcome visitors annehmen"}},{q="Welches Interesse hat der Hohe Orden an den Kreischlingen?",a="Der Hohe Orden interessiert sich für die Krallen der Kreischlinge, die besondere alchemistische Eigenschaften besitzen. Obwohl der Orden Fallenstellen und Schädlingsbekämpfung gewöhnlich anderen überlässt, sieht Iaadaria Bitterwind eine Gelegenheit, wertvolle Reagenzien zu untersuchen und zugleich zum Schutz der Region beizutragen.",al={"warum will der hohe orden krallen","hoher orden kreischlinge","iaadaria bitterwind beweggrund"}},{q="Warum muss der Bestand der Kreischlinge verringert werden?",a="Die Kreischlinge im Schattenwindwald haben sich in den letzten Monaten stark vermehrt. Sie dringen über ihr angestammtes Waldrevier hinaus vor und bedrohen benachbarte Gebiete, wenn ihre Ausbreitung anhält.",al={"warum kreischlinge töten","bedrohung durch kreischlinge","warum sind kreischlinge ein problem"}},{q="Wo liegt der Schattenwindwald?",a="Der Schattenwindwald liegt nahe Valanaar. Seine gefährlichen Wälder sind gewöhnlichen Reisenden und unerfahrenen Abenteurern wegen der wilden, angriffslustigen Tiere darin normalerweise verwehrt.",al={"wo liegt der schattenwindwald","schattenwindwald lage","wie zum schattenwindwald gelangen"}},{q="Was sind Kreischlinge?",a="Kreischlinge sind bösartige Raubbestien, die im Schattenwindwald heimisch sind. Ihre Krallen besitzen alchemistische Eigenschaften, und in den letzten Monaten ist ihre Zahl so stark gewachsen, dass sie über den Waldrand hinaus vordringen.",al={"was ist ein kreischling","kreischling hintergrundgeschichte","was für bestien sind kreischlinge"}},{q="Welche Gegenstände werden benötigt, um Unwelcome Visitors abzuschließen?",a="Reisende müssen Iaadaria Bitterwind in Valanaar acht Kreischlingskrallen aus dem Schattenwindwald bringen. Die Krallen dienen ihrer gelehrten und alchemistischen Forschung.",al={"unwelcome visitors ziele","was wird für unwelcome visitors benötigt","benötigte kreischlingskrallen"}},{q="Warum dürfen gewöhnliche Abenteurer den Schattenwindwald nicht betreten?",a="Gewöhnlichen Abenteurern ist der Zutritt zum Schattenwindwald verboten, weil seine Tierwelt tödlich und das Waldgebiet tückisch ist. Wer ihn betritt, auch Reisende mit dem Auftrag, die Kreischlinge zu dezimieren, muss auf große Gefahren gefasst sein.",al={"warum ist schattenwind gesperrt","schattenwindwald gefahr","darf jeder den schattenwindwald betreten"}}},fp="18,160,20.339.0,17.417.0,39.185.0,53.263.0,45.190.0,35.171.0,21.215.0,55.162.0,58.217.0"}
P.entries["quest:92742"] = {n="Testing the Wells",s="Alba Fairmoon schickt Euch los, um die Hofbrunnen in ganz Westfall zu untersuchen. Ihre Wasserproben könnten zeigen, was Boden und Grundwasser vergiftet.",h="Alba Fairmoon schickt Euch los, um die Hofbrunnen in ganz Westfall zu untersuchen.",kw={"alba fairmoon","grundwasser","jansens hof","molsens hof","gift","testing the wells","wasserprobe","westfall"},ang={["class:Druid"]="Als Druide wisst Ihr, dass unnatürliche Giftstoffe im Boden und im frischen Grundwasser das Gleichgewicht des Landes verletzen und Heilung erfordern.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass die Höfe von Westfall das Königreich Sturmwind ernähren müssen. Der Zustand ihrer Brunnen betrifft das ganze Königreich."},sec={{t="Verderbnis im Grundwasser",b="Alba Fairmoon bittet Euch, das Wasser unter Westfall zu untersuchen. Vernachlässigung und Banditentum haben den offenen Ebenen bereits zugesetzt. Nun bedroht Gift unter der Erde das verbliebene Ackerland. Ihr sammelt Proben aus Hofbrunnen, damit Alba herausfinden kann, was Boden und Wasser verseucht."},{t="Höfe im Grenzland",b="Ihr sammelt Proben aus den Brunnen auf Jansens Hof und Molsens Hof. Diese Gehöfte liegen zwischen verstreuten Bauernhöfen, schutzlos Defias-Geächteten und wilden Tieren ausgeliefert. Ihr Wasser könnte zeigen, ob die Verderbnis aus dem Boden aufsteigt, durch Magie entsteht oder absichtlich eingebracht wurde."}},faq={{q="Welchen Zweck hat Testing the Wells?",a="Alba Fairmoon will Ursprung und Art des Giftes ermitteln, das Westfall heimsucht. Mit frischen Proben aus Hofbrunnen kann sie die Verseuchung untersuchen.",al={"warum die brunnen untersuchen","ziel von testing the wells","wozu dient diese quest"}},{q="Wer vergibt diese Aufgabe?",a="Alba Fairmoon bittet Euch um Hilfe bei ihrer Untersuchung der sich ausbreitenden Verderbnis und der unnatürlichen Gifte in Westfall.",al={"wer vergibt testing the wells","alba fairmoon quest","questgeber"}},{q="An welchen Orten müssen Proben entnommen werden?",a="Ihr entnehmt Proben aus den Brunnen auf Jansens Hof und Molsens Hof in Westfall.",al={"wohin gehen","welche brunnen","standorte der brunnen"}},{q="Was bedroht Wasser und Boden in Westfall?",a="Eine unbekannte Verderbnis oder ein Gift verseucht das Land von Westfall. Die Untersuchung des Brunnenwassers ist der erste Schritt, um herauszufinden, ob das Wasser unter den Gehöften verseucht ist.",al={"warum ist westfall vergiftet","was vergiftet das land","ursprung des giftes"}},{q="Ist die Verseuchung natürlich oder künstlich?",a="Die Ursache ist noch unbekannt. Proben von Jansens Hof und Molsens Hof könnten zeigen, ob die Fäulnis von natürlicher Verderbnis im Grundwasser oder gezielter Sabotage herrührt.",al={"ist das wasser absichtlich vergiftet","wer hat die brunnen vergiftet"}},{q="Warum stehen Jansens Hof und Molsens Hof im Mittelpunkt?",a="Jansens Hof und Molsens Hof sind alteingesessene Gehöfte mit Brunnen, die das Grundwasser unter den Ebenen anzapfen. Ihre Untersuchung kann zeigen, wie weit die Verderbnis reicht.",al={"warum jansen und molsen","warum diese höfe"}}},fx={["40e3ab69"]={q="Warum möchte Alba Fairmoon, dass dies erledigt wird?",a="Alba Fairmoon versucht, die Quelle und die genaue Art des Giftes aufzudecken, das derzeit den Boden und das Grundwasser von Westfall verseucht. Durch die Analyse von Wasser direkt aus den Brunnen arbeitender Gehöfte hofft sie, diagnostizieren zu können, was das Land verheert, bevor sich die Kontamination unumkehrbar ausbreitet.",al={"warum will alba wasserproben","alba fairmoons beweggrund","warum die brunnen testen"}},d6dffc38={q="Wofür ist die Wasserprobe von Jansens Hof?",a="Diese Probe liefert Alba Fairmoon Grundwasser, das direkt von Jansens Hof stammt. Durch die Untersuchung zusammen mit anderen Farmproben kann sie nachverfolgen, ob die Fäulnis tief in unterirdische Grundwasserleiter in ganz Westfall eindringt oder aus einem spezifisch lokalisierten Schadstoff austritt.",al={"nutzen der wasserprobe jansens hof","warum wasser von jansens hof holen","zweck der probe jansens hof"}},fcb7e3cb={q="Wofür ist die Wasserprobe von Molsens Hof?",a="Dieses Wasser, das aus dem Brunnen auf Molsens Hof entnommen wurde, ermöglicht es Alba Fairmoon, das Ausmaß der Korruption in verschiedenen Teilen von Westfalls Ackerland zu testen. Der Vergleich seiner Reinheit mit anderen örtlichen Brunnen hilft ihr, den Weg und die Intensität des sich ausbreitenden Giftes einzuschätzen.",al={"nutzen der wasserprobe molsens hof","warum probe von molsens hof sammeln","zweck des wassers molsens hof"}}},fp="17,131,21.270.0,21.268.0,41.155.0,22.110.0,35.65.0,46.164.0,43.167.0,42.182.0"}
P.entries["quest:92744"] = {n="Murloc Gills",s="An Westfalls Endloser Küste sucht Alba Fairmoon Murlockiemen, um das Meer zu untersuchen. Sie fürchtet, die Ernteseuche könnte das große Meer erreichen, und die Kiemen könnten zeigen, ob die Küstengewässer verseucht sind.",h="An Westfalls Endloser Küste sucht Alba Fairmoon Murlockiemen, um das Meer zu untersuchen.",kw={"alba fairmoon","seuche","hungersnot","die endlose küste","murloc gills","meerwasser","sturmwind","giftstoffe","westfall"},ang={["class:Druid"]="Die Seuche aus dem Landesinneren breitet sich in die Küstengewässer aus und bedroht die heimische Tierwelt. Die Beobachtung von Zeigerarten wie Murlocs hilft, dieser Gefahr vorzubeugen.",["faction:Alliance"]="Da König Varian verschwunden ist und Nahrungsmangel Unruhen schürt, ist der Schutz von Westfalls verbliebener Nahrungsversorgung entscheidend für Sturmwinds Stabilität.",["race:Human"]="Für die Menschen von Sturmwind bedroht Westfalls Niedergang ihre Heime, ihr Ackerland und das Essen auf ihren Tischen."},sec={{t="Eine Bedrohung der Küste",b="Westfall steht kurz vor dem Ruin. Ernten fallen aus, Bauern verlassen ihre Höfe, und Banditen durchstreifen die Straßen. Alba Fairmoon fürchtet, die Seuche könnte von den Feldern im Landesinneren ins große Meer geschwemmt werden. Verseucht sie die Küste, könnten die Fische verschwinden, die Westfalls Arme ernähren und Sturmwinds Tafeln füllen. Dann droht dem bereits gebeutelten Königreich womöglich eine Hungersnot."},{t="Wächter der Wasserqualität",b="Murlocs sind starrsinnig und gewalttätig, doch ihre amphibischen Körper können Aufschluss über den Zustand des Wassers geben. Beim Atmen filtern ihre Kiemen Meerwasser und nehmen dabei leicht Gifte, Seuchenerreger und unnatürliche Schadstoffe auf. Alba Fairmoon hofft, dass frische Kiemen von Murlocs, die an der Endlosen Küste umherstreifen, zeigen, wie weit sich die Verseuchung ausgebreitet hat."}},faq={{q="Warum braucht Alba Fairmoon Murlockiemen?",a="Alba Fairmoon braucht Murlockiemen, um herauszufinden, ob Westfalls Ernteseuche das Meer erreicht hat. Ihre Kiemen filtern Meerwasser und können Spuren von Giftstoffen oder Verunreinigungen offenbaren.",al={"warum murlockiemen","alba fairmoon murlocs","zweck der aufgabe"}},{q="Wo befinden sich die Murlocs für diese Aufgabe?",a="Die Murlocs durchstreifen die Endlose Küste, den Strand entlang Westfalls Westküste. Sie treiben sich im seichten Wasser und im Watt jenseits der Steilhänge herum.",al={"wo sind murlocs","endlose küste murlocs fundort","murlockiemen fundort"}},{q="Welche weitreichende Gefahr droht, wenn das Meer verseucht wird?",a="Westfall ist Sturmwinds wichtigste Kornkammer, und im Landesinneren fallen die Ernten bereits aus. Die Küstenfischerei liefert lebenswichtige Nahrung. Wenn Giftstoffe das Meeresleben entlang der Küste vergiften, könnte dem Königreich eine unausweichliche Hungersnot drohen.",al={"warum ist das wichtig","westfall hungersnot gefahr","bedrohung für sturmwind"}},{q="Sind Murlocs besonders anfällig für Krankheiten?",a="Murlocs überleben unter widrigen Bedingungen, doch ihre amphibischen Atmungsorgane reagieren rasch auf chemische oder magische Verunreinigungen im Wasser. Dadurch eignen sie sich zur Untersuchung von Schadstoffen, die sich über das Wasser ausbreiten.",al={"murloc physiologie","werden murlocs krank"}},{q="Besteht bei dieser Aufgabe eine Verbindung zur Bruderschaft der Defias?",a="Die Bruderschaft der Defias hat Westfall ins Chaos gestürzt und dafür gesorgt, dass Ackerland brachliegt. Alba Fairmoons Untersuchung befasst sich hingegen mit der Seuche in der Umwelt und dem Schutz der Nahrungsversorgung des Königreichs.",al={"verbindung zu den defias","sind das die defias"}},{q="Wer ist Alba Fairmoon?",a="Alba Fairmoon ist eine Forscherin der Allianz in Westfall. Sie beobachtet die Seuche und den Verfall der Umwelt, die das Ackerland der Region bedrohen.",al={"wer ist fairmoon","alba fairmoon hintergrund"}}},fx={["853673a8"]={q="Wofür sind die Murloc Gills aus Die Endlose Küste?",a="Murlocs atmen durch ihre Kiemen, während sie durch die Küstengewässer streifen, was ihr Atemgewebe empfindlich gegenüber allem macht, was das Meer verschmutzt. Alba Fairmoon verwendet die Kiemen als biologisches Testobjekt. Durch die Untersuchung des Gewebes auf Toxine kann sie feststellen, ob die seltsame Korruption, die den Boden und die Ernte von Westfall verdorren lässt, auch begonnen hat, den Ozean zu vergiften.",al={"nutzen murloc kiemen","warum murloc kiemen sammeln","murloc kiemen die endlose küste"}},["4abd0ea3"]={q="Warum jagt Ihr die Murlocs an Die Endlose Küste?",a="Die Murlocs leben entlang der Westküste von Westfall und sind ständig den Gezeiten und der Gischt ausgesetzt. Da ihre aquatischen Körper Küstenwasser direkt durch ihre Kiemen filtern, bietet die Entnahme von Proben von ihnen unmittelbare biologische Beweise dafür, ob Schadstoffe von dem betroffenen Ackerland ins Meer gesickert sind.",al={"warum murlocs","wer sind die murlocs der endlosen küste","warum murlocs als ziel"}}},fp="12,190,25.325.0,26.319.0,41.169.0,44.133.0,53.215.0,42.192.0,50.195.0,21.137.0"}
P.entries["quest:92745"] = {n="The State of the Mines",s="Giftige Metalle tauchen in Westfalls Brunnen auf, und Alba Fairmoon fürchtet um das Ackerland. Sie verdächtigt die Minen der Defias und warnt, dass der Boden jahrzehntelang unfruchtbar bleiben könnte. Ihr brecht zum Jangoschacht und zum Goldküstensteinbruch auf, um den Bergbau zu stören.",h="Giftige Metalle tauchen in Westfalls Brunnen auf, und Alba Fairmoon fürchtet um das Ackerland.",kw={"alba fairmoon","defias","der goldküstensteinbruch","der jangoschacht","koboldgräber","bergbau","flusspfoten","giftige abflüsse","westfall"},ang={["class:Druid"]="Als Druide steht Ihr einer dringenden Bedrohung durch Metallgifte gegenüber, die in Westfalls Ebenen und Küstenökosysteme sickern.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass Westfall zur Ernährung Sturmwinds beiträgt. Wenn die Defias das Ackerland ruinieren, könnte dem Königreich jahrelange Hungersnot drohen.",["profession:Mining"]="Im Jangoschacht und im Goldküstensteinbruch bauen die Defias Mineralien ab und nehmen dabei kaum Rücksicht auf die Sicherheit oder die Standfestigkeit der Minen."},sec={{t="Vergiftung des Landes",b="Alba Fairmoon entdeckt gefährliche Konzentrationen giftiger Metalle in Westfalls Brunnen. Einst Sturmwinds wichtigste Kornkammer, sieht die Region nun ihre Ernten bedroht. Alba vermutet, dass die Bruderschaft der Defias das Wasser durch die von ihr besetzten Minen vergiftet. Hält die Verschmutzung an, könnte der umliegende Boden jahrzehntelang unfruchtbar bleiben."},{t="Zwangsarbeit und angeworbene Arbeitskräfte",b="Die Defias lassen einheimische Kreaturen an der Seite ihrer Wegelagerer arbeiten und plündern so Westfalls Ressourcen. Flusspfotengnolle graben im Goldküstensteinbruch nach Gestein und Mineralien, während Koboldgräber Stollen durch den Jangoschacht treiben. Wer ihre Arbeit stört, schwächt die Fähigkeit der Defias, verunreinigte Mineralien zu verarbeiten und zu verteilen."}},faq={{q="Warum treten aus Westfalls Minen giftige Metalle aus?",a="Alba Fairmoon vermutet, dass die von der Bruderschaft der Defias besetzten Minen Westfalls Grundwasser mit giftigen Metallen verunreinigen. Sie will die Arbeit ihrer Bergleute stören, um die Verschmutzung aufzuhalten.",al={"warum giftiges wasser westfall","westfall minenverschmutzung","giftige abflüsse westfall"}},{q="Wer steckt hinter dem Bergbau in Westfall?",a="Die Bruderschaft der Defias kontrolliert den Bergbau in Westfall. Sie hat ehemalige Infrastruktur des Königreichs besetzt und lässt Flusspfotengnolle und Kobolde Mineralien abbauen.",al={"wer betreibt die minen","wer kontrolliert westfalls minen","defias bergbau"}},{q="Wo arbeiten die Flusspfotengnolle und Kobolde?",a="Flusspfotengnolle arbeiten im Goldküstensteinbruch an Westfalls Westküste, während Koboldgräber im nördlich gelegenen Jangoschacht arbeiten.",al={"wo sind die bergleute","goldküstensteinbruch standort","jangoschacht standort"}},{q="Wer ist Alba Fairmoon?",a="Alba Fairmoon untersucht Westfalls Wasser und versucht, das Ackerland der Region vor dauerhaften Schäden zu schützen.",al={"wer vergibt the state of the mines","alba fairmoon hintergrund","questgeber"}},{q="Warum arbeiten Gnolle und Kobolde für die Defias?",a="Die Defias setzen Gnolle und Kobolde als Arbeitskräfte in den besetzten Minen ein. Alba sagt nicht, wie die Arbeiter angeworben wurden.",al={"warum werben defias gnolle an","kobolde arbeiten für defias"}},{q="Kann sich das Land in Westfall von dieser Verunreinigung erholen?",a="Alba Fairmoon sagt, der Boden könne sich erholen, wenn die Quelle der Vergiftung schnell beseitigt wird. Geht der Bergbau weiter, könnte die Erde jahrzehntelang unfruchtbar und verseucht bleiben.",al={"erholt sich westfalls boden","können feldfrüchte wieder wachsen"}}},fx={f9d72c87={q="Warum will Alba Fairmoon, dass die Bergleute getötet werden?",a="Wasserproben aus den örtlichen Brunnen ergaben, dass gefährliche toxische Metalle in den Boden von Westfall sickern. Alba Fairmoon weiß, dass die Umweltgifte bestehen bleiben und die Region für Jahrzehnte unfruchtbar und unfähig machen werden, Pflanzen anzubauen, wenn der aggressive Tagebau nicht sofort gestoppt wird.",al={"warum die bergleute töten","motiv von alba fairmoon","warum den bergbau stoppen"}},["23ba5f2a"]={q="Wer sind die Bergleute im Jangoschacht und im Goldküstensteinbruch?",a="Ihr werdet gegen die Koboldgräber im Jangoschacht und die Flusspfotenminenarbeiter im Goldküstensteinbruch ausgesandt. Anstatt für sich selbst zu arbeiten, werden diese Kreaturen von der The Defias Brotherhood als Arbeitskräfte eingesetzt, die die Minen besetzten, um Westfall rücksichtslos um seinen mineralischen Reichtum zu bringen.",al={"wer sind die bergleute","wen sollt ihr töten","koboldgräber flusspfotenminenarbeiter"}}},fp="22,240,18.325.0,25.320.0,51.182.0,48.160.0,50.136.0,21.107.0,50.113.0,57.169.0"}
P.entries["quest:92747"] = {n="Moonbrook Espionage",s="In Mondbruch geht Alba Fairmoon Anzeichen für Probleme mit der Industrie in Westfall nach. Das Gift, das überall in der Region gefunden wurde, scheint nicht aus den kleineren Minen zu stammen, weshalb die Todesminen unter der Stadt ihre Aufmerksamkeit erregen.",h="In Mondbruch geht Alba Fairmoon Anzeichen für Probleme mit der Industrie in Westfall nach.",kw={"alba fairmoon","die todesminen","spionage","industriebedarfsvorräte","minen","mondbruch","gift","westfall"},ang={["class:Rogue"]="Als Schurke könnt Ihr durch Mondbruch schleichen, um Informationen über die Aktivitäten der Defias zu sammeln, ohne Alarm auszulösen.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass die aktive Industrie in Mondbruch Westfalls Kornkammer und Sturmwinds Sicherheit bedroht.",["profession:Mining"]="Als Bergmann kennt Ihr den Reichtum und die logistischen Ausmaße der tiefen Schächte unter Mondbruch."},sec={{t="Eine giftige Spur",b="Die bereits durchsuchten Minen in ganz Westfall haben keine Erklärung für das Gift geliefert, das sich in der Region ausbreitet. Keine bekannte oberirdische Ausgrabungsstätte scheint seine Quelle zu sein. Eine große Anlage bleibt unerforscht: die Todesminen, deren gewaltige Schächte unter Mondbruchs zerstörten Straßen liegen."},{t="Geheimnisse der Todesminen",b="Die Horde überrannte die Region während des Ersten Krieges, und Berichten zufolge wurden die Todesminen danach aufgegeben. Doch überall in Mondbruch liegen moderne Industrieausrüstung und Vorräte verstreut. Sie deuten auf umfangreichen Bergbau und Fertigung hin, verborgen hinter dem verfallenen, verlassenen Erscheinungsbild der Stadt."}},faq={{q="Wer vergibt Moonbrook Espionage?",a="Alba Fairmoon schickt Euch, um Mondbruch zu untersuchen. Sie geht verdächtigen Giftstoffen und industriellen Aktivitäten im umkämpften Westfall nach.",al={"questgeber","wer vergibt moonbrook espionage","alba fairmoon"}},{q="Warum untersucht Alba Mondbruch?",a="In den anderen örtlichen Minen gibt es keine Anzeichen dafür, dass dort das Gift entsteht, das Alba untersucht. Mondbruch liegt direkt über den Todesminen, weshalb sie einen illegalen Betrieb unter der Stadt vermutet.",al={"warum mondbruch","was ist in mondbruch","mondbruch untersuchen"}},{q="Was sind die Todesminen?",a="Die Todesminen sind die tiefsten und weitläufigsten Goldminen der Region. Seit Sturmwind im Ersten Krieg fiel, gelten sie als verlassene Ruinen, obwohl sich dort angeblich Ungeziefer und Banditen herumtreiben.",al={"hintergrund der todesminen","was sind die todesminen","geschichte der todesminen"}},{q="Welche Gegenstände werden bei dieser Erkundungsmission gesammelt?",a="Späher werden ausgesandt, um Verdächtige Industriebedarfsvorräte zu bergen, die überall in Mondbruch verstreut liegen. Die Vorräte deuten auf laufende industrielle Arbeiten und Veredelung nahe den Minenschächten hin.",al={"verdächtige industriebedarfsvorräte","questgegenstände moonbrook espionage"}},{q="Welche Bedrohungen gibt es derzeit in Mondbruch?",a="Die Bruderschaft der Defias hat Mondbruch überrannt und nutzt die verfallenen Gebäude als vorgeschobenen Stützpunkt. Ihre Mitglieder bewachen den oberirdischen Eingang zum unterirdischen Netzwerk.",al={"feinde in mondbruch","wer kontrolliert mondbruch"}},{q="Was beweist der Fund dieser Vorräte?",a="Moderne, schwere Industrieausrüstung in einer vermeintlich verlassenen Stadt deutet auf eine organisierte Fraktion hin, die im großen Stil und vor Sturmwinds Behörden verborgen produziert.",al={"was bedeuten die vorräte","industrie der defias"}}},fp="19,209,13.271.0,24.282.1,32.144.0,36.181.0,23.198.0,53.167.0,40.161.0,39.175.0"}
P.entries["quest:92748"] = {n="Explosive Consultation",s="Alba Fairmoon schickt Euch los, um die Ausbreitung des Gifts aus den Todesminen auf Westfalls Felder aufzuhalten. In Sturmwinds Zwergendistrikt sucht Ihr einen Ingenieur, der die dafür nötigen schweren Sprengstoffe herstellen kann.",h="Alba Fairmoon schickt Euch los, um die Ausbreitung des Gifts aus den Todesminen auf Westfalls Felder...",kw={"alba fairmoon","die todesminen","der zwergendistrikt","ingenieurskunst","explosive consultation","glimm springspross","sturmwind","giftstoffe","westfall"},ang={["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie Westfalls bedrängte Grenzgemeinden auf die Werkstätten in Sturmwinds Zwergendistrikt angewiesen sind.",["profession:Engineering"]="Als Ingenieur wisst Ihr, dass rohe Gewalt die Probleme mit Westfalls vergiftetem Land nicht lösen kann. Große unterirdische Maschinen außer Betrieb zu setzen, erfordert spezielle Munition und sorgfältiges technisches Geschick.",["race:Gnome"]="Als Gnom bringt Ihr technischen Einfallsreichtum mit, der helfen kann, industrielle Bedrohungen unter Tage außerhalb der Reichweite regulärer Allianztruppen zu bekämpfen."},sec={{t="Eine giftige Quelle",b="Die Vergiftung von Westfalls Feldern lässt sich auf ätzende Giftstoffe und Industrieabfälle in den Todesminen zurückführen. Verstärkte Maschinen bewachen die unterirdischen Anlagen, und gewöhnliche Waffen können sie nicht außer Betrieb setzen. Schwere Sprengstoffe könnten diese Maschinen durchbrechen und die Vergiftung aufhalten."},{t="Sturmwinds Fachwissen gesucht",b="In Sturmwinds Zwergendistrikt sucht Ihr Glimm Springspross, eine Ingenieurin, die die benötigten Sprengstoffe entwickeln kann. Tosende Schmieden, Tüftler und Händler, die Sprengpulver verkaufen, prägen den Distrikt. Seine Handwerker wissen vielleicht, wie sich der Betrieb in den Todesminen stoppen lässt."}},faq={{q="Warum brauchen wir Sprengstoffe in den Todesminen?",a="Beweise aus Westfall deuten auf einen großen Industriebetrieb in den Todesminen hin, dessen Giftstoffe das nahe gelegene Ackerland verseuchen. Schwere Sprengstoffe können seine verstärkten Maschinen außer Betrieb setzen.",al={"warum sprengstoffe todesminen","warum brauchen wir bomben","todesminen giftstoffe grund"}},{q="Wer vergibt diese Quest?",a="Alba Fairmoon schickt Helden los, um die unnatürlichen Verunreinigungen und die Unruhen zu untersuchen, die Westfall bedrohen.",al={"wer vergibt explosive consultation","explosive consultation start"}},{q="Wer ist Glimm Springspross?",a="Glimm Springspross ist eine Gnomeningenieurin in Sturmwinds Zwergendistrikt. Sie arbeitet mit komplexen mechanischen Geräten und instabilen Verbindungen und kann mächtige Sprengladungen herstellen.",al={"glimm springspross standort","wer ist springspross"}},{q="Warum im Zwergendistrikt Hilfe suchen?",a="Sturmwinds Zwergendistrikt ist das industrielle Herz der Stadt. Dort arbeiten geschickte Schmiede und Tüftler neben Händlern, die Sprengpulver und Ingenieursbauteile verkaufen.",al={"warum zwergendistrikt","sturmwind zwergendistrikt verbindung"}},{q="Unterstützt Sturmwinds Regierung dieses Vorhaben?",a="Da König Varian Wrynn vermisst wird, zögert das House of Nobles, offizielle Militärgarnisonen nach Westfall zu entsenden. Die örtlichen Verteidiger verlassen sich auf unabhängige Freiwillige und private Handwerker in der Hauptstadt statt auf reguläre Armeeregimenter.",al={"hilft die armee","warum ingenieur aus sturmwind"}}},fx={fe11cddb={q="Warum möchte Alba Fairmoon, dass Ihr nach Sprengstoff sucht?",a="Alba Fairmoon hat Beweise für einen massiven industriellen Betrieb aufgedeckt, der tief in den Todesminen verborgen ist. Sie hat diese unterirdischen Maschinen direkt mit den üblen Giften in Verbindung gebracht, die den Boden vergiften und die Ackerflächen darüber schädigen. Da sie weiß, dass ein Betrieb dieser Größenordnung nicht einfach von Hand demontiert werden kann, möchte sie schwere Sprengstoffe haben, um jede üble Maschine, die das Land verschmutzt, auszulöschen, bevor der Schaden unumkehrbar wird.",al={"warum sprengstoff für alba fairmoon","motiv von alba fairmoon","warum braucht alba sprengstoff"}}},fp="22,216,14.261.0,29.256.0,43.169.0,22.101.0,27.174.0,44.171.0,52.231.0"}
P.entries["quest:92749"] = {n="A Dynamite Plan",s="Im Zwergendistrikt von Sturmwind will Glimm Springspross einen Plan beginnen, angeregt durch Gerede über Industriesabotage. Sie will zehn Stangen grobes Dynamit.",h="Im Zwergendistrikt von Sturmwind will Glimm Springspross einen Plan beginnen, angeregt durch Gerede über...",kw={"grobes dynamit","der zwergendistrikt","ingenieurskunst","sprengstoffe","sabotage","glimm springspross","sturmwind"},ang={["faction:Alliance"]="Als Mitglied der Allianz entdeckt Ihr Glimms explosiven Plan innerhalb der Mauern Eurer Hauptstadt Sturmwind.",["profession:Engineering"]="Als Ingenieur könnt Ihr grobes Dynamit aus coarse blasting powder und linen cloth herstellen. Es ist eine einfache Prüfung der ersten Tüftlerfertigkeiten.",["race:Gnome"]="Als Gnom seht Ihr, wie Glimm Springspross komplizierte industrielle Probleme mit cleveren, brennbaren Apparaturen angeht."},sec={{t="Funken im Zwergendistrikt",b="Glimm Springspross ist eine Gnomeningenieurin im Zwergendistrikt von Sturmwind. Sie begrüßt Gerede über Industriesabotage und bittet vorbeiziehende Söldner, ihr ein Bündel grobes Dynamit zu bringen."},{t="Gnomische Ambitionen",b="Ihr könnt grobes Dynamit an einer Werkbank für Ingenieurskunst herstellen oder mit den Handwerkern der Stadt handeln. Glimm verlangt zehn Stangen, genug, um industrielle Machenschaften in den umliegenden Gebieten zu stören. Ihr Plan zeigt die praktischen, gefährlichen Methoden, die Gnome bevorzugen, wenn sie mechanischen und politischen Störungen begegnen."}},faq={{q="Wer ist Glimm Springspross?",a="Glimm Springspross ist eine Ingenieurin im Zwergendistrikt von Sturmwind, zwischen dessen Schmieden und Werkstätten. Sie verfolgt kühne, explosive Ingenieursprojekte.",al={"glimm springspross","wer ist glimm","questgeber"}},{q="Was braucht Glimm für diese Aufgabe?",a="Glimm braucht zehn Stangen grobes Dynamit. Ihr könnt sie mit Ingenieurskunst herstellen oder durch Handel oder im Auktionshaus erwerben.",al={"gegenstände für einen explosiven plan","was wird benötigt","benötigte gegenstände"}},{q="Warum will Glimm grobes Dynamit?",a="Gerede über Industriesabotage hat Glimms Aufmerksamkeit geweckt. Für den Anfang will sie einen Vorrat einfacher Sprengladungen.",al={"warum dynamit","zweck des dynamits","sabotagemotiv"}},{q="Wo gebe ich die Quest ab?",a="Glimm Springspross befindet sich im Zwergendistrikt von Sturmwind.",al={"wo abgeben","abgabeort","glimms standort"}},{q="Ist Ingenieurskunst erforderlich, um diese Quest abzuschließen?",a="Nein, Ingenieurskunst ist nicht erforderlich. Ingenieure können grobes Dynamit herstellen, und Ihr könnt es auch durch Handel erwerben oder im Auktionshaus kaufen.",al={"ist ingenieurskunst nötig","voraussetzung ingenieurskunst","auch ohne ingenieurskunst möglich"}},{q="Wie hängt das mit den größeren Schwierigkeiten rund um Sturmwind zusammen?",a="Glimm sagt nicht, worauf ihre Sabotage abzielt. Sie zeigt nur ihren Eifer, mit Dynamit loszulegen, sobald Industriesabotage zur Sprache kommt.",al={"schwierigkeiten in sturmwind","sabotage in westfall","hintergrund der industriesabotage"}}},fx={dd094caa={q="Wofür ist das Grobe Dynamit?",a="Glimm Springspross ist begierig darauf, ein wenig industrielle Sabotage zu betreiben, und Sprengkraft ist entscheidend für diesen Plan. Grobes Dynamit liefert die rohe Stoßkraft, die sie benötigt, um mechanische Abläufe zu stören oder bauliche Hindernisse für ihr bevorstehendes Unterfangen zu beseitigen.",al={"verwendung von grobem dynamit","wofür benötigt glimmer dynamit","warum grobes dynamit"}}},fp="15,158,30.184.0,17.309.0,27.155.0,36.130.0,37.112.0,29.60.0,47.130.0,58.129.0"}
P.entries["quest:92750"] = {n="Detonation at a Distance",s="Glimm Springspross braucht eine sicherere Methode, Sprengstoff zu zünden, und schickt Euch zum Geheimdienst von Sturmwind, um einen Fernzünder zu beschaffen.",h="Glimm Springspross braucht eine sicherere Methode, Sprengstoff zu zünden, und schickt Euch zum Geheimdienst...",kw={"detonation at a distance","jasper teufel","fernzünder","si:7","glimm springspross","geheimdienst von sturmwind","westfall"},ang={["class:Rogue"]="Als Schurke betretet Ihr das Herz der SI:7-Operationen in der Altstadt, wo die Menschen ihre Geheimdienstmethoden anwenden.",["profession:Engineering"]="Als Ingenieur könnt Ihr Zündschnüre und Dynamit herstellen. Fernzünder für militärische Zwecke sind oft über Kontakte erhältlich, die sich auf unauffällige Sabotage spezialisieren.",["race:Gnome"]="Als Gnom teilt Ihr Glimm Springspross' Interesse an technischen Problemen. Für Spionagemunition wendet sie sich an den Geheimdienst der Menschen."},sec={{t="Eine kontrollierte Sprengung",b="Goblins und Gnome gehen rücksichtslos mit flüchtigen Chemikalien um, doch manche Sprengungen erfordern Vorsicht. Eine gewöhnliche Zündschnur kann Euch in Gefahr bringen. Gewöhnliche Tüftler haben den speziellen Zünder, den Glimm für eine kontrollierte Explosion braucht, nicht vorrätig."},{t="Den SI:7 einschalten",b="Glimm schickt Euch zum Geheimdienst von Sturmwind in der Altstadt statt zu örtlichen Zwergensprengmeistern oder gewöhnlichen Händlern für Ingenieursbedarf. Seine Agenten, bekannt als SI:7, sind auf Sabotage, Heimlichkeit und gezielte Sprengungen spezialisiert. Jasper Teufel dient unter ihnen in der Hauptstadt und kann unauffällige, gefährliche Ausrüstung beschaffen."}},faq={{q="Wer schickt Euch auf diese Mission?",a="Glimm Springspross, eine Gnomen-Tüftlerin im Zwergendistrikt von Sturmwind, schickt Euch los, um einen Fernzünder zu finden.",al={"questgeber","wer startet detonation at a distance","glimm springspross quest"}},{q="Mit wem müsst Ihr in Sturmwind sprechen?",a="Glimm schickt Euch zu Jasper Teufel, einem Mitarbeiter des Geheimdienstes von Sturmwind in Sturmwind.",al={"wo abgeben","kontakt beim geheimdienst von sturmwind","jasper teufel standort"}},{q="Warum braucht Glimm Springspross einen Fernzünder?",a="Glimm will Sprengstoff aus der Ferne zünden. Ein Fernzünder ist praktischer, als bei einer unkontrollierten Explosion Eure Gliedmaßen zu riskieren.",al={"warum fernzünder","zweck der sprengung"}},{q="Warum den Geheimdienst von Sturmwind statt eines Ingenieurs kontaktieren?",a="Der Geheimdienst von Sturmwind verfügt über spezielle Sabotageausrüstung, die gewöhnliche Händler und Tüftler im Feld weder vorrätig haben noch offen vertreiben.",al={"warum si7","warum geheimdienst von sturmwind"}},{q="Wo befindet sich Jasper Teufel in Sturmwind?",a="Jasper Teufel befindet sich im Hauptquartier des SI:7 in der Altstadt, wo Sturmwinds Spione und Geheimagenten arbeiten.",al={"jasper teufel sturmwind","jasper teufel raum"}},{q="Welche Fraktion kann diese Aufgabe übernehmen?",a="Nur Mitglieder der Allianz können diese Arbeit übernehmen. Sie erfordert die Zusammenarbeit mit dem königlichen Geheimdienst von Sturmwind.",al={"nur für die allianz","auch für die horde möglich"}}},fx={be1ed035={q="Warum schickt Glimm Springspross Euch zum SI:7, anstatt selbst zu gehen?",a="Glimm Springspross besitzt selbst keinen Fernzünder. Da Ihr eine kontrollierte Explosion wollt, die Eure Gliedmaßen intakt lässt, verweist sie Euch an die gerissenen Leute beim SI:7, von denen sie glaubt, dass sie einen finden können. Die Quest besagt nicht, warum sie nicht selbst geht.",al={"warum ich glimmer springspross","warum den spieler zum si:7 schicken","warum kann glimmer nicht nach sturmwind gehen"}}},fp="24,124,18.229.0,21.299.0,30.108.0,40.84.0,53.136.0,59.133.0,41.95.0,37.125.0"}
P.entries["quest:92751"] = {n="Detonation at a Distance",s="In Mondbruch haben Sprengungen unter Westfall die Aufmerksamkeit des SI:7 erregt. Jasper Teufel, ein Agent aus Sturmwind, schickt ein Fernzünderset, damit Ihr die Arbeit aus sicherer Entfernung erledigen könnt.",h="In Mondbruch haben Sprengungen unter Westfall die Aufmerksamkeit des SI:7 erregt.",kw={"die todesminen","der zwergendistrikt","jasper teufel","mondbruch","fernzünder","si:7","glimm springspross","westfall"},ang={["class:Rogue"]="Als Schurke erhaltet Ihr bei Eurer Begegnung mit Jasper Teufel einen Einblick in das geheime Netzwerk des SI:7. Es behält Agenten im Einsatz im Auge und versorgt sie unauffällig mit Werkzeugen.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie Sturmwind versucht, Westfall durch verdeckte Ingenieursarbeit und Geheimdienstarbeit statt durch offene militärische Gewalt zurückzugewinnen.",["profession:Engineering"]="Als Ingenieur wisst Ihr einen Fernzünderprototyp zu schätzen, der Ladungen aus der Ferne auslöst und bei Höhlensprengungen riskante, von Hand entzündete Zündschnüre vermeidet.",["race:Gnome"]="Als Gnom erkennt Ihr an Glimm Springspross' Arbeit, wie gnomische Ingenieurskunst Sturmwinds Spione mit Prototypen versorgt."},sec={{t="Augen in den Schatten",b="Jasper Teufel und der SI:7 beobachten die Geschehnisse in Sturmwinds Landen, einschließlich Westfalls unruhiger Grenze. Als ihn Berichte über Sprengarbeiten in Mondbruch erreichen, weiß Teufel bereits, was in den verlassenen Bergwerksstollen unter dem Umland geschieht."},{t="Ein Prototyp als Lösung",b="Explosionen in engen Höhlen gefährden alle in der Nähe. Jasper Teufel gibt Euch den Prototyp eines Fernzündersets, den Ingenieure im Dienste der Allianz gebaut haben. Damit lassen sich Sprengladungen unter Westfall von außen zünden. Er schickt Euch mit dem Set zu Glimm Springspross in Sturmwinds Zwergendistrikt und warnt Euch, den SI:7 gegenüber Euren elfischen Verbündeten zu erwähnen."}},faq={{q="Wer ist Jasper Teufel?",a="Jasper Teufel ist ein Agent des SI:7, Sturmwinds Geheimdienst. Er überwacht verborgene Bedrohungen im ganzen Königreich und stellt Werkzeuge bereit, um ihnen zu begegnen.",al={"jasper teufel","wer vergibt detonation at a distance","auftragsgeber"}},{q="Warum interessiert sich der SI:7 für Mondbruch?",a="Banditen und Gesetzlose halten Mondbruch besetzt, von dessen Oberfläche aus ein Weg in die Todesminen führt. Sprengarbeiten tief unter Westfall haben die Aufmerksamkeit von Sturmwinds Geheimdienstnetz geweckt.",al={"warum mondbruch","verbindung zu defias","höhlen in westfall"}},{q="Wer ist Glimm Springspross?",a="Glimm Springspross ist eine Gnomeningenieurin in Sturmwinds Zwergendistrikt. Sie bereitet Sprengstoff für die Sprengarbeiten vor.",al={"glimm springspross","wer erhält den fernzünder","abgabe-npc"}},{q="Wer ist der „Elfenfreund“, den Jasper Teufel erwähnt?",a="Jasper Teufel meint Alba Fairmoon, die als Elfe dem Gift in Westfall nachgeht und Euch losgeschickt hat, um Sprengstoff zu finden. Der SI:7 hält seine direkte Unterstützung vor außenstehenden Verbündeten geheim.",al={"elfenfreund","elf nichts erzählen","jasper teufel elf"}},{q="Wozu dient das Fernzünderset?",a="Das Fernzünderset löst Sprengladungen aus sicherer Entfernung aus. Damit können Agenten unterirdische Gänge freiräumen oder zum Einsturz bringen, ohne darin eingeschlossen zu werden.",al={"fernzünder","fernzünderset","was macht das set"}},{q="Wohin führt Euch dieser Auftrag?",a="Ihr bringt das Fernzünderset zu Glimm Springspross im Zwergendistrikt von Sturmwind.",al={"wohin geht es","auftragsroute","abgabeort"}}},fx={dd5ef9f7={q="Warum hilft Jasper Teufel bei dem Fernzünder?",a="Jasper Teufel bietet einen fortschrittlichen Fernzünder-Prototyp für Glimm an. Er bittet Euch, seine Beteiligung vor Eurer Elfenfreundin geheim zu halten, während Ihr bei der geplanten Sprengung helft.",al={"motiv von jasper teufel","warum bei der zündvorrichtung helfen","warum gibt jasper teufel das set"}},["2c859344"]={q="Warum bittet Jasper Teufel Euch, anstatt es selbst zu erledigen?",a="Jasper Teufel vertraut Euch den Fernzünder-Prototyp für Glimm an und bittet Euch gleichzeitig, seine Beteiligung vor Eurer Elfenfreundin zu verbergen. Er erklärt nicht, warum er ihn nicht persönlich übergeben kann.",al={"warum schickt ihr mich","warum liefert jasper teufel es nicht selbst","warum nicht si:7 agenten"}}},fp="24,179,19.243.0,20.334.1,18.154.0,35.165.0,27.120.0,44.162.0,42.162.0,31.88.0"}
P.entries["quest:92752"] = {n="Explosive Consultation",s="In Westfall schickt Glimm Springspross eine instabile Sprengladung an Alba Fairmoon. Die scharfen Sprengladungen müssen sie sicher erreichen, ohne dass der Zünder ausgelöst wird.",h="In Westfall schickt Glimm Springspross eine instabile Sprengladung an Alba Fairmoon.",kw={"alba fairmoon","zünder","explosive consultation","sprengladungen","gnomische ingenieurskunst","glimm springspross","westfall"},ang={["faction:Alliance"]="Als Abenteurer der Allianz seht Ihr, wie Agenten in ganz Westfall unkonventionelle Waffen gegen befestigte Banditenlager und außer Kontrolle geratene Maschinen einsetzen.",["profession:Engineering"]="Als Ingenieur wisst Ihr, dass gnomische Sprengkörper hohe Sprengkraft und einen hochempfindlichen Zünder mitbringen.",["race:Gnome"]="Als Gnom seht Ihr, wie Glimm Springspross Gnomeregans explosive Lösungen an Westfalls umkämpfte Front bringt."},sec={{t="Eine instabile Lieferung",b="Glimm Springspross hat ein Bündel Besonders zerstörerischer Sprengladungen für Alba Fairmoon fertiggestellt. Im kriegsgebeutelten Westfall bedrohen bereits Defias-Banditen und wilde Bestien die Straße. Eine scharfe Sprengladung macht die Reise noch gefährlicher."},{t="Mit Vorsicht behandeln",b="Glimm Springspross warnt Euch, auf den Zünder zu achten. Die Sprengladungen sollen den verborgenen Industriebetrieb in den Todesminen zerstören, der Westfalls Ackerland vergiftet. Alba Fairmoon braucht die Sprengladungen unversehrt, bevor sie sie einsetzen kann."}},faq={{q="Wer vergibt die Quest Explosive Consultation?",a="Glimm Springspross, ein gnomischer Tüftler im Zwergendistrikt von Sturmwind, gibt Euch die Sprengladungen für den Transport.",al={"wer vergibt explosive consultation","questgeber explosive consultation","glimm springspross quest"}},{q="Wer erhält die Sprengladungen am Ende der Quest?",a="Alba Fairmoon in Westfall erhält die Besonders zerstörerischen Sprengladungen.",al={"wohin müssen die sprengladungen","wer gibt explosive consultation ab","alba fairmoon sprengladung"}},{q="Welchen Gegenstand sollt Ihr transportieren?",a="Ihr tragt ein Paket Besonders zerstörerischer Sprengladungen mit einem scharfen, empfindlichen Zünder.",al={"was übergibt glimm","explosive consultation gegenstand","was ist das für eine bombe"}},{q="Warum werden in Westfall Sprengladungen gebraucht?",a="Alba Fairmoon verfolgte die Giftstoffe, die Westfalls Ackerland vergiften, bis zu einem gewaltigen Industriebetrieb, der in den Todesminen verborgen liegt. Sie suchte einen Ingenieur, der Sprengladungen liefern konnte, die stark genug waren, ihn zu zerstören.",al={"warum brauchen sie bomben","westfall sprengladungen zweck","warum etwas in westfall sprengen"}},{q="Ist diese Quest für Abenteurer der Horde verfügbar?",a="Nein. Glimm Springspross und Alba Fairmoon unterstützen die Einsätze der Allianz, daher können nur Abenteurer der Allianz diesen Auftrag übernehmen.",al={"kann die horde explosive consultation machen","horde explosive consultation"}},{q="Warnt Glimm Springspross Euch vor einer bestimmten Gefahr?",a="Glimm Springspross warnt Euch, dass die Bombe scharf ist, und sagt Euch, den Zünder auf der Reise mit äußerster Vorsicht zu behandeln.",al={"glimms warnung","bombenwarnung westfall"}}},fx={bb434565={q="Warum möchte Glimm Springspross, dass der Sprengstoff an Alba geliefert wird?",a="Glimm Springspross hat den Zusammenbau der Besonders zerstörerischen Sprengladungen abgeschlossen, die für Alba Fairmoons Bemühungen in Westfall in Auftrag gegeben wurden. Nachdem sie die gefährliche Fracht hergestellt hat, benötigt Glimm einen Abenteurer, der den heiklen, gefährlichen Transport zurück zu Alba übernimmt, damit die Bombe wie beabsichtigt eingesetzt werden kann.",al={"warum sprengstoff an alba liefern","motiv von glimmer springspross","warum hat glimmer eine bombe gebaut"}}},fp="22,151,19.237.0,18.246.0,44.105.0,52.68.0,43.86.0,38.190.0,45.117.0,60.121.0"}
P.entries["quest:92753"] = {n="Destruction in Deadmines",s="In den Todesminen unter Mondbruch verseucht die Industrie der Defias das Land. Alba Fairmoon vermutet ihre metallurgische Schmiede als Ursache und schickt Euch los, um sie mit Sprengladungen zu zerstören.",h="In den Todesminen unter Mondbruch verseucht die Industrie der Defias das Land.",kw={"alba fairmoon","die todesminen","bruderschaft der defias","besonders zerstörerische sprengladungen","metallurgische schmiede","mondbruch","sabotage","westfall"},ang={["faction:Alliance"]="Die Zerstörung der Schmiede der Defias trifft die Maschinen und Waffen, die von Westfall aus Sturmwinds Souveränität bedrohen.",["profession:Engineering"]="Alba Fairmoon schlägt vor, spezielle Besonders zerstörerische Sprengladungen gegen schwere Industrieanlagen einzusetzen, um die vermutete Quelle der Verseuchung zu beseitigen.",["profession:Mining"]="Die Todesminen waren einst Sturmwinds ertragreichste Gold- und Eisenminen. Die Defias haben sie in einen befestigten Verhüttungskomplex verwandelt, der die Erde verseucht."},sec={{t="Sabotage in der Gießerei",b="Unter Mondbruch liegt in den Todesminen ein befestigter Komplex, der die Bruderschaft der Defias antreibt. Seine schwere Schmiede schmilzt Metall und fertigt Maschinen. Alba Fairmoon hält die Schmiede für den wahrscheinlichen Ursprung der Verseuchung, die das Gebiet heimsucht. Sie will sie zerstören lassen."},{t="Ein entscheidender Sprengschlag",b="Jenseits von Barrikaden, Halsabschneidern und Gobliningenieuren wartet die Schmiede. Ihr führt Besonders zerstörerische Sprengladungen mit Euch und platziert sie neben den Schmiedeanlagen. Dann flieht Ihr in die Hügel oberhalb von Mondbruch. Alba Fairmoon wartet dort, um die Sprengladung zu zünden, in der Hoffnung, dass das Land beginnen kann, sich zu erholen."}},faq={{q="Was ist das Ziel dieser Mission?",a="Ihr sollt die Todesminen unter Mondbruch betreten, die metallurgische Schmiede der Bruderschaft der Defias finden und Besonders zerstörerische Sprengladungen in ihrer Nähe platzieren. Alba Fairmoon wartet am Ausgang.",al={"questziel","was ist zu tun","was ist destruction in deadmines"}},{q="Wer ist Alba Fairmoon?",a="Alba Fairmoon ist eine Agentin der Allianz in Westfall. Sie glaubt, dass die Verseuchung und das Gift in der Region von der massiven Metallverhüttung und den Industriearbeiten in den Todesminen stammen.",al={"wer ist alba","alba fairmoon hintergrundgeschichte","questgeber"}},{q="Warum gilt die Schmiede der Defias als so gefährlich?",a="Alba vermutet, dass die große metallurgische Schmiede in den Todesminen die Quelle des Giftes ist. Sie hofft, dass ihre Zerstörung dem Land ermöglicht, sich allmählich zu erholen.",al={"warum die schmiede zerstören","was macht die schmiede","schmiede gift"}},{q="Wo trifft der Spieler Alba nach dem Platzieren der Sprengladungen?",a="Alba Fairmoon wartet in den Hügeln hinter Mondbruch, außerhalb der Todesminen nahe dem oberen Minenausgang. Sie ist bereit, die Sprengladungen zu zünden, sobald Ihr sicher herausgekommen seid.",al={"wo wartet alba","todesminen ausgang position","abgabeort"}},{q="Wo in den Todesminen befindet sich die Schmiede?",a="Die Schmiede liegt tief in den Todesminen, hinter den Bergbaustollen in der industriellen Gießerei, wo Arbeiter der Defias und Goblinaufseher tätig sind.",al={"wo ist die schmiede","schmiede position todesminen","schmiede finden"}},{q="Erholt sich das Land sofort nach der Zerstörung der Schmiede?",a="Alba hofft, dass das Ende der massiven Metallverhüttung dem Land um Mondbruch ermöglicht, sich zu erholen. Die Spuren jahrelanger Industrie und Vernachlässigung durch die Defias werden erst mit der Zeit verschwinden.",al={"wird sich das land erholen","hört die vergiftung auf","schmiede folgen"}}},fx={cfdfebff={q="Warum will Alba Fairmoon, dass die Schmiede zerstört wird?",a="Alba glaubt, dass die Defias-Schmiede tief in den Todesminen die wahre Quelle der üblen Verschmutzung ist, die in die umliegende Erde sickert. Durch das Anbringen von Sprengstoff und das Zerschmettern des massiven Schmelzbetriebs hofft sie, die Fäulnis an der Wurzel zu packen, damit sich der verwundete Boden von Westfall endlich erholen kann.",al={"motiv von alba fairmoon","warum die schmiede der todesminen zerstören","warum will alba das getan haben"}}},fp="24,177,22.263.0,16.278.1,33.180.0,21.167.0,48.146.0,62.163.0,48.141.0,52.146.0"}
P.entries["quest:928"] = {n="Krone der Erde",s="Im Laubschattental tragt Ihr Mondbrunnenwasser nach Süden zu Corithras Mondzorn in Dolanaar. Die Reise führt Euch aus der behüteten Ausbildung zu den umfassenderen Aufgaben beim Schutz Teldrassils.",h="Im Laubschattental tragt Ihr Mondbrunnenwasser nach Süden zu Corithras Mondzorn in Dolanaar.",kw={"aldrassil","corithras mondzorn","crown of the earth","dolanaar","mondbrunnen","teilweise gefülltes gefäß","laubschattental","teldrassil","tenaron sturmgewalt"},ang={["class:Druid"]="Als Druide verbindet Euch das Tragen des geweihten Wassers mit den Bemühungen, Teldrassils wachsendes Ökosystem zu pflegen und im Gleichgewicht zu halten.",["class:Priest"]="Als Priester spiegelt das Tragen von Mondbrunnenwasser, das durch Elune's Grace geweiht wurde, Eure Pflicht wider, für das geistige Wohl Eurer Gemeinschaft zu sorgen.",["race:NightElf"]="Als junger Kaldorei ist das Verlassen des Laubschattentals ein Übergangsritus, wenn Ihr aufbrecht, um Eurem Volk zu dienen."},sec={{t="Abschied vom Hain",b="Ihr habt das verzauberte Wasser aus dem Mondbrunnen des Laubschattentals gekostet. In der Krone von Aldrassil versiegelt Tenaron Sturmgewalt das gesammelte Wasser in einem größeren Gefäß und schickt Euch über den geschützten Hain hinaus. Die Straße führt nach Süden nach Dolanaar, durch Wälder, in denen Gefahren schwerer vorherzusehen sind."},{t="Der Weg nach Dolanaar",b="Dolanaar ist das erste größere Dorf jenseits des Laubschattentals und liegt an den Kopfsteinpflasterwegen durch das Zentrum Teldrassils. Sein Mondbrunnen liegt im Herzen des Dorfes. Corithras Mondzorn, ein Ältester, der über die Schutzbemühungen auf den Ästen wacht, wartet dort. Das Gefäß, das Ihr tragt, verbindet Euch mit den umfassenderen Bemühungen zum Schutz des Weltbaums."}},faq={{q="Was trage ich nach Dolanaar?",a="Ihr tragt das Teilweise gefüllte Gefäß mit geweihtem Wasser aus dem Mondbrunnen des Laubschattentals. Tenaron Sturmgewalt hat Eure Gabe gesammelt, damit Corithras Mondzorn sie für Rituale in ganz Teldrassil verwenden kann.",al={"was ist das gefäß","teilweise gefülltes gefäß hintergrund","was ist das für wasser"}},{q="Wer ist Corithras Mondzorn?",a="Corithras Mondzorn ist ein Ältester der Nachtelfen am Mondbrunnen in Dolanaar. Er leitet die Ankommenden bei Riten und Untersuchungen an, die den Weltbaum erhalten sollen.",al={"wer ist corithras","corithras mondzorn aufgabe","wo ist corithras"}},{q="Warum schickt mich Tenaron aus dem Laubschattental fort?",a="Das Laubschattental vermittelt Euch die Grundlagen, während sich Teldrassils Probleme über die Äste erstrecken. Nachdem Ihr Euch gegen die örtlichen Bedrohungen bewährt und die Mondbrunnen geehrt habt, schickt Tenaron Euch nach Dolanaar, wo umfassendere Aufgaben warten.",al={"warum das laubschattental verlassen","warum nach dolanaar gehen","tenaron schickt mich fort"}},{q="Wo verläuft der Weg nach Dolanaar?",a="Folgt dem Kopfsteinpflasterweg von Aldrassil nach Süden und durch die Tore des Laubschattentals. Bleibt auf der Straße, die sich nach Süden und Westen windet, und sie wird Euch nach Dolanaar führen.",al={"wie nach dolanaar gelangen","weg nach dolanaar","straße aus dem laubschattental"}},{q="Warum warnt Tenaron vor gefährlichen Bestien?",a="Tenaron sagt, dass in letzter Zeit gefährliche Bestien durch die Wälder streifen. Selbst in Teldrassils heiligen Ästen sind die Wildtiere aggressiv geworden, weshalb Ihr Euch in Gefahr begebt, wenn Ihr den gepflasterten Weg verlasst.",al={"warum sind bestien gefährlich","verderbte bestien teldrassil","warnung auf der straße bleiben"}},{q="Was geschieht nach der Ankunft in Dolanaar?",a="Corithras Mondzorn nimmt das Gefäß entgegen und schickt Euch los, um Phiolen an anderen Mondbrunnen in ganz Teldrassil zu füllen. Die Arbeit setzt sich auf dem ganzen Baum fort.",al={"was kommt nach crown of the earth","dolanaar nächste quest","was macht corithras"}}},fx={a4343de4={q="Warum schickt Tenaron Sturmgewalt einen Abenteurer, anstatt das Gefäß selbst zu überbringen?",a="Tenaron Sturmgewalt beaufsichtigt die Zweige von Aldrassil und kümmert sich um die heiligen Angelegenheiten im Laubschattental, wo junge Nachtelfen zuerst ihre Künste verfeinern. Er kann seine Pflichten auf dem großen Baum nicht einfach aufgeben, um kuriertes Wasser über Teldrassil zu tragen. Das Aussenden vielversprechender Initianden erlaubt es ihm, Eure Disziplin und Bereitschaft für die weitere Welt zu testen, während er sicherstellt, dass das heilige Gefäß Corithras Mondzorn erreicht, ohne das Laubschattental unbeaufsichtigt zu lassen.",al={"warum schickt ihr mich","warum braucht tenaron mich","warum das gefäß nicht selbst nehmen"}}},fp="18,172,17.281.0,20.317.0,31.196.0,26.161.0,46.219.0,30.160.0,45.177.0,37.142.0"}
P.entries["quest:92812"] = {n="Economic Warfare",s="Ein Gelkis-Zentaur bittet Euch, geschnitzte Totems anderer Clans zu sammeln. Diese Totems erzählen Geschichten und geben den Gelkis mehr Macht, mit den Magram zu verhandeln.",h="Ein Gelkis-Zentaur bittet Euch, geschnitzte Totems anderer Clans zu sammeln.",kw={"tauschhandel","zentauren","desolace","wirtschaftliche kriegsführung","gelkis","magram","totem","handel"},sec={{t="Geschichten im Tausch",b="Die Gelkis halten an einem alten Brauch der Zentauren fest: Die Clans tauschen geschnitzte Totems, die von großen Taten einer Person oder eines Clans erzählen. Obwohl die Clans im Streit liegen, ehren sie diese Handelsweise weiterhin. Ihr könnt den Gelkis Totems bringen, die gefallenen Zentauren anderer Clans abgenommen wurden, und ihnen so mehr Tauschware verschaffen."},{t="Vorräte der Gelkis",b="Die Gelkis nehmen Eure Gaben in ihre Sammlung auf, und ihre Macht wächst. Es liegt noch ein weiter Weg vor ihnen, bis sie den Magram-Clan überwinden können."}},faq={{q="Was tauschen die Zentauren?",a="Die Zentauren-Clans tauschen geschnitzte Totems, die große Errungenschaften einer Person oder eines Clans darstellen.",al={"handelswaren der zentauren","was wird getauscht"}},{q="Warum sind die Totems für die Gelkis wichtig?",a="Die Gelkis nutzen die Totems als Tauschmittel, und eine größere Sammlung stärkt sie.",al={"gelkis-totems","wert der totems"}},{q="Tauschen die Zentauren auch während des Kampfes?",a="Ja. Die Clans ehren die Tradition trotz ihres endlosen Konflikts, auch wenn es nur noch wenige Gelegenheiten zum Tauschen gibt.",al={"handel der zentauren-clans","handel während des konflikts"}},{q="Welchen Clan hoffen die Gelkis zu überwinden?",a="Die Gelkis hoffen, den Magram-Clan zu überwinden.",al={"feind der gelkis","magram-clan"}}},fp="16,152,16.298.0,13.152.1,26.99.0,43.99.0,42.113.0,42.44.0"}
P.entries["quest:92819"] = {n="Destruction in Deadmines",s="Alba Fairmoon schickt Euch gegen die Schmiede der Defias unter Westfall. Der Sprengstoff ist platziert, und sie wartet in den Hügeln hinter Mondbruch mit dem Zünder.",h="Alba Fairmoon schickt Euch gegen die Schmiede der Defias unter Westfall.",kw={"alba fairmoon","die todesminen","defias","destruction in deadmines","zünder","sprengstoff","sabotage","westfall"},ang={["class:Rogue"]="Ihr dringt in feindliches Gebiet ein, platziert Sprengladungen und schleicht Euch vor der Explosion davon, um einen verdeckten Sabotageakt auszuführen.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr mit jedem Schlag gegen die Hochburg der Defias, Westfalls bedrängte Bauernhöfe und Sturmwinds südliche Grenze zu sichern.",["profession:Engineering"]="Sprengarbeiten und Fernzünder stehen im Mittelpunkt dieses Auftrags, ein Handwerk, das Ingenieure ansprechen könnte."},sec={{t="Sabotage unter Westfall",b="Unter Westfall liegt die Streitmacht der Bruderschaft der Defias in den Todesminen. Alba Fairmoon schickt Euch los, um die in den Minen verborgene Schmiede zu sabotieren. Der Sprengstoff ist daneben platziert. Ihr kehrt zu Alba in den Hügeln hinter Mondbruch zurück, wo Ihr ihn aus sicherer Entfernung zünden könnt. Sie hofft, dass die Explosion dem vergifteten Land von Westfall ermöglicht, sich allmählich zu erholen."},{t="Der Zünder",b="Tief in den Todesminen wartet die Sprengladung neben der Schmiede. Nachdem Ihr Alba Fairmoon in den Hügeln hinter Mondbruch wieder getroffen habt, könnt Ihr sie mit einem Fernzünder von außerhalb der Höhlen aus zünden. Sie hofft, dass die Zerstörung der Schmiede dem vergifteten Land von Westfall ermöglicht, sich allmählich zu erholen."}},faq={{q="Wer bietet die Quest „Destruction in den Todesminen“ an?",a="Alba Fairmoon, eine Agentin in Westfall, schickt Euch gegen die Hochburg der Bruderschaft der Defias.",al={"wer vergibt destruction in deadmines","questgeber todesminen sprengung","alba fairmoon quest"}},{q="Was ist das Hauptziel dieser Mission?",a="Ihr zündet den Sprengstoff, der neben der Schmiede der Defias in den Todesminen platziert wurde. Kehrt zu Alba Fairmoon zurück und benutzt dann den Zünder außerhalb der Minen.",al={"was ist in destruction in deadmines zu tun","destruction in deadmines ziel","destruction in deadmines abschließen"}},{q="Warum werden die Todesminen mit Sprengstoff angegriffen?",a="Alba Fairmoon hat das Gift im Ackerland von Westfall zu einer großen metallurgischen Schmiede zurückverfolgt, die in den Todesminen verborgen liegt. Sie hofft, dass deren Zerstörung dem Land ermöglicht, sich allmählich zu erholen.",al={"warum todesminen sprengen","todesminen sabotage hintergrundgeschichte","warum zünder in den todesminen benutzen"}},{q="Wo findet diese Quest statt?",a="Nachdem der Sprengstoff platziert ist, kehrt Ihr zu Alba Fairmoon in den Hügeln hinter Mondbruch zurück, außerhalb der Todesminen.",al={"destruction in deadmines ort","wo ist destruction in deadmines","todesminen zünder standort"}},{q="Ist diese Mission für Spieler der Horde verfügbar?",a="Nein. Alba Fairmoon arbeitet mit Agenten der Allianz zusammen, die Westfall gegen die Bruderschaft der Defias verteidigen.",al={"destruction in deadmines nur für allianz","destruction in deadmines für horde verfügbar"}},{q="Welche Bedrohung stellt die Bruderschaft der Defias in Westfall dar?",a="Die Bruderschaft der Defias vertrieb Bauern, überfiel Siedlungen und besetzte Westfalls verlassene Minen. Tief in den Todesminen bereiten sie einen bewaffneten Aufstand vor, der das Königreich Sturmwind bedroht.",al={"defias hintergrundgeschichte westfall","warum defias bekämpfen","was machen die defias in den todesminen"}}},fp="24,158,25.344.0,13.261.0,46.95.0,46.145.0,41.169.0,33.115.0,43.99.0,57.209.0"}
P.entries["quest:92834"] = {n="Avenged Tenfold",s="Elaadrin wendet sich von der Diplomatie der Vergeltung zu, nachdem der Kult der Al'Aketh seinen Appell mit Gewalt beantwortet. Der Gelehrte des Hohen Ordens hatte seinen teuren Freund Belathaan Brightwish zum Schrein von Akir nördlich von Valanaar geschickt, um Frieden zu suchen.",h="Elaadrin wendet sich von der Diplomatie der Vergeltung zu, nachdem der Kult der Al'Aketh seinen Appell mit...",kw={"al'aketh","avenged tenfold","belathaan brightwish","elaadrin","gustberry fields","der hohe orden","schrein von akir","windformer","windstone charms"},ang={["class:Mage"]="Als Magier könnt Ihr sehen, wie Elaadrin knisternde arkane Macht kanalisiert, wenn er provoziert wird. Die Hingabe des Hohen Ordens an die Logik geht mit gewaltiger magischer Kraft einher."},sec={{t="Der diplomatische Vorstoß",b="Die Gewalt des Kults der Al'Aketh führte bei Fraktionen wie den Peacekeepers und den Windformern zu bewaffnetem Imponiergehabe. Elaadrin sprach für den Hohen Orden und betrachtete solche Machtdemonstrationen als törichte Eskalation. Sein Orden schätzt Pragmatismus und meidet Konflikte, also glaubte er weiterhin, dass ein vernünftiger Dialog gelingen könnte. Er schickte seinen engen Freund Belathaan Brightwish zum Schrein von Akir, um Frieden auszuhandeln."},{t="Eine grausige Ablehnung",b="Der Kult der Al'Aketh antwortete mit einem Paket, das Belathaans abgetrennte, mit Silberpigment überzogene Zunge enthielt. Elaadrin war entsetzt und von Schuldgefühlen geplagt. Er erkannte, dass sein ehrenhafter Weg seinen teuren Freund das Leben gekostet hatte, und räumte ein, dass die Windformer Verhandlungen zu Recht ablehnten. Er gab die Diplomatie auf und rief Reisende dazu auf, die Kultisten in den Gustberry Fields und am Schrein von Akir zu jagen und ihre Al'Aketh Windstone Charms zu sammeln."},{t="Besonnenheit und arkaner Zorn",b="Der Hohe Orden stellt Logik über Gefühl und hält es meist für den besonnenen Weg, Blutvergießen zu vermeiden. Doch Elaadrin zeigt, wie kalte Logik in beide Richtungen schneidet, wenn Feinde Zurückhaltung mit Hilflosigkeit verwechseln. Knisternde arkane Energie sammelt sich um ihn. Der Hohe Orden bevorzugt Frieden, doch wer seine Abgesandten niedermetzelt, muss mit überwältigender Vergeltung rechnen."}},faq={{q="Wer ist Elaadrin?",a="Elaadrin vertritt den Hohen Orden und suchte zunächst Frieden mit dem Kult der Al'Aketh. Nachdem sie seinen Abgesandten und engen Freund Belathaan Brightwish ermordet hatten, gab er die Diplomatie auf und befahl die Vernichtung der Kultisten.",al={"wer ist elaadrin","questgeber avenged tenfold","wer vergibt diese quest"}},{q="Was geschah mit Belathaan Brightwish?",a="Belathaan Brightwish war Elaadrins enger Freund und sein Abgesandter zum Schrein von Akir, entsandt, um einen friedlichen Dialog mit dem Kult der Al'Aketh zu eröffnen. Der Kult ermordete ihn und schickte Elaadrin eine Schachtel mit seiner abgetrennten, mit Silberpigment bemalten Zunge zurück.",al={"was geschah mit belathaan","wer ist belathaan brightwish","warum starb belathaan"}},{q="Wer sind die Kultisten der Al'Aketh?",a="Die Al'Aketh sind ein gewalttätiger Kult, der nördlich von Valanaar rund um die Gustberry Fields und den Schrein von Akir aktiv ist. Sie tragen Gebetsamulette namens Al'Aketh Windstone Charms und beantworten friedliche Annäherungsversuche von Außenstehenden mit Gewalt.",al={"wer sind alaketh","wer sind die kultisten","kult der al'aketh"}},{q="Was ist der Hohe Orden?",a="Der Hohe Orden schätzt Pragmatismus, Intellekt und Logik. Seine Mitglieder ziehen es im Allgemeinen vor, Konflikte zu vermeiden und Leben zu bewahren, können aber auf eine schwere Kränkung mit heftiger magischer Vergeltung antworten.",al={"was ist der hohe orden","überzeugungen des hohen ordens"}},{q="Wer sind die Windformer?",a="Die Windformer und die Peacekeepers sind Fraktionen, die die Gewalt des Kults der Al'Aketh zunächst mit Machtdemonstrationen und Imponiergehabe beantworteten. Elaadrin nannte ihre Reaktion leichtsinnig, räumte aber später ein, dass sie diplomatische Appelle zu Recht ablehnten.",al={"wer sind die windformer","windformer peacekeepers"}},{q="Wo sind die Kultisten der Al'Aketh zu finden?",a="Die Kultisten der Al'Aketh versammeln sich nördlich von Valanaar, in den Gustberry Fields und rund um den Schrein von Akir. Belathaan Brightwish wurde vor seinem Tod zum Schrein geschickt.",al={"wo ist der schrein von akir","wo sind die gustberry fields","wo sind die kultisten"}}},fp="15,227,23.376.0,20.443.1,25.341.0,16.209.0,38.249.0,30.223.0,23.186.0,24.239.0,38.164.0"}
P.entries["quest:92840"] = {n="Catching Wind",s="An den Menhiren der Warte sucht der Hohe Orden nach Messwerten, die helfen könnten, Zephras zu retten. Seine Expedition stößt im Shen'darhochland auf erbitterten Widerstand der Windformer.",h="An den Menhiren der Warte sucht der Hohe Orden nach Messwerten, die helfen könnten, Zephras zu retten.",kw={"al'aketh","catching wind","fillion","der hohe orden","index esoteria","die menhire der warte","shen'darhochland","valanaar","windformer","windsteinformationen","zephras"},ang={["class:Mage"]="Als Magier schätzt Ihr vielleicht die sorgfältigen Messungen des Index Esoteria und betrachtet elementare Kräfte als Forschungsgebiet.",["class:Shaman"]="Als Schamane fühlt Ihr Euch vielleicht hin- und hergerissen zwischen der Ehrfurcht der Windformer vor elementaren Strömen und der wohlbemessenen Entnahme elementarer Kraft durch den Hohen Orden."},sec={{t="Die Sturmwinde vermessen",b="Der Hohe Orden erforscht die wilden elementaren Ströme des Shen'darhochlands in der Hoffnung, Zephras zu retten. An den Menhiren der Warte nutzen seine Forscher einen Index Esoteria, ein Werkzeug zur Datengewinnung aus den gewaltigen Windsteinformationen. Die Windformer betrachten diese Untersuchungen als frevelhaften Übergriff auf den Wind."},{t="Dogma trifft Forscherdrang",b="Die Expedition des Hohen Ordens und die Windformer geraten an den Steinen bald aneinander. Die Windformer bezeichnen die Erforschung und Entnahme elementarer Energie als Entweihung ihrer heiligen Traditionen. Der Hohe Orden hält sie für engstirnig in ihrem Glauben, ähnlich wie die gewalttätigen Al'Aketh. Er wird nicht zulassen, dass ihr Widerstand seine Arbeit zur Rettung des Reiches aufhält."},{t="Das Massaker an den Menhiren",b="An den Menhiren der Warte stößt der Hohe Orden auf feindseligen Widerstand, und bei dem Zusammenstoß fließt Blut zwischen den Windsteinen. Der Hohe Orden sichert seine Messwerte mit dem Index Esoteria. Die Windformer bezeichnen die Kämpfe als Massaker, und die Fehde wirft einen Schatten über Valanaar."}},faq={{q="Worum geht es in der Quest Catching Wind?",a="Der Hohe Orden entsendet einen Beauftragten, um an den Menhiren der Warte im Shen'darhochland elementare Energie zu erforschen. Der Beauftragte trägt einen Index Esoteria bei sich, um trotz des Widerstands der Windformer Daten aus den Windsteinen zu gewinnen.",al={"was ist catching wind","catching wind quest"}},{q="Was ist ein Index Esoteria?",a="Der Index Esoteria ist ein Instrument des Hohen Ordens, das elementare Energie aus den gewaltigen Windsteinformationen an den Menhiren der Warte entnimmt, misst und aufzeichnet.",al={"was ist der index esoteria","index esoteria gerät"}},{q="Wer sind die Windformer?",a="Die Windformer verteidigen ihre heiligen Stätten und ihre überlieferten Glaubensvorstellungen zur Elementarmagie. Sie betrachten die Forschung und die Geräte des Hohen Ordens als Entweihung und kämpfen dafür, Außenstehende von den Windsteinen fernzuhalten.",al={"wer sind die windformer","windformer hintergrundgeschichte"}},{q="Wer sind die Al'Aketh?",a="Die Al'Aketh sind eine gewalttätige Gruppe, mit der der Hohe Orden die Windformer vergleicht. Der Hohe Orden hält beide Gruppen für gefährliche Eiferer, die an starre Glaubensvorstellungen gebunden sind, bezeichnet die Al'Aketh jedoch als gewalttätiger.",al={"wer sind die al'aketh","al aketh"}},{q="Wo befinden sich die Menhire der Warte?",a="Die Menhire der Warte liegen im Shen'darhochland. Ihre gewaltigen Windsteinformationen kanalisieren starke elementare Ströme, was den Ort für die Forschung des Hohen Ordens bedeutsam macht.",al={"wo sind die menhire der warte","menhire der warte standort"}},{q="Wer ist Fillion?",a="Fillion ist ein Beauftragter oder Forscher des Hohen Ordens, der entsandt wurde, um an den Menhiren der Warte elementare Energie zu erforschen. Nach einer Konfrontation mit den Windformern entsandte der Hohe Orden einen Abenteurer mit dem Index Esoteria, um die Daten zu sichern.",al={"was ist mit fillion geschehen","wer ist fillion"}},{q="Warum braucht der Hohe Orden die Windsteindaten?",a="Der Hohe Orden glaubt, dass Wissen über die elementaren Kräfte des Reiches entscheidend ist, um Zephras zu retten. Er hält Forschung für notwendig, um Bedrohungen zu überwinden, denen überlieferte Glaubensvorstellungen nicht beikommen können.",al={"warum will der hohe orden daten","zephras retten"}}},fp="13,177,19.306.0,26.322.0,27.272.1,38.234.0,26.168.0,24.199.0,21.205.0,47.183.0,15.231.0,48.184.0"}
P.entries["quest:92849"] = {n="The Missing Scholar",s="Ihr folgt der Spur von Fillion Flamebreeze, der nach einem Auftrag bei den Menhiren der Warte verschwand. Die Suche führt nach Norden zu einer Höhle, in die ihn eine geflügelte Bestie gezerrt hat.",h="Ihr folgt der Spur von Fillion Flamebreeze, der nach einem Auftrag bei den Menhiren der Warte verschwand.",kw={"fillion","fillion flamebreeze","die menhire der warte","the missing scholar","windformer","geflügelte bestie"},sec={{t="Der verschwundene Forscher",b="Entlang des Weges, den Fillion Flamebreeze auf seinen Reisen nahm, findet Ihr Anzeichen von Unheil. Sie deuten auf einen Übergriff hin. Wer ihnen folgt, gelangt nach Norden zu einer dunklen Höhle. Der vermisste Gelehrte könnte darin noch am Leben sein und auf Hilfe warten."},{t="Hinterhalt der Windformer",b="Fillion Flamebreeze kehrte von einem Auftrag bei den Menhiren der Warte zurück, als Windformer ihn überfielen. Sie schlugen ihn zusammen, zerrten ihn zum Höhleneingang und ließen ihn blutend zurück. Hilflos war er dem ausgeliefert, was im Inneren wartete."},{t="Bau der geflügelten Bestie",b="Als Fillion an der Schwelle der Höhle im Sterben lag, trat eine gewaltige geflügelte Bestie aus der Dunkelheit und zerrte ihn hinein. Sie trug ihn tief in ihren Bau, als Beute für ihre Jungen. Eine rechtzeitige Rettung ersparte ihm dieses Schicksal."}},faq={{q="Wer ist Fillion Flamebreeze?",a="Fillion Flamebreeze ist ein Gelehrter, der von einem Auftrag bei den Menhiren der Warte zurückkehrte, als Windformer ihn überfielen. Blutend und bewusstlos vor einer nahen Höhle zurückgelassen, wurde er von einem gewaltigen geflügelten Raubtier hineingezerrt.",al={"wer ist fillion","fillion flamebreeze","vermisster gelehrter nsc"}},{q="Was tat Fillion bei den Menhiren der Warte?",a="Die Menhire der Warte waren der Ort von Fillion Flamebreezes wissenschaftlichem Auftrag. Auf dem Rückweg von den Steinen geriet er in einen Hinterhalt der Windformer. Die genaue Art seiner Forschung ist unklar.",al={"was sind die menhire der warte","auftrag menhire der warte","fillions mission"}},{q="Wer griff Fillion Flamebreeze an?",a="Windformer überfielen Fillion Flamebreeze und schlugen ihn zusammen. Sie zwangen ihn zum Eingang einer nahen Höhle und ließen ihn blutend und kaum bei Bewusstsein zurück.",al={"wer griff fillion an","was sind windformer","hinterhalt der windformer"}},{q="Welche Kreatur verschleppte Fillion in die Höhle?",a="Eine gewaltige geflügelte Bestie in einer Höhle nördlich des Hinterhalts verschleppte Fillion vom Höhleneingang. Sie zerrte ihn in ihren Bau, um sich und ihre hungrigen Jungen zu ernähren.",al={"welche höhlenbestie","geflügeltes monster fillion","was verschleppte fillion"}},{q="Wo ist Fillion Flamebreeze zu finden?",a="Hinweise am Ort von Fillion Flamebreezes Unglück deuten auf eine Höhle gleich im Norden hin. Darin sitzt er am Nistplatz der Bestie fest und wartet auf Rettung, bevor er verschlungen wird.",al={"wie fillion finden","wo ist der vermisste gelehrte","fillion höhle fundort"}},{q="Welches Schicksal ereilte den vermissten Gelehrten?",a="Fillion überlebt seine Qualen, weil jemand rechtzeitig in der Höhle eingreift. Hätte ihn kein Abenteurer gefunden und ihm geholfen, wäre er zum Abendessen für die geflügelte Bestie und ihren Nachwuchs geworden.",al={"hat fillion überlebt","was geschieht mit fillion flamebreeze","vermissten gelehrten retten"}}},fp="19,179,23.215.0,25.234.1,24.217.1,27.237.0,55.204.0,33.144.0,41.165.0,39.186.0,41.190.0"}
P.entries["quest:92850"] = {n="The Missing Scholar",s="Fillion Flamebreeze sitzt nahe einem gefährlichen Bau fest, und Valanaar braucht ein Ende dieser Bedrohung. Sobald er reisen kann, bittet er Euch, die Shriekling Matriarch in der Nähe zu erschlagen.",h="Fillion Flamebreeze sitzt nahe einem gefährlichen Bau fest, und Valanaar braucht ein Ende dieser Bedrohung.",kw={"fillion flamebreeze","kreischling","kreischlingsbau","shriekling matriarch","supreme magister","the missing scholar","valanaar"},ang={["class:Mage"]="Als Magier habt Ihr wie Fillion Flamebreeze eine Ausbildung in den arkanen Künsten erhalten. Er verlässt sich auf diese Ausbildung, um sich zu erholen und sicher zu reisen."},sec={{t="Ein gefährlicher Nistplatz",b="Nach seinen Strapazen kann Fillion Flamebreeze wieder in Richtung des sicheren Valanaar reisen. Doch eine Brut von Kreischlingen hat sich nahe der Siedlung eingenistet. Fillion bittet Euch, den Kreischlingsbau zu betreten und die Shriekling Matriarch zu erschlagen, bevor die Bestien den Ort bedrohen."},{t="Bericht an den Magister",b="Wenn Ihr Fillion in Valanaar den Kopf der Matriarchin bringt, dankt er Euch. Doch die Kreischlinge sind nur das geringste ihrer Probleme. Fillion bereitet sich darauf vor, dem Supreme Magister über seine Mission und die Umgebung zu berichten."}},faq={{q="Wer ist Fillion Flamebreeze?",a="Fillion Flamebreeze ist ein Gelehrter, der die arkanen Künste beherrscht. Er war im Auftrag nahe Valanaar unterwegs, bevor er in der Nähe eines Nests gefährlicher Bestien festsaß.",al={"wer ist fillion flamebreeze","wer ist der gelehrte","wer vergibt the missing scholar"}},{q="Was sind Kreischlinge?",a="Kreischlinge sind feindselige Bestien, die in einem nahegelegenen Bau bei Valanaar nisten. Ihre Anwesenheit bedroht alle, die in der Gegend unterwegs sind.",al={"was sind kreischlinge","wo nisten kreischlinge","bedrohung durch kreischlinge"}},{q="Wer ist der Supreme Magister?",a="Der Supreme Magister ist Elaadrin Evengale, der den Hohen Orden in Valanaar anführt. Fillion berichtet dem Supreme Magister von den Ereignissen am Bau und dem Stand seiner Mission.",al={"wer ist der supreme magister","fillions bericht","wem untersteht fillion"}},{q="Was ist Valanaar?",a="Valanaar ist die nahegelegene Siedlung, in der Fillion stationiert ist. Er kehrt dorthin zurück, sobald er sich genug erholt hat, um zu reisen.",al={"was ist valanaar","wo ist valanaar"}},{q="Was ist die Shriekling Matriarch?",a="Die Shriekling Matriarch führt die Kreischlinge an, die im Kreischlingsbau nisten. Fillion bittet Euch, sie zu erschlagen und ihren Kopf zurückzubringen, um die unmittelbare Gefahr für Valanaar zu beenden.",al={"ziel shriekling matriarch","wen im kreischlingsbau töten"}},{q="Warum hält Fillion die Kreischlinge für das geringste ihrer Probleme?",a="Die Kreischlinge bedrohen Valanaar, weil sie so nahe an der Siedlung nisten. Als Ihr zurückkehrt, sagt Fillion, dass sie nur das geringste ihrer Probleme sind.",al={"warum das geringste unserer probleme","größere gefahr für valanaar"}}},fp="19,163,25.263.0,25.226.1,27.156.0,21.128.0,28.157.0,17.118.0,33.171.0,70.152.0"}
P.entries["quest:92860"] = {n="In Service of Zephras",s="Der Hohe Orden bietet Valanaar nun seine volle militärische und diplomatische Unterstützung gegen den Al'Aketh-Kult an. Feindliche Bewegungen auf der Insel haben seiner Politik ein Ende gesetzt, direkte Konfrontationen zu vermeiden.",h="Der Hohe Orden bietet Valanaar nun seine volle militärische und diplomatische Unterstützung gegen den...",kw={"al'aketh","belathaan","kult der al'aketh","der hohe orden","in service of zephras","stormfist","valanaar","valennia stormfist","zephras"},sec={{t="Die aufziehende Bedrohung",b="Der Hohe Orden versuchte einst, einen offenen Konflikt mit dem geheimnisvollen Al'Aketh-Kult zu vermeiden. Berichte über große Truppenbewegungen und offenkundige Feindseligkeit haben diesem Bemühen ein Ende gesetzt. Die Kultisten mobilisieren, und jede Siedlung auf der Insel ist in ihrer Ruhe und Sicherheit bedroht. Daher hat sich der Hohe Orden zum Handeln entschlossen. Er entsendet einen Gesandten, der sich den örtlichen Verteidigern anschließt, bevor der Al'Aketh zuschlägt."},{t="Bündnis mit Valanaar",b="Valennia Stormfist nimmt das Angebot des Hohen Ordens bedingungsloser Hilfe für Valanaars Widerstand gegen den Al'Aketh an. Gemeinsam können die beiden Seiten eine vereinte Verteidigung aufstellen und gemeinsame militärische Einsätze in der Region vorbereiten. Der Gesandte überbringt außerdem die Nachricht von Belathaans Tod. Valennias Cousin war ein hingebungsvoller Diener Zephras'. Sie trauert um ihn und schwört Rache, dann wendet sie sich den Vorbereitungen für den bevorstehenden Feldzug zu."}},faq={{q="Worum geht es bei der Quest In Service of Zephras?",a="Der Hohe Orden entsendet einen Gesandten zu Valennia Stormfist, um Valanaar seine Unterstützung zuzusichern. Er hatte versucht, direkte Gewalt gegen den Al'Aketh zu vermeiden, doch Feindseligkeit und Berichte über große Truppenbewegungen auf der Insel zwangen ihn zum Umdenken. Mit diesem Angebot beteiligt sich der Hohe Orden an der Verteidigung Valanaars und überbringt die Nachricht von Belathaans Tod.",al={"überblick zu in service of zephras","was geschieht in in service of zephras","quest in service of zephras"}},{q="Wer ist Valennia Stormfist?",a="Valennia Stormfist leitet die Verteidigung gegen den Al'Aketh in Valanaar. Sie nimmt das Angebot gegenseitiger Hilfe des Hohen Ordens an. Belathaan, ihr Cousin und ein Diener Zephras', ist gestorben, und Valennia schwört Rache an jenen, die ihr Volk bedrohen.",al={"valennia stormfist lore","wer ist valennia","valennia stormfist"}},{q="Wer war Belathaan?",a="Belathaan war Valennia Stormfists Cousin und ein hingebungsvoller Diener Zephras'. Er starb, bevor der Gesandte Valennia die Nachricht überbrachte. Die Nachricht macht die persönlichen Folgen des Konflikts spürbarer und bestärkt sie in ihrem Schwur, ihn zu rächen.",al={"wer ist belathaan","belathaan lore","was geschah mit belathaan"}},{q="Was sind die Al'Aketh?",a="Der Al'Aketh ist ein feindseliger Kult, der auf der Insel aktiv ist. Seine feindseligen Taten und Truppenbewegungen bedrohen die Bewohner Zephras'. Der Hohe Orden hat seinen Versuch, direkte Konflikte zu vermeiden, aufgegeben und sich mit anderen gegen den Kult verbündet.",al={"wer sind die al'aketh","al'aketh-kult","was ist al'aketh"}},{q="Welche Rolle spielt der Hohe Orden in diesem Konflikt?",a="Der Hohe Orden wollte zunächst einen direkten Krieg mit dem Al'Aketh vermeiden. Dessen feindselige Handlungen und Berichte über große Truppenbewegungen überzeugten seine Anführer, zu handeln. Der Hohe Orden entsendet nun einen Boten zu Valennia Stormfist und sagt Valanaars Widerstand seine volle Unterstützung zu.",al={"beteiligung des hohen ordens","warum kämpft der hohe orden","hoher orden zephras"}},{q="Was ist Zephras?",a="Zephras ist die Insel, die auch Insel Zephras genannt wird und die der Hohe Orden, Valanaar und seine Verteidiger schützen wollen. Die zunehmenden Aktivitäten des Al'Aketh bedrohen ihre Bewohner, und Belathaan gilt als treuer Diener Zephras'. Zu ihrem Schutz schließt sich der Hohe Orden der Verteidigung an.",al={"wo liegt zephras","wer ist zephras","zephras lore"}}},fp="21,194,20.378.0,22.413.1,46.324.0,26.251.0,18.227.0,21.223.0,47.266.0,16.284.0"}
P.entries["quest:92867"] = {n="Ground to Keep",s="Groundskeeper Lomar bittet Euch, Eindringlinge aus der Burg Stromgarde zu vertreiben. Die verbliebenen Skulpturen und heiligen Begräbnisstätten des Königreichs müssen geschützt werden.",h="Groundskeeper Lomar bittet Euch, Eindringlinge aus der Burg Stromgarde zu vertreiben.",kw={"boulderfist","begräbnisstätten","grund zum bewahren","groundskeeper lomar","skulpturen","stromgarde","burg stromgarde","syndikat","witherbark"},sec={{t="Die Überreste eines Königreichs",b="In der Burg Stromgarde bittet Groundskeeper Lomar Euch, die Boulderfist-, Syndikat- und Witherbark-Eindringlinge zurückzudrängen. Er sagt, Stromgarde habe noch mehr in Reserve und müsse es zu seinem eigenen Schutz verborgen halten. Immer mehr Stimmen setzen sich dafür ein, die verbliebenen Skulpturen und heiligen Begräbnisstätten des Königreichs zu bewahren."}},faq={{q="Wer bittet um Hilfe?",a="Groundskeeper Lomar bittet Euch, die Boulderfist-, Syndikat- und Witherbark-Eindringlinge aus der Burg Stromgarde zu vertreiben.",al={"wer braucht hilfe","groundskeeper lomar","wer hat das gegeben"}},{q="Warum sollten Stromgardes Überreste geschützt werden?",a="Immer mehr Stimmen setzen sich dafür ein, Stromgardes verbliebene Skulpturen und heilige Begräbnisstätten zu bewahren.",al={"warum stromgarde schützen","was muss geschützt werden","skulpturen schützen"}},{q="Welche Eindringlinge sind in der Burg Stromgarde?",a="Boulderfist, Syndikat und Witherbark haben sich in der Burg Stromgarde niedergelassen.",al={"wer ist in der burg","feinde in stromgarde","boulderfist syndikat witherbark"}},{q="Was muss verborgen bleiben?",a="Lomar sagt, Stromgarde habe noch mehr in Reserve, und diese Vorräte müssten zu ihrem eigenen Schutz verborgen bleiben.",al={"was ist verborgen","stromgardes vorräte","was muss geheim bleiben"}}},fp="14,149,19.307.0,23.112.0,47.96.0,39.86.0,24.92.0"}
P.entries["quest:92871"] = {n="In Service of Zephras",s="Auf ganz Zephras sammelt sich der Kult der Al'Aketh für einen größeren Konflikt. Die Windformer entsenden einen Abgesandten, um Valennia Stormfist zu versichern, dass sie ihren Friedenswächtern helfen werden.",h="Auf ganz Zephras sammelt sich der Kult der Al'Aketh für einen größeren Konflikt.",kw={"al'aketh","in service of zephras","valanaar","valennia stormfist","windformer","zephras"},sec={{t="Gerüchte auf der Insel",b="Berichte über Aktivitäten der Al'Aketh verbreiten sich auf ganz Zephras. Valennia Stormfists Friedenswächter beschützen die Insel schon seit Langem, doch nun scheint der Kult einen größeren Konflikt vorzubereiten. Deshalb versprechen die Windformer, an der Seite von Valanaars Streitkräften zu stehen, falls offene Kämpfe ausbrechen."},{t="Die Zusage der Unterstützung",b="Ihr werdet zu Valennia Stormfist entsandt, um ihr zu versichern, dass die Windformer bereit sind, ihren Friedenswächtern zu helfen. Valennia begrüßt ihre rasche Zusage. Sie ist bereit, mit Euch über die wachsende Bedrohung durch den Kult zu sprechen."}},faq={{q="Wer ist Valennia Stormfist?",a="Valennia Stormfist führt die Friedenswächter an, die Zephras beschützen. Sie leitet die Verteidigung der Insel, darunter auch Valanaars Feldzug gegen die Al'Aketh.",al={"wer ist valennia stormfist","valennia stormfist"}},{q="Wer sind die Windformer?",a="Die Windformer sind Verbündete auf Zephras, die Valennia Stormfist und ihren Friedenswächtern helfen. Sie bieten Valanaars Streitkräften ihre volle Unterstützung gegen die wachsende Bedrohung durch die Al'Aketh an.",al={"was sind die windformer","windformer hintergrundgeschichte"}},{q="Was sind die Al'Aketh?",a="Die Al'Aketh sind ein Kult, der auf ganz Zephras aktiv ist. Berichten zufolge unternehmen sie größere Vorstöße und bereiten sich auf einen Konflikt vor.",al={"wer sind die alaketh","was ist alaketh","al aketh kult"}},{q="Was ist Zephras?",a="Zephras ist eine Insel, die von Valennia Stormfist und ihren Friedenswächtern verteidigt wird. Die Windformer helfen ihnen gegen den Kult der Al'Aketh.",al={"was ist zephras","zephras insel"}},{q="Was ist Valanaar?",a="Valanaar ist eine Siedlung auf Zephras und die Heimat von Valennia Stormfists Friedenswächtern. Die Windformer unterstützen ihren Kampf gegen die Al'Aketh uneingeschränkt.",al={"was ist valanaar","wer ist valanaar"}}},fp="21,167,20.279.0,16.208.0,26.148.0,24.175.0,22.115.0,16.125.0,17.144.0"}
P.entries["quest:92872"] = {n="Dutiful Steps",s="Hüter Alaric bittet Euch, Grabstaub aus der Gruft von Burg Stromgarde zum Meer zu bringen. Das Ritual erneuert einen Kreislauf des Gedenkens an die Gefallenen.",h="Hüter Alaric bittet Euch, Grabstaub aus der Gruft von Burg Stromgarde zum Meer zu bringen.",kw={"hüter alaric","zeremonielle riten","gruft","pflichtbewusste schritte","gefallene","großes meer","beutel mit grabstaub","burg stromgarde","grabstaub"},sec={{t="Dem Meer entgegen",b="Euer Weg zurück in die sonnenbeschienene Welt beginnt mit einer kleinen Tasche. Hüter Alaric bittet Euch, sie zu den Klippen hinter Burg Stromgarde zu bringen und ihren Inhalt ins große Meer zu werfen. Der Staub stammt aus dem Grab unter der Burg, wo seine Hüter zeremonielle Riten zur Ehrung der Gefallenen bewahren. In jeder Jahreszeit wird etwas davon als symbolische Erneuerung über Azeroths Meere gestreut."}},faq={{q="Wer bittet mich, den Staub zu bringen?",a="Hüter Alaric bittet Euch, den Grabstaub aus der Gruft von Burg Stromgarde zum Meer zu bringen.",al={"wer gab mir das","alarics bitte"}},{q="Was ist in der Tasche?",a="Die Tasche enthält Staub aus dem Grab unter Burg Stromgarde.",al={"was ist im beutel","grabstaub"}},{q="Warum wird der Grabstaub über dem Meer verstreut?",a="In jeder Jahreszeit wird etwas Grabstaub als symbolischer Akt zur Erneuerung von Kreisläufen über Azeroths Meere gestreut.",al={"warum staub ins meer werfen","wozu ist der staub"}},{q="Wo soll ich die Tasche ausleeren?",a="Hüter Alaric bittet Euch, den Grabstaub von den Klippen hinter Burg Stromgarde ins große Meer zu werfen.",al={"wohin damit","klippen hinter stromgarde"}},{q="Was bewahren die Hüter des Grabes?",a="Die Hüter des Grabes bewahren Wissen über zeremonielle Riten, mit denen die Gefallenen geehrt werden.",al={"was ist im grab","zeremonielle riten"}}},fp="13,142,14.371.0,35.91.0,23.61.0,43.101.0,37.106.0,40.87.0"}
P.entries["quest:92880"] = {n="Return to Valanaar",s="Yornas Bericht meldet Valanaar, dass der östliche Wachturm standgehalten hat. Sein Verteidigungsbereich ist gesichert, und die verbliebenen Angreifer werden beseitigt.",h="Yornas Bericht meldet Valanaar, dass der östliche Wachturm standgehalten hat.",kw={"östlicher wachturm","vier winde","return to valanaar","valanaar","valennia stormfist","yorna","yorna's report"},ang={["race:Skyborne"]="Als Skyborne teilt Ihr die Verbundenheit der Verteidiger und Anführer mit den vier Winden, die sich in ihrem Segen widerspiegelt."},sec={{t="Nachricht vom Außenposten",b="Nach dem Angriff auf den Außenposten schickt Yorna Nachricht nach Valanaar. Die Angreifer sind geschlagen, und die Verteidiger beseitigen jene, die noch übrig sind. Ihr überbringt Yorna's Report, um die Anführer zu beruhigen, die in der Stadt auf Nachricht warten."},{t="Erleichterung in Valanaar",b="Ihr bringt den Bericht des östlichen Wachturms zu Valennia Stormfist in Valanaar. Der Turm hat standgehalten, und sein Verteidigungsbereich ist gesichert. Valennia dankt den Winden, erleichtert darüber, dass die Grenze weiterhin sicher ist."}},faq={{q="Wer schickt Euch nach Valanaar?",a="Yorna schickt Euch nach der hart erkämpften Verteidigung des Außenpostens nach Valanaar. Sie bittet Euch, den Anführern der Siedlung einen Bericht zu überbringen.",al={"wer vergibt return to valanaar","wer schickt zurück nach valanaar","yorna questgeberin"}},{q="Wem erstattet Ihr in Valanaar Bericht?",a="Ihr erstattet Valennia Stormfist in Valanaar Bericht. Sie wartet auf Nachricht über die Verteidiger außerhalb der Siedlung und ihre Sicherheit.",al={"wer ist valennia stormfist","wo ist valennia stormfist","return to valanaar abgeben"}},{q="Was ist Yorna's Report?",a="Yorna's Report besagt, dass die Verteidiger ihre Stellung gesichert haben und die verbliebenen Angreifer beseitigen.",al={"was ist yorna's report","was steht in yorna's report"}},{q="Welcher Wachturm wurde angegriffen?",a="Yorna und ihre Truppen verteidigten den östlichen Wachturm, eine Schlüsselstellung zur Überwachung der Zugänge nach Valanaar.",al={"welcher turm wurde angegriffen","bei welchem wachturm ist yorna"}},{q="Wie steht es um den östlichen Wachturm?",a="Die Verteidiger haben den östlichen Wachturm gesichert und die Lage stabilisiert. Sie beseitigen noch immer die verbliebenen Angreifer.",al={"ist der wachturm sicher","haben die verteidiger gewonnen"}},{q="Warum sprechen die Verteidiger von den vier Winden?",a="Die Verteidiger von Valanaar ehren die vier Winde und die Elemente. Ihr Segen und Valennias Dank an die Winde zeugen von dieser Verehrung.",al={"vier winde bedeutung","segen der vier winde"}}},fp="18,153,21.219.0,18.204.0,26.128.0,33.105.0,23.112.0,34.105.0,45.130.0,45.135.0"}
P.entries["quest:92881"] = {n="The High Elder's Request",s="In Valanaar ruft der Oberste Älteste Talaanis Shadowsong nach koordinierten Angriffen auf die Wachtürme der Region um Hilfe. Berichte vom westlichen Wachturm deuten darauf hin, dass ein feindseliger Kult die örtlichen Ankerpylone ins Visier nimmt.",h="In Valanaar ruft der Oberste Älteste Talaanis Shadowsong nach koordinierten Angriffen auf die Wachtürme der...",kw={"ankerpylone","östlicher wachturm","shadowsong","himmelspriester","talaanis shadowsong","the high elder's request","valanaar","westlicher wachturm"},ang={["class:Priest"]="Für Priester, die göttliche oder rituelle Manipulation erforschen, sind das Interesse des Kults an Ankerpylonen und die Beteiligung des Himmelspriesters am westlichen Wachturm beunruhigende Zeichen."},sec={{t="Unruhe an den Wachtürmen",b="Koordinierte Angriffe auf den westlichen und den östlichen Wachturm offenbaren ein beunruhigendes Muster. Was wie vereinzelte Scharmützel wirkte, deutet nun auf einen geplanten Angriff auf die örtlichen Ankerpylone hin. Ein Bericht vom westlichen Wachturm schildert, wie ein Himmelspriester das Interesse des Kults an diesen Bauwerken offenbarte. Nun ist die Verteidigung der Türme ein dringendes Anliegen."},{t="Audienz in Valanaar",b="Die Bedrohung für die Ankerpylone wächst, daher entsendet Euch die Führung zu einem Gespräch mit dem Obersten Ältesten Talaanis Shadowsong in Valanaar. Er hat eine vielversprechende Spur zu den Bewegungen des Kults und sucht erfahrene Verbündete, um den Feind aufzuspüren. Der Kult bereitet möglicherweise ein Ritual oder Sabotage vor."}},faq={{q="Wer ist der Oberste Älteste Shadowsong?",a="Der Oberste Älteste Talaanis Shadowsong ist eine Führungspersönlichkeit in Valanaar. Die Wachtürme der Region wurden von koordinierten Angriffen des Kults getroffen, und er sucht fähige Verbündete, um Hinweisen auf dessen Absichten nachzugehen.",al={"wer ist talaanis shadowsong","oberster ältester shadowsong","wo ist shadowsong"}},{q="Wo liegt Valanaar?",a="In Valanaar ist der Oberste Älteste Talaanis Shadowsong stationiert. Er koordiniert die Verteidigung und untersucht Vorstöße des Kults gegen örtliche Ankerpylone und Türme.",al={"was ist valanaar","lage von valanaar"}},{q="Warum wurden die Wachtürme angegriffen?",a="Koordinierte Angriffe trafen sowohl den westlichen als auch den östlichen Wachturm. Die Verteidiger vermuten gezielte Manöver gegen die nahe gelegenen Ankerpylone statt wahlloser Überfälle.",al={"warum wurden die wachtürme angegriffen","westlicher und östlicher wachturm","angriffe auf wachtürme"}},{q="Was sind die Ankerpylone?",a="Ankerpylone sind wichtige Bauwerke für die Verteidigung oder die Region. Berichte vom westlichen Wachturm legen nahe, dass ein feindseliger Kult sie stören oder unter seine Kontrolle bringen will.",al={"was sind ankerpylone","kult ankerpylone","warum ankerpylone"}},{q="Wer war der Himmelspriester am westlichen Wachturm?",a="Ein Himmelspriester war an dem Vorfall am westlichen Wachturm beteiligt. Berichte über diese Begegnung ließen die Führung vermuten, dass der Kult einen umfassenderen Plan verfolgt, der die Ankerpylone einbezieht.",al={"wer war der himmelspriester","himmelspriester am westlichen wachturm","rolle des himmelspriesters"}},{q="Welcher Kult nimmt die Wachtürme ins Visier?",a="Ein feindseliger Kult führte gleichzeitige Angriffe auf die Wachtürme der Region aus. Sein Wesen und seine Beweggründe werden weiterhin untersucht, während der Oberste Älteste Shadowsong daran arbeitet, seine Pläne aufzudecken.",al={"welcher kult ist das","wer hat die türme angegriffen"}}},fp="24,213,26.339.0,20.266.0,29.188.0,18.159.0,34.160.0,27.166.0,48.177.0,39.179.0"}
P.entries["quest:929"] = {n="Krone der Erde",s="Nahe Sternenhauch schöpft Ihr heiliges Wasser für Darnassus. Corithras Mondzorn in Dolanaar schickt junge Nachtelfen aus, um den Mondbrunnen der Stadt aufzufüllen, und lehrt sie, warum ihr Volk Teldrassils gewaltige Äste pflegt.",h="Nahe Sternenhauch schöpft Ihr heiliges Wasser für Darnassus.",kw={"corithras mondzorn","crown of the earth","dolanaar","jadephiole","mondbrunnen","nordrassil","sternenhauch","teldrassil"},ang={["class:Druid"]="Als Druide kennt Ihr Mondbrunnen als lebendige Speicher der Natur- und Astralmagie. Ihr Wasser verbindet die Pflichten Eures Ordens in Darnassus mit Teldrassils Wurzeln.",["race:NightElf"]="Als Nachtelf müsst Ihr Euch dem Verlust der Unsterblichkeit und Malfurion Sturmgrimms Verschwinden stellen. Beim Schöpfen von Mondbrunnenwasser erfahrt Ihr von der jüngsten Trauer Eures Volkes."},sec={{t="Die Mondbrunnen erhalten",b="Druiden haben Euch eine Jadephiole für die Reise nach Sternenhauch gefertigt. Dort birgt ein kleinerer Mondbrunnen geweihtes Wasser. Die kunstvolle Verarbeitung der Phiole erlaubt Euch, das leuchtende Wasser zu schöpfen und zu tragen, ohne seine Reinheit zu beeinträchtigen.\n\nDer zentrale Mondbrunnen von Darnassus ist auf verstreute Quellen wie diese angewiesen. Die Ältesten schicken Novizen zu Fuß los, um die Brunnen der Stadt mit Elune's Grace gefüllt zu halten. Die Reise lehrt die Jungen, was nötig ist, um Teldrassil zu nähren."},{t="Nachhall des Dritten Krieges",b="Corithras Mondzorn erzählt Euch von der Trauer, die auf die Schlacht um den Hyjal folgte. Die Nachtelfen opferten Nordrassil, ihren uralten Weltenbaum, und verloren ihre Unsterblichkeit. Illidan Stormrage wurde inmitten der Verwüstung entfesselt, während Shan'do Malfurion Sturmgrimm verschwand.\n\nTrauer und Isolation prägten die folgenden Tage. Die Kaldorei wandten sich Teldrassil zu."}},faq={{q="Welchem Zweck dient das Schöpfen von Mondbrunnenwasser?",a="Druiden in Darnassus füllen den Hauptmondbrunnen der Stadt mit Wasser aus Waldschreinen auf. So erhalten sie das heilige Netz, das sich über Teldrassil erstreckt.",al={"warum mondbrunnenwasser holen","verwendung von mondbrunnenwasser","zweck der jadephiole"}},{q="Wo liegt der Mondbrunnen für diese Aufgabe?",a="Der Mondbrunnen liegt direkt außerhalb von Sternenhauch, östlich von Dolanaar am Waldpfad.",al={"wo ist der mondbrunnen","mondbrunnen sternenhauch standort","brunnen in sternenhauch"}},{q="Wer ist Corithras Mondzorn?",a="Corithras Mondzorn ist ein Nachtelf in Dolanaar, der junge Abenteurer bei ihren rituellen Pflichten anleitet. Er lehrt die Geschichte, die mit Teldrassils Wohlergehen verbunden ist.",al={"wer vergibt die quest","geschichte von corithras mondzorn"}},{q="Welche Geschichte lehrt Corithras nach der Rückkehr?",a="Corithras berichtet von den Folgen der Schlacht um den Hyjal. Nordrassil wurde geopfert, die Kaldorei verloren ihre Unsterblichkeit, Illidan wurde entfesselt, und Shan'do Malfurion Sturmgrimm verschwand.",al={"was sagt corithras","crown of the earth geschichtstext"}},{q="Warum fühlen sich die Nachtelfen nach der Schlacht um den Hyjal verloren?",a="Nordrassil schenkte den Nachtelfen ewiges Leben und Schutz. Sie opferten seine Macht, um Archimonde zu vernichten, verloren ihr zeitloses Dasein und wurden sterblich, orientierungslos und zutiefst verletzlich.",al={"warum verloren die elfen ihre unsterblichkeit","was geschah nach hyjal"}},{q="Was ist ein Shan'do?",a="Shan'do bedeutet auf Darnassian „verehrter Lehrer“. Es ist ein Ehrentitel für Malfurion Sturmgrimm, den obersten Anführer der Druiden.",al={"was bedeutet shando","shando bedeutung"}}},fx={["5a4296ad"]={q="Warum möchte Corithras Mondzorn, dass dies getan wird?",a="Corithras erfüllt lebenswichtige Aufgaben für den Zirkel des Cenarius, während er junge Nachtelfen über den zerbrechlichen Zustand ihres Volkes unterrichtet. Teldrassils heilige Gewässer erfordern ständige Pflege und Ausgewogenheit, und die Druiden in Darnassus sind auf frisches Wasser angewiesen, das aus abgelegenen Mondbrunnen über die Zweige hinweg gesammelt wird. Indem er diesen Dienst gegen Geschichte und Anleitung tauscht, stellt Corithras sicher, dass der Mondbrunnen von Darnassus wieder aufgefüllt wird und dass Ihr die schweren Lasten versteht, die Euer Volk nach dem Dritten Krieg zu tragen hat.",al={"motiv von corithras mondzorn","warum braucht corithras wasser","aufgabe von corithras zum mondbrunnen"}},["0abe9d82"]={q="Wofür ist die Gefüllte Jadephiole?",a="Die Gefüllte Jadephiole enthält heiliges Wasser, das aus dem Mondbrunnen in der Nähe von Sternenhauch gesammelt wurde. Sie wurde speziell dafür angefertigt, Mondbrunnenwasser zu halten und zu bewahren, ohne dessen latente magische Kraft zu mindern, und liefert Nachschub an die Druiden von Darnassus, die für ihre Rituale und Heilung auf die vereinte Kraft der Quellen von Teldrassil zurückgreifen.",al={"zweck der gefüllten jadephiole","wofür wird die jadephiole verwendet","gefüllte jadephiole"}}},fp="18,215,24.445.0,23.359.0,46.138.0,44.90.0,26.151.0,46.194.0,47.202.0,18.122.0"}
P.entries["quest:92909"] = {n="Harvesting the Harvesters",s="Auf Saldeans Farm in Westfall sitzt Ozwin Ironsprocket wegen außer Kontrolle geratener Erntegolems fest. Der Gnomentüftler ist zu Besuch und braucht geborgene Bauteile, um sich einen Ausweg zu bauen.",h="Auf Saldeans Farm in Westfall sitzt Ozwin Ironsprocket wegen außer Kontrolle geratener Erntegolems fest.",kw={"golem-isospringfedern","erntegolems","erntehelfer-gyrostabilisatoren","harvesting the harvesters","eisenschmiede","ozwin ironsprocket","saldeans farm","westfall"},ang={["faction:Alliance"]="Als Reisende der Allianz auf Saldeans Farm könnt Ihr einem gastierenden Gnomengelehrten helfen, der nach seinem gescheiterten Versuch, Westfalls außer Kontrolle geratene Erntehelfer zu reparieren, festsitzt.",["profession:Engineering"]="Als Ingenieur könnt Ihr Isospringfedern und Gyrostabilisatoren aus außer Kontrolle geratenen Erntegolems bergen und als Bauteile für eine Fluchtvorrichtung verwenden.",["race:Gnome"]="Als Gnom ist Euch Ozwins Ehrgeiz vertraut, an komplexen Maschinen zu tüfteln. Er unterschätzte die Aggressivität der Maschinen und wurde schließlich in einem Stall auf einer Farm in die Enge getrieben."},sec={{t="Ein fehlkalkuliertes Unterfangen",b="Ozwin Ironsprocket kam aus Eisenschmiede nach Süden, als die dortigen Werkstätten von außer Kontrolle geratenen Erntehelfern in Westfall hörten. Der Gnomeningenieur glaubte, er könne die Landmaschinen untersuchen und neu kalibrieren. Er hoffte, den Feldern der Region Frieden zu bringen, die bereits unter Gesetzlosen litten und nun von randalierenden Erntehelfern überrannt wurden."},{t="Im Stall gefangen",b="Nahe Saldeans Farm stellte Ozwin fest, dass die Erntegolems weitaus gewalttätiger waren, als seine Baupläne vermuten ließen. Ihre scharfen Klingen und unberechenbaren Hiebe trieben ihn in einen nahegelegenen Stall. Dort sitzt er fest und kann nicht gefahrlos auf die Felder zurückkehren. Er braucht wagemutige Reisende, die Isospringfedern und Gyrostabilisatoren aus den Maschinen bergen, damit er eine Vorrichtung zur Flucht bauen kann."}},faq={{q="Wer ist Ozwin Ironsprocket?",a="Ozwin Ironsprocket ist ein Gnomentüftler aus Eisenschmiede, der nach Westfall kam, um die randalierenden Erntegolems neu zu kalibrieren. Ihre Feindseligkeit trieb ihn in einen Stall auf Saldeans Farm.",al={"wer ist ozwin ironsprocket","ozwin","questgeber"}},{q="Warum sind die Erntegolems so aggressiv?",a="Die Erntegolems auf den verlassenen Feldern Westfalls sind gegenüber Vorbeikommenden äußerst aggressiv. Ihre Wildheit übertrifft bei Weitem, was Ozwin erwartet hatte, als er noch glaubte, eine routinemäßige Neukalibrierung würde sie wieder in Ordnung bringen.",al={"warum greifen erntehelfer an","warum sind golems aggressiv","was stimmt mit den erntehelfern nicht"}},{q="Wo ist Ozwin Ironsprocket zu finden?",a="Ozwin Ironsprocket versteckt sich in einem Stall auf Saldeans Farm in Westfall, wo er Schutz vor den Erntegolems auf den umliegenden Feldern sucht.",al={"wo ist ozwin ironsprocket","wo harvesting the harvesters abgeben","ozwins standort"}},{q="Was will Ozwin aus den gesammelten Bauteilen bauen?",a="Ozwin braucht Golem-Isospringfedern und Erntehelfer-Gyrostabilisatoren, um eine mechanische Vorrichtung zu bauen, mit der er sicher aus dem Stall fliehen kann.",al={"wofür braucht ozwin bauteile","warum isospringfedern sammeln","bauteile für die fluchtvorrichtung"}},{q="Warum reiste Ozwin von Eisenschmiede nach Westfall?",a="Ozwin reiste von Eisenschmiede nach Westfall, nachdem er gehört hatte, dass außer Kontrolle geratene Maschinen das Land terrorisierten. Er glaubte, die Erntehelfer neu kalibrieren zu können.",al={"warum kam ozwin nach westfall","warum eisenschmiede verlassen"}},{q="Woher stammen die benötigten Golembauteile?",a="Die Isospringfedern und Gyrostabilisatoren stammen von den feindseligen Erntegolems und Erntehelfern auf den Feldern rund um Saldeans Farm in Westfall.",al={"wo werden bauteile fallen gelassen","wie isospringfedern und gyrostabilisatoren bekommen"}}},fp="25,156,24.307.0,20.345.0,26.178.0,41.190.0,38.124.0,57.134.0,48.158.0,44.135.0"}
P.entries["quest:92910"] = {n="Harvesting the Harvesters",s="Ein geborgenes Ernterteil könnte jemanden interessieren, der Erntegolems erforscht. Ihr werdet gebeten, es zu Ozwin Ironsprocket auf Saldeans Farm zu bringen.",h="Ein geborgenes Ernterteil könnte jemanden interessieren, der Erntegolems erforscht.",kw={"erntegolem","ernter","harvesting the harvesters","ozwin ironsprocket","precessive autocognition assembly","saldeans farm","geborgenes teil"},sec={{t="Ein geborgenes Teil",b="Jemand auf Saldeans Farm möchte vielleicht das Teil untersuchen, das Ihr aus einem Ernter geborgen habt. Es scheint größtenteils unversehrt zu sein, und Ozwin Ironsprocket wartet darauf, es zu sehen."}},faq={{q="Was bringe ich zu Ozwin?",a="Ihr bringt Ozwin Ironsprocket die Precessive Autocognition Assembly, ein aus einem Ernter geborgenes Teil.",al={"ernterteil","welcher gegenstand","autocognition assembly"}},{q="Wohin bringe ich das geborgene Teil?",a="Bringt die Precessive Autocognition Assembly zu Ozwin Ironsprocket auf Saldeans Farm.",al={"wo ist ozwin","saldeans farm","wohin bringen"}},{q="Warum könnte jemand das Teil haben wollen?",a="Das geborgene Teil scheint größtenteils unversehrt zu sein, und jemand, der sich für Erntegolems interessiert, möchte es vielleicht sehen.",al={"warum ernter","wer will das","interesse an erntern"}}},fp="25,141,15.156.0,24.101.0,35.84.0,32.101.0"}
P.entries["quest:92911"] = {n="Harvesting the Harvesters",s="Auf Saldeans Farm braucht Ozwin Ironsprocket Teile für ein Gerät, das die Systeme der Erntegolems kurzzeitig übersteuern soll. Er arbeitet weiter am Zusammenbau, während Ihr die benötigten Teile sammelt.",h="Auf Saldeans Farm braucht Ozwin Ironsprocket Teile für ein Gerät, das die Systeme der Erntegolems kurzzeitig...",kw={"copper modulators","crude scope","gerät","golem isosprings","erntegolems","harvesting the harvesters","ozwin ironsprocket"},sec={{t="Teile für Ozwin",b="Ozwin Ironsprocket auf Saldeans Farm erforscht, wie die Erntegolems funktionieren. Er glaubt, ihre Systeme kurzzeitig übersteuern zu können. Ihr sammelt Teile für sein Gerät, während er weiter am Zusammenbau tüftelt."},{t="Das fertige Gerät",b="Ozwin stellt das Gerät fertig und bittet Euch, es auszuprobieren. Er bleibt auf der Farm, die sich für ihn allmählich wie ein Zuhause anfühlt."}},faq={{q="Wer bittet um Teile?",a="Ozwin Ironsprocket auf Saldeans Farm braucht Teile für ein Gerät.",al={"wer braucht teile","ozwin teile"}},{q="Was baut Ozwin?",a="Ozwin baut ein Gerät, das die Systeme der Erntegolems kurzzeitig übersteuern soll.",al={"welches gerät","erntegolem gerät"}},{q="Welche Teile braucht Ozwin?",a="Ozwin braucht Golem Isosprings, Copper Modulators und ein Crude Scope.",al={"teileliste","was braucht ozwin"}},{q="Wo arbeitet Ozwin?",a="Ozwin Ironsprocket arbeitet auf Saldeans Farm.",al={"wo ist ozwin","ozwin standort"}}},fp="25,182,15.218.0,19.117.1,24.62.0,23.80.0,27.67.0,23.48.0"}
P.entries["quest:92914"] = {n="Strange Pylons",s="In Shen'dralas ist der Zweck eines erschöpften Kristallpylons unbekannt. Ihr sollt in der Nähe nach weiteren suchen.",h="In Shen'dralas ist der Zweck eines erschöpften Kristallpylons unbekannt.",kw={"kristall","elfische ruinen","edelstein","manaelementare","pylon","shen'dralas","seltsame pylonen"},sec={{t="Unter den Ruinen",b="Ein seltsamer Kristall ruht auf einem uralten Sockel inmitten der elfischen Ruinen von Shen'dralas. Noch vor wenigen Augenblicken wurde er von ausgemergelten Manaelementaren bewacht. Der Edelstein ist gesprungen und seine Magie nahezu erschöpft, sein Zweck bleibt also ein Rätsel. Ihr durchsucht die Gegend nach weiteren Pylonen dieser Art."}},faq={{q="Was ist der seltsame Pylon?",a="Es ist ein gesprungener Edelstein auf einem uralten Sockel in Shen'dralas. Seine erschöpfte Magie lässt seinen Zweck unbekannt.",al={"seltsamer pylon","kristallpylon","was ist dieser kristall"}},{q="Warum summt der Kristall?",a="Vom gesprungenen Edelstein geht ein schwaches Machtbrummen aus, obwohl seine Magie stark erschöpft ist.",al={"kristall summt","warum summt er","schwaches brummen"}},{q="Was bewachte den Kristall?",a="Noch vor wenigen Augenblicken bewachten ausgemergelte Manaelementare den Kristall.",al={"manaelementare","was bewachte ihn","elementare am pylon"}},{q="Wo sind die anderen Pylonen?",a="Ihr sollt Shen'dralas nach weiteren Pylonen wie dem von Euch gefundenen durchsuchen.",al={"andere pylonen","weitere pylonen finden","pylonstandorte"}}},fp="14,109,15.269.0,26.116.0,27.92.0,30.63.0,27.76.0"}
P.entries["quest:92947"] = {n="Making Our Move",s="Am Schrein von Akir rückt eine Angriffstruppe gegen die Al'Aketh und ihre Hohepriesterin vor. Ein Frontalangriff soll die Verteidiger anlocken, während sich die Hauptstreitmacht von der Flanke nähert.",h="Am Schrein von Akir rückt eine Angriffstruppe gegen die Al'Aketh und ihre Hohepriesterin vor.",kw={"al'aketh","al'aketh klingenmeister","al'aketh wächter","al'aketh geisterrufer","hohepriesterin","hyusaa quickbreeze","making our move","schrein von akir"},ang={["class:Priest"]="Der Angriff gilt der Führung der Al'Aketh am Schrein von Akir, darunter die feindliche Hohepriesterin und ihre Geisterrufer."},sec={{t="Ein abgestimmter Zangenangriff",b="Am Schrein von Akir hängt der Angriff vom richtigen Zeitpunkt und geteilten Streitkräften ab. Eine kleine Schar Elitekämpfer stürmt die vorderen Tore, um Alarm auszulösen und die Verteidiger herauszulocken. Währenddessen führt der Kommandant die Hauptangriffstruppe von der Flanke heran. Ihr Vorstoß teilt die Aufmerksamkeit der Verteidiger und öffnet einen Weg zur Führung des Schreins."},{t="Die Linien der Al'Aketh durchbrechen",b="Die Al'Aketh verteidigen den Schrein von Akir mit gepanzerten Wächtern, mystischen Geisterrufern und kriegerischen Klingenmeistern. Die Angriffstruppe muss ihre vordersten Linien durchbrechen, um das innere Heiligtum zu erreichen, wo die Hohepriesterin ihre Anhänger befehligt. Sobald die äußeren Verteidiger besiegt sind, trefft Ihr Hyusaa Quickbreeze, die stellvertretende Anführerin der Truppe, an den Stufen des Schreins."}},faq={{q="Was ist das Ziel des Angriffs in Making Our Move?",a="Die Angriffstruppe will in den Schrein von Akir eindringen und die Hohepriesterin erreichen. Kämpfer greifen frontal an, um die Verteidiger anzulocken, während die Haupttruppe deren Stellung über die Flanke angreift.",al={"making our move","quest making our move","schrein von akir quest"}},{q="Wer ist Hyusaa Quickbreeze?",a="Hyusaa Quickbreeze ist die stellvertretende Anführerin der Angriffstruppe. Nachdem Ihr die Reihen der Al'Aketh-Verteidiger am Schrein gelichtet habt, sollt Ihr Quickbreeze nahe den Stufen treffen.",al={"wer ist hyusaa","hyusaa quickbreeze","wo ist hyusaa"}},{q="Wer ist die Hohepriesterin, der der Angriff gilt?",a="Die Hohepriesterin befehligt die Al'Aketh im Schrein von Akir. Die Angriffstruppe umgeht die feindlichen Linien über die Flanke, um sie zu erreichen und zu besiegen.",al={"wer ist die hohepriesterin akir","hohepriesterin alaketh","ziel hohepriesterin"}},{q="Was ist der Schrein von Akir?",a="Der Schrein von Akir ist eine befestigte religiöse Stätte, die von den Al'Aketh gehalten wird. Wächter, Geisterrufer und Klingenmeister verteidigen sein zentrales Heiligtum, in dem sich ihre Führung aufhält.",al={"was ist der schrein von akir","schrein von akir hintergrundgeschichte","wo ist der schrein von akir"}},{q="Wer sind die Al'Aketh-Streitkräfte, die den Schrein halten?",a="Die Al'Aketh sind die feindlichen Verteidiger des Schreins von Akir. Zu ihren Reihen gehören Wächter an der Front, zauberwirkende Geisterrufer und flinke Klingenmeister, die den Weg zu ihrer Hohepriesterin bewachen.",al={"wer sind die alaketh","al'aketh verteidiger","alaketh gegner"}},{q="Warum wird beim Angriff ein frontales Ablenkungsmanöver eingesetzt?",a="Eine Handvoll erfahrener Kämpfer dringt durch den Vordereingang des Schreins ein, um die Verteidiger anzulocken und Chaos zu stiften. Dadurch erhält die Hauptstreitmacht die Gelegenheit, die Anlage über die Flanke anzugreifen und zum inneren Schrein vorzustoßen.",al={"warum ablenkung","schrein angriffsplan","angriffsstrategie making our move"}}},fp="15,179,20.338.0,27.359.0,56.171.0,26.156.0,49.132.0,27.174.0,47.195.0,49.203.0"}
P.entries["quest:93"] = {n="Schwärzliche Krebsküchlein",s="In Dunkelhain sind Schwärzliche Krebsküchlein ein beliebter Imbiss, der keinerlei Krebs enthält. Küchenchef Grual schickt Euch los, um Spinnenbeine für den hungrigen und nervösen Bibbers zu sammeln.",h="In Dunkelhain sind Schwärzliche Krebsküchlein ein beliebter Imbiss, der keinerlei Krebs enthält.",kw={"küchenchef grual","dunkelhain","dämmerwald","schwärzliche krebsküchlein","bibbers","scarlet raven tavern","spinnenbeine","giftwebenspinne"},ang={["faction:Alliance"]="Als Reisender der Allianz seht Ihr, wie vernachlässigte Infrastruktur und abgeschnittene Versorgungswege Städte wie Dunkelhain dazu zwingen, von riesigem Ungeziefer zu leben.",["profession:Cooking"]="Als Koch im Grenzland lernt Ihr, dass selbst furchterregende Raubtiere wie riesige Giftspinnen zur regionalen Delikatesse einer Stadt werden können."},sec={{t="Eine fragwürdige Delikatesse",b="Küchenchef Grual kocht in der Scarlet Raven Tavern in Dunkelhain. Isolation, dunkle Magie und abgeschnittene Versorgungswege haben im Dämmerwald zu Nahrungsknappheit geführt, weshalb die Einheimischen ihre Ernährung umgestellt haben. Grual zufolge verdanken die Küchlein ihren pikanten Geschmack den klebrigen Beinen heimischer Riesenspinnen und keinen Meeresfrüchten von fernen Küsten."},{t="Jagd auf Giftwebenspinnen",b="Küchenchef Grual schickt Euch nach Norden zu den Ausläufern der Berge und den Flussufern, wo Giftwebenspinnen ihre Fangnetze weben. Untote und wilde Bestien machen den düsteren Wald gefährlich, doch frisches Spinnenfleisch ist eine der wenigen leicht verfügbaren Eiweißquellen in den verheerten Wäldern. Grual brät die gewürzten Gliedmaßen in einer heißen Pfanne knusprig."},{t="Trost für eine verfluchte Seele",b="Bibbers sucht im verlassenen Dorf Rabenflucht im westlichen Dämmerwald Zuflucht. Schuld und zitternde Angst verfolgen ihn, seit er versehentlich Schrecken über die Region gebracht hat. Der aufgewühlte Landstreicher denkt an kaum etwas anderes als seinen ausgehungerten Magen. Eine heiße Portion der herzhaften Spinnenküchlein von Küchenchef Grual schenkt ihm seltenen Trost im Exil."}},faq={{q="Werden Schwärzliche Krebsküchlein tatsächlich aus Krebs zubereitet?",a="Nein. Küchenchef Grual gibt offen zu, dass Schwärzliche Krebsküchlein vollständig aus klebrigen Spinnenbeinen bestehen. Dunkelhain hat weder Zugang zum Meer noch zu frischen Krebsen, weshalb er heimische Riesenspinnen wegen ihrer Konsistenz und ihres kräftigen, pikanten Geschmacks verwendet.",al={"ist es echter krebs","geheimnis der krebsküchlein","woraus bestehen krebsküchlein"}},{q="Woher bekommt Küchenchef Grual die Spinnenbeine?",a="Grual verlässt sich auf Abenteurer, die klebrige Beine von aggressiven Giftwebenspinnen sammeln. Diese nisten vor allem im nördlichen Dämmerwald, zwischen den bewaldeten Bergausläufern und dem Fluss.",al={"wo spinnenbeine finden","spinnenfundorte im dämmerwald","fundort der giftwebenspinnen"}},{q="Für wen werden diese Krebsküchlein zubereitet?",a="Küchenchef Grual bereitet diese Portion für Bibbers zu, serviert die Küchlein aber auch Gästen in Dunkelhain. Bibbers ist ein verängstigter Einsiedler in der Geisterstadt Rabenflucht im westlichen Dämmerwald, der dringend Nahrung braucht.",al={"wer will die krebsküchlein","wer isst die krebsküchlein","warum krebsküchlein zubereiten"}},{q="Wird Küchenchef Grual mir beibringen, wie man Schwärzliche Krebsküchlein zubereitet?",a="Küchenchef Grual hält sein genaues Rezept für Schwärzliche Krebsküchlein geheim und weigert sich, seine unverwechselbare Gewürzmischung preiszugeben. Hilfsbereiten Abenteurern gibt er jedoch ein anderes Rezept aus seinem Kochrepertoire.",al={"kann man das rezept für krebsküchlein lernen","krebsküchlein rezept kochkunst"}},{q="Warum ist Dunkelhain auf Spinnen als Nahrung angewiesen?",a="Untote, Nightbane worgen und feindselige Kreaturen belagern die Straßen des Dämmerwalds und beeinträchtigen Handelskarawanen und Landwirtschaft schwer. Da frisches Schlachtvieh und eingeführte Waren knapp sind, verwerten die Bewohner Dunkelhains alle Wildtiere, die sie fangen können.",al={"warum in dunkelhain spinnen essen","nahrungsknappheit im dämmerwald"}},{q="Weiß Bibbers, dass die Küchlein aus Spinnen bestehen?",a="Bibbers sehnt sich nach den berühmten Krebsküchlein von Küchenchef Grual und schert sich wenig um ihre Zutaten. Vor Angst und Hunger wie gelähmt, giert er in den Wäldern nach jeder vertrauten Mahlzeit aus Dunkelhain, wie gruselig ihre Herkunft auch sein mag.",al={"weiß bibbers von den spinnen","bibbers reaktion auf spinnenfleisch"}}},fx={e54432be={q="Wofür wird das Klebrige Spinnenbein verwendet?",a="Trotz des angenehmen Namens auf der Speisekarte der Taverne sind Klebrige Spinnenbeine das Kernfleisch in Küchenchef Gruals berühmten Schwärzlichen Krebsküchlein. Grual würzt die huschenden Gliedmaßen mit seiner geheimen Gewürzmischung und brät sie in einer Pfanne an, wobei er sich auf ihre natürlichen Säfte verlässt, um den herzhaften Küchlein ihren unverwechselbaren, würzigen Geschmack zu verleihen.",al={"verwendung von klebrigem spinnenbein","warum klebrige spinnenbeine","spinnenbeine für krebsküchlein"}}},fp="16,156,23.300.0,22.309.0,25.320.1,43.216.0,42.166.0,40.196.0,54.184.0,44.236.0,48.213.0"}
P.entries["quest:930"] = {n="Die leuchtende Frucht",s="Eine seltsame Frucht leuchtet zwischen Teldrassils Bäumen, und ihr Wuchs beunruhigt jene, die sie finden. Ihr bringt sie zu Denalan am Al'Amethsee, wo der Kräuterkundige die unbekannte Pflanze untersuchen kann.",h="Eine seltsame Frucht leuchtet zwischen Teldrassils Bäumen, und ihr Wuchs beunruhigt jene, die sie finden.",kw={"sumpflinge","denalan","leuchtende frucht","kräuterkunde","al'amethsee","seltsame fruchttragende pflanze","teldrassil","timberlings"},ang={["class:Druid"]="Als Druide, der das Gleichgewicht der Natur bewahrt, wisst Ihr, dass fremde, unberechenbare Pflanzen in Teldrassils heiligen Ästen Anlass zur Sorge geben.",["profession:Herbalism"]="Als Kräuterkundiger könnt Ihr erkennen, wie fremde Samen Kontinente überqueren und sich in verzaubertem Boden verändern können.",["race:NightElf"]="Als Nachtelf erfahrt Ihr von Denalan, dass der junge Boden Eurer neuen Heimat Teldrassil unter unvorhersehbaren, fremden Pflanzenkrankheiten leiden kann."},sec={{t="Eine unnatürliche Ernte",b="In Teldrassils nebligen Ästen könnt Ihr Pflanzen finden, die große, runde Früchte tragen, die aus eigener Kraft leuchten. Das Gleichgewicht des Weltbaums ist empfindlich, und seine Tierwelt verhält sich in letzter Zeit seltsam. Daher ist bei ungewöhnlichen Pflanzen Vorsicht geboten. Ihr sammelt die leuchtende Frucht, um sie jemandem zu bringen, der die Pflanzen der Wildnis kennt."},{t="Denalans Untersuchung",b="Am Al'Amethsee nimmt Denalan die leuchtende Frucht mit Faszination und Sorge entgegen. Der Gärtner und Kräuterkundige glaubt, ihre Samen könnten aus fernen Ländern jenseits des Meeres stammen, vielleicht sogar aus den Östlichen Königreichen. Doch mehr Sorgen bereitet ihm, wie der fremde Samen mit Teldrassils Boden reagiert hat. Als Denalan die Samen in vorbereitete Erde pflanzt, steigen feindselige Sumpflinge daraus empor."}},faq={{q="Wo ist die seltsame fruchttragende Pflanze zu finden?",a="Die seltsame fruchttragende Pflanze wächst wild in Teldrassils Wald, im Unterholz und fernab der großen Siedlungen. Beim Sammeln erhaltet Ihr die Leuchtende Frucht.",al={"wo ist die pflanze zu finden","seltsame fruchttragende pflanze fundort","wie beginnt die leuchtende frucht"}},{q="Wer ist Denalan?",a="Denalan ist ein Nachtelf, Kräuterkundiger und Botaniker, der am Ufer des Al'Amethsees lebt. Er pflegt den Boden, untersucht heimische Pflanzen und beobachtet die seltsamen Störungen, die Teldrassil heimsuchen.",al={"wo ist denalan","denalan npc","wer gibt die leuchtende frucht ab"}},{q="Warum leuchtet die Frucht?",a="Niemand weiß, warum die Frucht leuchtet. Denalan hält sie für ungewöhnlich und will sie untersuchen.",al={"warum leuchtet die frucht","was stimmt mit der frucht nicht"}},{q="Was geschieht, wenn Ihr Denalan die Frucht übergebt?",a="Ihr bringt die leuchtende Frucht zu Denalan am Al'Amethsee, damit er sie untersucht. Seine Erkenntnisse und das Ergebnis Eurer Lieferung werden deutlich, wenn Ihr zurückkehrt.",al={"was erscheint nach der quest","sumpflinghinterhalt"}},{q="Woher stammt diese Pflanze nach Denalans Vermutung?",a="Denalan vermutet, dass die Samen der Pflanze von weit jenseits des großen Meeres stammen und vom fernen östlichen Kontinent Azeroths nach Kalimdor gelangten.",al={"woher stammen die samen","herkunft der frucht"}},{q="Hängt diese Quest mit anderen ökologischen Problemen auf Teldrassil zusammen?",a="Ja. Die Pflanze ist Teil von Denalans umfassender Untersuchung, warum Teldrassils Äste und Waldkreaturen wie die timberlings immer unruhiger und unnatürlicher geworden sind.",al={"verderbnis in teldrassil","probleme am al'amethsee"}}},fx={a8a1e1a2={q="Warum die leuchtende Frucht zu Denalan bringen?",a="Die Fremdartige Fruchtpflanze ist gedankenlose Flora, aber ihre unheimliche Leuchtkraft und ihr bizarres Aussehen heben sie sofort von Teldrassils natürlicher Flora ab. Da Ihr erkennt, dass eine solche unnatürliche Anomalie eine Untersuchung rechtfertigt, ergreift Ihr die Initiative, ein Exemplar an Denalan am Al'Amethsee zu liefern, da Ihr wisst, dass der Botaniker die seltsamen ökologischen Störungen der Insel aktiv untersucht.",al={"warum frucht für denalan","motiv der fremdartigen fruchtpflanze","warum leuchtende frucht pflücken"}}},fp="17,185,20.306.0,23.373.1,41.158.0,15.190.0,24.85.0,48.147.1,46.137.0,67.161.0"}
P.entries["quest:93016"] = {n="A Brief History Lesson",s="Ihr werdet nach Shen'dralas geschickt, um von den Kristallen zu hören, die Ihr repariert habt. Ihr Leuchten hat Besorgnis geweckt, und eine Erklärung erwartet Euch.",h="Ihr werdet nach Shen'dralas geschickt, um von den Kristallen zu hören, die Ihr repariert habt.",kw={"eine kurze geschichtsstunde","kristallleuchten","kristalle","dramatischer himmel","mordent evenshade","shen'dralar","shen'dralas","tempel"},sec={{t="Fragen in Shen'dralas",b="Die Kristalle, die Ihr repariert habt, haben Fragen aufgeworfen, und Ihr werdet zu Mordent Evenshade nach Shen'dralas geschickt, um Antworten zu erhalten. Der Himmel hat ein dramatisches Aussehen angenommen und verstärkt das Unbehagen wegen der früheren Bitten."},{t="Ein geplanter Besuch",b="Mordent sagt, sein Schweigen sei der Aufregung darüber geschuldet gewesen, die Kristalle wieder leuchten zu sehen. Er hofft, den Tempel von Shen'dralas zu besuchen, obwohl ihm der Mut fehlt, mit den Shen'dralar dort zu sprechen."}},faq={{q="Wer soll die Kristalle erklären?",a="Mordent Evenshade in Shen'dralas soll die Kristalle erklären, die Ihr repariert habt.",al={"wer erklärt die kristalle","mordent infos","erklärung der kristalle"}},{q="Warum wirkten die früheren Bitten verdächtig?",a="Die Bitten kamen ohne Zusammenhang, und der Himmel hatte ein dramatisches Aussehen angenommen.",al={"warum verdächtig","was war seltsam","warum kein zusammenhang"}},{q="Warum ließ Mordent die Erklärung aus?",a="Mordent sagt, er habe es kaum erwarten können, die Kristalle wieder leuchten zu sehen, und es versäumt, die Situation von Anfang an zu erklären.",al={"warum keine erklärung","mordents grund","warum wartete er"}},{q="Hat Mordent vor, den Tempel zu besuchen?",a="Mordent freut sich darauf, den Tempel von Shen'dralas wieder zu besuchen, doch es könne dauern, bis er mit den Shen'dralar dort sprechen kann.",al={"tempelbesuch","geht mordent dorthin","tempel von shen'dralas"}}},fp="22,132,24.211.0,15.191.1,40.79.0,45.84.0,42.117.0,38.140.0"}
P.entries["quest:93036"] = {n="Infiltrating the Cult",s="In Shen'dar gewinnt Sania Silverstream Anhänger, während der unsichere Frieden im Dorf zu bröckeln beginnt. Das Dorf bittet einen Neuankömmling, sich ihr zu nähern und herauszufinden, was der Orden der Al'Aketh für die Siedlung plant.",h="In Shen'dar gewinnt Sania Silverstream Anhänger, während der unsichere Frieden im Dorf zu bröckeln beginnt.",kw={"al'aketh","al'akir","alaketh","alakir","infiltrating the cult","sania silverstream","shen'dar","windlord"},ang={["class:Priest"]="Als Priester erkennt Ihr vielleicht, dass Sania Silverstreams Glaube einem Elementarfürsten gilt, nicht dem Heiligen Licht oder Elune. Ihr freundliches religiöses Auftreten verbirgt die Verehrung der Elemente.",["class:Rogue"]="Als Schurke könnt Ihr Eure Talente für Spionage, Täuschung und Aufklärung nutzen, um Euch dem Kult über seine ahnungslose Anwerberin zu nähern."},sec={{t="Ein unsicherer Frieden",b="In Shen'dar beginnt ein unsicherer Waffenstillstand mit dem Orden der Al'Aketh zu zerbrechen. Die örtlichen Autoritäten dulden Sania Silverstream schon lange, eine selbsternannte Missionarin, die unter ihnen lebt. Der Orden gibt sich als friedliche religiöse Bewegung aus und schickt sanftmütige Anwerber, um ahnungslose Anhänger zu gewinnen. Die Dorfoberhäupter lassen Sania Anhänger anwerben, um einen offenen Konflikt mit dem Kult zu vermeiden. Nun beginnt dieser zerbrechliche Frieden zu bröckeln."},{t="Hinter dem Schleier der Missionarin",b="Sania Silverstream ist eine niedere Priesterin im Orden der Al'Aketh, ergeben dem Windlord Al'Akir, dem Herrscher über die Luftelementare. Sie lädt Neuankömmlinge ein, mehr über ihren Herrscher zu erfahren, und verspricht ihnen einen Platz an seiner Tafel. Die Bewohner von Shen'dar sind ihr zu gut bekannt, um sich ihr gefahrlos nähern zu können. Deshalb wenden sich die Dorfoberhäupter an einen Neuankömmling, der ihr Vertrauen gewinnen und aufdecken soll, was der Kult für ihre Heimat plant."}},faq={{q="Wer ist Sania Silverstream?",a="Sania Silverstream ist eine niedere Priesterin im Orden der Al'Aketh, die in Shen'dar lebt und sich als Missionarin ausgibt. Sie wirbt mit sanfter Überzeugungskraft Einheimische an, damit sie den Windlord Al'Akir verehren.",al={"wer ist sania","sania silverstream hintergrundgeschichte","priesterin sania"}},{q="Was ist der Orden der Al'Aketh?",a="Der Orden der Al'Aketh ist ein Kult, der sich als gewöhnliche religiöse Bewegung ausgibt. Seine Mitglieder verehren den Windlord Al'Akir, den Herrscher über die Luftelementare, und werben im Stillen Bekehrte aus nahe gelegenen Siedlungen an, um ihren Einfluss auszuweiten.",al={"wer sind die alaketh","was ist alaketh","orden der alaketh"}},{q="Warum hat Shen'dar Sania Silverstream geduldet?",a="Die Dorfoberhäupter von Shen'dar dulden Sania Silverstreams Missionsarbeit, um einen zerbrechlichen Frieden zu wahren und einen offenen Konflikt mit dem Kult zu vermeiden. Dieser Waffenstillstand bröckelt, weshalb sie beschlossen haben, ihr im Stillen nachzugehen.",al={"warum darf sania bleiben","warum sania nicht töten","warum ist sania im dorf"}},{q="Wer ist der Windlord Al'Akir?",a="Der Windlord Al'Akir ist der Elementarfürst des Himmels, der Stürme und der Luft. Der Orden der Al'Aketh verehrt ihn als seinen Herrscher und verspricht jenen einen Platz an seiner Tafel, die bereuen und sich ihm anschließen.",al={"wer ist der windlord","alakir hintergrundgeschichte","wer ist alakir"}},{q="Warum sollt Ihr den Kult anstelle eines Einheimischen unterwandern?",a="Als Neuankömmling in Shen'dar seid Ihr Sania und den Al'Aketh unbekannt. Sie werden weniger leicht vermuten, dass Ihr für die Dorfoberhäupter arbeitet, sodass Ihr Euch ihr als interessierter Rekrut nähern könnt, ohne Verdacht zu erregen.",al={"warum ich","warum einen abenteurer schicken","grund für die unterwanderungsquest"}},{q="Was planen die Al'Aketh für Shen'dar?",a="Die Dorfoberhäupter von Shen'dar vermuten, dass sich hinter der Anwerbung durch die Al'Aketh weitreichendere, aggressive Pläne für die Siedlung verbergen. Sie wollen diese Pläne aufdecken, bevor der zerbrechliche Frieden zusammenbricht.",al={"kultplan für das dorf","was wollen die alaketh","absichten der alaketh"}}},fp="21,204,18.424.0,29.388.1,26.197.0,34.244.0,54.210.0,28.192.0,60.218.0,52.181.0"}
P.entries["quest:93065"] = {n="Prepare for Battle",s="Die Peacekeepers versammeln sich in der Stadt, um ins umliegende Gebiet zu marschieren. Ihr seid aufgerufen, Eure letzten Vorbereitungen zu treffen und Valennia Stormfist im Böenbeerentiefland zu treffen, bevor die Kompanie aufbricht.",h="Die Peacekeepers versammeln sich in der Stadt, um ins umliegende Gebiet zu marschieren.",kw={"östliche straße","böenbeerentiefland","mobilisierung","peacekeepers","prepare for battle","valennia stormfist"},ang={["class:Warrior"]="Als Kämpfer an vorderster Front wisst Ihr, dass diese Versammlung einem Kampf vorausgeht. Prüft Eure Ausrüstung und reiht Euch neben Euren Verbündeten ein, während sich die Kompanie zum Abmarsch bereit macht."},sec={{t="Ruf zum Appell",b="Die Peacekeepers, die örtlichen Verteidigungskräfte, haben angesichts wachsender Spannungen ihre Truppen und Freiwilligen zu den Waffen gerufen. Sichert Eure Ausrüstung, macht Eure Waffen bereit und schließt Euch der Kompanie an, die sich zum geordneten Marsch ins umliegende Gebiet formiert."},{t="Versammlung im Böenbeerentiefland",b="Die Kompanie versammelt sich an der östlichen Straße, die nach Norden aus der Stadt ins Böenbeerentiefland führt. Dort inspiziert Organisatorin Valennia Stormfist die Kämpfer und verliest die Namen zum Appell. Dann marschiert die Kompanie der Gefahr entgegen."}},faq={{q="Wer ist Valennia Stormfist?",a="Valennia Stormfist organisiert den Appell der Peacekeepers im Böenbeerentiefland. Sie beaufsichtigt die letzten Vorbereitungen an der östlichen Straße, die nach Norden aus der Stadt führt, bevor die Truppen aufbrechen.",al={"wer ist valennia stormfist","valennia stormfist","stormfist"}},{q="Wer sind die Peacekeepers?",a="Die Peacekeepers sind eine organisierte örtliche Verteidigungstruppe. Sie versammeln sich, um einer nahenden Bedrohung außerhalb der Stadt entgegenzutreten.",al={"wer sind die peacekeepers","peacekeepers","peacekeepers-truppe"}},{q="Wo liegt das Böenbeerentiefland?",a="Im Böenbeerentiefland versammeln sich die örtlichen Verteidigungskräfte. Ihr Bereitstellungsraum liegt an der Straße, die nach Norden aus der Stadt führt.",al={"wo liegt das böenbeerentiefland","lage des böenbeerentieflands","böenbeerentiefland"}},{q="Worauf bereiten sich die Peacekeepers vor?",a="Die Peacekeepers bereiten sich darauf vor, in voller Stärke auszurücken. Sie rufen fähige Verbündete dazu auf, ihre Ausrüstung zu prüfen und sich am Stadtrand zu versammeln, bevor die Kompanie aufbricht.",al={"worauf bereiten sie sich vor","warum prepare for battle","was ist das für ein kampf"}},{q="Wo ist der Treffpunkt für den Marsch?",a="Die Kompanie trifft sich an der östlichen Straße, die nach Norden aus der Stadt führt. Dort können sich ihre Mitglieder in Formation sammeln, bevor sie ins Feld ziehen.",al={"wo ist der sammelpunkt","wo valennia treffen","treffpunkt"}},{q="Was geschieht, sobald alle versammelt sind?",a="Valennia Stormfist inspiziert die versammelten Reihen und verliest die Namen zum Appell. Dann marschieren die Truppen der Gefahr entgegen.",al={"wie endet der appell","was sagt valennia","wir sind so bereit wie nur möglich"}}},fp="18,208,16.240.0,35.213.0,26.187.0,25.115.0,33.128.0,40.160.0,44.142.0,40.102.0"}
P.entries["quest:93089"] = {n="What Comes Next",s="Auf der Insel Zephras erbittet der Hohe Orden Euren Segen, bevor er mit seinen Verbündeten der Kirin Tor aufbricht. Der Erfolg ihrer Expedition hängt davon ab, eine arkane Lösung für die Instabilität der Insel zu finden.",h="Auf der Insel Zephras erbittet der Hohe Orden Euren Segen, bevor er mit seinen Verbündeten der Kirin Tor...",kw={"ansirem","dalaran","elaadrin evengale","der hohe orden","kirin tor","himmelskutter","what comes next","insel zephras"},sec={{t="Der Aufbruch",b="Hochälteste Shadowsong hat die Expedition gesegnet, und die Vorbereitungen sind abgeschlossen. Ansirem hat daran gearbeitet, eine Himmelskutterverbindung zwischen Dalaran und der Insel Zephras einzurichten. Nun bereitet sich die Vorhut auf den Aufbruch vor. Sprecht mit Elaadrin Evengale, wenn Ihr bereit seid, die Insel zu verlassen."}},faq={{q="Mit wem spreche ich, bevor ich die Insel Zephras verlasse?",a="Sprecht mit Elaadrin Evengale, wenn Ihr bereit seid, die Insel Zephras zu verlassen.",al={"mit wem sprechen","insel zephras verlassen","elaadrin aufbruch"}},{q="Wohin reist der Hohe Orden?",a="Der Hohe Orden bereitet eine Expedition vor, bei der Himmelskutter Dalaran und die Insel Zephras verbinden.",al={"wohin reisen sie","reiseziel des hohen ordens","nächster halt"}},{q="Wer hilft dem Hohen Orden?",a="Die Kirin Tor helfen dem Hohen Orden. Ansirem hat an einer Himmelskutterverbindung zwischen Dalaran und der Insel Zephras gearbeitet.",al={"wer sind die verbündeten","hilfe der kirin tor","freunde des hohen ordens"}},{q="Wonach sucht die Expedition?",a="Die Expedition hofft, eine arkane Lösung zu finden, um der Insel Zephras Stabilität zu bringen.",al={"wonach suchen sie","arkane lösung","warum die insel verlassen"}},{q="Was ist mit dem Kult geschehen?",a="Elaadrin sagt, der Kult sei besiegt und die Vorbereitungen für die Expedition seien abgeschlossen.",al={"status des kults","ist der kult besiegt","was ist mit dem kult"}}},fp="15,179,13.274.0,48.70.0,30.101.0,30.117.0,31.83.0,26.91.0"}
P.entries["quest:93090"] = {n="What Comes Next",s="Auf der Insel Zephras bereitet sich die Expedition auf die Reise durch die Lüfte nach Kalimdor vor. Der örtliche Kult ist besiegt, und High Elder Shadowsong hat seinen Segen erteilt. Skycutter befördern nun Reisende zwischen der Insel und Mulgore.",h="Auf der Insel Zephras bereitet sich die Expedition auf die Reise durch die Lüfte nach Kalimdor vor.",kw={"ayessa dawnsinger","der irdene ring","high elder shadowsong","mulgore","muln","skycutter","what comes next","insel zephras"},ang={["class:Shaman"]="Als Schamane reist Ihr nach Mulgore, um den Irdenen Ring zu treffen, eine angesehene Schamanenorganisation, die sich der Besänftigung von Azeroths Elementargeistern widmet.",["race:Tauren"]="Als Tauren reist Ihr nach Mulgore, der angestammten Heimat Eures Volkes. Der Irdene Ring unterhält dort seinen Stützpunkt."},sec={{t="Aufbruch von der Insel Zephras",b="High Elder Shadowsong hat die Weiterreise der Expedition von der Insel Zephras gesegnet, wo der örtliche Kult besiegt und die Sicherheit wiederhergestellt wurde. Die Expedition blickt nun über die Insel hinaus und richtet ihr Augenmerk auf die Reise durch den offenen Himmel nach Kalimdor. Ayessa Dawnsinger koordiniert die endgültige Abreise für alle, die zum Aufbruch bereit sind."},{t="Skycutter nach Mulgore",b="Muln arbeitete daran, regelmäßige Reisen per Skycutter zwischen der Insel Zephras und Mulgore zu ermöglichen. Die Testreisen waren erfolgreich, und eine Vorhut hat bereits übergesetzt. Ihre Mitglieder warten auf der anderen Seite, um Kontakt mit dem Schamanen des Irdenen Rings aufzunehmen."}},faq={{q="Was ist die Quest What Comes Next?",a="Die Expedition bereitet sich darauf vor, die Insel Zephras zu verlassen, nachdem sie den Segen von High Elder Shadowsong erhalten und den örtlichen Kult besiegt hat. Die Reisenden sind bereit, per Skycutter durch die Lüfte nach Kalimdor aufzubrechen.",al={"was ist what comes next","what comes next quest","was ist diese quest"}},{q="Wohin reist die Expedition?",a="Skycutter verbinden die Insel Zephras mit Mulgore, einer Region grasbewachsener Tafelberge im Zentrum Kalimdors. Der Irdene Ring ist dort beheimatet, und vorausgereiste Mitglieder der Expedition warten bereits.",al={"wohin geht die reise","skycutter ziel","wohin fliegt der skycutter"}},{q="Wer ist Ayessa Dawnsinger?",a="Ayessa Dawnsinger koordiniert die Abreise von der Insel Zephras. Die Vorbereitungen sind getroffen, die Testflüge waren erfolgreich, und High Elder Shadowsong hat den Aufbruch der Expedition gesegnet.",al={"wer ist ayessa dawnsinger","ayessa dawnsinger","ayessa"}},{q="Wer ist Muln?",a="Muln arbeitete daran, regelmäßige Reisen per Skycutter zwischen der Insel Zephras und Mulgore einzurichten. Er führte Testreisen durch, um eine sichere Überfahrt durch die Lüfte zu gewährleisten.",al={"wer ist muln","muln skycutter","muln zephras"}},{q="Was ist der Irdene Ring?",a="Der Irdene Ring ist eine Organisation von Schamanen, die sich der Wahrung der Harmonie unter den Elementargeistern widmen. Seine Mitglieder sind die Kontaktpersonen und Gastgeber der Expedition in Mulgore.",al={"was ist der irdene ring","irdener ring mulgore","wer ist der irdene ring"}},{q="Warum verlässt die Expedition die Insel Zephras?",a="Der örtliche Kult ist besiegt, und High Elder Shadowsong hat die Expedition gesegnet. Da diese Aufgaben erfüllt sind, kann die Expedition die Insel Zephras verlassen und zum Festland weiterreisen.",al={"warum die insel zephras verlassen","ist zephras abgeschlossen","warum nach mulgore reisen"}}},fp="15,214,27.332.0,21.231.0,34.191.0,33.185.0,25.184.0,12.149.0,25.166.0,43.176.0"}
P.entries["quest:931"] = {n="Der schimmernde Wedel",s="Eine sonderbare Pflanze schimmert zwischen Teldrassils Wurzeln und Baumkronen. Reisende bringen einen Ableger zu Denalan am Al'Amethsee und hoffen, dass der Botaniker ihre Herkunft erklären kann.",h="Eine sonderbare Pflanze schimmert zwischen Teldrassils Wurzeln und Baumkronen.",kw={"botanik","denalan","al'amethsee","schimmernder wedel","gesprossene wedel","seltsame wedelpflanze","sümpfe des elends","teldrassil"},ang={["class:Druid"]="Als Druide könnt Ihr beobachten, wie fremde Pflanzen Teldrassils junge Baumkronen beeinflussen.",["profession:Herbalism"]="Kräuterkundige und Pflanzenliebhaber mögen sich fragen, wie eine Pflanze aus den Sümpfen des Elends so fern ihrer sumpfigen Heimat gedeiht.",["race:NightElf"]="Als Nachtelf, der seine neue Heimat pflegt, könnt Ihr sehen, wie Denalans Experimente die Widerstandskraft von Teldrassils Boden offenbaren."},sec={{t="Ein seltsames Leuchten",b="Eine seltsame Pflanze fängt in Teldrassils Geäst das Licht ein. Ihre Wedel winden sich mit einem pulsierenden Schimmer, anders als das übliche Blattwerk der Insel. Das Leuchten zieht zwischen den Pflanzen des jungen Waldes die Blicke auf sich."},{t="Denalans Entdeckung",b="Am Al'Amethsee erkennt Denalan den Ableger als eine Pflanze, die nicht aus dem nördlichen Kalimdor stammt. Zuletzt sah er vor Jahrzehnten eine solche Pflanze auf einer Reise durch die Sümpfe des Elends in den Östlichen Königreichen. Wie ihr Samen den Ozean überquerte und auf dem Weltbaum so groß werden konnte, gibt ihm Rätsel auf. Denalan beginnt, das Exemplar zu kultivieren und zu untersuchen."}},faq={{q="Woher stammt die seltsame Pflanze ursprünglich?",a="Denalan zufolge stammt die Pflanze aus den Sümpfen des Elends in den Östlichen Königreichen. Zuletzt sah er vor Jahrzehnten ein lebendes Exemplar in jenen Sümpfen.",al={"herkunft des wedels","woher stammt der wedel","sumpfpflanze"}},{q="Wer ist Denalan?",a="Denalan ist ein nachtelfischer Botaniker und Kräuterkundiger nahe dem Al'Amethsee auf Teldrassil. Er erforscht und pflegt die wachsende Pflanzenwelt der Insel und experimentiert mit fremden Samen und Pflanzgefäßen.",al={"denalans geschichte","wer ist denalan"}},{q="Warum wächst diese Pflanze auf Teldrassil?",a="Niemand weiß, wie die Pflanze Teldrassil erreichte. Denalan fragt sich, wie ein Samen aus den Östlichen Königreichen das große Meer überquerte, dann in Teldrassils Erde Wurzeln schlug und groß wurde.",al={"wie kam die pflanze nach teldrassil","warum ist der wedel hier"}},{q="Was geschieht, nachdem Denalan den Wedel erhalten hat?",a="Denalan setzt das Exemplar in sein Pflanzgefäß am Al'Amethsee und beginnt, es zu untersuchen. Rasch sprießen mehrere Wedel und erblühen, sodass er mehr zu erforschen hat.",al={"nächste quest","denalans untersuchung","gesprossene wedel"}},{q="Verursacht diese Pflanze Verderbnis in Teldrassil?",a="Nein. Die Pflanze scheint eine ungewöhnliche exotische Art am falschen Ort zu sein, statt eine Quelle der Verderbnis.",al={"ist der wedel verderbt","verderbte pflanze"}}},fx={add2b0dd={q="Warum einen Wedel der Seltsamen Wedelpflanze zu Denalan bringen?",a="Die Pflanze selbst hat keine bewusste Motivation; sie ist lediglich ein ungewöhnliches, pulsierendes Exemplar, das wild in Teldrassils Zweigen wächst. Ihr erkennt ihre seltsame, schimmernde Aura als etwas Exotisches und möglicherweise Unnatürliches für den großen Baum, was Euch dazu veranlasst, einen Ableger für Denalan zu ernten, den ansässigen Botaniker, der am Al'Amethsee seltene Flora untersucht.",al={"motiv der seltsamen wedelpflanze","warum wedel zu denalan bringen","warum wedel nehmen"}}},fp="20,168,14.188.0,19.318.1,50.139.0,15.180.0,40.174.0,47.151.1,47.107.0"}
P.entries["quest:93159"] = {n="The Strange Hermit",s="The Strange Hermit ist eine Einführungsquest im Schattenwindwald, die sich auf einen schüchternen, verhüllten Einsiedler konzentriert, der abseits der Zivilisation lebt. Auf der Suche nach einem Gespräch nach langer Isolation teilt der Hermit Einblicke in sein einfaches, handgefertigtes Leben und seine Bindung zu den örtlichen singenden Waldgeistern.",h="The Strange Hermit ist eine Einführungsquest im Schattenwindwald, die sich auf einen schüchternen, verhüllten...",kw={"waldgeister","handgefertigt","hermit","verhüllte gestalt","einzelgänger","schattenwindwald","seltsamer hermit"},ang={["class:Druid"]="Druiden, die mit der Natur im Einklang stehen, wissen die Interaktion des Hermits mit den örtlichen Waldgeistern vielleicht zu schätzen, obwohl seine Unfähigkeit, sich wahrhaft mit ihnen zu unterhalten, im Kontrast zur tieferen Zwiesprache eines Druiden steht.",["profession:Engineering"]="Tüftler und Handwerker können möglicherweise nachempfinden, dass der Hermit darin Trost findet, Dinge von Hand zu bauen, um seine einsame Behausung einzurichten."},sec={{t="Ein Einsiedler im Wald",b="Tief im abgeschiedenen Blätterdach des Schattenwindwalds lebt ein rätselhafter, verhüllter Einsiedler, der einfach als the Strange Hermit bekannt ist. Weit entfernt von besiedelten Städten und üblichen Handelsrouten verbringt er seine Tage in ruhiger Isolation zwischen den Bäumen. Nähert man sich ihm, zeigen seine unbeholfene Sprache und sein nervöses Auftreten, wie lange er ohne gewöhnliche Gesellschaft gelebt hat, was selbst eine einfache Begrüßung zu einer ungewohnten Herausforderung macht."},{t="Geister und einfache Dinge",b="Obwohl er einsam lebt, beharrt der Hermit darauf, dass er alle Gesellschaft und Vorräte hat, die er braucht. Er vertraut an, dass er einst woanders lebte, bevor er sich hier niederließ, und sich entschied, ein Leben inmitten von handgefertigtem Tand und den örtlichen Waldgeistern zu führen. Während die wilden Geister häufig für ihn singen, gibt er zu, dass melodische Chöre das Gespräch mit jemandem, der wirklich antworten kann, nicht völlig ersetzen können."}},faq={{q="Wer ist der seltsame Hermit?",a="Der seltsame Hermit ist eine exzentrische, verhüllte Person, die in Isolation im Schattenwindwald lebt. An regelmäßige soziale Interaktion nicht gewöhnt, verbringt er seine Zeit damit, sich um handgefertigte Besitztümer zu kümmern und mit den örtlichen Waldgeistern zu kommunizieren, anstatt mit anderen Menschen.",al={"seltsamer hermit","identität des hermits","wer ist der hermit"}},{q="Wo lebt der Hermit?",a="Der Hermit hat sein Zuhause abgelegen tief zwischen den Bäumen des Schattenwindwalds errichtet und lebt weit abseits der ausgetretenen Pfade, wo nur selten Reisende vorbeikommen.",al={"wo ist der hermit","lage des schattenwindwalds","zone des hermits"}},{q="Warum lebt der Hermit allein?",a="Er gibt zu, dass er an einem völlig anderen Ort lebte, bevor er sich in den Wald zurückzog. Obwohl er bezüglich seiner Vergangenheit recht vage bleibt, wählte er ein ruhiges Leben, nur umgeben von Dingen, die er selbst gebaut hat, und den wilden Geistern des Waldes.",al={"warum der hermit allein ist","isolation des hermits","hintergrundgeschichte des hermits"}},{q="Kann der Hermit mit Waldgeistern sprechen?",a="Er betrachtet die örtlichen Waldgeister als seine Gefährten, obwohl sie keine normalen Gespräche führen. Stattdessen singen sie für ihn, was er als angenehm empfindet, auch wenn es nicht die Tiefe einer Unterhaltung mit einem anderen Sterblichen bieten kann.",al={"hermit spricht mit geistern","waldgeister schattenwindwald","freunde des hermits"}},{q="Was hat der Hermit im Wald gebaut?",a="Der Hermit erwähnt, mehrere handgefertigte Gegenstände und Bauwerke zu besitzen, die ihn beschäftigen, und findet Trost und Zufriedenheit in einfachen handgemachten Besitztümern.",al={"handarbeiten des hermits","was baute der hermit"}},{q="Was geschieht während der Quest 'The Strange Hermit'?",a="Die Quest beinhaltet, an den nervösen Hermit im Schattenwindwald heranzutreten, um ein freundliches Gespräch zu beginnen und das Wenige zu erfahren, das er über sein zurückgezogenes Dasein preiszugeben bereit ist.",al={"quest the strange hermit","mit dem hermit sprechen"}}},fp="18,192,22.261.0,25.245.0,26.194.0,27.117.0,36.180.0,41.148.0,40.140.0,51.115.0"}
P.entries["quest:93160"] = {n="The Forest's Bounty",s="Im Schattenwindwald braucht ein Sammler Hilfe beim Auflesen herabgefallener Eicheln. Raptorartige Raubtiere durchstreifen die tieferen Wälder, und die Ernte lässt sich zu einer Waldmahlzeit rösten.",h="Im Schattenwindwald braucht ein Sammler Hilfe beim Auflesen herabgefallener Eicheln.",kw={"eicheln","kochen","nahrungssuche","raptorvogel","schattenwind-eicheln","schattenwindwald","the forest's bounty"},ang={["profession:Cooking"]="Als Koch könnt Ihr Schattenwind-Eicheln zu einfacher Waldkost rösten."},sec={{t="Eine gefährliche Nahrungssuche",b="Ein vorsichtiger Sammler im Schattenwindwald hat die Eicheln in sicherer Nähe aufgelesen. Wilde, raptorartige Kreaturen streifen zwischen den Bäumen umher und hindern den Sammler daran, die wilderen Haine zu erreichen. Deshalb werden vorbeiziehende Reisende gebraucht, um aufzusammeln, was tiefer im Wald liegt, und dafür zu sorgen, dass keiner von beiden hungert."},{t="Die Ernte rösten",b="Schattenwind-Eicheln ergeben nahrhafte Kost, wenn sie sorgfältig zubereitet werden. Roh können sie bitter oder zäh sein, doch das Rösten über einem Feuer verwandelt die Wilde Ernte in einen gehaltvollen Leckerbissen. Um sie zu sammeln, müsst Ihr Euch ins Gehölz wagen, wo Raubvögel umherstreifen."}},faq={{q="Wer bittet Euch, die Eicheln zu sammeln?",a="Ein nervöser Sammler nahe dem Schattenwindwald bittet Euch, Eicheln zu sammeln. Er hat die in der Nähe aufgelesen, braucht aber Hilfe, um Waldgebiete zu erreichen, in denen gefährliche Wildtiere umherstreifen.",al={"wer vergibt die quest the forest's bounty","wer möchte eicheln","questgeber the forest's bounty"}},{q="Wo sind die Eicheln zu finden?",a="Schattenwind-Eicheln liegen unter dem Blätterdach des Schattenwindwalds verstreut. Sucht auf dem Waldboden und haltet zwischen den Bäumen nach Raubtieren Ausschau.",al={"wo sind schattenwind-eicheln","eicheln fundort","schattenwindwald eicheln"}},{q="Warum ist das Sammeln von Eicheln hier gefährlich?",a="Raubvögel, die Raptoren ähneln, streifen über den Waldboden. Ohne Kampfausbildung geraten gewöhnliche Leute in Gefahr, wenn sie sich weit vom Lager entfernen.",al={"warum ist der schattenwindwald gefährlich","was sind raptorvögel","warum ist eicheln sammeln gefährlich"}},{q="Wofür werden die Eicheln verwendet?",a="Die Eicheln sind nahrhafte Wildkost. Röstet sie über einem Feuer als warmen Imbiss, den Ihr mit jenen teilen könnt, die den Waldtieren trotzen wollen.",al={"wofür sind schattenwind-eicheln","geröstete eicheln","warum eicheln sammeln"}},{q="Was sind die im Wald erwähnten Raptorvogel-Kreaturen?",a="Der Sammler beschreibt gefährliche „Raptorvogel-Dinger“, die im Schattenwindwald jagen. Diese vogel- oder reptilienartigen Raubtiere sind groß und wild genug, um einen unachtsamen Reisenden zu erbeuten.",al={"was ist ein raptorvogel-ding","raptorvögel in shadowgale","waldraptoren"}},{q="Wie werden die Eicheln zum Verzehr zubereitet?",a="Schattenwind-Eicheln können roh zäh oder bitter sein. Durch Rösten über Hitze werden sie zu einem köstlichen Leckerbissen.",al={"sind schattenwind-eicheln roh essbar","wie schattenwind-eicheln zubereiten","waldeicheln essen"}}},fp="19,164,23.292.0,20.236.0,34.162.0,27.132.0,40.133.0,29.128.0,59.181.0,39.99.0"}
P.entries["quest:93165"] = {n="Mercy Falls on Deaf Ears",s="In der Wildnis um den Schattenwindwald suchen die Überlebenden der Nightclaw Rache an den Al'Aketh. Nach einer schrecklichen Tragödie durch die Hand der Kultisten bieten sie Münzen und versprechen Zugang zu ihren verborgenen Überlieferungen für Trophäen erschlagener Feinde. Ihre Fehde erstreckt sich nun über den Schattenwindwald und die umliegenden Gebiete.",h="In der Wildnis um den Schattenwindwald suchen die Überlebenden der Nightclaw Rache an den Al'Aketh.",kw={"al'aketh","blutfehde","kultisten","ohren","böenbeerentiefland","mercy falls on deaf ears","nightclaw","schattenwindwald","schrein von akir"},sec={{t="Blut für Blut",b="Die Enklave der Nightclaw und die Al'Aketh-Kultisten sind in eine erbitterte Fehde verstrickt. Eine schreckliche Tragödie hat den Überlebenden jede Hoffnung auf Frieden genommen. Sie suchen Rache für ihre gefallenen Angehörigen und wenden sich an umherziehende Abenteurer und Söldner um Hilfe. Die Enklave bietet jenen Münzen und die Aussicht auf tieferes Vertrauen, die Kultisten töten und deren Ohren als Beweis zurückbringen."},{t="Die Bedrohung der Al'Aketh",b="Die Al'Aketh breiten ihren Einfluss im Böenbeerentiefland, im Schattenwindwald und im uralten Schrein von Akir aus. Ihre finsteren Praktiken und ihre fanatische Lebensweise haben ihnen den Hass der Einheimischen eingebracht. Angriffe auf die Lager des Kults in diesen Gebieten können seinen Einfluss schwächen und die Gunst der verschwiegenen Nightclaw einbringen. Die Enklave hütet ihre Geheimnisse, bis ein Außenstehender seine Treue beweist."}},faq={{q="Was ist Mercy Falls on Deaf Ears?",a="Die Enklave der Nightclaw bietet jenen Münzen und tieferes Vertrauen, die Al'Aketh-Kultisten töten und deren Ohren zurückbringen. Die Überlebenden suchen nach einer schrecklichen Tragödie Rache.",al={"mercy falls on deaf ears quest","was ist diese quest","questübersicht"}},{q="Wer sind die Al'Aketh?",a="Die Al'Aketh sind eine Sekte verfluchter Kultisten, deren Taten Verderben und Tragödien über benachbarte Siedlungen gebracht haben. Sie sind im Böenbeerentiefland, im Schattenwindwald und im Schrein von Akir tätig und lösen Blutfehden mit den Bewohnern dieser Gebiete aus.",al={"wer sind die alaketh","alaketh kultisten hintergrund","wer sind al'aketh"}},{q="Wo sind Al'Aketh-Kultisten zu finden?",a="Al'Aketh-Kultisten sind im Schattenwindwald, rund um den Schrein von Akir und im gesamten Böenbeerentiefland zu finden. Die Nightclaw verlangen Beweise von jenen, die sie töten.",al={"wo sind alaketh kultisten","alaketh standorte","wo kultisten finden"}},{q="Warum sammelt der Questgeber Kultistenohren?",a="Die Nightclaw verlangen Kultistenohren als Beweis dafür, dass ihre Feinde tot sind. Nach einer schweren Tragödie durch die Hand der Al'Aketh sucht die Enklave Rache und verlangt für jedes ausgezahlte Kopfgeld einen Beweis.",al={"warum ohren","warum wollen sie kultistenohren","ohren als beweis"}},{q="Wer sind die Nightclaw?",a="Die Nightclaw sind eine verschwiegene Enklave, die durch die Hand der Al'Aketh schwere Verluste erlitten hat. Sie hüten ihre Überlieferungen streng, versprechen Außenstehenden aber Zugang zu ihren Geheimnissen, wenn diese im Kampf gegen die Kultisten ihre Treue beweisen.",al={"nightclaw fraktion","wer sind nightclaw","nightclaw geheimnisse hintergrund"}},{q="Welche Tragödie haben die Al'Aketh verursacht?",a="Die Al'Aketh haben eine große Tragödie über die Enklave der Nightclaw gebracht und damit eine kompromisslose Blutfehde entfacht. Der Kopfgeldauftrag nennt keine Einzelheiten zum Vorfall oder seinen Opfern, doch die Überlebenden verlangen vollständige Vergeltung.",al={"was haben die alaketh getan","was ist der enklave widerfahren","alaketh tragödie"}},{q="Was sind die Geheimnisse der Nightclaw?",a="Die Nightclaw bewahren ihre Geheimnisse innerhalb der Enklave und offenbaren sie Außenstehenden nicht sofort. Sie versprechen jenen Zugang zu diesem verborgenen Wissen, die sie weiterhin im Kampf gegen die Al'Aketh unterstützen und sich als wahre Freunde erweisen.",al={"nightclaw geheimnisse","welche geheimnisse haben die nightclaw","was offenbaren die nightclaw"}}},fp="24,329,15.361.0,19.392.0,33.168.0,21.257.0,37.169.0,46.180.0,22.231.0,36.206.0,33.234.0"}
P.entries["quest:93172"] = {n="Free the Hollows",s="Im Schattenwindwald klingt der traurige Gesang der Wind Hollows durch uralte Ruinen. Eine alte Tragödie bindet diese geisterhaften Wesen, und Reisende wollen ihnen Frieden schenken.",h="Im Schattenwindwald klingt der traurige Gesang der Wind Hollows durch uralte Ruinen.",kw={"free the hollows","geister","hollows","ruinen","shadowgale","schattenwindwald","wind hollows"},ang={["class:Druid"]="Als Druide wisst Ihr, dass die ruhelosen Geister im Schattenwindwald die Wildnis stören und nach Gleichgewicht und Erlösung verlangen.",["class:Priest"]="Als Priester seht Ihr in den Wind Hollows traurige Geister, die durch eine Tragödie gefangen sind. Ihre Vernichtung gilt als Gnade, die in Qual gebundene Seelen erlöst.",["race:NightElf"]="Als Elf der Insel wisst Ihr, dass der Schattenwindwald seit Langem als Spukort gefürchtet wird und seine Geister an uralte Ruinen gebunden sind."},sec={{t="Spuk in Shadowgale",b="Elfen auf der ganzen Insel fürchten den Schattenwindwald seit Langem als verwunschenen Hain. In seinen nordöstlichen Wäldern liegen alte Steinruinen unter dichtem Bewuchs. Geisterhafte Wind Hollows treiben dort rastlos umher, doch sie zeigen keine Bosheit. Ihre Trauer deutet auf ein Unglück hin, das die Ruinen vor langer Zeit heimsuchte."},{t="Der klagende Gesang",b="In stillen Nächten hören Reisende nahe den Ruinen seltsamen Gesang, den der Wind heranträgt. Kein Lied der Sterblichen klingt so, und seine tiefe Melancholie beunruhigt alle, die es hören. Mitfühlende Reisende glauben, dass die Schemen unter ihrer endlosen Klage leiden. Sie suchen die Wind Hollows auf, um ihre geisterhaften Fesseln zu brechen und ihnen Frieden zu schenken."}},faq={{q="Was sind die Wind Hollows?",a="Wind Hollows sind traurige, geisterhafte Wesen, die in alten Elfenruinen im Nordosten des Schattenwindwalds spuken. Durch eine uralte Tragödie gebunden, singen sie nachts klagend zwischen den Bäumen.",al={"was sind wind hollows","geschichte der hollows","was sind die hollows"}},{q="Warum müssen die Wind Hollows befreit werden?",a="Man glaubt, dass eine schreckliche Katastrophe die Geister noch immer bindet und in Trauer gefangen hält. Ihre Vernichtung gilt als Akt der Gnade, der ihre verweilenden Gestalten aus den Ruinen erlöst.",al={"warum hollows befreien","warum hollows töten","zweck von free the hollows"}},{q="Wo sind die Geister zu finden?",a="Die Geister sammeln sich zwischen uralten Ruinen in den nordöstlichen Wäldern des Schattenwindwalds, eines von Elfen bewohnten Inselwalds.",al={"wo liegt der schattenwindwald","ruinen von shadowgale","lage der ruinen"}},{q="Was ist der seltsame Gesang, der im Wald zu hören ist?",a="Die Wind Hollows singen eine traurige Melodie, die keiner gewöhnlichen Weise gleicht. Man glaubt, ihr Gesang rühre von ihrem tragischen Ende und ihrer endlosen Gefangenschaft in den Ruinen der Insel her.",al={"gesang der hollows","geistergesang","warum singen die geister"}},{q="Wer bittet Euch, die Hollows zu befreien?",a="Ein Beobachter auf der Insel hat Mitleid mit den gefangenen Geistern und bittet Euch, sie zu befreien, wohl wissend, dass die örtlichen Elfen den verwunschenen Wald fürchten.",al={"wer vergibt free the hollows","questgeber von free the hollows"}},{q="Was geschah in den Ruinen, wodurch die Hollows entstanden?",a="Die genauen Einzelheiten sind im Lauf der Zeit verloren gegangen, doch die Einheimischen wissen, dass ein schreckliches Ereignis die nordöstlichen Ruinen heimsuchte und die Geister dort in endloser Trauer band.",al={"was geschah in den ruinen von shadowgale","warum spukt es in den ruinen"}}},fp="16,173,23.290.0,17.315.0,26.184.0,41.184.0,28.125.0,47.176.0,33.121.0,49.152.0"}
P.entries["quest:93176"] = {n="My Little Friends",s="Ein Pfleger bietet Euch ein Paket an, um mit dem Studium dreier kleiner Kreaturen zu beginnen. Das Entomology Starter Kit enthält die Notizen und Materialien für die Arbeit.",h="Ein Pfleger bietet Euch ein Paket an, um mit dem Studium dreier kleiner Kreaturen zu beginnen.",kw={"arbor tarantula","entomologie","flesh picker","hay weevil specimen","menagerie","my little friends","starterset"},sec={{t="Das Angebot eines Pflegers",b="Ein Pfleger, der viele Stunden mit dem Studium einer kleinen Menagerie verbracht hat, bietet Euch an, sein Hobby mit Euch zu teilen. Das Paket enthält Notizen und Materialien für den Anfang. Mit dem Entomology Starter Kit könnt Ihr nach einer Arbor Tarantula, einem Hay Weevil Specimen und einem Flesh Picker suchen."}},faq={{q="Was soll ich für den Pfleger tun?",a="Benutzt das Entomology Starter Kit, um eine Arbor Tarantula, ein Hay Weevil Specimen und einen Flesh Picker zu finden und zu fangen.",al={"my little friends aufgabe","was muss ich sammeln"}},{q="Was ist in dem Paket?",a="Das Paket enthält Notizen und Materialien, die Euch den Einstieg in das Hobby des Pflegers erleichtern.",al={"starterset inhalt","was ist im paket"}},{q="Was erforscht der Pfleger?",a="Der Pfleger erforscht die Anatomie, die Ernährung und die sozialen Rituale der Kreaturen in einer kleinen Menagerie.",al={"kleine menagerie","was erforscht er"}},{q="Was passiert, wenn ich das Set verliere?",a="Der Pfleger sagt, dass Ihr für eine kleine Gebühr ein weiteres Paket kaufen müsst.",al={"starterset verloren","ersatz für das set"}}},fp="17,141,18.256.0,35.111.0,23.86.0,28.96.0,31.74.0"}
P.entries["quest:932"] = {n="Krankhafter Hass",s="Nahe Teldrassils Siedlungen hat Lord Melenas die Grell am Teufelsfels um sich geschart. Tallonkai Flinkwurzel entsendet bewährte Champions, um den Satyr aufzuhalten, bevor er die Nachtelfen bedroht.",h="Nahe Teldrassils Siedlungen hat Lord Melenas die Grell am Teufelsfels um sich geschart.",kw={"teufelsfels","grell","lord melenas","satyr","tallonkai flinkwurzel","teldrassil","krankhafter hass"},ang={["class:Druid"]="Als Druide trefft Ihr auf Melenas und seine verderbten Grell, die das empfindliche Gleichgewicht der jungen Wildnis Teldrassils vergiften.",["race:NightElf"]="Als Nachtelf steht Ihr einer uralten Erinnerung daran gegenüber, wie Eure Vorfahren dämonischem Ehrgeiz verfielen. Lord Melenas zu besiegen ist eine Pflicht gegenüber dem Weltbaum und ein Akt der Sühne für Eure Ahnen."},sec={{t="Eine bittere Schmach",b="Satyrn verkörpern einen uralten Verrat in der Geschichte der Kaldorei. Während des Krieges der Ahnen waren sie Hochgeborene, die sich der Brennenden Legion verschrieben. Nun hat sich einer auf Teldrassil festgesetzt, dem jungen Weltbaum, der als Zuflucht gedacht war. Für Tallonkai Flinkwurzel und die Verteidiger an seiner Seite ist diese Gegenwart eine bittere Schmach."},{t="Die Bedrohung am Teufelsfels",b="Nördlich der nahen Pfade wimmeln die verderbten Höhlen des Teufelsfelsens von wilden Grell. Lord Melenas hat die chaotischen Kreaturen unter seinem Willen zu einer feindseligen Streitmacht versammelt. Tallonkai fürchtet, was der Satyr über die Äste des Weltbaums bringen könnte, und verlangt ein schnelles, stilles Ende. Er will, dass Melenas getötet und sein abgetrennter Kopf zurückgebracht wird."}},faq={{q="Wer ist Lord Melenas?",a="Lord Melenas ist ein Satyr, der den Teufelsfels im Norden Teldrassils für sich beansprucht hat. Er befehligt aggressive Grellkrieger und schmiedet Pläne, um Verderbnis im Weltbaum zu verbreiten.",al={"lord melenas","wer ist melenas","teufelsfels boss"}},{q="Wo kann ich Lord Melenas finden?",a="Lord Melenas lauert tief im Teufelsfels, nördlich von Dolanaar auf Teldrassil. Grell und andere verderbte Kreaturen umgeben ihn.",al={"melenas aufenthaltsort","wo ist melenas","wie den teufelsfels finden"}},{q="Warum will Tallonkai Flinkwurzel dies geheim halten?",a="Satyrn erinnern an den uralten Verrat der Nachtelfen während des Krieges der Ahnen. Dass sich ein Satyr so dreist im jungen Weltbaum festsetzt, ist eine Schmach, und Tallonkai will die Angelegenheit ohne weitverbreitete Panik bereinigen.",al={"warum geheim","warum muss das unter uns bleiben","tallonkai geheimnis"}},{q="In welcher Beziehung stehen Satyrn und Grell zueinander?",a="Grell sind kleine, schelmische Wildkreaturen, von Natur aus verderbt und auf ganz Teldrassil zu finden. Satyrn können diese niederen Kreaturen einschüchtern oder unterwerfen, damit sie ihren Zielen dienen.",al={"grell und satyrn","warum folgen grell melenas","verbindung zwischen satyrn und grell"}},{q="Warum gibt es überhaupt Satyrn auf Teldrassil?",a="Teldrassil wurde erst vor wenigen Jahren herangezogen, doch Verderbnis und dunkle Wesen erreichten die Insel rasch, entgegen der Hoffnung der Druiden auf eine unverdorbene Zuflucht. Satyrn schlichen sich ein und errichteten Stützpunkte an finsteren Orten wie dem Teufelsfels.",al={"satyrn auf teldrassil","wie kamen satyrn hierher","teldrassil verderbnis"}},{q="Wer ist Tallonkai Flinkwurzel?",a="Tallonkai Flinkwurzel ist ein Nachtelfenwächter, der nahe Dolanaar stationiert ist. Er hält nach Bedrohungen für Teldrassil Ausschau und schickt Abenteurer gegen nahe Verderbnisherde aus.",al={"tallonkai","wer vergibt krankhafter hass"}}},fx={["84ee0888"]={q="Warum braucht Tallonkai Flinkwurzel Melenas Kopf?",a="Tallonkai Flinkwurzel bittet um den abgetrennten Kopf von Lord Melenas als unwiderlegbaren Beweis dafür, dass der Satyr wirklich erschlagen wurde. Mit Lord Melenas' Tod und dessen Kopf in der Hand kann Tallonkai sicher sein, dass die üble Bedrohung, die direkt neben dem Laubschattental lauert, im Geheimen beseitigt wurde, was es ihm ermöglicht, die demütigende Angelegenheit hinter sich zu lassen, ohne unter den Ältesten Alarm zu schlagen.",al={"zweck von melenas kopf","warum melenas kopf zurückbringen","wofür ist melenas kopf"}}},fp="14,179,17.327.0,22.331.0,20.167.0,30.123.0,51.210.0,50.167.0,54.221.0,27.165.0"}
P.entries["quest:93224"] = {n="Carved Centaur Totems",s="Captain Pentigast an der Nijelspitze sucht geschnitzte Zentaurentotems, um ihre Muster nachzuahmen. Er hofft, mit den Nachbildungen bei den Zentaurenstämmen einen Vorteil erkaufen zu können.",h="Captain Pentigast an der Nijelspitze sucht geschnitzte Zentaurentotems, um ihre Muster nachzuahmen.",kw={"captain pentigast","geschnitzte zentaurentotems","geschnitztes holz","zentauren","zentaurenstämme","desolace","die nijelspitze","totems"},sec={{t="Ein Handel mit Holz",b="Captain Pentigast an der Nijelspitze sucht in den geschnitzten Holzarbeiten der Zentaurenstämme nach einer Möglichkeit, sich einen Vorteil zu verschaffen. Beide Stämme zögern, Hilfe von Außenstehenden anzunehmen, besonders von Nicht-Zentauren. Er bittet Euch, ihm Muster ihrer Schnitzereien zu bringen, damit er ähnliche anfertigen lassen kann."}},faq={{q="Warum will Captain Pentigast die Totems?",a="Er hofft, ähnliche Schnitzereien anfertigen zu lassen und sich bei den Zentaurenstämmen einen Vorteil zu erkaufen.",al={"warum totems","pentigasts plan"}},{q="Warum zögern die Zentaurenstämme, Hilfe anzunehmen?",a="Beide Stämme zögern, Hilfe von außerhalb ihres Stammes anzunehmen, besonders von Nicht-Zentauren.",al={"warum nehmen zentauren keine hilfe an","zentauren misstrauen außenstehenden"}},{q="Woraus sind die Zentaurentotems gefertigt?",a="Die örtlichen Zentauren handeln mit geschnitztem Holz.",al={"material der totems","geschnitztes holz"}},{q="Wo wartet Captain Pentigast?",a="Captain Pentigast befindet sich an der Nijelspitze.",al={"wo ist pentigast","hauptmann an der nijelspitze"}}},fp="21,158,17.267.0,43.81.0,50.88.0,36.42.0,34.38.0"}
P.entries["quest:93225"] = {n="Carved Centaur Totems",s="Gurda Wildmane glaubt, dass geschnitzte Totems helfen könnten, die Gunst der Gelkis oder Magram zu gewinnen. Sie braucht echte Totems, die von Zentaurenclans in Desolace gesammelt wurden.",h="Gurda Wildmane glaubt, dass geschnitzte Totems helfen könnten, die Gunst der Gelkis oder Magram zu gewinnen.",kw={"geschnitzte zentaurentotems","währung der zentauren","desolace","gelkis","geistwandlerposten","gurda wildmane","magram"},sec={{t="Eine Währung der Zentauren",b="Gurda Wildmane am Geistwandlerposten hat beobachtet, wie sich Zentaurenclans abseits ihrer Siedlungen zum Handel treffen. Sie hat gesehen, dass sie geschnitzte Totems als Währung verwenden. Nun glaubt sie, dass ein großer Vorrat die Gelkis oder Magram umstimmen könnte, doch die Totems, die sie geschnitzt hat, wirken vielleicht nicht echt. Deshalb bittet sie Euch, ihr echte Exemplare zu bringen."}},faq={{q="Was möchte Gurda?",a="Gurda Wildmane bittet Euch, ihr echte geschnitzte Zentaurentotems zu bringen.",al={"gurdas bitte","was braucht wildmane"}},{q="Wozu braucht sie geschnitzte Totems?",a="Gurda glaubt, dass ein großer Vorrat helfen könnte, die Gunst der Gelkis oder Magram zu gewinnen.",al={"wofür die totems","warum totems"}},{q="Wo verwenden die Zentauren die Totems?",a="Gurda hat gesehen, wie sich Zentauren verschiedener Clans abseits ihrer Siedlungen treffen und mit geschnitzten Totems als Währung handeln.",al={"zentaurenhandel","wo die totems"}},{q="Wo finde ich Gurda Wildmane?",a="Gurda Wildmane ist am Geistwandlerposten.",al={"gurdas ort","wildmane am geistwandlerposten"}},{q="Welche Zentaurenclans sind beteiligt?",a="Gurda hofft, dass ein Vorrat an Totems die Gunst der Gelkis oder der Magram gewinnen könnte.",al={"gelkis magram","welche clans"}}},fp="21,157,18.320.0,21.69.0,32.79.0,32.118.0,32.39.0,33.84.0"}
P.entries["quest:933"] = {n="Krone der Erde",s="An den Teichen von Arlithrien bittet Corithras Mondzorn Euch, Wasser zu holen, während Gnarlpine-Furbolgs gewalttätig werden. Sein Bericht über Teldrassil beginnt mit Malfurion Sturmgrimms Verschwinden nach dem Dritten Krieg.",h="An den Teichen von Arlithrien bittet Corithras Mondzorn Euch, Wasser zu holen, während Gnarlpine-Furbolgs...",kw={"corithras mondzorn","dolanaar","fandral hirschhaupt","gnarlpine","malfurion sturmgrimm","teiche von arlithrien","turmalinphiole"},ang={["class:Druid"]="Als Druide erfahrt Ihr, wie Fandral Hirschhaupts Führung den Zirkel des Cenarius spaltete, während er darauf drängte, die einstige Unsterblichkeit der Nachtelfen zurückzugewinnen.",["race:NightElf"]="Als Nachtelf erfahrt Ihr, wie Teldrassil nach Malfurions plötzlichem Verschwinden entstand, und lernt die politische Entscheidung hinter seiner Pflanzung kennen."},sec={{t="Ein gefährlicher Mondbrunnen",b="Corithras Mondzorn gibt Euch eine Turmalinphiole und schickt Euch zu einem Mondbrunnen südöstlich des Eingangs von Darnassus, an den Teichen von Arlithrien. Die Gnarlpine-Furbolgs waren einst friedlich, doch nun schlagen sie ohne Vorwarnung zu. Sie überfallen Reisende und bedrängen Späherpatrouillen in der gesamten Region. Diese Scharmützel sind zu einer Bedrohung für die neue Heimat der Nachtelfen geworden."},{t="Fandral Hirschhaupts Ehrgeiz",b="Als Ihr mit der gefüllten Phiole zurückkehrt, erzählt Corithras Euch, wie Teldrassil entstand. Nach dem Dritten Krieg verschwand Shan'do Malfurion Sturmgrimm und ließ die Druiden des Cenarius führungslos und gespalten zurück. Erzdruide Fandral Hirschhaupt übernahm in seiner Abwesenheit die Führung. Er drängte den Zirkel der Ältesten in Dunkelküste, seine Trauer hinter sich zu lassen. Die Nachtelfen, so erklärte er, mussten ihre verlorene Unsterblichkeit zurückgewinnen und ihre Zivilisation heilen, indem sie einen gewaltigen neuen Weltenbaum pflanzten."}},faq={{q="Wo ist der Mondbrunnen für diese Quest?",a="Der Mondbrunnen liegt südöstlich des Haupteingangs von Darnassus, an den südlichen Ufern der Teiche von Arlithrien.",al={"arlithrien mondbrunnen","mondbrunnen standort","wo phiole füllen"}},{q="Warum greifen die Gnarlpine-Furbolgs an?",a="Die Gnarlpine-Furbolgs, einst ein friedliches Volk von Bärenmenschen, leiden nun überall auf Teldrassil unter einer dunklen, blinden Raserei. Die Späher hielten die Angriffe zunächst für Einzelfälle, doch inzwischen sind sie zu einer ständigen Gefahr für nahe Siedlungen und Patrouillen geworden.",al={"furbolgs wahnsinnig","gnarlpine aggressiv","warum furbolgs angreifen"}},{q="Was ist mit Malfurion Sturmgrimm geschehen?",a="Shan'do Malfurion Sturmgrimm verschwand nach dem Dritten Krieg ohne Erklärung. Die Druiden des Cenarius und die Anführer der Nachtelfen wissen nicht, was aus ihm geworden ist.",al={"wo ist malfurion","was geschah mit sturmgrimm","malfurion verschwunden"}},{q="Wer beschloss, Teldrassil zu pflanzen?",a="Nach Malfurions Verschwinden übernahm Erzdruide Fandral Hirschhaupt die Führung unter den Druiden. Er überzeugte den Zirkel der Ältesten in Dunkelküste, einen neuen Weltenbaum wachsen zu lassen, da die Kaldorei ihn für den Wiederaufbau und die Rückgewinnung der mit Nordrassils Zerstörung verlorenen Unsterblichkeit brauchten.",al={"wer erschuf teldrassil","hirschhaupt weltenbaum","warum wurde teldrassil gepflanzt"}}},fx={f2628340={q="Warum möchte Corithras Mondzorn, dass dies getan wird?",a="Corithras Mondzorn untersucht die heiligen Mondbrunnen über ganz Teldrassil, um den Zustand des Weltenbaums zu beurteilen und zu pflegen. Während er Euch durch diese Rituale führt, teilt er auch die heikle Geschichte der Pflanzung von Teldrassil – in der Hoffnung, dass Ihr sowohl die heiligen Pflichten Eures Volkes als auch die beunruhigenden Zeichen versteht, die sich über ihrer neuen Heimat ausbreiten.",al={"warum will corithras mondbrunnenwasser","motiv von corithras","warum krone der erde"}},["21308da4"]={q="Wofür ist die Gefüllte Turmalinphiole?",a="Die Phiole enthält reines Wasser, das aus dem Mondbrunnen in der Nähe der Teiche von Arlithrien geschöpft wurde. Corithras benötigt Proben aus Teldrassils verschiedenen Mondbrunnen, um das Wasser zu überwachen, das den Weltenbaum nährt, und um die Riten durchzuführen, die nötig sind, um das spirituelle Gleichgewicht des Landes inmitten der zunehmenden Verderbnis aufrechtzuerhalten.",al={"zweck der gefüllten turmalinphiole","warum turmalinphiole füllen","turmalinphiole mondbrunnen"}}},fp="18,201,19.359.0,27.473.0,37.111.0,41.247.0,37.151.0,32.269.0"}
P.entries["quest:93317"] = {n="Crab Season",s="Auf Zephras sammeln Einheimische eilig Windsongkriecher, ehe die kurze Saison endet. Kultisten haben die Ufer gefährlich gemacht, deshalb bitten die Einheimischen um Hilfe.",h="Auf Zephras sammeln Einheimische eilig Windsongkriecher, ehe die kurze Saison endet.",kw={"crab season","krabben","kultaktivitäten","windsongkriecherfleisch","windsongkriecher","windweisensee","zephras"},ang={["profession:Cooking"]="Als Koch könnt Ihr saisonales Fleisch von Windsongkriechern zubereiten, die aus dem See auf Zephras gesammelt werden."},sec={{t="Eine flüchtige Ernte",b="Jedes Jahr erscheinen für wenige Wochen Windsongkriecher an den Süßwasserufern des Windweisensees und an den Flüssen, die ihn speisen. Ihr Fleisch ist eine seltene Ernte, doch die Saison ist bald vorüber."},{t="Gefahr am Wasser",b="Kultisten durchstreifen die Wildnis rund um Zephras und gefährden einheimische Sammler. Der Weg zum Windweisensee ist für Sammler allein zu gefährlich. Wenn Ihr den Ufern und den übellaunigen Krabben nicht trotzt, könnte diese kurze Ernte verloren sein."}},faq={{q="Was sind Windsongkriecher?",a="Windsongkriecher sind aggressive Krabben, die nur rund um den Windweisensee auf Zephras vorkommen. Sie können jedes Jahr nur wenige Wochen lang gesammelt werden.",al={"was sind windsongkriecher","windsongkrabben","seekrabben zephras"}},{q="Warum müssen die Krabben gerade jetzt gesammelt werden?",a="Windsongkriecher gibt es jedes Jahr nur für wenige Wochen. Sobald die Saison endet, lässt sich ihr Fleisch erst im nächsten Jahr wieder sammeln.",al={"warum jetzt kriecher sammeln","zeitfenster der kriechersaison","warum krabben nur begrenzt verfügbar"}},{q="Warum kann der einheimische Sammler die Krabben nicht selbst sammeln?",a="Die Aktivitäten der Kultisten haben den Weg zum Windweisensee für einheimische Sammler zu gefährlich gemacht, um ihn vor Ende der kurzen Saison zurückzulegen.",al={"warum können einheimische keine krabben sammeln","kultisten zephras","kultaktivitäten windsong"}},{q="Wo findet man Windsongkriecher?",a="Windsongkriecher leben an den Ufern des Windweisensees auf Zephras und an den nahen Ufern der angeschlossenen Flüsse.",al={"fundorte der windsongkriecher","wo sind krabben auf zephras","ufer des windweisensees"}},{q="Ist die Jagd auf Windsongkriecher gefährlich?",a="Windsongkriecher sind aggressiv und schnappen nach jedem, der versucht, sie zu sammeln.",al={"sind windsongkriecher gefährlich","temperament der krabben","übellaunige krabben"}},{q="Wofür wird das Fleisch der Windsongkriecher verwendet?",a="Die Einheimischen sammeln das Fleisch der Windsongkriecher als saisonale Nahrung während der wenigen Wochen, in denen es verfügbar ist. Weil Kultisten die Wege versperren, suchen sie Hilfe bei Abenteurern.",al={"verwendung von windsongkriecherfleisch","warum krabbenfleisch sammeln","wofür ist kriecherfleisch"}}},fp="11,149,18.180.0,19.235.0,27.135.0,48.144.0,58.125.0,34.105.0,40.74.0,39.163.0"}
P.entries["quest:93318"] = {n="WANTED: Vulgara the Insatiable",s="Im Shen'darhochland terrorisiert Vulgara the Insatiable Reisende und nahe gelegene Siedlungen. Constable Aonda hat ein Kopfgeld der Friedenswahrer ausloben lassen, für das Vulgaras Kopf zu Danarii Bellowveil gebracht werden soll.",h="Im Shen'darhochland terrorisiert Vulgara the Insatiable Reisende und nahe gelegene Siedlungen.",kw={"kopfgeld","constable aonda","danarii bellowveil","friedenswahrer","shen'darhochland","shen'dar","vuldren","vulgara","vulgara the insatiable"},sec={{t="Die Geißel des Hochlands",b="Constable Aonda hat Vulgara the Insatiable als unmittelbare Gefahr für das Hochland eingestuft. Die gewaltige geflügelte Vuldren hat ihren Horst südwestlich von Shen'dar, wo sie Reisende und örtliche Siedlungen terrorisiert. Die Friedenswahrer rufen Kopfgeldjäger dazu auf, der Bedrohung ein Ende zu setzen."},{t="Bedrängte Beschützer",b="Banditen und ein im Verborgenen agierender Kult machen den Friedenswahrern in der gesamten Region zu schaffen. Vulgara zu erschlagen würde die Gefahr für die örtliche Bevölkerung verringern und den Himmel über Shen'dar sicher halten. Dann könnten sich die Verteidiger auf die Zivilverteidigung konzentrieren."}},faq={{q="Wer ist Vulgara the Insatiable?",a="Vulgara the Insatiable ist eine gewaltige geflügelte Vuldren, die das Shen'darhochland terrorisiert. Die örtlichen Behörden nennen sie eine Geißel, und ihr unstillbarer Hunger und ihre Gewalttätigkeit gefährden Reisende und nahe gelegene Siedlungen.",al={"wer ist vulgara","vulgara hintergrundgeschichte","was für ein monster ist vulgara"}},{q="Wer hat das Kopfgeld auf Vulgara ausgesetzt?",a="Constable Aonda von den örtlichen Friedenswahrern hat das Kopfgeld zum Schutz der örtlichen Bevölkerung ausgesetzt. Jäger sollen Danarii Bellowveil einen Beweis für Vulgaras Tod bringen.",al={"wer hat das kopfgeld auf vulgara ausgesetzt","wer will vulgara tot sehen","constable aonda"}},{q="Wo ist Vulgara the Insatiable zu finden?",a="Vulgara streift auf einer Hügelkuppe südwestlich von Shen'dar im Shen'darhochland umher.",al={"vulgara fundort","wo erscheint vulgara","vulgara finden"}},{q="Wer ist Danarii Bellowveil?",a="Danarii Bellowveil wickelt den Kopfgeldauftrag ab. Während Banditen und Kultisten die Friedenswahrer bedrängen, prüft Danarii Vulgaras abgetrennten Kopf und zahlt die versprochene Belohnung aus.",al={"wer ist danarii bellowveil","bei danarii abgeben"}},{q="Was für eine Kreatur ist ein Vuldren?",a="Ein Vuldren ist eine gefährliche geflügelte Raubbestie, die im Hochland vorkommt. Vulgara ist besonders gewaltig und bösartig, und ihre Raubzüge bedrohen die örtlichen Siedlungen.",al={"was ist ein vuldren","vuldren bestie"}},{q="Welche anderen Bedrohungen plagen das Shen'darhochland?",a="Die Friedenswahrer im Shen'darhochland sind durch einen fest verwurzelten Kult und Banditen, die die örtliche Bevölkerung ausplündern, überlastet. Raubbestien wie Vulgara machen ihnen ebenfalls zu schaffen.",al={"welche bedrohungen gibt es im shen'darhochland","shen'dar kult und banditen"}}},fp="30,204,20.264.0,20.212.0,30.207.0,33.155.0,42.81.0,26.180.0,35.164.0,49.174.0"}
P.entries["quest:93319"] = {n="Pilfered Windstones",s="Auf Zephras fehlen durch gestohlene Windsteine wichtige Notfallvorräte. Die Highlands Bandits haben sie gestohlen, während Aondas wenige Friedenswahrer die wachsende Zahl von Kultisten bei Falaath Village in Schach halten.",h="Auf Zephras fehlen durch gestohlene Windsteine wichtige Notfallvorräte.",kw={"aonda","banditenhöhle","falaath village","highlands bandits","pilfered windstones","shen'darhochland","windsteine","zephras"},ang={["class:Rogue"]="Als Schurke erkennt Ihr, wie die Highlands Bandits ausnutzen, dass die Bedrohung durch Kultisten die Kräfte einer Siedlung überfordert.",["race:Skyborne"]="Als Skyborne wisst Ihr, dass der Alltag auf Zephras von Windsteinen abhängt. Diese Vorräte zurückzuholen und zu verteidigen, ist für die örtlichen Siedlungen von Bedeutung."},sec={{t="Die geplünderten Vorratslager von Zephras",b="Windsteine halten den Alltag auf Zephras am Laufen. Jede Siedlung hält Notfallvorräte für Krisenzeiten bereit, doch die Vorräte der Dörfer wurden knapp. Dann fand man die Steine bei gefangenen Banditen aus dem nördlichen Shen'darhochland. Monatelang hatten sich die Highlands Bandits in örtliche Vorratslager geschlichen und bei schwacher Bewachung mitgenommen, was sie konnten."},{t="Überlastete Verteidigung und drohende Gefahren",b="Aonda ist für die Verteidigung des Dorfes verantwortlich und hat sich geweigert, einen Angriff auf die nördliche Höhle zu genehmigen. Die Siedlung hat zu wenige Friedenswahrer, um sie entbehren zu können. Im Süden werden die Kultisten bei Falaath Village immer zahlreicher, weshalb die Wachen angesichts dieser Bedrohung ihre Posten halten müssen. Da die Friedenswahrer gebunden sind, müssen unabhängige Abenteurer sich den Banditen stellen und die gestohlenen Windsteine zurückholen."}},faq={{q="Wofür werden Windsteine auf Zephras gebraucht?",a="Die Bewohner von Zephras sind im Alltag und zum Überleben auf Windsteine angewiesen. Die Siedlungen halten Vorratslager für Notfälle bereit.",al={"wofür werden windsteine gebraucht","warum werden windsteine benötigt","zweck der windsteine"}},{q="Wer hat die Windsteine gestohlen?",a="Die Highlands Bandits haben die Windsteine gestohlen. Man fand sie bei gefangenen Banditen aus einer Höhle im Shen'darhochland, und die Einheimischen glauben, dass die Diebe monatelang in die Vorratslager der Dörfer eingebrochen waren.",al={"wer hat die windsteine gestohlen","wer hat windsteine genommen","windsteindiebe"}},{q="Wo befinden sich die Highlands Bandits?",a="Die Highlands Bandits lagern in einer Höhle nördlich der Siedlung im Shen'darhochland. Dort bewahren sie Waren auf, die sie aus den Vorratslagern der Dörfer gestohlen haben.",al={"wo ist die banditenhöhle","standort der highlands bandits","shendar banditen"}},{q="Warum hat das Dorf die Banditenhöhle noch nicht ausgehoben?",a="Aonda leitet die Verteidigung der Siedlung und hat einen Angriff auf die nördliche Höhle abgelehnt, weil das Dorf nur wenige Friedenswahrer hat. Würden sie fortgeschickt, wäre die Siedlung der wachsenden Zahl von Kultisten bei Falaath Village im Süden schutzlos ausgeliefert.",al={"warum die banditenhöhle nicht angreifen","warum aonda nicht angreift","dorfverteidigung banditen"}},{q="Welche Bedrohung gibt es bei Falaath Village?",a="Bei Falaath Village südlich der Siedlung wächst die Zahl der Kultisten. Wegen ihrer Anwesenheit müssen die Friedenswahrer ihre Heimat bewachen, statt Banditen zu verfolgen.",al={"welche bedrohung bei falaath village","kultisten falaath","falaath kultisten"}},{q="Behebt die Rückholung der Windsteine den Mangel in der Siedlung?",a="Die Rückholung der gestohlenen Steine entlastet die Notfallvorräte vorübergehend, doch die Störungen der Versorgungswege bleiben ein dringendes Problem. Ohne sichere Nachschubwege werden Engpässe die Siedlung weiterhin bedrohen.",al={"sind die windsteine jetzt sicher","versorgungswege zephras","windsteinmangel behoben"}}},fp="19,184,28.354.0,38.379.0,40.117.0,25.210.0,40.137.0,51.254.0,38.159.0,63.194.0"}
P.entries["quest:93320"] = {n="Tower Defense",s="An der befestigten Stellung hält Tower Defense einer erdrückenden Übermacht stand. Die Verteidiger halten die Linie vorerst, doch Erschöpfung droht sie zu durchbrechen.",h="An der befestigten Stellung hält Tower Defense einer erdrückenden Übermacht stand.",kw={"verteidiger","erschöpfung","befestigung","außenposten","belagerung","patt","tower defense"},ang={["class:Warrior"]="Als Krieger wisst Ihr, dass das Standhalten gegen eine Übermacht Ausdauer ebenso auf die Probe stellt wie Können. Disziplin an der Front kann den Zusammenbruch der Verteidigung verhindern."},sec={{t="Eine bedrängte Verteidigung",b="Die Garnison wehrt den ersten Ansturm an einer befestigten Stellung ab. Doch die Angreifer sind zahlenmäßig überlegen und drängen weiter vor. Die überlebenden Kämpfer werden müde, und die Grenze zwischen Überleben und Niederlage wird schmal."},{t="Drohende Zermürbung",b="Die Garnison hält ihren Verteidigungsring, doch die Zeit spielt den Angreifern in die Hände. Anhaltende Scharmützel gegen eine zahlenmäßige Übermacht zehren an den Kräften der Verteidiger. Sie brauchen einen entscheidenden Vorstoß, um das Patt zu durchbrechen, bevor ihre Linien nachgeben."}},faq={{q="Worum geht es in Tower Defense?",a="Tower Defense ist eine verzweifelte Verteidigung gegen eine erdrückende Übermacht. Die Linie hält noch, doch Erschöpfung droht sie zu durchbrechen, wenn das Patt nicht endet.",al={"was ist tower defense","tower defense quest","was ist das für eine quest"}},{q="Gegen wen kämpfen die Verteidiger?",a="Die Angreifer sind den Verteidigern zahlenmäßig überlegen und setzen die Garnison so stark unter Druck, dass ihre Kräfte schwinden. Der Kult greift den Pylonenwachturm außerhalb der Stadt an.",al={"wer greift in tower defense an","gegen wen kämpfen wir","tower defense gegner"}},{q="Wie steht es derzeit um die Verteidiger?",a="Die Verteidiger ermüden durch die anhaltenden Kämpfe unter unablässigen Angriffen. Ohne Entlastung droht die Garnison an Boden zu verlieren, wenn das Patt nicht bald durchbrochen wird.",al={"warum sind die verteidiger müde","patt am turm","stand des kampfes"}},{q="Entscheidet das Halten der Linie die Schlacht?",a="Den Ansturm abzuwehren verschafft nur wenig Zeit. Erschöpfung wird die Verteidiger zermürben, wenn sie keinen Weg finden, das Patt zu durchbrechen.",al={"haben wir tower defense gewonnen","wie endet tower defense","was passiert nach der abwehr"}},{q="Wo findet diese Verteidigung statt?",a="Die Verteidigung findet an einem befestigten Außenposten statt, der belagert wird. Der ständige Druck zahlreicher Angreifer hat die Verteidiger an ihre Grenzen gebracht.",al={"wo findet tower defense statt","tower defense gebiet","welcher turm ist das"}},{q="Was ist nötig, um das Blatt zu wenden?",a="Die Verteidiger brauchen rasch einen Plan, um die Belagerung zu durchbrechen, bevor ihre erschöpfte Frontlinie nachgibt.",al={"was muss als nächstes getan werden","wie die belagerung gewinnen","das patt durchbrechen"}}},fp="13,156,21.221.0,23.219.0,28.152.0,31.143.0,44.155.0,41.131.0,35.135.0,32.94.0"}
P.entries["quest:93394"] = {n="Meeting the Magister",s="Ein Kontakt der Shen'dralar bittet Euch, Magister Kirandis im Tempel von Shen'dralas zu suchen. Es geht um die erneuerten Pylonen des Tempels und Euren Platz unter seinen misstrauischen Bewohnern.",h="Ein Kontakt der Shen'dralar bittet Euch, Magister Kirandis im Tempel von Shen'dralas zu suchen.",kw={"kirandis","magister kirandis","treffen mit dem magister","pylonen","shen'dralar","shen'dralas","tempel"},sec={{t="Im Tempel",b="Das eindrucksvolle Bauwerk zieht Eure Aufmerksamkeit auf sich, und ein Kontakt der Shen'dralar weist Euch den Weg zu Magister Kirandis. Der Magister ist ein alter Freund der Person, die Euch geschickt hat, und könnte Euch willkommen heißen. Die Shen'dralar sind vielleicht misstrauisch, daher sollt Ihr ihnen mit Respekt begegnen."},{t="Die Pylonen",b="Als Ihr Kirandis findet, sieht der Magister, dass die Macht der Pylonen wieder erstrahlt. Ihre Rückkehr bindet die Shen'dralar vollständig an Shen'dralas. Kirandis drängt Euch, die Bewohner des Tempels kennenzulernen, deren Misstrauen mit der Zeit schwinden könnte."}},faq={{q="Wen soll ich finden?",a="Ihr sollt Magister Kirandis im Tempel von Shen'dralas ausfindig machen.",al={"kirandis finden","treffen mit magister","kirandis tempel"}},{q="Wo ist Magister Kirandis?",a="Magister Kirandis befindet sich im Tempel von Shen'dralas.",al={"kirandis aufenthaltsort","wo magister","tempel kirandis"}},{q="Was bedeutet Kirandis der Person, die mich geschickt hat?",a="Kirandis ist ein alter Freund des Kontakts der Shen'dralar, der Euch geschickt hat.",al={"kirandis freund","alter freund magister"}},{q="Werden die Shen'dralar mich willkommen heißen?",a="Die Shen'dralar sind vielleicht misstrauisch, aber Ihr sollt ihnen respektvoll begegnen.",al={"shen'dralar misstrauisch","mögen sie mich","shen'dralar willkommen"}},{q="Was ist mit den Pylonen geschehen?",a="Ihre Macht erstrahlt wieder, und Kirandis sagt, dass dies die Shen'dralar vollständig an Shen'dralas bindet.",al={"macht der pylonen","tempel-pylonen","pylonen erneuert"}},{q="Was soll ich tun, nachdem ich Kirandis getroffen habe?",a="Kirandis ermutigt Euch, einige Bewohner des Tempels kennenzulernen, die anfangs misstrauisch sein könnten.",al={"bewohner kennenlernen","was nun kirandis","bewohner von shen'dralas"}}},fp="20,180,13.266.0,10.221.0,26.75.0,27.54.0,42.66.0,32.86.0,32.92.0,40.88.0"}
P.entries["quest:934"] = {n="Krone der Erde",s="Auf der Lichtung des Orakels schickt Euch Corithras Mondzorn, Wasser aus Teldrassils heiligem Mondbrunnen zu holen. Die Reise beginnt zu enthüllen, warum die Erschaffung des Weltbaums misslang.",h="Auf der Lichtung des Orakels schickt Euch Corithras Mondzorn, Wasser aus Teldrassils heiligem Mondbrunnen zu...",kw={"alexstrasza","amethystphiole","corithras mondzorn","fandral hirschhaupt","unsterblichkeit","mondbrunnen","nozdormu","die lichtung des orakels","oracle tree","teldrassil"},ang={["class:Druid"]="Als Druide erkennt Ihr die Kluft zwischen Fandral Hirschhaupts nachdrücklichem Ehrgeiz und dem natürlichen Gleichgewicht, das traditionell von Malfurion Sturmgrimm gewahrt wird.",["faction:Alliance"]="Als Mitglied der Allianz erfahrt Ihr, warum Fäulnis und der Wahnsinn der Kreaturen Teldrassil plagen, das neueste Hauptstadtgebiet der Allianz.",["race:NightElf"]="Als Nachtelf hört Ihr von den Hoffnungen Eures Volkes für Teldrassil nach Nordrassils Opfer während des Dritten Krieges."},sec={{t="Die Lichtung des Orakels",b="Corithras Mondzorn schickt Euch nordwestwärts durch Teldrassil zur Lichtung des Orakels. Unter den gewaltigen Ästen des Oracle Tree liegt der erste und mächtigste Mondbrunnen der Insel. Ihr schöpft Wasser aus seinem heiligen Becken in eine Amethystphiole. Von diesem Heiligtum aus wachen Druiden und der Baum selbst über die Gesundheit ihrer neuen Heimat."},{t="Der verweigerte Segen",b="Als Ihr die Phiole nach Dolanaar zurückbringt, erzählt Euch Corithras, wie der Plan von Erzdruide Fandral Hirschhaupt scheiterte. Nachdem Nordrassil am Hyjal geopfert worden war, pflanzte Hirschhaupt Teldrassil, um die Unsterblichkeit der Nachtelfen wiederherzustellen. Er bat die Drachenaspekte, den Baum zu segnen.\n\nNozdormu der Zeitlose weigerte sich und tadelte Hirschhaupt für seine Arroganz. Auch Königin Alexstrasza verweigerte ihren Segen, die Gabe des Aspekts des Lebens. Ohne diese Gabe wuchs Teldrassil unstet und unvollkommen und blieb dadurch anfällig für tiefgreifende Verderbnis."}},faq={{q="Wo liegt der Mondbrunnen auf der Lichtung des Orakels?",a="Der Mondbrunnen auf der Lichtung des Orakels liegt im Nordwesten Teldrassils, unter den gewaltigen Ästen des Oracle Tree und direkt nördlich der Hauptstraße nach Darnassus.",al={"wo ist die lichtung des orakels","mondbrunnen lichtung des orakels standort","orakelbrunnen"}},{q="Wer ist Corithras Mondzorn?",a="Corithras Mondzorn ist ein nachtelfischer Hüter, der in Dolanaar stationiert ist. Er führt junge Verteidiger durch Teldrassil, um Proben aus dessen Mondbrunnen zu sammeln, und lehrt die Geschichte der fehlerhaften Anfänge des Baums.",al={"corithras","wer ist corithras mondzorn"}},{q="Hat Teldrassil die Unsterblichkeit der Nachtelfen wiederhergestellt?",a="Nein. Teldrassil gab den Nachtelfen eine neue Heimat, doch ihre Unsterblichkeit wurde nach Nordrassils Opfer während des Dritten Krieges nicht wiederhergestellt.",al={"sind nachtelfen unsterblich","teldrassil unsterblichkeit","leben elfen wieder ewig"}},{q="Wozu wird Wasser von der Lichtung des Orakels gesammelt?",a="Der Mondbrunnen unter dem Oracle Tree ist der erste und mächtigste der Insel. Sein Wasser ermöglicht Corithras, Teldrassils geistige und natürliche Gesundheit zu beurteilen.",al={"warum orakelwasser holen","amethystphiole zweck"}}},fx={["28d6c4e0"]={q="Warum möchte Corithras Mondzorn, dass dies getan wird?",a="Corithras Mondzorn führt Euch durch die heiligen Mondbrunnen von Teldrassil, um die wahre Geschichte des neuen Weltenbaums zu vermitteln. Indem er Euch unter die Zweige des Orakelbaums schickt, um Wasser aus Teldrassils erstem und mächtigstem Brunnen zu schöpfen, stellt er sicher, dass Ihr mit seiner tiefen Weisheit aus erster Hand kommuniziert, bevor er offenbart, warum die Zweige weiterhin beunruhigt und unfruchtbar an Unsterblichkeit sind.",al={"warum will corithras das wasser","motiv von corithras","warum zur lichtung des orakels schicken"}}},fp="18,174,16.321.0,19.520.1,43.152.0,26.190.0,45.139.0,62.156.0"}
P.entries["quest:93461"] = {n="Welcome to Shen'dar Village",s="In Shen'dar werden Neuankömmlinge mit hochgeborenem Blut unter einem brüchigen Waffenstillstand willkommen geheißen. Der Hohe Orden und die Windformer wahren den Frieden innerhalb der Siedlung, während jenseits ihrer Grenzen alte Rivalitäten schwelen.",h="In Shen'dar werden Neuankömmlinge mit hochgeborenem Blut unter einem brüchigen Waffenstillstand willkommen...",kw={"coriella calmbreeze","der hohe orden","hochgeborene","haupthütte","rathiril sunlance","shen'dar","windformer"},ang={["class:Mage"]="Als Magier mit Verbindungen zu den Traditionen der Hochgeborenen erkennt Ihr im Hohen Orden womöglich Eure eigene Abstammung wieder. Seine Ältesten, darunter Rathiril Sunlance, genießen in Shen'dar Respekt.",["race:NightElf"]="Als Nachtelf findet Ihr in Shen'dar Verbindungen zu uralten Blutlinien und zum Vermächtnis der Hochgeborenen, eine Erinnerung an den Stolz und das arkane Erbe, die die elfische Gesellschaft spalteten."},sec={{t="Ein brüchiger Herd",b="Neuankömmlinge mit Spuren hochgeborenen Blutes gehen zur Haupthütte, um Rathiril Sunlance, einem Ältesten des Hohen Ordens, ihre Ehrerbietung zu erweisen. Außerdem bitten sie Coriella Calmbreeze, die örtliche Wirtin, um ein Zimmer. Verschiedene elfische Fraktionen teilen diesen Zufluchtsort, doch ihr Waffenstillstand bleibt angespannt."},{t="Rivalitäten der Wildnis",b="Der Alltag bringt Zimmer und Gelegenheitsarbeiten mit sich, doch zwischen dem Hohen Orden und den Windformern bestehen weiterhin Spannungen. Auf dem Dorfplatz wahren beide Gruppen die Höflichkeit. Jenseits der Siedlung, fernab neugieriger Blicke, nehmen alte Rivalitäten ungehemmt ihren Lauf."}},faq={{q="Welchen Zweck hat die Quest „Welcome to Shen'dar Village“ in Shen'dar?",a="Ihr werdet in Shen'dar willkommen geheißen und lernt seine wichtigsten Persönlichkeiten und seinen brüchigen Frieden kennen. Ihr begegnet Rathiril Sunlance, dem Ältesten des Hohen Ordens, und Coriella Calmbreeze im Dorfgasthaus, bevor Ihr örtliche Arbeiten übernehmt.",al={"was ist das für eine quest","willkommen in shen'dar infos","shen'dar einführung"}},{q="Wer ist Rathiril Sunlance?",a="Rathiril Sunlance ist ein Ältester des Hohen Ordens, der in Shen'dar lebt. Er befindet sich in der Haupthütte des Dorfes, um die Ecke von der Person, die Euch zuerst willkommen heißt, und ist ein Ansprechpartner für jene, die von den Hochgeborenen abstammen oder mit dem Hohen Orden zu tun haben.",al={"wer ist rathiril sunlance","ältester des hohen ordens","wo ist rathiril"}},{q="Wer ist Coriella Calmbreeze?",a="Coriella Calmbreeze führt das örtliche Gasthaus in Shen'dar. Sie bietet Reisenden Nahrung, Unterkunft und Vorräte, bevor sie sich in die umliegende Wildnis wagen.",al={"wer ist coriella calmbreeze","shen'dar wirtin","wo gibt es unterkunft in shen'dar"}},{q="Welche Spannungen bestehen zwischen dem Hohen Orden und den Windformern?",a="Der Hohe Orden und die Windformer folgen unterschiedlichen Traditionen und Zielen, und zwischen ihnen herrschen starke Spannungen. Innerhalb von Shen'dar wahren sie einen höflichen Frieden, doch jenseits der Dorfgrenze kann der Konflikt in der Wildnis in Gewalt umschlagen.",al={"hoher orden gegen windformer","warum gibt es spannungen","konflikt im dorf"}},{q="Was meint der Questgeber mit dem Aussehen des Hohen Ordens?",a="Die Nachfahren der Hochgeborenen haben ein unverwechselbares Funkeln in den Augen. Dieses arkane Erbe lässt aufmerksame Einheimische das Aussehen des Hohen Ordens erkennen.",al={"aussehen des hohen ordens","augen der hochgeborenen","funkeln der hochgeborenen"}},{q="Ist Shen'dar vor Konflikten sicher?",a="Innerhalb von Shen'dar wahren der Hohe Orden und die Windformer die Höflichkeit. Außerhalb der Siedlung endet der Frieden, und fernab wachsamer Augen flammt offene Feindseligkeit auf.",al={"ist shen'dar sicher","gewalt außerhalb von shen'dar","gefahr in der wildnis"}}},fp="27,199,16.267.0,22.230.0,61.211.0,25.249.0,27.156.0,63.230.0,56.157.0,39.171.0"}
P.entries["quest:93464"] = {n="The Visiting Mage",s="Ein Draenei im Sicheren Hafen bittet Euch, Azore aufzusuchen, einen menschlichen Magier in Desolace. Sein Wissen über draenethyst könnte denen helfen, die seine Macht nicht ganz verstehen.",h="Ein Draenei im Sicheren Hafen bittet Euch, Azore aufzusuchen, einen menschlichen Magier in Desolace.",kw={"azore","desolace","draenei","draenethyst","der sichere hafen","menschlicher magier"},sec={{t="Ein erinnerter Magier",b="Im Sicheren Hafen erinnert sich ein Draenei daran, Azore fortgeschickt zu haben, als dieser aus Desolace kam. Der menschliche Magier fürchtete die Macht von draenethyst und warnte davor, dass es nicht in die falschen Hände geraten dürfe. Nun scheint es sich zu lohnen, sein Wissen zu suchen, obwohl der Draenei zugibt, dass die Bewohner hier den Kristall nicht ganz verstehen. Ihr sollt Azore in Desolace finden."}},faq={{q="Wer ist Azore?",a="Azore ist ein menschlicher Magier aus Desolace, der einst zum Sicheren Hafen kam. Er fürchtete die Macht von draenethyst.",al={"wer ist azore","besuchender magier","draenethyst magier"}},{q="Was ist draenethyst?",a="Draenethyst ist den Draenei im Sicheren Hafen heilig und hilft ihnen, den Verstand zu bewahren, obwohl sie es nicht ganz verstehen.",al={"draenethyst","draenei kristall","was ist draenethyst"}},{q="Warum suche ich Azore?",a="Die Draenei im Sicheren Hafen glauben, dass Azores Wissen über draenethyst wertvoll sein könnte.",al={"azore finden","warum magier suchen","magier in desolace"}},{q="Wohin ging Azore?",a="Azore ist in Desolace.",al={"azores aufenthaltsort","wo ist der magier","besuchenden magier finden"}},{q="Warum schickten die Draenei Azore fort?",a="Sie schickten Azore fort, um zu schützen, was ihnen gehörte.",al={"warum azore fortschicken","azore hinausgeworfen","magier im sicheren hafen"}}},fp="17,159,17.336.0,13.98.0,20.119.0,27.88.0,19.21.0,37.49.0"}
P.entries["quest:93465"] = {n="Notes on Draenethyst",s="Azore Aldamort schickt Euch los, um Gimashis Aufzeichnungen über draenethyst zu holen. Die Hexenmeister der Burning Blade erforschen den Stoff, der von jenseits des Dunklen Portals stammt.",h="Azore Aldamort schickt Euch los, um Gimashis Aufzeichnungen über draenethyst zu holen.",kw={"azore aldamort","burning blade","das dunkle portal","draenethyst","gimashi","aufzeichnungen","hexenmeister"},sec={{t="Gimashis Aufzeichnungen",b="Azore Aldamort sagt, Gimashis Aufzeichnungen könnten erklären, was die Burning Blade über draenethyst herausgefunden hat. Gimashi ist eine Hexenmeisterin, deren Turm in einer Schlucht im Südosten steht. Ihr sollt ihre Aufzeichnungen zu Azore zurückbringen, bevor die Burning Blade ihr Wissen über den Stoff für finstere Zwecke nutzen kann."}},faq={{q="Was ist draenethyst?",a="Draenethyst ist ein Stoff von jenseits des Dunklen Portals.",al={"bedeutung von draenethyst","was ist draenethyst","draenethyst stein"}},{q="Wer ist Gimashi?",a="Gimashi ist eine Hexenmeisterin der Burning Blade, die draenethyst erforscht.",al={"wer ist gimashi","hexenmeisterin gimashi","gimashis aufzeichnungen"}},{q="Warum will Azore Gimashis Aufzeichnungen?",a="Azore will durch Gimashis Aufzeichnungen erfahren, was die Burning Blade über draenethyst weiß.",al={"warum aufzeichnungen","azore draenethyst","was braucht azore"}},{q="Wo ist Gimashi?",a="Gimashi ist oben auf ihrem Turm in einer Schlucht im Südosten zu finden.",al={"gimashis aufenthaltsort","wo ist der turm","schlucht im südosten"}},{q="Woher stammt draenethyst?",a="Draenethyst stammt von jenseits des Dunklen Portals.",al={"ursprung von draenethyst","stoff dunkles portal","woher stammt draenethyst"}}},fp="20,157,15.300.0,20.55.0,15.56.0,36.84.0,17.65.0,32.45.0"}
P.entries["quest:935"] = {n="Krone der Erde",s="In Teldrassil wird Mondbrunnenwasser gesammelt, um die Krankheit des Weltbaums zu lindern. Die Riten führen die Proben zu Erzdruide Fandral Hirschhaupt in Darnassus, wo die Sorge um einen ohne Segen gewachsenen Baum zunimmt.",h="In Teldrassil wird Mondbrunnenwasser gesammelt, um die Krankheit des Weltbaums zu lindern.",kw={"alexstrasza","die enklave des cenarius","corithras mondzorn","crown of the earth","darnassus","fandral hirschhaupt","mondbrunnen","nozdormu","teldrassil"},ang={["class:Druid"]="Als Druide bringt Ihr Mondbrunnenwasser vor Fandral Hirschhaupt, den Erzdruiden des Zirkels des Cenarius. Seine Gegenwart offenbart die tiefe politische und geistige Spaltung unter den Druiden während Malfurions Abwesenheit.",["faction:Alliance"]="Als Mitglied der Allianz erlebt Ihr Darnassus als eine Hauptstadt voller uralter Geheimnisse. Die verderbte Wildnis ringsum zeigt, dass Gefahr die Nachtelfen selbst auf ihrem heiligen Boden erreicht.",["race:NightElf"]="Als Nachtelf erkennt Ihr die Sorge, die unter Eurer neuen Heimat liegt. Teldrassil wurde aus Stolz ohne den Segen der Drachenaspekte gepflanzt, und seine Krankheit bedroht den Neuanfang Eures Volkes."},sec={{t="Ein fehlerhafter Ursprung",b="Teldrassil entstand nach dem Dritten Krieg, um den Nachtelfen eine neue Heimat zu geben und ihre verlorene Unsterblichkeit wiederherzustellen. Doch die Großen Aspekte Alexstrasza und Nozdormu verweigerten ihren Segen und wollten seine Erschaffung nicht gutheißen. Ohne ihren Schutz breitet sich Krankheit im Baum aus. Seltsame Kreaturen kommen aus seinen Ästen hervor, und einst friedliche Furbolgstämme verfallen dem Wahnsinn."},{t="Übergabe an den Erzdruiden",b="Corithras Mondzorn schickt junge Abenteurer aus, um Wasser aus Mondbrunnen in ganz Teldrassil zu sammeln. Er hofft, die Proben zu untersuchen und die Leiden des Baumes zu lindern. Sobald er sie in ein einziges Gefäß gegossen hat, schickt er Euch tief nach Darnassus, in die Enklave des Cenarius. Erzdruide Fandral Hirschhaupt hat Teldrassil geformt und sieht dessen wachsende Verderbnis als eine Bürde, die nur er bewältigen kann."}},faq={{q="Warum will Fandral Hirschhaupt dieses Mondbrunnenwasser?",a="Fandral Hirschhaupt will die Mondbrunnenproben, um die Verderbnis zu untersuchen und zu bekämpfen, die sich im Weltbaum ausbreitet. Er setzte sich für Teldrassils Pflanzung ein und trägt die Verantwortung dafür, Abhilfe gegen die seltsamen Bestien und wahnsinnigen Furbolgs in seiner Krone zu finden.",al={"fandral wasser zweck","warum braucht fandral das gefäß","wozu dient das wasser"}},{q="Warum wird Teldrassil von Verderbnis und wahnsinnigen Bestien geplagt?",a="Teldrassil leidet unter Verderbnis und seltsamen Bestien, weil er ohne den Segen von Alexstrasza the Life-Binder oder Nozdormu the Timeless gepflanzt wurde. Anders als dem uralten Weltbaum Nordrassil fehlt ihm der Schutz dieser ursprünglichen Drachenaspekte. Sein fehlerhaftes Wachstum lässt bösartige Auswüchse die Tiere und Furbolgs in der Umgebung entstellen.",al={"warum ist teldrassil krank","teldrassil verderbnis","warum sind furbolgs wahnsinnig"}},{q="Wo befindet sich Erzdruide Fandral Hirschhaupt?",a="Erzdruide Fandral Hirschhaupt befindet sich in der Enklave des Cenarius in Darnassus. Ihr findet ihn oben auf dem zentralen Druidenpavillon, von wo aus er die heiligen Haine der Enklave überblickt.",al={"wo ist fandral","fandral hirschhaupt aufenthaltsort","wie fandral finden"}},{q="Wer ist Corithras Mondzorn?",a="Corithras Mondzorn ist ein Nachtelf, der in Dolanaar stationiert ist. Er schickt junge Abenteurer aus, um Phiolen an Teldrassils Mondbrunnen zu füllen, gießt deren Wasser dann in ein einziges Gefäß und weist Boten an, es zu Erzdruide Hirschhaupt in Darnassus zu bringen.",al={"wer vergibt crown of the earth","corithras rolle","corithras mondzorn"}},{q="Was geschieht nach Abschluss dieser Quest?",a="Ihr übergebt das gefüllte Gefäß an Fandral Hirschhaupt und beendet damit die Hauptquestreihe von Crown of the Earth in Teldrassil. Er nimmt das Wasser knapp entgegen und wendet sich wieder den umfassenderen Bedrohungen für die Heimat der Nachtelfen zu.",al={"crown of the earth fortsetzung","was kommt nach crown of the earth sechs","nächste quest nach crown of the earth"}},{q="Warum ist Fandral Hirschhaupt beim Empfang des Gefäßes so abweisend?",a="Fandral Hirschhaupt ist stolz und ungeduldig. In Malfurion Sturmgrimms Abwesenheit trägt er die Bürde, den Zirkel des Cenarius zu führen. Er verachtet Rückschläge bei Verwaltungsaufgaben und langsame Boten, denn er glaubt, dass Teldrassils Überleben auf seinen Schultern ruht.",al={"warum ist fandral unhöflich","fandral persönlichkeit","ist fandral immer mürrisch"}}},fx={["01febe86"]={q="Warum schickt Euch Corithras Mondzorn, anstatt selbst zu gehen?",a="Corithras bleibt auf seinem Posten in Dolanaar, um dortige Angelegenheiten zu beaufsichtigen und die beunruhigenden Anomalien zu überwachen, die die unteren Zweige von Teldrassil stören. Ihr seid persönlich zu den verschiedenen Mondbrunnen gereist, um die Phiolen mit Wasser zu sammeln, und habt dabei Eure Ausdauer und Hingabe bewiesen. Indem er Euch das kombinierte Gefäß anvertraut, kann Corithras weiterhin Dolanaar bewachen und gleichzeitig sicherstellen, dass Fandral Hirschhaupt die Proben in Darnassus ohne weitere Verzögerung erhält.",al={"warum spieler zu fandral schicken","warum ich corithras","warum liefert corithras das gefäß nicht"}},d62362b9={q="Warum möchte Corithras Mondzorn, dass das Gefäß zu Fandral gebracht wird?",a="Corithras ist zutiefst besorgt über die wachsende Krankheit, die Teldrassil infiziert. Da der Weltenbaum ohne den lebenswichtigen Segen der Aspekte Alexstrasza und Nozdormu wuchs, sind seltsame Bestien aus dem Boden aufgestiegen und einst friedliche Furbolgs sind wahnsinnig geworden. Corithras glaubt, dass Erzdruide Fandral Hirschhaupt aktiv an einem Heilmittel forscht, um diese sich ausbreitende Verderbnis zu beseitigen, also kombiniert er dringend die Wasserproben, die Ihr über die Zweige hinweg gesammelt habt, und schickt Euch, um sie direkt nach Darnassus zu liefern.",al={"motiv von corithras","warum mondbrunnenwasser schicken","warum will corithras, dass dies getan wird"}}},fp="18,209,16.368.0,26.368.1,51.257.0,58.324.0,45.161.0,26.239.0,41.201.1,64.240.0"}
P.entries["quest:93552"] = {n="Harvesting Windstones",s="Im Thendalhain bittet Euch Dalia die Collector, rohe Windsteine zu sammeln, bevor ihre Kraft schwindet. Die uralten Elementarenergien der Insel Zephras nehmen langsam ab.",h="Im Thendalhain bittet Euch Dalia die Collector, rohe Windsteine zu sammeln, bevor ihre Kraft schwindet.",kw={"ankerpylone","dalia","dalia die collector","thendalhain","windelementare","windsteingruppe","windsteine","insel zephras"},ang={["class:Mage"]="Als Magier könnt Ihr die Elementarkraft in Windsteinen erkennen und sehen, wie zerbrechlich magische Ökosysteme werden, wenn ihre elementaren Quellen verschwinden.",["profession:Mining"]="Als Bergmann sammelt Ihr wertvolle Mineralien und Kristalle in der Wildnis der Insel Zephras, darunter rohe Windsteine."},sec={{t="Eine schwindende Insel",b="Die Insel Zephras schöpft noch immer aus Windmagie, doch ihre natürlichen Abwehrkräfte versagen. Vor Jahrhunderten verschwanden die Windelementare, die sich die Insel mit ihren Elfen teilten. Seitdem ist die Magie schwächer geworden, die das Land und seine großen Ankerpylone erhält. Deshalb brauchen die Bewohner des Thendalhains jeden Vorrat an roher Energie, den sie sichern können."},{t="Der Wert der Windsteine",b="Blaue kristalline Windsteine liegen im Thendalhain verstreut. Ihre spröden Hüllen bergen dichte Windmagie aus längst vergangenen Zeiten. Sie können die Insel nicht für immer erhalten, doch sie bieten ihren Elfen eine verlässliche Quelle arkaner Kraft. Das Sammeln roher Windsteingruppen bleibt für das tägliche Leben unerlässlich."}},faq={{q="Was sind Windsteine?",a="Windsteine sind blaue kristalline Ablagerungen, die im Thendalhain verstreut liegen. Sie bergen konzentrierte rohe Windenergie, die die Elfen der Insel Zephras als magischen Brennstoff sammeln.",al={"roher windstein","windsteingruppe","blaue kristalle"}},{q="Wer ist Dalia die Collector?",a="Dalia die Collector ist eine elfische Sammlerin, die im Thendalhain auf der Insel Zephras stationiert ist. Sie organisiert das Sammeln lebenswichtiger Rohstoffe, insbesondere Windsteine, um die schwindenden magischen Reserven der Insel zu stützen.",al={"dalia","dalia zephras","sammlerin dalia"}},{q="Warum schwindet die Magie auf der Insel Zephras?",a="Vor Jahrhunderten verschwanden die Windelementare, die Seite an Seite mit den einheimischen Elfen lebten. Seitdem ist die Magie der großen Ankerpylone, die die Insel erhält, langsam versiegt.",al={"zephras verliert magie","schwindende magie zephras","ankerpylone"}},{q="Wohin sind die Windelementare verschwunden?",a="Niemand weiß, wohin die Windelementare verschwunden sind. Sie verschwanden vor mehreren Jahrhunderten und ließen die Insel zurück, die seitdem langsam ihre verbliebenen Elementarreserven aufzehrt.",al={"vermisste elementare","wo sind die windelementare","elementare verschwunden"}},{q="Was sind die Ankerpylone?",a="Die großen Ankerpylone sind uralte Bauwerke auf der Insel Zephras, erfüllt von mächtiger Magie, die das Land erhält. Seit die Elementare verschwunden sind, ist diese erhaltende Kraft allmählich schwächer geworden.",al={"große ankerpylone","geschichte der ankerpylone"}},{q="Wo findet Ihr rohe Windsteine?",a="Rohe Windsteine liegen im gesamten Thendalhain auf der Insel Zephras verstreut, wo sie als leuchtend blaue Kristallformationen hervortreten.",al={"windstein fundort","thendalhain kristalle"}}},fx={["0a83a06c"]={q="Warum möchte Dalia, The Collector, Windsteincluster haben?",a="Dalia sucht nach Windsteinclustern, weil die Insel Zephras auf deren magische Kraft angewiesen ist, um zu bestehen. Seit die Windelementare vor Jahrhunderten verschwanden, schwindet die erhaltende Magie, die einst die Insel nährte. Für die dortigen Elfen, deren Leben und Kultur tief mit arkaner Energie verwoben bleiben, stellen diese kristallisierten Winde eine lebenswichtige und zuverlässige Energiequelle dar, um zu ersetzen, was die versagenden Ankerpylonen nicht mehr liefern können.",al={"warum dalia windsteine will","dalia collector beweggrund","warum windsteine ernten"}},["33ac4299"]={q="Wofür werden Windsteincluster verwendet?",a="Windsteincluster enthalten die rohe, konzentrierte Energie der Winde selbst. Da die alten magischen Ankerpylonen auf der Insel Zephras mit der Zeit ihre Wirkung verlieren, nutzen die Bewohner der Insel diese kristallisierten Cluster als zuverlässige alternative Energiequelle, um ihre Gemeinschaft zu erhalten und ihre essenzielle Verbindung zur magischen Energie aufrechtzuerhalten.",al={"verwendung von windsteinclustern","wofür sind windsteincluster","warum windsteincluster"}}},fp="21,166,15.327.0,23.276.0,20.168.0,27.214.0,40.178.0,33.152.0,27.191.0,33.122.0"}
P.entries["quest:93644"] = {n="Tattered Journal",s="Ein beschädigtes Tagebuch, nahe Shen'dralas gefunden, weist Euch auf seinen Verfasser Evenshade hin. Die fehlenden Worte könnten ihm noch immer wichtig sein.",h="Ein beschädigtes Tagebuch, nahe Shen'dralas gefunden, weist Euch auf seinen Verfasser Evenshade hin.",kw={"beschädigtes tagebuch","evenshade","verlorenes tagebuch","mordent","tagebuch wiederherstellen","shen'dralas","zerfleddertes tagebuch"},sec={{t="Ein Name bleibt",b="Nahe Shen'dralas bieten Euch die abgenutzten Seiten eines Tagebuchs kaum Lesestoff. Zwischen den verschwommenen Buchstaben ist ein Nachname deutlich zu erkennen: Evenshade. Der Verfasser könnte irgendwo in der Nähe sein, und die verbliebenen Worte im Tagebuch sind die einzige Spur."},{t="Das Schicksal des Tagebuchs",b="Mordent erkennt das Tagebuch als sein Eigentum, obwohl Jahrhunderte vergangen sind, seit er es verloren hat. Die Schrift ist verschwunden, doch er erinnert sich an den Inhalt und behält dieses Wissen für sich. Er erlaubt Euch, das Tagebuch wiederherzustellen, falls seine Seiten erhalten geblieben sind."}},faq={{q="Wo wurde das Tagebuch gefunden?",a="Das Tagebuch wurde nahe Shen'dralas gefunden.",al={"wo tagebuch","fundort des zerfledderten tagebuchs"}},{q="Wer hat das Tagebuch verfasst?",a="Der verbliebene Name im Tagebuch weist Evenshade als Verfasser aus.",al={"verfasser des tagebuchs","evenshade tagebuch"}},{q="Warum nach Evenshade suchen?",a="Das Tagebuch trägt den Nachnamen Evenshade, und sein Verfasser könnte sich irgendwo in Shen'dralas aufhalten.",al={"evenshade finden","nachname im tagebuch"}},{q="Könnt Ihr das Tagebuch lesen?",a="Das meiste Wissen im Tagebuch ist verloren, und die verbliebenen Buchstaben sind schwer zu erkennen.",al={"tagebuch unleserlich","inhalt des tagebuchs"}},{q="Was sagt Mordent über das Tagebuch?",a="Mordent erkennt darin sein verlorenes Tagebuch, sagt aber, dass die Schrift verschwunden ist.",al={"mordent tagebuch","wem gehört das tagebuch"}},{q="Wird Mordent erzählen, was darin stand?",a="Mordent erinnert sich an den Inhalt des Tagebuchs, möchte aber nicht laut darüber sprechen.",al={"tagebuchinhalt","mordents geheimnis"}}},fp="16,124,14.231.0,18.250.1,28.39.0,22.71.0,23.88.0,25.96.0,40.72.0,36.85.0"}
P.entries["quest:93663"] = {n="Lost in Transit",s="Dar bittet Euch, einen vermissten Goblinboten und seine für den Sicheren Hafen bestimmte Lieferung zu finden. Sein Ruf als Händler steht auf dem Spiel.",h="Dar bittet Euch, einen vermissten Goblinboten und seine für den Sicheren Hafen bestimmte Lieferung zu finden.",kw={"krokilisk","dar","draenei","goblinbote","der sichere hafen","auf dem transport verschollen","lieferung","handel"},sec={{t="Eine vermisste Lieferung",b="Dar tauscht zusätzliche Vorräte mit den Draenei des Sicheren Hafens gegen einen Teil ihres Fangs. Nun ist sein Goblinbote mit einer Lieferung nicht zurückgekehrt. Dar befürchtet, dass ein Krokilisk ihn getötet haben könnte, doch die Waren wiederzufinden ist wichtig für sein Geschäft. Ihr sollt in der Nähe der Gewässer entlang der Straße suchen und die Lieferung zum Sicheren Hafen bringen."}},faq={{q="Wer ist Dar?",a="Dar tauscht zusätzliche Vorräte mit den Draenei des Sicheren Hafens gegen einen Teil ihres Fangs.",al={"dar","wer schickte die lieferung","goblinhändler"}},{q="Wer ist der vermisste Bote?",a="Dar schickte einen Goblinboten mit seiner neuesten Lieferung los, doch der Bote kehrte nie zurück.",al={"vermisster goblin","wo ist der bote","goblinbote"}},{q="Wohin sollte die Lieferung gebracht werden?",a="Die Lieferung war für die Draenei im Sicheren Hafen bestimmt.",al={"ziel der lieferung","wohin damit","lieferung zum sicheren hafen"}},{q="Warum muss Dar die Lieferung wiederfinden lassen?",a="Dar sagt, sein Ruf als Händler stehe auf dem Spiel, wenn die Lieferung nicht gefunden und zugestellt wird.",al={"warum die lieferung finden","dars ruf","warum ist das wichtig"}},{q="Wo soll ich nach dem Boten suchen?",a="Dar bittet Euch, in der Nähe der Gewässer entlang der Straße nachzusehen.",al={"wo suchen","aufenthaltsort des boten","auf dem transport verschollen wo"}}},fp="15,130,18.328.0,11.84.0,27.83.0,29.56.0,37.88.0,36.53.0"}
P.entries["quest:93680"] = {n="Schlüssel zur Stadt",s="Wordeen sucht einen Weg nach Dalaran, das nun vor der Haustür der Dark Lady wiederaufgebaut wurde.",h="Wordeen sucht einen Weg nach Dalaran, das nun vor der Haustür der Dark Lady wiederaufgebaut wurde.",kw={"archimonde","brennende legion","dalaran","schmutziger schlüssel","kirin tor","kanalschlüssel","tarrens mühle","wordeen voidglare"},sec={{t="Die wiederaufgebaute Stadt",b="In Tarrens Mühle will Magus Wordeen Voidglare mehr über die Kirin Tor erfahren. Ihre Stadt Dalaran fiel der dämonischen Brennenden Legion durch einen einzigen Schlag des Erzdämons Archimonde zum Opfer. Die überlebenden Magier wurden zu heimatlosen Wanderern. Nun haben sie Dalaran direkt vor der Haustür der Dark Lady wiederaufgebaut.\n\nWordeen schickt Euch los, um ihre Lager zu durchsuchen. Er hofft, dass Ihr einen uralten Folianten, ein geheimes Relikt oder etwas anderes findet, das der Horde unbemerkt Zugang zur Stadt verschafft. Ihr bringt einen verdreckten Schlüssel zur Kanalisation von Dalaran zurück."},{t="Wordeens Antwort",b="Wordeen sieht den Kanalisationsschlüssel und ist dankbar, dass jemand anderes ihn benutzen wird. Bevor er gefahrlos benutzt werden kann, gibt es noch Arbeit."}},faq={{q="Wer erteilt den Auftrag für Key to the City?",a="Magus Wordeen Voidglare in Tarrens Mühle bittet Euch um Hilfe.",al={"wer vergibt key to the city","key to the city questgeber","wo beginnt key to the city"}},{q="Warum interessiert sich die Horde für Dalaran?",a="Die Kirin Tor haben Dalaran vor der Haustür der Dark Lady wiederaufgebaut, nachdem Archimonde ihre Stadt zerstört hatte. Wordeen will mehr über sie erfahren und einen Weg finden, wie die Horde unbemerkt hineingelangen kann.",al={"warum dalaran","warum dalaran beobachten","was machen die magier"}},{q="Welcher Gegenstand soll gefunden werden?",a="Ihr werdet losgeschickt, um die Lager der Kirin Tor nach einem verdreckten Schlüssel zur Kanalisation von Dalaran zu durchsuchen.",al={"was besorge ich für wordeen","was ist der schlüssel","key to the city gegenstand"}}},fp="15,76,16.518.0,16.120.1,42.56.0,39.191.0,31.73.0"}
P.entries["quest:937"] = {n="Die verzauberte Lichtung",s="Im Nordwesten Teldrassils bedrohen Harpyien der Bloodfeather die Lichtung des Orakels und ihren uralten Oracle Tree. Nachdem sie einen Läufer auf dem Weg nach Darnassus getötet haben, fordert Schildwache Arynia Wolkenbruch, ihre Nester auszudünnen und ihre Gürtel als Beweis zurückzubringen.",h="Im Nordwesten Teldrassils bedrohen Harpyien der Bloodfeather die Lichtung des Orakels und ihren uralten...",kw={"arynia wolkenbruch","bloodfeather","darnassus","harpyien","die lichtung des orakels","oracle tree","schildwache","teldrassil","die verzauberte lichtung"},ang={["class:Druid"]="Als Druide bringt Ihr empfindungsfähigen Urtumen große Ehrfurcht entgegen. Wenn Ihr die Harpyien beseitigt, die den Oracle Tree bedrohen, helft Ihr, das natürliche Gleichgewicht der Lichtung zu schützen.",["faction:Alliance"]="Als Mitglied der Allianz stärkt Ihr die Bande zur Führung der Nachtelfen im nahen Darnassus, wenn Ihr den Sentinels helft, Teldrassils heilige Haine zu sichern.",["race:NightElf"]="Als Nachtelf habt Ihr die feierliche Pflicht, die uralten Geister des Weltbaums zu verteidigen und die Sentinels vor Harpyienangriffen zu schützen."},sec={{t="Eine belagerte Lichtung",b="Schildwache Arynia Wolkenbruch bewacht die Lichtung des Orakels mit einer Eskorte von Kriegern. In ihrem Herzen steht der gewaltige Oracle Tree, ein Urtum, das zwischen Teldrassils Ästen wurzelt. Harpyien der Bloodfeather haben sich im umliegenden Blätterdach ausgebreitet. Sie nisten in seinen Höhlungen und bedrohen jeden, der sich nähert."},{t="Verbindung nach Darnassus abgerissen",b="Ein Läufer mit einem dringenden Bericht vom Oracle Tree erreicht Darnassus nie. Harpyien der Bloodfeather überfallen und töten den Boten, bevor er die Lichtung verlassen kann. Arynia fordert Euch auf, ihren Schwarm auszudünnen und Blutfedergürtel als Beweis dafür zurückzubringen, dass ihre Nester geschwächt wurden."},{t="Ein Ruf des Baumes",b="Während die nahen Nester ausgedünnt werden, sendet der Oracle Tree ein Stück seiner verzauberten Rinde. Das Urtum sucht einen Abgesandten, der seine Botschaft zur hohen Führung der Kaldorei trägt."}},faq={{q="Warum greifen Harpyien die Lichtung des Orakels an?",a="Harpyien der Bloodfeather nisten im gesamten Norden Teldrassils und haben den Oracle Tree umzingelt. Sie verteidigen ihre Nistplätze erbittert und greifen jeden an, der zur heiligen Lichtung reist oder sie verlässt.",al={"harpyien in der lichtung des orakels","warum greifen bloodfeather an","oracle tree harpyien"}},{q="Wer ist Schildwache Arynia Wolkenbruch?",a="Schildwache Arynia Wolkenbruch ist eine Offizierin, die mit einer kleinen Vorhut in der Lichtung des Orakels stationiert ist. Sie schützt den Oracle Tree vor den nahen Harpyien und bemüht sich, den Kontakt zu Darnassus wiederherzustellen.",al={"arynia wolkenbruch","wer vergibt die verzauberte lichtung","wolkenbruch hintergrundgeschichte"}},{q="Was geschah mit dem nach Darnassus entsandten Läufer?",a="Harpyien der Bloodfeather überfielen und töteten den Läufer, der einen Bericht vom Oracle Tree nach Darnassus trug. Sie schlugen auf den Pfaden der Lichtung zu, bevor der Bote Sicherheit erreichte.",al={"oracle tree bote","toter läufer darnassus"}},{q="Was ist der Oracle Tree?",a="Der Oracle Tree ist ein gewaltiges, empfindungsfähiges Urtum, das in der Lichtung des Orakels wurzelt. Er wacht über die Äste des Weltbaums und sendet Weisheit und Warnungen an die Führung der Nachtelfen.",al={"oracle tree teldrassil","wer ist der oracle tree"}},{q="Welchen Beweis verlangt Schildwache Wolkenbruch?",a="Schildwache Wolkenbruch bittet Euch, sechs Blutfedergürtel von erschlagenen Harpyien zurückzubringen. Sie beweisen, dass die Nistplätze rund um die Lichtung ausgedünnt wurden.",al={"blutfedergürtel quest","wie viele gürtel","quest beweis"}},{q="Was geschieht nach dem Ausdünnen der Harpyien?",a="Sobald die Harpyien in der Nähe ausgedünnt sind, wirft der Oracle Tree ein Stück seiner Rinde ab. Ihr könnt die lange verzögerte Botschaft des Urtums in Richtung Darnassus tragen.",al={"nächste quest nach der verzauberten lichtung","was tut der oracle tree als nächstes"}}},fx={["2b035f45"]={q="Warum möchte Schildwache Arynia Wolkenbruch, dass dies getan wird?",a="Schildwache Arynia Wolkenbruch wurde mit einer kleinen Einheit von Schildwachen entsandt, um die Lichtung des Orakels zu verteidigen. Harpyien haben sich auf der gesamten Lichtung eingenistet, die Verteidiger eingekesselt und sogar einen Kurier abgeschlachtet, der mit wichtigen Berichten nach Darnassus geschickt wurde. Arynia kann ihren Verteidigungsposten nicht unbewacht lassen, also benötigt sie einen Abenteurer, der direkt gegen die Nester vorgeht und den Schwarm zurückdrängt, bevor die Lichtung überrannt wird.",al={"warum die harpyien töten","arynia wolkenbruch beweggrund","warum den baum des orakels schützen"}},["164cdda3"]={q="Wer sind die Blutfederharpyien, die die Lichtung bedrohen?",a="Die Blutfederharpyien sind bösartige, vogelartige Raubtiere, die sich in den nordwestlichen Ausläufern von Teldrassil niedergelassen haben. Aggressiv und territorial, haben sie Nester um die Lichtung des Orakels errichtet, die Kommunikation mit Darnassus abgeschnitten und versuchen, die Nachtelfen-Beschützer, die den uralten Baum bewachen, zu vertreiben oder abzuschlachten.",al={"wer sind die harpyien","blutfederharpyien teldrassil","warum sind harpyien hier"}},["3f052dc4"]={q="Warum kann Schildwache Wolkenbruch nicht selbst gegen die Harpyien vorgehen?",a="Schildwache Arynia Wolkenbruch befehligt nur eine kleine Einheit von Schildwachen, die am Baum des Orakels stationiert ist. Da ihr Bote bereits tot ist und Harpyien die Stellung einkesseln, müssen ihre verbleibenden Truppen am Boden bleiben, um den heiligen Baum vor Hinterhalten zu schützen. Um den Angriff in die Brutstätten der Harpyien zu tragen, bedarf es fähiger, ungebundener Reisender, die bereit sind, sich in feindselige Nester zu wagen.",al={"warum braucht arynia meine hilfe","warum können die schildwachen die harpyien nicht töten","warum ich verzauberte lichtung"}}},fp="19,252,19.296.0,26.290.0,23.172.1,43.181.0,35.187.0,46.175.0,24.178.0,45.149.0,39.146.1"}
P.entries["quest:93735"] = {n="The Broken Construct",s="In Valanaar bedroht ein beschädigtes Konstrukt eines der letzten funktionierenden Relikte der Insel. Riaani Nightwind ist zum westlichen Rand der Stadt gegangen, um es zu untersuchen. Die alten Maschinen haben eine Geschichte, die bis zu den Geistern des Windes zurückreicht.",h="In Valanaar bedroht ein beschädigtes Konstrukt eines der letzten funktionierenden Relikte der Insel.",kw={"handwerker","broken construct","konstrukt","riaani nightwind","valanaar","windgeister","windformer"},ang={["class:Mage"]="Als Magier dürften Euch die empfindlichen magischen Vorrichtungen, die die Windformer pflegen, besonders interessieren.",["class:Shaman"]="Als Schamane könnt Ihr in den Konstrukten, die die Geister des Windes vor ihrem Fortgang schenkten, ihren alten Bund mit den Inselbewohnern erkennen.",["profession:Engineering"]="Als Ingenieur könnt Ihr die mechanischen und magischen Herausforderungen ermessen, denen Handwerker gegenüberstehen, wenn sie uralte verzauberte Konstrukte ohne deren ursprüngliche Geisterpatrone funktionsfähig halten."},sec={{t="Gaben der Windgeister",b="Vor langer Zeit schenkten die Geister des Windes den Bewohnern der Insel magische Instrumente, Vorrichtungen und belebte Konstrukte. Über Generationen hinweg kümmerten sich die Windformer um diese Gaben. Dann zogen die Geister fort, und ihr Beistand endete. Die meisten Schöpfungen verfielen. Nur eine Handvoll funktioniert noch."},{t="Eine Krise in Valanaar",b="Eines der letzten funktionierenden Konstrukte Valanaars wurde beschädigt. Sein Verlust würde das schwindende Erbe der Insel weiter schmälern. Die Handwerkerin Riaani Nightwind wurde an den westlichen Rand der Stadt entsandt, um die Maschine zu untersuchen und eine Reparatur zu versuchen. Diese uralten Vorrichtungen sind empfindlich, und sie braucht Hilfe."}},faq={{q="Wer sind die Windformer?",a="Die Windformer sind einheimische Hüter, denen die Pflege der magischen Instrumente, Vorrichtungen und Konstrukte anvertraut wurde, die die Geister des Windes schenkten. Seit die Geister fortgezogen sind, arbeiten sie daran, die wenigen noch funktionierenden Relikte zu bewahren.",al={"wer sind die windformer","geschichte der windformer","was tun windformer"}},{q="Woher stammen die magischen Konstrukte?",a="Die Geister des Windes schenkten den Inselbewohnern magische Konstrukte, Instrumente und Vorrichtungen. Seit die Geister fortgezogen sind, funktionieren nur noch sehr wenige dieser Schöpfungen.",al={"wer hat die konstrukte gebaut","ursprung der konstrukte","woher stammen die konstrukte"}},{q="Wer ist Riaani Nightwind?",a="Riaani Nightwind ist eine Handwerkerin, die an Valanaars westlichen Rand entsandt wurde, um eines der wenigen funktionierenden Konstrukte der Stadt nach einer Beschädigung zu untersuchen und zu reparieren.",al={"wer ist riaani nightwind","riaani aufenthaltsort","handwerker in valanaar"}},{q="Warum sind die meisten Konstrukte der Insel kaputt?",a="Die meisten Konstrukte der Insel verfielen, nachdem die Geister des Windes fortgezogen waren und ihr uralter Beistand geendet hatte. Nur eine Handvoll ist noch funktionsfähig.",al={"warum sind die konstrukte kaputt","warum versagten die konstrukte","fortgang der windgeister"}},{q="Welche Verbindung hat Valanaar zu den Konstrukten?",a="In Valanaar befinden sich einige der letzten funktionierenden Konstrukte der Insel, die einst die Windgeister schenkten. Eines wurde kürzlich am westlichen Ende der Stadt beschädigt, und Riaani Nightwind wurde entsandt, um es zu untersuchen und zu reparieren.",al={"was ist valanaar","stadt valanaar","wo ist das konstrukt"}},{q="Was ist bei The Broken Construct zu tun?",a="Ihr werdet gebeten, an Valanaars westlichen Rand zu reisen, den Handwerker Riaani Nightwind zu finden und ihm bei der Reparatur des beschädigten Konstrukts zu helfen.",al={"broken construct questziel","was tun bei broken construct","wohin für broken construct"}}},fp="20,230,25.291.0,20.290.0,24.236.0,43.173.0,24.151.0,47.167.0,48.204.0,47.127.0"}
P.entries["quest:93736"] = {n="Unwelcome Spirits",s="Die Windformer suchen die Geister des Windes, die sich ihrer Reichweite entzogen haben. Nun erscheinen Hollows im Schattenwindwald, und der Orden sammelt ihre Essenzen, um zu erfahren, was die wahren Geister vertrieben hat.",h="Die Windformer suchen die Geister des Windes, die sich ihrer Reichweite entzogen haben.",kw={"hollows","schattenwindwald","geisterchen","unwelcome spirits","wind hollow essence","wind-hollows","windgeister","windformer"},ang={["class:Shaman"]="Für jene, die mit den Elementen Zwiesprache halten, deuten der Fortgang der natürlichen Windgeister und die Ankunft der Hollows auf eine tiefe Störung des örtlichen Gleichgewichts der Luft hin."},sec={{t="Die verschwundenen Geister",b="Die Windformer haben die Verbindung zu den Geistern des Windes verloren. Sie wollen erfahren, warum die Geister fortgingen und was sie zurückbringen könnte. Ihr Fortgang hat eine Leere in der örtlichen elementaren Atmosphäre hinterlassen."},{t="Schatten in Shadowgale",b="Nachdem die Windgeister fortgegangen waren, erschienen im Schattenwindwald im Norden seltsame Geisterchen, die Hollows genannt werden. Die Windformer hatten sie vor dem Verschwinden der Geister nicht gekannt. Die Hollows scheinen mit der Abwesenheit der Geister verbunden zu sein, und ihre Essenzen könnten helfen, ihr Wesen zu ergründen."}},faq={{q="Wer sind die Windformer?",a="Die Windformer sind ein Orden, der ergründen will, warum die Geister des Windes ihn verlassen haben und wie er sie zurückbringen kann. Ihre Nachforschungen konzentrieren sich nun auf seltsame Vorkommnisse, die nach dem Verschwinden der Geister begannen.",al={"wer sind die windformer","windformer fraktion","was wollen die windformer"}},{q="Was sind die Hollows?",a="Hollows sind seltsame Windgeisterchen, die im Schattenwindwald erschienen, nachdem die ursprünglichen Windgeister fortgegangen waren. Ihr Ursprung und ihr Wesen bleiben unbekannt, weshalb Gelehrte ihre Essenzen zu Forschungszwecken sammeln.",al={"was sind hollows","wind-hollow hintergrund","hollow-geisterchen"}},{q="Wo liegt der Schattenwindwald?",a="Der Schattenwindwald liegt im Norden. Dort sind seltsame Wind-Hollows erschienen, seit die Elementargeister der Gegend fortgegangen sind.",al={"wo liegt der schattenwindwald","shadowgale lage"}},{q="Warum gingen die Windgeister fort?",a="Niemand weiß, warum die Geister des Windes verschwanden. Die Windformer suchen nach der Ursache und hoffen, die Zwiesprache mit ihnen wiederherzustellen.",al={"warum gingen die windgeister fort","wohin gingen die geister"}},{q="Warum werden Wind Hollow Essences gesammelt?",a="Die Windformer sammeln Essenzen zerstreuter Hollows zu Forschungszwecken. Sie hoffen, dass diese Überreste offenbaren, was die Wesen nach dem Fortgang der Geister ins Dasein rief.",al={"warum hollow-essenzen sammeln","wind hollow essence zweck"}},{q="Gelten die Hollows als feindselig?",a="Die Hollows sind unerwünschte Eindringlinge, die erschienen, als die natürlichen Geister fort waren. Ihre Ausbreitung im Schattenwindwald erfordert ihre Zerstreuung, damit die Region geschützt wird und Proben gesammelt werden können.",al={"sind hollows gefährlich","bedrohung durch hollow-geisterchen"}}},fp="17,189,20.204.0,21.273.0,24.207.0,21.195.0,27.122.0,31.122.0,44.168.0,35.202.0"}
P.entries["quest:93737"] = {n="The Broken Construct",s="Ayessa hat Euch geschickt, um Riaani Nightwind mit einem funktionsunfähigen Konstrukt zu helfen. Hört Euch seine Pläne an und erfahrt, was er erledigt haben muss, um die Maschine wieder instand zu setzen.",h="Ayessa hat Euch geschickt, um Riaani Nightwind mit einem funktionsunfähigen Konstrukt zu helfen.",kw={"ayessa","defektes konstrukt","konstrukt","ingenieurskunst","riaani nightwind","the broken construct"},ang={["profession:Engineering"]="Als Ingenieur kennt Ihr den Frust bei der Fehlersuche an einem Konstrukt mit komplizierten mechanischen Teilen."},sec={{t="Dem Handwerker beistehen",b="Ayessa schickt Euch, um Riaani Nightwind mit einem beschädigten Konstrukt zu helfen. Er steckt tief zwischen dessen Bauteilen und sucht nach der Ursache des Problems. Von Eurer Ankunft überrascht, bezweifelt Riaani, dass ein ungeschulter Reisender filigrane mechanische Arbeiten bewältigen kann. Sobald er herausgeklettert ist, erklärt er sich bereit, die nötigen Arbeiten zu erläutern."},{t="Fehlersuche an Maschinen",b="Ein Konstrukt ist auf präzise Montage und sorgfältige Kalibrierung angewiesen. Wenn es ausfällt, steht seinem Ingenieur eine Menge Arbeit bevor. Riaani Nightwind steckt bis zu den Schultern in mechanischen Teilen und braucht ein weiteres Paar Hände, um Materialien zu sammeln oder die Maschine im Einsatz zu testen. Hört Euch seine Einweisung an, um zu erfahren, wie Ihr helfen könnt, das reglose Konstrukt wieder funktionstüchtig zu machen."}},faq={{q="Wer ist Riaani Nightwind?",a="Riaani Nightwind ist ein Tüftler, der an einem funktionsunfähigen mechanischen Konstrukt arbeitet. Er zweifelt an Neuankömmlingen, die ihm zur Hilfe geschickt werden, braucht aber Unterstützung, um die Maschine wieder zum Laufen zu bringen.",al={"wer ist riaani nightwind","riaani","konstruktmechaniker"}},{q="Wer ist Ayessa?",a="Ayessa ist eine Bekannte, die Reisende zu Riaani Nightwind schickt, um ihm bei seinen mechanischen Problemen zu helfen. Ihre Empfehlung bewegt ihn dazu, in Betracht zu ziehen, einem Neuankömmling Arbeit zu geben.",al={"wer schickt reisende zu riaani","ayessa","wer ist ayessa"}},{q="Was ist das defekte Konstrukt?",a="Das defekte Konstrukt ist eine mechanische Schöpfung, die nicht mehr richtig funktioniert. Riaani Nightwind steckt darin und sucht nach den benötigten Teilen und den Arbeiten, die für die Reparatur nötig sind.",al={"was ist das konstrukt","welche maschine repariert riaani","defekte maschine"}},{q="Wobei braucht Riaani Hilfe?",a="Ayessa hat Euch geschickt, um Riaani zu helfen. Er braucht Zeit, um aus dem Innenleben des Konstrukts herauszuklettern und zu erklären, welche Hilfe er benötigt.",al={"was soll für riaani erledigt werden","aufgabe zum defekten konstrukt","riaani helfen"}},{q="Warum steht Riaani Eurer Hilfe skeptisch gegenüber?",a="Riaani ist in technische Arbeiten vertieft und wird ungeduldig, wenn man ihn unterbricht. Er betrachtet die meisten Abenteurer als ungeschulte Anfänger, bis sie zeigen, dass sie mechanische Anweisungen befolgen können.",al={"warum nennt riaani abenteurer anfänger","ist riaani unhöflich","riaanis dialog"}}},fp="20,141,21.300.0,25.356.0,24.163.0,14.164.0,29.165.0,32.128.0,37.171.0"}
P.entries["quest:93738"] = {n="The Broken Construct",s="Ein Windformer bittet Euch, Ayessa Dawnsinger zu berichten, was Ihr über das beschädigte Konstrukt erfahren habt. Die Arbeit des Hohen Ordens mit Windgeistmagie hat Besorgnis erregt.",h="Ein Windformer bittet Euch, Ayessa Dawnsinger zu berichten, was Ihr über das beschädigte Konstrukt erfahren...",kw={"ayessa dawnsinger","belathaan","beschädigtes konstrukt","der hohe orden","valanaar","valennia stormfist","windgeister","windformer"},sec={{t="Zurück zu Ayessa",b="Berichtet Ayessa Dawnsinger in Valanaar, was Ihr erfahren habt. Der Hohe Orden hat mit seinen Experimenten mit Windgeistmagie die Geduld der Windformer strapaziert. Er hat sich auch mit Wissen befasst, das den Windformern vorbehalten ist. Ayessa kann entscheiden, was als Nächstes geschehen soll."},{t="Ein beunruhigender Name",b="Ayessa glaubt, dass der Hohe Orden für den Zusammenbruch des Konstrukts verantwortlich war. Sie kennt Belathaan als Cousin von Valennia Stormfist und sagt, seine Mutter habe den Windformern angehört. Seine Beteiligung enttäuscht sie. Sie braucht Zeit zum Nachdenken."}},faq={{q="Wem soll ich Bericht erstatten?",a="Berichtet Ayessa Dawnsinger in Valanaar, was Ihr erfahren habt.",al={"ayessa berichten","wo bericht erstatten","ayessa daw sinsinger"}},{q="Warum sind die Windformer wegen des Hohen Ordens besorgt?",a="Der Hohe Orden hat mit Windgeistmagie experimentiert und sich in Wissen eingemischt, das den Windformern vorbehalten ist, obwohl ihm dies verboten ist.",al={"ärger mit dem hohen orden","warum windformer wütend","hoher orden windmagie"}},{q="Was ist mit dem Konstrukt geschehen?",a="Ayessa glaubt, dass der Hohe Orden für den Zusammenbruch des Konstrukts verantwortlich war.",al={"beschädigtes konstrukt","konstrukt zusammengebrochen","warum konstrukt beschädigt"}},{q="Wer ist Belathaan?",a="Belathaan ist der Cousin von Valennia Stormfist, und seine Mutter gehörte den Windformern an.",al={"belathaan","belathaans familie","belathaans cousin"}}},fp="20,158,16.251.0,16.239.1,23.57.0,55.140.0,31.79.0,17.76.0"}
P.entries["quest:93739"] = {n="Exploring the Horde",s="Von Grommash Hold aus reist Ihr zu den Anführern, die die Horde lenken. Die Reise führt Euch von Orgrimmar zu den Dunkelspeertrollen, den Tauren und den Verlassenen.",h="Von Grommash Hold aus reist Ihr zu den Anführern, die die Horde lenken.",kw={"cairne bluthuf","dunkelspeer","exploring the horde","verlassene","grommash hold","nazgrel","orgrimmar","sylvanas windläufer","tauren","donnerfels","unterstadt","vol'jin"},ang={["faction:Horde"]="Ihr begegnet den Anführern, die die Horde in Kalimdor und den Östlichen Königreichen lenken.",["race:Orc"]="Nazgrel berät Kriegshäuptling Thrall in Orgrimmar und weist jungen Orc-Kriegern den Weg, die sich einen Namen machen.",["race:Tauren"]="Die Begegnung mit Oberhäuptling Cairne Bluthuf in Donnerfels führt Euch zum spirituellen Herzen und zur Stärke der Tauren.",["race:Troll"]="Das Gespräch mit Schattenjäger Vol'jin stärkt das Band zwischen dem Stamm der Dunkelspeer und seinen Orc-Verbündeten im Tal der Geister.",["race:Undead"]="Die Reise nach Unterstadt zur Dunklen Fürstin Sylvanas Windläufer zeigt Euch das strategische, wenn auch angespannte Bündnis der Verlassenen mit Kalimdors Horde."},sec={{t="Befehle aus Grommash Hold",b="Nazgrel schickt Euch von Grommash Hold hinaus in die weiten Lande der Horde. Die Festung steht im Herzen von Orgrimmar, wo Nazgrel und der Rat des Kriegshäuptlings die militärischen Angelegenheiten überwachen. Ihr lasst die roten Schluchten Durotars hinter Euch, um zu erfahren, wie weit die Völker unter dem roten Banner miteinander verbunden sind."},{t="Ein Bündnis zum Überleben",b="Ihr begegnet den Anführern der verbündeten Völker der Horde: Schattenjäger Vol'jin von den Dunkelspeertrollen, Oberhäuptling Cairne Bluthuf von den Tauren und Fürstin Sylvanas Windläufer, Königin der Verlassenen. Im persönlichen Gespräch mit ihnen erkennt Ihr die Bande zwischen Kalimdor und Lordaeron, über das große Meer hinweg, wo die Seuche das Land gezeichnet hat."}},faq={{q="Was ist die Quest Exploring the Horde?",a="Ihr meldet Euch bei Nazgrel in Grommash Hold und reist dann durch die Lande der Horde, um Vol'jin, Cairne Bluthuf und Fürstin Sylvanas Windläufer zu treffen.",al={"was ist exploring the horde","quest exploring the horde","was geschieht in dieser quest"}},{q="Wer ist Nazgrel und wo befindet er sich?",a="Nazgrel ist ein Orc-Krieger und ein vertrauter Leutnant in Grommash Hold in Orgrimmar. Er berät die Horde und weist aufstrebenden Champions den Weg zu Befehlshabern und Verbündeten in ihren Landen.",al={"wer ist nazgrel","wo ist nazgrel","nazgrels rolle"}},{q="Zu welchen Anführern werdet Ihr geschickt?",a="Ihr trefft Schattenjäger Vol'jin von den Dunkelspeertrollen, Oberhäuptling Cairne Bluthuf von den Tauren in Mulgore und Fürstin Sylvanas Windläufer, die Banshee Queen der Verlassenen in Unterstadt.",al={"mit welchen anführern sprechen","zu besuchende anführer","mit wem sprechen"}},{q="Warum sollen Abenteurer jeden Anführer besuchen?",a="Der gemeinsame Überlebenskampf und brüderliche Bündnisse verbinden die Völker der Horde. Die Begegnungen mit Vol'jin, Cairne und Sylvanas zeigen Euch die Reichweite des Bündnisses, von Durotar und Mulgore bis nach Lordaeron.",al={"warum alle anführer besuchen","zweck der besuche bei hordenanführern","grund für die diplomatie"}},{q="Wo sind die einzelnen Anführer zu finden?",a="Vol'jin befindet sich bei den Dunkelspeertrollen im Tal der Geister in Orgrimmar. Cairne Bluthuf hält auf den Tafelbergen von Donnerfels in Mulgore Hof. Fürstin Sylvanas Windläufer residiert im Royal Quarter von Unterstadt unter den Ruinen von Lordaeron.",al={"wo befinden sich die anführer","aufenthaltsorte der anführer","wie voljin cairne sylvanas finden"}},{q="Was ist Grommash Hold?",a="Grommash Hold ist die zentrale Festung im Tal der Stärke in Orgrimmar. Sie ist nach Grom Hellscream benannt, und hier überwachen Kriegshäuptling Thrall und seine Berater, darunter Nazgrel, die Angelegenheiten der Horde.",al={"was ist grommash hold","wo ist grommash hold","festung in orgrimmar"}}},fp="19,164,25.281.0,23.338.0,38.134.0,39.179.0,35.195.0,52.182.0,39.242.0,22.187.0"}
P.entries["quest:93740"] = {n="Blood for Blood",s="Mehrere Novizen der Windformer liegen tot im Hochland, und die Windformer verdächtigen die Al'Aketh. Ayessa schickt Euch nach Norden ins Böenbeerentiefland, um die Morde zu vergelten und die Windstein-Gebetsamulette der gefallenen Kultisten zurückzubringen.",h="Mehrere Novizen der Windformer liegen tot im Hochland, und die Windformer verdächtigen die Al'Aketh.",kw={"al'aketh","ayessa","blood for blood","kultisten","böenbeerentiefland","hochland","windformer","windstein-gebetsamulette"},sec={{t="Eine grausige Entdeckung",b="Mehrere Novizen der Windformer wurden im Hochland erschlagen aufgefunden. Es gibt kaum Beweise, doch die Windformer verdächtigen die Kultisten von Al'Aketh. Ihr Fanatismus macht sie zu den Hauptverdächtigen. Der Glaube der Windformer fordert Auge um Auge, deshalb werden sie die Morde nicht ungesühnt lassen."},{t="Forderungen nach Vergeltung",b="Ayessa fordert Euch auf, alle Al'Aketh anzugreifen, die Ihr im Norden im Böenbeerentiefland findet. Sie bittet Euch, die Windstein-Gebetsamulette der gefallenen Kultisten als Beweis für deren Tod zurückzubringen. Die Windformer sehen diesen Schlag als Antwort auf den langjährigen Fanatismus der Kultisten."}},faq={{q="Wer sind die Al'Aketh?",a="Die Al'Aketh sind Kultisten, die die Windformer als blutrünstige Eiferer betrachten. Die Windformer verdächtigen sie, Novizen im Hochland erschlagen zu haben.",al={"wer sind die alaketh","alaketh-kultisten","gegen wen wird gekämpft"}},{q="Warum suchen die Windformer Vergeltung?",a="Mehrere Novizen der Windformer wurden im Hochland tot aufgefunden, und die Windformer verdächtigen die Al'Aketh. Ihr Glaube verlangt dafür Rache.",al={"warum alaketh töten","novizen der windformer tot","warum rache"}},{q="Wer ist Ayessa?",a="Ayessa vertritt die Windformer. Sie leitet ihre Vergeltung gegen die Al'Aketh und sammelt die Gebetsamulette, die gefallenen Kultisten abgenommen werden.",al={"wer ist ayessa","questgeber","ayessa windformer"}},{q="Was sind die Windstein-Gebetsamulette?",a="Kultisten von Al'Aketh tragen Windstein-Gebetsamulette. Ayessa verlangt sie als Beweis dafür, dass die für die Morde verantwortlichen Kultisten erschlagen wurden.",al={"was sind windstein-amulette","gebetsamulette","beweis der tat"}},{q="Wo sind die Al'Aketh zu finden?",a="Die Al'Aketh befinden sich im Norden im Böenbeerentiefland, wo sie ihren Praktiken nachgehen.",al={"wo sind die alaketh","wo sind kultisten","lage des böenbeerentieflands"}}},fp="15,228,16.279.0,22.280.0,21.138.0,44.145.0,14.144.0,37.142.0,32.94.0"}
P.entries["quest:93746"] = {n="A Firm Response",s="Ayessa Dawnsinger beantwortet das Eindringen des Hohen Ordens auf der Insel Zephras mit Gewalt. Sie schickt Euch hinter Belathaan Brightwish her, auf die Straße nach Norden zum Schrein von Akir, um die Grenzen der Windformer deutlich zu machen.",h="Ayessa Dawnsinger beantwortet das Eindringen des Hohen Ordens auf der Insel Zephras mit Gewalt.",kw={"a firm response","ayessa dawnsinger","belathaan brightwish","der hohe orden","lebende stürme","schrein von akir","windformer","insel zephras"},ang={["class:Shaman"]="Als Schamane stellt Ihr Euch Lebenden Stürmen inmitten der aufgewühlten, ungezähmten elementaren Luftmagie, die überall auf der Insel Zephras zu finden ist.",["faction:Horde"]="Als Mitglied der Horde auf der Insel Zephras helft Ihr, ihre Stellungen zu sichern und Rivalen wie den Hohen Orden davon abzuhalten, verbündete Interessen zu beeinträchtigen."},sec={{t="Grenzen ziehen",b="Die Windformer der Insel Zephras dulden die heimlichen Nachforschungen des Hohen Ordens nicht. Ihre Warnungen blieben unbeachtet, also verschärft Ayessa Dawnsinger den Konflikt. Sie schickt Euch los, um Belathaan Brightwish auf der einsamen Straße nach Norden zum Schrein von Akir abzufangen, fernab neugieriger Blicke im Ort."},{t="Stürme auf der Straße",b="Belathaan Brightwish reist nach Norden zum uralten Schrein von Akir, und seine Absichten sind unklar. Als Ihr ihn auf der abgelegenen Straße stellt, wird er feindselig, und Lebende Stürme greifen in den Kampf ein. Die Elementare zu besiegen und Belathaan zu demütigen, sendet dem Hohen Orden eine klare Botschaft: Die Windformer beantworten Einmischung mit Gewalt."}},faq={{q="Wer ist Ayessa Dawnsinger?",a="Ayessa Dawnsinger gehört zu den Windformern auf der Insel Zephras, die mit der Horde verbündet sind. Sie schützt ihr Gebiet und geht rücksichtslos gegen Eindringlinge vor, die sich in ihre Angelegenheiten einmischen.",al={"ayessa dawnsinger","wer vergibt a firm response","ayessa"}},{q="Wer ist Belathaan Brightwish?",a="Belathaan Brightwish steht mit dem Hohen Orden in Verbindung. Ayessa Dawnsinger nimmt ihn ins Visier, um die Organisation einzuschüchtern, nachdem er allein auf dem Weg zum Schrein von Akir gesichtet wurde.",al={"belathaan brightwish","belthaan","wer ist belathaan"}},{q="Was ist der Hohe Orden?",a="Der Hohe Orden ist eine Fraktion auf der Insel Zephras, deren Aktivitäten mit denen der örtlichen Windformer in Konflikt stehen. Trotz ausdrücklicher Warnungen forscht er weiter in ihren Angelegenheiten nach.",al={"der hohe orden","geschichte des hohen ordens","was ist der hohe orden"}},{q="Wo liegt der Schrein von Akir?",a="Der Schrein von Akir liegt nördlich des Ortes auf der Insel Zephras. Belathaan wird auf der abgelegenen Straße abgefangen, die dorthin führt.",al={"schrein von akir","wo ist der schrein von akir","schrein akir zephras"}},{q="Warum will Ayessa Belathaan verprügeln lassen, statt ihn zu töten?",a="Ayessa will Belathaan verprügeln lassen, um eine Botschaft zu senden, ohne einen umfassenden Krieg auszulösen. Sie hofft, dass er voller Furcht und mit Respekt vor den Grenzen der Windformer zu seinen Vorgesetzten zurückkehrt.",al={"belathaan töten","warum belathaan verschonen","warum nur blaue flecken"}},{q="Was sind die Lebenden Stürme, denen man bei dieser Aufgabe begegnet?",a="Lebende Stürme sind Elementarwesen, die während der Konfrontation mit Belathaan auf der Straße erscheinen. Sie spiegeln die unberechenbaren Elementarkräfte der Insel Zephras wider.",al={"lebende stürme","was sind lebende stürme"}}},fx={["3180a0eb"]={q="Warum möchte Ayessa Dawnsinger, dass Belathaan zur Rede gestellt wird?",a="Der Hohe Orden hat sich wiederholt in die Angelegenheiten der Windformer eingemischt und frühere Warnungen ignoriert, ihr Territorium und ihre Praktiken zu respektieren. Ayessa glaubt, dass diplomatische Worte nicht mehr ausreichen. Indem Ihr Belathaan auf der Straße abfangt und ihm eine kräftige Tracht Prügel verpasst, hofft sie, ein unmissverständliches Signal an seine Vorgesetzten zu senden, dass die Windformer ihre Grenzen notfalls mit Gewalt durchsetzen werden.",al={"warum belathaan zur rede stellen","ayessa beweggrund","warum nachricht an den hohen orden schicken"}}},fp="15,209,16.292.0,18.327.1,25.168.0,28.169.0,23.169.0,36.118.0,57.176.0,56.160.0"}
P.entries["quest:93786"] = {n="A Message in Blood",s="Krom’rosh schickt Euch gegen den Menschenhof in Meadowsbrook. Er will, dass Ihr die Farmarbeiter tötet, um auf den Anspruch der Überläufer auf das Land zu antworten.",h="Krom’rosh schickt Euch gegen den Menschenhof in Meadowsbrook.",kw={"eine botschaft in blut","farholde","farm","menschliche überläufer","krom’rosh","farm in meadowsbrook","meadowsbrook farmhands","scharmützel"},ang={["faction:Horde"]="Als Mitglied der Horde führt Ihr Krom’roshs Befehl gegen menschliche Überläufer aus, die die Farm beansprucht haben."},sec={{t="Die Farmarbeiter",b="Krom’rosh weist Euch den Weg zur Farm in Meadowsbrook, südwestlich jenseits des Flusses. Menschliche Überläufer beanspruchten die Farm vor einigen Jahren und rückten dann in Richtung Farholde vor, der Festung am Ostufer. Krom’rosh sagt, bei früheren Scharmützeln hätten ihnen die nötigen Kämpfer gefehlt, um zu siegen. Nun will er, dass Ihr die Farm verwüstet und keine Gefangenen macht."}},faq={{q="Wer schickt mich nach Meadowsbrook?",a="Krom’rosh bittet Euch, die Farm in Meadowsbrook anzugreifen und den Betrieb dort zu stören.",al={"wer hat mich geschickt","krom’roshs auftrag","wer bittet darum"}},{q="Warum will Krom’rosh, dass die Farm angegriffen wird?",a="Menschliche Überläufer beanspruchten die Farm und breiteten sich in Richtung Farholde aus. Krom’rosh will sie daran erinnern, dass sein Volk hier ist.",al={"warum die farm angreifen","warum meadowsbrook","warum gegen menschen kämpfen"}},{q="Wo liegt die Farm in Meadowsbrook?",a="Die Farm in Meadowsbrook liegt südwestlich jenseits des Flusses.",al={"wo liegt die farm","meadowsbrook lage","farm im südwesten"}},{q="Wer sind die Farmarbeiter?",a="Die Meadowsbrook Farmhands sind die Leute, die Krom’rosh Euch zu töten schickt.",al={"wer sind die farmarbeiter","menschen aus meadowsbrook","menschen auf der farm"}},{q="Was geschah bei den früheren Scharmützeln?",a="Krom’rosh sagt, die früheren Scharmützel wären für seine Seite ausgegangen, wenn sie mehr Kämpfer gehabt hätten.",al={"frühere kämpfe","warum die scharmützel scheiterten","krom’roshs scharmützel"}}},fp="18,136,13.314.0,34.73.0,44.119.0,27.50.0,22.72.0,40.98.0"}
P.entries["quest:93788"] = {n="Borrowed Blades",s="Kreza Darkthorn bittet Euch, die Äxte der Holzfäller aus Turner's Logging Camp zu holen. Ihre Klingen liefern Material für Waffen in Rog'mar.",h="Kreza Darkthorn bittet Euch, die Äxte der Holzfäller aus Turner's Logging Camp zu holen.",kw={"geliehene klingen","schmiede","gur'dok","kreza darkthorn","holzfäller","rog'mar","turner's logging camp","waffen","holzfälleraxt"},sec={{t="Im Holzfällerlager",b="Kreza Darkthorn hält Rog'mars Schmiede in Betrieb, während Gur'dok die Klingen zerlegt. Die Menschen im Süden und Twilight im Westen erschweren die Beschaffung von Rohstoffen. Ihr sollt die Äxte der Holzfäller aus Turner's Logging Camp zurückbringen, damit aus ihrem Material Waffen gefertigt werden können."}},faq={{q="Wer will die Äxte?",a="Kreza Darkthorn in Rog'mar bittet Euch, die Äxte aus Turner's Logging Camp zu holen.",al={"wer hat mich geschickt","äxte von kreza","wer braucht klingen"}},{q="Warum will Kreza die Äxte der Holzfäller?",a="Gur'dok wird die Klingen zerlegen, und Kreza wird aus ihrem Material Waffen herstellen.",al={"warum äxte","wofür sind äxte","waffenmaterial"}},{q="Wo liegt Turner's Logging Camp?",a="Turner's Logging Camp liegt südlich am Fluss, bei der Mühle.",al={"standort des holzfällerlagers","wo sind die holzfäller","turner's camp"}},{q="Was erschwert die Beschaffung von Rohstoffen?",a="Die Menschen im Süden und Twilight im Westen erschweren den Kampf um Rohstoffe.",al={"warum rohstoffe schwer zu beschaffen sind","menschen im süden","twilight in der nähe"}}},fp="15,143,19.304.0,19.84.0,42.87.0,31.60.0,41.96.0"}
P.entries["quest:93791"] = {n="Speak with Belann",s="In Valanaar werden angehende Zauberwirker zu Belann Windwood geschickt. Der Hohe Orden ehrt die Herstellung eines persönlichen Zauberfokus als lang gepflegte Tradition.",h="In Valanaar werden angehende Zauberwirker zu Belann Windwood geschickt.",kw={"belann","belann windwood","der hohe orden","zauberfokus","stäbe","valanaar","zauberstäbe"},ang={["class:Mage"]="Als Magier vollzieht Ihr mit der Herstellung eines persönlichen Zauberfokus einen bedeutsamen Übergangsritus und ehrt die uralten Traditionen des Hohen Ordens."},sec={{t="Ein Ritus wachsender Macht",b="Während Schüler die Magie immer besser beherrschen, greift der Hohe Orden auf einen uralten Brauch zurück, um ihre Talente zu prüfen und zu stärken. Einen eigenen Zauberfokus herzustellen, ob Zauberstab oder Stab, zählt zu den beständigsten Traditionen des Ordens. Sie gilt Schülern, die ihre wachsende Macht an ein selbst gefertigtes Werkzeug binden möchten."},{t="Der Handwerker von Valanaar",b="In Valanaar suchen Initianden Belann Windwood auf, um Hilfe bei diesem Handwerk zu erhalten. Seit mehr als einem Jahrhundert schmiedet er Stäbe und Zauberstäbe für den Hohen Orden. Als vertrauenswürdiger Mentor heißt Belann engagierte Schüler willkommen und führt sie in das Handwerk und die Geschichte ihrer magischen Werkzeuge ein."}},faq={{q="Wer ist Belann Windwood?",a="Belann Windwood ist ein Meisterhandwerker, der in Valanaar lebt. Seit mehr als einem Jahrhundert fertigt er Stäbe und Zauberstäbe für Mitglieder des Hohen Ordens.",al={"wer ist belann","belann windwood","belann"}},{q="Was ist der Hohe Orden?",a="Der Hohe Orden ist eine uralte Gemeinschaft von Magieanwendern. Zu seinen Traditionen gehört es, junge Zauberwirker bei der Herstellung und Beherrschung ihrer eigenen Zauberfokusse anzuleiten.",al={"was ist der hohe orden","geschichte des hohen ordens"}},{q="Was ist ein Zauberfokus?",a="Ein Zauberfokus, etwa ein Zauberstab oder Stab, bündelt magische Energien. Für heranwachsende Zauberwirker des Hohen Ordens zählt seine Herstellung zu den ältesten Übergangsriten.",al={"was ist ein zauberfokus","zweck eines zauberfokus"}},{q="Wo liegt Valanaar?",a="Valanaar ist die Siedlung, in der Belann Windwood seine Werkstatt unterhält und Schülern des Hohen Ordens hilft, Fokusse herzustellen.",al={"wo liegt valanaar","lage von valanaar"}},{q="Warum werdet Ihr zu Belann geschickt?",a="Als angehender Magieanwender werdet Ihr zu Belann geschickt, dessen Erfahrung mehr als ein Jahrhundert umfasst, um bei ihm zu lernen und Euer eigenes magisches Werkzeug zu formen.",al={"warum belann besuchen","warum einen fokus herstellen"}},{q="Was geschieht, nachdem Ihr Belann getroffen habt?",a="Wenn Ihr Euch Belann in Valanaar vorstellt, heißt er Euch willkommen und bereitet sich darauf vor, die nächsten Schritte beim Zusammenbau Eures Zauberfokus zu erklären.",al={"was geschieht als nächstes","nach dem gespräch mit belann"}}},fp="17,153,23.326.0,25.270.0,23.145.0,23.158.0,22.162.0,28.112.0,38.157.0,35.138.0"}
P.entries["quest:93797"] = {n="Boughs in the Wind",s="In Valanaar führt Belann Windwood Lehrlinge durch den alten Ritus, einen Zauberfokus zu formen. Sie suchen nahe Falaath Village einen vom Wind berührten Zweig, da in Zephras immer weniger Menschen mit magischer Begabung geboren werden.",h="In Valanaar führt Belann Windwood Lehrlinge durch den alten Ritus, einen Zauberfokus zu formen.",kw={"belann windwood","boughs in the wind","falaath village","zauberfokus","valanaar","windschrein","winddurchfluteter zweig","zephras"},ang={["class:Mage"]="Einen Zauberfokus aus einem vom Wind berührten Zweig zu formen, ist ein früher Ritus für Zauberwirker, die lernen, elementare Resonanz zu kanalisieren.",["race:Skyborne"]="Da mit jedem Jahr weniger Jugendliche eine Begabung für Magie zeigen, hilft das Formen eines traditionellen Zauberfokus, die überlieferte Kultur Eures Volkes in Zephras zu bewahren."},sec={{t="Ein Übergangsritus",b="Junge Zauberwirker in Zephras beginnen diesen alten Ritus, sobald sie eine Begabung für Magie zeigen. In Valanaar leitet Belann Windwood Lehrlinge an, während sie einen herabgefallenen Zweig von den ältesten Bäumen der Region sammeln. Die Zweige bewahren Spuren des Windes und eignen sich dadurch zum Kanalisieren von Zaubern."},{t="Flüstern am Windschrein",b="Die mächtigsten Zweige liegen nahe dem Windschrein unmittelbar südlich von Falaath Village, wo sich elementare Strömungen sammeln. Der Überlieferung nach kann ein Zweig seinen Zauberwirker wählen, und manche sagen, er singe leise für jene, die seine Macht nutzen können. Für Älteste wie Belann trägt jeder Lehrling, der den Ritus vollendet, dazu bei, ihre Kultur weiterzutragen. Mit jedem Jahr werden in Zephras weniger Menschen mit einer Begabung für Magie geboren."}},faq={{q="Was ist die Quest Boughs in the Wind?",a="Lehrlinge sammeln einen vom Wind berührten, herabgefallenen Zweig, um einen Zauberfokus zu formen. Dieser alte Ritus hilft, das magische Erbe von Zephras zu bewahren.",al={"was ist boughs in the wind","boughs in the wind quest","zauberfokus quest"}},{q="Wer ist Belann Windwood?",a="Belann Windwood ist ein Mentor in Valanaar, der junge Zauberwirker beim Formen ihrer Zauberfoki anleitet. Ihn sorgt, dass mit jedem Jahr weniger Menschen eine Begabung für Magie zeigen.",al={"wer ist belann windwood","belann questgeber","belann valanaar"}},{q="Wo findet Ihr den Winddurchfluteten Zweig?",a="Die Zweige fallen von den ältesten Bäumen nahe dem Windschrein unmittelbar südlich von Falaath Village. Belann schickt Lehrlinge dorthin, weil uraltes Holz Spuren elementarer Strömungen bewahrt.",al={"wo windzweig finden","wo ist winddurchfluteter zweig","zweig fundort"}},{q="Warum fertigen junge Zauberwirker einen Zauberfokus an?",a="Lehrlinge formen ihren eigenen Zauberfokus, nachdem sie eine Begabung für Magie gezeigt haben. Er kanalisiert elementare Energien und markiert ihren Eintritt in einen alten kulturellen Ritus.",al={"warum zauberfokus anfertigen","zweck des zauberfokus","zauberfokus hintergrundgeschichte"}},{q="Warum fragt Belann, ob der Zweig für Euch gesungen hat?",a="Belann Windwood sagt, der Überlieferung nach wähle ein Zweig oft seinen Zauberwirker. Ein passender Zweig mag für jemanden, der für elementare Winde empfänglich ist, zu singen scheinen.",al={"zweig wählt den zauberwirker","singender zweig","wählt der zweig seinen zauberwirker"}},{q="Was geschieht mit der Magie in Zephras?",a="Mit jedem Jahr werden in Zephras weniger Menschen mit einer natürlichen Begabung für Magie geboren. Belann glaubt, dass es deshalb umso wichtiger ist, die alten Riten lebendig zu halten.",al={"wo ist zephras","magie schwindet zephras","zephras magie hintergrundgeschichte"}}},fp="18,207,17.262.0,27.396.0,37.130.0,23.174.0,41.181.0,47.153.0,46.155.0,38.147.0"}
P.entries["quest:938"] = {n="Nebel",s="Im schattigen Geäst von Teldrassil liegt Mist verwundet und von ihrer Gefährtin getrennt. Sie braucht einen sicheren Weg zu Schildwache Arynia Wolkenbruch an einem nahegelegenen Mondbrunnen.",h="Im schattigen Geäst von Teldrassil liegt Mist verwundet und von ihrer Gefährtin getrennt.",kw={"arynia wolkenbruch","mist","mondbrunnen","oracle tree","säbelzahnkatze","schildwache","teldrassil"},ang={["class:Hunter"]="Als Jäger erkennt Ihr die leidenschaftliche Treue in Mists leuchtendem Blick. Ihre sichere Rückkehr zu ihrer Gefährtin ist eine Frage der Ehre.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr den Schildwachen in Teldrassil helfen und das Wohlwollen der kaldorei gewinnen, die den Weltbaum verteidigen.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass Schildwachen und Säbelzahnkatzen ein Band verbindet, das für Eure Kriegskunst und Waldkunde von zentraler Bedeutung ist. Mist heimzubringen ehrt diese uralte Verbundenheit."},sec={{t="Eine verwundete Gefährtin",b="Mist liegt verwundet im Unterholz von Teldrassil, ihr graues Fell von tiefen Schnittwunden an Rücken und Bauch gezeichnet. Ihre blauen Augen leuchten noch immer, und sie bleibt ruhig, statt sich wie eine wilde Bestie zu verhalten. Bei freundlichen Reisenden sucht sie Führung und Schutz."},{t="Der Preis des Hinterhalts",b="Schildwache Arynia Wolkenbruch und Mist patrouillierten nahe dem Oracle Tree, als Hexen ihnen auflauerten und sie auseinandertrieben. Arynia glaubte, ihre geliebte Gefährtin sei gestorben. Voller Trauer zog sie sich an einen nahegelegenen Mondbrunnen zurück und hoffte, Mist habe überlebt."}},faq={{q="Wer ist Mist?",a="Mist ist die treue graue Säbelzahnkatze an der Seite von Schildwache Arynia Wolkenbruch. In den Wäldern von Teldrassil wurde sie bei einem Hinterhalt verwundet und von Arynia getrennt.",al={"mist katze","was ist mist","wer ist die säbelzahnkatze"}},{q="Wer hat Mist verletzt?",a="Hexen in den Wäldern von Teldrassil überfielen Mist und Schildwache Arynia Wolkenbruch. Sie trennten die beiden und fügten Mist Schnittwunden an Rücken und Bauch zu.",al={"wer hat mist verletzt","warum blutet mist","hexen hinterhalt mist"}},{q="Wohin soll Mist geleitet werden?",a="Geleitet Mist sicher zu Schildwache Arynia Wolkenbruch, die an einem Mondbrunnen nahe dem Oracle Tree wartet.",al={"wohin mist bringen","mist abgeben","mist ziel"}},{q="Wer ist Schildwache Arynia Wolkenbruch?",a="Schildwache Arynia Wolkenbruch ist eine Nachtelfen-Schildwache und Mists Gefährtin. Sie wartet an einem Mondbrunnen nahe dem Oracle Tree.",al={"arynia wolkenbruch","wolkenbruch","mist besitzerin"}},{q="Warum sind Nachtelfen-Schildwachen mit Säbelzahnkatzen verbunden?",a="Seit Jahrtausenden kämpfen Nachtelfen-Schildwachen an der Seite von Kalimdors Großkatzen. Säbelzahnkatzen dienen als erbitterte Kampfgefährten in Scharmützeln, als Späher unter schattigem Geäst und als vertraute Gefährten fürs Leben.",al={"nachtelfen katzengefährten","schildwachen säbelzahnkatzen","warum säbelzahnkatzen"}},{q="Wo liegt der Oracle Tree im Verhältnis zu dieser Rettung?",a="Der Oracle Tree steht im Nordwesten von Teldrassil. Ein nahegelegener Mondbrunnen spendet heiliges Wasser, und Schildwache Arynia Wolkenbruch geht dort ihren Pflichten nach.",al={"oracle tree standort","mondbrunnen mist"}}},fx={["1795c253"]={q="Warum benötigt Mist Eure Hilfe?",a="Mist ist schwer verwundet, mit tiefen Schnittwunden an Rücken und Bauch, und wurde von ihrer Begleiterin, der Schildwache Arynia Wolkenbruch, getrennt. Geschwächt und einsam im Wald gestrandet, kann sie ohne Euren Schutz nicht sicher durch die Gefahren von Teldrassil navigieren, um die Sicherheit des Mondbrunnens zu erreichen.",al={"warum mist helfen","mist beweggrund","warum braucht mist eine eskortierung"}},["94db0917"]={q="Warum verlässt sich Mist auf Euch, anstatt sich selbst zu retten?",a="Mist ist zu schwer verletzt, um sich ohne Hilfe durch die feindseligen Wälder zu kämpfen oder den langen Weg zurückzulegen. Als ein Tier, das von ihrer Schildwache getrennt wurde, hat sie keine Verbündeten oder Wachen in der Nähe, an die sie sich wenden kann; als Ihr sie findet, erkennt sie in Euch eine freundliche Präsenz und setzt ihr Vertrauen in Eure Fähigkeit, sie zu führen und zu beschützen.",al={"warum ich mist","warum kann mist nicht alleine entkommen","warum folgt mist euch"}}},fp="4,154,19.257.0,19.238.1,12.145.0,17.135.0,30.101.0,35.120.0,50.191.0,52.150.0"}
P.entries["quest:93835"] = {n="Confront Lorthuna",s="Ein verletzter Magier braucht Euch, um Ayessa Dawnsinger und Elaadrin Evengale durch ein Portal zu den Türmen der Rohashi zu folgen. Dort stellen sie sich Hohepriesterin Lorthuna und brauchen Eure Hilfe.",h="Ein verletzter Magier braucht Euch, um Ayessa Dawnsinger und Elaadrin Evengale durch ein Portal zu den Türmen...",kw={"ayessa dawnsinger","elaadrin evengale","der hohe orden","lorthuna","portal","die türme der rohashi","valennia","zephras"},sec={{t="Durch das Portal",b="Lorthuna floh durch ein Portal zu den Türmen hoch oben. Ayessa Dawnsinger und Elaadrin Evengale folgten ihr vor wenigen Augenblicken, doch ihr Begleiter ist zu schwer verletzt, um mitzugehen. Folgt den beiden Magiern durch das Portal, während sie sich der Hohepriesterin stellen."},{t="Nach dem Kampf",b="Die verbliebenen Magier wurden ausgesandt, um Valennia und ihren Streitkräften bei der Flucht zu helfen. Valennia ruht sich in der Residenz von High Elder Shadowsong aus. Ansirem ist nach Azeroth zurückgekehrt, nachdem er die nächsten Schritte des Hohen Ordens besprochen hat. Zephras hat den Tag überlebt, bleibt aber gefährlich verwundbar, und es müssen Pläne für das gemacht werden, was als Nächstes kommt."}},faq={{q="Wer bittet mich, Lorthuna zu folgen?",a="Ein verletzter Magier bittet Euch, Ayessa Dawnsinger und Elaadrin Evengale durch das Portal zu folgen und ihnen zu helfen, sich Hohepriesterin Lorthuna zu stellen.",al={"wer hat mich geschickt","verletzter magier","wer braucht hilfe"}},{q="Wohin ist Lorthuna gegangen?",a="Lorthuna floh durch ein Portal zu den Türmen der Rohashi hoch oben.",al={"wo ist lorthuna","lorthunas portal","wohin ist sie geflohen"}},{q="Wer ist Lorthuna gefolgt?",a="Ayessa Dawnsinger und Elaadrin Evengale sind Lorthuna durch das Portal gefolgt.",al={"ayessa und elaadrin","wer ist ihr gefolgt","wer ist dort oben"}},{q="Warum kann der verletzte Magier nicht mitgehen?",a="Der Magier hat zu viele Treffer eingesteckt und muss zurückbleiben.",al={"warum gehe ich allein","magier zu schwer verletzt","warum zurückbleiben"}},{q="Wo ist Valennia?",a="Valennia ruht sich in der Residenz von High Elder Shadowsong aus, nachdem die verbliebenen Magier ihr und ihren Streitkräften bei der Flucht geholfen haben.",al={"valennias aufenthaltsort","wohin ist sie gegangen","valennia in sicherheit"}},{q="Was steht jetzt auf dem Spiel?",a="Zephras ist gefährlich verwundbar, und der Hohe Orden muss planen, was als Nächstes kommt.",al={"zephras verwundbar","was ist mit zephras geschehen","hoher orden nächste schritte"}}},fp="17,176,18.239.0,15.311.1,38.137.0,22.62.0,24.79.0,40.49.0,18.116.0,20.84.0"}
P.entries["quest:93836"] = {n="The Fate of Zephras",s="Nach Lorthunas Fall erreicht Valanaar die Nachricht von einer Gefahr. Die Bannzauber der Insel Zephras haben versagt, und Ayessa schlägt eine Reise nach Azeroth vor. Der Hohe Älteste Talaanis Shadowsong muss erfahren, was geschehen ist.",h="Nach Lorthunas Fall erreicht Valanaar die Nachricht von einer Gefahr.",kw={"al'akir","ayessa","the fate of zephras","lorthuna","muln","schrein von akir","talaanis shadowsong","valanaar","insel zephras"},ang={["class:Shaman"]="Als Schamane wisst Ihr, dass die elementare Domäne des Windlords Al'Akir Zephras umgibt. Ohne die uralten Bannzauber liegt die Insel ungeschützt da.",["race:Skyborne"]="Als Skyborne von der Insel Zephras steht Ihr vor dem Verlust der Bannzauber und der Bedrohung durch Al'Akir. Euer Volk sucht nun jenseits seiner schwebenden Heimat nach einem Weg, sie zu schützen."},sec={{t="Ein unsicherer Sieg",b="Lorthuna ist nach der Schlacht über dem Schrein von Akir gefallen. Doch die Insel Zephras hat für den Sieg teuer bezahlt. Ihre uralten Bannzauber, die sie vor Al'Akir verbargen, sind zusammengebrochen. Das schwebende Refugium liegt nun ungeschützt in der Domäne des Windlords. Ein Bote durchquert die Insel mit einer Nachricht für Valanaar."},{t="Die Nachricht nach Valanaar",b="Der Hohe Älteste Talaanis Shadowsong erfährt, dass Lorthuna tot ist und die Bannzauber gebrochen sind. Er erfährt auch, dass Ayessa eine Expedition nach Azeroth führen will. Ohne ihren magischen Schleier suchen die Inselbewohner jenseits ihrer Heimat nach einem Weg, sie zu schützen. Shadowsong wägt Furcht gegen Hoffnung ab. Al'Akir ist eine schreckliche Bedrohung, doch Elementargötter handeln in gewaltigen Zeiträumen. Das könnte den Inselbewohnern kostbare Zeit zum Handeln lassen."}},faq={{q="Worum geht es in der Quest The Fate of Zephras?",a="Lorthuna ist am Schrein von Akir gefallen, und die Nachricht von der Gefahr wird nach Valanaar gebracht. Die schützenden Bannzauber der Insel haben versagt, und Ayessa schlägt eine Expedition nach Azeroth vor. Der Hohe Älteste Talaanis Shadowsong empfängt die Nachricht.",al={"quest the fate of zephras","was ist the fate of zephras","was geschieht in the fate of zephras"}},{q="Warum ist die Insel Zephras durch Al'Akir in Gefahr?",a="Die Insel Zephras liegt in der elementaren Domäne von Al'Akir, dem Windlord. Uralte Bannzauber verbargen das Refugium einst vor seinem Blick. Nun sind sie verschwunden, und die Insel ist schutzlos, sollte Al'Akir seinen Zorn gegen sie richten.",al={"warum ist zephras in gefahr","warum zephras angreifen","elementare bedrohung für zephras"}},{q="Wer ist Talaanis Shadowsong?",a="Talaanis Shadowsong ist der Hohe Älteste der Skyborne in Valanaar auf der Insel Zephras. Er wacht über die Herrschaft und das Überleben seines Volkes und erhält Berichte über Bedrohungen und Entscheidungen, vor denen seine Heimat steht.",al={"wer ist talaanis shadowsong","hoher ältester shadowsong","wo ist talaanis shadowsong"}},{q="Was ist Ayessas Plan?",a="Ayessa plant, eine Expedition von der Insel Zephras nach Azeroth zu führen. Sie sucht jenseits ihrer Domäne nach Antworten und Verbündeten, um ihr Volk vor Al'Akir zu schützen.",al={"wer ist ayessa","ayessas plan","was tut ayessa"}},{q="Wer war Lorthuna und was ist mit ihr geschehen?",a="Lorthuna führte den Kult auf der Insel Zephras an. Sie wurde über dem Schrein von Akir erschlagen, wodurch die Führung des Kults zerschlagen wurde, während die schützenden Bannzauber der Insel fielen.",al={"wer ist lorthuna","kultführerin lorthuna","was ist mit lorthuna geschehen"}},{q="Wer ist Muln?",a="Muln ist ein Berater oder Gelehrter, der sich mit den Elementarfürsten auskennt. Er warnte die Verteidiger von Zephras vor Al'Akirs großer Macht und Gefährlichkeit und bestätigte ihre Verwundbarkeit ohne magische Tarnung.",al={"wer ist muln","mulns hintergrundgeschichte"}}},fp="19,190,20.293.0,20.417.1,44.222.0,43.209.0,27.189.0,22.154.0,42.148.0,12.196.0"}
P.entries["quest:93926"] = {n="The Western Watch",s="Am Außenposten südwestlich der Siedlung bedrängen Kultisten die Verteidiger, und die örtlichen Anführer rufen sie zurück. Sie halten die Verteidigung des Turms für zu verlustreich und wenden sich dem Schutz des Dorfes zu.",h="Am Außenposten südwestlich der Siedlung bedrängen Kultisten die Verteidiger, und die örtlichen Anführer rufen...",kw={"kult","friedensbewahrer vaaniel","friedensbewahrer","sturmzauberwirker","the western watch","wachturm","westlicher wachturm"},sec={{t="Ein verlustreicher Außenposten",b="Der westliche Wachturm bewacht die Grenze südwestlich der Siedlung. Kultisten haben ihren Angriff erneuert, und die örtlichen Anführer entscheiden, dass die Verteidigung des abgelegenen Postens zu viele Leben kostet. Also bereiten sie Befehle vor, um die Friedensbewahrer zurückzurufen. Sie hoffen, weitere Leben zu schonen und alle Verteidiger zum Schutz des Dorfes und seiner Bewohner zu versammeln."},{t="Zu spät zum Rückzug",b="Friedensbewahrer Vaaniel befehligte die Garnison am westlichen Wachturm. Der Rückzugsbefehl traf zu spät ein. Zauberwirker des Kults, die Stürme beherrschten, hatten den Turm überrannt, bevor die Boten ihn erreichten. Vaaniel und seine Garnison lagen tot zwischen versengten Steinen und Brandspuren von Blitzen."}},faq={{q="Wer ist Friedensbewahrer Vaaniel?",a="Friedensbewahrer Vaaniel befehligt die Friedensbewahrer am westlichen Wachturm. Kultisten greifen an, und Ihr werdet entsandt, um ihn zu finden und ihm auszurichten, dass er seine Garnison schnell ins Dorf zurückbringen soll.",al={"wer ist vaaniel","vaaniel hintergrund","friedensbewahrer vaaniel"}},{q="Warum wurde den Friedensbewahrern befohlen, den Wachturm aufzugeben?",a="Die örtlichen Anführer befahlen den Friedensbewahrern den Abzug, weil die Angriffe des Kults zu viele Leben kosteten. Sie wollen die Verteidiger im Dorf versammeln, um dessen Bewohner zu schützen.",al={"warum turm aufgeben","warum wachturm verlassen","westlicher wachturm befehl"}},{q="Was tötete Friedensbewahrer Vaaniel?",a="Zauberwirker des Kults, die Stürme beherrschten, töteten Friedensbewahrer Vaaniel. Blitze und Elementarmagie hinterließen Verbrennungen und Brandspuren an ihm und den Verteidigern des Turms.",al={"wie starb vaaniel","wer tötete vaaniel","wodurch wurde der friedensbewahrer getötet"}},{q="Wer griff den westlichen Wachturm an?",a="Ein feindseliger Kult griff den westlichen Wachturm mit zerstörerischer Sturmmagie an. Die örtlichen Befehlshaber wissen nicht, warum der Kult den Turm haben will, doch der Angriff bedroht nahe gelegene Siedlungen.",al={"wer greift den turm an","kultangriff westlicher turm","welcher kult ist das"}},{q="Wo befindet sich der westliche Wachturm?",a="Der westliche Wachturm steht südwestlich der örtlichen Siedlung und bewacht die westlichen Zugänge. Seine abgeschiedene Lage machte ihn für Angriffe des Kults verwundbar.",al={"wo ist der wachturm","westlicher wachturm standort"}},{q="Was geschah mit der Garnison am Turm?",a="Der Wachturm war bereits gefallen, als die Boten mit dem Befehl zur Räumung eintrafen. Zauberwirker des Kults töteten Friedensbewahrer Vaaniel und die anderen Verteidiger, kurz bevor Hilfe sie erreichen konnte.",al={"was geschieht am turm","wachturm ausgang","haben friedensbewahrer überlebt"}}},fp="17,183,16.329.0,19.264.1,27.189.0,60.173.0,32.152.0,36.180.0,40.148.0,43.184.0"}
P.entries["quest:93927"] = {n="A Last Request",s="Auf Zephras trägt ein gefallener Friedensbewahrer eine Nachricht, die seine letzten Augenblicke offenbaren könnte. Seine blutbefleckte Notiz weist auf die Pflicht hin, die er unerfüllt zurückließ.",h="Auf Zephras trägt ein gefallener Friedensbewahrer eine Nachricht, die seine letzten Augenblicke offenbaren...",kw={"a last request","blutige notiz","toter friedensbewahrer","friedensbewahrer","notiz des friedensbewahrers"},sec={{t="Ein düsterer Fund",b="Ihr findet im Feld einen toten Friedensbewahrer mit einer blutbefleckten Notiz in den Händen. Als Ihr ihn untersucht, löst sich die Notiz. Auf Zephras riskieren Friedensbewahrer ihr Leben, um die Ordnung zu wahren. Seine letzten Worte könnten verraten, was ihm widerfahren ist."},{t="Die letzte Nachricht",b="Das blutige Pergament enthält die letzte Bitte oder die letzten Anweisungen des Friedensbewahrers. Wer auch immer ihn getötet hat, ließ seine Pflicht unerfüllt. Lest die Hinweise und vollendet seine letzte Mission. Die Notiz weist den Weg, um seinem letzten Ruf zu folgen."}},faq={{q="Wer ist der tote Friedensbewahrer?",a="Die Identität des gefallenen Friedensbewahrers ist unbekannt, als Ihr ihn findet. Er wahrte die Ordnung, und sein Dienst endete gewaltsam. Nur eine dringende Nachricht bleibt in seinen Händen zurück.",al={"wer ist der tote friedensbewahrer","toter friedensbewahrer","identität des friedensbewahrers"}},{q="Was steht auf der blutigen Notiz?",a="Die Notiz enthält den letzten Bericht des Friedensbewahrers. Der Kult überrumpelte seinen Posten. Raani sah es nicht kommen, Arvensus traf ein Schwert in den Bauch, und ein Blitz streckte den Verfasser nieder. Zum Sterben zurückgelassen, erwartete er, dass seine Wunden vollenden würden, was der Kult begonnen hatte.",al={"was ist die blutige notiz","was steht in der notiz","notiz des friedensbewahrers"}},{q="Wie wird diese Bitte entdeckt?",a="Ihr findet die Leiche des Friedensbewahrers im Feld und untersucht sie. Die blutige Notiz in seinen Händen enthält seine letzte Bitte.",al={"wie beginnt a last request","wo wird a last request gefunden"}},{q="Was ist dem Friedensbewahrer widerfahren?",a="Der Kult überfiel den Posten des Friedensbewahrers ohne Vorwarnung. Seine Gefährten fielen, und ein Blitz traf ihn, woraufhin er zum Sterben zurückgelassen wurde. Er lebte lange genug, um die Geschehnisse in der Notiz festzuhalten, die in seinen Händen gefunden wurde.",al={"warum wurde der friedensbewahrer getötet","wer hat den friedensbewahrer getötet"}},{q="Was ist die letzte Bitte des Friedensbewahrers?",a="Der Friedensbewahrer starb, bevor er seine Mission vollenden oder seine Nachricht überbringen konnte. Ihr könnt seine blutbefleckte Notiz bergen und lesen, seine letzten Anweisungen entschlüsseln und seinen letzten Wunsch erfüllen.",al={"was ist die bitte des friedensbewahrers","zweck der letzten bitte"}},{q="Welche Aufgabe erfüllen Friedensbewahrer?",a="Friedensbewahrer schützen Siedlungen und Straßen, wahren die Ordnung und verteidigen sie gegen Gefahren. Fällt einer im Feld, bleiben seine Pflichten unerfüllt und seine Verbündeten ungewarnt, sofern niemand seinen letzten Bericht birgt.",al={"wer sind die friedensbewahrer","geschichte der friedensbewahrer"}}},fp="14,146,16.225.0,17.216.0,28.153.0,35.249.0,31.111.0,33.207.0,39.189.0,32.219.0"}
P.entries["quest:93948"] = {n="Deliver the Signet",s="Ein Reisender bringt das geborgene Schattensang-Familiensiegel zum Obersten Ältesten Talaanis Shadowsong in Valanaar. Seine Rückkehr bestätigt den Tod seines Neffen auf der Insel Zephras, und Talaanis verweist den Reisenden an die örtlichen Friedenswahrer.",h="Ein Reisender bringt das geborgene Schattensang-Familiensiegel zum Obersten Ältesten Talaanis Shadowsong in...",kw={"deliver the signet","schattensang-familiensiegel","shen'dorei","talaanis shadowsong","valanaar","valennia stormfist","insel zephras"},ang={["race:NightElf"]="Für einen Nachtelfen birgt der Name Shadowsong eine lange Geschichte unter den elfischen Geschlechtern. Auf der Insel Zephras stehen der Oberste Älteste Talaanis und die örtlichen shen'dorei vor ihren eigenen Schwierigkeiten."},sec={{t="Ein trauriger Auftrag",b="Ein Reisender bringt das Schattensang-Familiensiegel nach Valanaar, nachdem es aus einem abgelegenen Turm geborgen wurde. Das düstere Pfand ist für Talaanis Shadowsong bestimmt, den Obersten Ältesten der Insel Zephras. Sein Volk liebt ihn, doch die Not lastet auf der Siedlung. Der Ring bestätigt, dass sein Neffe umgekommen ist, und Talaanis nimmt das Erbstück zusammen mit Beileidsbekundungen entgegen."},{t="Trauer und Pflicht in Valanaar",b="In Valanaar dankt der Oberste Älteste Talaanis dem Reisenden für die Rückgabe des Siegels, auch wenn Trauer auf ihm lastet. Er erkennt das Geschick des Reisenden und verweist ihn an Captain Valennia Stormfist, die die Friedenswahrer von Valanaar anführt. Die Siedlung kämpft mit angespannten Verhältnissen und wachsendem Druck. Ihre Beschützer heißen fähige Helfer willkommen."}},faq={{q="Wer ist Talaanis Shadowsong?",a="Talaanis Shadowsong ist der Oberste Älteste der Insel Zephras. Seine Gemeinschaft achtet und liebt ihn, und das zurückgebrachte Siegel bestätigt den Tod seines Neffen.",al={"wer ist talaanis","oberster ältester talaanis","talaanis shadowsong geschichte"}},{q="Was ist das Schattensang-Familiensiegel?",a="Das Schattensang-Familiensiegel ist ein Familienring, der aus einem Turm geborgen wurde. Seine Rückgabe an Talaanis Shadowsong bestätigt, dass dessen Neffe umgekommen ist.",al={"was ist der siegelring","ring des neffen","shadowsong siegel"}},{q="Wo liegt Valanaar?",a="Valanaar ist eine Siedlung auf der Insel Zephras. Der Oberste Älteste Talaanis Shadowsong lebt dort, und Captain Valennia Stormfist führt die Friedenswahrer an.",al={"wo ist valanaar","siedlung valanaar","talaanis aufenthaltsort"}},{q="Wer ist Valennia Stormfist?",a="Valennia Stormfist führt die Friedenswahrer in Valanaar an. Der Oberste Älteste Talaanis schickt fähige Reisende zu ihr, damit sie mit ihr sprechen, denn die Siedlung braucht Hilfe.",al={"wer ist valennia stormfist","captain valennia","captain der friedenswahrer von valanaar"}},{q="Wer sind die shen'dorei, die Talaanis erwähnt?",a="Talaanis nennt fähige junge Reisende, die aus dem Hochland herabkommen, shen'dorei, ein Name, der die elfische Präsenz und das elfische Erbe auf der Insel Zephras widerspiegelt.",al={"wer sind die shendorei","shendorei hochland"}},{q="Was ist mit Talaanis Shadowsongs Neffen geschehen?",a="Talaanis' Neffe starb bei einem Turm, wo das Familiensiegel verloren ging. Die Rückgabe des Rings in Valanaar bringt dem Obersten Ältesten die Nachricht vom Tod seines Neffen.",al={"was geschah mit talaanis' neffen","wie starb der neffe"}}},fp="18,224,15.334.0,26.329.0,27.145.0,37.142.0,26.140.0,26.153.0,45.151.0,46.143.0"}
P.entries["quest:93949"] = {n="Bugged",s="Bugged ist eine Quest in Valanaar, bei der sich ein Zustrom saisonaler Tieflandinsekten als Spionagekomplott herausstellt. Magier des Hohen Ordens fanden heraus, dass örtliche Kultisten Abhörzauber auf Skyhopper wirken, um die Siedlung auszuspionieren, was eine Ausrottungsaktion erforderlich macht, um das verzauberte Ungeziefer zu beseitigen.",h="Bugged ist eine Quest in Valanaar, bei der sich ein Zustrom saisonaler Tieflandinsekten als Spionagekomplott...",kw={"bugged","kult","verzauberte skyhopper","der hohe orden","abhörzauber","skyhopper","valanaar"},ang={["class:Mage"]="Magier des Hohen Ordens deckten die magischen Abhörzauber auf, die auf gewöhnliches Ungeziefer gewirkt worden waren, und machten so arkane Analysen zur Spionageabwehr."},sec={{t="Lauscher im Schwarm",b="Während der Skyhopper-Saison im Tiefland ziehen Schwärme einheimischer Insekten um die Stadt Valanaar auf. Während dies für gewöhnlich lediglich als saisonale Plage angesehen wird, ergab eine Inspektion durch Magier des Hohen Ordens, dass mehrere getötete Exemplare hochentwickelte Abhörverzauberungen trugen. Ein örtlicher Kult hat den Insektenschwarm als Waffe eingesetzt und gewöhnliches Tieflandungeziefer in unauffällige Überwachungswerkzeuge verwandelt, um die Stadt zu belauschen."},{t="Reine Luft schaffen",b="Da verzauberte Skyhopper von ihren gewöhnlichen Artgenossen nicht zu unterscheiden sind, sind die Beschützer von Valanaar gezwungen, die Schwärme wahllos auszudünnen. Durch die Ausrottung dieser Insekten wird dem feindseligen Kult der Zugang zu entscheidenden Informationen verwehrt, wodurch die magische Überwachung unterbrochen und die Verteidigung der Stadt gegen innere Zersetzung gestärkt wird."}},faq={{q="Was sind Skyhopper?",a="Skyhopper sind geflügeltes Ungeziefer, das im Tiefland rund um Valanaar heimisch ist und während seiner saisonalen Zunahme in großer Zahl schwärmt.",al={"was sind skyhopper","skyhopper-insekt"}},{q="Wer hat die Insekten verzaubert?",a="Örtliche Kultisten stehen im Verdacht, Skyhopper einzufangen und mit magischen Abhörzaubern zu belegen, um die Siedlung zu belauschen.",al={"wer hat die insekten verzaubert","abhörinsekten des kults","wer spioniert in valanaar"}},{q="Wie erkennt man, welche Skyhopper verzaubert sind?",a="Verzauberte Skyhopper sehen für das bloße Auge mit gewöhnlichen Insekten identisch aus. Nur durch die Vernichtung der Schwärme können die magisch erfüllten Spione entlarvt und ausgeschaltet werden.",al={"wie man verzauberte skyhopper erkennt","welche insekten verzaubert sind"}},{q="Wo findet dies statt?",a="Der Befall und die Spionage ereignen sich rund um Valanaar, eine Stadt in den Lüften, wo saisonale Schwärme aus dem angrenzenden Tiefland aufsteigen.",al={"wo ist die quest bugged","valanaar insekten"}},{q="Welche Art von Verzauberung wurde auf die Skyhopper gelegt?",a="Magier des Hohen Ordens untersuchten getötete Insekten und entdeckten einen an sie gebundenen, spezialisierten Abhörzauber, der die Kreaturen effektiv in umherziehende Überwachungswerkzeuge verwandelte.",al={"welcher zauber liegt auf den insekten","skyhopper-verzauberung"}},{q="Warum müssen alle Skyhopper vernichtet werden?",a="Da verzauberte Skyhopper optisch nicht von gewöhnlichem Ungeziefer zu unterscheiden sind, ist die Beseitigung des Schwarms notwendig, um das Netzwerk magischer Abhörposten des Kults zu säubern und Valanaar zu schützen.",al={"warum skyhopper töten","bugged questziel"}}},fp="6,188,26.244.0,16.206.0,20.124.0,26.96.0,47.121.0,27.115.0,54.115.0,50.165.0"}
P.entries["quest:93951"] = {n="A Little Beauty",s="Im Shen'darhochland sammeln die Skyborne nahe Zephras Hippogryphendaunen. Ihre leuchtenden Federn bringen dem Dorf in schweren Zeiten Schönheit und kleine Freuden.",h="Im Shen'darhochland sammeln die Skyborne nahe Zephras Hippogryphendaunen.",kw={"a little beauty","daunenfedern","federn","hippogryph","zierfedern","shen'darhochland","skyborne","zephras"},ang={["race:Skyborne"]="Als Skyborne könnt Ihr farbenprächtige Hippogryphendaunen sammeln, um Euer Haar mit weichen Federn zu schmücken. Dieser Brauch bringt Zephras in schweren Zeiten kleine Freuden."},sec={{t="Federn des Hochlands",b="Wilde Hippogryphen nisten auf der Insel Zephras, südwestlich des Dorfes im Shen'darhochland. Sie verteidigen ihr Revier und können Reisenden in der Nähe Schwierigkeiten bereiten. Doch sie verlieren farbenprächtige, seidig weiche Daunen, die die Skyborne sammeln, um daraus Haarschmuck zu flechten."},{t="Freude an kleinen Dingen",b="Für die Handwerkerin von Zephras ist das Sammeln von Federn als Haarschmuck mehr als Eitelkeit. Selbst in schweren Zeiten helfen kleine Freuden, die man mit anderen teilt, den Gemeinschaftsgeist lebendig zu halten. Schönheit gibt dem Dorf jeden Tag etwas zu feiern."}},faq={{q="Warum werden Hippogryphenfedern gesammelt?",a="Die Skyborne sammeln Daunen wilder Hippogryphen, um daraus Haarschmuck herzustellen. Die farbenprächtigen, seidig weichen Federn stammen von den Vögeln, die sie verloren haben und Reisenden nahe der Siedlung Schwierigkeiten bereiten können.",al={"warum federn sammeln","wozu dienen federn","zweck der federn"}},{q="Was ist Zephras?",a="Zephras ist die Inselheimat der Skyborne. Die dortige Handwerkerin fertigt aus gesammelten Federn Haarschmuck, um den Bewohnern Freude und unbeschwerte Momente zu schenken.",al={"wer ist zephras","welcher ort ist das","wo geschieht das"}},{q="Wo nisten die Hippogryphen?",a="Wilde Hippogryphen nisten südwestlich des Dorfes im Shen'darhochland. Sie verteidigen ihr Revier und halten unerwünschte Gäste von ihren Nistplätzen fern.",al={"wo sind die nester","wo sind hippogryphen","lage des shen'darhochlands"}},{q="Warum sind kleine Annehmlichkeiten wie Haarschmuck in Zeiten wie diesen wichtig?",a="Die Handwerkerin glaubt, dass kleine Freuden und Schönheit gerade in schwierigen Zeiten wichtig sind. Anderen Freude zu bereiten, macht die Mühe lohnenswert.",al={"sind federn wichtig","warum haarschmuck","eitle belanglosigkeit"}},{q="Sind die Hippogryphen Besuchern gegenüber feindselig?",a="Die wilden Hippogryphen südwestlich des Dorfes verteidigen ihre Nistplätze gegen Eindringlinge. Ihre ausgefallenen Federn zu sammeln, kann für unachtsame Reisende gefährlich sein.",al={"warum sind hippogryphen gefährlich","sind hippogryphen wild"}},{q="Ist es unter den Skyborne üblich, das Haar mit Federn zu schmücken?",a="Ja, viele Skyborne flechten farbenprächtige Federn in ihr Haar. Hippogryphendaunen sind außergewöhnlich weich und eignen sich gut für diesen Schmuck.",al={"skyborne federn","tragen skyborne federn"}}},fp="15,157,23.241.0,27.222.0,44.173.0,16.159.0,30.152.0,74.139.0,40.161.0,59.131.0"}
P.entries["quest:93958"] = {n="The Inner Sanctum",s="Am Schrein von Akir ist Valennia Stormfists Angriff verstummt. Ihr Trupp drang unter heftigen Kämpfen in die tiefste Kammer vor, und nun fürchten die Verbündeten draußen um jene im Inneren.",h="Am Schrein von Akir ist Valennia Stormfists Angriff verstummt.",kw={"inneres sanktum","schrein von akir","stormfist","the inner sanctum","valennia","valennia stormfist"},sec={{t="Eine plötzliche Stille",b="Valennia Stormfist führte ihre Abteilung nach einem harten Angriff in das innere Sanktum des Schreins von Akir. Aus den Tiefen der Kammern drangen heftige, verzweifelte Kampfgeräusche. Dann verstummte der Lärm ohne Vorwarnung. Die draußen wartenden Verbündeten können nur das Schlimmste befürchten."},{t="Der Preis des Durchbruchs",b="Valennia Stormfist wird schwer verwundet im stillen Sanktum aufgefunden. Das Schicksal ihrer Vorhut bleibt nach der Schlacht ungewiss."}},faq={{q="Wer ist Valennia Stormfist?",a="Valennia Stormfist befehligt den Angriff auf die Tiefen des Schreins von Akir. Sie führte ihre Truppen durch die Bresche in das innere Sanktum, wo die Kämpfe bald verstummten.",al={"wer ist valennia","wer ist valennia stormfist","valennia"}},{q="Was ist der Schrein von Akir?",a="Der Schrein von Akir birgt ein inneres Sanktum, das nun angegriffen wird. Valennias Truppen durchbrachen unter schweren Kämpfen seine Verteidigung und machten den Schrein zum Mittelpunkt eines tödlichen Gefechts.",al={"was ist der schrein von akir","geschichte des schreins von akir","schrein von akir"}},{q="Was ist Valennias Truppen im Inneren zugestoßen?",a="Nach dem Durchbruch erklangen im Inneren schwere Kämpfe, die dann schlagartig verstummten. Die Stille lässt die Verbündeten draußen befürchten, dass Valennias Vorhut überwältigt oder getötet wurde.",al={"warum ist es still","was ist valennias truppen zugestoßen","valennias soldaten"}},{q="Lebt Valennia Stormfist noch?",a="Valennia Stormfist überlebt den Angriff, liegt aber nach dem Ende der Kämpfe schwer verwundet im inneren Sanktum des Schreins von Akir.",al={"lebt valennia","ist valennia gestorben","valennias schicksal"}},{q="Was ist das Ziel im inneren Sanktum?",a="Das innere Sanktum ist die tiefste Kammer im Schrein von Akir. Ihr werdet allein hineingeschickt, um die Lage nach der Schlacht zu erkunden und Valennia sowie alle überlebenden Kämpfer zu finden.",al={"was ist das innere sanktum","questziel im inneren sanktum"}},{q="Wer schickt Euch in das innere Sanktum?",a="Ein Verbündeter, der draußen hinter dem inneren Sanktum Wache hält, schickt Euch hinein. Er sichert die Umgebung und hält Euch den Rücken frei, während Ihr Euch Valennias Vorhut anschließt.",al={"wer schickt einen zu valennia","questgeber inneres sanktum"}}},fp="17,175,16.262.0,22.139.1,26.177.0,27.173.0,42.173.0,34.123.0,47.158.0,37.156.0"}
P.entries["quest:93963"] = {n="Exploring the Alliance",s="In Burg Sturmwind beginnt Eure Reise zu den Herrschern von Eisenschmiede und Darnassus. Ihre Länder zeigen Euch die Vielfalt der Allianz, bevor Ihr Euch Westfall zuwendet.",h="In Burg Sturmwind beginnt Eure Reise zu den Herrschern von Eisenschmiede und Darnassus.",kw={"dalaran","darnassus","exploring the alliance","obertüftler mekkadrill","eisenschmiede","magni bronzebart","randal emerson","burg sturmwind","tyrande wisperwind","westfall"},ang={["faction:Alliance"]="Als Neuankömmling bei der Allianz besucht Ihr ihre wichtigsten Festungen und trefft die Anführer, die das Bündnis zusammenhalten.",["race:Skyborne"]="Als Gast der Skyborne auf Azeroth werdet Ihr angehalten, die verbündeten Nationen kennenzulernen, die Euch Zuflucht gewähren, während Euer Orden sich darauf vorbereitet, in Dalaran Fuß zu fassen."},sec={{t="Eine Reise durch verbündete Länder",b="Randal Emerson, ein Bediensteter in der südlichen Vorkammer von Burg Sturmwind, schickt Euch über die Hauptstadt der Menschen hinaus. Als Neuankömmling auf Azeroth seid Ihr eingeladen, die verbündeten Völker der Allianz aus erster Hand kennenzulernen. Die Reise führt Euch über die Burg hinaus, um die besonderen Kulturen, Traditionen und die Stärke jener kennenzulernen, die an Sturmwinds Seite stehen."},{t="Audienzen bei den Oberhäuptern",b="Eure Reise führt Euch über Land und Meer zu den Anführern der Allianz. In Eisenschmiede begegnet Ihr König Magni Bronzebart in den Berghallen und Obertüftler Gelbin Mekkadrill, dem Anführer der vertriebenen Gnome. In Darnassus auf Teldrassil trefft Ihr Hohepriesterin Tyrande Wisperwind. Ihre Städte und Völker offenbaren die Bande zwischen Menschen, Zwergen, Gnomen und Nachtelfen."},{t="Eine Welt braucht Hilfe",b="Nach der langen Reise kehrt Ihr nach Sturmwind zurück. Mehr über Azeroth zu wissen hilft Euch, Eurem eigenen Volk beizustehen, während Euer Orden sich darauf vorbereitet, in Dalaran Fuß zu fassen. Vorerst brauchen die bedrängten Gebiete nahe der Hauptstadt Hilfe, angefangen beim notleidenden Ackerland von Westfall."}},faq={{q="Was ist die Quest Exploring the Alliance?",a="Ihr reist durch Azeroth, um die Anführer der wichtigsten Machtzentren der Allianz zu treffen. Die Reise führt Euch vor die Herrscher von Eisenschmiede und Darnassus sowie vor Obertüftler Gelbin Mekkadrill, den Anführer der Gnome im Exil.",al={"quest exploring the alliance","was ist diese quest"}},{q="Wer ist Randal Emerson?",a="Randal Emerson ist ein Bediensteter in der südlichen Vorkammer von Burg Sturmwind. Er weist Reisenden den Weg zu den anderen Hauptstädten.",al={"randal emerson","wer weist den weg"}},{q="Welche Anführer müssen auf dieser Reise besucht werden?",a="Ihr besucht König Magni Bronzebart in Eisenschmiede, Obertüftler Gelbin Mekkadrill und Hohepriesterin Tyrande Wisperwind in Darnassus. Jeder von ihnen führt eines der tragenden Völker und besitzt Autorität innerhalb der Allianz.",al={"besuchte anführer","mit wem sprechen"}},{q="Warum wird beim Abschluss der Quest Dalaran erwähnt?",a="Euer Orden bereitet sich darauf vor, in Dalaran Fuß zu fassen. Während diese Vorbereitungen laufen, werdet Ihr ermutigt, Azeroth kennenzulernen und den umliegenden Gebieten zu helfen.",al={"warum wird dalaran erwähnt","orden in dalaran"}},{q="Wohin führt der Weg nach Abschluss dieser Reise?",a="Nach Eurer Rückkehr nach Burg Sturmwind zieht Ihr in die ländlichen Gebiete nahe der Hauptstadt, genauer gesagt nach Westfall. Die bedrängten Gemeinden dort brauchen dringend fähige Verteidiger.",al={"wohin als nächstes","nach exploring the alliance"}},{q="Warum wird der Abenteurer als Gast der Allianz behandelt?",a="Ihr werdet als Außenstehender behandelt, der gerade erst auf Azeroth eingetroffen ist, und sollt die weitere Welt verstehen, um Euer eigenes Volk schützen und unterstützen zu können. Die Reise macht Euch mit den vielfältigen Kulturen der Allianz vertraut.",al={"gast der allianz","warum gast"}}},fp="22,167,22.330.0,29.363.0,22.273.0,41.223.0,22.133.0,50.195.0,51.170.0,55.165.0,57.211.0"}
P.entries["quest:94"] = {n="Ein wachsames Auge",s="Im Turm von Azora beobachtet Theocritus Morganth aus der Ferne. Er schickt Reisende nach Osten ins Rotkammgebirge, um eine verzauberte Glyphe an einer alten Löwenstatue nahe dem Turm von Ilgalar anzubringen.",h="Im Turm von Azora beobachtet Theocritus Morganth aus der Ferne.",kw={"elwynn","glyphe von azora","morganth","old lion statue","rotkammgebirge","theocritus","turm von azora","der turm von ilgalar"},ang={["class:Mage"]="Als Magier seht Ihr, wie arkane Weissagung große Entfernungen überwinden kann. Theocritus nutzt Methoden aus Elwynn, während Morganth abtrünnige Zauberei betreibt.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, die Grenze zwischen dem Wald von Elwynn und den umkämpften Siedlungen des Rotkammgebirges vor abtrünnigen menschlichen Zauberwirkern wie Morganth zu schützen."},sec={{t="Rivalität über die Grenze",b="Von seinem Turm im östlichen Wald von Elwynn aus beobachtet Theocritus die Hügel. Sein Rivale Morganth ist ein mächtiger Zauberer, der den Turm von Ilgalar im Rotkammgebirge für sich beansprucht hat. Aus Furcht, Morganths dunkle Magie könnte die Grenze überschreiten, erschuf Theocritus das Auge von Azora, um den abtrünnigen Zauberer aus der Ferne zu beobachten."},{t="Die Wacht des Löwen",b="Ein Blick aus der Ferne kann Theocritus nicht zeigen, was Morganth plant. Deshalb gibt er Reisenden die Glyphe von Azora und schickt sie zur Old Lion Statue nahe dem Turm von Ilgalar. Die Statue hält dort seit Jahrzehnten Wache.\n\nSetzt die Glyphe in die abgenutzte Vertiefung an ihrem Sockel. Eine arkane Verbindung reicht dann zurück nach Azora und lässt Theocritus in den Geist seines Rivalen blicken."}},faq={{q="Wer ist Theocritus?",a="Theocritus ist ein Zauberer der Allianz, der im Turm von Azora im östlichen Wald von Elwynn lebt. Er erforscht Magie, um die Region vor abtrünnigen Zauberwirkern zu schützen, insbesondere vor Morganth.",al={"theocritus","magier im turm von azora","wer vergibt ein wachsames auge"}},{q="Wer ist Morganth?",a="Morganth ist ein abtrünniger menschlicher Zauberer, der den Turm von Ilgalar im Rotkammgebirge zu seiner Festung gemacht hat. Er ist Theocritus' erbitterter Rivale, und Theocritus fürchtet seine Machenschaften gegen die umliegenden Lande.",al={"morganth","wer ist morganth","rivalisierender magier"}},{q="Wo befindet sich die Old Lion Statue?",a="Die Old Lion Statue steht auf den Bergrücken über dem Turm von Ilgalar in den östlichen Hügeln des Rotkammgebirges. Eine flache Vertiefung an ihrem Sockel kann die Glyphe von Azora aufnehmen.",al={"standort der löwenstatue","wo ist die statue","wo glyphe von azora einsetzen"}},{q="Was bewirkt die Glyphe von Azora?",a="Die Glyphe von Azora ist ein verzauberter Stein, den Theocritus erschaffen hat. In die Löwenstatue nahe dem Turm von Ilgalar eingesetzt, trägt sie seinen arkanen Lauschzauber und lässt ihn Morganths Gedanken erforschen.",al={"glyphe von azora","was ist die glyphe"}},{q="Was ist der Turm von Ilgalar?",a="Der Turm von Ilgalar ist ein abgelegener Steinturm hoch in den zerklüfteten Felsen des östlichen Rotkammgebirges. Morganth und seine Diener halten ihn besetzt und verteidigen ihn.",al={"der turm von ilgalar","ilgalar"}},{q="Was folgt nach dem Einsetzen der Glyphe?",a="Nachdem Ihr die Glyphe von Azora in die Statue eingesetzt habt, spricht Theocritus durch den Stein und bietet Euch Looking Further an. Er beginnt, Morganths Pläne aufzudecken.",al={"nächste quest","was kommt nach ein wachsames auge"}}},fx={["0c307b8a"]={q="Warum möchte Theocritus, dass dies getan wird?",a="Morganth ist ein rücksichtsloser Magier von beeindruckender Macht, der sich im Turm von Ilgalar verschanzt hat. Obwohl Theocritus seinen Rivalen mithilfe der Wahrsagemagie der Glyphe von Azora beobachten kann, reicht es nicht mehr aus, ihn nur zu sehen. Indem Ihr die Glyphe von Azora an der nahegelegenen Löwenstatue anbringt, hofft Theocritus, in Morganths Geist einzudringen und herauszufinden, was der dunkle Zauberer plant, bevor er es über die Region entfesselt.",al={"theocritus beweggrund","warum die glyphe von azora platzieren","warum morganth ausspionieren"}}},fp="14,186,27.296.0,16.348.0,18.173.0,16.201.0,37.175.0,32.188.0,29.144.0,35.150.0"}
P.entries["quest:940"] = {n="Teldrassil",s="Nachdem die Harpyien zurückgedrängt sind, schickt Arynia Wolkenbruch Euch mit Neuigkeiten für die Führung der Kaldorei nach Darnassus. Die gravierte Rinde berichtet Erzdruide Fandral Hirschhaupt, was die Äste Teldrassils plagt.",h="Nachdem die Harpyien zurückgedrängt sind, schickt Arynia Wolkenbruch Euch mit Neuigkeiten für die Führung der...",kw={"arynia wolkenbruch","die enklave des cenarius","darnassus","fandral hirschhaupt","unsterblichkeit","gravierte rinde","kaldorei","oracle tree","teldrassil"},ang={["class:Druid"]="Als Druide bringt Ihr Nachricht vom Oracle Tree zum Anführer des Zirkels des Cenarius. Dort zeigt sich der Kampf, Teldrassils natürliches Gleichgewicht von Verderbnis zu reinigen.",["faction:Alliance"]="Als Streiter der Allianz werdet Ihr förmlich mit der Hauptstadt der Nachtelfen und ihrer strengen Führung bekannt gemacht.",["race:NightElf"]="Als Nachtelf bringt Ihr Erzdruide Hirschhaupt den Bericht und erfahrt von seinem Bestreben, die Unsterblichkeit der Kaldorei durch Teldrassils geplagte Äste wiederherzustellen."},sec={{t="Ein Bote zur Steinstadt",b="Schildwache Arynia Wolkenbruch gibt Euch ein Stück gravierte Rinde, nachdem Ihr die Harpyien aus ihren Nestern auf der Lichtung des Orakels vertrieben habt. The Oracle Tree wacht über den Wald, und nun kann Arynia der Führung der Kaldorei Nachricht senden. Ihr tragt ihren Bericht durch die Wildnis nach Darnassus, dem großen Wald aus Stein, und übergebt ihn Erzdruide Fandral Hirschhaupt."},{t="Hirschhaupts Ehrgeiz und Frustration",b="Fandral Hirschhaupt nimmt den Bericht mit Dankbarkeit und Frustration entgegen. Die Harpyien wurden zurückgedrängt, doch überall auf Teldrassil folgt eine Bedrohung auf die nächste. Hirschhaupt setzte sich für die Pflanzung des neuen Weltbaums ein, um die verlorene Unsterblichkeit der Nachtelfen zurückzugewinnen. Die Leiden in seinen Ästen erinnern ihn daran, dass seine Arbeit noch lange nicht vollendet ist."}},faq={{q="Was ist das Ziel der Quest „Teldrassil“?",a="Ihr bringt den Bericht von Schildwache Arynia Wolkenbruch vom Oracle Tree zu Erzdruide Fandral Hirschhaupt in Darnassus. Die gravierte Rinde überbringt Neuigkeiten über den Baum, nachdem Ihr die Harpyien zurückgedrängt habt.",al={"teldrassil questziel","was bewirkt diese quest","teldrassil botengang"}},{q="Wer ist Schildwache Arynia Wolkenbruch?",a="Schildwache Arynia Wolkenbruch ist eine Nachtelfen-Schildwache, die nahe dem Oracle Tree in Teldrassils Wildnis stationiert ist. Sie überwacht Bedrohungen in der Region, darunter die Bloodfeather-Harpyien, und stimmt die Verteidigung des Waldes mit Darnassus ab.",al={"arynia wolkenbruch hintergrund","wer startet die quest teldrassil"}},{q="Warum nennt Arynia Darnassus einen „Wald aus Stein“?",a="Darnassus wird als Wald aus Stein bezeichnet, weil seine Tempel, Brücken und Pavillons aus Marmor und Stein erbaut sind. Die Nachtelfen leben in der Krone des Weltbaums, während sich die Stadt zwischen diesen Bauwerken erhebt.",al={"wald aus stein bedeutung","warum wald aus stein"}},{q="Warum ist Fandral Hirschhaupt wegen des Berichts des Oracle Tree so besorgt?",a="Fandral Hirschhaupt ist besorgt, weil der Bericht Verderbnis und Unruhe unter Teldrassils Wildtieren beschreibt. Er setzte sich für die Pflanzung des Baums ein, um die Unsterblichkeit der Kaldorei wiederherzustellen, nachdem Nordrassil im Dritten Krieg beschädigt worden war. Diese Leiden bedrohen sein Vorhaben.",al={"fandral hirschhaupt reaktion","warum ist hirschhaupt besorgt"}},{q="Welche Quest führt hierher, und welche folgt darauf?",a="Ihr kommt hierher, nachdem Ihr Euch in The Enchanted Glade um die Harpyien gekümmert habt, die den Oracle Tree bedrohen. Nachdem Ihr Erzdruide Hirschhaupt den Bericht übergeben habt, schickt er Euch mit „Der Hain der Uralten“ zur Dunkelküste.",al={"teldrassil questreihe","welche quest folgt"}},{q="Wo ist Erzdruide Fandral Hirschhaupt zu finden?",a="Erzdruide Fandral Hirschhaupt lebt in Darnassus, am höchsten Punkt der Enklave des Cenarius. Dort beaufsichtigt er die Druiden des Zirkels des Cenarius und lenkt die Regierung der Kaldorei.",al={"wo ist fandral","fandral hirschhaupt aufenthaltsort"}}},fx={d4229979={q="Warum möchte Schildwache Arynia Wolkenbruch, dass dieser Bericht übermittelt wird?",a="Arynia muss sicherstellen, dass Erzdruide Fandral Hirschhaupt den Bericht über den Baum des Orakels erhält, damit Darnassus über den Zustand der Zweige informiert bleibt. Die Wälder haben unter dem Befall durch Harpyien und unnatürlicher Verderbnis gelitten, und frühere Boten haben es nicht sicher geschafft. Da die Ruhe auf der Lichtung des Orakels wiederhergestellt ist, müssen die Nachrichten den Erzdruiden erreichen, damit die Führung den Zustand des Weltenbaums beurteilen kann.",al={"warum bericht an fandral schicken","arynia wolkenbruch beweggrund","warum will arynia, dass der bericht übermittelt wird"}},["174bd7d2"]={q="Warum schickt Arynia Wolkenbruch Euch anstatt eines anderen Boten?",a="Frühere Boten, die über die Waldpfade geschickt wurden, haben Darnassus nicht erreicht oder gingen unterwegs verloren, was Arynia zögern lässt, einen weiteren gewöhnlichen Läufer zu riskieren. Da Ihr Euren Mut und Eure Kampfkraft durch die Säuberung der Harpyien von der Lichtung des Orakels bewiesen habt, habt Ihr die Gunst des Waldes gewonnen und gezeigt, dass Ihr Euch und die Nachricht auf den gefährlichen Straßen zur Stadt verteidigen könnt.",al={"warum schickt sie mich nach darnassus","warum keinen anderen boten schicken","warum arynia euch braucht"}}},fp="10,203,29.359.0,35.336.0,46.188.0,35.219.0,51.210.0,68.276.0,48.200.0,47.172.0"}
P.entries["quest:94003"] = {n="The Skybreaker Bulwark",s="Am Schrein von Akir hat Zaal Stormshield das Bollwerk der Himmelsbrecher in seiner Gewalt. Der letzte Skybreaker will es von dem Kultisten zurückerlangen, der es gestohlen hat.",h="Am Schrein von Akir hat Zaal Stormshield das Bollwerk der Himmelsbrecher in seiner Gewalt.",kw={"al'aketh","schrein von akir","skybreaker","bollwerk der himmelsbrecher","skybreaker defense","das bollwerk der himmelsbrecher","zaal stormshield","insel zephras"},ang={["class:Paladin"]="Als Paladin mögt Ihr es schätzen, ein gesegnetes Erbstück aus den Händen eines verderbten Kultisten zurückzuholen.",["class:Warrior"]="Als Krieger könnt Ihr die Technik „Skybreaker Defense“ erlernen, indem Ihr den Ahnenschild zurückholt."},sec={{t="Ein gefallenes Geschlecht",b="Auf der Insel Zephras haben die Al'Aketh die Skybreakers erschlagen und nur einen Überlebenden zurückgelassen. Den Letzten der Familie plagen tiefe Trauer und bittere Scham über den Verlust ihres bedeutendsten Erbstücks. Der Kultist Zaal Stormshield nahm das Bollwerk der Himmelsbrecher an sich und lauert nun am Schrein von Akir."},{t="Der heilige Schild",b="Der Familientradition nach schützt das Bollwerk der Himmelsbrecher jeden, der wahrhaft würdig ist, es zu führen. Der letzte Skybreaker hält Zaal seiner göttlichen Gunst für unwürdig. Deshalb sucht der Überlebende einen Abenteurer, der den Dieb am Schrein von Akir niederstreckt und den Ahnenschild zurückholt. Als Gegenleistung bietet der Skybreaker eine Ausbildung in der Technik „Skybreaker Defense“ an."}},faq={{q="Wer sind die Skybreakers?",a="Die Skybreakers sind ein uraltes Geschlecht auf der Insel Zephras, das von den Al'Aketh beinahe ausgelöscht wurde. Derjenige, der um den Schild bittet, ist der einzige Überlebende.",al={"wer sind die skybreakers","familie der skybreakers"}},{q="Was ist das Bollwerk der Himmelsbrecher?",a="Das Bollwerk der Himmelsbrecher ist ein Ahnenschild des Geschlechts der Skybreakers auf der Insel Zephras. Der Familientradition nach kann niemandem ein Leid geschehen, der würdig ist, ihn zu führen.",al={"was ist das bollwerk der himmelsbrecher","der schild","geschichte des skybreaker-schilds"}},{q="Wer sind die Al'Aketh?",a="Die Al'Aketh erschlugen die Familie der Skybreakers auf der Insel Zephras und ließen nur einen Überlebenden zurück, der ihren Verlust betrauert.",al={"wer hat die skybreakers getötet","was sind die alaketh","alaketh"}},{q="Wer ist Zaal Stormshield?",a="Zaal Stormshield ist ein Kultist, der das Bollwerk der Himmelsbrecher an sich nahm, nachdem die Familie der Skybreakers erschlagen worden war. Er lauert mit dem Erbstück am Schrein von Akir auf der Insel Zephras.",al={"wer hat den schild","zaal","stormshield"}},{q="Wo liegt der Schrein von Akir?",a="Der Schrein von Akir liegt auf der Insel Zephras. Zaal Stormshield lauert dort mit dem gestohlenen Bollwerk der Himmelsbrecher.",al={"wo ist zaal","standort des schreins von akir","wo den schild finden"}},{q="Warum muss das Bollwerk zurückgeholt werden?",a="Der letzte Skybreaker will das Bollwerk zurückerlangen, um die Schande der Familie zu tilgen und das heilige Relikt unwürdigen Händen zu entreißen. Als Gegenleistung lehrt der Überlebende die Technik „Skybreaker Defense“.",al={"warum den schild zurückholen","was ist skybreaker defense","belohnung für den schild"}}},fp="22,144,16.273.0,17.345.0,24.143.0,31.153.0,21.98.0,24.166.0,28.103.0,34.187.0"}
P.entries["quest:94006"] = {n="The Great Ursera Spirit",s="Ein Druide schickt Euch zu Urs'endris, einem Geist auf Zephras, der Druiden seit Generationen die ursera-Gestalt lehrt. Sein Reich verdorrt, und Urs'endris kann Eure Studien weiterführen.",h="Ein Druide schickt Euch zu Urs'endris, einem Geist auf Zephras, der Druiden seit Generationen die...",kw={"druide","wasserfälle","schrein von akir","geist","urs'endris","ursera","valanaar","zephras"},ang={["class:Druid"]="Als Druide haben Euch Eure Studien zu Urs'endris geführt, der Druiden seit Generationen die ursera-Gestalt lehrt."},sec={{t="Der große Geist",b="Ein Druide schickt Euch zu Urs'endris bei den Wasserfällen nordöstlich von Valanaar. Eure druidischen Studien haben Euch zu einer Begegnung mit einem der großen Geister von Zephras geführt. Urs'endris lehrt Druiden seit Generationen, die ursera-Gestalt anzunehmen, und sein Reich verdorrt und fällt in den Himmel."}},faq={{q="Wer ist Urs'endris?",a="Urs'endris ist ein weiser Geist auf Zephras, der Druiden seit Generationen lehrt, die ursera-Gestalt anzunehmen.",al={"urs'endris wer","großer geist urs","ursera-geist"}},{q="Wo kann ich Urs'endris finden?",a="Urs'endris ist bei den Wasserfällen nordöstlich von Valanaar, nahe dem Schrein von Akir.",al={"urs'endris standort","wo ist urs'endris","den geist treffen"}},{q="Warum werde ich zu Urs'endris geschickt?",a="Eure druidischen Studien sind weit genug fortgeschritten, um einem der großen Geister von Zephras zu begegnen, und Urs'endris kann Euch weiter unterweisen.",al={"warum urs'endris treffen","druide geist quest","ursera-studien"}},{q="Was geschieht mit Urs'endris' Reich?",a="Urs'endris' Reich hat begonnen, zu verdorren und in den Himmel zu fallen.",al={"verdorrendes reich","zephras fällt","was stimmt dort nicht"}},{q="Was ist die ursera-Gestalt?",a="Die ursera-Gestalt ist eine Form, die anzunehmen Urs'endris Druiden seit Generationen lehrt.",al={"ursera-gestalt","weg der klaue","ursera"}}},fp="23,185,16.270.0,18.102.0,28.76.0,34.132.0,41.62.0,25.80.0"}
P.entries["quest:94007"] = {n="Taming the Beast",s="In Valanaar kann Quel'ana Quickgale Euch beibringen, ein Tier zu zähmen. Eure Zeit im Hochland hat Euch darauf vorbereitet, einen tierischen Gefährten zu suchen.",h="In Valanaar kann Quel'ana Quickgale Euch beibringen, ein Tier zu zähmen.",kw={"tierischer gefährte","tierzähmung","hochland","quel'ana quickgale","taming the beast","valanaar"},sec={{t="Ein neuer Gefährte",b="Euer Gastgeber glaubt, dass Ihr nach Eurer Zeit im Hochland bereit seid, einen tierischen Gefährten zu suchen. Geht nach Valanaar und sprecht mit Quel'ana Quickgale. Er wird Euch die Kunst der Tierzähmung beibringen."}},faq={{q="Wer lehrt die Tierzähmung?",a="Quel'ana Quickgale bringt Euch in Valanaar bei, Tiere zu zähmen.",al={"wer ist quel'ana quickgale","lehrer für tierzähmung"}},{q="Wo finde ich Quel'ana Quickgale?",a="Quel'ana Quickgale ist in Valanaar, dem Hafen im Südosten.",al={"wo ist quel'ana","valanaar tierzähmung"}},{q="Warum gehe ich nach Valanaar?",a="Ihr werdet nach Valanaar geschickt, um mit Quel'ana Quickgale zu sprechen und die ersten Schritte der Tierzähmung zu lernen.",al={"warum valanaar","quest tier zähmen"}},{q="Was lerne ich?",a="Quel'ana Quickgale wird Euch beibringen, ein Tier zu zähmen, damit Ihr einen tierischen Gefährten suchen könnt.",al={"was ist tierzähmung","tierischer gefährte"}}},fp="16,135,15.187.0,25.58.0,35.61.0,27.92.0,19.86.0"}
P.entries["quest:94013"] = {n="Taming the Beast",s="Quel'ana Quickgale stellt Euch eine letzte Prüfung: Zähmt einen Vuldren-Alpha. Wenn Ihr sie meistert, seid Ihr für die tieferen Lehren Eurer Klasse bereit.",h="Quel'ana Quickgale stellt Euch eine letzte Prüfung: Zähmt einen Vuldren-Alpha.",kw={"tierischer gefährte","böenbeerentiefland","quel'ana quickgale","zähmerrute","taming the beast","valanaar","vuldren-alpha","insel zephras"},sec={{t="Die letzte Prüfung",b="Quel'ana gibt Euch eine Zähmerrute und schickt Euch ins Böenbeerentiefland. Dort sollt Ihr einen Vuldren-Alpha zähmen. Bringt ihm die Rute dann nach Valanaar zurück. Diese Prüfung beweist Eure Meisterschaft und bereitet Euch auf tiefere Lehren Eurer Klasse vor."},{t="Eine neue Lektion",b="Nach Eurer Rückkehr sagt Quel'ana, Ihr hättet die Grundlagen gelernt. Er bietet an, Euch beizubringen, wie Ihr eine dauerhafte Bindung zu einem tierischen Gefährten aufbaut. Er drängt Euch, dieses Wissen zum Wohl der Klasse weiterzutragen, die die Insel Zephras braucht."}},faq={{q="Was soll ich für Quel'ana zähmen?",a="Quel'ana bittet Euch, mit der Zähmerrute einen Vuldren-Alpha im Böenbeerentiefland zu zähmen.",al={"vuldren-alpha zähmen","welches wildtier","alpha zähmen"}},{q="Wo finde ich den Vuldren-Alpha?",a="Der Vuldren-Alpha ist im Böenbeerentiefland.",al={"alpha fundort","böenbeerentiefland","wo wildtier zähmen"}},{q="Wozu dient die Zähmerrute?",a="Quel'ana gibt Euch die Zähmerrute, damit Ihr einen Vuldren-Alpha zähmt.",al={"zweck der rute","zähmerrute quest","wie rute benutzen"}},{q="Wohin bringe ich die Zähmerrute zurück?",a="Bringt die Zähmerrute zu Quel'ana Quickgale in Valanaar zurück.",al={"rute zurückbringen","quelana aufenthaltsort","wohin zähmerrute zurückbringen"}},{q="Was lerne ich danach?",a="Quel'ana sagt, er könne Euch beibringen, wie Ihr eine dauerhafte Bindung zu einem tierischen Gefährten aufbaut.",al={"nächste lektion","bindung zu tierischem gefährten","was kommt danach"}}},fp="16,136,15.228.0,12.223.1,34.88.0,34.47.0,27.58.0,33.56.0,29.79.0"}
P.entries["quest:94050"] = {n="Training the Beast",s="In Valanaar trefft Ihr Quel'dora Quickgale, um zu lernen, wie Ihr Euer Tier ausbildet. Ihre Lehren helfen Euch, für es zu sorgen und es zu führen.",h="In Valanaar trefft Ihr Quel'dora Quickgale, um zu lernen, wie Ihr Euer Tier ausbildet.",kw={"tier füttern","jäger","tierausbildung","quel'dora quickgale","tier wiederbeleben","tier zähmen","training the beast","valanaar"},ang={["class:Hunter"]="Als Jäger lernt Ihr, ein Tier auszubilden und zu führen, das Ihr bereits zähmen könnt."},sec={{t="Quel'doras Lehren",b="Euer Jägerkollege schickt Euch zu seiner Schwester Quel'dora Quickgale in Valanaar. Ihr wisst bereits, wie Ihr ein Tier zähmt. Nun kann Quel'dora Euch beibringen, Euren Begleiter auszubilden."},{t="Die Verantwortung eines Jägers",b="Quel'dora lehrt Euch, Euer Tier zu führen, ihm neue Fähigkeiten beizubringen, es zu füttern und wiederzubeleben, falls es im Kampf fällt. Sie ermahnt Euch, das Gleichgewicht zu achten und die Natur um Euch herum ehrfürchtig zu betrachten."}},faq={{q="Wer ist Quel'dora Quickgale?",a="Quel'dora Quickgale ist die Schwester des Jägers, der Euch schickt, um die Tierausbildung zu erlernen.",al={"wer ist queldora","quel'dora","quickgale"}},{q="Wo kann ich Quel'dora finden?",a="Quel'dora Quickgale ist in Valanaar.",al={"wo ist queldora","quel'dora standort","valanaar lehrerin"}},{q="Was lehrt Quel'dora?",a="Quel'dora lehrt Euch, Euer Tier auszubilden und zu führen, ihm Fähigkeiten beizubringen, es zu füttern und wiederzubeleben, falls es im Kampf fällt.",al={"tierausbildung","eigenes tier ausbilden","was kann ein tierausbilder lehren"}},{q="Kann ich bereits ein Tier zähmen?",a="Der Jäger, der Euch zu Quel'dora schickt, sagt, dass Ihr bereits die Macht habt, ein Tier zu zähmen.",al={"tier zähmen","tierzähmung","kann ein jäger tiere zähmen"}},{q="Worum bittet mich der Jäger?",a="Der Jäger bittet Euch, mit Quel'dora Quickgale in Valanaar zu sprechen.",al={"training the beast","tierausbilder quest","mit queldora sprechen"}},{q="Was sagt Quel'dora über die Natur?",a="Quel'dora ermahnt Euch, das Gleichgewicht zu achten und in Ehrfurcht vor der Natur um Euch herum zu leben.",al={"natur achten","gleichgewicht","quel'doras rat"}}},fp="18,119,20.166.0,17.191.0,27.84.0,27.35.0,26.116.0,25.84.0,34.66.0,37.84.0"}
P.entries["quest:941"] = {n="Das Einpflanzen des Herzens",s="Am Al'Amethsee helft Ihr Denalan, ein hölzernes Herz aus einem verderbten Timberling zu pflegen. Er entfernt das Moos und bittet Euch dann, es in seinen Pflanzkasten zu setzen, um zu sehen, ob es geheilt werden kann.",h="Am Al'Amethsee helft Ihr Denalan, ein hölzernes Herz aus einem verderbten Timberling zu pflegen.",kw={"blackmoss the fetid","gereinigtes herz","denalan","al'amethsee","pflanzkasten","besudeltes herz","teldrassil","timberling"},ang={["class:Druid"]="Als Druide seht Ihr, wie nährstoffreiche Erde das Innerste eines verderbten Timberlings reinigt. Es ist ein beruhigendes Zeichen dafür, dass natürliche Pflege die unnatürliche Verderbnis zurückdrängen kann, die die Äste des Weltbaums heimsucht.",["profession:Herbalism"]="Denalans meisterhafter Umgang mit nährstoffreicher Erde und der Erneuerung von Pflanzen zeigt, wie das Studium des Bodens helfen kann, geschädigte Pflanzen zu heilen.",["race:NightElf"]="Als Nachtelf erkennt Ihr die Hingabe der Kaldorei an die Pflege der Natur darin, wie lebendes Holz wiederhergestellt und gefallenen Waldgeistern Leben entlockt wird, während Teldrassil unter beunruhigenden Leiden ächzt."},sec={{t="Eine zweite Lebenschance",b="Denalan hat das faulige Moos von dem hölzernen Herzen gekratzt, das aus Blackmoss the Fetid stammt, einem verderbten Timberling. Doch noch immer pulsiert eine unnatürliche Verderbnis im Holz. Also vertraut der Kräuterkundige auf seine jahrelange Erfahrung in der Pflanzen- und Bodenpflege. Er bittet Euch, das Herz in seinem eigenen Pflanzkasten zu vergraben, und hofft, seine angereicherte Erde könne dessen verbliebene natürliche Lebenskraft wieder gesunden lassen."},{t="Das Wunder angereicherter Erde",b="Das Herz gräbt sich in den Boden ein, sobald es die Erde berührt, als folge es einem Urinstinkt. Augenblicke später kommt es wieder hervor, von Verderbnis gereinigt und von einem sanften, zutraulichen Leuchten gewärmt. Das Herz einer gefallenen, besudelten Kreatur ist geläutert worden. Dieser Wandel zeigt, wie sorgsame Pflege und heilige Erde die Harmonie wiederherstellen können, wenn unnatürliche Seuchen die wilden Bewohner Teldrassils befallen."}},faq={{q="Woher stammt dieses besudelte Herz?",a="Das Herz stammt aus Blackmoss the Fetid, einem verderbten Timberling an den Ufern des Al'Amethsees. Als es geborgen wurde, war es von fauligem Moos überwuchert, das Denalan abkratzte.",al={"herkunft des herzens","woher stammt das herz","blackmoss herz"}},{q="Wer ist Denalan?",a="Denalan ist ein Nachtelf, Botaniker und Kräuterkundiger mit einem abgeschiedenen Lager am Ostufer des Al'Amethsees. Er erforscht Teldrassils Pflanzenwelt, untersucht die seltsame Verderbnis, die sich in dessen Ästen ausbreitet, und mischt angereicherte Erden.",al={"wer ist denalan","denalans geschichte"}},{q="Warum soll das Herz in einen Pflanzkasten, statt es zu zerstören?",a="Denalan glaubt, dass die Natur verstanden und geheilt werden sollte, statt sie einfach zu zerstören. Er hofft, seine nährstoffreiche Erde könne die Verderbnis vertreiben und die ursprüngliche Lebenskraft des Herzens wiederherstellen.",al={"warum das herz einpflanzen","warum das herz heilen"}},{q="Was geschieht, wenn Ihr das Herz vergrabt?",a="Wenn das Herz die Erde berührt, gräbt es sich hinein. Sekunden später windet es sich wieder an die Oberfläche, von seiner Verderbnis gereinigt und als lebendiger Begleiter sanft pulsierend.",al={"was geschieht im pflanzkasten","herz gräbt sich ein"}},{q="Heilt das die Verderbnis der Timberlinge?",a="Nur dieses eine geborgene Herz wird geheilt. Sein Wandel zeigt, dass einzelne Pflanzengeister durch Pflege und nährstoffreiche Erde gereinigt werden können, während sich die Verderbnis weiterhin über Teldrassil ausbreitet.",al={"werden timberlinge geheilt","timberlinge heilen"}},{q="Was macht die Erde in Denalans Pflanzkasten so besonders?",a="Denalan hat viel Zeit damit verbracht, rund um den Al'Amethsee mit Kompost und nährstoffreichen Erdmischungen zu experimentieren. Er hat die Erde so zusammengestellt, dass sie kränkelnde Pflanzen belebt und schleichende Fäulnis vertreibt.",al={"denalans erde","pflanzkastenerde"}}},fp="18,188,23.366.0,29.383.1,40.167.0,15.228.0,56.176.0,37.167.1,49.183.0,45.184.0"}
P.entries["quest:942"] = {n="Der geistesabwesende Ausgrabungsleiter",s="An der Dunkelküste führt Euch ein seltsames Fossil über das große Meer ins Sumpfland. Chefarchäologe Grauflaum schickt Euch zu Archäologe Magenbitter im Hafen von Menethil, in der Hoffnung, dass er seine Geheimnisse lüften kann.",h="An der Dunkelküste führt Euch ein seltsames Fossil über das große Meer ins Sumpfland.",kw={"der geistesabwesende ausgrabungsleiter","archäologe magenbitter","chefarchäologe grauflaum","dunkelküste","tiefenwassertaverne","forscherliga","hafen von menethil","geheimnisvolles fossil"},ang={["faction:Alliance"]="Als Abenteurer der Allianz reist Ihr auf den Schifffahrtsrouten der Allianz von Kalimdor über das Meer zum Hafen von Menethil. Diese Routen verbinden die Zweigstellen der Liga miteinander.",["race:Dwarf"]="Als Zwerg erkennt Ihr, wie weit der Einfluss der Forscherliga reicht. Ihre Feldarbeit im entlegenen Kalimdor verbindet sie mit Gelehrtenkollegen in Khaz Modan."},sec={{t="Eine kuriose Entdeckung",b="Chefarchäologe Grauflaum erkennt eine Ähnlichkeit zwischen dem seltsamen Fossil von der Dunkelküste und einem Relikt, das auf einer Konferenz der Forscherliga in Eisenschmiede gezeigt wurde. Archäologe Magenbitter stellte jenes Relikt vor und glaubte, solche Fossilien würden Kräfte bergen, die darauf warteten, entfesselt zu werden. Grauflaum hält Magenbitter für den einzigen Zwerg, der erkennen kann, was diesen Fund aus Kalimdor so außergewöhnlich macht."},{t="Eine Reise übers Meer",b="Ihr bringt das Geheimnisvolle Fossil von Kalimdor in die Östlichen Königreiche. Magenbitter wurde zuletzt in der Tiefenwassertaverne im Hafen von Menethil gesehen, wo er auf eine bewaffnete Eskorte zum Ausgrabungsgelände von Whelgar wartete. Als Ihr ihm das Fossil bringt, reicht die Erkundung der Dunkelküste als Teil einer umfassenderen archäologischen Untersuchung über Kontinente hinweg."}},faq={{q="Warum schickt Grauflaum mich bis zum Hafen von Menethil?",a="Chefarchäologe Grauflaum erinnert sich, dass Archäologe Magenbitter auf einer jährlichen Konferenz der Forscherliga in Eisenschmiede ein identisches Relikt zeigte. Er glaubt, dass Magenbitter weiß, wie sich dessen verborgene Kraft entfesseln lässt, und schickt Euch deshalb zu dessen letztem bekannten Aufenthaltsort im Hafen von Menethil.",al={"warum zum hafen von menethil","grauflaums fossilauftrag","warum ins sumpfland"}},{q="Wer ist Archäologe Magenbitter?",a="Archäologe Magenbitter ist ein Forscher der Forscherliga, der im Sumpfland stationiert ist. Er wohnt in der Tiefenwassertaverne im Hafen von Menethil und bereitet sich auf eine Expedition zum gefährlichen Ausgrabungsgelände von Whelgar vor.",al={"wer ist magenbitter","archäologe magenbitter hintergrund"}},{q="Was ist das Geheimnisvolle Fossil?",a="Das Geheimnisvolle Fossil ist ein uraltes Fundstück von der Dunkelküste. Magenbitter behauptete einst, ein identisches Exemplar, das er untersucht hatte, berge verborgene magische oder historische Kraft, die darauf warte, entfesselt zu werden.",al={"was ist das fossil","geheimnisvolles fossil herkunft","wirrbarts fossil"}},{q="Was sagt Magenbitter, wenn Ihr das Fossil überbringt?",a="Magenbitter ist erstaunt, dass ein Relikt, das seinem eigenen Forschungsobjekt gleicht, aus dem fernen Kalimdor stammt. Die Entdeckung bestätigt, dass die uralte Geschichte beide Landmassen verbindet.",al={"magenbitters reaktion","das fossil abgeben"}},{q="Wohin möchte Magenbitter als Nächstes reisen?",a="Magenbitter wartet im Hafen von Menethil auf eine Eskorte ins Landesinnere zum Ausgrabungsgelände von Whelgar, einer bedeutenden Ausgrabungsstätte im Sumpfland.",al={"wohin reist magenbitter","magenbitters ausgrabung"}},{q="Wie fügt sich diese Quest in den Handlungsstrang von „Der geistesabwesende Ausgrabungsleiter“ ein?",a="Nachdem Ihr Ausgrabungsleiter Wirrbart an der Dunkelküste eskortiert und gerettet habt, untersucht Ihr sein ausgegrabenes Relikt gemeinsam mit Grauflaum. Die Nachforschungen verlagern sich dann vom nördlichen Kalimdor zu Experten der Forscherliga in den Östlichen Königreichen.",al={"der geistesabwesende ausgrabungsleiter teil vier","zusammenhang der questreihe"}}},fx={["5b36a0d8"]={q="Warum möchte Chefarchäologe Grauflaum, dass dies getan wird?",a="Chefarchäologe Grauflaum erkennt, dass das geheimnisvolle Fossil, das Wirrbart freigelegt hat, eine verblüffende Ähnlichkeit mit einem merkwürdigen Relikt aufweist, das auf einer Konferenz der Forscherliga in Eisenschmiede präsentiert wurde. Sein Entdecker, Archäologe Magenbitter, glaubte, dass das Relikt eine latente Kraft besaß, die darauf wartete, freigesetzt zu werden. Grauflaum hofft, dass Magenbitter dieses neue Exemplar untersuchen und uralte Geheimnisse der Vergangenheit entschlüsseln kann.",al={"warum fossil schicken","grauflaum beweggrund","warum will grauflaum das fossil untersucht haben"}}},fp="28,201,19.374.0,23.327.0,60.282.0,31.217.0,30.195.0,52.171.0,37.121.0,68.212.0"}
P.entries["quest:94212"] = {n="Craftsman's Writ: Elixir of Wisdom",s="Ein übertragbarer Craftsman's Writ fordert ein Elixir of Wisdom an und enthält Angaben zu Lieferung und Bezahlung. Ihr benötigt das Schreiben, um den Tausch abzuschließen.",h="Ein übertragbarer Craftsman's Writ fordert ein Elixir of Wisdom an und enthält Angaben zu Lieferung und...",kw={"craftsman's writ","lieferung","elixir of wisdom","bezahlung","übertragbar","schreiben"},sec={{t="Eine schriftliche Bitte",b="Eine verblasste Notiz namens Craftsman's Writ: Elixir of Wisdom bittet Euch, ein Elixir of Wisdom zu bringen. Sie enthält Angaben zum Lieferort und zur Bezahlung, und das Schreiben kann von Hand zu Hand weitergegeben werden. Ihr müsst das Schreiben bei Euch haben, wenn Ihr den Tausch abschließt."}},faq={{q="Was fordert das Schreiben an?",a="Es fordert ein Elixir of Wisdom an.",al={"elixier-schreiben","angeforderter gegenstand"}},{q="Kann ich das Schreiben jemand anderem geben?",a="Ja. Auf der Notiz steht, dass das Schreiben übertragbar ist.",al={"ist das schreiben übertragbar","kann es jemand anderes tragen"}},{q="Was benötige ich, um den Tausch abzuschließen?",a="Ihr benötigt den angeforderten Gegenstand und das Schreiben bei Euch. Die Notiz enthält Angaben zum Lieferort und zur Bezahlung.",al={"was brauche ich für die lieferung","schreiben abschließen"}}},fp="34,149,17.246.0,27.33.0,36.44.0,40.118.0"}
P.entries["quest:94214"] = {n="Craftsman's Writ: Shadow Protection Potion",s="Ein übertragbares Auftragsschreiben verlangt einen Shadow Protection Potion und nennt Einzelheiten zu Lieferung und Bezahlung. Für den Austausch müsst Ihr das Schreiben bei Euch haben.",h="Ein übertragbares Auftragsschreiben verlangt einen Shadow Protection Potion und nennt Einzelheiten zu...",kw={"craftsman's writ","lieferung","bezahlung","trank","shadow protection potion","übertragbar","auftragsschreiben"},sec={{t="Eine schriftliche Bitte",b="Eine verblasste Notiz bittet Euch, einen Shadow Protection Potion bereitzustellen. Sie nennt auch den Lieferort und Einzelheiten zur Bezahlung und erklärt, dass das Auftragsschreiben von Hand zu Hand weitergegeben werden kann. Ihr müsst das Schreiben bei Euch haben, um den Austausch abzuschließen."}},faq={{q="Was wird in dem Auftragsschreiben verlangt?",a="Das Auftragsschreiben verlangt einen Shadow Protection Potion.",al={"was wird verlangt","trank angefordert","gegenstand im auftragsschreiben"}},{q="Wo liefere ich ihn ab?",a="Der Lieferort ist auf Eurer Karte markiert.",al={"lieferort","wohin den trank bringen","markierter ort"}},{q="Steht in dem Auftragsschreiben, wie ich bezahlt werde?",a="Das Auftragsschreiben enthält Angaben zur Bezahlung.",al={"einzelheiten zur bezahlung","wie viel wird bezahlt","bezahlung für das auftragsschreiben"}},{q="Kann ich das Auftragsschreiben jemand anderem geben?",a="Ja. Laut der Notiz ist das Auftragsschreiben übertragbar.",al={"ist es übertragbar","auftragsschreiben weitergeben","auftragsschreiben übertragen"}},{q="Muss ich das Auftragsschreiben bei mir behalten?",a="Ja. Ihr müsst das Auftragsschreiben bei Euch haben, um den Austausch abzuschließen.",al={"auftragsschreiben zur ablieferung nötig","muss es mitgeführt werden","auftragsschreiben erforderlich"}}},fp="42,156,17.215.0,27.47.0,22.44.0,37.44.0,36.44.0,35.65.0"}
P.entries["quest:94216"] = {n="Craftsman's Writ: Elixir of Lesser Agility",s="Ein übertragbares Schriftstück bittet Euch, für einen Kunden ein Elixir of Lesser Agility zu besorgen. Es enthält den Lieferort und Angaben zur Bezahlung.",h="Ein übertragbares Schriftstück bittet Euch, für einen Kunden ein Elixir of Lesser Agility zu besorgen.",kw={"beweglichkeit","schriftstück des handwerkers","lieferung","elixier","elixir of lesser agility","bezahlung","übertragbar"},sec={{t="Die Bitte eines Kunden",b="Ein Kunde sucht über dieses Schriftstück mit verblasster Tinte nach einem Elixir of Lesser Agility. Ihr sollt den gewünschten Gegenstand beschaffen und zum markierten Ort bringen. Damit Ihr den Handel abschließen könnt, müsst Ihr das Schriftstück bei Euch haben."}},faq={{q="Worum bittet das Schriftstück?",a="Der Kunde bittet um ein Elixir of Lesser Agility.",al={"welcher gegenstand","elixier anfrage","was wird verlangt"}},{q="Wohin soll ich es bringen?",a="Das Schriftstück verweist auf einen Lieferort, der auf Eurer Karte markiert ist.",al={"lieferort","wohin damit","markierter ort"}},{q="Steht im Schriftstück, wie die Bezahlung abläuft?",a="Das Schriftstück enthält Angaben zur Bezahlung.",al={"zahlungsangaben","wie viel wird bezahlt","wie lautet die bezahlung"}},{q="Kann jemand anderes das Schriftstück tragen?",a="Ja. Am unteren Rand steht, dass das Schriftstück übertragbar ist.",al={"ist es übertragbar","weitergeben","handelsschriftstück"}},{q="Brauche ich das Schriftstück, um die Lieferung abzuschließen?",a="Ja. Ihr müsst das Schriftstück bei Euch haben, um den Handel abzuschließen.",al={"schriftstück benötigt","das papier behalten","schriftstück erforderlich"}}},fp="42,132,20.209.0,27.51.0,22.58.0,36.44.0,32.54.0,44.68.0"}
P.entries["quest:94219"] = {n="Craftsman's Writ: Draught of Water Breathing",s="Ein übertragbares Schreiben fordert einen Draught of Water Breathing an und nennt Lieferort und Bezahlung. Ihr braucht das Schreiben, um den Tausch abzuschließen.",h="Ein übertragbares Schreiben fordert einen Draught of Water Breathing an und nennt Lieferort und Bezahlung.",kw={"craftsman's writ","lieferung","draught of water breathing","bezahlung","wasseratmung","schreiben"},sec={{t="Eine schriftliche Bitte",b="Die verblasste Notiz bittet Euch um einen Draught of Water Breathing. Sie nennt auch den Lieferort und die Bezahlung und kann von einem Besitzer zum nächsten weitergegeben werden."}},faq={{q="Was wird in dem Schreiben angefordert?",a="Es wird ein Draught of Water Breathing angefordert.",al={"was wird verlangt","trankanforderung","angeforderter gegenstand"}},{q="Wo liefere ich ihn ab?",a="Das Schreiben nennt einen Lieferort, der auf Eurer Karte markiert ist.",al={"lieferort","wohin bringen","ort im schreiben"}},{q="Welche Bezahlung wird angeboten?",a="Das Schreiben enthält Angaben zur Bezahlung.",al={"wie viel bezahlung","bezahlung im schreiben","was gibt es dafür"}},{q="Kann das Schreiben übertragen werden?",a="Ja. Laut der Notiz kann das Schreiben übertragen werden.",al={"übertragbares schreiben","kann jemand anderes es tragen","schreiben weitergeben"}},{q="Brauche ich das Schreiben, um den Tausch abzuschließen?",a="Ja. Ihr müsst das Schreiben bei Euch haben, um den Handel abzuschließen.",al={"notiz benötigt","schreiben erforderlich","ablieferung ohne schreiben möglich"}}},fp="44,143,17.146.0,27.43.0,22.55.0,24.44.0,28.47.0,44.65.0"}
P.entries["quest:94220"] = {n="Craftsman's Writ: Pearl-Handled Dagger",s="Ein übertragbarer Auftrag verlangt einen Pearl-Handled Dagger und nennt die Bedingungen für Lieferung und Bezahlung. Ihr benötigt den Auftrag, um den Austausch abzuschließen.",h="Ein übertragbarer Auftrag verlangt einen Pearl-Handled Dagger und nennt die Bedingungen für Lieferung und...",kw={"craftsman's writ","dolch","lieferung","bezahlung","pearl-handled dagger","auftrag"},sec={{t="Der Auftrag",b="Die Notiz ist mit verblasster Tinte geschrieben und nennt einen Pearl-Handled Dagger unter den gesuchten Gegenständen. Die unteren Zeilen nennen einen Lieferort und die Zahlungsbedingungen. Der Auftrag kann von Hand zu Hand gehen, doch Ihr müsst ihn beim Abschluss des Austauschs bei Euch haben."}},faq={{q="Was wird im Auftrag verlangt?",a="Der Auftrag verlangt einen Pearl-Handled Dagger.",al={"auftrag dolch perle","welcher gegenstand wird gesucht"}},{q="Wo liefere ich den Gegenstand ab?",a="Der Lieferort ist auf Eurer Karte markiert.",al={"lieferort","wohin bringen"}},{q="Was bietet der Kunde an?",a="Der Auftrag enthält Angaben zur Bezahlung.",al={"zahlungsbedingungen","wie viel bezahlung"}},{q="Kann ich diesen Auftrag weitergeben?",a="Ja. Laut Auftrag kann er weitergegeben werden.",al={"auftrag weitergeben","ist die notiz übertragbar"}},{q="Muss ich den Auftrag behalten?",a="Ja. Ihr müsst den Auftrag bei Euch haben, um das Geschäft abzuschließen.",al={"auftrag zum abschließen benötigt","notiz bei sich haben"}}},fp="38,141,8.243.0,27.41.0,28.44.0,29.44.0,25.41.0,27.70.0"}
P.entries["quest:94222"] = {n="Handwerksverfügung: Schillernder Hammer",s="Ein Kunde erwartet einen Schillernden Hammer; Angaben zu Lieferung und Bezahlung sind in einem Auftrag festgehalten. Seine Kennzeichnung als übertragbar ermöglicht dem Inhaber, den Austausch abzuschließen.",h="Ein Kunde erwartet einen Schillernden Hammer; Angaben zu Lieferung und Bezahlung sind in einem Auftrag...",kw={"craftsman's writ","lieferung","hammer","schillernder hammer","bezahlung","übertragbar","auftrag"},sec={{t="Der Auftrag",b="Der Kunde verlangt einen Schillernden Hammer. Bringt den Auftrag mit, um den Austausch am markierten Ort abzuschließen."}},faq={{q="Was möchte der Kunde?",a="Der Kunde möchte einen Schillernden Hammer.",al={"schillernder hammer auftrag","welcher gegenstand wird verlangt"}},{q="Wo liefere ich ihn ab?",a="Der Auftrag enthält die Lieferangaben, und der Ort ist auf Eurer Karte markiert.",al={"lieferort des auftrags","wohin den hammer bringen"}},{q="Muss ich den Auftrag bei mir haben?",a="Ja. Behaltet den Auftrag bei Euch, um den Austausch abzuschließen.",al={"auftrag zur lieferung nötig","auftrag erforderlich"}},{q="Kann jemand anderes den Auftrag verwenden?",a="Ja. Der Auftrag ist als übertragbar gekennzeichnet.",al={"übertragbarer auftrag","auftrag weitergeben"}},{q="Steht im Auftrag, wie die Bezahlung abläuft?",a="Ja. Der Auftrag enthält Angaben zur Bezahlung.",al={"hammer bezahlung","wie viel bezahlung"}}},fp="35,155,8.108.0,28.49.0,22.76.0,33.53.0,30.40.0,36.43.0"}
P.entries["quest:94223"] = {n="Craftsman's Writ: Silver Skeleton Key",s="Ein übertragbarer Auftrag verlangt einen Silbernen Skelettschlüssel und weist Euch an, ihn an einem markierten Ort abzuliefern. In der Krypta befinden sich ein Zettel des Verwalters und eine Truhe, die mit dem Schlüssel verbunden ist.",h="Ein übertragbarer Auftrag verlangt einen Silbernen Skelettschlüssel und weist Euch an, ihn an einem...",kw={"verwalter","auftrag des handwerkers","krypta","friedhof von rabenflucht","silberner skelettschlüssel","truhe","untoter"},sec={{t="Der Auftrag",b="Verblasste Tinte nennt einen Silbernen Skelettschlüssel und gibt einen Ablieferungsort sowie eine Bezahlung an. Der Auftrag kann von Hand zu Hand gehen, doch Ihr müsst ihn bei Euch tragen, um den Tausch abzuschließen."},{t="In der Krypta",b="Auf einer Truhe liegt ein Zettel, der Euch mitteilt, dass der Verwalter des Friedhofs von Rabenflucht tot ist. Er schreibt, dass seine Auftraggeber in Dunkelhain ihn weitgehend vergessen haben und er seinen Besitz in der Truhe für denjenigen zurückgelassen hat, der sie öffnen kann. Da sich Untote in der Nähe sammeln und sonst niemand zu sehen ist, benutzt Ihr den Schlüssel. Die Truhe enthält wenig, doch ihr Inhalt deckt einen Teil der Kosten."}},faq={{q="Wonach verlangt der Auftrag?",a="Der Auftrag verlangt einen Silbernen Skelettschlüssel und nennt einen Ablieferungsort sowie eine Bezahlung.",al={"auftrag für silberschlüssel","welchen schlüssel wollen sie"}},{q="Kann jemand anderes den Auftrag tragen?",a="Ja. Im Auftrag steht, dass er weitergegeben werden kann. Ihr müsst ihn jedoch bei Euch haben, um den Tausch abzuschließen.",al={"übertragbarer auftrag","kann ich ihn weitergeben"}},{q="Wohin schickt mich der Auftrag?",a="Der Auftrag weist Euch zu dem Ort, der auf Eurer Karte markiert ist.",al={"ablieferungsort","wohin mit dem schlüssel"}},{q="Wer hat den Zettel in der Krypta hinterlassen?",a="Der Zettel stammt von einem Verwalter des Friedhofs von Rabenflucht, der schreibt, dass er gestorben ist.",al={"zettel des verwalters","wer ist gestorben"}},{q="Was war in der Truhe?",a="Die Truhe ist fast leer. Ihr Inhalt reicht aus, um einen Teil der Kosten zu decken.",al={"leere truhe","schatz des verwalters"}}},fp="37,165,8.165.0,12.334.1,27.81.0,32.97.0,28.56.0,31.77.0,22.72.0"}
P.entries["quest:94224"] = {n="Craftsman's Writ: Heavy Bronze Mace",s="Ein verblasster Auftrag verlangt eine Heavy Bronze Mace und nennt die Bedingungen für Lieferung und Bezahlung. Für den Tausch wird das Auftragsschreiben benötigt.",h="Ein verblasster Auftrag verlangt eine Heavy Bronze Mace und nennt die Bedingungen für Lieferung und Bezahlung.",kw={"auftrag des handwerkers","lieferung","heavy bronze mace","keule","bezahlung","übertragbares auftragsschreiben"},sec={{t="Eine schriftliche Bitte",b="Die Notiz ist mit verblasster Tinte geschrieben, und der Kunde verlangt eine Heavy Bronze Mace. Der Gegenstand soll an den auf der Karte markierten Ort gebracht werden. Das Auftragsschreiben muss bei Euch bleiben, denn es wird für den Tausch benötigt."}},faq={{q="Was verlangt das Auftragsschreiben?",a="Der Kunde verlangt eine Heavy Bronze Mace.",al={"heavy bronze mace auftrag","welcher gegenstand wird verlangt"}},{q="Wo soll die Keule abgeliefert werden?",a="Der Lieferort ist auf der Karte markiert.",al={"lieferort der keule","wohin damit"}},{q="Muss das Auftragsschreiben behalten werden?",a="Ja. Für den Abschluss des Geschäfts muss das Auftragsschreiben in Eurem Besitz sein.",al={"auftragsschreiben nötig","auftragsschreiben erforderlich"}},{q="Was steht in der Notiz über die Bezahlung?",a="Die Notiz enthält Angaben zur Bezahlung, doch im vorliegenden Text wird kein Betrag genannt.",al={"bezahlung für die keule","wie hoch ist die bezahlung"}},{q="Kann jemand anderes das Auftragsschreiben verwenden?",a="Am unteren Rand steht, dass das Auftragsschreiben übertragbar ist.",al={"übertragbares auftragsschreiben","auftragsschreiben weitergeben"}}},fp="35,133,17.218.0,27.44.0,28.44.0,27.69.0,37.92.0,30.56.0"}
P.entries["quest:94226"] = {n="Craftsman's Writ: Green Iron Gauntlets",s="MacKinleys Auftrag verlangt, dass Ihr ihm Green Iron Gauntlets bringt. Das übertragbare Schreiben enthält Angaben zur Lieferung und Bezahlung.",h="MacKinleys Auftrag verlangt, dass Ihr ihm Green Iron Gauntlets bringt.",kw={"craftsman's writ","lieferung","green iron gauntlets","grüne eisenschlagringe","mackinley","bezahlung","übertragbar"},sec={{t="Ein schriftlicher Auftrag",b="Der verblasste Auftrag nennt Green Iron Gauntlets sowie einen Lieferort und eine Bezahlung. Ihr müsst den Auftrag bei Euch haben, um den Austausch abzuschließen. MacKinley wartet auf die Waren, doch seine Begrüßung deutet an, dass etwas nicht stimmt."},{t="Bei der Übergabe",b="MacKinley sagt, er wollte grüne Eisenschlagringe, keine Panzerhandschuhe. Er nimmt die Panzerhandschuhe an, während er auf Ersatz wartet, bezahlt Euch dann aber weniger als erwartet."}},faq={{q="Was verlangt MacKinley?",a="Der Auftrag verlangt ein Paar Green Iron Gauntlets, doch MacKinley sagt, er habe eigentlich grüne Eisenschlagringe bestellen wollen.",al={"was will mckinley","auftrag grünes eisen"}},{q="Wo liefere ich die Panzerhandschuhe ab?",a="Der Auftrag nennt einen Lieferort, der auf Eurer Karte markiert ist.",al={"wo abliefern","lieferort des auftrags"}},{q="Muss ich den Auftrag bei mir haben?",a="Ja. Ihr müsst den Auftrag in Eurem Besitz haben, um den Austausch abzuschließen.",al={"auftrag benötigt","auftrag vergessen"}},{q="Was sagt der Auftrag über die Bezahlung?",a="Das Schreiben enthält Angaben zur Bezahlung, nennt im Text aber keinen Betrag.",al={"wie viel bezahlung","angaben zur bezahlung"}},{q="Kann jemand anderes den Auftrag bei sich tragen?",a="Ja. Laut dem Schreiben ist der Auftrag übertragbar.",al={"übertragbarer auftrag","auftrag weitergeben"}}},fp="38,123,15.216.0,15.157.1,28.114.0,33.55.0,27.66.0,37.77.0,32.44.0"}
P.entries["quest:94229"] = {n="Craftsman's Writ: Ornate Spyglass",s="Eine übertragbare Urkunde fordert ein Ornate Spyglass an und nennt Einzelheiten zu Lieferung und Bezahlung. Der wartende Kunde sagt, dass ein Ingenieur den Auftrag noch nicht ausgeführt hat.",h="Eine übertragbare Urkunde fordert ein Ornate Spyglass an und nennt Einzelheiten zu Lieferung und Bezahlung.",kw={"craftman's writ","lieferung","ingenieur","ornate spyglass","bezahlung","fernrohr","urkunde"},ang={["profession:Engineering"]="Als Ingenieur seid Ihr an den Auftrag gebunden: Der wartende Kunde sagt, dass ein Ingenieur das Fernrohr noch nicht geliefert hat."},sec={{t="Ein wartender Kunde",b="Ein Kunde wartet darauf, dass ein Ingenieur ein Ornate Spyglass liefert. Die verblasste Urkunde nennt den gewünschten Gegenstand sowie Lieferort und Zahlungsweise. Ihr müsst die Urkunde bei Euch haben, um den Austausch abzuschließen."}},faq={{q="Was fordert die Urkunde an?",a="Die Urkunde fordert ein Ornate Spyglass an.",al={"ornate spyglass-urkunde","welcher gegenstand wird verlangt"}},{q="Wohin soll ich das Fernrohr liefern?",a="Die Urkunde nennt einen Lieferort, der auf Eurer Karte markiert ist.",al={"lieferort für das fernrohr","wohin soll ich es bringen"}},{q="Steht in der Urkunde, wie die Bezahlung abläuft?",a="Die Urkunde enthält Angaben zur Bezahlung, nennt hier aber keinen Betrag.",al={"bezahlung für das fernrohr","wie viel wird bezahlt"}},{q="Warum muss ich die Urkunde behalten?",a="Ihr müsst die Urkunde bei Euch haben, um die Transaktion abzuschließen.",al={"brauche ich die urkunde","urkunde vergessen"}},{q="Wer wartet auf den Auftrag?",a="Ein Kunde wartet darauf, dass ein Ingenieur das Ornate Spyglass liefert.",al={"wer möchte das fernrohr","wartender kunde"}}},fp="33,163,18.217.0,27.38.0,32.55.0,36.79.0,31.60.0,29.69.0"}
P.entries["quest:94231"] = {n="Craftsman's Writ: Moonsight Rifle",s="Ein übertragbarer Berechtigungsschein fordert ein Moonsight Rifle und nennt Lieferort und Bezahlung. Der Käufer will den Tausch geheim halten.",h="Ein übertragbarer Berechtigungsschein fordert ein Moonsight Rifle und nennt Lieferort und Bezahlung.",kw={"tarnung","berechtigungsschein des handwerkers","kreuzfeuer","lieferung","moonsight rifle","bezahlung","gewehr","satyr"},sec={{t="Ein stiller Tausch",b="Eine verblasste Notiz bittet Euch, ein Moonsight Rifle zum markierten Ort zu bringen. Die Bezahlung ist dort geregelt. Der Berechtigungsschein kann von Hand zu Hand gehen, doch Ihr müsst ihn bei Euch tragen, um den Tausch abzuschließen. Der Käufer warnt, dass Euer Herannahen Aufmerksamkeit erregt und seine Tarnung auffliegen lassen könnte."},{t="Das Gewehr",b="Sobald Ihr das Moonsight Rifle vorzeigt, lobt der Käufer seine Durchschlagskraft gegen Satyrn. Er fordert Euch auf, beiseitezutreten, bevor das Kreuzfeuer beginnt."}},faq={{q="Was verlangt der Berechtigungsschein?",a="Der Berechtigungsschein verlangt ein Moonsight Rifle, das am auf Eurer Karte markierten Ort abzuliefern ist.",al={"moonsight rifle berechtigungsschein","welches gewehr wird verlangt"}},{q="Kann ich den Berechtigungsschein jemand anderem geben?",a="Ja. Die Notiz besagt, dass der Berechtigungsschein übertragbar ist. Ihr müsst ihn jedoch bei Euch haben, um den Tausch abzuschließen.",al={"ist der berechtigungsschein übertragbar","berechtigungsschein weitergeben"}},{q="Warum will der Käufer Diskretion?",a="Der Käufer sagt, Euer Herannahen erregt Aufmerksamkeit und droht, seine Tarnung auffliegen zu lassen.",al={"warum so geheimnisvoll","tarnung auffliegen lassen"}},{q="Gegen wen soll das Gewehr eingesetzt werden?",a="Der Käufer sagt, das Gewehr könne einem Satyr den Kopf glatt wegschießen.",al={"gewehr gegen satyrn","ziel des moonsight rifle"}}},fp="33,127,16.270.0,9.139.1,27.87.0,36.107.0,33.86.0,42.62.0"}
P.entries["quest:94233"] = {n="Craftsman's Writ: Practice Lock",s="Ein übertragbarer Auftrag verlangt, dass Ihr ein Practice Lock bereitstellt. Lieferort und Zahlungsbedingungen sind auf dem Zettel vermerkt.",h="Ein übertragbarer Auftrag verlangt, dass Ihr ein Practice Lock bereitstellt.",kw={"handwerkerauftrag","lieferung","schloss","bezahlung","practice lock","übertragbar","auftrag"},sec={{t="Eine schriftliche Anfrage",b="Ein Kunde fordert mit einem verblassten, übertragbaren Auftrag ein Practice Lock an. Ihr sollt den gewünschten Gegenstand zum auf Eurer Karte markierten Ort bringen und den Auftrag bei Euch haben, um den Handel abzuschließen."}},faq={{q="Was verlangt der Auftrag?",a="Der Auftrag verlangt ein Practice Lock.",al={"anfrage für practice lock","welcher gegenstand","schlossauftrag"}},{q="Wohin soll ich das Practice Lock bringen?",a="Der Lieferort ist auf Eurer Karte markiert.",al={"lieferort","wohin damit","wohin liefern"}},{q="Muss ich den Auftrag behalten?",a="Ja. Ihr müsst den Auftrag bei Euch haben, um den Handel abzuschließen.",al={"auftrag nötig","den zettel mitbringen","auftrag erforderlich"}},{q="Ist der Auftrag übertragbar?",a="Ja. Auf dem Auftrag steht, dass er übertragbar ist.",al={"kann ich ihn übertragen","übertragbarer zettel","auftrag weitergeben"}},{q="Erwähnt der Zettel eine Bezahlung?",a="Der Auftrag erwähnt eine Bezahlung, nennt im vorliegenden Text aber keinen Betrag.",al={"zahlungsbedingungen","wie viel wird bezahlt","bezahlung"}}},fp="31,122,17.215.0,27.36.0,37.44.0,27.69.0,25.38.0,30.68.0"}
P.entries["quest:94236"] = {n="Craftsman's Writ: Big Bronze Bomb",s="Ein übertragbarer Auftrag verlangt eine Big Bronze Bomb und nennt Lieferort und Bezahlung. Ihr müsst den Auftrag bei Euch haben, um den Austausch abzuschließen.",h="Ein übertragbarer Auftrag verlangt eine Big Bronze Bomb und nennt Lieferort und Bezahlung.",kw={"big bronze bomb","bombe","schreiben des handwerkers","lieferung","bezahlung","übertragbarer auftrag"},sec={{t="Eine schriftliche Bitte",b="Die verblasste Notiz bittet Euch, eine Big Bronze Bomb zu bringen. Sie nennt außerdem Lieferort und Bezahlung und besagt, dass der Auftrag weitergegeben werden kann. Habt ihn für den Austausch bei Euch."}},faq={{q="Was wird im Auftrag verlangt?",a="Der Auftrag verlangt eine Big Bronze Bomb.",al={"welcher gegenstand wird verlangt","auftrag für big bronze bomb"}},{q="Wohin soll ich die Bombe liefern?",a="Der Auftrag verweist auf den auf Eurer Karte markierten Lieferort.",al={"lieferort","wohin bringen"}},{q="Was bietet der Kunde an?",a="Der Auftrag enthält Angaben zur Bezahlung.",al={"wie hoch ist die bezahlung","angaben zur bezahlung"}},{q="Kann ich den Auftrag jemand anderem geben?",a="Ja. Die Notiz besagt, dass der Auftrag übertragbar ist.",al={"ist der auftrag übertragbar","die notiz weitergeben"}},{q="Brauche ich den Auftrag für den Austausch?",a="Ja. Ihr müsst den Auftrag bei Euch haben, um den Austausch abzuschließen.",al={"auftrag zum abschließen nötig","muss ich die notiz bei mir tragen"}}},fp="33,141,17.181.0,27.38.0,28.60.0,29.44.0,36.44.0,36.70.0"}
P.entries["quest:94238"] = {n="Craftsman's Writ: Heavy Leather Ball",s="Ein übertragbarer Handwerkerauftrag verlangt einen Ball aus schwerem Leder und nennt einen Kunden. Sos'mols Sehnsucht nach dem Ball macht diese Lieferung für ihn bedeutsam.",h="Ein übertragbarer Handwerkerauftrag verlangt einen Ball aus schwerem Leder und nennt einen Kunden.",kw={"handwerkerauftrag","lieferung","ball aus schwerem leder","oger","bezahlung","sos'mol","übertragbar"},sec={{t="Der Wunsch eines Kunden",b="Der verblasste Auftrag verlangt einen Ball aus schwerem Leder und enthält Angaben zu Lieferung und Bezahlung. Ihr bringt den Auftrag mit, um den Tausch abzuschließen. Sos'mol summt bei Eurer Ankunft eine schiefe Melodie über Langeweile. Er summt weiter, wenn auch leiser, und wirkt ein wenig verlegen."},{t="Sos'mols Freude",b="Sos'mol fragt, ob Ihr ihm den Ball mitgebracht habt. Als er ihn erhält, steigen ihm Tränen in die Augen, und er nennt es den glücklichsten Tag im Leben eines Ogers. Der Ball bedeutet ihm mehr als alles andere, was er sich gewünscht hatte, obwohl er sich nicht mehr daran erinnern kann, was es war."}},faq={{q="Was verlangt der Auftrag?",a="Der Auftrag verlangt einen Ball aus schwerem Leder und enthält Angaben zu Lieferung und Bezahlung.",al={"auftrag für ball aus schwerem leder","welcher gegenstand wird verlangt"}},{q="Wer ist der Kunde?",a="Sos'mol ist der Kunde, der in der Lieferung genannt wird.",al={"wer möchte den ball","sos'mols auftrag"}},{q="Warum möchte Sos'mol einen Ball?",a="Sos'mol sagt, der Ball sei etwas gewesen, wovon er geträumt hatte.",al={"warum ein ball","sos'mol möchte einen ball"}},{q="Was tut Sos'mol, wenn ich ankomme?",a="Sos'mol hat ein schiefes Lied über Langeweile gesummt und summt leiser weiter, als Ihr näher kommt.",al={"was tut sos'mol","sos'mol singt"}},{q="Kann jemand anderes den Auftrag verwenden?",a="Ja. Auf dem Zettel steht, dass der Auftrag übertragbar ist.",al={"übertragbarer auftrag","kann ich den auftrag weitergeben"}}},fp="36,151,20.284.0,17.252.1,27.88.0,20.46.0,29.60.0,36.99.0,30.44.0"}
P.entries["quest:94242"] = {n="Craftsman's Writ: Pilferer's Gloves",s="Ein übertragbares Auftragsschreiben verlangt Pilferer's Gloves und nennt Einzelheiten zu Lieferung und Bezahlung. Ihr braucht das Schreiben, um den Handel abzuschließen.",h="Ein übertragbares Auftragsschreiben verlangt Pilferer's Gloves und nennt Einzelheiten zu Lieferung und...",kw={"craftsman's writ","lieferung","handschuhe","bezahlung","pilferer's gloves","übertragbar","auftragsschreiben"},sec={{t="Ein schriftlicher Auftrag",b="Eine verblasste Notiz verlangt ein Paar Pilferer's Gloves. Sie nennt den Lieferort und die Zahlungsmodalitäten, und das Auftragsschreiben kann von Hand zu Hand gehen."},{t="Der Handel",b="Ihr müsst das Auftragsschreiben bei Euch haben, wenn Ihr die verlangten Handschuhe zum markierten Ort bringt. Die Notiz verknüpft die Einzelheiten zu Lieferung und Bezahlung mit diesem schriftlichen Auftrag."}},faq={{q="Was verlangt das Auftragsschreiben?",a="Das Auftragsschreiben verlangt ein Paar Pilferer's Gloves.",al={"pilferer's gloves auftragsschreiben","handschuhauftrag","welcher gegenstand"}},{q="Wo liefere ich die Handschuhe ab?",a="Der Lieferort ist auf Eurer Karte markiert.",al={"lieferort","wohin die handschuhe bringen","markierter ort"}},{q="Was brauche ich, um den Handel abzuschließen?",a="Ihr müsst das Auftragsschreiben in Eurem Besitz haben, um den Handel abzuschließen.",al={"auftragsschreiben benötigt","auftragsschreiben voraussetzung","handel abschließen"}},{q="Steht im Auftragsschreiben, wie die Bezahlung erfolgt?",a="Das Auftragsschreiben enthält Informationen zur Bezahlung.",al={"zahlungsdetails","wie viel bezahlung","handschuhe bezahlung"}},{q="Kann jemand anderes das Auftragsschreiben bei sich tragen?",a="Ja. Das Auftragsschreiben ist übertragbar.",al={"übertragbares auftragsschreiben","notiz weitergeben","kann ich es weitergeben"}}},fp="35,141,15.156.0,15.156.0,27.48.0,30.44.0,43.65.0,36.44.0,32.30.0"}
P.entries["quest:94243"] = {n="Handwerksverfügung: Schwerer Köcher",s="Ein verblasster „Craftsman's Writ: Schwerer Köcher“ fordert Euch auf, einen Schweren Köcher an einen markierten Ort zu bringen, und enthält Angaben zur Bezahlung.",h="Ein verblasster „Craftsman's Writ: Schwerer Köcher“ fordert Euch auf, einen Schweren Köcher an einen...",kw={"craftsman's writ","lieferung","schwerer köcher","bezahlung","köcher","übertragbar"},sec={{t="Der Auftrag",b="Die Notiz fordert Euch auf, einen Schweren Köcher zu beschaffen und zu dem auf Eurer Karte markierten Ort zu bringen. Behaltet den Auftrag bei Euch, um den Austausch abzuschließen."}},faq={{q="Was verlangt der Auftrag?",a="Der Kunde verlangt einen Schweren Köcher.",al={"schwerer köcher gesucht","welcher gegenstand wird gesucht"}},{q="Wo liefere ich ihn ab?",a="Der Lieferort ist auf Eurer Karte markiert.",al={"lieferort","wohin den köcher bringen"}},{q="Muss ich den Auftrag bei mir tragen?",a="Ja. Tragt den Auftrag bei Euch, um den Austausch abzuschließen.",al={"auftrag nötig","auftrag erforderlich"}},{q="Kann ich diesen Auftrag jemand anderem geben?",a="Ja. Der Auftrag kann an jemand anderen übertragen werden.",al={"auftrag übertragen","kann jemand anderes ihn verwenden"}},{q="Erwähnt der Auftrag eine Bezahlung?",a="Der Auftrag enthält Angaben zur Bezahlung, nennt aber keinen Betrag.",al={"wie hoch ist die bezahlung","bezahlung für köcher"}}},fp="30,121,8.140.0,27.39.0,22.41.0,28.54.0,37.49.0,30.56.0"}
P.entries["quest:94245"] = {n="Craftsman's Writ: Barbaric Gloves",s="Ein übertragbares Schreiben fordert Barbaric Gloves an und nennt einen Lieferort sowie Zahlungsdetails. Ihr müsst das Schreiben bei Euch haben, um den Handel abzuschließen.",h="Ein übertragbares Schreiben fordert Barbaric Gloves an und nennt einen Lieferort sowie Zahlungsdetails.",kw={"barbaric gloves","craftsman's writ","lieferung","handschuhe","bezahlung","übertragbar","schreiben"},sec={{t="Die Bitte eines Kunden",b="Ein Kunde fordert mit diesem verblassten Schreiben ein Paar Barbaric Gloves an. Die Notiz nennt einen Lieferort und Zahlungsdetails und kann von Hand zu Hand weitergegeben werden. Ihr müsst das Schreiben bei Euch haben, wenn Ihr den gewünschten Gegenstand abliefert."}},faq={{q="Was fordert das Schreiben an?",a="Der Kunde fordert ein Paar Barbaric Gloves an.",al={"barbaric gloves schreiben","welche handschuhe","handwerkerschreiben"}},{q="Wohin soll ich die Handschuhe liefern?",a="Der Lieferort ist auf Eurer Karte markiert.",al={"lieferort","wohin die handschuhe bringen"}},{q="Muss ich das Schreiben bei mir tragen?",a="Ja. Ihr müsst das Schreiben bei Euch haben, um den Handel abzuschließen.",al={"schreiben bei mir haben","schreiben erforderlich"}},{q="Kann das Schreiben weitergegeben werden?",a="Ja. In der Notiz steht, dass das Schreiben übertragbar ist.",al={"schreiben übertragen","schreiben weitergeben"}},{q="Was steht im Schreiben zur Bezahlung?",a="Das Schreiben enthält Informationen zur Bezahlung.",al={"zahlungsdetails","wie hoch ist die bezahlung"}}},fp="33,151,20.237.0,27.50.0,30.44.0,28.70.0,28.44.0,37.44.0"}
P.entries["quest:94246"] = {n="Craftsman's Writ: Red Whelp Gloves",s="Ein übertragbares Auftragsschreiben verlangt ein Paar Red Whelp Gloves. Es nennt einen Lieferort und die Bezahlung für den Austausch.",h="Ein übertragbares Auftragsschreiben verlangt ein Paar Red Whelp Gloves.",kw={"craftsman's writ","lieferung","bezahlung","red whelp gloves","übertragbar","auftragsschreiben"},sec={{t="Eine schriftliche Bitte",b="Eine verblasste Notiz verlangt ein Paar Red Whelp Gloves und nennt einen Lieferort sowie die Bezahlung. Ihr müsst das Auftragsschreiben besitzen, um den Austausch abzuschließen."}},faq={{q="Was wird im Auftragsschreiben verlangt?",a="Das Auftragsschreiben verlangt ein Paar Red Whelp Gloves.",al={"red whelp gloves auftragsschreiben","welcher gegenstand wird verlangt"}},{q="Wo liefere ich die Handschuhe ab?",a="Das Auftragsschreiben nennt einen Lieferort, der auf Eurer Karte markiert ist.",al={"lieferort","wohin mit den handschuhen"}},{q="Was brauche ich, um den Austausch abzuschließen?",a="Ihr müsst das Auftragsschreiben in Eurem Besitz haben, um den Austausch abzuschließen.",al={"was wird benötigt","auftragsschreiben voraussetzung"}},{q="Kann das Auftragsschreiben übertragen werden?",a="Ja. Laut der Notiz ist das Auftragsschreiben übertragbar.",al={"übertragbares auftragsschreiben","kann jemand anderes es übernehmen"}},{q="Erwähnt das Auftragsschreiben eine Bezahlung?",a="Ja. Das Auftragsschreiben enthält Angaben zur Bezahlung.",al={"wie viel bezahlung","bezahlung für handschuhe"}}},fp="34,114,17.145.0,27.47.0,30.57.0,40.62.0,28.44.0,30.49.0"}
P.entries["quest:94249"] = {n="Craftsman's Writ: Azure Silk Hood",s="Ein verblasster Craftsman’s Writ verlangt eine Azure Silk Hood und nennt die Bedingungen für Lieferung und Bezahlung. Ihr braucht das Schreiben, um den Tausch abzuschließen.",h="Ein verblasster Craftsman’s Writ verlangt eine Azure Silk Hood und nennt die Bedingungen für Lieferung und...",kw={"azure silk hood","craftsman's writ","lieferung","bezahlung","seidenkapuze","übertragbar","schreiben"},sec={{t="Die schriftlichen Bedingungen",b="Die Notiz ist mit verblasster Tinte geschrieben und nennt einen Gegenstand: eine Azure Silk Hood. Sie nennt auch den Lieferort und die Bezahlung. Das Schreiben kann von einem Träger an einen anderen weitergegeben werden, aber Ihr müsst es bei Euch haben, um den Handel abzuschließen."}},faq={{q="Was wird in dem Schreiben verlangt?",a="Der Kunde verlangt eine Azure Silk Hood.",al={"azure hood schreiben","welcher gegenstand wird gesucht","craftsman writ"}},{q="Wo liefere ich die Kapuze ab?",a="Der Lieferort ist auf Eurer Karte markiert.",al={"lieferort","wohin bringen","markierter ort"}},{q="Was brauche ich für den Handel?",a="Ihr müsst den verlangten Gegenstand und das Schreiben in Eurem Besitz haben.",al={"was mitbringen","schreiben nötig?","tausch abschließen"}},{q="Steht im Schreiben, wie die Bezahlung abläuft?",a="Die Notiz enthält Angaben zur Bezahlung, aber der hier vorliegende Text nennt keinen Betrag.",al={"höhe der bezahlung","zahlungsbedingungen","was gibt es dafür"}},{q="Kann jemand anderes das Schreiben tragen?",a="Ja. Das Schreiben ist als übertragbar gekennzeichnet.",al={"übertragbares schreiben","weitergabe möglich","wer darf es besitzen"}}},fp="33,144,17.225.0,27.42.0,28.44.0,35.60.0,36.91.0,32.40.0"}
P.entries["quest:94250"] = {n="Craftsman's Writ: Small Silk Pack",s="Ein übertragbarer Auftragsschein verlangt ein Small Silk Pack und enthält Angaben zu Lieferung und Bezahlung. Der Schein wird benötigt, um den Austausch abzuschließen.",h="Ein übertragbarer Auftragsschein verlangt ein Small Silk Pack und enthält Angaben zu Lieferung und Bezahlung.",kw={"craftsman's writ","lieferung","bezahlung","seide","small silk pack","übertragbar","auftragsschein"},sec={{t="Der Auftragsschein",b="Die verblasste Notiz eines Kunden bittet Euch um ein Small Silk Pack. Sie enthält Angaben dazu, wohin Ihr das Pack liefern sollt und wie die Bezahlung erfolgt. Der Auftragsschein kann von Hand zu Hand weitergegeben werden, doch Ihr müsst ihn beim Abschluss des Austauschs bei Euch haben."}},faq={{q="Was verlangt der Auftragsschein?",a="Der Kunde verlangt ein Small Silk Pack.",al={"small silk pack auftragsschein","welcher gegenstand wird verlangt","anfrage für seidenpack"}},{q="Wohin soll ich das Pack liefern?",a="Der Auftragsschein enthält Angaben zur Lieferung, und der Ort ist auf Eurer Karte markiert.",al={"lieferort","wohin damit","wo ist der abgabeort"}},{q="Wie erfolgt die Bezahlung?",a="Der Auftragsschein enthält Angaben zur Bezahlung.",al={"wie viel bekomme ich","zahlungsdetails","wie wird bezahlt"}},{q="Kann ich den Auftragsschein jemand anderem geben?",a="Ja. Auf der Notiz steht, dass der Auftragsschein übertragbar ist.",al={"ist der auftragsschein übertragbar","auftragsschein weitergeben","weiterreichen"}},{q="Benötigt Ihr den Auftragsschein, um den Austausch abzuschließen?",a="Ja. Ihr müsst den Auftragsschein bei Euch haben, um die Transaktion abzuschließen.",al={"auftragsschein zum abgeben nötig","muss ich die notiz behalten","auftragsschein erforderlich"}}},fp="33,141,8.220.0,27.42.0,28.79.0,23.44.0,40.44.0,44.70.0"}
P.entries["quest:94252"] = {n="Craftsman's Writ: Red Woolen Boots",s="Ein übertragbares Schreiben fordert ein Paar Red Woolen Boots und enthält Angaben zu Lieferung und Bezahlung. Ihr benötigt das Schreiben, um den Tausch abzuschließen.",h="Ein übertragbares Schreiben fordert ein Paar Red Woolen Boots und enthält Angaben zu Lieferung und Bezahlung.",kw={"stiefel","schreiben des handwerkers","lieferung","bezahlung","red woolen boots","übertragbar","schreiben"},sec={{t="Die schriftliche Anfrage",b="Eine verblasste Notiz bittet Euch, ein Paar Red Woolen Boots bereitzustellen. Sie enthält Angaben dazu, wohin Ihr sie liefern sollt und wie die Bezahlung geregelt ist. Das Schreiben ist übertragbar, aber Ihr müsst es besitzen, wenn Ihr den Tausch abschließt."}},faq={{q="Was wird im Schreiben angefordert?",a="Das Schreiben fordert ein Paar Red Woolen Boots an.",al={"schreiben für rote stiefel","welche stiefel werden angefordert"}},{q="Wohin soll ich die Stiefel liefern?",a="Das Schreiben enthält Lieferangaben, und der markierte Ort wird auf Eurer Karte angezeigt.",al={"lieferort","wohin rote stiefel bringen"}},{q="Wie ist die Bezahlung geregelt?",a="Das Schreiben enthält Angaben zur Bezahlung.",al={"bezahlung für stiefel","wie viel wird bezahlt"}},{q="Kann ich dieses Schreiben übertragen?",a="Ja. In der Notiz steht, dass das Schreiben übertragbar ist.",al={"übertragbares schreiben","kann es jemand anderes tragen"}},{q="Benötige ich das Schreiben, um den Tausch abzuschließen?",a="Ja. Ihr müsst das Schreiben bei Euch haben, um den Tausch abzuschließen.",al={"schreiben bei mir haben","tausch abschließen"}}},fp="34,143,19.213.0,27.47.0,29.81.0,24.44.0,25.44.0,44.75.0"}
P.entries["quest:94253"] = {n="Handwerksverfügung: Bunter Kilt",s="Ein Kunde sucht eine Verkleidung, um nach Zul'Gurub zu gelangen, und Craftsman's Writ: Bunter Kilt nennt das gewünschte Kleidungsstück.",h="Ein Kunde sucht eine Verkleidung, um nach Zul'Gurub zu gelangen, und Craftsman's Writ: Bunter Kilt nennt das...",kw={"bunter kilt","craftsman's writ","lieferung","verkleidung","ritualist","zul'gurub"},sec={{t="Eine Verkleidung",b="Der übertragbare Auftrag verlangt von Euch, einen Bunten Kilt zum markierten Ort zu bringen. Der Kunde will als einer der dortigen Ritualisten verkleidet durch die Tore von Zul'Gurub gelangen und sagt, der Kilt passe zur Verkleidung."}},faq={{q="Was verlangt der Auftrag?",a="Der Auftrag verlangt einen Bunten Kilt, der an den auf Eurer Karte markierten Ort geliefert werden soll.",al={"bunter kilt auftrag","welcher gegenstand wird benötigt"}},{q="Warum möchte der Kunde einen bunten Kilt?",a="Der Kunde will sich als einer der dortigen Ritualisten verkleidet nach Zul'Gurub schleichen und sagt, der Kilt werde dabei helfen.",al={"warum kilt","kilt verkleidung"}},{q="Kann ich diesen Auftrag übertragen?",a="Ja. Laut dem Auftrag ist er übertragbar.",al={"auftrag übertragen","auftrag weitergeben"}},{q="Wohin soll ich den Kilt liefern?",a="Der Auftrag schickt Euch an den auf Eurer Karte markierten Ort.",al={"lieferort","wohin bringen"}}},fp="31,121,10.206.0,27.88.0,43.104.0,25.38.0,32.56.0"}
P.entries["quest:943"] = {n="Der geistesabwesende Ausgrabungsleiter",s="Wirrbarts Ausgrabung an der Dunkelküste führt seine Suche über das große Meer. Im Hafen von Menethil hofft Archäologe Magenbitter, Wirrbarts Funde mit seinem eigenen Fossil und dem verlorenen Stein von Relu zu vereinen und die verborgenen Kräfte der Relikte zu enthüllen.",h="Wirrbarts Ausgrabung an der Dunkelküste führt seine Suche über das große Meer.",kw={"dunkelküste","explorers' league","magenbitter","fossil","menethil","wirrbart","stein von relu","sumpfland","whelgar"},ang={["faction:Alliance"]="Als Abenteurer der Allianz könnt Ihr gemeinsam mit Kurieren der Allianz die Verbindung über das Meer zwischen den Nachtelfengebieten der Dunkelküste und den Zwergensiedlungen rund um den Hafen von Menethil stärken.",["race:Dwarf"]="Als Zwerg seht Ihr die Explorers' League bei der Arbeit, wie sie ferne Ausgrabungsstätten über Kontinente hinweg verbindet, um das Erbe der Zwerge und die Geheimnisse der Titans zu ergründen."},sec={{t="Archäologie über Kontinente hinweg",b="Ihr habt dem zerstreuten Ausgrabungsleiter Wirrbart einst geholfen, als Ihr ihn durch den Norden der Dunkelküste begleitet habt. Nun führt die Suche über das große Meer in die Marschen des Sumpflands. Ausgrabungsleiter Whelgar verwahrt Magenbitters ursprüngliches Fossil an seiner Ausgrabungsstätte. Nach der Untersuchung der Funde glaubt Archäologe Magenbitter, dass der Stein von Relu die geheimnisvollen Kräfte in den Fossilien freisetzen kann."},{t="In den Marschen verloren",b="Bevor Magenbitter Whelgar treffen konnte, überfielen gescheckte Raptoren seine Karawane auf der Straße und verschlangen den Stein von Relu. Um das Rätsel zu lösen, braucht Magenbitter Eure Hilfe: Ihr müsst die Bestien jagen, den Stein bergen und sein ursprüngliches Fossil aus Whelgars Lager holen. Mit beiden Fossilien und dem Schlüssel hoffen die zwergischen Forscher, den wahren Ursprung und die Macht der Relikte zu ergründen."}},faq={{q="Warum endet eine Quest von der Dunkelküste im Sumpfland?",a="Die Explorers' League ist in Kalimdor und den Östlichen Königreichen tätig. Chefarchäologe Grauflaum schickte Wirrbarts Fossil von der Dunkelküste über das Meer zu Archäologe Magenbitter im Sumpfland. Ihre gemeinsame Forschung verbindet die beiden Ausgrabungsstätten.",al={"warum sumpfland dunkelküste quest","hafen von menethil verbindung","warum ins sumpfland schicken"}},{q="Was ist der Stein von Relu?",a="Der Stein von Relu ist ein uraltes Relikt, das Archäologe Magenbitter geborgen hat. Er glaubt, dass er als Chiffre oder Katalysator dienen kann, um schlummernde magische Geheimnisse in Fossilien von der Dunkelküste und aus dem Sumpfland zu erschließen.",al={"stein von relu","was ist der stein von relu","relu artefakt"}},{q="Wer ist Archäologe Magenbitter?",a="Archäologe Magenbitter ist ein Mitarbeiter der zwergischen Explorers' League und im Hafen von Menethil ansässig. Er untersucht uralte Relikte aus nahe gelegenen Ausgrabungen und hofft, die verborgene Macht in den Fossilien der Ausgrabungsleiter Wirrbart und Whelgar freizusetzen.",al={"magenbitter","wer ist magenbitter"}},{q="Wer hat das ursprüngliche Fossil?",a="Ausgrabungsleiter Whelgar verwahrt Magenbitters ursprüngliches Fossil an seiner Ausgrabungsstätte im Sumpfland. Ihr habt Wirrbarts Fossil von der Dunkelküste bereits zu Magenbitter gebracht.",al={"wo ist das fossil","wer hat wirrbarts fossil","whelgar fossil"}},{q="Warum haben Raptoren den Stein von Relu?",a="Als Magenbitter auf der Straße durch das Sumpfland unterwegs war, um Ausgrabungsleiter Whelgar zu sprechen, geriet er in einen Hinterhalt gescheckter Raptoren. Im Chaos verschluckte eine der Bestien den Stein im Ganzen.",al={"raptor verschluckte relikt","warum haben raptoren den stein"}},{q="Was erwarten die Zwerge von den Fossilien?",a="Magenbitter glaubt, dass die Fossilien verborgene Macht und Geheimnisse der Vergangenheit bergen. Er glaubt, dass der Stein von Relu der Schlüssel dazu ist.",al={"fossil macht","was bewirkt das fossil"}}},fx={["1568e7b3"]={q="Wozu dient Magenbitters Fossil?",a="Magenbitters Fossil ist eines der alten Exemplare, die von den zwergischen Ausgräbern geborgen wurden, zusammen mit dem Stück, das Ausgrabungsleiter Wirrbart in der Dunkelküste freigelegt hat. Archäologe Magenbitter glaubt, dass diese uralten Relikte ruhende magische Kraft und vergessene Geheimnisse bergen, die er mithilfe der Resonanzkraft des Steins von Relu endlich freischalten und entschlüsseln möchte.",al={"magenbitters fossil","magenbitter fossil verwendung","was ist magenbitters fossil"}}},fp="28,229,29.366.0,19.376.1,48.246.0,26.221.0,31.241.0,28.162.0,38.172.0,45.133.0"}
P.entries["quest:94369"] = {n="The Fate of Zephras",s="In Valanaar überbringt Ihr Talaanis Shadowsong Nachricht von der Gefahr, die Zephras droht. Die gefallenen Schutzzauber lassen die Insel Al'Akir schutzlos ausgeliefert zurück, und ihre Bewohner müssen entscheiden, wie sie ihre Heimat schützen.",h="In Valanaar überbringt Ihr Talaanis Shadowsong Nachricht von der Gefahr, die Zephras droht.",kw={"al'akir","elaadrin","lorthuna","schrein von akir","talaanis shadowsong","valanaar","schutzzauber","windlord","zephras"},sec={{t="Eine Warnung für Talaanis",b="Ihr berichtet Talaanis, was sich über dem Schrein von Akir zugetragen hat. Ihr erzählt von Elaadrins Plan, die Insel Zephras zu verlassen. Der Hohe Älteste Shadowsong muss die Gefahr verstehen und erfahren, warum Ihr nach Azeroth geschickt wurdet. Die Bewohner von Zephras müssen einen Weg finden, ihre Heimat zu retten."},{t="Was bleibt",b="Talaanis wägt die Nachricht ab. Lorthuna ist fort, und der Kult hat seinen Anführer verloren. Zephras wurde nicht überfallen. Doch Al'Akir könnte seine Aufmerksamkeit in Jahren oder Jahrzehnten der Insel zuwenden, und neben dem Grund zum Feiern steht nun die Furcht."}},faq={{q="Mit wem spreche ich?",a="Ihr sprecht mit Talaanis Shadowsong in Valanaar.",al={"mit wem sprechen","talaanis","wo bericht erstatten"}},{q="Was erzähle ich Talaanis?",a="Ihr berichtet Talaanis, was sich über dem Schrein von Akir zugetragen hat, und erzählt von Elaadrins Plan, die Insel Zephras zu verlassen.",al={"was geschah am schrein","was berichten","nachrichten vom schrein von akir"}},{q="Warum fürchten die Bewohner von Zephras Al'Akir?",a="Die Schutzzauber, die Zephras verbargen, sind gefallen. Al'Akir könnte sich zum Angriff entschließen, während sich die Bewohner in seinem Reich befinden.",al={"warum al'akir fürchten","gefahr durch windlord","bedrohung durch al akir"}},{q="Was muss der Hohe Älteste Shadowsong wissen?",a="Der Hohe Älteste Shadowsong muss von der Gefahr erfahren und wissen, was die Bewohner von Zephras auf ihrer Mission nach Azeroth vorhaben.",al={"was talaanis braucht","nachrichten für den hohen ältesten","absichten für azeroth"}}},fp="19,183,22.251.0,12.225.1,20.47.0,24.102.0,48.104.0,45.122.0"}
P.entries["quest:94373"] = {n="Call of Earth",s="In Ambossar prüft Teo Hammerstorm Initianden, die die Gunst der Erde suchen. Sie stellen sich Frostmähnentrollen im Süden und erbeuten Bärenanhänger, bevor sie ein Earth Sapta erhalten.",h="In Ambossar prüft Teo Hammerstorm Initianden, die die Gunst der Erde suchen.",kw={"ambossar","call of earth","das coldridgetal","erdtotem","frostmähne","frostmane bear pendant","eiskrallenbär","sapta","schamane","teo hammerstorm"},ang={["class:Shaman"]="Als Schamane beginnt Ihr durch diese Initiation, mit den Geistern von Stein und Erde Zwiesprache zu halten. Teo bereitet ein Earth Sapta für Euch zu.",["faction:Alliance"]="Als Mitglied der Allianz stellt Ihr Euch Frostmähnentrollen in Höhlen südlich von Ambossar.",["race:Dwarf"]="Als Zwerg findet Ihr diese Prüfung nahe Ambossar im Coldridgetal. Sie verbindet Euer Erbe aus den Bergen und Eure Standhaftigkeit mit der Geduld der Erde."},sec={{t="Die Weisheit des Steins",b="Im Coldridgetal führt Teo Hammerstorm Initianden in Ambossar auf dem rauen Pfad der Erde. Er lehrt junge Wanderer, auf die Berge zu hören und das Land als festen Grund zu betrachten. Stein kann jene schützen, die ihn achten. Die Erde teilt ihre Weisheit nur mit jenen, die Zähigkeit und Geduld beweisen."},{t="Prüfung in Frostmane Den",b="Um ihre Bereitschaft zu beweisen, stellen sich Initianden Frostmähnentrollen in einer Höhle südlich von Ambossar. Die Trolle fertigen grobe Anhänger aus Eiskrallenbären, die durch die gefrorenen Höhen streifen. Zwei Bärenanhänger aus dem Unterschlupf zu bergen, beweist die unbeirrbare Entschlossenheit und Stärke, die die Elementargeister erwarten."},{t="Das Earth Sapta",b="Nachdem der Initiand die Anhänger überreicht hat, lobt Teo Hammerstorm die Geduld, die edelste Tugend der Erde. Geduld überdauert zerbröckelnde Gipfel und Flüsse, die Täler graben. Dann bereitet Teo ein Earth Sapta zu, das den Initianden den wahren Pfad der Elemente erkennen und beschreiten lässt."}},faq={{q="Wer bietet die Quest Call of Earth an?",a="Teo Hammerstorm, ein alter Mentor in Ambossar im Coldridgetal, bietet die Prüfung an. Er lehrt Initianden die Wege des Steins und fordert sie auf, den Erdgeistern ihre Entschlossenheit zu beweisen.",al={"wer vergibt call of earth","questgeber call of earth","teo hammerstorm quest"}},{q="Was verlangt Teo Hammerstorm von Euch?",a="Ihr reist südlich von Ambossar zu einer Höhle, die von Frostmähnentrollen bewohnt wird, und bergt zwei Frostmane Bear Pendants. Die Trolle fertigen sie aus Eiskrallenbären, und Ihr bringt sie zu Teo Hammerstorm.",al={"call of earth ziele","was braucht man für call of earth","frostmähnenanhänger quest"}},{q="Wo findet Ihr die Frostmane Bear Pendants?",a="Frostmähnentrolle tragen die Anhänger in einer Höhle südlich von Ambossar. Sie fertigen die Talismane aus Eiskrallenbären und tragen sie in ihrem Unterschlupf.",al={"wo sind frostmane bear pendants","wie bekommt man frostmane bear pendants","frostmähnenhöhle ambossar"}},{q="Welche Belohnung bereitet Teo Hammerstorm nach Abschluss zu?",a="Teo bereitet ein Earth Sapta zu, einen zeremoniellen Trank, der Euch auf die Elementargeister einstimmt. Er lässt Euch den wahren Pfad der Erde beschreiten.",al={"was ist ein sapta","earth sapta zwerg","was stellt teo hammerstorm her"}},{q="Warum müssen sich Initianden für diese Prüfung den Frostmähnentrollen stellen?",a="Sich den Frostmähnentrollen zu stellen, beweist die Zähigkeit und Widerstandskraft, die nötig sind, um mit der Erde Zwiesprache zu halten. Die Bärenanhänger aus ihrem Unterschlupf zu holen, beweist die Entschlossenheit des Initianden.",al={"warum frostmähnentrolle töten","warum frostmähnenanhänger"}},{q="Was lehrt Teo Hammerstorm über das Wesen der Erde?",a="Teo lehrt, dass Geduld die größte Tugend der Erde ist. Sie besteht fort, während Berge zerbröckeln und Flüsse Täler graben. Er sagt, Stein schütze jene, die ihn achten, doch selbst Felsgrund könne sich verschieben, wenn man ihn kränkt.",al={"tugenden der erde teo hammerstorm","weisheit des berges"}}},fp="13,171,19.289.0,26.279.0,17.273.1,35.180.0,40.189.0,46.135.0,57.139.0,60.162.0,58.204.0"}
P.entries["quest:94374"] = {n="Call of Earth",s="An einem Geiststein im Gebirge trinkt ein Initiand Earth Sapta und bindet seinen Geist an die beständigen Fundamente der Welt. Der Trunk öffnet den Weg zur Wahrnehmung der Elemente und lehrt inmitten von Schnee und Fels Demut und Geduld.",h="An einem Geiststein im Gebirge trinkt ein Initiand Earth Sapta und bindet seinen Geist an die beständigen...",kw={"call of earth","dun morogh","earth sapta","elementarer ritus","verborgener pfad","sapta","schamane","geiststein"},ang={["class:Shaman"]="Als Schamane nehmt Ihr an einer grundlegenden Zwiesprache teil, die Geist an Stein bindet und durch den rituellen Sapta-Trunk einen Blick jenseits sterblicher Wahrnehmung gewährt.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr einen elementaren Ritus, der zwischen verschneiten Bergklippen praktiziert wird, wo schamanische Traditionen in den Ländern der Allianz Wurzeln schlagen.",["race:Dwarf"]="Als Zwerg hört Ihr diese heilige Zwiesprache im rauen Sprachrhythmus Eures Volkes, inmitten gefrorener Berggipfel. Sie verbindet die Zwiesprache mit der Erde mit den verschneiten Höhen von Dun Morogh."},sec={{t="Der Trunk der Vision",b="An einem abgelegenen Bergschrein trinkt Ihr Earth Sapta, ein verzaubertes Gebräu. Uralte Elementarmagie verleiht ihm die Macht, sterblichen Augen Elementargeister und feine Strömungen jenseits der gewöhnlichen Wahrnehmung zu offenbaren. Seine Stärke macht den Schrein zum einzigen sicheren Ort, um es zu trinken, wo Geist und Stein ihr Band knüpfen können."},{t="Der Geiststein im Schnee",b="Hoch auf einem schneeverwehten Berg wartet der Geiststein am Ende eines abgeschiedenen Pfades. Ihr reist durch bittere Kälte, um demütig vor dem uralten Fels zu stehen. Die lebendige Erde heißt jene willkommen, die ohne Hochmut kommen. Berge verleihen beständige körperliche Stärke, während die weiten, ruhigen Ebenen Geduld lehren."},{t="Stärke und Stille",b="Die Zwiesprache mit dem Stein ist ein grundlegender Ritus für spirituelle Pfadfinder. Wind, Feuer und tosendes Wasser tragen rastlosen Zorn in sich, während die Erde Disziplin und stille Widerstandskraft lehrt. Ihr nehmt die stille Essenz der Erde auf und bereitet Geist und Körper auf die widersprüchlichen, chaotischen Doppelnaturen der unberechenbareren Elemente vor, die über die Welt tosen."}},faq={{q="Was ist Earth Sapta?",a="Earth Sapta ist ein mächtiges mystisches Gebräu, das mithilfe von Magie den Geist des Anwenders unmittelbar an die Elemente bindet. Es ist nicht für Willensschwache bestimmt. Wer es trinkt, durchdringt die Grenzen des gewöhnlichen sterblichen Blicks und erkennt Geister und elementare Wahrheiten, die andere nicht wahrnehmen können.",al={"was ist sapta","hintergrund von earth sapta","was bewirkt sapta"}},{q="Wo muss das Sapta getrunken werden?",a="Ihr dürft das Gebräu nur an einer eigens dafür bestimmten heiligen Stätte trinken. Für diesen Ritus reist Ihr auf einem verborgenen Pfad nach Norden den Berg hinauf, um den uralten Geiststein zwischen den Felsen zu finden.",al={"wo sapta trinken","standort des geiststeins","wo ist der geiststein"}},{q="Welchem Zweck dient der Ritus Call of Earth?",a="Der Ritus ist eine grundlegende Prüfung der Zwiesprache und Demut. Am Geiststein lehrt Euch das Trinken von Sapta, Stärke aus den Bergen und Geduld aus den Ebenen zu schöpfen. Es stimmt Euren sterblichen Geist auf die lebendige Welt ein, bevor Ihr Euch ungestümeren Elementen stellt.",al={"warum diese quest machen","bedeutung von call of earth","hintergrund von call of earth"}},{q="Wer weiß, wie Earth Sapta gebraut wird?",a="Nur wenige auserwählte, eingeweihte Schamanen wissen, wie Sapta gebraut wird. Das Brauen erfordert Wissen und spirituelle Vorbereitung. Das Rezept wird mit großer Ehrfurcht gehütet, denn der Trunk verbindet das sterbliche Bewusstsein unmittelbar mit urzeitlichen Kräften.",al={"wer kennt das sapta-rezept","kann jeder sapta herstellen"}},{q="Wie unterscheidet sich das Element Erde von den anderen Elementen?",a="Andere Elementarkräfte prallen aufeinander, brennen und tosen in heftiger Unruhe, während die Erde unerschütterliche Stille, Geduld und ein unnachgiebiges Fundament bietet. Ihr lernt zuerst Demut vor dem Stein, bevor Ihr Euch der unberechenbaren Doppelnatur der anderen Elemente stellt.",al={"erde im vergleich zu anderen elementen","erde im vergleich zu feuer wasser luft"}},{q="In welcher Umgebung wird dieser Ritus vollzogen?",a="Der Ritus findet hoch oben in einem kalten, verschneiten Gebirge statt. Ihr folgt einem abgeschiedenen Pfad durch Schnee und Fels, um trotz des beißenden Frosts mit den Geistern des Landes Zwiesprache zu halten.",al={"wo spielt call of earth","gefrorenes land erdquest"}}},fp="13,213,21.300.0,28.300.0,22.330.0,20.259.0,33.174.0,46.264.0,34.232.0,61.242.0,39.178.0"}
P.entries["quest:94375"] = {n="Call of Earth",s="Junge Schamanen in Dun Morogh suchen durch Call of Earth die Gunst der Erdgeister. Sie bringen Rohquarz zu Teo Hammerstorm in Ambossar, wo er ihn zum Herzen eines Erdtotems formt.",h="Junge Schamanen in Dun Morogh suchen durch Call of Earth die Gunst der Erdgeister.",kw={"ambossar","call of earth","das coldridgetal","dun morogh","erdtotem","rohquarz","schamane","teo hammerstorm","totem"},ang={["class:Shaman"]="Als Schamane beginnt Ihr Euren Weg, indem Ihr Zwiesprache mit den Erdgeistern haltet und Euch ein Erdtotem verdient.",["faction:Alliance"]="Als Schamane der Allianz findet Ihr rund um Ambossar, in den Landen von Eisenschmiede, Spiritisten der Elemente, die Euch den Weg weisen.",["race:Dwarf"]="Als Zwerg könnt Ihr die Verbundenheit Eures Volkes mit Stein und Berg mit dem schamanischen Weg vereinen, indem Ihr in Dun Morogh Zwiesprache mit Erdgeistern haltet."},sec={{t="Der flüsternde Stein",b="In Dun Morogh beginnen junge Schamanen ihren spirituellen Weg, indem sie den Erdgeist aufsuchen und seinen Lehren lauschen. Der Geist gibt ihnen Rohquarz, einen unscheinbaren Stein, der zum Herzen eines Erdtotems werden soll. Der Ritus verlangt Demut, Geduld, Stärke und Entschlossenheit. Ein Initiand lernt von der Erde und misst Wert nicht an Größe."},{t="Die Gunst des Berges",b="Teo Hammerstorm wartet in Ambossar darauf, dass der Initiand den Rohquarz zurückbringt. Er beurteilt, ob die Berggeister den Initianden anerkannt haben, und schickt jeden fort, der ohne den Stein erscheint. Bringt ihm den Quarz, und er formt ihn zu einem Erdtotem. Das Totem bindet den jungen Schamanen an die Stärke der Wurzeln der Welt."}},faq={{q="Wozu dient der Rohquarz?",a="Ein Erdgeist gibt Euch Rohquarz als Beweis Eurer Zwiesprache. Teo Hammerstorm fertigt daraus Euer Erdtotem.",al={"rohquarz zweck","was ist rohquarz","wozu wird rohquarz benötigt"}},{q="Wer ist Teo Hammerstorm?",a="Teo Hammerstorm ist ein Mentor in Ambossar, in Dun Morogh. Er prüft angehende Schamanen, indem er einen Beweis ihrer Zwiesprache mit den Elementen verlangt, bevor er ihre Totems fertigt.",al={"wer ist teo hammerstorm","teo hammerstorm standort","wo ist teo"}},{q="Was ist Call of Earth?",a="Durch Call of Earth suchen junge Schamanen Zwiesprache mit den Erdgeistern und verdienen sich ihr erstes Erdtotem.",al={"call of earth questreihe","was ist call of earth","erdtotem quest"}},{q="Was verlangt der Erdgeist vom Initianden?",a="Der Erdgeist verlangt von Euch, auf Eurer Suche nach Weisheit stark und geduldig zu bleiben. Er lehrt, dass kleine Dinge andere überdauern können und dass wahre Macht aus gegenseitigem Respekt zwischen Euch und der Erde erwächst.",al={"erdgeist lehre","was verlangt die erde","schamanische erdphilosophie"}},{q="Wo liegt Ambossar?",a="Ambossar liegt im Coldridgetal, in Dun Morogh. Junge zwergische Initianden werden dort ausgebildet und halten Zwiesprache mit den umliegenden Bergen.",al={"was ist ambossar","ambossar hintergrundgeschichte","wo findet call of earth statt"}},{q="Warum ist das Erdtotem wichtig?",a="Ein Totem verbindet einen Schamanen mit den Elementargeistern. Das Erdtotem bindet Euren Willen an die unerschütterliche Stärke und Widerstandskraft der Berge.",al={"warum ist das totem wichtig","schamanentotem hintergrundgeschichte","was bewirkt ein erdtotem"}}},fp="13,190,20.342.0,20.329.0,29.111.0,23.159.0,26.107.0,47.186.0,26.129.0,33.140.0"}
P.entries["quest:944"] = {n="Die Meistergleve",s="Bei der Meistergleve im Süden der Dunkelküste fürchtet Onu, dass der Schattenhammerkult den gefallenen uralten Schrecken erreicht hat. Er schickt Kundschafter der Allianz aus, um dem nachzugehen.",h="Bei der Meistergleve im Süden der Dunkelküste fürchtet Onu, dass der Schattenhammerkult den gefallenen...",kw={"dunkelküste","die meistergleve","alter herrscher","onu","wahrsagephiole","scrying bowl","schattenhammer"},ang={["class:Druid"]="Als Druide folgt Ihr Onus Ruf, um zu erfahren, wie die tief in der Erde begrabene uralte Verderbnis das Land und seine Tierwelt stört.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr dabei, den Schattenhammer daran zu hindern, uralte Schrecken zu erwecken, die die bedrängten Siedlungen im Norden Kalimdors überrennen könnten.",["race:NightElf"]="Als Nachtelf seht Ihr die Meistergleve als Mahnung an Schrecken, die älter sind als Euer Volk. Dass wahnsinnige Kultisten den heiligen Boden der Dunkelküste betreten, ist eine unerträgliche Entweihung."},sec={{t="Eine beunruhigende Präsenz",b="Onu sieht, wie die Verderbnis an der Dunkelküste fortbesteht und Wildtiere aus ihrer Heimat vertreibt. Die Naga an der Küste beunruhigen ihn, doch die Anzeichen des Schattenhammers beunruhigen ihn noch mehr. Seine Anhänger verehren urzeitliche Herrscher, die vor ihrem Sturz in längst vergangenen Zeitaltern über die Welt herrschten."},{t="Der gefallene Herrscher",b="Südlich von Onu umgibt eine düstere Ausgrabungsstätte eine gewaltige Kreatur, die von einer großen Steinwaffe durchbohrt ist. Onu gibt Euch eine Wahrsagephiole und bittet Euch, die Grube zu betreten und herauszufinden, ob sich dort Kultisten versammelt haben. Das Ungetüm ist seit Äonen tot, doch seinen Knochen haftet noch immer verderbende Macht an. Der Schattenhammer könnte versuchen, sie an sich zu reißen."}},faq={{q="Wer schickt mich auf diese Mission?",a="Onu, ein Urtum der Lehren, schickt Euch von seinem Platz an der Straße im Süden der Dunkelküste nahe dem Hain der Uralten aus.",al={"questgeber","wer vergibt die quest die meistergleve","start-npc"}},{q="Was ist die Meistergleve?",a="Im Süden der Dunkelküste fiel vor Äonen ein monströser uralter Herrscher, dessen Schädel von einer gewaltigen Steingleve durchbohrt wurde. Sein riesiges versteinertes Skelett liegt noch immer in der Erde begraben.",al={"was ist die meistergleve","geschichte der meistergleve","riesiger schädel an der dunkelküste"}},{q="Warum interessiert sich der Schattenhammerkult für diesen Ort?",a="Der Schattenhammer verehrt die alten, dunklen Mächte des urzeitlichen Azeroth. In den Überresten der längst toten Kreatur sind noch Splitter urzeitlicher Macht erhalten, und die Kultisten wollen sie sich zunutze machen.",al={"schattenhammerkult dunkelküste","warum sind schattenhammerkultisten hier","schattenhammer meistergleve"}},{q="Wie erstatte ich Onu Bericht?",a="Nachdem Ihr die Ausgrabungsgrube erkundet habt, benutzt die Wahrsagephiole aus Euren Taschen, um eine Scrying Bowl auf dem Boden heraufzubeschwören. Durch sie könnt Ihr mittels Magie mit Onu sprechen, ohne zu ihm zurückzukehren.",al={"wo die quest abgeben","wie die wahrsagephiole benutzen","scrying bowl"}},{q="Was folgt auf diese Erkundungsmission?",a="Sobald die Scrying Bowl die Anwesenheit der Kultisten bestätigt, schickt Onu Euch zu ihrem Lager im Twilight Camp, um mehr über ihre Aktivitäten zu erfahren.",al={"nächste quest","folgequest der meistergleve"}}},fx={fcbe4ca5={q="Warum schickt Euch Onu, um The Master's Glaive zu untersuchen?",a="Onu ist zutiefst beunruhigt über die Anwesenheit des Schattenhammerklans in der Dunkelküste. Als ein uralter Hüter der Lehre, der über die Wälder wacht, weiß er, dass dieser nihilistische Kult die besiegten Alten Götter der Erde verehrt. The Master's Glaive markiert die uralte Ruhestätte eines solchen gefallenen Ungeheuers, und Onu fürchtet, dass selbst im Tod Überreste der verweilenden dunklen Kraft des Wesens ausgegraben und von den Kultisten genutzt werden könnten.",al={"warum will onu das","onu beweggrund masters glaive","warum masters glaive auskundschaften"}},["821e537b"]={q="Wen sollt Ihr bei The Master's Glaive untersuchen?",a="Ihr seid entsandt worden, um die Kultisten des Schattenhammerklans auszuspähen, die um das gewaltige Monument lauern. Diese Eiferer verehren urzeitliche, uralte Mächte, die einst Azeroth beherrschten. Sie haben sich in der höhlenartigen Grube von The Master's Glaive versammelt, um die eldritische Essenz oder die verbliebene Stärke anzuzapfen, die noch immer vom versteinerten Schädel des dort erschlagenen uralten Wesens ausgeht.",al={"masters glaive ziel","wen suche ich bei masters glaive","wer ist bei masters glaive"}},dfa4afd6={q="Warum möchte Onu, dass Ihr The Master's Glaive ausspäht, anstatt selbst zu gehen?",a="Onu ist ein gewaltiger, verwurzelter Hüter der Lehre, der nicht einfach unbemerkt in die tiefe Schlucht von The Master's Glaive schlüpfen kann. Zudem sind die Nachtelfenstreitkräfte der Dunkelküste überlastet, da sie mit den eindringenden Naga an der Küste und der Verderbnis im ganzen Wildland zu kämpfen haben. Ein flinker, fähiger Reisender, bewaffnet mit einer Wahrsagephiole, kann das Lager der Kultisten leise ausspähen und magisch Bericht erstatten, ohne unerwünschte Aufmerksamkeit zu erregen.",al={"warum ich onu","warum schickt er mich zu masters glaive","warum kundschaftet onu masters glaive nicht selbst aus"}}},fp="19,162,21.256.0,15.334.0,29.119.0,28.172.0,57.180.0,28.187.0,32.147.0"}
P.entries["quest:94411"] = {n="Meddlesome Mages",s="Im Shen'darhochland versammeln sich Lehrlinge des Hohen Ordens an heiligen Steinen und pfuschen mit Magie. Ihre Zauber bedrohen die empfindlichen Kräfte, die die Insel zusammenhalten.",h="Im Shen'darhochland versammeln sich Lehrlinge des Hohen Ordens an heiligen Steinen und pfuschen mit Magie.",kw={"arkanes eingreifen","der hohe orden","lehrlinge des hohen ordens","meddlesome mages","shen'darhochland","shen'dorei","menhire"},ang={["class:Mage"]="Als Magier erkennt Ihr die Gefahr in der rücksichtslosen Zauberei des Hohen Ordens. Seine Lehrlinge missachten das empfindliche Gleichgewicht, das die Insel zusammenhält."},sec={{t="Vordringen zu den Steinen",b="Nördlich des Dorfes versammeln sich Lehrlinge des Hohen Ordens um uralte Menhire. Wiederholte Warnungen haben sie nicht von den heiligen Stätten ferngehalten. Sie treiben ihre arkanen Studien voran, während die örtlichen Anführer zögern, das Blut ihrer Verwandten, der Shen'dorei, zu vergießen. Deshalb rufen sie Hilfe von außen, um die Lehrlinge zu vertreiben, bevor bleibender Schaden entsteht."},{t="Die zerbrechliche Insel",b="Empfindliche mystische Kräfte halten das Land der Insel zusammen und schützen es. Die Verteidiger fürchten, dass der Hohe Orden den Gefahren seiner Zauberei wenig Beachtung schenkt. Ein unbedachter Zauber könnte diese Bindungen zerreißen. Dann käme der Untergang über alle, die dort leben."}},faq={{q="Worum geht es in der Quest Meddlesome Mages?",a="Ihr sollt Lehrlinge des Hohen Ordens vertreiben, die sich an heiligen Menhiren nördlich des Dorfes im Shen'darhochland versammelt haben.",al={"was ist meddlesome mages","meddlesome mages quest","was ist diese quest"}},{q="Wer sind die Lehrlinge des Hohen Ordens?",a="Der Hohe Orden ist eine Magierfraktion, deren Lehrlinge Warnungen missachtet haben und auf heiligen Boden vorgedrungen sind, um mit Magie zu experimentieren. Die Einheimischen betrachten sie als ihre Brüder und Schwestern unter den Shen'dorei.",al={"wer sind die lehrlinge des hohen ordens","was ist der hohe orden","magier des hohen ordens"}},{q="Warum müssen die Lehrlinge des Hohen Ordens vertrieben werden?",a="Die Lehrlinge haben wiederholte Warnungen missachtet, sich von den Menhiren fernzuhalten. Ihre rücksichtslose Zauberei bedroht die empfindlichen Kräfte, die die Insel zusammenhalten, und könnte die Heimat zerstören.",al={"warum den hohen orden vertreiben","warum die lehrlinge bekämpfen","problem mit den menhiren"}},{q="Wo versammeln sich die Lehrlinge des Hohen Ordens?",a="Die Lehrlinge des Hohen Ordens versammeln sich an Menhiren nördlich des Dorfes im Shen'darhochland.",al={"wo ist diese quest","lage des shen'darhochlands","menhire nördlich des dorfes"}},{q="Wer sind die Shen'dorei, die in der Quest erwähnt werden?",a="Die Shen'dorei sind mit den Menschen verwandt, die um Hilfe bitten. Ein Konflikt im eigenen Volk lastet schwer auf den örtlichen Anführern, doch sie fühlen sich gezwungen, zum Schutz ihrer Heimat gegen den Hohen Orden vorzugehen.",al={"wer sind shendorei","shendorei brüder und schwestern","was sind shen'dorei"}},{q="Welche Gefahr stellen die Magier für die Insel dar?",a="Empfindliche Kräfte halten die Insel zusammen, und sie sind verletzlich. Ungezügeltes arkanes Eingreifen könnte sie zerreißen und die Insel zerstören.",al={"was ist die gefahr","empfindliche kräfte der insel","was könnte der insel geschehen"}}},fp="16,168,26.347.0,18.259.0,41.133.0,35.191.0,49.195.0,47.100.0,46.196.0,44.133.0"}
P.entries["quest:94413"] = {n="A Magical Affront",s="Auf Zephras bringt A Magical Affront den örtlichen Orden gegen die Windformer auf. Der Orden will die an die Oberfläche getretenen Ley-Linien nutzen und erforschen, während die Windformer sie als Narben betrachten, die geheilt werden müssen. Ihr Konflikt hat den südwestlichen Wald erreicht.",h="Auf Zephras bringt A Magical Affront den örtlichen Orden gegen die Windformer auf.",kw={"a magical affront","arkan","ley-linie","ley-linien","narben","windformer","zephras"},ang={["class:Druid"]="Als Druide spürt Ihr vielleicht die Spannung in der Sichtweise der Windformer, die die freigelegten Ley-Linien als heilungsbedürftige Wunden im natürlichen Land betrachten.",["class:Mage"]="Als Magier seht Ihr die an die Oberfläche getretenen Ley-Linien auf Zephras vielleicht als seltene Gelegenheit, rohe mystische Energie unmittelbar zu erforschen. Ihr Erhalt ist für Eure arkane Kunst von Bedeutung.",["class:Shaman"]="Als Schamane teilt Ihr vielleicht das Verantwortungsgefühl der Windformer für die Elemente und die Natur, während sie Störungen auf Zephras beruhigen und heilen wollen. Dadurch stehen ihre Ziele im Widerspruch zu denen der Orden, die rohe magische Strömungen nutzen."},sec={{t="Freigelegte Strömungen",b="Uralte Leitbahnen roher Magie haben auf Zephras vor Kurzem die Erde durchbrochen. Für Gelehrte und Magiekundige des örtlichen Ordens ist dies ein seltener Segen. Direkter Kontakt mit den Ley-Linien gewährt ihnen neue Einblicke in die arkanen Strömungen der Region und vertieft ihre Beherrschung der Magie."},{t="Narben und Zwist",b="Die Windformer sehen die freigelegten Energien als offene Wunden und Narben, die sich über Zephras ziehen. Sie versammeln sich an den Bruchstellen, um die Ley-Linien zu unterdrücken oder zu heilen und die Erde zu heilen.\n\nDer Orden ist auf diese rohe Macht angewiesen und sieht ihre Bemühungen daher als Bedrohung. Er schickt Euch nach Südwesten in den Wald, um die Windformer zurückzudrängen."}},faq={{q="Wer sind die Windformer?",a="Die Windformer sind eine Gruppe auf Zephras, die die an die Oberfläche getretenen Ley-Linien als unnatürliche Wunden im Land betrachtet. Sie wollen diese heilen und geraten dadurch mit Orden in Konflikt, die die Ley-Linien erforschen und ihre Energien kanalisieren.",al={"wer sind die windformer","was sind windformer","windformer zephras"}},{q="Warum will der Orden die Windformer vertreiben lassen?",a="Der Orden braucht Zugang zu den an die Oberfläche getretenen Ley-Linien, um sein Verständnis der Magie zu vertiefen. Die Windformer versuchen, sie zu unterdrücken oder zu heilen, weshalb der Orden ihre Bemühungen als Bedrohung sieht und Euch schickt, um sie zu vertreiben.",al={"warum windformer töten","warum gegen die windformer kämpfen","konflikt mit windformern"}},{q="Was sind die Ley-Linien auf Zephras?",a="Ley-Linien sind Leitbahnen mystischer Energie, die die Welt durchziehen. Auf Zephras haben sie vor Kurzem die Erde durchbrochen, wodurch rohe Magie freigelegt wurde, die Arkankundige nun unmittelbar erforschen können.",al={"was sind ley-linien auf zephras","zephras ley-linien","ley-linien an der oberfläche"}},{q="Wo liegt die umkämpfte Ley-Linie?",a="Die umkämpfte Ley-Linie liegt im südwestlichen Wald auf Zephras. Dort haben sich Windformer versammelt, um den freigelegten Magiestrom zu verschließen oder zu heilen.",al={"wo liegt die ley-linie im wald","lage der ley-linie","wald im südwesten"}},{q="Warum betrachten die Windformer die Ley-Linien als Narben?",a="Die Windformer betrachten den plötzlichen Ausbruch roher unterirdischer Energie durch die Erde als gewaltsam gerissene Narben, die sich über Zephras ziehen. Sie glauben, dass die Heilung dieser Risse das natürliche Gleichgewicht wiederherstellt, und geraten dadurch mit Zauberwirkern in Konflikt, die die Ley-Linien offen halten wollen.",al={"warum wollen windformer ley-linien heilen","sind ley-linien auf zephras schädlich","heilung der narben"}},{q="Welche Bedeutung hat Zephras in diesem Konflikt?",a="Auf Zephras sind die Ley-Linien vor Kurzem an die Oberfläche getreten. Ihre rohe Magie hat das Land zum Brennpunkt zwischen jenen gemacht, die ihre arkane Macht beherrschen wollen, und jenen, die die Brüche als heilungsbedürftige Wunden sehen.",al={"was ist zephras","wo spielt a magical affront","geschichte von zephras"}}},fp="17,236,17.287.0,16.313.0,24.195.0,51.208.0,33.200.0,39.139.0,51.254.0,53.214.0"}
P.entries["quest:94414"] = {n="The Anchors of Zephras",s="Auf der Insel Zephras bittet Halaan Hawk-Eye Euch, die uralten Ankerpylone zu beobachten, welche die Insel in der Luft halten. Ihre Magie hat zu schwanken begonnen, und der Segen der Windgeister ist womöglich nicht mehr beständig.",h="Auf der Insel Zephras bittet Halaan Hawk-Eye Euch, die uralten Ankerpylone zu beobachten, welche die Insel in...",kw={"ankerpylon","anker von zephras","halaan hawk-eye","kraftlinien","himmelssicht","windgeister","zephras"},ang={["class:Mage"]="Als Magier könnt Ihr Halaans scharfe Sehkraft als natürliche Gabe erkennen.",["class:Shaman"]="Als Schamane wisst Ihr, dass der Segen der Windgeister die Ankerpylone erhält. Ihre instabile Magie verlangt nach der Aufmerksamkeit eines Elementars."},sec={{t="Die Fesseln der Insel",b="Windgeister verliehen den uralten Ankerpylonen von Zephras die Macht, die schwebende Insel zu binden und zu erhalten. Ihre Magie hält das Land inmitten der aufgewühlten Himmel stabil. Aus der Ferne wirken die hoch aufragenden Monolithen unversehrt. Doch die Insel ist auf den fortwährenden Segen der Windgeister angewiesen."},{t="Ein beunruhigender Wandel",b="Die Ankerpylone wirken erhaben und unbeschädigt, doch ihre Magie ist unberechenbar geworden. Halaan Hawk-Eye sagt, die Harmonie, die sie erhält, sei instabil und unbeständig geworden. Es gibt keine deutlichen Anzeichen körperlicher Schäden. Jene, die über die Haine wachen, haben Grund, die Bedrohung der Insel zu fürchten."},{t="Halaans Gabe",b="Halaan Hawk-Eye kann weder mit Himmelssicht zwischen die Welten blicken noch die tiefen Kraftlinien von Zephras anzapfen. Seine Gabe ist eine natürliche Sehkraft, scharf genug, um über gewaltige Entfernungen zu reichen. Er leiht Neuankömmlingen diesen Blick, damit sie die fernen Pylone untersuchen und auf Veränderungen im Schicksal ihrer Heimat achten können."}},faq={{q="Was sind die Ankerpylone auf Zephras?",a="Die Ankerpylone sind uralte Bauwerke, welche die Windgeister Zephras schenkten. Sie binden und erhalten die Insel und halten sie stabil über der umliegenden Welt.",al={"was sind die anker","zephras ankerpylon","was ist ein ankerpylon"}},{q="Was stimmt mit den Ankerpylonen nicht?",a="Die Pylone zeigen keine offensichtlichen körperlichen Schäden, doch ihre stabilisierende Magie ist instabil und unbeständig geworden. Die Ursache bleibt unbekannt.",al={"warum versagen die anker","problem mit ankerpylonen","was ist mit den ankern geschehen"}},{q="Wer ist Halaan Hawk-Eye?",a="Halaan Hawk-Eye wacht über die Haine der Insel Zephras. Seine natürliche Sehkraft reicht über große Entfernungen, und er wacht über das Wohlergehen des Landes.",al={"halaans geschichte","wer ist halaan"}},{q="Was ist Halaans Gabe?",a="Halaans Gabe ist eine außergewöhnlich scharfe Sehkraft über große Entfernungen. Sie ist natürlich, anders als die Himmelssicht oder die Macht, die tiefen Kraftlinien von Zephras anzuzapfen.",al={"halaans gabe","wie sieht halaan so weit"}},{q="Was ist Himmelssicht?",a="Himmelssicht ist eine mystische Wahrnehmung, mit der manche Kundige zwischen die Welten blicken können, weit über gewöhnliche Sehkraft hinaus.",al={"was ist himmelssicht","himmelssicht bedeutung"}},{q="Woher kommt die Magie, welche die Pylone antreibt?",a="Die Windgeister schenkten Zephras die Ankerpylone. Halaan sagt, dass sie die Insel binden und erhalten, erklärt aber nicht, woher ihre fortwährende Kraft stammt.",al={"wer erschuf die pylone","ursprung der ankerpylone"}}},fx={["61bc2f74"]={q="Warum möchte Halaan Hawk-Eye, dass Ihr Euch den Ankerpylon anseht?",a="Halaan Hawk-Eye wacht über den Hain und kümmert sich zutiefst um das Wohlergehen von Zephras. Die alten Ankerpylonen, Geschenke der Geister der Winde, binden und erhalten die Insel, doch ihre Magie ist kürzlich instabil und unbeständig geworden. Obwohl sie physisch unbeschädigt erscheinen, bietet Halaan an, seine weitreichende Vision mit Euch zu teilen, damit Ihr die Pylonen aus erster Hand sehen und den empfindlichen Zustand Eurer Heimat verstehen könnt.",al={"halaan beweggrund","warum den ankerpylon ansehen","warum will halaan das"}}},fp="22,192,19.274.0,18.282.0,13.287.0,38.155.0,37.135.0,23.142.0,22.148.0,17.114.0,51.159.0"}
P.entries["quest:94427"] = {n="A Lesson in Divinity",s="Euer Orden schickt Euch zu Tanis Alderwood ins Trade Quarter der Unterstadt. Dort bietet sich Euch die Gelegenheit, durch gute Taten Gnade zu zeigen.",h="Euer Orden schickt Euch zu Tanis Alderwood ins Trade Quarter der Unterstadt.",kw={"a lesson in divinity","göttlichkeit","gnade","betteln","tanis alderwood","trade quarter","unterstadt"},ang={["class:Priest"]="Für Euch als Priester definiert Euer Orden Göttlichkeit als das Tun des Guten um seiner selbst willen. Er sagt, eine Tragödie könne die Gnade bedrohen, die Euch zu Lebzeiten auszeichnete."},sec={{t="Ein Ruf zur Gnade",b="Euer Orden lehrt, dass Göttlichkeit bedeutet, um seiner selbst willen Gutes zu tun, statt danach zu streben, selbst ein Gott zu werden. Er sagt, eine Tragödie habe Euch hierhergebracht. Nun bittet er Euch, Tanis Alderwood im Trade Quarter der Unterstadt aufzusuchen. Tanis ist in Not und könnte von Eurer Gnade profitieren."},{t="Tanis' Flehen",b="Als Ihr Euch Tanis Alderwood nähert, fürchtet Tanis, dass Ihr Schaden zufügen könntet. Tanis beteuert, keinen Streit mit Euch oder Eurem Orden zu haben. Dann fleht Tanis Euch an, in Ruhe gelassen zu werden."}},faq={{q="Wer ist Tanis Alderwood?",a="Tanis Alderwood ist eine Person in Not im Trade Quarter der Unterstadt.",al={"tanis","wer ist tanis","person im trade quarter"}},{q="Warum werde ich zu Tanis geschickt?",a="Euer Orden sagt, Tanis Alderwood könnte von Eurer Gnade profitieren.",al={"warum tanis","tanis helfen","was ist der sinn"}},{q="Was bedeutet Göttlichkeit für meinen Orden?",a="Euer Orden definiert Göttlichkeit als das Tun des Guten um seiner selbst willen, statt danach zu streben, selbst ein Gott zu werden.",al={"bedeutung von göttlichkeit","gutes um seiner selbst willen","was ist göttlichkeit"}},{q="Wo kann ich Tanis Alderwood finden?",a="Ihr findet Tanis Alderwood im Trade Quarter der Unterstadt.",al={"tanis aufenthaltsort","wo ist tanis","trade quarter"}}},fp="20,127,16.244.0,14.156.1,23.66.0,23.60.0,36.88.0,33.60.0"}
P.entries["quest:94434"] = {n="A Lesson in Divinity",s="In der Unterstadt bittet Euch Tanis Alderwood um frischen Stoff. Seine Frau fällt auseinander, und er hofft, sie einwickeln zu können, bis ein Apotheker Zeit hat.",h="In der Unterstadt bittet Euch Tanis Alderwood um frischen Stoff.",kw={"a lesson in divinity","apotheker","bettler","dunkle fürstin","leinenstoff","tanis alderwood","unterstadt","frau"},sec={{t="Die Bitte eines Bettlers",b="Die Apotheker sind mit den Angelegenheiten der Dunklen Fürstin beschäftigt. Deshalb bittet Euch Tanis, Leinen für seine Frau zu bringen. Er hofft, dass der Stoff sie zusammenhält, während sie auf Hilfe warten."}},faq={{q="Wer bittet um Hilfe?",a="Tanis Alderwood, ein Bettler in der Unterstadt, bittet Euch, seiner Frau zu helfen.",al={"wer ist tanis","tanis alderwood","bettler"}},{q="Was fehlt Tanis' Frau?",a="Tanis sagt, sie falle buchstäblich auseinander und brauche einen Verband, der sie zusammenhält.",al={"frau fällt auseinander","was ist seiner frau passiert","tanis' frau"}},{q="Warum können die Apotheker nicht helfen?",a="Tanis sagt, die Apotheker seien mit den Angelegenheiten der Dunklen Fürstin beschäftigt.",al={"apotheker beschäftigt","warum kein apotheker","angelegenheiten der dunklen fürstin"}},{q="Was braucht Tanis?",a="Tanis bittet Euch, frischen Stoff zu bringen, damit er seine Frau einwickeln kann, während sie auf die Apotheker warten.",al={"welchen stoff braucht er","leinen für tanis","bettler helfen"}}},fp="20,140,15.175.0,23.70.0,31.84.0,32.71.0,21.97.0"}
P.entries["quest:94435"] = {n="A Lesson in Divinity",s="Tanis Alderwood dankt Euch für Eure Hilfe und nennt Euch einen Freund. Danitha Morr sieht in diesem kleinen Dienst eine Möglichkeit, die Verbindung der Verlassenen zum Licht zu stärken.",h="Tanis Alderwood dankt Euch für Eure Hilfe und nennt Euch einen Freund.",kw={"a lesson in divinity","danitha morr","dunkle lady","verlassene","licht","misstrauen","symbol","tanis alderwood"},ang={["faction:Alliance"]="Als Reisender der Allianz hört Ihr, wie Danitha die Bemühungen der Verlassenen beschreibt, ihrem Volk wieder zu Wohlstand zu verhelfen.",["race:Undead"]="Als Mitglied der Verlassenen hört Ihr, wie Danitha zu Mut und Rechtschaffenheit aufruft, um Eurem Volk wieder zu Wohlstand zu verhelfen."},sec={{t="Ein kleiner Dienst",b="Danitha Morr sagt, Eure Hilfe könne die Verbindung der Verlassenen zum Licht stärken. Unter den Anhängern der Dunklen Lady halten sich Misstrauen und Verschwörungen. Die Verlassenen müssen dieser Angst mit Mut und Rechtschaffenheit begegnen. Danitha gibt Euch ein Symbol für das, was als Nächstes kommt."}},faq={{q="Wer dankt mir?",a="Tanis Alderwood dankt Euch dafür, dass Ihr ihm geholfen habt, und sagt, dass Ihr in ihm immer einen Freund haben werdet.",al={"tanis alderwood","wer ist tanis","tanis dankt"}},{q="Was bedeutet meine Hilfe laut Danitha?",a="Danitha sagt, selbst ein kleiner Dienst könne die Verbindung der Verlassenen zum Licht stärken.",al={"warum danitha helfen","bedeutung des kleinen dienstes","verbindung zum licht"}},{q="Warum erwähnt Danitha Misstrauen?",a="Danitha sagt, die Dunkle Lady und einige in ihren Diensten misstrauten ihnen, und manche verschwörten sich sogar gegen sie.",al={"misstrauen gegen verlassene","dunkle lady angst","warum wird ihnen misstraut"}},{q="Was gibt mir Danitha?",a="Ein Symbol von Danitha für das, was als Nächstes kommt.",al={"welches symbol","danithas gegenstand","symbol für das nächste"}}},fp="20,173,15.265.0,19.89.0,36.97.0,34.107.0,26.43.0"}
P.entries["quest:94436"] = {n="A Lesson in Divinity",s="In A Lesson in Divinity bittet Danitha Morr Euch, mit dem Symbol des Lebens zu zeigen, was ein Priester vermag. Todeswache Billmuth sucht auf der Bandarionfestung Hilfe für einen Freund.",h="In A Lesson in Divinity bittet Danitha Morr Euch, mit dem Symbol des Lebens zu zeigen, was ein Priester...",kw={"a lesson in divinity","die bandarionfestung","danitha morr","todeswache billmuth","verlassene","licht","priester","symbol des lebens"},ang={["class:Priest"]="Danitha bittet Euch, als Priester mit dem Symbol des Lebens Eure Fähigkeit zu zeigen, das Licht zu kanalisieren."},sec={{t="Eine Bitte um Hilfe",b="Billmuth sagt, die Priester hätten ihn abgewiesen, und sein Freund habe womöglich niemanden sonst, an den er sich wenden könne. Er ist nicht stolz darauf, Euch zu bitten, doch er braucht Hilfe für die Verlassenen. Das Symbol des Lebens soll Eure Fähigkeit zeigen, das Licht zu kanalisieren. Der Umgang damit kann Unbehagen verursachen. Seine Macht kann Euch dennoch Verbündeter und Wegweiser sein, selbst für die Verlassenen, deren Erschaffung mit einer Kraft verbunden ist, die dem Licht entgegensteht."}},faq={{q="Wer bittet um Hilfe?",a="Todeswache Billmuth sucht auf der Bandarionfestung Hilfe für einen Freund.",al={"billmuth hilfe","wer braucht hilfe"}},{q="Warum bittet Billmuth einen Priester?",a="Billmuth sagt, die Priester hätten ihn abgewiesen, und Ihr seid womöglich die einzige Chance für seinen Freund.",al={"warum priester","priester haben ihn abgewiesen"}},{q="Was ist das Symbol des Lebens?",a="Das Symbol des Lebens ist ein Talisman des Lichts, den Danitha Morr Euch gibt, um Eure Fähigkeit zu zeigen, das Licht zu kanalisieren.",al={"symbol des lebens","talisman des lichts"}},{q="Warum könnte der Umgang mit dem Symbol des Lebens schmerzen?",a="Danitha warnt, dass der Talisman Unbehagen verursachen kann, weil das Licht der Kraft entgegensteht, die die Verlassenen erschaffen hat.",al={"symbol schmerzen","licht schmerzt"}},{q="Wo kann ich Todeswache Billmuth finden?",a="Todeswache Billmuth befindet sich unten in der Bandarionfestung.",al={"billmuth aufenthaltsort","die bandarionfestung"}}},fp="20,173,14.380.0,23.73.0,31.83.0,27.116.0,44.121.0,37.52.0"}
P.entries["quest:94438"] = {n="A Lesson in Divinity",s="Danitha Morr schickt Euch ins Giftwebertal, um Todeswache Falgan zu finden. Er und sein Begleiter wurden getrennt, nachdem sie erfahren hatten, dass der Scharlachrote Kreuzzug einen Angriff auf Brill plant.",h="Danitha Morr schickt Euch ins Giftwebertal, um Todeswache Falgan zu finden.",kw={"a lesson in divinity","billmuth","brill","danitha morr","todeswache falgan","scharlachroter kreuzzug","symbol des lebens","giftwebertal"},sec={{t="Falgans Rückkehr",b="Todeswache Falgan ging mit Billmuth ins Giftwebertal, um die Aktivitäten des Scharlachroten Kreuzzugs auszukundschaften. Sie erfuhren, dass der Scharlachrote Kreuzzug irgendeinen Angriff plant. Nun fragt Falgan, ob Ihr den Verlassenen weiterhelfen werdet."}},faq={{q="Wer bittet mich, Falgan zu finden?",a="Danitha Morr bittet Euch, Todeswache Falgan zu finden und ihm zu helfen, wenn Ihr könnt.",al={"wer hat mich geschickt","danitha morr","questgeber"}},{q="Wo ist Falgan?",a="Falgan ist im Giftwebertal.",al={"falgans aufenthaltsort","wo ist falgan","todeswache finden"}},{q="Was ist mit Falgan geschehen?",a="Falgan blieb zurück, nachdem ein Geräusch die Streitkräfte des Scharlachroten Kreuzzugs auf ihn und seinen Begleiter aufmerksam gemacht hatte. Sein Begleiter erreichte Brill ohne ihn.",al={"falgan vermisst","was ist geschehen","falgan retten"}},{q="Was haben Falgan und Billmuth entdeckt?",a="Falgan und Billmuth erfuhren, dass der Scharlachrote Kreuzzug irgendeinen Angriff plant.",al={"befehle des scharlachroten kreuzzugs","was haben sie gefunden","angriffspläne"}},{q="Wozu dient das Symbol des Lebens?",a="Das Symbol des Lebens wird verwendet, um Todeswache Falgan wieder zum Leben zu erwecken.",al={"falgan wiederbeleben","symbol des lebens","wie falgan retten"}},{q="Was fragt Falgan nach seiner Rückkehr?",a="Nach seiner Rückkehr fragt Falgan, ob Ihr bereit seid, den Verlassenen weiterzuhelfen.",al={"verlassenen helfen","was kommt als nächstes","falgan fragt"}}},fp="20,163,15.200.0,32.72.0,16.27.0,24.124.0,38.79.0,31.67.0,37.82.0"}
P.entries["quest:94440"] = {n="A Lesson in Divinity",s="Todeswache Billmuth braucht Euch, um Angriffspläne des Scharlachroten Kreuzzugs aus dem Giftwebertal zu bergen. Die Todeswache erwartet einen Angriff und hofft, mithilfe der Pläne einen Hinterhalt vorbereiten zu können.",h="Todeswache Billmuth braucht Euch, um Angriffspläne des Scharlachroten Kreuzzugs aus dem Giftwebertal zu...",kw={"a lesson in divinity","angriffspläne","die bandarionfestung","todeswache billmuth","verlassene","scharlachroter kreuzzug","giftwebertal"},sec={{t="Befehle für die Festung",b="Mitglieder des Scharlachroten Kreuzzugs tragen Einsatzbefehle in ihren Beuteln, und die Todeswache erwartet einen Angriff. Bringt eine Abschrift der Pläne zu Todeswache Billmuth in der Bandarionfestung. Dann kann die Todeswache einen Hinterhalt vorbereiten."},{t="Ein Freund gerettet",b="Billmuth dankt Euch dafür, dass Ihr seinen Freund gerettet habt, und sagt, er werde die Pläne seinem Befehlshaber bringen. Eure Taten haben ihm gezeigt, dass Ihr durch und durch zu den Verlassenen gehört, obwohl manche seiner Leute Eurer Klasse misstrauen."}},faq={{q="Was braucht Billmuth?",a="Todeswache Billmuth bittet Euch, die Angriffspläne des Scharlachroten Kreuzzugs aus dem Giftwebertal zu bergen.",al={"was will billmuth","billmuth pläne","pläne für billmuth"}},{q="Wo sind die Angriffspläne?",a="Die Mitglieder des Scharlachroten Kreuzzugs im Giftwebertal tragen die Angriffspläne bei sich.",al={"wo sind die pläne","pläne des scharlachroten kreuzzugs fundort","angriffspläne finden"}},{q="Warum will die Todeswache die Pläne?",a="Die Todeswache erwartet einen Angriff und will die Pläne, um einen Hinterhalt vorbereiten zu können.",al={"warum pläne beschaffen","wozu dienen die pläne","todeswache hinterhalt"}},{q="Wer soll die Pläne erhalten?",a="Bringt die Pläne zu Todeswache Billmuth in der Bandarionfestung.",al={"wer bekommt die pläne","pläne zurückbringen zu","wo ist billmuth"}}},fp="20,172,19.209.0,14.221.1,24.94.0,27.62.0,39.81.0,29.57.0"}
P.entries["quest:94441"] = {n="A Lesson in Divinity",s="Ein anderer Verlassener bittet Euch, Danitha Morr für den Dienst der Paladine in der Bandarionfestung zu danken. Eure Arbeit hat Euch die Dankbarkeit der Todeswache eingebracht und beschert Euch ein Geschenk der Erlösung.",h="Ein anderer Verlassener bittet Euch, Danitha Morr für den Dienst der Paladine in der Bandarionfestung zu...",kw={"a lesson in divinity","die bandarionfestung","danitha morr","todeswache","verlassene","licht","erlösung","symbol des lebens"},sec={{t="Dank in der Festung",b="Ein anderer Verlassener bittet Euch, Danitha Morr in der Bandarionfestung seinen Dank zu überbringen. Die übrige Todeswache wird von dem Dienst erfahren, den Ihr und die anderen Paladine geleistet habt. Sie sind stolz, Euch zu den Verlassenen zu zählen, und vertrauen darauf, dass die Dunkle Fürstin über Euch wacht."},{t="Ein Geschenk des Lichts",b="Danitha sagt, ein Paladin, der bereit ist, eine der größten Segnungen des Lichts zu empfangen, könne das Symbol des Lebens nutzen. Sie gewährt Euch Erlösung, mit der Ihr gefallene Gefährten wiederbeleben könnt. Euer Dienst ist den Verlassenen und den Paladinen der Bandarionfestung wichtig. Die Todeswache hofft, dass solche Taten die Herzen und den Verstand anderer Verlassener gewinnen."}},faq={{q="Wem soll ich danken?",a="Ihr werdet gebeten, Danitha Morr für den Dienst der Paladine in der Bandarionfestung zu danken.",al={"wer ist danitha","danitha danken","danitha morr"}},{q="Wer wird von dem Dienst erfahren?",a="Die übrige Todeswache wird vom Dienst der Paladine in der Bandarionfestung erfahren.",al={"dank der todeswache","wer erfährt davon","dienst in der festung"}},{q="Was bewirkt das Symbol des Lebens?",a="Das Symbol des Lebens kann von einem Paladin genutzt werden, der bereit ist, eine der größten Segnungen des Lichts zu empfangen.",al={"symbol des lebens","was bewirkt es"}},{q="Warum ist die Todeswache stolz auf mich?",a="Die Todeswache ist stolz, Euch zu den Verlassenen zu zählen, und schätzt den Dienst, den Ihr mit den Paladinen der Bandarionfestung geleistet habt.",al={"verlassene stolz","warum stolz","todeswache stolz"}}},fp="20,178,18.262.0,15.335.1,15.82.0,32.82.0,32.101.0,34.129.0"}
P.entries["quest:94449"] = {n="Call of Fire",s="In Dun Morogh schickt ein Ältester Schamaneninitianden zu Bruegs Kindleborn, um ihre Bereitschaft für das Feuersapta zu prüfen. Durch die Erde haben sie bereits Geduld und Erdung gelernt.",h="In Dun Morogh schickt ein Ältester Schamaneninitianden zu Bruegs Kindleborn, um ihre Bereitschaft für das...",kw={"bruegs kindleborn","call of fire","dun morogh","earth sapta","feuertotem","feuersapta","schamane","südtoraußenposten"},ang={["class:Shaman"]="Als Schamane stellt Ihr Euch einer spirituellen Prüfung, die Euch von der Ausdauer des Steins zur ungestümen, zerstörerischen Macht des Feuers führt.",["faction:Alliance"]="Als Schamane der Allianz folgt Ihr dem Rat Eurer Ältesten in den Bergen von Dun Morogh, um die Zwiesprache mit den Elementen des Feuers zu erwecken.",["race:Dwarf"]="Als Zwerg stellt Ihr Euch dieser Prüfung hoch über dem Südtoraußenposten in Dun Morogh, wo Eure Disziplin am brennenden Hunger der Flamme gemessen wird."},sec={{t="Die brennende Prüfung",b="Nachdem Schamanen durch die Erde Geduld und Erdung bewiesen haben, stellen sie sich einer unberechenbareren Kraft: dem Feuerelementargeist. Stein bleibt beständig, doch Feuer verspricht Chaos, Verderben und ungestüme Energie. Deshalb schickt ein Ältester den Initianden über die schneebedeckten Gipfel von Dun Morogh, damit er Rat sucht, bevor er versucht, die wilde Hitze zu bändigen."},{t="Der Einsiedler der Gipfel",b="Bruegs Kindleborn wacht in einer abgelegenen Höhle hoch in den Bergen über dem Südtoraußenposten. Wenn ein Initiand mit der Empfehlung eines Ältesten eintrifft, bereitet Bruegs ihn auf das Feuersapta vor. Er warnt, dass sich der Hunger der Flamme, zu brennen und zu verzehren, leicht entfachen lässt. Um sie zu meistern, muss ein Schamane wissen, wann er sich zurückhalten muss."}},faq={{q="Wer ist Bruegs Kindleborn?",a="Bruegs Kindleborn unterweist Schamanen in einer Berghöhle hoch über dem Südtoraußenposten in Dun Morogh. Älteste schicken Initianden zu ihm, und er beurteilt, ob sie die nötige Reife und Disziplin besitzen, um das Feuersapta zu empfangen.",al={"wer ist bruegs kindleborn","bruegs kindleborn hintergrundgeschichte","wo ist bruegs"}},{q="Was ist das Feuersapta?",a="Ein Sapta ist ein elementarer Trank oder eine Zubereitung, die einem Schamanen erlaubt, mit den Geistern des jeweiligen Elements Zwiesprache zu halten. Das Feuersapta ermöglicht die Zwiesprache mit der Flamme und ihrer rohen Kraft und erfordert geistige Konzentration sowie vorherige Erdung im Stein.",al={"was ist feuersapta","feuersapta","sapta bedeutung"}},{q="Wo befindet sich Bruegs Kindleborn?",a="Bruegs Kindleborn lebt weit im Osten in den verschneiten Bergen von Dun Morogh, geborgen in einer Höhle mit Blick auf den Südtoraußenposten.",al={"wo ist bruegs kindleborn zu finden","südtoraußenposten höhle","wo call of fire abgeben"}},{q="Welchem Zweck dient Call of Fire?",a="Call of Fire konfrontiert Schamanen, die Geduld bewiesen und die Erde gemeistert haben, mit der chaotischen Macht der Zerstörung. Bruegs Kindleborn wacht über ihre Prüfung.",al={"was ist call of fire","feuertotem quest dun morogh"}},{q="Warum muss ein Schamane vor dem Feuer die Lehren des Steins lernen?",a="Erde lehrt unerschütterliche Geduld, Beständigkeit und Kontrolle. Ohne die Erdung des Steins läuft ein Schamane Gefahr, vom unberechenbaren Hunger und den zerstörerischen Leidenschaften des Feuers überwältigt zu werden.",al={"warum zuerst stein","die lehren des steins in erinnerung rufen"}},{q="Welche Voraussetzungen müssen vor Call of Fire erfüllt sein?",a="Vor diesem Ritus hat ein Initiand in früheren Prüfungen Geduld und Erdung in der Erde bewiesen. Der Älteste schickt einen Schüler erst zu Bruegs Kindleborn, wenn sich dessen Disziplin als gefestigt erwiesen hat.",al={"call of fire voraussetzungen","verbindung zur geduldsquest"}}},fp="12,175,17.311.0,24.321.0,25.214.0,26.225.0,35.122.0,40.155.0,57.173.0,68.186.0"}
P.entries["quest:94465"] = {n="Call of Fire",s="Ihr tragt die Fackel der schlafenden Flamme durch Loch Modan, um Braldir Ashmantle aufzusuchen. Die Prüfung zeigt, ob ein Initiand bereit ist, die elementare Flamme zu führen.",h="Ihr tragt die Fackel der schlafenden Flamme durch Loch Modan, um Braldir Ashmantle aufzusuchen.",kw={"braldir ashmantle","call of fire","feuertotem","loch modan","schamane","schrein der schlafenden flamme","fackel der schlafenden flamme","tal der könige"},ang={["class:Shaman"]="Als angehender Schamane beweist Ihr Eure Hingabe an die Elementargeister des Feuers, indem Ihr eine heilige Fackel auf einen abgelegenen Gipfel in Loch Modan tragt.",["faction:Alliance"]="Überall in den Landen der Allianz sehen gewöhnliche Reisende nur kahles Berggestein. Die Hüter des Schreins bewahren uralte Geheimnisse der Elemente vor gewöhnlichen Blicken.",["race:Dwarf"]="Als Zwerg hört Ihr zwergische Sprache, während der Pfad jenseits des Tals der Könige in die zerklüfteten Höhen von Khaz Modan führt."},sec={{t="Jenseits des Tals der Könige",b="Um das Feuertotem zu erlangen, tragt Ihr die unentzündete Fackel der schlafenden Flamme in die zerklüfteten Höhen von Loch Modan. Jenseits der Steinmetzarbeiten im Tal der Könige führt ein steiler Pfad auf einen abgelegenen Berggipfel. Dort herrschen die Elemente, fernab der Straßen, die Reisende kennen."},{t="Der Schrein der schlafenden Flamme",b="Braldir Ashmantle wacht auf einem hohen, windgepeitschten Gipfel über den Schrein der schlafenden Flamme. Unvorbereitete Wanderer und Glücksjäger finden nur Stille und kahlen Stein. Doch wenn Ihr als wahrer Initiand mit der heiligen Fackel eintrefft, offenbart Braldir die elementare Macht, die im Kohlenbecken des Schreins schlummert und darauf wartet, neu entfacht zu werden."}},faq={{q="Was ist die Quest Call of Fire?",a="Call of Fire ist eine Prüfung für einen Initianden, der ein Feuertotem erlangen möchte. Ihr reist in die zerklüfteten Höhen von Loch Modan und bringt Braldir Ashmantle die Fackel der schlafenden Flamme auf einen heiligen Berggipfel.",al={"was ist call of fire","schamane feuerquest loch modan","feuertotem quest"}},{q="Wer ist Braldir Ashmantle?",a="Braldir Ashmantle bewacht den Schrein der schlafenden Flamme hoch in den zerklüfteten Höhen von Loch Modan. Er weist gewöhnliche Reisende und Schatzsucher ab und heißt jene willkommen, die die Fackel der schlafenden Flamme tragen.",al={"wer ist braldir ashmantle","schreinhüter loch modan"}},{q="Wo befindet sich der Schrein der schlafenden Flamme?",a="Der Schrein der schlafenden Flamme liegt hoch in den zerklüfteten Höhen von Loch Modan. Jenseits des Tals der Könige windet sich ein verborgener Pfad dorthin.",al={"wo ist der schrein der schlafenden flamme","schlafende flamme standort"}},{q="Welchen Zweck hat die Fackel der schlafenden Flamme?",a="Initianden tragen die Fackel der schlafenden Flamme, um ihre ernste Absicht und ihre Bereitschaft zu zeigen, mit dem elementaren Feuer Zwiesprache zu halten. Braldir Ashmantle verlangt, dass Ihr sie vorzeigt, bevor er Euch eine Audienz gewährt.",al={"was ist die fackel der schlafenden flamme","fackel der schlafenden flamme zweck"}},{q="Warum muss der Bittsteller nach Loch Modan reisen?",a="Ihr reist nach Loch Modan, weil sich der abgelegene Gipfel der Elemente mit dem Schrein der schlafenden Flamme jenseits des Tals der Könige erhebt, fernab gewöhnlicher Reisender.",al={"warum nach loch modan reisen","warum ist der feuerschrein in loch modan"}},{q="Wie wird das Feuertotem durch diese Prüfung erlangt?",a="Nachdem Ihr Braldir Ashmantle erreicht und mit der Fackel Eure Absicht bewiesen habt, entzündet Ihr das Kohlenbecken des Schreins. Ihr kehrt mit der brennenden Flamme zurück und erlangt das Feuertotem.",al={"was geschieht nach dem finden von braldir","wie das feuertotem erlangen"}}},fp="12,157,35.270.0,31.328.0,31.202.0,25.204.0,49.124.0,54.195.0,45.165.0,48.166.0"}
P.entries["quest:94466"] = {n="Call of Fire",s="In Loch Modan suchen Initianden die Ewige Flamme und das Feuertotem, das sie gewährt. Braldir Ashmantle führt sie durch eine Prüfung, die Reagenzien von Kobolden und Troggs verlangt. Sie bereiten eine Feuersapta zu und lernen, dass Flammen sowohl schmieden und Leben schenken als auch zerstören können.",h="In Loch Modan suchen Initianden die Ewige Flamme und das Feuertotem, das sie gewährt.",kw={"braldir ashmantle","call of fire","ewige flamme","feuersapta","feuerteer","feuertotem","loch modan","stonesplinter seer","tunnel rat geomancer"},ang={["class:Shaman"]="Um mit Feuergeistern zu kommunizieren und die Ewige Flamme zu suchen, schmiedet Ihr mit einer Feuersapta eine elementare Bindung. Dieser Pfad führt zum Feuertotem.",["faction:Alliance"]="In den Landen der Allianz stellt Ihr Euch den Bedrohungen durch einheimische Troggs und Kobolde, während Ihr in Loch Modan an schamanischen Riten teilnehmt.",["race:Dwarf"]="Als Zwerg findet Ihr Braldir Ashmantle in Loch Modan, wo er Initianden führt. Er betrachtet Feuer als den Atem der Schmiede und der Schöpfung, nicht als bloße Zerstörung."},sec={{t="Der Pfad zur Flamme",b="In Loch Modan führt Braldir Ashmantle Initianden, die nach der Macht der Flamme suchen. Bevor sie mit Feuergeistern kommunizieren können, müssen sie ihren sterblichen Geist mit einem heiligen Trank einstimmen, einer sogenannten Feuersapta. Ohne sie würde die Ewige Flamme sie verzehren, statt sie zu erleuchten. Braldir fordert jeden Bittsteller auf, zwei Reagenzien von feindseligen Talbewohnern zu sammeln und seine Entschlossenheit zu beweisen."},{t="Reagenzien aus Erde und Funken",b="Eine Feuersapta benötigt Substanzen, die reich an elementarer Macht sind. Im Norden sammeln Tunnel Rat Geomancers in ihren Bauen klebrigen Feuerteer, um ihre unterirdische Magie zu speisen. Im Süden tragen Stonesplinter Seers Reagent Pouches voller primitiver Elementartalismane durch die Hügel. Diese Gegenstände zu erlangen bedeutet, sich zwei der hartnäckigsten Plagen von Loch Modan zu stellen und das Nötige zu gewinnen, um die Seele eines Initianden an die Flamme zu binden."},{t="Die Läuterung der Weisheit",b="Sobald die Reagenzien gesammelt sind, lehrt Braldir Ashmantle neben der Macht der Zerstörung auch Geduld. Für ihn bedeutet Feuer mehr als Zorn und Asche. Es ist Leben, das Handwerk der Schmiede und der Atem der Schöpfung. Meisterschaft verlangt Gleichgewicht: Schatten verleiht dem Licht Bedeutung, und die Flamme bewahrt den Stein davor, nur eine kalte Erinnerung zu sein. Um das Feuer zu meistern, muss ein Initiand lernen, wann er verbinden statt verbrennen sollte."}},faq={{q="Welchen Zweck hat Call of Fire?",a="Angehende Schamanen stellen sich Call of Fire, um mit der Ewigen Flamme zu kommunizieren. Zunächst bereiten sie eine Feuersapta zu, um ihren sterblichen Geist an das Element zu binden.",al={"was ist call of fire","was ist diese quest","zweck von call of fire"}},{q="Wer ist Braldir Ashmantle?",a="Braldir Ashmantle führt Initianden in Loch Modan. Er lehrt das Gleichgewicht des Feuers und bereitet eine Feuersapta zu, sobald sie die nötigen Reagenzien gesammelt haben.",al={"wer vergibt call of fire","wer ist braldir ashmantle","braldir ashmantle aufenthaltsort"}},{q="Was ist eine Feuersapta?",a="Eine Feuersapta ist eine Zubereitung aus Reagenzien, die an die Flamme gebunden sind. Sie stimmt den Geist eines Schamanen auf das Feuer ein und bindet ihn daran, wodurch die Kommunikation mit der Ewigen Flamme möglich wird.",al={"was ist eine feuersapta","was bewirkt eine sapta","warum ist eine sapta nötig"}},{q="Wo findet man den Feuerteer?",a="Tunnel Rat Geomancers tragen Feuerteer in ihren Höhlen im Norden von Loch Modan bei sich. Sie verwenden ihn für ihre primitiven Feuerkünste.",al={"wo gibt es feuerteer","feuerteer fundort","koboldhöhlen feuerteer"}},{q="Wo findet man den Reagent Pouch der Stonesplinter?",a="Stonesplinter Seers tragen Reagent Pouches in den südlichen Hügeln von Loch Modan bei sich. Die Trogg-Mystiker bewahren darin Reagenzien auf, die mit elementarer Magie verbunden sind.",al={"wo gibt es reagent pouch","stonesplinter seer beutel","stonesplinter beutel fundort"}},{q="Wie betrachtet Braldir Ashmantle das Element Feuer?",a="Braldir lehrt, dass Feuer mehr als Zerstörung ist: Es ist Schmiede, Leben und der Atem der Schöpfung. Im Gleichgewicht mit anderen Kräften läutert es kalten Stein und verleiht dem Dasein Wärme und Sinn.",al={"braldirs sicht auf feuer","bedeutung des feuers loch modan","zwergische feuerphilosophie"}}},fp="12,263,21.387.0,31.422.0,23.387.0,36.157.0,25.144.0,21.164.0,28.119.0,47.147.0,52.193.0"}
P.entries["quest:94467"] = {n="Call of Fire",s="Am Schrein trinkt ein Initiant Feuersapta, um sich der Prüfung namens Call of Fire zu stellen. Der Ritus verlangt, einen Geist zu bezwingen und seine Glut dem heiligen Kohlenbecken darzubringen.",h="Am Schrein trinkt ein Initiant Feuersapta, um sich der Prüfung namens Call of Fire zu stellen.",kw={"kohlenbecken","call of fire","feuersapta","glut","minor manifestation of fire","schamanenprüfung","shrine of eternal flame"},ang={["class:Shaman"]="Als Schamane unterzieht Ihr Euch einer grundlegenden Prüfung in Gemeinschaft mit dem Feuer. Heilige Sapta lässt Euch die Flammengeister wahrnehmen und Euch ihnen stellen."},sec={{t="Der Ritus der Flamme",b="Ein Initiant erhält zubereitete Feuersapta, geleitet von elementarer Kunde. Der Trank weckt seine Sinne für die unsichtbare Welt. Nachdem er am Schrein getrunken hat, steigt er zum Gipfel auf, wo der Blick der Sterblichen den Urkräften weicht. Dort wartet eine ruhende Manifestation des Feuers darauf, von ihm herausgefordert zu werden."},{t="Der Manifestation gegenübertreten",b="Die Minor Manifestation of Fire prüft die Entschlossenheit und Ausdauer eines Initianten. Sie greift erst an, wenn sie herausgefordert wird, und wird dann mit jedem Augenblick wilder. Wird sie bezwungen, hinterlässt sie glühende Glut. Bringt diese zum Kohlenbecken oben auf dem Shrine of Eternal Flame, um die Fackel zu entzünden und die dauerhafte Gunst des Geistes zu erlangen."}},faq={{q="Was ist Call of Fire?",a="Call of Fire ist ein heiliger Ritus, bei dem ein Initiant zubereitete Feuersapta trinkt, einem Flammengeist gegenübertritt und dessen Glutstück einem Kohlenbecken darbringt, um die Gunst des Feuers zu erlangen.",al={"was ist call of fire","call of fire quest","feuertotem prüfung"}},{q="Welchen Zweck hat die Feuersapta?",a="Feuersapta ist ein zubereiteter Trank, der den geistigen Blick eines Initianten öffnet und den Elementargeist offenbart, der auf dem Berggipfel wartet.",al={"feuersapta zweck","warum sapta trinken","was bewirkt sapta"}},{q="Welcher Geist erscheint während der Prüfung?",a="Eine Minor Manifestation of Fire erwartet den Initianten auf dem Gipfel. Sie kämpft erst, wenn sie geschlagen wird.",al={"welchen geist bekämpfen","call of fire gegner","manifestation des feuers"}},{q="Warum muss der Feuergeist schnell besiegt werden?",a="Der Elementargeist wird im Verlauf des Kampfes immer wilder und heißer. Ein schneller, entschlossener Schlag kann ihn bezwingen, bevor seine Flammen den Initianten überwältigen.",al={"warum schnell zuschlagen","call of fire kampf","feuergeist zeitlimit"}},{q="Was geschieht mit der glühenden Glut?",a="Nachdem die Minor Manifestation of Fire besiegt wurde, wird ihre glühende Glut zum Kohlenbecken oben auf dem Shrine of Eternal Flame getragen, um die Ritualfackel zu entzünden.",al={"wohin mit der glut","call of fire kohlenbecken","shrine of eternal flame kohlenbecken"}},{q="Was bedeutet es, die Gunst des Feuers zu erlangen?",a="Das Entzünden der Fackel gewährt die unmittelbare Gunst der Feuerelementare und Gemeinschaft mit ihnen. Der Ritus knüpft ein Band zu den Flammen.",al={"was ist die belohnung","was gewährt das ritual","gunst des feuers"}}},fp="12,165,17.289.0,24.311.0,25.159.0,38.135.0,37.96.0,45.150.0,37.157.0,40.124.0"}
P.entries["quest:94468"] = {n="Call of Fire",s="Über Loch Modan entzündet ein Initiant die Flamme, die Dun Morogh erreichen muss. Bruegs Kindleborn erwartet ihre Rückkehr und beurteilt die Beherrschung der Elemente durch den Reisenden.",h="Über Loch Modan entzündet ein Initiant die Flamme, die Dun Morogh erreichen muss.",kw={"bruegs kindleborn","call of fire","dun morogh","feuertotem","flammengeboren","loch modan","schamane","fackel der ewigen flamme"},ang={["class:Shaman"]="Als Schamane besteht Ihr die Prüfung des Feuers in Khaz Modan und verdient Euch das Feuertotem. Es lässt Euch Flammen kanalisieren und Zwiesprache mit den Feuergeistern halten.",["faction:Alliance"]="In den Gebieten der Allianz in Khaz Modan schlagen spirituelle Berufungen Wurzeln. Bruegs Kindleborn leitet neue Initianten an, während sie die elementaren Künste erlernen.",["race:Dwarf"]="Als Zwerg tragt Ihr die Flamme von den Höhen über Loch Modan nach Dun Morogh. Die Reise verbindet Eure spirituelle Suche mit den elementaren Kräften Eurer Gebirgsheimat."},sec={{t="Die Flamme über dem Loch",b="Ein Initiant entzündet die Fackel der ewigen Flamme auf einem Gebirgskamm über Loch Modan. Die Flamme markiert den Beginn einer tieferen Bindung an die Elemente. Von dort trägt der Initiant sie die Pfade hinab und in die verschneiten Täler von Dun Morogh."},{t="Die Belohnung des Flammengeborenen",b="In Dun Morogh erwartet Bruegs Kindleborn den Reisenden. Er ist ein elementarer Mentor, der beurteilt, ob das innere Feuer des Reisenden Wurzeln geschlagen hat. Die lodernde Fackel beweist den Willen des Initianten und seine Ehrfurcht vor dem Feuer. Bruegs verleiht daraufhin das Feuertotem und nimmt den Flammengeborenen in eine Reihe jener auf, die ihrem Volk elementare Führung bieten."}},faq={{q="Was ist Call of Fire?",a="Call of Fire ist eine spirituelle Prüfung für Schamanen in Khaz Modan. Der Initiant entzündet die Fackel der ewigen Flamme an einer Feuerschale mit Blick auf Loch Modan und trägt sie dann durch die Berge zu Bruegs Kindleborn in Dun Morogh.",al={"was ist call of fire","call of fire quest","was geschieht bei call of fire"}},{q="Wer ist Bruegs Kindleborn?",a="Bruegs Kindleborn ist ein elementarer Mentor, der in Dun Morogh lebt. Er wacht über die Riten der Flamme und verleiht Initianten, die den Weg bewältigen, ihr Feuertotem.",al={"wer ist bruegs kindleborn","wo ist bruegs kindleborn","bruegs kindleborn standort"}},{q="Was ist die Fackel der ewigen Flamme?",a="Die Fackel der ewigen Flamme ist eine zeremonielle Fackel, die an einer Feuerschale mit Blick auf Loch Modan entzündet wird. Sie steht für die Bindung eines Initianten an das elementare Feuer und muss sicher zu Bruegs Kindleborn in Dun Morogh getragen werden.",al={"was ist die fackel der ewigen flamme","fackel der ewigen flamme","wo gibt es die fackel"}},{q="Was erhaltet Ihr nach Abschluss dieser Prüfung?",a="Wenn Ihr die Fackel der ewigen Flamme sicher zu Bruegs Kindleborn bringt, erkennt er Euren lodernden Geist an und verleiht Euch Euer Feuertotem. Das Totem kennzeichnet Euch als flammengeboren.",al={"welche belohnung für call of fire","gibt es ein feuertotem","call of fire totem"}},{q="Wo findet diese Reise statt?",a="Die Reise beginnt an einem Aussichtspunkt über Loch Modan, wo die Fackel entzündet wird. Der Gebirgspfad führt nach Dun Morogh, wo Bruegs Kindleborn wartet.",al={"wo findet call of fire statt","call of fire weg","wohin mit der fackel"}},{q="Warum erwähnt Bruegs Madoran?",a="Bruegs erwähnt Madoran in einem Schwur und bezieht sich damit auf Madoran Bronzebeard. Er war der verehrte Zwergenanführer, der den Bronzebeard-Clan während des War of the Three Hammers führte.",al={"warum bei madorans bart","madoran bedeutung","wer ist der von bruegs erwähnte madoran"}}},fp="12,162,23.241.0,22.320.0,25.218.0,25.156.0,35.200.0,47.173.0,35.148.0,32.169.0"}
P.entries["quest:94480"] = {n="A Gift From Our Enemies",s="Ihr bringt gestohlenes Futter zu Gorg nach Rog'mar, damit seine Verbündeten versorgt werden. Nahe Gnolle und das vorrückende Twilight bedrohen die Siedlung.",h="Ihr bringt gestohlenes Futter zu Gorg nach Rog'mar, damit seine Verbündeten versorgt werden.",kw={"verbündete","farmstead","gnolle","gorg","kräftiger eintopf","rog'mar","gestohlenes futter","twilight"},sec={{t="Nahrung für Rog'mar",b="Gorg wartet in Rog'mar auf das gestohlene Futter, das Ihr gesammelt habt. Die Menschen sind nicht die einzige Gefahr in der Nähe: Gnolle knurren von den Hügeln herab, und Twilight rückt näher. Wenn Rog'mars Verbündete satt werden, kann das ihre Kräfte bewahren."},{t="Ein kräftiger Eintopf",b="Das Futter riecht kräftig und erdig, mit etwas Unangenehmem darunter. Gorg erkennt, dass Ihr es vom farmstead genommen habt, und sagt, es werde einen kräftigen Eintopf für die Verbündeten ergeben."}},faq={{q="Warum will Gorg das gestohlene Futter?",a="Gorg wird aus dem gestohlenen Futter einen kräftigen Eintopf für Rog'mars Verbündete machen.",al={"warum futter","gorg futter","wozu gestohlenes futter"}},{q="Welche Gefahren lauern nahe Rog'mar?",a="Die Menschen sind eine Gefahr, während Gnolle von den Hügeln in der Nähe herabknurren und Twilight näher rückt.",al={"gnolle in der nähe","gefahr durch twilight","was ist nahe rog'mar"}},{q="Wer ist Gorg?",a="Gorg nimmt in Rog'mar das gestohlene Futter entgegen und sagt, dass es einen kräftigen Eintopf ergeben kann.",al={"wer ist gorg"}},{q="Wohin bringe ich das gestohlene Futter?",a="Bringt das gestohlene Futter zu Gorg nach Rog'mar.",al={"ort des futters","wohin futter bringen","gorgs ort"}}},fp="23,134,16.224.0,13.177.1,35.73.0,30.92.0,12.91.0,32.40.0"}
P.entries["quest:94481"] = {n="A Serving of Strength",s="Ein Ausbilder bittet Euch, Rog’mar-Rekruten auf dem Übungsgelände zu versorgen. Der Eintopf hält sie satt, während die Versorgungslinien immer schwerer zu verteidigen sind.",h="Ein Ausbilder bittet Euch, Rog’mar-Rekruten auf dem Übungsgelände zu versorgen.",kw={"eine portion stärke","rog’mar-rekruten","eintopf","versorgungslinien","rekruten","übungsgelände","krieger"},sec={{t="Essen für Rekruten",b="Die Rekruten auf dem Übungsgelände brauchen Essen, und ihr Ausbilder schickt Euch mit kräftigem Eintopf los. Ihr sollt die Rog’mar-Rekruten im Westen versorgen. Ihre Beschwerden müssen warten; die Versorgungslinien zu verteidigen, ist schwierig geworden, und die Krieger sind dankbar für das Essen, das Ihr bringt."}},faq={{q="Wer braucht den Eintopf?",a="Die Rog’mar-Rekruten auf dem Übungsgelände brauchen den Eintopf.",al={"wer hat hunger","wer wird versorgt","essen für rekruten"}},{q="Wohin soll ich den Eintopf bringen?",a="Die Rog’mar-Rekruten sind auf dem Übungsgelände im Westen.",al={"wo rekruten versorgen","aufenthaltsort der rekruten","wohin mit dem eintopf"}},{q="Warum bekommen sie Eintopf?",a="Der Eintopf hält die Rekruten satt, während die Verteidigung der Versorgungslinien schwieriger geworden ist.",al={"warum eintopf","wofür ist das essen","warum rekruten versorgen"}},{q="Was hält der Ausbilder von den Beschwerden der Rekruten?",a="Der Ausbilder sagt, die Rekruten können weitere Beschwerden direkt an ihn richten.",al={"beschwerden der rekruten","warum beschweren sie sich","ausbilder verärgert"}},{q="Ist der Ausbilder dankbar für das Essen?",a="Ja. Der Ausbilder und die Krieger sind trotz allem, was die Krieger sagen, dankbar für das Essen.",al={"weiß der ausbilder das zu schätzen","dank für den eintopf","krieger dankbar"}}},fp="21,149,17.274.0,19.57.0,25.63.0,28.86.0,56.80.0,37.91.0"}
P.entries["quest:94483"] = {n="Show Them How It's Done",s="Ein Kommandant schickt Euch südlich des Flusses, um die Trainingslager von Farholde anzugreifen. Der Angriff soll die Menschen nahe ihrer Festung halten und anderen Angelegenheiten Zeit verschaffen.",h="Ein Kommandant schickt Euch südlich des Flusses, um die Trainingslager von Farholde anzugreifen.",kw={"farholde","menschen","festung","priester","fluss","späher","trainingslager"},sec={{t="Am Fluss",b="Der Kommandant weist Euch zu den Lagern von Farholde südlich des Flusses, wo Späher von menschlichen Truppen berichtet haben. Ihr sollt Farholde-Priester und Farholde-Späher töten. Wenn Ihr die Menschen von ihrer Festung fernhaltet, gewinnt der Kommandant Zeit, sich um andere Angelegenheiten zu kümmern."}},faq={{q="Wer beauftragt mich, die Lager anzugreifen?",a="Ein Kommandant, der Berichte von Spähern über Trainingslager südlich des Flusses erhalten hat, schickt Euch gegen die Truppen von Farholde.",al={"wer gab diesen auftrag","beauftragung durch kommandanten"}},{q="Wo befinden sich die Lager von Farholde?",a="Die Trainingslager liegen südlich des Flusses.",al={"wo sind die lager","ort von farholde"}},{q="Wen soll ich angreifen?",a="Der Kommandant nennt Farholde-Priester und Farholde-Späher als Ziele.",al={"wen töten","ziele"}},{q="Warum greifen wir die Menschen an?",a="Die Menschen nahe ihrer Festung aufzuhalten, soll dem Kommandanten Zeit für seine anderen Angelegenheiten verschaffen.",al={"warum gegen menschen kämpfen","worum geht es"}},{q="Was geschieht nach dem Angriff?",a="Der Kommandant sagt, der Einsatz sei schnell verlaufen, und will anderswo weitermachen.",al={"wie geht es weiter","nach den lagern"}}},fp="23,160,12.264.0,37.119.0,29.42.0,28.72.0,22.96.0,30.74.0"}
P.entries["quest:94484"] = {n="Unnerving Silence",s="Im nordöstlichen Schattenwindwald ist eine Druidenenklave verstummt. Seit Ban'aethall in Trümmern liegt, haben sich Unruhen im Gebiet ausgebreitet.",h="Im nordöstlichen Schattenwindwald ist eine Druidenenklave verstummt.",kw={"ban'aethall","druide","druidenkonklave","elegael thornpaw","schattenwindwald","unnerving silence"},ang={["class:Druid"]="Als Druide sorgt Ihr Euch womöglich um Euresgleichen und das Gleichgewicht der Wildnis, wenn eine abgeschiedene Enklave im Schattenwindwald verstummt. Elegael Thornpaw zu finden, könnte offenbaren, was ihre Zwiesprache mit der Natur gestört hat."},sec={{t="Stille im Blätterdach",b="Nachdem Ban'aethall in Trümmer gefallen war, regten sich Unruhen im Gebiet. Die regelmäßigen Nachrichten des Druidenkonklaves in einer Höhle im nordöstlichen Schattenwindwald bleiben nun aus. Seine Verbündeten haben nichts mehr gehört, und mit der Unruhe im Wald wächst auch ihre Sorge."},{t="Suche nach der Enklave",b="Ihr werdet in den nordöstlichen Schattenwindwald geschickt, um Elegael Thornpaw zu finden, eine bedeutende Druidin der Enklave. Hat sich das Konklave in eine tiefere Zwiesprache mit der Natur zurückgezogen, oder haben die Gefahren, die Ban'aethall verwüsteten, die Höhle erreicht? Niemand kennt das Schicksal der Enklave."}},faq={{q="Worum geht es in der Quest Unnerving Silence?",a="Ihr sollt herausfinden, warum die Nachrichten eines Druidenkonklaves im Schattenwindwald ausbleiben. Durchsucht die Höhle im Nordosten des Waldes und findet heraus, was dem abgeschiedenen Orden widerfahren ist.",al={"unnerving silence quest","was ist unnerving silence"}},{q="Wo ist Elegael Thornpaw zu finden?",a="Elegael Thornpaw befindet sich in einer Höhle im nordöstlichen Schattenwindwald. Sie ist die Ansprechpartnerin des dortigen abgeschiedenen Druidenkonklaves.",al={"wo ist elegael thornpaw","elegael thornpaw fundort","thornpaw finden"}},{q="Wer ist Elegael Thornpaw?",a="Elegael Thornpaw gehört dem Druidenkonklave in einer Höhle im nordöstlichen Schattenwindwald an. Ihr Schweigen und das Ausbleiben der vorgesehenen Nachrichten haben Sorge um die Sicherheit der Enklave geweckt.",al={"wer ist elegael thornpaw","thornpaw hintergrundgeschichte"}},{q="Was ist der Schattenwindwald?",a="Der Schattenwindwald ist ein bewaldetes Gebiet mit einem verborgenen Druidenkonklave in einer Höhle im Nordosten. Seit Ban'aethall fiel und sich Unruhen im Gebiet ausbreiteten, ist der Kontakt zu den Bewohnern des Waldes unsicher geworden.",al={"was ist der schattenwindwald","schattenwindwald konklave"}},{q="Was ist Ban'aethall?",a="Ban'aethall war ein Dorf tief im Schattenwindwald, das nun in Trümmern liegt. Seine Zerstörung und die Unruhen im gesamten Gebiet haben Ängste um nahe gelegene Lager geweckt, darunter das Shadowgale-Konklave.",al={"was geschah mit banaethall","banaethall ruinen hintergrundgeschichte","ban'aethall gefallen"}},{q="Warum ist das Druidenkonklave verstummt?",a="Die vorgesehenen Nachrichten und Berichte der Druiden aus dem Schattenwindwald bleiben ohne Erklärung aus. Da Ban'aethall in Trümmern liegt und die Spannungen zunehmen, fürchten ihre Verbündeten, dass Unheil oder feindliche Mächte die Enklave heimgesucht haben könnten.",al={"warum senden die druiden keine nachrichten mehr","warum schweigen die druiden"}}},fp="17,142,21.259.0,19.271.0,42.188.0,36.131.0,24.183.0,26.223.0,20.193.0,39.222.0"}
P.entries["quest:94485"] = {n="Tears of the Lady",s="Im Schattenwindwald kann das Moos Lady's Tear Elegaels verwundete Gefährten am Leben halten. Sie sitzen in Nightclaw Den fest, und Elegael braucht Heilmittel von nahe gelegenen Bäumen.",h="Im Schattenwindwald kann das Moos Lady's Tear Elegaels verwundete Gefährten am Leben halten.",kw={"elegael","lady's tear","moos","nightclaw den","wundumschlag","schattenwindwald","tears of the lady"},ang={["class:Priest"]="Als Priester kanalisiert Ihr das Licht, um tödliche Verletzungen zu heilen. Natürliche Wundumschläge wie Lady's Tear können Wunden versorgen, wenn magische Hilfe kaum ausreicht.",["profession:Herbalism"]="Als Kräuterkundiger kennt Ihr Lady's Tear wegen seines klebrigen, antiseptischen Sekrets. Es kann offenes Fleisch verschließen und in Notfällen in der Wildnis helfen, Infektionen zu verhindern."},sec={{t="Verzweifelte Heilversuche im Schattenwindwald",b="Elegael braucht Eure Hilfe im Schattenwindwald. Verwundete Gefährten sitzen in Nightclaw Den fest, schwer verletzt und auf Hilfe wartend. Herkömmliche Vorräte sind knapp, also sammelt Ihr Heilmittel in den umliegenden Wäldern. Ihre Wunden dulden keinen Aufschub."},{t="Das heilende Moos",b="Elegael braucht Lady's Tear, ein spindeldürres Moos, das überall im Schattenwindwald am Fuß von Bäumen haftet. Sein Sekret ist zähflüssig und klebrig und hat natürliche antiseptische Eigenschaften. Es verschließt klaffende Wunden und schützt Verletzungen davor, sich in der feuchten Wildnis zu verschlimmern. Mit genügend Moos kann Elegael Verbände vorbereiten, um die Gefallenen zu stabilisieren."}},faq={{q="Worum geht es bei der Quest Tears of the Lady?",a="Elegael braucht Hilfe bei der Behandlung verwundeter Gefährten, die in Nightclaw Den festsitzen. Sammelt das Moos Lady's Tear im Schattenwindwald, damit Elegael einen Wundumschlag zubereiten kann, der sie am Leben hält.",al={"was ist tears of the lady","questinfos zu tears of the lady"}},{q="Was ist Lady's Tear?",a="Lady's Tear ist ein spindeldürres Moos, das überall im Schattenwindwald am Fuß von Bäumen wächst. Sein Sekret ist zähflüssig und klebrig und hat natürliche antiseptische Eigenschaften, die offene Wunden verschließen können.",al={"was ist ladys tear","ladys tear moos","was ist lady's tear moos"}},{q="Wer ist Elegael?",a="Elegael organisiert die medizinische Hilfe im Schattenwindwald. Verwundete Gefährten sitzen in Nightclaw Den fest, und Elegael braucht Vorräte, um sie zu behandeln.",al={"wer ist elegael","questgeber tears of the lady"}},{q="Was ist Nightclaw Den?",a="In Nightclaw Den nahe dem Schattenwindwald sitzen mehrere von Elegaels verletzten Verbündeten fest. Ihr Zustand ist bedenklich, während Elegael nach heilenden Zutaten sucht.",al={"was ist nightclaw den","wo ist nightclaw den"}},{q="Warum braucht Elegael das Moos Lady's Tear?",a="Elegael braucht das antiseptische Sekret von Lady's Tear, um einen Wundumschlag zuzubereiten. Die zähflüssige, klebrige Substanz verschließt klaffende Wunden und schützt Verletzungen davor, sich zu verschlimmern.",al={"warum wird ladys tear benötigt","was bewirkt das moos"}},{q="Wo findet man das Moos Lady's Tear?",a="Lady's Tear haftet überall im Schattenwindwald am Fuß von Bäumen. Elegael hat gesammelt, was unmittelbar erreichbar war, und weiteres Moos findet sich in den umliegenden Wäldern.",al={"wo wächst ladys tear","ladys tear finden"}}},fp="17,157,32.238.0,16.312.0,42.164.0,20.178.0,15.135.0,26.156.0,39.165.0,32.153.0"}
P.entries["quest:94486"] = {n="Feathers for Binding",s="Im Schattenwindwald brauchen Heiler Federn junger Shrieklinge, um einen heilenden Umschlag zu binden. Die sonst friedfertigen Vögel greifen nun Reisende an, was das Sammeln ihres Gefieders gefährlich macht.",h="Im Schattenwindwald brauchen Heiler Federn junger Shrieklinge, um einen heilenden Umschlag zu binden.",kw={"antiseptischer saft","feathers for binding","umschlag","schattenwindwald","shadowgale shriekling","shriekling","shrieklinge"},ang={["class:Druid"]="Als Druide teilt Ihr vielleicht den Kummer der Pfleger darüber, junge Waldtiere zu töten, selbst wenn zunehmende Aggression und dringender medizinischer Bedarf kaum Alternativen lassen.",["profession:Herbalism"]="Kräuterkundige und Naturheiler wissen das Zusammenspiel von Moos, antiseptischem Baumsaft und isolierenden Federn in einem Feldverband oder heilenden Umschlag zu schätzen."},sec={{t="Heilmittel des Waldes",b="Feldheiler im Schattenwindwald behandeln schwere Verletzungen mit Moos und antiseptischem Baumsaft. Raues Wetter kann den Saft austrocknen oder ihm seine Wirkkraft nehmen. Deshalb binden sie den Umschlag mit Federn junger Shadowgale Shrieklinge, die die Wunde schützen und das Heilmittel an Ort und Stelle halten."},{t="Ungewöhnliche Feindseligkeit",b="Das Sammeln der weichen Federn ist gefährlich geworden. Junge Shadowgale Shrieklinge sind gewöhnlich friedfertige Waldbewohner, doch in letzter Zeit sind sie unerklärlich aggressiv geworden. Ihre kräftigen Krallen können tödliche Wunden verursachen. Nun greifen die Jungvögel Vorübergehende an."},{t="Eine bedauerliche Notwendigkeit",b="Die örtlichen Pfleger bedauern, dass sie junge Tiere töten müssen. Doch Notfälle bedrohen die Region, und die Shrieklinge werden immer gefährlicher. Ihre Zahl zu verringern liefert lebenswichtige Heilmaterialien und dämmt eine wachsende Bedrohung entlang der Waldpfade ein. Jede Feder wird mit Respekt behandelt, damit das Opfer der Tiere nicht vergebens ist."}},faq={{q="Warum werden Federn von Shadowgale Shrieklingen für den Umschlag benötigt?",a="Die Federn junger Shadowgale Shrieklinge isolieren den Umschlag. Über Moos und antiseptischen Saft gelegt, bewahren sie den Saft vor dem Austrocknen und schützen Wunden vor rauem Wetter.",al={"zweck der federn","warum shrieklingfedern","federn für den umschlag"}},{q="Wie gefährlich sind die jungen Shrieklinge?",a="Shadowgale Shrieklinge sind gewöhnlich friedfertig, doch in letzter Zeit sind sie ungewöhnlich feindselig geworden. Selbst die Jungtiere haben große, gefährliche Krallen, mit denen sie einem unachtsamen Reisenden den Bauch aufschlitzen können.",al={"gefahr durch shrieklinge","sind shrieklinge gefährlich","aggression der shrieklinge"}},{q="Warum müssen junge Shrieklinge statt ausgewachsener Tiere gejagt werden?",a="Die Pfleger bedauern es, junge Shrieklinge zu töten, doch deren plötzliche Aggression und weitere drängende Notfälle in der Wildnis machen dies zur schmerzlichen Notwendigkeit. Das Sammeln ihrer Federn hilft auch, den dringenden medizinischen Bedarf zu decken.",al={"warum junge shrieklinge töten","junge shrieklinge töten"}},{q="Wo sind die Shadowgale Shrieklinge zu finden?",a="Shadowgale Shrieklinge durchstreifen die Baumkronen und das Unterholz des Schattenwindwalds. Reisende müssen sich vorsichtig durch den Wald wagen, um sie zu finden.",al={"wo ist der schattenwindwald","fundort der shrieklinge","wo sind shrieklinge"}},{q="Welche anderen Zutaten werden zusammen mit diesen Federn verwendet?",a="Der Umschlag besteht aus heimischem Moos und antiseptischem Saft und wird mit Federn junger Shrieklinge gebunden und isoliert.",al={"zutaten des umschlags","was ist im umschlag"}},{q="Warum sind die Shrieklinge in letzter Zeit so feindselig geworden?",a="Niemand kennt die genaue Ursache für die plötzliche Feindseligkeit der Shrieklinge. Die normalerweise friedlichen Jungtiere sind aggressiv geworden und verschärfen die Krisen, denen sich die örtlichen Pfleger stellen müssen.",al={"warum sind shrieklinge wütend","ursache der aggression der shrieklinge"}}},fp="20,179,22.275.0,26.255.0,23.313.0,63.166.0,43.170.0,58.225.0,43.142.0,63.106.0,50.175.0"}
P.entries["quest:94487"] = {n="Unwanted and Unworthy",s="Auf Zephras treibt das Blutvergießen im Schattenwindwald Elegael dazu, Rache zu suchen und gestohlene Erbstücke für den Hohen Ältesten zu bergen.",h="Auf Zephras treibt das Blutvergießen im Schattenwindwald Elegael dazu, Rache zu suchen und gestohlene...",kw={"al'aketh","blutbefleckte erbstücke","elegael","footsoldiers","erbstücke","schattenwindwald","shen'dorei","stormchasers","zephras"},ang={["class:Druid"]="Auf Zephras vergossen die Al'Aketh-Kultisten bei einem unprovozierten Angriff das Blut örtlicher Druiden. Als Druide antwortet Ihr mit Rache und verteidigt das Gleichgewicht der Natur."},sec={{t="Hinterhalt im Schattenwindwald",b="Die Al'Aketh-Kultisten überfallen die örtlichen Druiden im Schattenwindwald aus dem Hinterhalt. Elegael hatte diese Eiferer für harmlose Träumer mit Wolken zwischen den Ohren gehalten. Nun befleckt Druidenblut den Waldboden, und Elegael fordert rasche Vergeltung an den verantwortlichen Footsoldiers und Stormchasers."},{t="Befleckte Erbstücke und verlorene Jugend",b="Elegael glaubt, dass der Verrat die Kultisten ihr Erbe gekostet hat. Sie verdienen weder länger den Namen Shen'dorei, noch verdienen ihre sterblichen Überreste die Winde ihrer Heimat. Viele waren jung, und ihr Fanatismus setzte ihrer vielversprechenden Zukunft ein jähes Ende.\n\nIhre blutbefleckten Erbstücke müssen zum Hohen Ältesten zurückkehren. Dort warten die heiligen Gegenstände auf eine weisere und würdigere Generation."}},faq={{q="Wer sind die Al'Aketh-Kultisten?",a="Die Al'Aketh-Kultisten sind von Stürmen besessene Kultisten auf Zephras. Elegael hielt sie einst für törichte Träumer mit Wolken zwischen den Ohren, doch sie wandten brutale Gewalt gegen die örtlichen Druiden an.",al={"wer sind die alaketh","alaketh-kult","wer sind die kultisten"}},{q="Wer ist Elegael?",a="Elegael ist eine Beschützerin oder Druidin der Shen'dorei auf Zephras. Die Al'Aketh-Kultisten überfielen Elegael aus dem Hinterhalt, und der Verrat und das vergossene Blut junger Menschen haben Elegael tief erschüttert. Elegael sucht Vergeltung und will gestohlene Erbstücke der Ahnen zurückholen.",al={"wer ist elegael","questgeberin elegael"}},{q="Was sind die blutbefleckten Erbstücke?",a="Die blutbefleckten Erbstücke gehörten jungen Shen'dorei, die in den Al'Aketh-Kult hineingezogen wurden. Elegael sammelt sie, um sie in die Sammlung des Hohen Ältesten zurückzubringen, wo sie an eine würdigere künftige Generation weitergegeben werden können.",al={"blutbefleckte erbstücke","warum erbstücke sammeln","was sind die erbstücke"}},{q="Was sind die Shen'dorei?",a="Die Shen'dorei sind das Volk, das Zephras bewohnt. Elegael glaubt, dass die Al'Aketh-Kultisten durch ihren gewaltsamen Verrat und die Entweihung der Harmonie der Insel ihr Recht auf diesen Namen verwirkt haben.",al={"shendorei bedeutung","wer sind die shendorei"}},{q="Wo liegt der Schattenwindwald?",a="Der Schattenwindwald ist eine bewaldete Region auf Zephras. Dort sind Al'Aketh Footsoldiers und Stormchasers tätig, und dort überfielen die Kultisten die Druiden aus dem Hinterhalt.",al={"schattenwindwald lage","wo liegt der schattenwindwald"}},{q="Warum überfielen die Al'Aketh-Kultisten die Druiden aus dem Hinterhalt?",a="Elegael kennt die genauen Beweggründe der Kultisten nicht. Einst als harmlose Eiferer abgetan, erhoben sie sich plötzlich mit grausamer Gewalt und zerschlugen das empfindliche Gleichgewicht auf der Insel.",al={"warum griffen die kultisten an","beweggründe des kults","warum druiden aus dem hinterhalt überfallen"}}},fp="21,124,27.286.0,32.360.0,30.198.0,15.244.0,32.200.0,24.189.0,27.146.0,48.174.0"}
P.entries["quest:94488"] = {n="The Ties That Bind",s="Elegael Thornpaw steht einem Verräter unter den Druiden des Schattenwindwalds gegenüber. Haalien verschwand vor Monaten, schloss sich dann den angreifenden Kultisten an und stieg zu ihrem Anführer auf. Nun befiehlt Elegael seine Hinrichtung.",h="Elegael Thornpaw steht einem Verräter unter den Druiden des Schattenwindwalds gegenüber.",kw={"zirkel des cenarius","kommandant haalien","kultisten","druide","elegael thornpaw","haalien","schattenwindwald","the ties that bind"},ang={["class:Druid"]="Als Druide wisst Ihr, dass dem Zirkel des Cenarius Gleichgewicht und Zusammenhalt heilig sind. Haaliens Verrat und das Blutvergießen unter seinen Mitdruiden sind schwere Vergehen gegen den Orden."},sec={{t="Verrat im Wald",b="Druiden stehen im Schattenwindwald einem grausamen Angriff von Kultisten gegenüber. Elegael Thornpaw entdeckt Haaliens Witterung über dem Gemetzel. Haalien war ein Druide des Zirkels, der vor Monaten verschwand, doch er kam nicht in der Wildnis um. Er schloss sich den eindringenden Kultisten an und befehligt nun ihren gewaltsamen Feldzug gegen seine einstigen Gefährten."},{t="Blut und Verwandtschaft",b="Haalien verriet mehr als seine Gelübde gegenüber dem Zirkel des Cenarius. Als Elegael den abgetrennten Kopf des gefallenen Kommandanten sieht, offenbart sie, dass Haalien ihr Cousin war. Der Zorn über seine Gräueltaten konnte die Bürde, ihren eigenen Verwandten niederzustrecken, nicht lindern, und so konnte sie diese nicht allein tragen. Sein Tod beendet das Leben eines Abtrünnigen, dessen Bosheit zahlreiche Unschuldige das Leben kostete."}},faq={{q="Wer bietet die Quest The Ties That Bind an?",a="Elegael Thornpaw ist eine Druidin, die im Schattenwindwald stationiert ist. Während die Kultisten angreifen, schickt sie Euch auf die Jagd nach Kommandant Haalien, nachdem sie seine Beteiligung am Blutvergießen entdeckt hat.",al={"wer vergibt ties that bind","questgeber schattenwindwald","wer ist elegael thornpaw"}},{q="Wer ist Kommandant Haalien?",a="Kommandant Haalien war ein Druide des Zirkels des Cenarius, der Monate vor den Angriffen der Kultisten verschwand. Er schloss sich den feindlichen Kultisten aus freien Stücken an und stieg zum Befehlshaber ihrer Streitkräfte gegen die Seinen auf.",al={"wer ist haalien","kommandant haalien geschichte","haalien hintergrund"}},{q="Warum will Elegael den Tod von Kommandant Haalien?",a="Haalien verließ seinen druidischen Zirkel, um Kultisten zu befehligen, die Unschuldige abschlachteten und das Blut seiner Brüder vergossen. Elegael befiehlt seine Hinrichtung wegen seiner Verbrechen und der Gefahr, die er für den Wald darstellt.",al={"warum haalien töten","haalien verbrechen","was hat haalien getan"}},{q="Welche Verbindung besteht zwischen Elegael Thornpaw und Haalien?",a="Kommandant Haalien ist Elegael Thornpaws Cousin. Voller Zorn über seine Verbrechen gesteht sie, dass es eine bittere Bürde gewesen wäre, ihren eigenen Verwandten zu töten, und bittet Euch deshalb um Hilfe.",al={"elegael haalien verwandt","woher kennen sich elegael und haalien"}},{q="Warum sind Kultisten im Schattenwindwald?",a="Selbst die örtlichen Druiden wissen nicht genau, warum die Kultisten in den Schattenwindwald gekommen sind. Ehemalige Zirkelmitglieder wie Haalien führen sie an und lenken Gewalt und Blutvergießen gegen die Verteidiger des Waldes.",al={"schattenwindwald kultisten","warum sind kultisten im schattenwindwald"}},{q="Wo spielt diese Quest?",a="Die Ereignisse spielen sich im Schattenwindwald ab, wo Elegael Thornpaw den Angriff der Kultisten untersucht und sich dem Verrat ihres Cousins stellt.",al={"wo spielt ties that bind","schattenwindwald lage"}}},fp="18,192,22.310.0,17.349.1,40.171.0,25.191.0,45.206.0,60.166.0,50.198.0,33.133.0"}
P.entries["quest:94489"] = {n="The Wounds of Betrayal",s="Im Schattenwindwald versorgt Elegael die Shen'dorei-Druiden, die bei einem schrecklichen Angriff verwundet wurden. Umschläge für Nightfang Den, nördlich jenseits der Lichtung, liegen bereit, während ihr Gefährte Jorel Windsinger vermisst wird.",h="Im Schattenwindwald versorgt Elegael die Shen'dorei-Druiden, die bei einem schrecklichen Angriff verwundet...",kw={"al'aketh","druide","elegael","jorel windsinger","nightfang den","schattenwindwald","shen'dorei","the wounds of betrayal"},ang={["class:Druid"]="Als Druide wisst Ihr, wie schwer es wiegt, wenn andere Hüter der Wildnis Verrat und schwere Verletzungen erleiden. Die Shen'dorei-Druiden sind nur wenige.",["race:NightElf"]="Als Nachtelf verehrt Ihr die druidischen Traditionen. Das Leid verwandter Druiden im Schattenwindwald und ihr Kampf gegen Verrat mögen schwer auf Euch lasten."},sec={{t="Hilfe für die Shen'dorei",b="Elegael versorgt die Shen'dorei-Druiden, die beim Angriff auf den Schattenwindwald verletzt wurden. Sie hat Umschläge für ihre Brüder vorbereitet, die in Nightfang Den gleich nördlich jenseits der Lichtung Zuflucht gefunden haben. Nur wenige Shen'dorei-Druiden sind noch am Leben, und jeder Überlebende zählt für ihre gefährdete Enklave."},{t="Die Suche nach Jorel Windsinger",b="Elegael bittet Euch, ihren Gefährten Jorel Windsinger zu finden und die sieben schwer verletzten Druiden in der Höhle zu versorgen. Als sie vor den Kämpfen floh, um Arzneien vorzubereiten, rang Jorel bereits mit dem Tod. In Nightfang Den zeigt sich das ganze Ausmaß der Verwüstung des Heiligtums, und in seinen dunklen Winkeln liegt Jorels Schicksal verborgen."},{t="Ein Schwur der Vergeltung",b="Als Elegael von Jorels Ende erfährt und den schrecklichen Blutzoll unter ihren Brüdern sieht, schlägt ihre Trauer in Zorn um. Sie schüttelt die Verzweiflung ab und entscheidet sich für Vergeltung. Jeder, der mit den Al'Aketh verbündet ist, wird für das Abschlachten ihres Volkes ihren unerbittlichen Zorn zu spüren bekommen."}},faq={{q="Wer vergibt die Quest The Wounds of Betrayal?",a="Elegael, eine Shen'dorei-Druidin, bittet Euch, ihre verwundeten Brüder nach einem gewaltsamen Angriff im Schattenwindwald zu versorgen.",al={"wer vergibt the wounds of betrayal","questgeber the wounds of betrayal","wer ist elegael"}},{q="Wo liegt Nightfang Den?",a="Nightfang Den liegt nördlich jenseits der Lichtung im Schattenwindwald. Verwundete Shen'dorei-Druiden haben in der Höhle Zuflucht gesucht.",al={"wo ist nightfang den","nightfang den lage","wo sind die verwundeten druiden"}},{q="Wer ist Jorel Windsinger?",a="Jorel Windsinger ist Elegaels Gefährte. Beim Angriff schwer verletzt, blieb er in Nightfang Den zurück, wo Ihr von seinem Schicksal erfahrt.",al={"wer ist jorel windsinger","jorel windsinger schicksal","wo ist jorel"}},{q="Was sind die Shen'dorei-Druiden?",a="Die Shen'dorei sind ein seltenes Volk mit nur wenigen Druiden in ihren Reihen. Elegael sagt, dass jeder Überlebende kostbar ist.",al={"was sind die shendorei","wer sind die shendorei-druiden","shendorei-druiden hintergrundgeschichte"}},{q="Wer sind die Al'Aketh?",a="Die Al'Aketh sind Feinde, die für den Angriff auf die Druiden verantwortlich sind, oder Verbündete der Verantwortlichen. Nachdem Elegael von Jorels Schicksal erfahren und die Verwüstung gesehen hat, schwört sie ihnen und all ihren Verbündeten Rache.",al={"wer sind die alaketh","al aketh","warum hasst elegael al aketh"}},{q="Was geschieht mit Jorel Windsinger in der Quest?",a="Als Ihr Jorel Windsinger in Nightfang Den findet, hat sein Zustand eine tragische Wendung genommen. Die Nachricht von seinem Schicksal und dem elenden Zustand der überlebenden Druiden erfüllt Elegael mit Trauer und Zorn, und sie schwört Rache.",al={"was geschieht mit jorel windsinger","lebt jorel","jorels schicksal"}}},fp="22,202,22.265.0,31.307.1,20.247.2,43.111.0,31.123.0,24.120.0,31.101.0,21.214.0,46.206.0"}
P.entries["quest:94490"] = {n="Zerfetztes Schreiben",s="Haalien trägt nach einem Angriff auf einen Druidenbau im Schattenwindwald einen blutverschmierten Brief bei sich. Seine Worte enthüllen, wonach die Kultisten suchten, und deuten auf eine Gefahr innerhalb von Valanaar hin.",h="Haalien trägt nach einem Angriff auf einen Druidenbau im Schattenwindwald einen blutverschmierten Brief bei...",kw={"kultist","druidenbau","elegael thornpaw","haalien","lotheluum","pylon","zerrissene nachricht","schattenwindwald","valanaar"},ang={["class:Druid"]="Der Brief bringt bittere Nachrichten: Die Druiden im Bau wurden niedergemetzelt, weil sie Kultisten im Weg standen, die einen Pylon suchten."},sec={{t="Blutbefleckte Befehle",b="Haaliens Nachricht gewährt einen Einblick in die Gewalt im Schattenwindwald. Der nach einem erbitterten Scharmützel gefundene Papierfetzen enthält düstere Nachrichten über Kultisten, die einen örtlichen Druidenbau angegriffen haben. Seine Worte liefern Hinweise für jene, die Gerechtigkeit für die Gefallenen suchen."},{t="Sinnloses Gemetzel",b="Elegael Thornpaw erfährt, warum die Kultisten den Bau angriffen. Sie suchten einen geheimnisvollen Pylon und waren nicht auf eine Fehde mit den Druiden aus. Die Bewohner des Baus starben, weil sie ihnen im Weg standen. Erzürnt über das Gemetzel schwört Elegael Rache an allen Kultisten, die sich noch im Wald aufhalten."},{t="Verrat in Valanaar",b="Befehle aus Valanaar stecken hinter dem Angriff. Die Nachricht verweist auf eine Anweisung aus der Siedlung, wo möglicherweise ein Verräter am Werk ist. Um die Verschwörung aufzudecken, bevor weitere Leben verloren gehen, muss der Brief unverzüglich Lotheluum in Valanaar erreichen."}},faq={{q="Was ist die Zerrissene Nachricht?",a="Die Nachricht ist ein zerrissener, blutbefleckter Brief, der nach einem Kampf hinter Haaliens Armschiene gefunden wurde. Sie enthüllt, warum Kultisten einen Druidenbau im Schattenwindwald angriffen.",al={"was ist die zerrissene nachricht","zerrissene nachricht quest","blutbefleckte nachricht haalien"}},{q="Wo wird die Nachricht geborgen?",a="Die Nachricht wurde nach einer gewaltsamen Auseinandersetzung hinter Haaliens Armschiene gefunden. Der Kampf hinterließ den Brief zerrissen und blutbefleckt.",al={"wer hat die zerrissene nachricht fallen gelassen","woher stammt die zerrissene nachricht","wer ist haalien"}},{q="Wer soll die Zerrissene Nachricht erhalten?",a="Elegael Thornpaw im Schattenwindwald soll die Nachricht zuerst erhalten. Nachdem Elegael sie gelesen hat, soll sie auf Elegaels Anweisung hin rasch zu Lotheluum in Valanaar gebracht werden.",al={"wer will die zerrissene nachricht","wem die zerrissene nachricht geben","elegael thornpaw nachricht"}},{q="Warum griffen die Kultisten den Druidenbau an?",a="Die Kultisten griffen den Druidenbau an, um sich einen dort befindlichen Pylon zu sichern. Sie töteten die Druiden, weil diese ihnen im Weg standen.",al={"warum griffen die kultisten den druidenbau an","kultisten motiv druidenbau","warum griff haalien an"}},{q="Woher kamen die Befehle zum Angriff?",a="Die Nachricht deutet auf Befehle aus Valanaar hin, wo möglicherweise ein Verräter die Arbeit der Kultisten lenkt.",al={"woher kamen die befehle","wer schickte haalien","valanaar verräter"}},{q="Wer ist Lotheluum und warum muss Lotheluum benachrichtigt werden?",a="Lotheluum ist eine Kontaktperson in Valanaar. Elegael Thornpaw befiehlt, die Nachricht dorthin zu bringen, um davor zu warnen, dass die tödlichen Befehle von jemandem stammen, der sich in der Siedlung verbirgt.",al={"wer ist lotheluum","warum die nachricht zu lotheluum bringen","lotheluum valanaar"}}},fp="14,167,19.240.0,19.260.1,21.250.2,27.155.0,36.126.0,38.158.0,42.114.0,38.96.0,47.166.0"}
P.entries["quest:94491"] = {n="The Fate of the Den",s="An der Druidenhöhle trauern Überlebende nach dem Kultistenangriff um ihre Gefallenen. The Fate of the Den führt mit einem sichergestellten Schreiben und der Nachricht von schweren Verlusten zu Lotheluum in Valanaar. Die Depesche enthüllt, dass jemand in Valanaar den Feind mit entscheidenden Informationen versorgt hat.",h="An der Druidenhöhle trauern Überlebende nach dem Kultistenangriff um ihre Gefallenen.",kw={"kultisten","druidenhöhle","hoher ältester","lotheluum","schreiben","the fate of the den","verräter","valanaar"},ang={["class:Druid"]="Als Druide spürt Ihr die Last dieser Tragödie. Die Gefallenen waren Eure Gefährten, und feindliche Kultisten haben ihre abgeschiedene Zuflucht verraten."},sec={{t="Tragödie in der Den",b="Kultisten überfielen die Druidenhöhle und ließen ihre Verteidiger schwer mitgenommen und in Trauer um gefallene Kameraden zurück. Hilfe von außen brachte die unmittelbare Gefahr unter Kontrolle, doch die körperliche und seelische Verwüstung bleibt gewaltig. Die Toten können nicht zurückgebracht werden, und die verwundeten Überlebenden sind für den langen Marsch zu schwach. Verbliebene Kultisten streifen noch immer in der Nähe umher."},{t="Verrat in Valanaar",b="Das sichergestellte Schreiben zeigt, dass die Kultisten ihr Ziel bewusst gewählt haben. Jemand, der sich in Valanaar verbirgt, hat sie mit Informationen versorgt. Als Lotheluum von dem Gemetzel hört und die Depesche liest, weicht die Trauer um seine gefallenen Gefährten der Bestürzung. Ein Verräter bewegt sich noch immer frei in der Siedlung. Er bringt die Beweise zum Hohen Ältesten, damit ihr Opfer nicht vergessen wird."}},faq={{q="Wer ist Lotheluum?",a="Lotheluum lebt in Valanaar und erhält Berichte über die Druidenhöhle. Die Nachricht vom Angriff und das sichergestellte Schreiben lassen ihn um seine gefallenen Gefährten trauern, weshalb er Beweise für den Verrat zum Hohen Ältesten bringt.",al={"lotheluum","wer ist lotheluum","lotheluum npc"}},{q="Was geschah an der Druidenhöhle?",a="Kultisten verwüsteten die Druidenhöhle und töteten viele Verteidiger. Ein Abenteurer half, die unmittelbare Gefahr unter Kontrolle zu bringen, und die schwer mitgenommenen Überlebenden fanden Beweise dafür, dass ein Insider den Angriff gelenkt hatte.",al={"was geschah in der den","angriff auf die druidenhöhle","fate of the den hintergrundgeschichte"}},{q="Was enthüllt das sichergestellte Schreiben?",a="Das Schreiben enthüllt, dass jemand, der sich in Valanaar verbirgt, den Kult heimlich mit Informationen versorgt hat. Es deutet darauf hin, dass Sabotage und Spionage vor Ort den tödlichen Überfall auf die Höhle ermöglichten.",al={"was steht im schreiben","schreiben aus der höhle","verräter schreiben"}},{q="Wer ist der Hohe Älteste, den Lotheluum erwähnt?",a="Der Hohe Älteste ist eine Autorität in Valanaar, der Lotheluum untersteht. Angesichts schwerer Verluste und der Bedrohung durch einen Verräter bringt Lotheluum das Schreiben und die Nachricht von der Tragödie zum Hohen Ältesten.",al={"wer ist der hohe älteste","valanaar hoher ältester","hoher ältester"}},{q="Wer war für den Angriff auf die Druidenhöhle verantwortlich?",a="Mitglieder eines in der Region tätigen Kults griffen die Druidenhöhle an. Ein Informant, der in Valanaar Unterschlupf fand, leitete sie an, und der Angriff kam die Bewohner der Höhle teuer zu stehen.",al={"wer griff die höhle an","wer griff die druidenhöhle an","höhle kultisten"}},{q="Warum konnte der Überlebende an der Höhle das Schreiben nicht persönlich überbringen?",a="Der Überlebende war durch den Angriff zu schwer verwundet, um den Marsch nach Valanaar zu bewältigen. Der Überlebende blieb zurück, um die verbliebenen Kultisten auszuschalten, und schickte einen Abenteurer los, um Alarm zu schlagen.",al={"warum überbringen wir das schreiben","questgeber verwundet","warum kann der überlebende nicht nach valanaar gehen"}}},fp="19,269,18.340.0,21.379.1,17.202.0,31.204.0,39.171.0,45.194.0,48.164.0,69.180.0"}
P.entries["quest:94493"] = {n="A Sacrifice in Vain",s="Elegael Thornpaw fürchtet, dass die Al'Aketh-Kultisten die Verwundeten in ihrem Bau überwältigen. Eine Nachricht an Valanaar hat sie nicht erreicht, und so bittet sie um Hilfe.",h="Elegael Thornpaw fürchtet, dass die Al'Aketh-Kultisten die Verwundeten in ihrem Bau überwältigen.",kw={"a sacrifice in vain","al'aketh-kultisten","bau","elegael thornpaw","verstärkung","valanaar","verwundete"},sec={{t="Eine Bitte um Hilfe",b="Die Al'Aketh-Kultisten überfielen Elegael Thornpaws Gefährten fast ohne Vorwarnung. Viele in ihrem Lager sind verwundet oder liegen im Sterben, und sie weiß nicht, wie lange sie den Angriff überstehen können. Sie hatte versucht, Nachricht nach Valanaar zu schicken, doch die Botschaft kam nicht an. Da keine Verstärkung in Sicht ist, bittet Elegael Euch um Hilfe."}},faq={{q="Wer bittet um Hilfe?",a="Elegael Thornpaw bittet um Hilfe, während die Al'Aketh-Kultisten ihre Gefährten angreifen.",al={"wer braucht hilfe","elegael thornpaw","elegael"}},{q="Was ist den Leuten im Bau zugestoßen?",a="Die Al'Aketh-Kultisten überfielen sie ohne große Vorwarnung. Viele sind verwundet oder sterben.",al={"verwundete im bau","was ist hier geschehen","angriff der kultisten"}},{q="Warum hat Valanaar keine Verstärkung geschickt?",a="Elegaels Nachricht hat Valanaar nicht erreicht, daher ist keine Verstärkung eingetroffen.",al={"wo bleibt die verstärkung","nachricht an valanaar","nachricht nach valanaar"}},{q="Was braucht Elegael?",a="Elegael bittet Euch, ihren verwundeten Gefährten zu helfen, den Angriff der Al'Aketh-Kultisten zu überleben.",al={"wie kann ich helfen","elegael helfen","worum bittet sie"}}},fp="19,163,14.316.0,23.75.0,39.83.0,41.77.0,23.83.0"}
P.entries["quest:94494"] = {n="Call of Water",s="In Loch Modan ruft Norric Lochthane einen Schamanen zur Reinheit des Wassers. Nachdem der Initiand mit Wind, Erde und Flamme Harmonie gefunden hat, ist er bereit, mit dem Wasser Zwiesprache zu halten.",h="In Loch Modan ruft Norric Lochthane einen Schamanen zur Reinheit des Wassers.",kw={"call of water","elemente","berg","reinheit","schamane","totemprüfung","wassertotem"},ang={["class:Shaman"]="Als Schamane tut Ihr einen grundlegenden Schritt zur Zwiesprache mit den Elementargeistern. Ihr geht von Erde und Feuer zur Wandelbarkeit und Reinheit des Wassers über.",["race:Dwarf"]="Als Zwerg hört Ihr den rauen Tonfall eines Mentors, während Ihr schroffen Bergpfaden folgt, um mit der Natur Zwiesprache zu halten."},sec={{t="Der Pfad der Reinheit",b="Ein Schamane, der mit Erde, Wind und Flamme Gleichgewicht gefunden hat, wendet sich nun dem Wasser zu. Seine Lehre reicht über eine Kraft hinaus, die sich beherrschen lässt. Wasser bietet ein spirituelles Sinnbild für Reinheit und Widerstandskraft."},{t="Aufstieg zu den Elementen",b="Norric Lochthane drängt den Initianden, ohne Verzögerung weiterzugehen. Zwiesprache mit den Elementen verlangt Anstrengung und Ausdauer, und der Weg führt durch unwegsames Land bergauf. Der Berg wartet auf niemanden. Erkenntnis beginnt mit dem Aufstieg."}},faq={{q="Was ist Call of Water?",a="Call of Water leitet die Zwiesprache eines Schamanen mit dem Wasser ein. Nachdem der Initiand von Erde, Wind und Feuer gelernt hat, sucht er nun die tiefere Wahrheit des Wassers.",al={"was ist call of water","call of water quest","was ist diese quest"}},{q="Wer begleitet diesen Schritt der Reise?",a="Eldrun Stormbreaker, der Schamanenlehrer in Eisenschmiede, schickt den Initianden zu Norric Lochthane in Loch Modan. Norric drängt zu einem entschlossenen ersten Schritt, denn weder die Elemente noch die Höhen warten auf Zögernde.",al={"wer vergibt call of water","wer sagt der berg wartet auf niemanden","call of water mentor"}},{q="Was bedeutet es, dass der Berg auf niemanden wartet?",a="Der Spruch mahnt den Initianden, einen beschwerlichen Aufstieg zu beginnen. Schamanische Reisen führen auf hohe Gipfel und in entlegene Wildnis, wo die Geister wohnen, und verlangen Entschlossenheit.",al={"was bedeutet der berg wartet auf niemanden","der berg wartet auf niemanden","bedeutung des berges"}},{q="Was ist die Wahrheit über die Reinheit des Wassers?",a="Wasser lehrt Reinigung, Wandelbarkeit und Reinheit. Stein bietet Beständigkeit und Feuer nährt die Entschlossenheit, während die Weisheit des Wassers hilft, die Geister im eigenen Inneren ins Gleichgewicht zu bringen.",al={"warum reinheit des wassers","wahrheit über die reinheit des wassers","bedeutung des elements wasser"}},{q="Wie steht Wasser hier zu den anderen Elementen?",a="Erde, Wind und Feuer sind Grundlagen, die der Initiand bereits in Stiefeln, Atem und Bauch gespürt hat. Harmonie verlangt Gleichgewicht zwischen den Elementen, statt nur einer einzigen Macht nachzustreben.",al={"welche elemente kommen zuerst","voraussetzungen für wasser","call of water elemente"}},{q="Wohin geht der Initiand, nachdem er diese Worte gehört hat?",a="Norric Lochthane schickt den Initianden ins Sumpfland, um bei Hervdana Saegrund nach Water Sapta zu suchen. Sie lebt in einer Höhle unterhalb der südlichen Wasserfälle.",al={"was geschieht als nächstes bei call of water","wohin geht es jetzt","nächster schritt call of water"}}},fp="13,164,18.179.0,24.227.0,26.141.0,36.205.0,53.171.0,36.156.0,49.173.0,53.148.0"}
P.entries["quest:94495"] = {n="Call of Water",s="Im Sumpfland lernen Suchende, was reines Wasser vermag, und suchen nach dem Water Sapta. Unter den südlichen Wasserfällen heißt Hervdana Saegrund jene willkommen, die der Wildnis trotzen.",h="Im Sumpfland lernen Suchende, was reines Wasser vermag, und suchen nach dem Water Sapta.",kw={"call of water","zwerg","hervdana saegrund","schamane","südliche wasserfälle","water sapta","sumpfland"},ang={["class:Shaman"]="Als Schamane lernt Ihr das Wesen des Wassers kennen und sucht ein Water Sapta, um mit seinen Geistern Zwiesprache zu halten.",["faction:Alliance"]="Als Reisender der Allianz dringt Ihr tief in das gefährliche Sumpfland vor, fernab der Wachpatrouillen der Zwerge oder der Allianz.",["race:Dwarf"]="Als Zwerg erkennt Hervdana Euch als einen der Ihren, der den gefährlichen Sümpfen trotzt, wo ganz in der Nähe Dunkeleisenzwerge lauern."},sec={{t="Das Wesen des Wassers",b="Reines Wasser schenkt neues Leben, formt Stein und spült Unreinheiten fort. Verunreinigtes Wasser droht Verderben zu bringen. Wer Zwiesprache mit dem Wasser sucht, wird in die Wildnis geschickt, um von jenen, die nahe dem Element leben, ein Water Sapta zu erhalten."},{t="Zuflucht unter den Wasserfällen",b="Hervdana Saegrund und ihre Familie leben in einer abgelegenen Höhle direkt unter den südlichen Wasserfällen des Sumpflands. Die Wachen von Eisenschmiede sind weit entfernt, und in den umliegenden Sümpfen lauern Dunkeleisenzwerge. Dennoch halten Hervdana und ihre Angehörigen an ihrem abgeschiedenen Heim bei den Wasserfällen fest."}},faq={{q="Wer ist Hervdana Saegrund?",a="Hervdana Saegrund ist eine Zwergin, die mit ihrer Familie in einer Höhle unter den südlichen Wasserfällen des Sumpflands lebt. Sie hilft Schamanen, die Zwiesprache mit dem Wasser und die Geheimnisse des Water Sapta suchen.",al={"wer ist hervdana","hervdana saegrund","wo ist hervdana"}},{q="Was ist das Water Sapta?",a="Ein Water Sapta ist ein rituelles Elixier, mit dem Schamanen Zwiesprache mit Wassergeistern halten. In den östlichen Reichen werden Suchende zu Hervdana Saegrund nahe den südlichen Wasserfällen geschickt, um eines zu erhalten.",al={"was ist water sapta","bedeutung von sapta","warum water sapta beschaffen"}},{q="Wo ist Hervdana Saegrund zu finden?",a="Hervdana Saegrund und ihre Familie leben in einer abgelegenen Höhle direkt unter den südlichen Wasserfällen im Sumpfland.",al={"wo lebt hervdana","wo ist die höhle","lage der südlichen wasserfälle"}},{q="Warum lebt Hervdana im gefährlichen Sumpfland?",a="Hervdana und ihre Angehörigen haben aus eigenen Gründen die Einsamkeit der Wasserfallhöhle gewählt, trotz der Dunkeleisenzwerge in den Sümpfen und der fehlenden Stadtwachen.",al={"warum im sumpfland leben","gefahren im sumpfland","dunkeleisenzwerge im sumpfland"}},{q="Welche Lehre über das Wasser wird hier vermittelt?",a="Reines Wasser bringt Wiedergeburt, formt Stein, spült Unreinheiten fort und lindert die Erschöpfung der Müden. Verderbtes oder verunreinigtes Wasser droht Verderben zu bringen.",al={"was bedeutet wasser","philosophie des wassers","lehre des wassers"}},{q="Welchen Zweck hat die Quest Call of Water?",a="Schamanen nehmen Call of Water auf sich, um das Wesen des Wassers kennenzulernen und das Water Sapta bei Lehrern zu suchen, die abgeschieden leben.",al={"was für eine quest ist das","für wen ist diese quest","quest für zwergenschamanen"}}},fp="13,172,19.234.0,25.277.0,25.191.0,24.183.0,37.114.0,49.167.0,40.130.0,47.114.0"}
P.entries["quest:94497"] = {n="Call of Water",s="Im Sumpfland sammelt ein Initiand durch Call of Water Wasser, um das Sapta zu verdienen. Der Sumpf ist gefährlich, doch seine Gewässer zeigen, wie die Energien des Wassers das Land formen und erhalten.",h="Im Sumpfland sammelt ein Initiand durch Call of Water Wasser, um das Sapta zu verdienen.",kw={"call of water","dunkeleisen","flussmündung","hervdana","sapta","wasserschlauch","sumpfland"},ang={["class:Shaman"]="Als Schamane sucht Ihr das Sapta, indem Ihr in verschiedenen Landstrichen das Wesen des Wassers ergründet. Ihr stimmt Euren Geist auf seine vielen Formen ein.",["race:Dwarf"]="Als Zwerg hört Ihr, wie Hervdana die Spaltung zwischen den Klans beklagt. Dunkeleisenzwerge drängen nach Norden bis ins Sumpfland vor."},sec={{t="Der Weg zum Sapta",b="Hervdana führt Initianden auf der Suche nach Wasser in seinen vielen Formen. Sie lernen, wie es sich bewegt, Leben verändert und das Land erhält. Ihr Weg zum Sapta und zur Zwiesprache mit den Geistern beginnt an einer Flussmündung, wo Meeresgezeiten auf Süßwasser aus dem Hochland treffen."},{t="Wo Süßwasser auf Brackwasser trifft",b="Unterhalb von Hervdanas Höhle tragen Wasserfälle Quellwasser aus dem Hochland in den Sumpf. Dort trifft es auf Salzwasser, das die Gezeiten der Küste ins Landesinnere drücken. Das Meer bringt Sedimente, Mineralien und Energien mit sich, die sich von denen im klaren Schmelzwasser des Gebirgsschnees unterscheiden. Wo diese Gewässer zusammentreffen, kann ein Initiand in den natürlichen Abläufen des Landes Weisheit finden."},{t="Schatten im Sumpf",b="Gefährliche Sumpfkreaturen machen das Wassersammeln riskant. Auch Dunkeleisenzwerge sind weit nach Norden ins Sumpfland vorgedrungen. Hervdana bedauert die Feindseligkeit zwischen den Zwergenklans. Sie sieht, wie viel das Zwergenvolk erreichen könnte, wenn es seine Fehden beilegen würde."}},faq={{q="Was ist das Sapta?",a="Das Sapta ist ein heiliger Trank, der einem Initianden die Zwiesprache mit Elementargeistern ermöglicht. Um es zu verdienen, sucht ein Initiand Wasser in seinen vielen Formen und lernt, wie es das Land formt und das Leben nährt.",al={"was ist das sapta","sapta bedeutung","warum das sapta suchen"}},{q="Wer ist Hervdana?",a="Hervdana leitet Initianden von ihrer Höhle oberhalb der Wasserfälle im Sumpfland aus an. Sie weist sie an, Wasserproben zu sammeln und sich auf das Element einzustimmen.",al={"wer vergibt call of water","wo ist hervdana","hervdanas höhle"}},{q="Warum Wasser sammeln, wo Süßwasser auf Brackwasser trifft?",a="An der Flussmündung treffen Schmelzwasser und Quellwasser aus dem Hochland auf die Gezeiten des Meeres. Ihre Gewässer tragen Sedimente, Mineralien und spirituelle Weisheit mit sich.",al={"warum mündungswasser","brackwasser im sumpfland","süßwasser trifft auf salzwasser"}},{q="Welche Gefahren lauern nahe den Wasserfällen?",a="Gefährliche Sumpfkreaturen und Dunkeleisenzwerge bedrohen Reisende nahe den Wasserfällen. Die Zwerge sind nach Norden ins Sumpfland vorgedrungen.",al={"dunkeleisenzwerge im sumpfland","warum sind dunkeleisenzwerge hier","bedrohung durch dunkeleisenzwerge"}},{q="Was bedeutet es, ein Gefäß zu werden?",a="Ein Gefäß ist ein Initiand, der in den Gewässern Weisheit sucht und Opfergaben aus der Natur mit sich führt, um die elementare Harmonie zu vertiefen.",al={"was ist ein gefäß","gefäß des wassers"}},{q="Wofür wird der Leere braune Wasserschlauch verwendet?",a="Hervdana stellt den Leeren braunen Wasserschlauch bereit, um im Sumpf am Fuße der Wasserfälle eine Brackwasserprobe zu sammeln.",al={"leerer brauner wasserschlauch verwendung","welcher wasserschlauch wird verwendet"}}},fp="13,176,20.273.0,26.308.0,20.248.0,18.191.0,16.149.0,52.128.0,38.136.0,37.126.0,43.116.0"}
P.entries["quest:94499"] = {n="Call of Water",s="Hervdana Saegrund schickt Euch aus dem Sumpfland zu den Steinwachtfällen im Rotkammgebirge, um das Wasser zu prüfen. Was Ihr zurückbringt, wird Euren spirituellen Prüfungen dienen.",h="Hervdana Saegrund schickt Euch aus dem Sumpfland zu den Steinwachtfällen im Rotkammgebirge, um das Wasser zu...",kw={"call of water","hervdana saegrund","der immerruhsee","nightcrawler-murlocs","rotkammgebirge","sapta","shadowseers","steinwachtfälle","sumpfland"},ang={["class:Shaman"]="Als Schamane sammelt Ihr Wasser für ein Sapta und beweist an weit entfernten Gewässern Eure Hingabe und Wahrnehmung, bevor Ihr mit den Wassergeistern Zwiesprache haltet."},sec={{t="Eine verdächtige Kaskade",b="Hervdana Saegrund schickt Euch vom Sumpfland nach Süden, um das Wasser der Steinwachtfälle im Rotkammgebirge zu untersuchen. Der Immerruhsee versorgt Seenhain mit sauberem Wasser, doch unterhalb der Kaskade lauern Murlocs. Sie sind ungewöhnlich groß und entstellt geworden. Hervdana vermutet Gift, üble Zauberei oder Sickerwasser aus der alten Festung oberhalb der Fälle. Sie bittet Euch, eine Probe in einem Leeren roten Wasserschlauch zu sammeln."},{t="Die wahre Quelle der Verderbnis",b="Hervdana Saegrund stellt fest, dass das Wasser aus Everstill sauber und frei von Verunreinigungen ist. Dunkle Zauberei von Shadowseers nahe Steinwacht hat die Nightcrawler-Murlocs entstellt, nicht verunreinigtes Wasser. Die Probe beweist, dass die Fälle rein sind und Ihr Euch Euren Prüfungen mit Hingabe widmet. Sie ist außerdem ein unverzichtbares Reagenz zum Brauen eines spirituellen Saptas."}},faq={{q="Wer vergibt diese Quest und wo ist diese Person zu finden?",a="Hervdana Saegrund vergibt sie im Sumpfland. Sie untersucht Wasserquellen und die Reagenzien, die zum Herstellen eines Saptas für die spirituellen Prüfungen eines angehenden Schamanen benötigt werden.",al={"wer vergibt call of water","questgeberin hervdana"}},{q="Warum werdet Ihr ausgesandt, Wasser von den Steinwachtfällen zu sammeln?",a="Hervdana vermutet, dass Gift, dunkle Magie oder Verderbnis aus der alten Festung über die Steinwachtfälle hinabsickern und die Murlocs darunter entstellen könnten. Sie bittet Euch, ihr eine frische Probe zur Untersuchung zu bringen.",al={"warum wasserschlauch im rotkammgebirge füllen","zweck der steinwachtfälle"}},{q="Ist das Wasser der Steinwachtfälle tatsächlich verunreinigt?",a="Nein. Das Wasser ist rein und unbelastet. Hervdana stellt fest, dass die dunkle Magie der örtlichen Shadowseers die Murlocs entstellt.",al={"ist das wasser bei steinwacht verunreinigt","ist der immerruhsee verderbt"}},{q="Warum sind die Murlocs um die Steinwachtfälle so groß und entstellt?",a="Die Nightcrawler-Murlocs nahe den Fällen sind größer und stärker entstellt als jene im Loch oder im Sumpfland. Hervdana führt die Veränderung auf die üble Magie der örtlichen Shadowseers zurück.",al={"warum sind murlocs im rotkammgebirge mutiert","unterschied der murlocs bei steinwacht"}},{q="Wofür wird die Wasserprobe verwendet?",a="Ein Sapta lässt einen Schamanen den Schleier durchdringen und Elementargeister wahrnehmen. Hervdana sammelt reines Wasser aus verschiedenen Quellen, um das Reagenz für Eure spirituellen Prüfungen zu brauen.",al={"was ist sapta","call of water belohnung zweck"}},{q="Wer ist Norric?",a="Norric ist ein Gefährte oder Mentor, der an den schamanischen Prüfungen beteiligt ist. Hervdana sagt, Norric werde erfreut sein, wenn Ihr mit reinem Wasser zurückkehrt.",al={"wer ist norric","norric call of water"}}},fp="13,154,17.377.0,29.321.1,48.155.0,56.206.0,50.111.0,65.166.0,34.165.0,14.135.0"}
P.entries["quest:945"] = {n="Therylunes Flucht",s="An der Meistergleve im Süden der Dunkelküste braucht Therylune Hilfe, um in Sicherheit zu gelangen. Sie ist in die Ausgrabungsstätten geraten, und ihre Schwester Therysil wartet am Schrein von Aessina voller Sorge um sie.",h="An der Meistergleve im Süden der Dunkelküste braucht Therylune Hilfe, um in Sicherheit zu gelangen.",kw={"eschental","kultisten","eskorte","die meistergleve","der schrein von aessina","therylune","therysil","schattenhammer"},ang={["faction:Alliance"]="Wenn Ihr Reisenden wie Therylune helft, stärkt Ihr die Präsenz der Allianz und das Wohlwollen ihr gegenüber bei den Nachtelfen, die das Eschental verteidigen.",["race:NightElf"]="Die Meistergleve zeugt von einer uralten Narbe in Kalimdors Geschichte. Einen anderen Kaldorei in die Ausgrabungen der Kultisten geraten zu sehen, erinnert auf ernüchternde Weise an die Bedrohungen im Eschental."},sec={{t="Ein gefährlicher Spaziergang",b="An der Meistergleve haben Kultisten des Schattenhammers Therylune in die Enge getrieben. Der Schädel einer uralten Monstrosität beherrscht die Schlucht, durchbohrt von einer gewaltigen Steinklinge. Trotz des Grauens, das ihn umgibt, wanderte Therylune ins Herz des Tals. Sie überlebt, indem sie schnell reagiert und sich im unwegsamen Gelände versteckt."},{t="Nachricht an den Schrein",b="Therysil wartet weit im Süden am Schrein von Aessina. Ihre abenteuerlustige Schwester Therylune stört sich selten an schmutziger Kleidung, doch selbst Therysil war entsetzt, dass sie sich in die unheilvollen Ausgrabungen an der Meistergleve gewagt hatte. Sagt ihr, dass Therylune in Sicherheit ist, und ihre Sorge wird nachlassen. Therysil kennt die finsteren Mächte, die die uralte Erde der Dunkelküste durchgraben."}},faq={{q="Wer ist Therylune?",a="Therylune ist eine abenteuerlustige junge Nachtelfe, die in die gefährlichen Ausgrabungen an der Meistergleve im Süden der Dunkelküste geraten ist. Sie ist Therysils Schwester.",al={"therylune","wer ist das mädchen","gefangene elfe"}},{q="Wer ist Therysil?",a="Therysil ist Therylunes Schwester und lebt am Schrein von Aessina im Eschental. Sie ist bestürzt, dass ihre Schwester einem finsteren, verderbten Ort so nahe gekommen ist.",al={"therysil","therylunes schwester"}},{q="Warum ist die Meistergleve so gefährlich?",a="Die Meistergleve ist eine unheilvolle Schlucht, in der vor langer Zeit ein uralter Herr fiel. Kultisten des Schattenhammers wimmeln dort umher, graben und greifen Eindringlinge an.",al={"gefahr an der meistergleve","kultisten an der meistergleve"}},{q="Wohin muss Therylune eskortiert werden?",a="Therylune braucht eine Eskorte, die sie von der Meistergleve fort in Sicherheit bringt. Reist danach zum Schrein von Aessina und sagt ihrer Schwester, dass sie überlebt hat.",al={"eskortenziel","wohin geht therylune"}},{q="Wo liegt der Schrein von Aessina?",a="Der Schrein von Aessina liegt im Südwesten des Eschentals, westlich von Astranaar. Er ist ein Heiligtum, das dem Waldgeist Aessina geweiht ist.",al={"lage des schreins von aessina","wo ist therysil"}},{q="Wie hat Therylune inmitten der Kultisten überlebt?",a="Therylune entging der Gefangennahme, indem sie sich zwischen Felsen und im Gelände versteckte, bevor die umliegenden Kultisten des Schattenhammers sie entdecken konnten.",al={"wie hat sich therylune versteckt"}}},fx={["8c0c4bd7"]={q="Warum braucht Therylune Eure Hilfe bei der Flucht?",a="Therylune ist bei der unheilvollen Ausgrabung bei The Master's Glaive umhergeirrt und fand sich schnell gefangen und umzingelt von Kultisten des Schattenhammerklans wieder. Während ihr Geschick im Verstecken sie am Leben erhielt, kann sie nicht allein an den sie einkesselnden Eiferern vorbeischleichen, um Sicherheit zu erreichen und ihre Schwester Therysil zu beruhigen.",al={"warum will therylune hilfe","therylune beweggrund","warum therylune helfen"}},cc515991={q="Warum kann Therylune nicht alleine entkommen?",a="Obwohl sie geschickt genug darin ist, sich zu verstecken, um einer sofortigen Gefangennahme zu entgehen, ist Therylune völlig unbewaffnet, wehrlos und tief in feindlichem Gebiet gefangen. Da keine örtlichen Wachen oder Verbündeten in der Nähe sind, um ihr zu helfen, ist sie völlig darauf angewiesen, dass ein vorbeiziehender Abenteurer ihr einen Fluchtweg durch die Kultisten bahnt.",al={"warum braucht therylune mich","warum kann therylune nicht entkommen","warum ich therylune"}}},fp="18,189,17.304.0,18.371.0,17.159.0,16.156.0,40.167.0,41.143.0,39.130.0,49.129.0"}
P.entries["quest:94500"] = {n="Call of Water",s="Im Eschental sammelt Ihr reines Wasser aus dem See neben Astranaar. Es ist die letzte Probe, die Ihr braucht, bevor Ihr zu Norric zurückkehrt.",h="Im Eschental sammelt Ihr reines Wasser aus dem See neben Astranaar.",kw={"eschental","astranaar","auberdine","call of water","menethil","norric","süderstade","wasserschlauch"},ang={["faction:Alliance"]="Als Reisender der Allianz überquert Ihr das Meer von den Östlichen Königreichen nach Kalimdor und segelt vom Hafen von Menethil nach Auberdine. Von dort erreicht Ihr Astranaar, eine Siedlung der Nachtelfen.",["race:NightElf"]="Als Nachtelf werdet Ihr ausgesandt, Wasser aus dem reinen See neben Astranaar zu sammeln, im Kernland der Kaldorei im Eschental. Uralte Ruinen liegen dort noch immer unberührt."},sec={{t="Die Suche nach reinem Wasser",b="Ihr werdet ausgesandt, einen Wasserschlauch mit dem unverdorbenen Wasser des Eschentals zu füllen. Astranaar ist eine Zuflucht neben dem See, dessen uralte Wasser an versunkene Ruinen plätschern. Dies ist die letzte Flüssigkeitsprobe, die der Questgeber benötigt, bevor er Euch zu Norric weiterschickt."},{t="Der Weg nach Astranaar",b="Um von den Östlichen Königreichen ins Eschental zu gelangen, überquert Ihr das Meer mit dem Schiff vom Hafen von Menethil in Richtung Auberdine. Unterwegs legt das Schiff in Süderstade an. Von den Docks von Auberdine folgt Ihr der Straße landeinwärts unter das grüne Geäst des Eschentals. Bleibt zwischen den wachsamen Schatten der Bäume auf der Hut."}},faq={{q="Was ist die Quest Call of Water?",a="Ihr tragt einen leeren Wasserschlauch in den uralten Wald des Eschentals, um reines Wasser aus dem See neben Astranaar zu sammeln. Die Probe könnte verzaubert sein, und Ihr bringt sie dem Questgeber zurück.",al={"was ist call of water","call of water quest","call of water questziel"}},{q="Wo sammle ich das Wasser für diese Quest?",a="Sammelt Wasser aus dem See neben Astranaar, tief im Eschental. Er ist noch immer unverdorben, und unter seiner Oberfläche liegen uralte versunkene Ruinen.",al={"wo reines wasser finden","wo wasserschlauch füllen","call of water ort"}},{q="Wie reise ich für diese Quest ins Eschental?",a="Überquert das Meer mit dem Schiff vom Hafen von Menethil nach Auberdine. Unterwegs hält das Schiff in Süderstade. Von Auberdine an der Küste der Dunkelküste reist Ihr nach Süden durch die tiefen Wälder des Eschentals nach Astranaar.",al={"wie nach astranaar gelangen","reise ins eschental","schiff nach astranaar"}},{q="Was macht das Wasser bei Astranaar so besonders?",a="Der See neben Astranaar birgt Wasser, das von Verderbnis unberührt ist. Versunkene Steinruinen deuten auf eine uralte Epoche elfischer Zivilisation hin und verleihen dem Wasser seine reinen, möglicherweise verzauberten Eigenschaften.",al={"welcher see in astranaar","astranaar wasser ruinen","ruinen im see von astranaar"}},{q="Wer ist Norric?",a="Norric erwartet Euch, nachdem Ihr die letzte Flüssigkeitsprobe gesammelt habt. Der Questgeber nimmt das reine Wasser aus dem Eschental entgegen, bevor er Euch zu Norric zurückschickt.",al={"wer ist norric","zu norric zurückkehren"}},{q="Welche Gefahren erwarten mich im Eschental?",a="Das Eschental ist ein uralter, dichter Wald voller Gefahren. Der Questgeber warnt Euch, unter seinem grünen Blätterdach auf der Hut zu bleiben, wo wachsame Augen niemals blinzeln.",al={"gefahr im eschental","bedrohungen im eschental"}}},fp="13,126,25.233.0,21.285.0,32.174.0,44.137.0,44.197.0,42.188.0,14.146.0,42.147.0"}
P.entries["quest:94501"] = {n="Call of Water",s="In Loch Modan bereiten sich Suchende darauf vor, mit Wassergeistern in Verbindung zu treten. Hervdana segnet reines Wasser für Norric Lochthane, während angehende Schamanen den Wassertotemriten näherkommen.",h="In Loch Modan bereiten sich Suchende darauf vor, mit Wassergeistern in Verbindung zu treten.",kw={"call of water","hervdana","loch modan","mondbruch","norric lochthane","schamane","stendels tümpel","phiole mit reinstem wasser","water sapta","wassertotem"},ang={["class:Shaman"]="Als Schamane stellt Ihr Euch einer Prüfung, um mit den Elementen in Verbindung zu treten. Ihr verdient Euch die Wassertotemriten und stellt das Sapta her, das Ihr benötigt, um Elementargeister wahrzunehmen.",["faction:Alliance"]="Als Schamane der Allianz sucht Ihr in den östlichen Landen zwischen Loch Modan und Westfall die Verbindung zu Wassergeistern.",["race:Dwarf"]="Als Zwerg könnt Ihr in ganz Khaz Modan bei Lehrmeistern der Elemente wie Norric Lochthane Rat suchen."},sec={{t="Der Weg zum Wassertotem",b="Durch Geduld und Ehrfurcht sucht Ihr Einklang mit dem Wasser. Hervdana segnet das Wasser, das Ihr sammelt, und Ihr bringt es zu Norric Lochthane in Loch Modan."},{t="Die Entstehung des Sapta",b="Norric Lochthane braut aus Hervdanas gesegnetem Wasser ein Water Sapta. Der Trank lässt Euch die Wassergeister an Stendels Tümpel nahe Mondbruch wahrnehmen. Jeder Tropfen zählt, und der angefeuchtete Pfropfen hat seinen Platz in den Riten."}},faq={{q="Wer ist Norric Lochthane?",a="Norric Lochthane betreut Anwärter in Loch Modan, die mit den Elementen in Verbindung treten wollen. Er beaufsichtigt die Vorbereitungen und Riten zur Erlangung des Wassertotems.",al={"wer ist norric","norric loch modan","wer ist norric lochthane"}},{q="Wer ist Hervdana?",a="Hervdana Saegrund lebt mit ihrer Familie in einer Höhle bei den südlichen Wasserfällen im Sumpfland. Sie leitet angehende Schamanen an und segnet heiliges Wasser zur Herstellung von Water Sapta.",al={"wer ist hervdana","von hervdana gesegnet","hervdana wasser"}},{q="Wozu dient ein Sapta?",a="Ein Sapta ist ein Trank, der mit heiligem Wasser zubereitet wird. Wer ihn trinkt, kann als Schamane schwer wahrnehmbare Wassergeister in natürlichen Wasserbecken erkennen.",al={"was ist water sapta","sapta zweck","was bewirkt sapta"}},{q="Wo liegt Stendels Tümpel?",a="Stendels Tümpel liegt in Westfall nahe Mondbruch. Dort leben Wassergeister, die ein Schamane aufsucht, nachdem er ein zubereitetes Sapta getrunken hat.",al={"wo ist stendels tümpel","stendels tümpel lage","wassergeister stendels tümpel"}},{q="Warum ist die Phiole mit reinstem Wasser wichtig?",a="Die Phiole mit reinstem Wasser enthält gesegnetes Wasser, das zum Brauen des Water Sapta und für die Riten zur Erlangung eines Wassertotems benötigt wird. Norric mahnt, dass jeder Tropfen zählt.",al={"warum reines wasser nötig","phiole mit reinstem wasser zweck"}},{q="Was sind die Wassertotemriten?",a="Die Wassertotemriten sind spirituelle Prüfungen, die Schamanen auf das Wasser einstimmen. Schamanen beweisen Respekt und Ausgeglichenheit, bevor sie ein Wassertotem erhalten.",al={"was sind wassertotemriten","wie ein wassertotem erhalten"}}},fp="13,168,27.150.0,18.228.1,24.159.0,16.165.0,25.123.0,32.133.0,42.162.0,31.137.0"}
P.entries["quest:94502"] = {n="Call of Water",s="Ihr reist von Loch Modan nach Westfall, wo eine verderbte Quelle die Wassergeister zum Schweigen gebracht hat. An Stendels Tümpel könnt Ihr die Verderbnis läutern und einen alten Schrein erwecken, um ihre Gunst und das Wassertotem zu erlangen.",h="Ihr reist von Loch Modan nach Westfall, wo eine verderbte Quelle die Wassergeister zum Schweigen gebracht hat.",kw={"call of water","loch modan","mondbruch","norric","schamane","stendels tümpel","wassertotem","westfall"},ang={["class:Shaman"]="Als Schamane unterzieht Ihr Euch einem Übergangsritus, um Euch auf die Wassergeister einzustimmen und das Wassertotem zu erlangen. Es zeugt von Einklang mit den elementaren Kräften und ihrer Beherrschung.",["faction:Alliance"]="Als Schamane der Allianz reist Ihr von Loch Modan nach Westfall, um dessen verderbte Gewässer zu reinigen."},sec={{t="Eine vom Schatten befleckte Quelle",b="Nahe Mondbruch liegt Stendels Tümpel unter einem dunklen Makel, der sich über Westfall ausbreitet. Sein Wasser war einst klar, doch nun schweigen die örtlichen Wassergeister. Ein alter Schrein steht vernachlässigt am Ufer, bedeckt von Staub und Spinnweben. Ihr könnt versuchen, die darin schlummernden Kräfte zu erwecken."},{t="Der Ritus der Läuterung",b="Norric in Loch Modan führt Euch durch den Ritus, um das Gleichgewicht wiederherzustellen. An Stendels Tümpel stellt Ihr Euch dem üblen Wesen, das das Wasser verunreinigt, und bringt seine Armschienen zum steinernen Schrein. Dort bringt Ihr sie mit Tropfen eines alchemistischen Tranks dar und sprecht die Beschwörungsformel. Seine Dämpfe rufen einen geläuterten Geist herbei, der Weisheit vermittelt und Euch des Wassertotems für würdig befindet."}},faq={{q="Was ist die Quest Call of Water?",a="Für Schamanen, die Gemeinschaft mit den Wasserelementen suchen, ist Call of Water eine spirituelle Prüfung. Ihr läutert die Verderbnis an Stendels Tümpel in Westfall und nutzt seinen alten Schrein, um einen geläuterten Wassergeist herbeizurufen und Euer Wassertotem zu erlangen.",al={"was ist call of water","wassertotem quest","wasserquest westfall"}},{q="Wer vergibt diese Quest?",a="Norric gibt Euch Call of Water in Loch Modan. Er unterweist Euch in elementaren Riten, stellt besondere Tränke bereit und leitet Euch bei der Läuterung verderbter elementarer Gewässer an.",al={"wer vergibt call of water","norric loch modan","questgeber"}},{q="Wo liegt Stendels Tümpel?",a="Stendels Tümpel liegt etwas außerhalb von Mondbruch im Südwesten von Westfall. Einst eine reine Quelle, ist er unter dunklen, verderblichen Einflüssen still und trüb geworden.",al={"wo liegt stendels tümpel","stendels tümpel standort","tümpel nahe mondbruch"}},{q="Wie läutert Ihr die Verderbnis an Stendels Tümpel?",a="Ihr läutert Stendels Tümpel, indem Ihr das verderbliche Wesen besiegt und seine Armschienen an Euch nehmt. Legt sie mit den verbleibenden Tropfen des Tranks auf den alten Schrein und sprecht dann die Beschwörungsformel, die Norric Euch gelehrt hat.",al={"wie tümpel läutern","stendels tümpel läutern","schreinritual"}},{q="Was erhaltet Ihr für den Abschluss dieser Quest?",a="Nachdem Ihr die Prüfung bestanden und Norric in Loch Modan einen Beweis der Läuterung gebracht habt, gibt er Euch das Wassertotem. Es verleiht Euch Macht über die elementaren Kräfte des Wassers.",al={"welche belohnung call of water","wassertotem belohnung"}},{q="Warum ist Stendels Tümpel verderbt?",a="Niemand weiß, was die Dunkelheit an Stendels Tümpel verursacht hat. Der Tümpel liegt unnatürlich still zwischen den Knochen von Tieren. Hat das sich ausbreitende Siechtum Westfalls ihn vergiftet, oder ist der Tümpel selbst ein Quell der Verderbnis?",al={"warum ist stendels tümpel verderbt","was hat den tümpel verderbt"}}},fp="13,212,26.284.0,21.359.1,32.235.0,21.168.0,24.152.0,52.195.0,43.169.0,32.211.0"}
P.entries["quest:94503"] = {n="Call of Water",s="In Westfall vertreibt Ihr rastlose Geister aus den Gewässern, bevor eine Schwache Wassermanifestation mit Euch sprechen kann.",h="In Westfall vertreibt Ihr rastlose Geister aus den Gewässern, bevor eine Schwache Wassermanifestation mit...",kw={"call of water","läuterung","verderbnis","elementar","schwache wassermanifestation","wassergeist","westfall"},ang={["class:Shaman"]="Als Schamane haltet Ihr Zwiesprache mit den Urelementen und läutert verseuchte Wassergeister. Dieser Ritus erinnert Euch an Eure fortwährende Pflicht, das Gleichgewicht der Natur zu wahren.",["faction:Alliance"]="Als Mitglied der Allianz findet Ihr die Manifestation in Westfall, wo die örtlichen Geister unter der schleichenden Fäulnis leiden, die das Land befällt."},sec={{t="Läuterung der verseuchten Gewässer",b="Verderbte Geister stören Westfalls Gewässer und ihr natürliches Gleichgewicht. Ihr sprecht heilige Worte, und strahlendes Licht lässt die rastlosen Essenzen zu Asche und stillem Nebel zerfallen."},{t="Die Warnung des Geistes",b="Sobald die verderbten Geister zurückgedrängt sind, kann eine Schwache Wassermanifestation hervortreten. Sie warnt, dass die Lebensenergien des Landes weiter schwinden und die Bewahrung des Lebens steter Fürsorge bedarf."}},faq={{q="Was ist Call of Water?",a="In Westfall stellt Ihr Euch einer spirituellen Prüfung gegen verderbte Geister. Eine heilige Anrufung drängt sie mit strahlendem Licht zurück und befreit die aufgewühlten Gewässer, damit Ihr mit einer Schwachen Wassermanifestation sprechen könnt.",al={"was ist call of water","call of water westfall","westfall wasserquest"}},{q="Wo ist die Schwache Wassermanifestation zu finden?",a="Die Schwache Wassermanifestation erscheint in Westfall, nachdem die verderbten Geister in der Nähe bezwungen und gebannt wurden. Sie wartet darauf, mit jenen zu sprechen, die den Gewässern geholfen haben.",al={"wo ist die schwache wassermanifestation","standort der manifestation","wassergeist westfall"}},{q="Was geschieht, wenn die verderbten Geister geläutert werden?",a="Wenn die Anrufung endet, zerstreut gleißendes Licht die verderbten Geister. Ihre verseuchte Essenz zerfällt zu Asche, während das Wasser zischend zu sanftem Nebel wird.",al={"was geschieht beim ritual","verderbte geister call of water"}},{q="Ist das Land nach Abschluss der Aufgabe vollständig wiederhergestellt?",a="Die unmittelbare Verderbnis ebbt ab, doch der Elementar warnt, dass die Lebenskraft des Landes weiter schwindet. Die Sterblichen tragen weiterhin die dauerhafte Pflicht, das Leben zu schützen.",al={"ist die verderbnis verschwunden","haben wir das wasser gerettet"}},{q="Wer wird aufgerufen, der Manifestation beizustehen?",a="Ihr werdet aufgerufen, die Geister zu läutern und die Pflicht zu übernehmen, das schwindende Leben zu schützen. Die Manifestation dankt Eurer Klasse dafür, dass sie sich dieser Aufgabe stellt.",al={"wer kann call of water abschließen","klassenvoraussetzung wasserquest"}},{q="Warum wurden die Wassergeister in Westfall verderbt?",a="Verderbte Geister haben Westfalls natürliche Gewässer gestört. Ihre genaue Herkunft ist unklar, doch ihre bösartige Gegenwart zehrt an der Lebenskraft der Gegend.",al={"warum ist das wasser in westfall verderbt","westfall wasserproblem"}}},fp="13,113,28.166.0,20.184.0,22.203.0,52.163.0,53.149.0,53.155.0,47.147.0,49.153.0"}
P.entries["quest:94505"] = {n="Call of Water",s="In Westfall lernt Ihr, was Wasser schenken und Verderbnis nehmen kann. Bringt Norric Lochthane in Loch Modan einen Wassersplitter, und er gewährt Euch ein Wassertotem.",h="In Westfall lernt Ihr, was Wasser schenken und Verderbnis nehmen kann.",kw={"call of water","loch modan","norric lochthane","schamane","wassersplitter","wassertotem","westfall"},ang={["class:Shaman"]="Als Schamane durchlauft Ihr einen Übergangsritus, der Euch Zwiesprache mit Wassergeistern ermöglicht und Euch ein Wassertotem gewährt, um Leben zu heilen und zu erhalten.",["faction:Alliance"]="Als Initiand der Allianz meldet Ihr Euch bei Mentoren wie Norric Lochthane in Loch Modan und stellt Euch Prüfungen an Orten wie Westfall, anders als die Schamanen der Horde in Kalimdor."},sec={{t="Der Pfad des Wassers",b="Ihr reist nach Westfall und kehrt mit einem Wassersplitter zu Norric Lochthane in Loch Modan zurück. Die Reise prüft Eure Hingabe an das Wasser und Euer Verständnis seiner Macht, Leben zu schenken und Verderbnis zu tilgen. Wer sich bewährt, erhält ein Wassertotem und macht einen wesentlichen Schritt auf seinem elementaren Pfad."},{t="Spender des Lebens",b="Wasser schenkt Leben, und Verderbnis beendet es. Norric Lochthane lehrt Euch, die heilsame Stärke des Wassers zu nutzen, um die Schutzbedürftigen zu schützen und Lebewesen zu bewahren. Seine Gaben reichen über die Heilung des Körpers hinaus. Sie bringen Ausdauer, Erneuerung und spirituelles Gleichgewicht."}},faq={{q="Wer ist Norric Lochthane?",a="Norric Lochthane ist ein Schamanenmentor in Loch Modan. Er führt Initianden durch Prüfungen, damit sie Wassergeister verstehen, und prüft ihre Entschlossenheit mit einer Reise nach Westfall. Wenn sie einen Beweis ihrer Zwiesprache bringen, gibt er ihnen ein Wassertotem.",al={"wer ist norric lochthane","wer gibt das wassertotem","norric loch modan"}},{q="Was ist der Wassersplitter?",a="Der Wassersplitter ist der Beweis, den Ihr aus Westfall zu Norric Lochthane in Loch Modan bringt. Er zeigt, dass Ihr mit dem Wasser Zwiesprache gehalten, sein lebensspendendes Wesen verstanden und gelernt habt, Verderbnis zu bekämpfen.",al={"was ist der wassersplitter","wassersplitter verwendung","wassersplitter questgegenstand"}},{q="Warum führt die Prüfung nach Westfall?",a="Ihr reist nach Westfall, um die lebensspendende Kraft des Wassers kennenzulernen und zu sehen, wie Verderbnis es bedroht. Selbst kleine Siege in diesem geplagten Land zeigen Eure Fähigkeit, Leben zu schützen.",al={"warum nach westfall reisen","westfall wasserquest","reise nach westfall call of water"}},{q="Welche Bedeutung hat das Wassertotem?",a="Ein Wassertotem verkörpert Eure Verbindung zum Wasser. Sein reines Wasser kann Wunden lindern und heilen, während seine spirituellen Gaben auch Leben bewahren und erhalten.",al={"was bewirkt das wassertotem","warum brauchen schamanen ein wassertotem","wassertotem hintergrundgeschichte"}},{q="Welche Lehre über Wasser vermittelt die Prüfung?",a="Die Prüfung lehrt Euch, dass Wasser Leben schenkt, während Verderbnis es beendet. Ihr seid damit betraut, mit der Kraft des Wassers Lebewesen zu nähren und zu schützen und das Gleichgewicht wiederherzustellen, wo Verderbnis sie bedroht.",al={"was bedeutet wasser ist leben","call of water philosophie","wasserlehren der schamanen"}},{q="Was folgt nach dem Abschluss von Call of Water?",a="Norric Lochthane sagt, dass Eure nächste elementare Prüfung nicht sofort folgen wird. Er ermutigt Euch, zu üben und die tieferen Geheimnisse des Wassers zu erkunden, bevor Ihr Euch weiteren Prüfungen stellt.",al={"welche prüfung kommt als nächstes","nächste schamanenprüfung","was geschieht nach call of water"}}},fp="13,163,17.305.0,13.267.0,24.236.0,27.193.0,36.173.0,44.145.0,45.201.0,46.170.0"}
P.entries["quest:94532"] = {n="Gnoll Infestation",s="Neza Bloodsnout bei Rog'mar bittet Euch, die Gnolle in den Hügeln südwestlich davon zurückzudrängen. Ihre Anwesenheit stört Handel und Reisen, doch durch das Vordringen der Twilight sind ihre Reihen geschrumpft.",h="Neza Bloodsnout bei Rog'mar bittet Euch, die Gnolle in den Hügeln südwestlich davon zurückzudrängen.",kw={"schläger","gnollplage","gnolle","mystiker","neza bloodsnout","rotkammgebirge","rog'mar","fallensteller","twilight"},sec={{t="Gnolle in den Hügeln",b="Durch das Vordringen der Twilight sind die Gnolle im Rotkammgebirge weniger geworden. Trotzdem machen sie die Hügel südwestlich von Rog'mar unsicher. Neza Bloodsnout bittet Euch, den Weg für Verbündete freizumachen und die Bedrohung zu beseitigen. Solange die Gnolle ihr Gebiet behaupten, leiden Handel und Reiseverkehr."}},faq={{q="Warum sind die Gnolle ein Problem?",a="Die Gnolle in den Hügeln südwestlich von Rog'mar stören den Handel und machen Reisenden zu schaffen.",al={"gnolle stören handel","warum gnolle beseitigen","bedrohung durch gnolle"}},{q="Wo sind die Gnolle?",a="Sie bevölkern die Hügel im Südwesten.",al={"gnollhügel","wo sind die gnolle im rotkammgebirge"}},{q="Wer bittet mich, mich um sie zu kümmern?",a="Neza Bloodsnout bei Rog'mar bittet Euch, die Bedrohung durch die Gnolle zu beseitigen.",al={"wer gab den auftrag gnollplage","neza-quest"}},{q="Gibt es jetzt weniger Gnolle?",a="Ja. Durch das Vordringen der Twilight sind ihre Reihen geschrumpft, doch die Bedrohung bleibt bestehen.",al={"zahl der gnolle","twilight-gnolle"}},{q="Welche Arten von Gnollen gibt es?",a="Genannt werden Rotkammgebirge-Mystiker, Rotkammgebirge-Fallensteller und Rotkammgebirge-Schläger.",al={"gnollarten","mystiker fallensteller schläger"}}},fp="17,187,19.268.0,29.81.0,21.39.0,30.63.0,27.86.0,31.78.0"}
P.entries["quest:94533"] = {n="Snargl's Snout",s="Neza Bloodsnout will Snargls Schnauze als Trophäe. Die unangenehmen Laute des älteren Gnolls machen Verbündeten und Kundschaftern in den Borstenhügeln zu schaffen.",h="Neza Bloodsnout will Snargls Schnauze als Trophäe.",kw={"borstenhügel","gnoll","neza bloodsnout","snargl","snargls schnauze","schnauze","trophäe"},sec={{t="Eine Trophäe für Neza",b="Neza Bloodsnout möchte ein Andenken für eine Sammlung, und Snargl ist der Gnoll, den sie nennt. Ihr werdet in die Borstenhügel geschickt, um seine Schnauze zu holen. Neza erwartet, dass Ihr Euch beeilt; Verbündete und Kundschafter, die dieses Gebiet betreten, werden von Snargls Lauten geplagt."}},faq={{q="Wer ist Snargl?",a="Snargl ist ein älterer Gnoll in den Borstenhügeln, südwestlich von Neza Bloodsnout.",al={"snargl","snargl gnoll","älterer gnoll"}},{q="Warum will Neza Snargls Schnauze?",a="Neza möchte Snargls Schnauze als Andenken für eine Trophäensammlung.",al={"warum schnauze","snargl trophäe","nezas sammlung"}},{q="Wo ist Snargl?",a="Snargl ist in den Borstenhügeln, südwestlich von Neza Bloodsnout.",al={"snargls standort","wo snargl","gnoll in den borstenhügeln"}},{q="Welchen Ärger verursacht Snargl?",a="Snargl macht unangenehme Laute, die Verbündeten und Kundschaftern zu schaffen machen, wenn sie die Borstenhügel betreten.",al={"snargls laute","warum kundschafter geplagt werden","gnolllärm"}},{q="Was sagt Neza, wenn Ihr zurückkehrt?",a="Neza sagt, die Trophäe sei schwerer als erwartet, und heißt sie als Ergänzung der Sammlung willkommen.",al={"snargl abgeschlossen","nezas reaktion","schnauze erledigt"}}},fp="14,133,17.247.0,14.75.0,34.63.0,16.61.0,31.90.0,35.95.0"}
P.entries["quest:94535"] = {n="Bristle Hills Bandits",s="Kreza Darkthorn schickt Euch zu den Borstenhügeln, nachdem Gnolle verbündete Bergleute angegriffen haben. Ihr sollt das gestohlene Erz aus ihren Lagern zurückholen.",h="Kreza Darkthorn schickt Euch zu den Borstenhügeln, nachdem Gnolle verbündete Bergleute angegriffen haben.",kw={"verbündete bergleute","banditen","borstenhügel","gnolle","kreza darkthorn","gestohlenes erz"},sec={{t="Erz aus den Hügeln",b="Verbündete Bergleute melden Angriffe von Gnollen in den Hügeln südlich von Kreza Darkthorn. Ihr sollt die Lager in den Borstenhügeln finden und das gestohlene Erz zurückholen. Die Verluste der Bergleute stehen auf dem Spiel."},{t="Nach der Rückholung",b="Kreza Darkthorn sagt, dass das Erz zurückgeholt wurde und Feuer alle zurückgebliebenen Spuren und Gerüche beseitigen wird."}},faq={{q="Wer schickt mich los, um das gestohlene Erz zurückzuholen?",a="Kreza Darkthorn bittet Euch, das Erz zurückzuholen, das verbündeten Bergleuten gestohlen wurde.",al={"wer ist kreza","erzgeber"}},{q="Wo sind die Banditen?",a="Die Gnolle lagern in den Borstenhügeln, südlich von Kreza Darkthorn.",al={"gnolllager","wo sind die banditen"}},{q="Wer hat das Erz gestohlen?",a="Gnolle in den Borstenhügeln griffen verbündete Bergleute an und stahlen ihr Erz.",al={"erzdiebe","wer hat es genommen"}},{q="Was geschah mit den Bergleuten?",a="Verbündete Bergleute, die in den Hügeln im Süden arbeiteten, meldeten mehrere Angriffe durch Gnolle.",al={"bergleute angegriffen","warum wurde das erz gestohlen"}}},fp="21,139,18.187.0,18.98.1,34.70.0,22.71.0,18.70.0,28.83.0"}
P.entries["quest:94556"] = {n="Jom-jom's Escape",s="Jom-jom möchte nach Hause zurückkehren und bittet Euch, ihn zu Clugfist bei Bolder'ok zu begleiten.",h="Jom-jom möchte nach Hause zurückkehren und bittet Euch, ihn zu Clugfist bei Bolder'ok zu begleiten.",kw={"bolder'ok","clugfist","begleiten","freund","zuhause","jom-jom"},sec={{t="Der Weg nach Hause",b="Jom-jom machte sich auf, um einen Freund zu finden. Nun braucht er Euch, damit Ihr ihn zu Clugfist bei Bolder'ok führt und er nach Hause kann."}},faq={{q="Wer ist Jom-jom?",a="Jom-jom kam, um einen Freund zu suchen, und möchte nun nach Hause.",al={"wer ist jom-jom","jom-jom"}},{q="Wohin möchte Jom-jom gehen?",a="Jom-jom möchte nach Hause zurückkehren, und Ihr sollt ihn zu Clugfist bei Bolder'ok begleiten.",al={"wohin geht jom-jom","jom-jom nach hause"}},{q="Wer ist Clugfist?",a="Jom-jom soll zu Clugfist bei Bolder'ok gebracht werden.",al={"clugfist","wer ist clugfist"}},{q="Warum kam Jom-jom hierher?",a="Jom-jom kam, um einen Freund zu suchen.",al={"warum ist jom-jom hier","jom-jom kam"}},{q="Betrachtet Jom-jom Euch als Freund?",a="Nachdem Ihr ihn gerettet habt, nennt Jom-jom Euch einen Freund.",al={"jom-jom freund","kleiner"}}},fp="16,81,12.107.0,15.59.0,30.87.0,16.62.0,26.34.0,35.47.0"}
P.entries["quest:94568"] = {n="The Cult's True Plans",s="Der Informant des Kults ist gestorben, bevor er sein Wissen weitergeben konnte. Talaanis Shadowsong muss den Ermittlern helfen, einen anderen Weg zu finden, dem Kult entgegenzutreten.",h="Der Informant des Kults ist gestorben, bevor er sein Wissen weitergeben konnte.",kw={"kult","überläufer","friedensbewahrer","talaanis shadowsong","the cult's true plans"},sec={{t="Ein verstummter Überläufer",b="Ein verängstigter Eingeweihter verließ den Kult und hoffte, außerhalb Hilfe zu finden. Bevor er sein Wissen preisgeben konnte, wurde er getötet. Seine Warnungen bleiben, doch die Pläne des Kults bleiben unbekannt."},{t="Die Vorgehensweise überdenken",b="Durch den Tod des Informanten verliert die Führung ihre wichtigste Wissensquelle. Sie berät sich mit Talaanis Shadowsong und überdenkt ihr Vorgehen gegen den Kult. Ein offener Angriff mit Friedensbewahrern gilt als aussichtsloser Kampf, also müssen die Ermittler einen anderen Weg finden."}},faq={{q="Wer war der Überläufer, der in dieser Quest erwähnt wird?",a="Der Überläufer war ein Eingeweihter des Kults, der aus Angst vor dessen Machenschaften Hilfe suchte. Er wurde getötet, bevor er sein Wissen preisgeben konnte.",al={"wer starb in the cult's true plans","wer ist der tote überläufer","überläufer kultgeheimnisse"}},{q="Wer ist Talaanis Shadowsong?",a="Talaanis Shadowsong ist die Kontaktperson, die nach dem Tod des Informanten zurate gezogen wird. Ihr verfolgt eine strategische Beratung mit Talaanis über das weitere Vorgehen gegen den Kult.",al={"talaanis shadowsongs rolle","wer ist talaanis shadowsong","mit talaanis sprechen"}},{q="Warum können die Friedensbewahrer den Kult nicht einfach direkt angreifen?",a="Man erwartet, dass die Friedensbewahrer in einem offenen Kampf gegen den Kult kaum bestehen könnten. Die Ermittler halten einen direkten Angriff für einen aussichtslosen Kampf.",al={"warum den kult nicht bekämpfen","friedensbewahrer gegen kult","direkter angriff auf den kult"}},{q="Was sind die tatsächlichen Pläne des Kults?",a="Die Pläne des Kults bleiben unbekannt, weil der Informant starb, bevor er sein Wissen weitergeben konnte. Was auch immer der Kult vorhat, es war beängstigend genug, um ein Mitglied dazu zu treiben, Hilfe zu suchen.",al={"was plant der kult","machenschaften des kults","bedeutung der wahren pläne des kults"}},{q="Was ist der nächste Schritt nach dem Gespräch mit Talaanis?",a="Nach dem Tod des Informanten und der Entscheidung gegen einen offenen Kampf muss die Führung einen anderen Weg finden, die Pläne des Kults aufzudecken und zu vereiteln.",al={"was geschieht nach the cult's true plans","nächste schritte kultquest"}},{q="Was geschieht in The Cult's True Plans?",a="Ihr sprecht mit Talaanis Shadowsong und verfolgt eine Beratung über den Tod des Informanten. Dabei wird erörtert, warum man sich nicht darauf verlassen kann, dass die Friedensbewahrer den Kult mit Gewalt aufhalten.",al={"the cult's true plans questzusammenfassung","was ist in the cult's true plans zu tun"}}},fp="21,139,19.170.0,23.268.1,45.146.0,27.161.0,55.145.0,33.163.0,51.142.0,42.178.0"}
P.entries["quest:94613"] = {n="My Kingdom for a Horse",s="Ein nahegelegener Bauernhof hat seine Pferde verloren, sodass Farholde für seinen Feldzug gegen die Horde ohne Kavallerie dasteht. Ihr werdet zu Wheeler’s Grange geschickt, um mit Benjy zu sprechen.",h="Ein nahegelegener Bauernhof hat seine Pferde verloren, sodass Farholde für seinen Feldzug gegen die Horde...",kw={"benjy","horde","verschwundene pferde","mein königreich für ein pferd","farholdes kavallerie","kriegspferde","wheelers grange"},sec={{t="Die verschwundenen Pferde",b="Farholdes Kriegspferde stammen von zwei nahegelegenen Bauernhöfen, doch Wheeler’s Grange hat seinen gesamten Bestand verloren. Die Ursache ist unbekannt, und ohne Pferde hat Farholde keine Kavallerie für seinen Feldzug gegen die Horde. Ihr werdet zu Wheeler’s Grange geschickt, um mit Benjy zu sprechen und zu erfahren, was er zu sagen hat."}},faq={{q="Warum braucht Farholde die Pferde?",a="Farholde ist auf Kriegspferde für seine Kavallerie angewiesen, die es für seinen Feldzug gegen die Horde als notwendig erachtet.",al={"warum pferde","kriegspferde brauchen","farholdes kavallerie"}},{q="Was ist mit den Pferden auf Wheeler’s Grange geschehen?",a="Der gesamte Viehbestand der Familie Wheeler ist verschwunden, und die Ursache ist unbekannt.",al={"verschwundene pferde","wohin die pferde verschwinden","wheelers pferde"}},{q="Wer ist Benjy?",a="Benjy ist auf Wheeler’s Grange. Ihr werdet dorthin geschickt, um ihn zu den verschwundenen Pferden zu befragen.",al={"benjy","mann auf wheelers grange","mit wem sprechen"}},{q="Wo werden Farholdes Kriegspferde gehalten?",a="Farholdes Kriegspferde stammen von zwei nahegelegenen Bauernhöfen. Einer davon gehört der Familie Wheeler: Wheeler’s Grange.",al={"pferdehöfe","woher die pferde stammen","kriegspferdehöfe"}}},fp="22,159,17.278.0,34.110.0,50.73.0,13.83.0,38.107.0"}
P.entries["quest:94615"] = {n="Foal Play",s="Auf Wheeler's Grange sind die Pferde aus den Ställen verschwunden. Ihr sucht nach Hinweisen, um herauszufinden, was geschehen ist.",h="Auf Wheeler's Grange sind die Pferde aus den Ställen verschwunden.",kw={"kojoten","farholde","fohlenstreiche","pferde","verschwundene pferde","murlocs","ställe","wheeler's grange"},sec={{t="Eine Suche auf dem Gut",b="Die Ställe auf Wheeler's Grange könnten Hinweise auf die verschwundenen Pferde bergen. Ihr Hüter sagt, sie seien fort gewesen, als er aufstand, um sie zu füttern. Draußen vor Farholde könnten Tiere, Murlocs, Orcs oder andere Gefahren daran schuld sein. Ihr sucht in der Nähe der Ställe, um einzugrenzen, was geschehen ist."}},faq={{q="Wohin sind die Pferde gegangen?",a="Die Pferde sind von Wheeler's Grange verschwunden, und Ihr sucht in der Nähe der Ställe nach Hinweisen darauf, wohin sie gegangen sind.",al={"verschwundene pferde","pferde verschwunden","wo sind die pferde"}},{q="Was könnte die Pferde mitgenommen haben?",a="Der Hüter hält Tiere, Murlocs, Orcs oder andere Gefahren außerhalb Farholdes für mögliche Täter.",al={"wer nahm die pferde","schuld an den pferden","was hat sie erwischt"}},{q="Warum sind die Pferde wichtig?",a="Der Hüter bestreitet seinen Lebensunterhalt mit den Pferden.",al={"warum pferde wichtig sind","pferde lebensunterhalt","pferdegeschäft"}},{q="Wo sollt Ihr nach Hinweisen suchen?",a="Sucht in der Nähe der Ställe auf Wheeler's Grange nach Hinweisen zu den verschwundenen Pferden.",al={"hinweise im stall","wo suchen","fohlenstreiche"}}},fp="9,116,22.266.0,24.110.0,33.100.0,29.47.0,30.82.0"}
P.entries["quest:94616"] = {n="Wassersapta",s="In Westfall nehmt Ihr den Water Sapta, um einen gestörten Teich aufzusuchen. Der zeremonielle Trank schärft Euren Blick für Wassergeister und verborgene Verderbnis, damit Ihr das Ungleichgewicht untersuchen könnt.",h="In Westfall nehmt Ihr den Water Sapta, um einen gestörten Teich aufzusuchen.",kw={"elementare einstimmung","sapta","schamanenprüfung","verdorbener teich","water sapta","wassergeister","westfall"},ang={["class:Shaman"]="Als Schamane könnt Ihr einen Sapta verwenden, um Eure spirituellen Sinne auf Elementargeister einzustimmen, die dem gewöhnlichen Blick verborgen bleiben.",["faction:Alliance"]="Als Mitglied der Allianz untersucht Ihr verdorbene Gewässer in Westfall und bringt elementare Reinigungsriten in die Lande der Allianz."},sec={{t="Die Sicht der Wasser",b="Schamanen bereiten einen Sapta zu, um über die körperliche Welt hinauszublicken. Der Water Sapta stimmt Eure Sinne auf Wasser ein und offenbart Störungen und Geister, die gewöhnlichen Reisenden verborgen bleiben. Ohne diesen veränderten Blick könnte eine elementare Präsenz wie bloßes Wellengekräusel wirken."},{t="Störung in Westfall",b="Der Water Sapta führt Euch nach Westfall, einem dürren Reich der Allianz, das von Unruhe und Vernachlässigung geplagt wird. Ein Teich dort birgt spirituell verunreinigtes Wasser. Mit der Sicht des Saptas sucht Ihr das verdorbene Wasser auf, deckt die Störung auf und stellt die Harmonie mit den örtlichen Wassergeistern wieder her."}},faq={{q="Was ist ein Water Sapta?",a="Ein Water Sapta ist ein zeremonielles Gebräu, das Euren spirituellen Blick auf Wassergeister und Störungen einstimmt, die sterblichen Augen verborgen bleiben.",al={"was ist ein water sapta","water sapta zweck","was bewirkt water sapta"}},{q="Wo liegt der verdorbene Teich in Westfall?",a="Der verdorbene Teich liegt in Westfall. Der Water Sapta führt Euch dorthin, um das verdorbene Wasser zu finden und Euch der spirituellen Störung anzunehmen.",al={"wo liegt der verdorbene teich","verdorbener teich westfall","verdorbener teich fundort"}},{q="Warum führt der Water Sapta nach Westfall?",a="Der Water Sapta führt Euch nach Westfall, weil ein Teich dort verdorbenes Wasser birgt. Ihr untersucht die Verderbnis und versucht, das Gleichgewicht der geplagten Geister wiederherzustellen.",al={"warum nach westfall gehen","westfall wasserverderbnis","warum ist westfalls wasser verdorben"}},{q="Wer verwendet den Water Sapta?",a="Schamanen verwenden Water Saptas bei Prüfungen der Zwiesprache mit den Elementen. Der Trank stimmt ihre Sinne auf Wassergeister ein und hilft ihnen, verborgene Elementare wahrzunehmen und verdorbene Wasserbecken zu untersuchen.",al={"wer trinkt water sapta","wer verwendet water sapta","schamane sapta trinken"}},{q="Was geschieht, wenn Ihr den Sapta zum verdorbenen Teich bringt?",a="Nahe dem verdorbenen Teich in Westfall verleiht der Water Sapta elementare Sicht. Er offenbart den spirituellen Zustand des Wassers oder ruft verborgene Geister herbei, die mit der örtlichen Wasserprüfung verbunden sind.",al={"was geschieht nach der verwendung von sapta","sapta elementare sicht"}},{q="Wie wirken elementare Saptas in der schamanischen Tradition?",a="Saptas sind zeremonielle Tränke, die Schamanen auf ein Element einstimmen und die körperliche Welt mit dem Geisterreich verbinden. Schamanen verwenden sie bei Prüfungen für Erde, Feuer, Wasser oder Luft.",al={"wie wirken saptas","sapta hintergrundgeschichte"}}},fp="11,183,23.267.0,23.267.0,22.127.0,38.138.0,42.163.0,25.180.0,58.170.0,51.171.0"}
P.entries["quest:94618"] = {n="Wheeler's Fleeing Steeds",s="Benjy bittet Euch, ein Pferd zu finden, das nach einem Kojotenangriff von Wheeler's Grange geflohen ist. Füttert es, damit es Euch vertraut und Ihr es zurückführen könnt.",h="Benjy bittet Euch, ein Pferd zu finden, das nach einem Kojotenangriff von Wheeler's Grange geflohen ist.",kw={"benjy","kojoten","futter","geflüchtete pferde","pferde","wheeler's fliehende rösser","wheeler's grange"},sec={{t="Von der Grange geflohen",b="Benjy bei Wheeler's Grange braucht Eure Hilfe, um eines der Pferde zu finden, die vor dem Kojotenangriff flohen. Kojoten haben einige Pferde erbeutet, während andere aus Angst davonliefen. Gebt einem Pferd etwas Futter, damit es Euch vertraut und Ihr es zurückführen könnt."}},faq={{q="Was ist mit den Pferden geschehen?",a="Die Kojoten haben die meisten Pferde erwischt, während einige aus Angst von Wheeler's Grange flohen.",al={"pferde bei wheeler's grange","pferde beim kojotenangriff"}},{q="Wer bittet um Hilfe?",a="Benjy bittet Euch, ein Pferd zu finden, das von Wheeler's Grange floh.",al={"wer hat mir das gegeben","benjys pferde"}},{q="Was soll ich mit dem Futter machen?",a="Gebt einem Pferd etwas Futter, damit es Euch vertraut und Ihr es zurückführen könnt.",al={"wie benutze ich den sack","pferd füttern"}},{q="Warum werden die Pferde gesucht?",a="Benjy sagt, die entlaufenen Pferde sollten gefunden werden, bevor die Kojoten zurückkehren.",al={"warum pferde finden","wo sind sie hingelaufen"}}},fp="24,127,20.231.0,28.78.0,23.58.0,31.70.0,32.72.0"}
P.entries["quest:94638"] = {n="Strength and Mercy",s="Ur'endras Gefährte bittet Euch, ihr Leiden zu beenden, nachdem sie dem Wahnsinn verfallen ist. Eure Entschlossenheit bringt Euch einen Segen ein, mit dem Ihr die Gestalt seiner Artgenossen annehmen könnt.",h="Ur'endras Gefährte bittet Euch, ihr Leiden zu beenden, nachdem sie dem Wahnsinn verfallen ist.",kw={"druidensegen","böenbeerentiefland","gestalt der klaue","shen'darhochland","stärke und gnade","ur'endra","magie der winde"},ang={["class:Druid"]="Als Druide sollt Ihr Eure Entschlossenheit beweisen, bevor Ihr einen Segen erhaltet, mit dem Ihr die Gestalt der Artgenossen des Druiden annehmen könnt."},sec={{t="Eine schwere Bitte",b="Ein Druide bittet Euch, Ur'endras Leiden im Shen'darhochland zu beenden. Sie ist seine Gefährtin, doch der Wahnsinn hat sie gegen ihre eigenen Artgenossen aufgebracht. Der Verlust der Magie der Winde hat viele Geschöpfe dazu gebracht, sich selbst zu verlieren, und Ur'endra gehört zu ihnen. Ihr Unterschlupf liegt in einer Höhle westlich von hier, an den Steilhängen zwischen dem Shen'darhochland und dem Böenbeerentiefland."},{t="Der Segen",b="Im Shen'darhochland trauert Ur'endras Gefährte um ihren Verlust und nennt ihn notwendig für das Gleichgewicht. Er erkennt Eure Entschlossenheit darin, dass Ihr einen so schrecklichen Preis hinnehmt. Er gewährt Euch einen Segen, mit dem Ihr die Gestalt seiner Artgenossen annehmen könnt, und trägt Euch auf, den Schwachen beizustehen und die Bedürftigen zu verteidigen."}},faq={{q="Wer ist Ur'endra?",a="Ur'endra ist die Gefährtin des Druiden, der Euch bittet, ihr Leiden zu beenden.",al={"ur'endra","wer ist urendra","gefährtin des druiden"}},{q="Warum greift Ur'endra ihre Artgenossen an?",a="Ur'endra ist dem Wahnsinn verfallen. Der Verlust der Magie der Winde hat viele Geschöpfe dazu gebracht, sich selbst zu verlieren.",al={"warum ist urendra wahnsinnig","urendra greift an","was ist mit urendra geschehen"}},{q="Wo ist Ur'endras Unterschlupf?",a="Ur'endra hat ihren Unterschlupf in einer Höhle westlich des Druiden, in den Steilhängen zwischen dem Shen'darhochland und dem Böenbeerentiefland.",al={"urendra höhle","wo ist urendra","shen'dar höhle"}},{q="Was soll ich für den Druiden tun?",a="Der Druide bittet Euch, Ur'endras Leiden zu beenden.",al={"urendra aufgabe","was ist zu tun","urendra töten"}},{q="Welchen Segen gewährt der Druide?",a="Der Druide gewährt Euch einen Segen, mit dem Ihr die Gestalt seiner Artgenossen annehmen könnt.",al={"gestaltsegen","weg der klaue","druidensegen"}},{q="Warum bittet der Druide darum?",a="Der Druide hält es für notwendig, Ur'endras Leiden zu beenden, um das Gleichgewicht zu wahren.",al={"warum urendra töten","warum ist das notwendig","gleichgewicht"}}},fp="18,141,12.353.0,12.293.1,16.68.0,34.112.0,25.125.0,33.47.0,35.72.0,32.74.0"}
P.entries["quest:94668"] = {n="Bloodmaster's Ring",s="Am Bloodmaster's Ring meldet Ihr Euch bei Jezap, nachdem Ihr Euch gegen Twilight ogres bewiesen habt. Der Bloodmaster ist bereit zu urteilen, ob Ihr dazugehört.",h="Am Bloodmaster's Ring meldet Ihr Euch bei Jezap, nachdem Ihr Euch gegen Twilight ogres bewiesen habt.",kw={"bloodmaster","bloodmaster's ring","goblin","jezap","abgrund der macht","twilight ogres"},sec={{t="Am Ring",b="Die Herausforderung am Bloodmaster's Ring hat Euch zu Jezap geführt, dem Goblin des Rings. Nachdem Ihr die Twilight-Oger besiegt habt, erstattet Ihr ihm Bericht, während der Bloodmaster und Jezap zusehen. Sie entscheiden, ob Ihr zu denen gehört, die sich dem Abgrund der Macht nähern."}},faq={{q="Bei wem melde ich mich am Bloodmaster's Ring?",a="Ihr meldet Euch bei Jezap am Bloodmaster's Ring.",al={"wer ist jezap","bei jezap melden","bloodmaster's ring goblin"}},{q="Was habe ich getan, bevor ich hierherkam?",a="Ihr habt Twilight ogres zerschmettert, die als schwach beurteilt wurden.",al={"was vorher geschah","twilight ogres","vorheriger schritt am ring"}},{q="Wonach sucht der Bloodmaster?",a="Der Bloodmaster beurteilt, ob Ihr an den Abgrund der Macht gehört.",al={"mich beweisen","was will der bloodmaster","gehöre ich dazu"}}},fp="18,147,11.267.0,45.46.0,33.49.0,36.72.0"}
P.entries["quest:94669"] = {n="Pay to Play",s="Ein Sammler verlangt ein Sicherheitsdepot, bevor Ihr den Bloodmaster's Ring betreten dürft. Zahlt, und Ihr könnt dort Eure Stärke beweisen.",h="Ein Sammler verlangt ein Sicherheitsdepot, bevor Ihr den Bloodmaster's Ring betreten dürft.",kw={"bloodmaster's ring","clugfist","pay to play","stärke beweisen","ring","sicherheitsdepot"},sec={{t="Der Preis für den Eintritt",b="Um den Bloodmaster's Ring zu betreten, sollt Ihr ein Sicherheitsdepot zahlen. Der Sammler sagt, die Zahlung sei zu Eurer Sicherheit erforderlich. Ohne sie droht er, Clugfist zu erzählen, dass Ihr Euch geweigert habt, Eure Stärke vor der willkommen heißenden Gesellschaft zu beweisen. Eure Entscheidung bestimmt, ob Ihr Euch für den Ring qualifiziert."}},faq={{q="Warum muss ich zahlen?",a="Der Sammler sagt, ein Sicherheitsdepot sei zu Eurer Sicherheit und für die Qualifikation zum Bloodmaster's Ring erforderlich.",al={"warum zahlen","sicherheitsdepot","quest pay to play"}},{q="Wer ist Clugfist?",a="Clugfist ist die Person, von der der Sammler droht, ihr zu erzählen, falls Ihr Euch weigert zu zahlen.",al={"wer ist clugfist","clugfist","alter clugfist"}},{q="Was geschieht, wenn ich mich weigere?",a="Der Sammler sagt, er werde Clugfist erzählen, dass Ihr nicht bereit wart, Eure Stärke zu beweisen.",al={"nicht zahlen","depot ablehnen","kein depot"}},{q="Wofür qualifiziere ich mich durch die Zahlung?",a="Mit der Zahlung des Sicherheitsdepots qualifiziert Ihr Euch für den Bloodmaster's Ring.",al={"wofür qualifizieren","eintritt in den ring","bloodmaster ring"}}},fp="11,132,18.294.0,21.106.0,16.76.0,25.90.0,32.67.0"}
P.entries["quest:94670"] = {n="Bloodmaster's Ring",s="Die Herausforderung von Bloodmaster's Ring schickt Euch gegen Buzzbeak ins Feld, mit Ruhm als möglichem Lohn. Der Goblin des Rings erwartet einen leichten Kampf.",h="Die Herausforderung von Bloodmaster's Ring schickt Euch gegen Buzzbeak ins Feld, mit Ruhm als möglichem Lohn.",kw={"bloodmaster","bloodmaster's ring","buzzbeak","ruhm","scheusal","kampf","ring"},sec={{t="In den Ring",b="Der Goblin des Rings stellt Euch Buzzbeak im Ring entgegen. Man sagt Euch, dieser erste Kampf sollte leicht sein, doch der Unhold soll seinen Gegner zu Fall bringen und dessen Habseligkeiten an sich nehmen. Allen, die antreten, wird Ruhm versprochen."}},faq={{q="Gegen wen kämpfe ich in Bloodmaster's Ring?",a="In Bloodmaster's Ring tretet Ihr gegen Buzzbeak an.",al={"kampf des bloodmaster","wer ist buzzbeak","gegner im ring"}},{q="Was soll Buzzbeak tun?",a="Buzzbeak wird als flatterhaftes Scheusal beschrieben, das Euch zu Fall bringen und Eure Habseligkeiten nehmen kann.",al={"buzzbeaks angriff","was tut buzzbeak","scheusal im ring"}},{q="Warum den Ring betreten?",a="Der Goblin des Rings verspricht allen Ruhm, die den Ring betreten.",al={"ruhm im ring","ruhm des bloodmaster","warum gegen buzzbeak kämpfen"}},{q="Soll dieser Kampf leicht sein?",a="Der Goblin des Rings stellt dies als leichten ersten Kampf dar.",al={"leichter ringkampf","bloodmaster leicht","buzzbeak schwierig"}}},fp="18,129,13.212.0,41.44.0,32.90.0,19.54.0,31.55.0"}
P.entries["quest:94672"] = {n="Encroaching Twilight",s="Tran'gul warnt, dass Twilight's Hammer eine menschliche Siedlung westlich von Rog'mar angegriffen hat. Ihr sollt nach Sonnengrund, um die Kultisten auszudünnen, bevor sie sich in der Nähe festsetzen.",h="Tran'gul warnt, dass Twilight's Hammer eine menschliche Siedlung westlich von Rog'mar angegriffen hat.",kw={"encroaching twilight","menschliche siedlung","rog'mar","sonnengrund","tran'gul","twilight's hammer-neophyten","twilight's hammer-plünderer","twilight's hammer"},sec={{t="Eine Gefahr in der Nähe",b="Die menschliche Siedlung im Westen wurde bereits verwüstet, und Rog'mar könnte das nächste Ziel sein. Tran'gul schickt Euch nach Sonnengrund, wo Twilight's Hammer seinen Feldzug gegen jene begonnen hat, die der Kult für Ketzer hält. Seine Plünderer und Neophyten drohen, sich nahe Rog'mar festzusetzen."},{t="Nach dem Kampf",b="Da die Reihen des Kults geschwächt sind, kann Tran'gul der Quelle seiner beispiellosen Ausbreitung nachgehen."}},faq={{q="Um wen sorgt sich Tran'gul?",a="Tran'gul fürchtet Twilight's Hammer, einen Kult, der jene angreift, die er für Ketzer hält.",al={"wer ist die bedrohung","bedrohung durch twilight's hammer"}},{q="Was ist mit der menschlichen Siedlung geschehen?",a="Twilight's Hammer hat eine menschliche Siedlung westlich von Rog'mar verwüstet.",al={"siedlung im westen","was geschah im westen"}},{q="Warum soll ich nach Sonnengrund?",a="Tran'gul schickt Euch nach Sonnengrund, um die Reihen von Twilight's Hammer auszudünnen.",al={"warum sonnengrund","was gibt es in sonnengrund"}},{q="Wen könnte der Kult als Nächstes angreifen?",a="Tran'gul fürchtet, dass Rog'mar nach der menschlichen Siedlung im Westen das nächste Ziel sein könnte.",al={"wer ist als nächstes dran","rog'mar als nächstes"}}},fp="20,173,15.274.0,15.96.1,30.75.0,38.65.0,29.74.0,31.74.0"}
P.entries["quest:94679"] = {n="Snargl's Snout",s="Cedric Dalton bei Southern Watch möchte Snargls Schnauze aus den Borstenhügeln. Er glaubt, dass die Tötung eines starken Gnolls die Reihen im Rotkammgebirge schwächen und den Gnollen Angst einjagen wird.",h="Cedric Dalton bei Southern Watch möchte Snargls Schnauze aus den Borstenhügeln.",kw={"borstenhügel","cedric dalton","gnoll","rotkammgebirge","snargl","snargls schnauze","southern watch"},sec={{t="Ein Gnoll in den Hügeln",b="Bei Southern Watch bittet Cedric Dalton Euch, Snargl zu erledigen, einen berüchtigten Gnoll in einem Bau in den Borstenhügeln. Er glaubt, dass Gnolle Stärke über alles stellen und Snargls Tod die Reihen im Rotkammgebirge schwächen und ihnen Angst einjagen könnte. Cedric möchte, dass Ihr Snargls Schnauze zurückbringt."},{t="Eine Trophäe kehrt zurück",b="Cedric nimmt Snargls Schnauze als Trophäe entgegen und sagt, sie werde bald eingesetzt. Der Tod des Gnolls soll Angst in den Reihen des Rotkammgebirges verbreiten."}},faq={{q="Wer ist Snargl?",a="Snargl ist ein berüchtigter Gnoll in einem Bau in den Borstenhügeln.",al={"wer ist snargl","snargl gnoll","gnoll in den borstenhügeln"}},{q="Wer möchte Snargls Schnauze?",a="Cedric Dalton bei Southern Watch bittet Euch, ihm Snargls Schnauze zu bringen.",al={"für wen ist snargls schnauze","cedric daltons auftrag","schnauze bei southern watch"}},{q="Warum will Cedric Snargl tot sehen?",a="Cedric glaubt, dass Gnolle Stärke über alles stellen und dass die Tötung ihres Stärksten sie schwächen und ihnen Angst einjagen wird.",al={"warum snargl töten","stärke der gnolle","rotkammgebirge einschüchtern"}},{q="Wo ist Snargl?",a="Snargl ist in einem Bau in den Borstenhügeln.",al={"snargls ort","wo ist snargl","bau in den borstenhügeln"}}},fp="14,159,20.287.0,17.144.1,14.61.0,25.69.0,33.122.0,16.43.0"}
P.entries["quest:94680"] = {n="Twilight Missives",s="Tran'gul will herausfinden, warum es rund um Sonnengrund mehr Kultisten des Twilight's Hammer gibt. Er bittet Euch, ihre Schreiben zu holen, damit er erfährt, wonach sie suchen.",h="Tran'gul will herausfinden, warum es rund um Sonnengrund mehr Kultisten des Twilight's Hammer gibt.",kw={"kultisten","schreiben","rog'mar","sonnengrund","tran'gul","twilight missives","twilight shadowmancers","twilight's hammer"},sec={{t="Twilight Missives",b="Tran'gul hat in der Gegend mehr Kultisten des Twilight's Hammer gesehen als früher. Ihre Twilight Shadowmancers sind angesehene Mitglieder des Ordens und könnten etwas über dessen Feldzug wissen. Ihr sollt ihre Schreiben holen, damit Tran'gul herausfinden kann, wonach der Kult sucht."}},faq={{q="Wer bittet um die Twilight Missives?",a="Tran'gul in Rog'mar bittet Euch, in Sonnengrund Schreiben von Twilight Shadowmancers zu bergen.",al={"wer will die schreiben","tran'gul bittet darum","wer ist tran'gul"}},{q="Wo finde ich die Twilight Shadowmancers?",a="Die Twilight Shadowmancers sind in Sonnengrund.",al={"standort der twilight shadowmancers","wo sind die kultisten des twilight's hammer","schreiben aus sonnengrund"}},{q="Warum will Tran'gul die Schreiben?",a="Tran'gul möchte mehr über die Kultisten und ihre Ziele erfahren.",al={"warum die schreiben holen","was will tran'gul wissen","kultistenpapiere"}},{q="Warum sorgen die Kultisten Tran'gul?",a="Tran'gul hat mehr Kultisten des Twilight's Hammer gesehen als früher, und sie scheinen sich ermutigt zu fühlen, ihren Einfluss auszuweiten.",al={"warum sind die kultisten des twilight's hammer hier","kultisten werden mehr","zahl der kultisten des twilight's hammer"}}},fp="17,171,18.258.0,35.91.0,44.45.0,36.67.0,45.128.0"}
P.entries["quest:947"] = {n="Höhlenpilze",s="An der Dunkelküste werden Höhlenpilze für einen Trank benötigt, den Barithras Mondschatten in Auberdine zubereitet. Er bittet Euch, seltene Pilze hinter den Cliffspring Falls zu sammeln und Warnungen aus dem Hain der Uralten nachzugehen.",h="An der Dunkelküste werden Höhlenpilze für einen Trank benötigt, den Barithras Mondschatten in Auberdine...",kw={"auberdine","barithras mondschatten","höhlenpilze","cliffspring falls","dunkelküste","todeskappe","der hain der uralten","onu","schorfstängel"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass Auberdine der wichtigste Stützpunkt der Allianz an der Küste Kalimdors ist. Ein Übel, das sich in den östlichen Bergen ausbreitet, bedroht die gesamte Küste.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr die Suche nach Todeskappen und Schorfstängeln vielleicht zu schätzen. Diese Pilze wachsen in dunklen Höhlen statt auf üppigem Waldboden.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass der Hain der Uralten eng mit dem natürlichen Gleichgewicht der Dunkelküste verbunden ist. Jede Störung unterhalb der Wasserfälle beunruhigt die Kaldorei."},sec={{t="Ein Rezept hinter den Wasserfällen",b="Barithras Mondschatten benötigt Schorfstängel und eine Todeskappe für eine wirkungsvolle Mischung. Beide wachsen in einer feuchten Höhle hinter den Cliffspring Falls im Nordosten der Dunkelküste. Sie zu sammeln ist gefährlicher, als gewöhnliche Waldkräuter zu pflücken."},{t="Die Warnung der Uralten",b="Die Baumwächter im Hain der Uralten warnten Barithras davor, die Höhle zu betreten. Sie spüren eine üble Präsenz in den Berghöhlen. Mondschatten schickt Euch los, um herauszufinden, ob die Ältesten zu Recht ein schleichendes Übel im Norden der Dunkelküste fürchten."}},faq={{q="Wo beginnt diese Aufgabe?",a="Barithras Mondschatten gibt Euch den Auftrag in Auberdine, der Nachtelfensiedlung an der mittleren Küste der Dunkelküste.",al={"wo höhlenpilze annehmen","barithras mondschatten standort","höhlenpilze questbeginn"}},{q="Wo sind die Pilze zu finden?",a="Die Pilze wachsen in einer Höhle hinter den Cliffspring Falls, an der Bergflanke nordöstlich von Auberdine.",al={"wo sind schorfstängel","todeskappe fundort","höhle hinter wasserfall dunkelküste"}},{q="Warum holt Barithras Mondschatten die Pilze nicht selbst?",a="Der Hain der Uralten warnte Barithras davor, sich den Wasserfällen zu nähern. Die großen Uralten spüren, dass ein unnatürliches, erstarkendes Übel in der Höhle Zuflucht gefunden hat.",al={"warum barithras nicht hingeht","warum barithras in auberdine bleibt"}},{q="Welche Pilze werden genau benötigt?",a="Mondschatten benötigt fünf Schorfstängel und eine gefährliche Todeskappe für seinen Trank.",al={"benötigte pilze","welche pilze für mondschatten"}},{q="Was folgt auf diesen Botengang?",a="Nachdem Ihr die Präsenz in der Höhle bestätigt und die Pilze abgeliefert habt, reist Ihr nach Süden zu Onu, dem uralten Beschützer im Hain der Uralten.",al={"nächste quest nach höhlenpilze","onu folgequest"}},{q="Warum sind die Uralten wegen der Cliffspring Falls besorgt?",a="Der Hain der Uralten warnte Barithras, dass ein erstarkendes Übel in der Höhle hinter den Wasserfällen lauern könnte. Er bittet Euch, Pilze zu sammeln und der Warnung nachzugehen.",al={"warnung der uralten cliffspring falls","warum höhle erkunden"}}},fx={a048db56={q="Warum möchte Barithras Mondschatten, dass dies getan wird?",a="Barithras Mondschatten ist ein Kräuterkundiger, der einen starken neuen Trank zusammenbraut, für den seltene Pilze benötigt werden, die nur in der Höhle hinter Cliffspring Falls zu finden sind. Neben seiner alchemistischen Arbeit hegt er jedoch eine tiefere Sorge: Die Grove of the Ancients hat ihn gewarnt, dass in genau dieser Höhle ein aufkommendes Übel lauert. Indem er Euch ausschickt, um die Zutaten zu sammeln, hofft er auch zu erfahren, ob die düsteren Vorzeichen der Ältesten wahr sind.",al={"warum will barithras cave mushrooms","barithras mondschatten beweggrund","warum pilze für barithras sammeln"}},["991c4c10"]={q="Wozu dient die Todeskappe?",a="Die Todeskappe ist ein außergewöhnlich seltener und stark giftiger Pilz, der in der Höhle hinter Cliffspring Falls heimisch ist. Barithras Mondschatten benötigt ein makelloses Exemplar als wichtiges Reagenz für einen speziellen Trank, den er in Auberdine herstellt.",al={"wozu dient die todeskappe","zweck der todeskappe","warum braucht barithras eine todeskappe"}},be6516db={q="Wozu dient der Schorfstängling?",a="Schorfstänglinge sind seltene Pilze, die in der feuchten, schattigen Höhle hinter Cliffspring Falls gedeihen. Barithras Mondschatten benötigt fünf davon, um sie zusammen mit der starken Todeskappe in seine laufenden alchemistischen Gebräue zu mischen.",al={"wozu dienen schorfstänglinge","zweck der schorfstänglinge","warum braucht barithras schorfstänglinge"}}},fp="14,210,25.227.0,21.252.1,27.115.0,32.104.0,61.156.0,35.87.0,35.141.0,55.161.1"}
P.entries["quest:94727"] = {n="Digging for Answers",s="Der Twilight's Hammer gräbt in den Flusslanden nach einer unbekannten Machtquelle. Ihr sollt im Sonnengrund einen seiner Bergarbeiter befragen.",h="Der Twilight's Hammer gräbt in den Flusslanden nach einer unbekannten Machtquelle.",kw={"digging for answers","bergarbeiter","flusslande","source of power","sonnengrund","twilight's hammer"},sec={{t="Bergarbeiter im Sonnengrund",b="Der Twilight's Hammer lässt im Sonnengrund graben, und Ihr sollt einen der Bergarbeiter befragen. Ihre Suche deutet auf eine Machtquelle hin, doch was es damit auf sich hat, ist unbekannt. Die Fanatiker hüten ihre Geheimnisse, daher wissen die Bergarbeiter vielleicht, wonach sie suchen."}},faq={{q="Wonach gräbt der Twilight's Hammer?",a="Der Twilight's Hammer scheint in den Flusslanden nach einer Machtquelle zu suchen, doch was es damit auf sich hat, ist unbekannt.",al={"wonach graben sie","twilight's hammer gräbt","source of power"}},{q="Warum befrage ich einen Bergarbeiter?",a="Die Fanatiker des Twilight's Hammer hüten ihre Geheimnisse, daher sollt Ihr im Sonnengrund einen ihrer Bergarbeiter befragen.",al={"warum bergarbeiter","mit dem bergarbeiter sprechen","quest digging for answers"}},{q="Wo sind die Bergarbeiter?",a="Die Bergarbeiter graben im Sonnengrund, in den Flusslanden.",al={"wo liegt sonnengrund","standort der bergarbeiter","graben in den flusslanden"}}},fp="19,148,20.255.0,42.119.0,29.112.0,21.61.0"}
P.entries["quest:94733"] = {n="Our Ogre Friend",s="Ein Goblin bittet Euch, Gobam in Bolder'ok zu finden und Futter für Snufflesnout, Chub'chobs Eber, mitzubringen. Gobam hilft gern, weil Chub'chob sein Freund ist.",h="Ein Goblin bittet Euch, Gobam in Bolder'ok zu finden und Futter für Snufflesnout, Chub'chobs Eber...",kw={"bolder'ok","chub'chob","klubhaus","gobam","goblin","unser ogerfreund","zahmer eber","snufflesnout"},sec={{t="Die Bitte eines Freundes",b="Nachdem Ihr einige Kämpfe gewonnen habt, bittet Euch der Goblin, Gobam in Bolder'ok zu finden. Er braucht Futter für Snufflesnout, Chub'chobs Eber, sagt aber, dass ihn seine Arbeit auf Trab hält. Gobam ist östlich von Clugfists Klubhaus, und der Goblin hofft, dass Ihr ihn findet."}},faq={{q="Wer ist Gobam?",a="Gobam ist der schüchterne Kerl, den der Goblin Euch in Bolder'ok suchen lässt.",al={"wer ist gobam"}},{q="Wo finde ich Gobam?",a="Gobam ist östlich von Clugfists Klubhaus in Bolder'ok.",al={"gobams aufenthaltsort","wo ist gobam"}},{q="Wer ist Snufflesnout?",a="Snufflesnout ist Chub'chobs zahmer Eber, und der Goblin bittet Euch, Futter für ihn mitzubringen.",al={"snufflesnout","eberfutter"}},{q="Warum braucht der Goblin Hilfe?",a="Der Goblin sagt, dass ihn seine Arbeit auf Trab hält, und bittet Euch deshalb, Futter für Snufflesnout zu finden.",al={"warum dem goblin helfen","goblin ist beschäftigt"}},{q="Warum wird Gobam helfen?",a="Gobam sagt, dass er den Goblin nicht leiden kann, Chub'chob aber helfen wird, weil sie gute Freunde sind.",al={"gobam hilft","warum gobam hilft"}}},fp="15,157,20.242.0,13.66.0,23.51.0,20.83.0,30.86.0,20.92.0"}
P.entries["quest:94734"] = {n="A Boar's Delight",s="Gobam bittet Euch, süße Beeren und Flusspflanzen für Snufflesnout, Chub'chobs Haustier, zu sammeln. Die Zutaten ergeben eine besondere Leckerei.",h="Gobam bittet Euch, süße Beeren und Flusspflanzen für Snufflesnout, Chub'chobs Haustier, zu sammeln.",kw={"beere","gobam","haustier","flusskraut","snufflesnout","süßbeere","leckerbissen"},sec={{t="Ein Leckerbissen fürs Haustier",b="Gobam möchte etwas Besonderes für Snufflesnout zubereiten, das gutes Essen liebt. Ihr sollt süße Beeren und Flusspflanzen für den Leckerbissen zurückbringen."}},faq={{q="Wer ist Gobam?",a="Gobam bittet Euch, Zutaten für eine besondere Leckerei für Snufflesnout, Chub'chobs Haustier, zu bringen.",al={"wer ist gobam","wer bittet um beeren"}},{q="Wer ist Snufflesnout?",a="Snufflesnout ist Chub'chobs Haustier und liebt gutes Essen.",al={"snufflesnout haustier","gobams haustier"}},{q="Welche Zutaten möchte Gobam?",a="Gobam bittet um süße Beeren und Flusskraut, um einen Leckerbissen für Snufflesnout zuzubereiten.",al={"beere und pflanze","welches essen"}},{q="Warum möchte Gobam Beeren?",a="Gobam möchte süße Beeren und Flusskraut für einen besonderen Leckerbissen für Snufflesnout.",al={"warum beeren","beeren wofür"}}},fp="16,133,13.150.0,13.95.0,20.52.0,33.76.0,28.81.0"}
P.entries["quest:94739"] = {n="Bloodmaster's Ring",s="Der Goblin von Bloodmaster's Ring schickt Euch für einen Kampf mit Kronk in die Grube von Bloodmaster's Ring. Die Menge freut sich schon auf die nächste Runde.",h="Der Goblin von Bloodmaster's Ring schickt Euch für einen Kampf mit Kronk in die Grube von Bloodmaster's Ring.",kw={"ansager","bloodmaster","bloodmaster's ring","kampf","kämpfer","kronk","grube"},sec={{t="Der nächste Kampf",b="Der Ansager heizt das Publikum an, während Kronk als nächster Kämpfer wartet. Ihr werdet in die Grube geschickt, um Euch ihm zu stellen, und der Lärm um den bevorstehenden Kampf wird lauter."}},faq={{q="Wer ist Kronk?",a="Kronk ist der nächste Kämpfer im Bloodmaster's Ring. Der Ansager sagt, dass sie sich schon lange kennen, und beschreibt ihn als starken Schläger.",al={"kronk","wer ist kronk","kronk bloodmaster"}},{q="Was will der Bloodmaster von mir?",a="Ihr werdet in die Grube von Bloodmaster's Ring geschickt, um Kronk gegenüberzutreten.",al={"was soll ich tun","aufgabe im ring","bloodmaster ring"}},{q="Warum kämpfe ich gegen Kronk?",a="Der Ansager kündigt Kronk als nächsten Kämpfer an, und der Kampf findet im Bloodmaster's Ring statt.",al={"warum kronk","gegen kronk kämpfen","kampf gegen kronk"}},{q="Wo findet der Kampf statt?",a="Der Kampf findet in der Grube des Bloodmaster's Ring statt.",al={"wo ist der kampf","die grube","ort des rings"}},{q="Was geschieht, nachdem ich die Grube betrete?",a="Der Ansager bereitet sich darauf vor, Kronk anzukündigen, während Ihr Euch in der Grube bereit macht.",al={"nach dem betreten","nächster im ring","was passiert als nächstes"}},{q="Was sagt der Ansager über Kronk?",a="Der Ansager sagt, Kronk sei nicht besonders helle, aber gut darin, alles zu vermöbeln, was ihm in die Quere kommt.",al={"kronks hintergrund","wie ist kronk","ansager kronk"}}},fp="18,136,13.160.0,13.130.0,40.66.0,24.101.0,31.58.0,35.78.0,40.91.0"}
P.entries["quest:94744"] = {n="The Wayward Warrior",s="Krom'rosh bittet Euch, seinen Bruder Dag'rosh bei der Festung des Twilight's Hammer westlich von Rog'mar zu unterstützen. Der Stützpunkt des Kults in Sonnengrund ist geschwächt, und der Kampf verlagert sich zu seiner Festung.",h="Krom'rosh bittet Euch, seinen Bruder Dag'rosh bei der Festung des Twilight's Hammer westlich von Rog'mar zu...",kw={"dag'rosh","krom'rosh","ogerkrieger","rog'mar","sonnengrund","der verirrte krieger","twilight's hammer"},sec={{t="Ein Bruder voraus",b="Krom'rosh schickt Euch zu Dag'rosh, der mit einer Kundschaftergruppe vorausgezogen ist. In den Hügeln westlich von Rog'mar sollt Ihr ihn finden. Krom'rosh sagt, der Twilight's Hammer habe in Sonnengrund an Boden verloren und seine Ogerkrieger hätten sich gegen ihn gewandt. Nun will er, dass Ihr seinem Bruder zur Seite steht, während die Schlacht zur Festung des Kults zieht."}},faq={{q="Wer bittet mich, Dag'rosh zu finden?",a="Krom'rosh bittet Euch, seinen Bruder Dag'rosh bei der Festung des Twilight's Hammer zu unterstützen.",al={"wer hat mich geschickt","krom'rosh","wer will dag'rosh"}},{q="Wo kann ich Dag'rosh finden?",a="Krom'rosh sagt, Ihr sollt Dag'rosh in den Hügeln westlich von Rog'mar suchen.",al={"wo ist dag'rosh","dag'roshs aufenthaltsort","dag'rosh finden"}},{q="Wer ist Dag'rosh?",a="Dag'rosh ist Krom'roshs Bruder. Er ist mit einer Kundschaftergruppe vorausgezogen.",al={"dag'roshs hintergrund","krom'roshs bruder","wer ist dag'rosh"}},{q="Was ist dem Twilight's Hammer in Sonnengrund zugestoßen?",a="Der Stützpunkt des Twilight's Hammer in Sonnengrund ist geschwächt, und seine Ogerkrieger haben sich gegen ihn gewandt.",al={"kult in sonnengrund","stützpunkt des twilight's hammer","was ist mit den ogers passiert"}}},fp="19,191,15.334.0,34.84.0,26.65.0,16.73.0,53.104.0"}
P.entries["quest:94773"] = {n="Divine Grace",s="Eine Lektion namens Divine Grace dankt Euch für Euren Dienst am Licht. Euer Vorbild ist für Reisende in gefährlichen Landen von Bedeutung.",h="Eine Lektion namens Divine Grace dankt Euch für Euren Dienst am Licht.",kw={"gefährliche lande","divine grace","lektion","licht","reisende"},sec={{t="Eine Lektion zum Dank",b="Nach Eurem Dienst wird das Licht für das Vorbild gepriesen, das Ihr Reisenden in gefährlichen Landen gegeben habt. Als Dank für Eure Taten wird Euch eine Lektion angeboten."}},faq={{q="Worum geht es bei Divine Grace?",a="Divine Grace dankt Euch dafür, dass Ihr dem Licht dient und Reisenden in gefährlichen Landen ein Vorbild seid.",al={"divine grace","was ist divine grace","divine grace quest"}},{q="Für wen ist diese Lektion bestimmt?",a="Die Lektion wird Euch als Dank für Euren Dienst am Licht angeboten.",al={"wer erhält die lektion","lektion für mich","divine grace belohnung"}},{q="Welches Vorbild habe ich gegeben?",a="Ihr wurdet Reisenden in gefährlichen Landen und darüber hinaus zum Vorbild.",al={"mein vorbild","leuchtendes vorbild","was habe ich getan"}}},fp="12,116,18.159.0,27.102.0,23.69.0,23.65.0"}
P.entries["quest:94774"] = {n="Divine Grace",s="Hohepriesterin Laurena ruft Euch in die Kathedrale des Lichts in Sturmwind, weil Eure Vorgesetzten einer weiteren Ausbildung zugestimmt haben. Euer Unterricht in den Wegen des Lichts kann nun beginnen.",h="Hohepriesterin Laurena ruft Euch in die Kathedrale des Lichts in Sturmwind, weil Eure Vorgesetzten einer...",kw={"kathedrale des lichts","divine grace","hohepriesterin laurena","licht","diener des lichts","sturmwind","ausbildung"},ang={["class:Priest"]="Als Priester habt Ihr von Euren Vorgesetzten die Erlaubnis zu einer weiteren Ausbildung in den Wegen des Lichts erhalten."},sec={{t="Ein Ruf nach Sturmwind",b="Eure Vorgesetzten schicken Euch in die Kathedrale des Lichts in Sturmwind, nachdem Ihr Euch in ihren Augen bewährt habt. Dort steht Hohepriesterin Laurena bereit, Eure weitere Ausbildung zu leiten. Sie sagt, es gebe Lektionen, die jeder Diener des Lichts lernen müsse, und ist bereit, sie mit Euch zu besprechen."}},faq={{q="Warum werde ich nach Sturmwind geschickt?",a="Eure Vorgesetzten glauben, dass Ihr Euch bewährt habt, und haben einer weiteren Ausbildung in den Wegen des Lichts zugestimmt.",al={"warum sturmwind","zur kathedrale geschickt","warum dorthin gehen"}},{q="Wer ist Hohepriesterin Laurena?",a="Hohepriesterin Laurena befindet sich in der Kathedrale des Lichts in Sturmwind und steht bereit, Eure Ausbildung zu leiten.",al={"laurena wer","wer ist laurena","hohepriesterin"}},{q="Wo finde ich Hohepriesterin Laurena?",a="Hohepriesterin Laurena befindet sich in der Kathedrale des Lichts in Sturmwind.",al={"laurenas standort","wo ist laurena","standort der kathedrale"}},{q="Welche Ausbildung bietet Laurena an?",a="Laurena ist bereit, Lektionen zu besprechen, die alle Diener des Lichts lernen müssen.",al={"ausbildung im licht","welche lektionen","die wege des lichts lernen"}}},fp="12,181,19.290.0,33.108.0,30.101.0,39.65.0,34.81.0"}
P.entries["quest:94789"] = {n="Call of Air",s="Ein Schamane wird zu Veyric Thundervein in den nördlichen Hügeln des Arathihochlands geschickt. Er wird Euch mehr darüber lehren, wie Ihr die Luft beherrscht.",h="Ein Schamane wird zu Veyric Thundervein in den nördlichen Hügeln des Arathihochlands geschickt.",kw={"luft","arathihochland","call of air","schamane","geister der luft","veyric thundervein","windzauber"},sec={{t="Die nördlichen Hügel",b="Ein Schamane schickt Euch nach Norden ins Arathihochland, um Veyric Thundervein zu finden. Das Element Luft ist schwer zu beherrschen, und er kann Euch mehr darüber lehren. Euer wachsendes Können hat Euch so weit gebracht; nun wendet sich Eure Ausbildung dem Wind und den Geistern der Luft zu."}},faq={{q="Wer ist Veyric Thundervein?",a="Veyric Thundervein befindet sich in den nördlichen Hügeln des Arathihochlands, wo er Euch mehr über die Luft lehren kann.",al={"veyric","wer ist veyric","luftlehrer"}},{q="Wo finde ich Veyric?",a="Findet Veyric Thundervein in den nördlichen Hügeln des Arathihochlands.",al={"veyric aufenthaltsort","wo ist veyric","arathi luftlehrer"}},{q="Worum geht es in Call of Air?",a="Ein Schamane schickt Euch zu Veyric Thundervein, damit er Euch mehr über das Element Luft lehren kann.",al={"call of air quest","luftausbildung","windzauber"}},{q="Warum reise ich ins Arathihochland?",a="Veyric Thundervein befindet sich in den nördlichen Hügeln des Arathihochlands und wird Euch mehr über die Luft lehren.",al={"warum arathi","quest nach norden","veyric finden"}},{q="Was lehrt Veyric?",a="Veyric lehrt Euch, Windzauber zu bündeln und die Geister der Luft anzurufen.",al={"veyric ausbildung","geister der luft","windzauber bündeln"}}},fp="11,125,18.245.0,26.103.0,23.66.0,26.91.0,35.102.0,23.73.0"}
P.entries["quest:94792"] = {n="Taming the Beast",s="Josephine Carson lehrt angehende Jäger in Taming the Beast, wie sie für einen wilden Begleiter sorgen. Bei der Prüfung kommen ein Rockhide Boar und eine Zähmerrute zum Einsatz, wobei das Gleichgewicht der Natur gewahrt wird.",h="Josephine Carson lehrt angehende Jäger in Taming the Beast, wie sie für einen wilden Begleiter sorgen.",kw={"tierbegleiter","gleichgewicht der natur","bestien zähmen","jägerbegleiter","josephine carson","rockhide boar","zähmerrute","taming the beast"},ang={["class:Druid"]="Als Druide wisst Ihr, dass Fürsorge und Zurückhaltung helfen, das Gleichgewicht der Natur zu bewahren. Wenn Ihr die Wildtiere des Waldes mit Respekt behandelt, ehrt Ihr die natürliche Ordnung, die zu schützen Ihr geschworen habt.",["class:Hunter"]="Als Jäger ist das Zähmen wilder Bestien für Euch ein prägendes Übergangsritual. Ein treuer Begleiter bietet Schutz und Wachsamkeit im Kampf und schafft eine dauerhafte Partnerschaft zwischen Fährtenleser und Bestie."},sec={{t="Bindung zu Bestien",b="Allein durch die Wildnis zu reisen, kann gefährlich sein. Ein Tierbegleiter bietet Schutz im Kampf und Gesellschaft auf langen Reisen. Für angehende Jäger und Fährtenleser ist es ein entscheidender Schritt, diese Bindung aufzubauen. Josephine Carson führt Novizen durch eine Prüfung mit einem Rockhide Boar und einer Zähmerrute. Um die Bestie zu beruhigen und zu führen, müssen sie gelassen und konzentriert bleiben, ohne der Furcht nachzugeben oder unnötiges Blutvergießen zu verursachen."},{t="Das Gleichgewicht der Natur",b="Josephine Carson warnt ihre Schüler davor, Bestien rücksichtslos auszubeuten. Das Zähmen erfordert Geduld und Disziplin, niemals Grausamkeit oder Dominanz, und das Gleichgewicht der Natur muss gewahrt bleiben. Die verzauberte Rute lässt Novizen den Umgang mit einem furchterregenden Rockhide Boar üben, ohne den örtlichen Wildbestand dauerhaft zu verringern. Sobald sie gelernt haben, die Bestie zu befehligen und zu beruhigen, geben sie die Rute zurück. Respekt vor der Natur kommt vor Stolz."}},faq={{q="Welchen Zweck hat die Quest Taming the Beast?",a="Taming the Beast lehrt angehende Jäger, eine Bindung zu wilden Kreaturen aufzubauen. Josephine Carson zeigt ihnen, wie sie sich einem Rockhide Boar nähern und es mit einer Zähmerrute besänftigen. Die Prüfung vermittelt Überlebensfertigkeiten und Respekt vor dem Gleichgewicht der Natur.",al={"taming the beast quest","was ist taming the beast","jägerbegleiter quest"}},{q="Wer ist Josephine Carson?",a="Josephine Carson unterweist Abenteurer darin, für Tierbegleiter zu sorgen. Sie leiht ihren Schülern eine Zähmerrute, damit sie im Umgang mit Bestien Geduld und Geschick üben können. Sie lehrt, dass diese Arbeit Übung und Respekt vor dem Gleichgewicht der Natur erfordert.",al={"josephine carson","wer vergibt taming the beast","zähmerrute questgeber"}},{q="Wofür wird die Zähmerrute verwendet?",a="Die Zähmerrute ist ein verzaubertes Werkzeug für den sicheren Umgang mit einer furchterregenden Bestie. Sie lässt Novizen das Befehligen und Beruhigen eines Rockhide Boar üben, ohne den örtlichen Wildbestand dauerhaft zu verringern. Sie geben die Rute zurück, sobald sie die Grundlagen erlernt haben.",al={"zähmerrute","was bewirkt die zähmerrute","zähmerrute verwenden"}},{q="Warum brauchen Jäger Tierbegleiter?",a="Ein Tierbegleiter bietet Schutz, Wachsamkeit und Hilfe im Kampf. Eine treue Bestie kann die Frontlinie sichern und einem Reisenden auf langen, gefährlichen Reisen durch die Wildnis Gesellschaft leisten.",al={"warum einen tierbegleiter haben","vorteile eines tierbegleiters","warum bestien zähmen"}},{q="Welche Kreatur muss bei dieser Prüfung gezähmt werden?",a="Die Prüfung erfordert ein Rockhide Boar, eine robuste Bestie, die sich eignet, um grundlegende Fertigkeiten im Umgang mit Tieren zu prüfen. Die Übung lehrt Gelassenheit und Disziplin gegenüber angriffslustigen Wildtieren. Anschließend berichten die Abenteurer Josephine Carson von ihren Fortschritten.",al={"welches wildschwein zähmen","rockhide boar ziel","taming the beast kreatur"}},{q="Warum betont Josephine Carson das Gleichgewicht der Natur?",a="Josephine Carson warnt vor Gier und Gewalt im Umgang mit wilden Bestien. Rücksichtsloser Einsatz stört das Gleichgewicht der Natur, und Bestien sind keine Wegwerfwerkzeuge. Wahre Meisterschaft bedeutet, ihren Platz in der Natur zu respektieren.",al={"gleichgewicht der natur bedeutung","gleichgewicht der natur beim zähmen","warum die natur respektieren"}}},fp="16,181,19.403.0,21.405.0,50.234.0,24.231.0,32.240.0,38.186.0,46.237.0,58.205.0"}
P.entries["quest:94793"] = {n="Training the Beast",s="In Goldhain zeigt Training the Beast jungen Jägern, wie sie einen gezähmten Begleiter versorgen. Isaac Chan lehrt sie, ihre Tiere zu füttern und wiederzubeleben und sie dann für das Leben an ihrer Seite auszubilden.",h="In Goldhain zeigt Training the Beast jungen Jägern, wie sie einen gezähmten Begleiter versorgen.",kw={"wald von elwynn","begleiter füttern","goldhain","jägerbegleiter","isaac chan","begleiterausbildung","begleiter wiederbeleben","training the beast","waldläufer"},ang={["class:Hunter"]="Als Jäger geht Ihr über das Einfangen von Tieren hinaus und baut eine dauerhafte, von Disziplin geprägte Bindung auf. Füttert Euren Begleiter, belebt ihn wieder und bildet ihn aus.",["faction:Alliance"]="Als Jäger der Allianz im Wald von Elwynn könnt Ihr die Grundlagen des Umgangs mit Tieren von erfahrenen Waldläufern wie Isaac Chan in Goldhain lernen."},sec={{t="Die Pflichten der Jagd",b="Ihr sucht Isaac Chan auf, einen erfahrenen Waldläufer in Goldhain, um zu lernen, wie Ihr Euer Tier ausbildet. Eine gezähmte Kreatur braucht Pflege und Disziplin, bevor sie zu einem verlässlichen Verbündeten werden kann. Ohne Chans Anleitung bleibt Euer Begleiter in der Wildnis womöglich widerspenstig."},{t="Die Anleitung eines Waldläufers",b="Isaac Chan lehrt Euch, Euren tierischen Begleiter zu versorgen. Ihr lernt, ihn zu füttern und wiederzubeleben, wenn er im Kampf fällt. Er lehrt Euch auch Befehle, die ihm im Kampf helfen, und erinnert Euch daran, dass Macht über die Tierwelt Respekt verlangt. Achtet das Gleichgewicht der Natur und lebt in Ehrfurcht vor der Welt um Euch herum."}},faq={{q="Wer ist Isaac Chan?",a="Isaac Chan ist seit jeher Waldläufer und lebt in Goldhain im Wald von Elwynn. Er kennt die Tierwelt und das Überleben in der Wildnis und lehrt unerfahrene Jäger, ihre tierischen Begleiter zu führen, zu füttern, wiederzubeleben und ihnen Fähigkeiten beizubringen.",al={"wer ist isaac chan","tierausbilder goldhain","isaac chan hintergrundgeschichte"}},{q="Welchen Zweck hat Training the Beast?",a="Jäger lernen, ein gezähmtes Tier zu versorgen und ihre Bindung zu ihm aufrechtzuerhalten. Isaac Chan lehrt sie, ihren Begleiter zu füttern, ihn wiederzubeleben, wenn er im Kampf fällt, und ihm neue Kampffähigkeiten beizubringen.",al={"was bewirkt diese quest","warum ein tier ausbilden","zweck von training the beast"}},{q="Wo ist Isaac Chan zu finden?",a="Isaac Chan lebt in Goldhain, dem zentralen Ort im Wald von Elwynn, südlich des Nordhaintals und südwestlich von Sturmwind.",al={"wo ist isaac chan","wo diese quest abgeben","isaac chan standort"}},{q="Welche Fähigkeiten lehrt Isaac Chan?",a="Isaac Chan vermittelt die Grundlagen der Pflege und Ausbildung eines tierischen Begleiters. Ihr lernt, Euer Tier zu füttern, es wiederzubeleben, wenn es im Kampf fällt, und ihm neue Fähigkeiten beizubringen, während es an Eurer Seite heranwächst.",al={"welche fähigkeiten werden erlernt","erlernte begleiterfähigkeiten","was lehrt isaac chan"}},{q="Warum erinnert Isaac Chan Jäger daran, die Natur zu achten?",a="Isaac Chan lehrt Jäger Demut vor der Wildnis. Er bittet sie, das Gleichgewicht der Natur zu achten und in Ehrfurcht vor der Welt um sie herum zu leben, damit ihre Bindung zu einem Tier auf Fürsorge statt auf Ausbeutung beruht.",al={"warum die natur achten","gleichgewicht achten jäger"}},{q="Wer nimmt diese Quest an?",a="Jäger, die bereits Tiere zähmen können, suchen Isaac Chans Schulung in der Waldläuferkunst, um einen tierischen Begleiter zu versorgen und auszubilden.",al={"wer kann diese quest machen","ist training the beast nur für jäger"}}},fp="18,184,32.248.0,21.284.0,18.217.0,42.181.0,30.129.0,34.194.0,53.207.0,26.115.0"}
P.entries["quest:948"] = {n="Onu",s="Barithras Mondschatten schickt Euch von Auberdine nach Süden, um Onu zu befragen. Eure Entdeckungen bei den Cliffspring Falls haben die Aufmerksamkeit eines der ältesten Wächter der Dunkelküste geweckt.",h="Barithras Mondschatten schickt Euch von Auberdine nach Süden, um Onu zu befragen.",kw={"ancient of lore","auberdine","barithras mondschatten","cliffwater falls","dunkelküste","der hain der uralten","onu"},ang={["class:Druid"]="Als Druide verehrt Ihr die Uralten als Hüter der Weisheit der Natur. Die seltsamen Gewächse in den Höhlen auf Onus Bitte hin zu untersuchen, entspricht der Arbeit des Zirkels des Cenarius.",["faction:Alliance"]="Als Reisender der Allianz, der bei der Verteidigung der Dunkelküste hilft, könnt Ihr bei den Uralten der Region Einsichten in Kalimdors nördliche Wildnis gewinnen.",["race:NightElf"]="Als Nachtelf kennt Ihr die Ancients of Lore als heilige Gefährten, die Euer Volk schon seit der Zeit vor der Sundering führen. Onus Ruf zu folgen hilft, die Dunkelküste zu bewahren."},sec={{t="Ein Ruf der Uralten",b="Barithras Mondschatten sieht mehr als seltsame Pilze in den Proben, die Ihr nach Auberdine gebracht habt. Die Höhlen unter den Cliffspring Falls sind verderbt, und die Kunde davon hat Onu erreicht, einen Ancient of Lore im Hain der Uralten südlich der Stadt. Die Wasserläufe der Dunkelküste könnten von einer Verderbnis befallen sein, die über alles hinausgeht, was ein Naturkundler erklären kann. Onu sucht Rat, und selbst die Geduld eines Uralten kann das Gewicht seines Rufes nicht verbergen."},{t="Reise zum Hain",b="Die Straße von Auberdine nach Süden führt landeinwärts, fort von den Küstenruinen und auf die Berghänge zu. Der Hain der Uralten birgt eine alte Zuflucht der Natur, abseits des Verfalls entlang der Küste. Onu wartet zwischen steinernen Hügelgräbern und verwandten Geistern. Er ist bereit, Verbündete zu den Plagen zu führen, die sich am Rand der Wildnis regen."}},faq={{q="Wer ist Onu?",a="Als Ancient of Lore sammelt und bewahrt Onu Wissen. Er wacht über den Hain der Uralten im Süden der Dunkelküste und teilt seine Weisheit mit jenen, die das Land verteidigen.",al={"wer ist onu","onus identität","was ist onu"}},{q="Warum will Onu mit mir sprechen?",a="Ihr habt für Barithras Mondschatten Pilzproben aus den Höhlen unter den Cliffspring Falls gesammelt. Eure Funde haben die Naturkundler alarmiert, und Onu möchte mit Euch über die um sich greifende Verderbnis sprechen.",al={"warum ruft onu","grund für das gespräch","warum zu onu gehen"}},{q="Wo liegt der Hain der Uralten?",a="Der Hain der Uralten liegt südlich von Auberdine, entlang der östlichen Bergausläufer. Folgt der Hauptstraße nach Süden durch die Dunkelküste und wendet Euch dann nach Osten zu den Berghängen, um Onu zu erreichen.",al={"onus standort","wo liegt der hain der uralten","wie onu finden"}},{q="Was für ein Wesen ist ein Ancient of Lore?",a="Ancients of Lore sind alte Treantwesen, die mit den Nachtelfen und dem Zirkel des Cenarius verbündet sind. Sie werden für ihre Weisheit und ihr Gedächtnis verehrt und bewahren die Magie und Geschichte der Natur.",al={"ancient of lore","was für ein wesen ist onu","treant oder uralter"}},{q="Warum gilt Onus Ruf als dringend?",a="Uralte handeln bedächtig und eilen selten. Barithras Mondschatten sagt, Onus Bitte um Rat bedeute, dass die Dunkelküste schwer bedroht ist.",al={"warum dringend","ist onu besorgt","barithras' warnung"}},{q="Was folgt auf das Treffen mit Onu?",a="Nachdem Ihr Onu im Hain der Uralten getroffen habt, bittet er Euch, eine finsterere Bedrohung weiter südlich an der Küste zu untersuchen: die Ausgrabung rund um Master’s Glaive.",al={"nächste quest nach onu","was geschieht als nächstes","wohin schickt onu"}}},fx={be40e913={q="Warum schickt mich Barithras Mondschatten zu Onu?",a="Barithras weiß, dass die Ältesten der Lehren tiefes Wissen über die Verderbnis des Landes besitzen, und Onu hat direkt bemerkt, was Ihr in der Höhle bei Cliffspring Falls gefunden habt. Da sich ein Ältester selten meldet, es sei denn, die Dunkelküste steht vor einer tiefgreifenden und dringenden Bedrohung, drängt Barithras Euch dazu, der Vorladung sofort Folge zu leisten.",al={"barithras beweggrund","warum zu onu schicken","warum will barithras das erledigt haben"}}},fp="3,166,27.409.0,20.339.0,11.167.0,35.197.0,35.190.0,44.180.0,39.132.0,34.167.1"}
P.entries["quest:94819"] = {n="Contingency Plan",s="Jemand schickt Euch nach Eisenschmiede, um High Priestess Mims zu treffen. Eure nächste Prüfung rückt näher, und sie wartet im Mystic Ward auf Euch.",h="Jemand schickt Euch nach Eisenschmiede, um High Priestess Mims zu treffen.",kw={"notfallplan","high priestess mims","eisenschmiede","licht","mystic ward","nächste prüfung","riten"},sec={{t="Ein wartendes Gespräch",b="In Eisenschmiede wartet High Priestess Mims im Mystic Ward darauf, mit Euch zu sprechen. Eure nächste Prüfung rückt näher, und die Person, die Euch geschickt hat, kann ihren Platz nicht verlassen, um den Riten Eures Volkes beizuwohnen. Auf Eurer Reise möge das Licht Euch begleiten, wenn Ihr Mims trefft."}},faq={{q="Wen soll ich treffen?",a="High Priestess Mims wartet im Mystic Ward von Eisenschmiede darauf, mit Euch zu sprechen.",al={"wer wartet","mims treffen","mims"}},{q="Wo finde ich Mims?",a="Mims sollte sich im Mystic Ward in Eisenschmiede aufhalten.",al={"wo ist mims","mims' aufenthaltsort","mystic ward"}},{q="Warum gehe ich nach Eisenschmiede?",a="High Priestess Mims möchte dort mit Euch sprechen, und Eure nächste Prüfung rückt näher.",al={"warum eisenschmiede","was gibt es in eisenschmiede","gespräch"}},{q="Was sagt die Person, die mich geschickt hat, über die Riten meines Volkes?",a="Die Person, die Euch geschickt hat, würde gern den Riten Eures Volkes beiwohnen, sagt aber, dass sie ihren Platz nicht verlassen kann.",al={"riten meines volkes","besondere riten","warum kann die person nicht kommen"}},{q="Was wird für meine Reise gewünscht?",a="Die Person, die Euch geschickt hat, wünscht, dass das Licht Euch auf Eurer Reise begleitet.",al={"segen des lichts","licht begleite mich","reisesegen"}}},fp="16,129,18.253.0,23.76.0,22.47.0,28.82.0,49.97.0,30.61.0"}
P.entries["quest:94822"] = {n="Confounding Flash",s="Eure Vorgesetzten schicken Euch nach Eisenschmiede, um Eure Ausbildung bei High Priestess Mims fortzusetzen. Euer Dienst am Licht hat ihre Aufmerksamkeit geweckt.",h="Eure Vorgesetzten schicken Euch nach Eisenschmiede, um Eure Ausbildung bei High Priestess Mims fortzusetzen.",kw={"confounding flash","hall of mysteries","high priestess mims","eisenschmiede","licht","vorgesetzte","ausbildung"},sec={{t="Eine weitere Lektion",b="Eure Vorgesetzten schicken Euch zu High Priestess Mims in der Hall of Mysteries in Eisenschmiede. Sie sind der Ansicht, dass Euer Dienst Euch auf weitere Unterweisung vorbereitet hat. Mims soll Euch anleiten, und die Lektion erwartet Eure Ankunft."},{t="Vor Mims",b="High Priestess Mims empfängt Euch in Eisenschmiede und bemerkt Eure verspätete Ankunft. Angesichts Eures Dienstes am Licht entschuldigt sie die Verspätung und bittet Euch dann, ihrer Lektion aufmerksam zu folgen."}},faq={{q="Wer hat mich nach Eisenschmiede geschickt?",a="Eure Vorgesetzten haben Euch gebeten, für weitere Unterweisung zur Hall of Mysteries in Eisenschmiede zu reisen.",al={"wer hat mich geschickt","wer sind meine vorgesetzten"}},{q="Wer ist High Priestess Mims?",a="High Priestess Mims ist diejenige, die Ihr auf Geheiß Eurer Vorgesetzten in Eisenschmiede aufsuchen sollt. Sie kann Eure weitere Ausbildung anleiten.",al={"wer ist mims","mims"}},{q="Warum werde ich zur Ausbildung geschickt?",a="Eure Vorgesetzten glauben, dass Ihr Euch durch Euren Dienst am Licht bewährt habt.",al={"warum ausbildung","warum ich"}},{q="Wo finde ich High Priestess Mims?",a="Sucht High Priestess Mims in der Hall of Mysteries in Eisenschmiede auf.",al={"wo ist mims","hall of mysteries"}}},fp="17,139,16.203.0,11.169.0,25.94.0,27.115.0,33.82.0,36.63.0"}
P.entries["quest:94824"] = {n="Confounding Flash",s="Eine Nachricht schickt Euch nach Eisenschmiede, um mit Hohepriesterin Mims zu sprechen. Sie erwartet Euch in der Hall of Mysteries, doch der Grund ist noch unklar.",h="Eine Nachricht schickt Euch nach Eisenschmiede, um mit Hohepriesterin Mims zu sprechen.",kw={"confounding flash","hall of mysteries","hohepriesterin mims","eisenschmiede","mit mims sprechen","vorladung"},sec={{t="Ein Ruf nach Eisenschmiede",b="Der Weg vor Euch führt nach Eisenschmiede, wo Hohepriesterin Mims in der Hall of Mysteries auf Euch wartet. Ihr sollt persönlich mit ihr sprechen, doch die Nachricht nennt keinen Grund für die Vorladung. Sie vermutet, dass Eure Taten erfolgreich waren, überlässt es aber Mims, Euch die Angelegenheit zu erklären."}},faq={{q="Wer möchte mit mir sprechen?",a="Hohepriesterin Mims möchte, dass Ihr nach Eisenschmiede kommt, um mit ihr zu sprechen.",al={"wer hat nach mir verlangt","mims vorladung","hohepriesterin mims"}},{q="Wohin soll ich gehen?",a="Ihr sollt mit Hohepriesterin Mims in der Hall of Mysteries in Eisenschmiede sprechen.",al={"wo ist mims","standort der hall of mysteries","nach eisenschmiede gehen"}},{q="Warum möchte Mims mich sehen?",a="Die Nachricht erklärt nicht, warum Hohepriesterin Mims mit Euch sprechen möchte.",al={"warum mims mich gerufen hat","was möchte sie","grund der vorladung"}},{q="Was soll ich tun?",a="Ihr sollt mit Hohepriesterin Mims in Eisenschmiede sprechen.",al={"was ist die aufgabe","mit mims sprechen","mims bitte"}}},fp="17,148,19.277.0,27.66.0,14.86.0,29.77.0,28.67.0"}
P.entries["quest:94841"] = {n="Lost Shipping Crate",s="Eine für Friz Frazzlespark bestimmte Transportkiste ist in den Flusslanden verschwunden. Ihr Etikett bittet darum, sie zum Hafen von Powderfuse zurückzubringen.",h="Eine für Friz Frazzlespark bestimmte Transportkiste ist in den Flusslanden verschwunden.",kw={"kiste","friz frazzlespark","etikett","vermisste transportkiste","karte","hafen von powderfuse","flusslande"},sec={{t="Eine markierte Kiste",b="Friz Frazzlesparks Kiste trägt ein handgeschriebenes Etikett, auf dem der Hafen von Powderfuse in den Flusslanden steht. Eine Karte markiert ein südöstliches Ufer nördlich eines von Wasser umgebenen Tempels, in dessen Nähe geflügelte Kreaturen sind. Das Etikett warnt davor, die Kiste ohne Aufsicht zu öffnen, und nennt Friz als Empfänger."}},faq={{q="Wem gehört die Transportkiste?",a="Auf dem Etikett steht, dass die Kiste Friz Frazzlespark gehört.",al={"besitzer der kiste","wem gehört sie"}},{q="Wohin soll ich die Kiste bringen?",a="Laut Etikett soll die Kiste zu Friz Frazzlespark am Hafen von Powderfuse in den Flusslanden zurückgebracht werden.",al={"wohin die kiste bringen","lieferung der kiste"}},{q="Was steht auf dem Etikett der Kiste?",a="Es nennt Friz Frazzlespark und den Hafen von Powderfuse, warnt davor, die Kiste ohne Aufsicht zu öffnen, und gibt einen Rückgabeort in den Flusslanden an.",al={"etikett der kiste","was darauf steht"}},{q="Kann man die Kiste gefahrlos öffnen?",a="Auf dem Etikett steht, dass sie nicht ohne Aufsicht geöffnet werden soll.",al={"kiste öffnen","warnung zur kiste"}}},fp="19,137,14.300.0,28.55.0,30.94.0,32.153.0,26.50.0"}
P.entries["quest:94863"] = {n="Taming the Beast",s="Josephine Carson führt Euch durch Taming the Beast, während Ihr lernt, mit einem Eber umzugehen, bevor Ihr Euch einem Gray Forest Wolf stellt. Mit einer Zähmerrute versucht Ihr, das Vertrauen des wilderen Tieres zu gewinnen.",h="Josephine Carson führt Euch durch Taming the Beast, während Ihr lernt, mit einem Eber umzugehen, bevor Ihr...",kw={"wildtiere zähmen","gray forest wolf","jäger","jägerausbildung","josephine carson","zähmerrute","taming the beast"},ang={["class:Hunter"]="Als Jäger lernt Ihr die Geduld und den Respekt, die nötig sind, um eine Bindung zu wilden, gefährlichen Raubtieren aufzubauen."},sec={{t="Der Pfad des Jägers",b="Josephine Carson beobachtet, wie Ihr einen weiteren Schritt beim Erlernen des Umgangs mit Wildtieren macht. Ihr habt mit einfachen Ebern geübt; nun betretet Ihr den Wald, um einen Gray Forest Wolf zu zähmen. Die verzauberte Rute, die sie Euch gibt, hilft, das Raubtier zu beruhigen. Geduld und Respekt zählen ebenso viel wie Spurenlesen und Treffsicherheit, wenn Ihr das Vertrauen eines wilden Tieres gewinnen wollt."},{t="Instinkt und Vertrauen",b="Josephine Carson gibt Euch eine spezielle Zähmerrute, um gefährliche Wildtiere zu beruhigen. Nähert Euch dem Wolf mit Geduld und Präzision und überwindet seine Aggression ohne tödliche Gewalt. Nachdem Ihr Eure Bindung zum Tier geübt habt, bringt die Rute als Beweis Eures wachsenden Könnens zu Josephine zurück."}},faq={{q="Was ist die Quest Taming the Beast?",a="Taming the Beast ist eine Ausbildungsprüfung für Jäger, bei der Ihr mit einer verzauberten Zähmerrute einen Gray Forest Wolf zähmt.",al={"taming the beast quest","gray forest wolf quest","wolf zähmen lektion"}},{q="Wer vergibt diese Quest und nimmt sie ab?",a="Josephine Carson unterweist Euch und gibt Euch die Zähmerrute. Nach der Prüfung bringt Ihr sie zu ihr zurück.",al={"wer vergibt taming the beast","wer ist josephine carson","wo taming the beast abgeben"}},{q="Welches Tier müsst Ihr zähmen?",a="Ihr sollt einen Gray Forest Wolf zähmen, ein wilderes Waldraubtier als die Eber, mit denen Ihr zuvor umgegangen seid.",al={"was muss gezähmt werden","welches wildtier","ziel von taming the beast"}},{q="Wozu dient die Zähmerrute?",a="Josephine Carson gibt Euch die Zähmerrute, um einen wilden Gray Forest Wolf zu beruhigen und eine vorübergehende Bindung aufzubauen, ohne bleibenden Schaden anzurichten.",al={"was bewirkt die zähmerrute","warum die zähmerrute benutzen","zähmerrute hintergrund"}},{q="Was hat der Jäger vor dieser Prüfung gezähmt?",a="Bevor Ihr Euch dem Gray Forest Wolf gestellt habt, habt Ihr den Umgang mit einem Waldeber geübt.",al={"zähmen vorherige lektion","was wurde vor dem wolf gezähmt"}},{q="Behaltet Ihr den Gray Forest Wolf als dauerhaften Begleiter?",a="Nein. Nachdem Ihr geübt habt, eine Bindung zu Wildtieren aufzubauen, bringt Ihr die Zähmerrute zu Josephine Carson zurück.",al={"bleibt der wolf erhalten","ist der wolf ein dauerhafter begleiter"}}},fp="16,174,22.331.0,28.279.0,35.112.0,35.99.0,34.107.0,32.133.0,43.73.0,58.94.0"}
P.entries["quest:94864"] = {n="Taming the Beast",s="Im Wald von Elwynn stellen sich Jäger Taming the Beast, der letzten Prüfung unter Josephine Carsons Aufsicht. Nachdem sie einen Eber und einen Wolf gezähmt haben, gewinnt jeder Jäger mit einer Zähmerrute das Vertrauen eines Young Forest Bear. Die Prüfung vertieft die Bindung des Jägers zu wilden Tieren und lehrt Respekt vor dem Gleichgewicht des Waldes.",h="Im Wald von Elwynn stellen sich Jäger Taming the Beast, der letzten Prüfung unter Josephine Carsons Aufsicht.",kw={"einklang mit tieren","tierausbildung","wald von elwynn","jägerquest","josephine carson","zähmerrute","taming the beast","young forest bear"},ang={["class:Hunter"]="Als Jäger geht Ihr über das Spurenlesen hinaus und entwickelt eine tiefere, verständnisvollere Bindung zu wilden Tieren.",["faction:Alliance"]="Als Tiermeister der Allianz könnt Ihr Wildniskundschaftern disziplinierte Begleiter zur Seite stellen, die Gehöfte verteidigen und die Handelsstraßen in Sturmwinds Gebieten patrouillieren.",["race:Human"]="Als menschlicher Jäger in der Ausbildung im Wald von Elwynn lernt Ihr, mit den natürlichen Raubtieren des Königreichs zu leben, statt sie vernichten zu wollen."},sec={{t="Die letzte Jagdprüfung",b="Jäger im Wald von Elwynn lernen, unter den wilden Kreaturen ihrer Umgebung zu leben. Nachdem sie einen Wolf und einen Eber gezähmt haben, erwartet sie eine letzte Prüfung ihres Mutes und ihrer Geduld. Josephine Carson schickt jeden Jäger zu einem Young Forest Bear, dem stärksten der gewöhnlichen Raubtiere des Waldes. Der Jäger muss der Stärke des Bären standhalten und sein Vertrauen gewinnen, statt ihn zur Unterwerfung zu zwingen."},{t="Respekt und Gleichgewicht in Elwynn",b="Wildtiere in Elwynn zu zähmen, verlangt Respekt, keine Herrschaft. Waldbären verkörpern die Stärke und Lebenskraft des Waldes und helfen, seine natürliche Ordnung zu bewahren. Mit einer Zähmerrute lernen Jäger, die Angriffslust eines Bären zu besänftigen und durch Verständnis eine Bindung aufzubauen. Das Vertrauen eines so mächtigen Tieres zu gewinnen, vertieft die Bindung eines Jägers zur Wildnis und schließt die ersten Lektionen unter Josephine Carsons Aufsicht ab."}},faq={{q="Wer erteilt Jägern diese Prüfung?",a="Josephine Carson erteilt die Prüfung Jägern, die im Wald von Elwynn ausgebildet werden. Nachdem sie schwächere Tiere gezähmt haben, gibt sie ihnen Anweisungen und die Zähmerrute für den Waldbären. Nach Abschluss der Prüfung geben sie ihr die Rute zurück.",al={"wer vergibt taming the beast","taming the beast questgeber","josephine carson quest"}},{q="Welche Tiere müssen vor dieser Herausforderung gezähmt werden?",a="Jäger zähmen zuerst einen Eber und einen Wolf, bevor sie sich einem Young Forest Bear stellen. Diese Prüfungen zeigen, dass sie mit zähen Tieren und Rudeltieren umgehen können, bevor sie versuchen, das Vertrauen eines Bären zu gewinnen.",al={"vorausgesetzte tiere zum zähmen","was wurde vor dem bären gezähmt","zuvor gezähmte tiere"}},{q="Warum werden Jäger zu einem Young Forest Bear geschickt?",a="Ein Young Forest Bear stellt einen Jäger auf die Probe, indem er ihn mit der Muskelkraft und Macht der Wildtiere des Waldes von Elwynn konfrontiert. Nach dem Umgang mit dem flinken Wolf und dem zähen Eber muss der Jäger Ausdauer, Respekt und Mut beweisen, um das Vertrauen des Bären zu gewinnen.",al={"warum young forest bear zähmen","young forest bear zweck","warum bären in elwynn"}},{q="Wozu dient die Zähmerrute?",a="Josephine Carson gibt Jägern eine Zähmerrute, die ihnen hilft, wilde Tiere zu beruhigen. Sie hilft, einen angriffslustigen Young Forest Bear zu besänftigen, ohne ihn zu töten, und ermöglicht dem Jäger, eine friedliche Bindung aufzubauen. Jäger geben Carson die Rute zurück, wenn die Prüfung abgeschlossen ist.",al={"zähmerrute zweck","was bewirkt die zähmerrute","warum zähmerrute verwenden"}},{q="Wie hilft das Zähmen von Tieren dem Wald von Elwynn?",a="Jäger lernen, das natürliche Gleichgewicht des Waldes von Elwynn zu bewahren, indem sie Wildtiere mit Respekt und Zurückhaltung behandeln. Sie lenken gefährliche Tiere auf friedliche Weise, statt sie zu erlegen, und bewahren so die Harmonie zwischen den heimischen Wildtieren und humanoiden Siedlungen.",al={"warum ist elwynns gleichgewicht wichtig","gleichgewicht im wald von elwynn","zähmen und waldgleichgewicht"}},{q="Was bedeutet der Abschluss dieser Lektion für einen Jäger?",a="Der Abschluss der letzten Prüfung vertieft die Bindung eines Jägers zu wilden Tieren. Das Vertrauen von Elwynns mächtigster Kreatur zu gewinnen, vermittelt das nötige Verständnis für lebenslange Partnerschaften mit tierischen Begleitern in ganz Azeroth.",al={"was geschieht nach dem zähmen des bären","abschluss der jägerausbildung","einklang mit tieren bedeutung"}},{q="Wo sind Young Forest Bears zu finden?",a="Young Forest Bears durchstreifen die bewaldeten Gebiete des Waldes von Elwynn, zwischen dicht stehenden Bäumen und Seite an Seite mit Wölfen und Spinnen. Jäger verlassen die nahen Siedlungen und spüren die Bären mit der Zähmerrute im Unterholz auf, um Carsons letzte Anweisung zu befolgen.",al={"young forest bear fundort","wo bären in elwynn finden","waldbär elwynn"}}},fp="16,291,27.363.0,29.396.0,34.219.0,49.184.0,47.224.0,38.240.0,42.245.0,54.219.0,35.246.0"}
P.entries["quest:94873"] = {n="Buying Friendship: Gelkis",s="Ein Außenstehender bietet dem Gelkis Clan im Dorf der Gelkis einen Beutel voller Totems an. Der Rüstmeister sieht das Geschenk als Hilfe gegen den Magram Clan.",h="Ein Außenstehender bietet dem Gelkis Clan im Dorf der Gelkis einen Beutel voller Totems an.",kw={"freundschaft erkaufen","zentaur","gelkis","gelkis clan","dorf der gelkis","magram","molkar","totembeutel"},sec={{t="Ein Geschenk für die Gelkis",b="Jemand hat einen Beutel voller Totems vorbereitet, den Ihr dem Rüstmeister im Dorf der Gelkis bringen sollt. Die Gelkis verlieren gegenüber den Magram an Boden, und ihre Isolation könnte sie für Hilfe von außen empfänglich machen. Das Geschenk soll Euer Ansehen beim Clan verbessern."}},faq={{q="Warum den Gelkis einen Beutel voller Totems bringen?",a="Das Geschenk soll Euer Ansehen beim Gelkis Clan verbessern, der gegenüber den Magram an Boden verliert.",al={"totembeutel","warum totems","geschenk für die gelkis"}},{q="Wer erhält den Beutel?",a="Der Rüstmeister im Dorf der Gelkis erhält den Beutel.",al={"rüstmeister der gelkis","wer erhält den beutel","empfänger der totems"}},{q="Welchen Schwierigkeiten stehen die Gelkis gegenüber?",a="Die Gelkis sind gegenüber den Magram im Nachteil, deren Clan ungewöhnlich grausam gewesen ist.",al={"problem der gelkis","magran gelkis","warum verlieren sie"}},{q="Wer ist Molkar?",a="Molkar ist der Rüstmeister der Gelkis, der den Beutel erhält.",al={"molkar gelkis","rüstmeister molkar","wer ist molkar"}}},fp="25,137,21.259.0,38.102.0,22.61.0,32.92.0,14.57.0"}
P.entries["quest:94890"] = {n="Bring Me His Head",s="Sergeant Riftan schickt Euch zurück zum Zwielichtschleier, wo Overlord Kilgar sich weiterhin in seiner Festung versteckt. Die geretteten Soldaten sind kampfbereit, und Riftan will Kilgar zu Fall bringen.",h="Sergeant Riftan schickt Euch zurück zum Zwielichtschleier, wo Overlord Kilgar sich weiterhin in seiner...",kw={"bringt mir seinen kopf","orc","overlord kilgar","gerettete soldaten","sergeant riftan","zwielichtschleier"},sec={{t="Zurück zur Festung",b="Die geretteten Soldaten sind kampfeslustig, und Sergeant Riftan sagt, Eure Stärke habe den Angriff so weit gebracht. Overlord Kilgar, ein Orc, versteckt sich tief in seiner Festung im Zwielichtschleier. Riftan bittet Euch, ihn zu besiegen und seinen Kopf zurückzubringen."}},faq={{q="Wer ist Overlord Kilgar?",a="Overlord Kilgar ist ein Orc-Anführer, der sich tief in seiner Festung im Zwielichtschleier versteckt.",al={"kilgar","wer ist kilgar","orc-anführer"}},{q="Warum werde ich zurück zum Zwielichtschleier geschickt?",a="Die geretteten Soldaten sind kampfbereit, und Sergeant Riftan sagt, der Angriff solle fortgesetzt werden. Er bittet Euch, zum Zwielichtschleier zurückzukehren und den Kopf von Overlord Kilgar zurückzubringen.",al={"warum zurückkehren","aufgabe im zwielichtschleier","wie geht es weiter"}},{q="Wer will Kilgars Kopf?",a="Sergeant Riftan bittet Euch, ihm den Kopf von Overlord Kilgar zu bringen.",al={"was will riftan","wer verlangt kilgars kopf","bringt mir seinen kopf"}},{q="Wo versteckt sich Kilgar?",a="Overlord Kilgar versteckt sich tief in seiner Festung im Zwielichtschleier.",al={"kilgars aufenthaltsort","wo ist der overlord","kilgars festung"}}},fp="17,185,16.255.0,23.86.0,50.180.0,24.61.0,23.72.0"}
P.entries["quest:94891"] = {n="News to Farholde",s="Ashe Amberhall in Burg Farholde erwartet Euren Bericht nach Eurer Arbeit mit Sergeant Riftan. Eure Rückkehr wird zeigen, ob das Vorhaben gelungen ist.",h="Ashe Amberhall in Burg Farholde erwartet Euren Bericht nach Eurer Arbeit mit Sergeant Riftan.",kw={"ashe amberhall","burg farholde","kilgar","nachricht nach farholde","bericht","sergeant riftan"},sec={{t="Ein Bericht für Ashe",b="Sergeant Riftan schickt Euch mit einem Bericht zu Ashe Amberhall in Burg Farholde zurück. Er gibt Euch Kilgars Kopf mit. Ashe sagt, sie habe während Eurer Abwesenheit begonnen, an ihrem Urteilsvermögen zu zweifeln, lobt nun aber Eure Fähigkeiten."}},faq={{q="Wer erwartet den Bericht?",a="Ashe Amberhall in Burg Farholde wartet auf Euren Bericht.",al={"wem soll ich bericht erstatten","bericht für ashe","bericht nach farholde"}},{q="Was gibt Riftan mir mit?",a="Sergeant Riftan gibt Euch Kilgars Kopf, damit Ihr ihn zu Ashe Amberhall bringt.",al={"was warf riftan zurück","kilgars kopf","was trage ich bei mir"}},{q="Was sagt Ashe, wenn ich zurückkehre?",a="Ashe sagt, sie habe begonnen, zu befürchten, Eure Fähigkeiten falsch eingeschätzt zu haben. Dann sagt sie, Ihr seid die Richtigen für den Auftrag gewesen.",al={"amberhalls reaktion","ashes dialog","war ashe besorgt"}},{q="Was sagt Ashe über Riftan?",a="Ashe fragt, ob Riftan noch da ist, und sagt, sie habe erwartet, dass Ihr beide Euch gut versteht.",al={"lebt riftan noch","was ist mit sergeant riftan","ashe und riftan"}}},fp="16,141,17.222.0,21.59.0,25.66.0,33.98.0,32.84.0"}
P.entries["quest:94892"] = {n="Dying Wish",s="Marshal Ryan liegt im Sterben und bittet Euch, sein Wappen zu Knight Commander Demar Brant zu bringen. Seine letzten Worte gelten seiner Heimat und Abigail.",h="Marshal Ryan liegt im Sterben und bittet Euch, sein Wappen zu Knight Commander Demar Brant zu bringen.",kw={"abigail","wappen","sterbewunsch","burg farholde","knight commander demar brant","marshal ryan","ryan"},sec={{t="Ryans letzte Worte",b="Als Ryans Augen trüb werden, spricht er von seiner Heimat und Abigail. Marshal Ryan gibt Euch sein Wappen und bittet Euch, Knight Commander Demar Brant zu warnen. Ihr bringt das Zeichen seines Ranges zur Burg Farholde, wo der Kommandant wartet."}},faq={{q="Wer liegt im Sterben?",a="Marshal Ryan liegt im Sterben, als er Euch bittet, sein Wappen zu Knight Commander Demar Brant zu bringen.",al={"sterbewunsch wer","marshal ryan"}},{q="Was möchte Ryan, dass ich tue?",a="Ryan bittet Euch, sein Wappen zu Knight Commander Demar Brant zu bringen und ihn zu warnen.",al={"ryans bitte","was mit wappen tun"}},{q="Wer ist Abigail?",a="Ryans letzte Worte erwähnen Abigail und sagen, er hätte nach Hause kommen sollen.",al={"abigail ryan","wer ist abigail"}},{q="Wohin soll ich das Wappen bringen?",a="Bringt Marshal Ryans Wappen zu Knight Commander Demar Brant in die Burg Farholde.",al={"wohin mit dem wappen","aufenthaltsort demar brant"}}},fp="10,132,19.218.0,13.89.0,29.78.0,15.68.0,26.75.0"}
P.entries["quest:94893"] = {n="Delivering Closure",s="Demar bittet Euch, Marshal Ryans Wappen zu Abigail Lawson nach Sturmwind zu bringen. Ryans Tod hinterlässt eine Botschaft für die Frau, die er einst heiraten wollte.",h="Demar bittet Euch, Marshal Ryans Wappen zu Abigail Lawson nach Sturmwind zu bringen.",kw={"abigail lawson","kathedralenplatz","abschluss finden","demar","burg farholde","marshal ryan","ryans wappen","sturmwind"},sec={{t="Eine Botschaft in Sturmwind",b="Abigail Lawson wartet auf dem Kathedralenplatz, und Ihr bringt ihr für Demar das Wappen von Marshal Ryan. Sie schloss sich Demar und Ryan nicht an, als sie Burg Farholde errichteten. Ryan und Abigail waren unterschiedlicher Meinung gewesen, doch Demar kennt den Grund nicht. Er glaubt, seine Anwesenheit wäre nicht willkommen, also muss das Wappen an seiner Stelle sprechen."},{t="Unausgesprochene Worte",b="Ryans Familie starb während der Orc-Invasion, und sein Pflichtgefühl im Kampf gegen die Horde schlug in Hass um. Demar drängte ihn einst, bei Demars Eltern in Sturmwind zu leben, doch Ryan lehnte ab. Er schwor, zu bleiben, bis er die Orcs aus seiner Heimat vertrieben hätte. Ryan und Abigail hatten seitdem nicht mehr miteinander gesprochen."},{t="Das Wappen erhalten",b="Als Ihr ihr das Wappen bringt, spricht Abigail über Ryans Weigerung, seine Heimat zu verlassen, und über ihr langes Schweigen. Sie nennt Demar einen Helden, warnt aber, dass Helden oft jene in ihrer Nähe in Gefahr bringen. Dann drückt sie Ryans Wappen an sich und nennt ihn einen Idioten."}},faq={{q="Wer ist Abigail Lawson?",a="Abigail Lawson war Marshal Ryans Verlobte. Sie lebt in Sturmwind und hatte sich Ryan und Demar in Burg Farholde nicht angeschlossen.",al={"wer ist abigail","ryans verlobte"}},{q="Wer bittet mich, Ryans Wappen zu bringen?",a="Demar bittet Euch, Marshal Ryans Wappen zu Abigail Lawson nach Sturmwind zu bringen. Er glaubt, sie würde seine Anwesenheit nicht willkommen heißen.",al={"wer hat mich geschickt","demars wappen","wer möchte, dass das wappen überbracht wird"}},{q="Warum blieb Ryan zurück?",a="Nachdem Ryans Familie während der Orc-Invasion getötet worden war, wurde aus seiner Pflicht gegenüber der Horde Hass. Er schwor, zu bleiben, bis er die Orcs aus seiner Heimat vertrieben hätte.",al={"warum ryan blieb","ryan und die orcs","seine familie"}},{q="Warum sprachen Abigail und Ryan nicht mehr miteinander?",a="Abigail und Ryan waren unterschiedlicher Meinung, doch Demar kennt die Einzelheiten nicht. Seitdem hatten sie nicht mehr miteinander gesprochen.",al={"warum sie nicht mehr miteinander sprachen","abigail und ryan","ihr streit"}},{q="Wozu dient Ryans Wappen?",a="Demar bittet Euch, Marshal Ryans Wappen zu Abigail Lawson auf dem Kathedralenplatz in Sturmwind zu bringen.",al={"marschallwappen","ryans wappen","was soll ich bringen"}}},fp="18,150,22.324.0,17.284.0,18.252.1,22.126.0,36.131.0,25.162.0,39.102.0,27.101.0"}
P.entries["quest:94894"] = {n="The Twilight Threat",s="Farholde bittet Sturmwind um Hilfe, da die Aktivitäten von Twilight's Hammer plötzlich zunehmen. Ihr bringt Bolvar Fordragon Beweise, doch die Allianz hat andere Kriege zu bedenken.",h="Farholde bittet Sturmwind um Hilfe, da die Aktivitäten von Twilight's Hammer plötzlich zunehmen.",kw={"bolvar fordragon","brant","farholde","horde","kilgar","flusslande","burg sturmwind","twilight's hammer"},ang={["faction:Alliance"]="Als Abenteurer der Allianz bringt Ihr Farholdes Beweise zu Bolvar Fordragon, während dessen Leute Hilfe gegen Twilight's Hammer und die Horde suchen."},sec={{t="Farholdes Bitte",b="Farholdes Leute wenden sich an Euch, nachdem Lady Amberhall von Euren Geschäften mit Twilight's Hammer erfahren hat. Ihr Feldzug begann, um die Horde aus ihrer Heimat zu vertreiben, doch die Aktivitäten der Kultisten haben stark zugenommen. Sie fürchten, Sturmwind werde ihre Bitten nicht erhören, bevor Farholde sich Feinden an zwei Fronten stellen muss. Ihr bringt Bolvar Fordragon in Burg Sturmwind Beweise."},{t="Sturmwinds Antwort",b="In Burg Sturmwind hört Bolvar Fordragon die Warnung aus Farholde. Er sagt, die Allianz befinde sich bereits in einem viel umfassenderen Krieg und könne ihre Kräfte nicht für die private Fehde eines Weilers einsetzen. Die Horde hat mehr Häuser niedergebrannt als jene in den Flusslanden. Bolvar sieht wenig Hoffnung, dass Brant seinen Stolz beiseitelegt und der Allianz seine Kavallerie zu Hilfe schickt."}},faq={{q="Wer bittet Sturmwind um Hilfe?",a="Farholde bittet Sturmwind um Hilfe, da die Aktivitäten von Twilight's Hammer zunehmen.",al={"wer bittet um hilfe","farholdes bitte","wer schickte mich"}},{q="Warum ist Farholde besorgt?",a="Farholde fürchtet, von Feinden an zwei Fronten überwältigt zu werden, wenn Sturmwind seine Bitten nicht erhört.",al={"was ist in farholde los","kultistenproblem","warum besorgt"}},{q="Welche Beweise bringe ich?",a="Ihr bringt Kilgar's Head zu Bolvar Fordragon in Burg Sturmwind.",al={"welche beweise","kilgars kopf","kopf überbringen"}},{q="Von wem hört Bolvar?",a="Bolvar Fordragon erhält Nachrichten aus Farholde, dessen Feldzug begann, die Horde aus seiner Heimat zu vertreiben.",al={"wer schickte die nachricht","bericht aus farholde","frage zu bolvar"}},{q="Warum kann Sturmwind Farholde nicht unterstützen?",a="Bolvar sagt, die Allianz kämpfe in viel größerem Maßstab und habe nicht die Mittel, Farholdes persönliche Fehde zu unterstützen.",al={"warum keine hilfe","unterstützung aus sturmwind","bolvar lehnt ab"}}},fp="19,175,15.357.0,18.365.1,30.69.0,24.100.0,25.62.0,27.105.0,37.120.0"}
P.entries["quest:94895"] = {n="Lost Shipping Crate",s="Friz Frazzlesparks Transportkiste ist im Hafen von Powderfuse in den Flusslanden verschwunden. Ihr Etikett warnt davor, sie ohne Aufsicht zu öffnen, und bittet Euch, sie zu Friz zurückzubringen.",h="Friz Frazzlesparks Transportkiste ist im Hafen von Powderfuse in den Flusslanden verschwunden.",kw={"etikett der kiste","karte der kiste","friz frazzlespark","verlorene transportkiste","hafen von powderfuse","flusslande","warnung"},sec={{t="Eine markierte Kiste",b="Eine Karte und eine Warnung kennzeichnen die Kiste, die Ihr durch die Flusslande tragt. Auf dem Etikett stehen Friz Frazzlespark und der Hafen von Powderfuse, und es bittet darum, die Kiste dorthin zurückzubringen, falls sie verloren geht. Ihr bringt sie zu ihrem Besitzer zurück."}},faq={{q="Wem gehört die Transportkiste?",a="Auf dem Etikett steht Friz Frazzlespark als Besitzer der Transportkiste.",al={"besitzer der kiste","wem gehört diese kiste","friz kiste"}},{q="Wohin soll ich die Kiste bringen?",a="Die Kiste soll zu Friz Frazzlespark im Hafen von Powderfuse in den Flusslanden zurückgebracht werden.",al={"wohin kiste zurückbringen","ziel der kiste","hafen von powderfuse"}},{q="Wovor warnt das Etikett?",a="Das Etikett warnt davor, die Kiste zu manipulieren, und besagt, dass sie nicht ohne Aufsicht geöffnet werden darf.",al={"warnung auf der kiste","darf ich sie öffnen","kiste öffnen"}},{q="Was ist auf der Karte der Kiste markiert?",a="Die Karte zeigt einen roten Kreis an einer südöstlichen Küste, nördlich eines schlecht gezeichneten Tempels, der von Wasser und geflügelten Kreaturen umgeben ist.",al={"karte der kiste","was ist auf der karte","roter kreis auf der karte"}}},fp="19,188,14.214.0,28.69.0,30.87.0,31.85.0,34.131.0"}
P.entries["quest:94896"] = {n="Aid For The Refugees",s="Nach dem Fall von Ban'aethal ist seinen Überlebenden kaum etwas geblieben, das sie ihr Eigen nennen können. Die Siedlung tief im Schattenwindwald begann mitten in der Nacht, in den Himmel zu stürzen, und die Gefahren halten die Flüchtlinge davon ab, ihre zurückgelassenen Besitztümer zu bergen.",h="Nach dem Fall von Ban'aethal ist seinen Überlebenden kaum etwas geblieben, das sie ihr Eigen nennen können.",kw={"aid for the refugees","ban'aethal","banaethal","besitztümer","ealaane","flüchtlinge","schattenwindwald"},sec={{t="Eine verzweifelte Bitte",b="Ealaane und die anderen Flüchtlinge flohen aus ihren Heimen tief im Schattenwindwald. Sie haben sich mit fast nichts versammelt und bitten Reisende, den Gefahren zu trotzen, die sie hinter sich gelassen haben."},{t="Die Katastrophe von Ban'aethal",b="Ban'aethal begann mitten in der Nacht, in den Himmel zu stürzen. Den Bewohnern blieben nur Augenblicke zur Flucht, und sie ließen ihre persönlichen Besitztümer zurück. Die umliegenden Wälder wurden feindselig und gefährlich."}},faq={{q="Wer ist Ealaane?",a="Ealaane floh mit anderen aus Ban'aethal, als ihre Siedlung einzustürzen begann. Sie bittet Reisende auf dem Weg zum Schattenwindwald, die in den Ruinen zurückgelassenen Besitztümer zu bergen.",al={"wer vergab aid for the refugees","questgeber aid for the refugees","ealaane"}},{q="Was geschah mit Ban'aethal?",a="Ban'aethal war eine Siedlung tief im Schattenwindwald. Ihre Bewohner flohen mitten in der Nacht, als eine plötzliche Katastrophe hereinbrach.",al={"was ist banaethal","wo ist banaethal","dorf ban aethal"}},{q="Warum mussten die Dorfbewohner Ban'aethal evakuieren?",a="Ban'aethal begann mitten in der Nacht, in den Himmel zu stürzen, und zwang seine Bewohner zur Flucht. Das Dorf und der umliegende Wald wurden zu gefährlich, um dort zu bleiben oder dorthin zurückzukehren.",al={"warum banaethal evakuieren","in den himmel stürzen","katastrophe von ban aethal"}},{q="Warum bitten die Dorfbewohner darum, ihre Besitztümer zu bergen?",a="Die Katastrophe brach plötzlich mitten in der Nacht herein und ließ den Dorfbewohnern kaum Zeit, mit ihren Besitztümern zu fliehen. Der Wald und die Ruinen sind nun zu gefährlich, weshalb sie auf Reisende angewiesen sind, um das Zurückgelassene zu bergen.",al={"warum besitztümer brauchen","zurückgelassene besitztümer","warum besitztümer bergen"}},{q="Was ist der Schattenwindwald?",a="Der Schattenwindwald ist das bewaldete Gebiet, in dem Ban'aethal stand. Seit die Katastrophe das Dorf auseinandergerissen hat, ist der Wald für gewöhnliche Leute äußerst gefährlich geworden.",al={"wo ist der schattenwindwald","geschichte des schattenwindwalds"}},{q="Können die Flüchtlinge in ihre Heime zurückkehren?",a="Nein. Ealaane sagt, der Schattenwindwald und die Ruinen von Ban'aethal seien zu gefährlich, als dass die Flüchtlinge auf eigene Faust zurückkehren könnten.",al={"können flüchtlinge zurückkehren","ist banaethal sicher"}}},fp="20,237,16.174.0,26.196.0,15.173.0,28.138.0,50.180.0,66.227.0,26.166.0,39.121.0"}
P.entries["quest:94897"] = {n="The Fate of a Loved One",s="Resaan ist seit über einer Woche aus den Ruinen von Ban'aethal fort, und sein Partner wartet auf Nachricht. Reisende auf dem Weg dorthin werden gebeten, ihn heimzubringen oder sein geliebtes Erbstück zurückzubringen.",h="Resaan ist seit über einer Woche aus den Ruinen von Ban'aethal fort, und sein Partner wartet auf Nachricht.",kw={"ban'aethal","erbstück","resaan","ruinen von ban'aethal","vorräte","the fate of a loved one"},sec={{t="Ein verzweifeltes Flehen",b="Resaans Partner fleht ihn an zu bleiben, als er sich auf die Rückkehr in die Ruinen von Ban'aethal vorbereitet. Doch er fühlt sich gedrängt, den Gefahren der Ruinen zu trotzen, um Vorräte zu beschaffen. Sein Partner bleibt zurück und wartet auf Nachricht."},{t="In den Ruinen verschollen",b="Mehr als eine Woche ist vergangen, seit Resaan aufgebrochen ist, weit länger, als eine rasche Rückkehr dauern sollte. Sein Partner bittet Reisende auf dem Weg nach Ban'aethal, die Ruinen zu durchsuchen. Falls Resaan lebt, bringt ihn heim. Falls ihm ein Unglück das Leben genommen hat, bergt sein Familienerbstück."}},faq={{q="Wer ist Resaan?",a="Resaan kehrte in die Ruinen von Ban'aethal zurück, um Vorräte zu beschaffen, obwohl sein Partner ihn angefleht hatte zu bleiben. Seit über einer Woche fehlt jede Nachricht, und sein Partner fürchtet das Schlimmste.",al={"wer ist resaan","wo ist resaan","resaan finden"}},{q="Was sind die Ruinen von Ban'aethal?",a="Die Ruinen von Ban'aethal sind der Ort, an dem Resaan nach Vorräten suchte. Sein Partner fürchtet, dass er dort allein womöglich keine Woche überlebt hat.",al={"was ist banaethal","geschichte der ruinen von banaethal","wo ist banaethal"}},{q="Warum kehrte Resaan nach Ban'aethal zurück?",a="Resaan kehrte nach Ban'aethal zurück, um Vorräte zu holen, obwohl sein Partner ihn angefleht hatte zu bleiben.",al={"warum kehrte resaan zurück","warum ist resaan in banaethal"}},{q="Was sollt Ihr dem Questgeber zurückbringen?",a="Resaans Partner bittet Reisende, ihn sicher heimzubringen, falls er noch lebt. Sollte er in den Ruinen umgekommen sein, bittet sein Partner um sein persönliches Erbstück als Andenken.",al={"was will der questgeber","was passiert wenn resaan tot ist"}},{q="Wie lange wird Resaan schon vermisst?",a="Resaan wird seit über einer Woche vermisst, seit er zu den Ruinen von Ban'aethal aufgebrochen ist. Die Gefahren dort lassen seinen Partner das Schlimmste befürchten.",al={"wie lange wird resaan vermisst","wie lange ist resaan schon fort"}},{q="Wer bietet diese Quest an?",a="Resaans trauernder Partner bittet vorbeikommende Reisende auf dem Weg nach Ban'aethal um Hilfe, verzweifelt bemüht zu erfahren, was aus ihm geworden ist.",al={"wer vergibt the fate of a loved one","the fate of a loved one questgeber"}}},fp="23,187,16.187.0,21.250.0,14.178.0,33.131.0,36.92.0,47.155.0,33.146.0,22.123.0"}
P.entries["quest:949"] = {n="Das Lager des Schattenhammers",s="An der Meistergleve im Süden der Dunkelküste sammeln sich Kultisten, während Späher der Allianz ihre Absichten ergründen. Eine Schale der Wahrsagung hat ihre Ritualstätte offenbart. Nun betretet Ihr die Ausgrabung, um zu erfahren, was der Schattenhammer unter der Erde sucht.",h="An der Meistergleve im Süden der Dunkelküste sammeln sich Kultisten, während Späher der Allianz ihre...",kw={"dunkelküste","die meistergleve","onu","schale der wahrsagung","lager des schattenhammers","twilight tome","schattenhammer"},ang={["class:Druid"]="Als Druide helft Ihr den Cenarion wardens, die Forschungen des Kults aufzudecken und zu verhindern, dass sie uralte, unter der Erde begrabene Wesen verderben.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr zu verhindern, dass die seltsamen Ausgrabungen des Kults das nördliche Kalimdor destabilisieren.",["race:NightElf"]="Als Nachtelf seht Ihr, wie der Schattenhammer das heilige Kalimdor unter den uralten Hainen der Dunkelküste entweiht."},sec={{t="Die Ausgrabung erkunden",b="Der Schattenhammer hat die Meistergleve zu einer Bedrohung gemacht. Eine Schale der Wahrsagung offenbarte die Befestigungen der Kultisten. Ihr betretet ihr Lager, um ihre Pläne zu ergründen, bevor die Allianz ihre Verteidigung vorbereiten kann."},{t="Der illustrierte Foliant",b="Im nördlichen Lager der Kultisten liegt ein uralter Foliant voller verstörender Bilder. Seine von Hand bedruckten Seiten offenbaren, dass der Schattenhammer das kolossale Wesen untersucht, das unter der Erde begraben liegt."}},faq={{q="Was ist das Ziel der Quest „Das Lager des Schattenhammers“?",a="Ihr betretet das Lager des Schattenhammers nahe der Meistergleve im Süden der Dunkelküste, um einen Hinweis auf die Beweggründe des Kults zu finden: ein von Hand gedrucktes Ritualbuch.",al={"lager des schattenhammers questziel","was tun im lager des schattenhammers"}},{q="Wer schickt Euch los, um das Lager zu untersuchen?",a="Die Schale der Wahrsagung am Rundblick oberhalb der Meistergleve schickt Euch zur Untersuchung los. Ihr setzt die Nachforschungen fort, die für den uralten Beschützer Onu begonnen wurden.",al={"wer vergibt das lager des schattenhammers","lager des schattenhammers questgeber"}},{q="Wo im Lager findet sich der Hinweis?",a="Der Twilight Tome liegt im nördlichen Teil des Lagers. Andere Folianten können Schutzmagie gegen Eindringlinge entfesseln.",al={"wo ist das buch","twilight tome fundort","hinweis im lager des schattenhammers finden"}},{q="Warum ist der Schattenhammer an der Meistergleve?",a="Die Kultisten suchen nach den dunklen Mächten der Old Gods und ihrer Diener. Um den gewaltigen versteinerten Kadaver, den die riesige Steinklinge festnagelt, graben sie, um das dort verbliebene uralte Böse zu untersuchen oder zu erwecken.",al={"warum sind kultisten an der meistergleve","schattenhammer dunkelküste absicht"}},{q="Was geschieht, nachdem der Foliant gefunden wurde?",a="Der Fund des Folianten führt zu Return to Onu. Ihr bringt die Schriften nach Norden zu dem uralten Treanten im Hain der Uralten.",al={"nächste quest nach dem lager des schattenhammers","wohin nach twilight tome"}}},fx={["8554815a"]={q="Warum weist Euch die Scrying Bowl an, das Lager zu untersuchen?",a="Onus Wahrsageschale enthüllt, dass sich Kultisten von Twilight's Hammer um die Meistergleve versammelt haben, wo vor langer Zeit ein uralter „alter Herr“ fiel. Was sie dort bezwecken, ist unbekannt, doch Onu ist sicher, dass es etwas Finsteres sein muss. Bevor er und die Verteidiger des Hains einen Plan schmieden können, brauchen sie etwas aus dem Lager, das die Absichten des Kults enthüllt.",al={"warum the twilight camp untersuchen","scrying bowl zweck","warum twilight camp durchsuchen"}}},fp="17,240,15.204.0,20.195.1,44.149.0,38.146.0,36.119.0,52.204.0,36.121.0"}
P.entries["quest:94911"] = {n="Child of Nature",s="Ein anderer Skyborne sieht Potenzial in Euren Druidenkünsten und verweist Euch an Turak Runentotem in Donnerfels. Er kann Euch lehren, wie Ihr die Festung des Zirkels des Cenarius in der Mondlichtung erreicht.",h="Ein anderer Skyborne sieht Potenzial in Euren Druidenkünsten und verweist Euch an Turak Runentotem in...",kw={"zirkel des cenarius","child of nature","druide","mondlichtung","skyborne","donnerfels","turak runentotem"},ang={["class:Druid"]="Als Druide werdet Ihr an Turak Runentotem in Donnerfels verwiesen, der Euch lehren kann, wie Ihr den Zirkel des Cenarius in der Mondlichtung erreicht.",["race:Skyborne"]="Als Skyborne wird Euch gesagt, dass die Druiden des Zirkels des Cenarius Euch willkommen heißen und ihr Wissen mit Euch teilen werden."},sec={{t="Der Willkommensgruß eines Druiden",b="Euer Lehrer glaubt, dass die Druiden des Zirkels des Cenarius Euch willkommen heißen und ihr Wissen mit Euch teilen werden. Turak Runentotem in Donnerfels kann Euch zeigen, wie Ihr ihre Festung in der Mondlichtung erreicht."}},faq={{q="Mit wem soll ich sprechen?",a="Sprecht mit Turak Runentotem in Donnerfels. Er kann Euch lehren, wie Ihr die Mondlichtung erreicht.",al={"mit wem sprechen","turak runentotem","wer ist turak"}},{q="Wo ist die Festung des Zirkels des Cenarius?",a="Die Festung des Zirkels des Cenarius liegt in der Mondlichtung auf Kalimdor.",al={"wo ist der zirkel","standort des zirkels des cenarius","mondlichtung"}},{q="Warum werde ich in die Mondlichtung geschickt?",a="Die Druiden des Zirkels des Cenarius können ihr Wissen mit Euch teilen.",al={"warum mondlichtung","druidenkünste lernen","druidenausbildung"}}},fp="15,186,19.189.0,24.85.0,44.63.0,33.69.0"}
P.entries["quest:94912"] = {n="Child of Nature",s="In Sturmwind kann Euch Sheldras Moontree den Weg zur Mondlichtung zeigen. Dort teilen die Druiden des Zirkels des Cenarius ihre Weisheit mit einem Kind der Natur.",h="In Sturmwind kann Euch Sheldras Moontree den Weg zur Mondlichtung zeigen.",kw={"zirkel des cenarius","child of nature","druide","kalimdor","mondlichtung","sheldras moontree","skyborne","sturmwind"},ang={["class:Druid"]="Als Druide werdet Ihr zum Zirkel des Cenarius gewiesen, einem uralten Orden, dessen Mitglieder die druidischen Künste ausüben.",["race:Skyborne"]="Als Skyborne gehört Ihr zu den Ersten Eures Volkes, die in Azeroth eintreffen, und werdet willkommen geheißen."},sec={{t="Eine ferne Hochburg",b="Sheldras Moontree, ein Nachtelf in Sturmwind, kann Euch zeigen, wie Ihr die Mondlichtung auf Kalimdor erreicht. Dort hat der Zirkel des Cenarius seine Hochburg. Er ist ein uralter Orden von Naturkundigen und Druiden, der Euch viel lehren kann."}},faq={{q="Wer ist Sheldras Moontree?",a="Sheldras Moontree ist ein Nachtelf in Sturmwind, der Euch zeigen kann, wie Ihr die Mondlichtung erreicht.",al={"sheldras","nachtelf in sturmwind","wer lehrt mich den weg zur mondlichtung"}},{q="Was ist der Zirkel des Cenarius?",a="Der Zirkel des Cenarius ist ein uralter Orden von Naturkundigen und Anhängern der druidischen Künste.",al={"zirkel des cenarius","druidenorden","zirkel der natur"}},{q="Wo liegt die Hochburg des Zirkels des Cenarius?",a="Der Zirkel des Cenarius hat seine Hochburg in der Mondlichtung auf Kalimdor.",al={"hochburg des zirkels des cenarius","wo ist die mondlichtung","mondlichtung"}},{q="Was kann ich vom Zirkel des Cenarius lernen?",a="Die Druiden des Zirkels des Cenarius haben viel Weisheit mit Euch zu teilen.",al={"lehren des zirkels des cenarius","was können sie lehren","weisheit der druiden"}}},fp="15,149,16.215.0,25.86.0,28.93.0,42.66.0,42.66.0"}
P.entries["quest:94914"] = {n="Mondlichtung",s="Euer Lehrer öffnet einen Weg zur Mondlichtung, wo Dendrite Sternenschauer auf Euch wartet. Dort könnt Ihr mit ihm über den Weg sprechen, den Ihr eingeschlagen habt.",h="Euer Lehrer öffnet einen Weg zur Mondlichtung, wo Dendrite Sternenschauer auf Euch wartet.",kw={"bärengestalt","dendrite sternenschauer","druide","hüter remulos","mondlichtung","nachthafen","teleportieren"},ang={["class:Druid"]="Als Druide heißt Euch Euer Lehrer in der Mondlichtung willkommen und lehrt Euch einen Zauber, mit dem Ihr dorthin reisen könnt."},sec={{t="Eine erste Lektion",b="Euer Lehrer heißt Druiden in der Mondlichtung willkommen. Hüter Remulos wacht über jene, die dort rasten. Ihr erhaltet Teleportieren: Mondlichtung, einen Zauber, der Euch dorthin bringt, wenn Ihr Wissen oder Trost sucht. Eure erste Lektion besteht darin, mit Dendrite Sternenschauer in Nachthafen über den Weg zu sprechen, dem Ihr nun folgt."},{t="Die Bärengestalt",b="Dendrite Sternenschauer erkennt, dass Ihr die Bärengestalt bereits gemeistert habt. Er sieht Euch auf einem guten Weg."}},faq={{q="Mit wem sollte ich in der Mondlichtung sprechen?",a="Sprecht mit Dendrite Sternenschauer in Nachthafen über den Weg, auf dem Ihr Euch befindet.",al={"mit wem sprechen","dendrite sternenschauer","nachthafen druide"}},{q="Wie gelange ich zur Mondlichtung?",a="Euer Lehrer gibt Euch Teleportieren: Mondlichtung, einen Zauber, der Euch dorthin bringt.",al={"mondlichtung teleportieren","wie mondlichtung erreichen","teleportationszauber"}},{q="Wer wacht über die Druiden in der Mondlichtung?",a="Hüter Remulos wacht über Druiden, die in der Mondlichtung rasten.",al={"hüter remulos","mondlichtung wächter","wer bewacht mondlichtung"}},{q="Was sagt Dendrite über meine Fortschritte?",a="Dendrite erkennt, dass Ihr die Bärengestalt bereits gemeistert habt.",al={"bärengestalt","bärengestalt gemeistert","dendrites antwort"}}},fp="9,132,14.290.0,13.112.1,35.70.0,26.75.0,37.57.0,41.72.0"}
P.entries["quest:94923"] = {n="Hats Off",s="Robbie bittet Euch, den Geburtstagshut zu finden, den er am Fluss nahe den Murlocs verloren hat. Er fürchtet, dass seine Familie erfährt, dass er dort war.",h="Robbie bittet Euch, den Geburtstagshut zu finden, den er am Fluss nahe den Murlocs verloren hat.",kw={"geburtstagshut","ellie","hut","verlorener hut","murlocs","fluss","robbie"},sec={{t="Ein verlorener Hut",b="Robbie verlor den Hut, den seine Schwester ihm zum Geburtstag geschenkt hatte, als er am Fluss spielte. Er darf sich den Murlocs nicht nähern und kann daher weder seinen Vater noch Ellie um Hilfe bitten. Er vermutet, dass einer der Murlocs den Hut gefunden hat. Ihr sollt irgendwo am Fluss danach suchen."}},faq={{q="Wer ist Robbie?",a="Robbie ist ein Junge, der den Geburtstagshut verlor, den seine Schwester ihm schenkte, als er am Fluss spielte.",al={"robbie","wer ist robbie"}},{q="Was hat Robbie verloren?",a="Robbie verlor einen Hut, den seine Schwester ihm zum Geburtstag schenkte.",al={"robbies hut","verlorener hut"}},{q="Wo hat Robbie seinen Hut verloren?",a="Robbie verlor seinen Hut, als er im Fluss spielte, und bittet Euch, irgendwo am Fluss nahe den Murlocs danach zu suchen.",al={"fundort des huts","wo ist der hut"}},{q="Warum kann Robbie seine Familie nicht um Hilfe bitten?",a="Robbie darf sich den Murlocs nicht nähern. Wenn er seinen Vater oder Ellie um Hilfe bittet, würde das verraten, wo er gewesen ist.",al={"warum nicht papa fragen","warum verheimlichen"}},{q="Weiß Robbie, ob ein Murloc den Hut genommen hat?",a="Robbie vermutet, dass einer der Murlocs seinen Hut gefunden und behalten hat.",al={"murloc-hut","haben die murlocs ihn genommen"}}},fp="8,125,10.268.0,14.89.0,21.55.0,30.111.0,41.111.0,42.62.0"}
P.entries["quest:94946"] = {n="The Magical City of Dalaran",s="Ein Magier in Valanaar schickt Euch von der Insel Zephras nach Dalaran, wo mehrere Magier die Ankunft Eures Volkes erwarten. Die Stadt bietet einen Ausgangspunkt, um Azeroth zu erkunden, doch die Länder jenseits davon können ohne Vorbereitung und Erfahrung gefährlich sein.",h="Ein Magier in Valanaar schickt Euch von der Insel Zephras nach Dalaran, wo mehrere Magier die Ankunft Eures...",kw={"kult","dalaran","danaaris stargale","magier","himmelsboot","valanaar","insel zephras"},ang={["race:Skyborne"]="Als Skyborne reist Ihr von der Insel Zephras zu den Magiern, die in Dalaran die Ankunft Eures Volkes erwarten."},sec={{t="Ankunft in Dalaran",b="Die jüngsten Ereignisse mit dem Kult halten den Sprecher vorerst in Valanaar. Mehrere Magier warten in Dalaran auf Euer Volk, also werdet Ihr zum Dock außerhalb der Herberge geschickt. Dort geht Ihr an Bord eines Himmelsboots mit Ziel Dalaran.\n\nSprecht nach Eurer Ankunft mit Danaaris Stargale. Euer Volk richtet sich noch in der Stadt ein, und das Land jenseits ihrer sicheren Grenzen kann sich als gefährlich erweisen."}},faq={{q="Wer wartet in Dalaran?",a="Mehrere Magier erwarten die Ankunft Eures Volkes in Dalaran. Wenn Ihr die Stadt erreicht, sollt Ihr mit Danaaris Stargale sprechen.",al={"magier in dalaran","wer ist in dalaran","dalarans magier"}},{q="Von wo reise ich ab?",a="Ihr reist von der Insel Zephras nach Dalaran, an Bord des Himmelsboots am Dock außerhalb der Herberge.",al={"wie nach dalaran gelangen","von zephras","himmelsboot"}},{q="Warum bleibt der Sprecher in Valanaar?",a="Die jüngsten Ereignisse mit dem Kult haben die Pläne des Sprechers geändert, weshalb er eine Zeit lang in Valanaar bleiben will.",al={"warum in valanaar bleiben","kult änderte pläne","magier in valanaar"}},{q="Ist es außerhalb von Dalaran sicher?",a="Das Land jenseits von Dalaran kann ohne angemessene Vorbereitung und Erfahrung gefährlich sein.",al={"außerhalb dalarans sicher","gefahr nahe dalaran","dalarans umland"}}},fp="27,238,18.368.0,26.125.0,23.96.0,39.105.0,27.83.0"}
P.entries["quest:94947"] = {n="Welcome to Azeroth",s="Ihr erreicht Sturmwind durch das Skyborne-Portal und werdet vom Regenten der Stadt willkommen geheißen. Hochlord Bolvar Fordragon gewährt Euch die Erlaubnis, durch die Länder der Allianz zu reisen.",h="Ihr erreicht Sturmwind durch das Skyborne-Portal und werdet vom Regenten der Stadt willkommen geheißen.",kw={"bolvar fordragon","hochelf","der hohe orden","kirin tor","portal","skyborne","burg sturmwind","welcome to azeroth"},ang={["faction:Alliance"]="Hochlord Bolvar Fordragon heißt den Hohen Orden im Namen von König Anduin Wrynn offiziell willkommen und gewährt seinen Mitgliedern die Erlaubnis, die Länder der Allianz frei zu durchqueren.",["race:Skyborne"]="Als Skyborne werdet Ihr bei Eurer Ankunft durch das Portal in Sturmwind willkommen geheißen und erhaltet freies Geleit durch das Gebiet der Allianz."},sec={{t="Ankunft in der Hauptstadt",b="Ihr tretet durch das Skyborne-Portal nach Sturmwind, der Hauptstadt der Menschen. Von dort führt Euch Euer Weg über die großen Straßen der Stadt zur Burg Sturmwind, wo die Regentschaft Eure Ankunft erwartet."},{t="Eine Audienz beim Regenten",b="Hochlord Bolvar Fordragon empfängt die eintreffenden Mitglieder des Hohen Ordens im Thronsaal. Ein Kurier der Kirin Tor hatte ihm ihre Ankunft angekündigt. Es ist einige Zeit her, seit Hochelfen durch die Hallen der Burg Sturmwind schritten, doch Bolvar heißt sie als Gäste willkommen und gewährt ihnen im Namen des Königs freies Geleit durch die Gebiete der Allianz."}},faq={{q="Worum geht es in dieser Quest?",a="Ihr erreicht Sturmwind durch das Skyborne-Portal und stellt Euch Hochlord Bolvar Fordragon in der Burg Sturmwind vor.",al={"was ist welcome to azeroth","welcome to azeroth quest"}},{q="Wer ist Bolvar Fordragon?",a="Hochlord Bolvar Fordragon regiert Sturmwind als Regent von der Burg Sturmwind aus. Er herrscht im Namen des jungen Königs Anduin Wrynn, während König Varian weiterhin vermisst wird.",al={"wer ist bolvar fordragon","regent von sturmwind"}},{q="Warum empfängt Bolvar die Skyborne?",a="Ein Bote der Kirin Tor teilte Bolvar Fordragon mit, dass Mitglieder des Hohen Ordens eintreffen würden. Er heißt sie als Gäste der Krone willkommen und gewährt ihnen die Erlaubnis, frei durch die Länder der Allianz zu reisen.",al={"warum sind skyborne in sturmwind","hochelfen sturmwind"}},{q="Was ist der Hohe Orden?",a="Der Hohe Orden ist die Gruppe, die mit den Hochelfen der Skyborne verbunden ist. Die Kirin Tor kündigten ihre Ankunft bei der Führung Sturmwinds an.",al={"wer ist der hohe orden","geschichte des hohen ordens"}},{q="Wohin führt das Skyborne-Portal?",a="Das Skyborne-Portal bringt Reisende direkt nach Sturmwind, der Hauptstadt der Menschen. Von dort können Neuankömmlinge zur Burg Sturmwind gehen, um eine Audienz bei der Krone zu erbitten.",al={"skyborne-portal ziel","wohin führt das portal"}},{q="Dürfen sich die Skyborne im gesamten Gebiet der Allianz bewegen?",a="Bolvar Fordragon heißt die Skyborne als Gäste des Königs willkommen und gewährt ihnen die Erlaubnis, ungehindert durch sämtliche Länder der Allianz zu reisen.",al={"gehören skyborne zur allianz","skyborne willkommen bei der allianz"}}},fp="18,159,22.196.0,27.336.0,25.120.0,24.159.0,37.190.0,23.130.0,36.163.0,55.129.0"}
P.entries["quest:94962"] = {n="Bloodmaster's Ring",s="Ein Kampf gegen Bonegnaw ist der nächste Wettstreit auf dem Weg zum Champion in Bloodmaster's Ring. Die Oger warten darauf zu sehen, ob Ihr ihnen einen sehenswerten Kampf liefern könnt.",h="Ein Kampf gegen Bonegnaw ist der nächste Wettstreit auf dem Weg zum Champion in Bloodmaster's Ring.",kw={"bloodmaster","bloodmaster's ring","bonegnaw","kampf","champion","oger"},sec={{t="Der nächste Kampf",b="Eure Siege haben Euch noch nicht zum Champion gemacht, und der Goblin des Rings hat einen weiteren Kampf im Sinn. Bonegnaw ist Euer Gegner, und der Goblin verspricht eine Überraschung. Die Oger sehen zu, und der nächste Kampf soll sie unterhalten."},{t="Nach dem Kampf",b="Der Goblin ist unzufrieden damit, wie der Kampf auf ihn wirkt. Die Oger scheinen jedoch unterhalten zu sein, und er warnt Euch davor, auf das Ergebnis stolz zu sein."}},faq={{q="Wer ist mein Gegner?",a="Bonegnaw ist Euer Gegner in Bloodmaster's Ring.",al={"kampf gegen bonegnaw","gegen wen kämpfe ich"}},{q="Bin ich schon ein Champion?",a="Der Goblin des Rings sagt, Eure Siege hätten Euch noch nicht zum Champion gemacht.",al={"bloodmaster champion","champion werden"}},{q="Wer sieht dem Kampf zu?",a="Oger sehen dem Kampf in Bloodmaster's Ring zu.",al={"oger sehen zu","wer ist unterhalten"}}},fp="18,170,13.226.0,15.151.1,19.52.0,20.66.0,26.54.0"}
P.entries["quest:94964"] = {n="Bloodmaster's Ring",s="Ein Ringansager ruft Euch zum Kampf gegen Mog’thar im Bloodmaster’s Ring. Das Publikum wartet auf den nächsten Herausforderer.",h="Ein Ringansager ruft Euch zum Kampf gegen Mog’thar im Bloodmaster’s Ring.",kw={"ansager","bloodmaster’s ring","herausforderer","publikum","mog’thar","ring"},sec={{t="Der nächste Herausforderer",b="Der Ansager hat das Publikum in Spannung gehalten und kündigt nun Mog’thar als nächsten Herausforderer an. Ihr werdet in den Bloodmaster’s Ring gerufen, während das Publikum gespannt darauf wartet, was geschieht."}},faq={{q="Gegen wen trete ich im Bloodmaster’s Ring an?",a="Ihr werdet zum Kampf gegen Mog’thar im Bloodmaster’s Ring gerufen.",al={"kampf gegen mog’thar","wer ist der nächste herausforderer","gegner im bloodmaster’s ring"}},{q="Was sagt der Ansager über Mog’thar?",a="Der Ansager sagt, Mog’thar sei kein Spaß.",al={"wer ist mog’thar","nächster herausforderer","ist mog’thar ein witz"}},{q="Warum werde ich in den Ring geschickt?",a="Der Ansager will die Spannung beim Publikum aufrechterhalten, indem er einen weiteren Herausforderer ankündigt.",al={"warum gegen mog’thar kämpfen","grund für den ringkampf","was will der ansager"}}},fp="18,123,18.181.0,42.62.0,45.41.0,34.91.0"}
P.entries["quest:94968"] = {n="Eye of Mugg",s="Krom'rosh schickt Euch in die Feste Krol'dok, denn der Stützpunkt des Twilight cult ist größer als erwartet. Er bittet Euch um einen Beweis für den Tod ihres Anführers.",h="Krom'rosh schickt Euch in die Feste Krol'dok, denn der Stützpunkt des Twilight cult ist größer als erwartet.",kw={"höhle","anführer des kults","auge von mugg","feste krol'dok","krom'rosh","opferungen","twilight cult"},sec={{t="Feste Krol'dok",b="Krom'rosh fürchtet, dass weitere Verbündete geopfert werden, wenn der Twilight cult diese Lande weiter verwüstet. Nur wenige, die die Höhle betraten, überlebten, und der Stützpunkt des Kults ist größer, als er glaubte. Nun sollt Ihr die Feste Krol'dok betreten und mit einem Beweis für den Tod des Anführers zurückkehren."}},faq={{q="Wer schickt mich in die Feste Krol'dok?",a="Krom'rosh schickt Euch in die Feste Krol'dok, um einen Beweis dafür zurückzubringen, dass der Anführer des Twilight cult tot ist.",al={"wer schickte mich","krom'roshs auftrag"}},{q="Was stimmt mit der Feste nicht?",a="Der Twilight cult hat einen größeren Stützpunkt als Krom'rosh erwartet hat, verwüstet die Lande und opfert Verbündete.",al={"was geschieht dort","problem mit dem twilight cult"}},{q="Warum will Krom'rosh, dass ich hineingehe?",a="Krom'rosh will den Kult aufhalten, bevor er die Lande weiter verwüsten und Verbündete opfern kann.",al={"warum hineingehen","warum die feste betreten"}},{q="Welchen Beweis verlangt Krom'rosh?",a="Er bittet um einen Beweis dafür, dass der Anführer des Twilight cult tot ist.",al={"benötigter beweis","was soll ich zurückbringen"}},{q="Haben viele überlebt, die die Höhle betraten?",a="Nur wenige, denen es gelang, die Höhle zu betreten, überlebten.",al={"überlebende der höhle","wer kam lebend heraus"}}},fp="11,150,19.268.0,46.105.0,32.119.0,36.98.0,34.58.0,38.43.0"}
P.entries["quest:94973"] = {n="Krol'dok Moulding",s="Ein nahe Rog'mar gefundenes Formstück scheint Teil eines Schlüssels zu sein. Vielleicht weiß jemand in der Siedlung, was es öffnet.",h="Ein nahe Rog'mar gefundenes Formstück scheint Teil eines Schlüssels zu sein.",kw={"schlüssel","krol'dok-formstück","form","formstück","rog'mar","festung"},sec={{t="Eine seltsame Form",b="Ihr habt ein Formstück, das für einen Schlüssel gemacht zu sein scheint. In Rog'mar weiß vielleicht jemand, wozu das Stück dient. Wenn es aus der Festung stammt, könnte es wichtig sein."}},faq={{q="Wozu dient das Formstück?",a="Das Formstück scheint für einen Schlüssel bestimmt zu sein.",al={"formstück","was ist diese form","schlüsselform"}},{q="Wer kann das Formstück identifizieren?",a="Jemand in Rog'mar weiß vielleicht etwas über die Form.",al={"wer weiß etwas über die form","nach der form fragen","wohin mit der form"}},{q="Warum könnte es wichtig sein?",a="Wenn das Formstück aus der Festung stammt, muss es wichtig sein.",al={"ist die form wichtig","festungsform","warum die form wichtig ist"}}},fp="17,108,15.151.0,25.37.0,30.44.0,20.61.0"}
P.entries["quest:94974"] = {n="Key Ingredients",s="Kreza Darkthorn braucht Leder und Eisen für eine Schlüsselgussform. Ihr sammelt die Materialien, während sie die Glut heiß hält.",h="Kreza Darkthorn braucht Leder und Eisen für eine Schlüsselgussform.",kw={"glut","iron bar","schlüssel","schlüsselzutaten","kreza darkthorn","gussform","thick leather"},sec={{t="Materialien für die Gussform",b="Kreza Darkthorn besitzt eine abgenutzte Gussform, aus der vielleicht ein Schlüssel gefertigt werden kann. Ihr bringt ihr vier Thick Leather und zwölf Iron Bar, während sie die Glut heiß hält. Die Gussform sollte halten, und Kreza ist bereit herauszufinden, was sich damit machen lässt."}},faq={{q="Was braucht Kreza?",a="Kreza bittet Euch, vier Thick Leather und zwölf Iron Bar zu bringen.",al={"welche materialien","schlüsselzutaten","was braucht kreza"}},{q="Wofür sind die Materialien?",a="Die Materialien werden gebraucht, um aus einer groben, abgenutzten Gussform einen Schlüssel zu fertigen.",al={"warum leder und eisen","wofür ein schlüssel","materialien für die gussform"}},{q="Wer hält die Glut heiß?",a="Kreza Darkthorn sagt, sie werde die Glut heiß halten, während Ihr die Materialien sammelt.",al={"wer hält die glut heiß","kreza glut","glut heiß"}},{q="Was sagt Kreza über die Gussform?",a="Kreza sagt, die Gussform sei grob und abgenutzt, könne aber vielleicht noch zur Fertigung eines Schlüssels verwendet werden.",al={"zustand der gussform","ist die gussform brauchbar","schlüsselgussform"}}},fp="15,115,26.225.0,21.63.0,27.67.0,30.81.0,39.82.0"}
P.entries["quest:94975"] = {n="A Token of Vengeance",s="Ein Verbündeter bittet Euch, den Twilight’s Hammer in einem Höhlennetz nahe der Feste Krol'dok aufzuspüren. Ihre Angriffe haben Euren Verbündeten geschadet und bedrohen das Land.",h="Ein Verbündeter bittet Euch, den Twilight’s Hammer in einem Höhlennetz nahe der Feste Krol'dok aufzuspüren.",kw={"ein zeichen der rache","ohren von kultisten","kultisten","verborgene höhle","feste krol'dok","twilight's hammer"},sec={{t="Die verborgenen Höhlen",b="Die Späher haben berichtet, dass sich Kultisten des Twilight’s Hammer unter dem zerklüfteten Boden nahe der Feste Krol'dok bewegen. Euer Verbündeter sagt, ihre Angriffe hätten Euren Verbündeten großen Schmerz zugefügt und die Kultisten würden das Land für sich beanspruchen. Ihr sollt ihr Versteck finden und fünfzehn Ohren von Kultisten als Zeichen der Rache zurückbringen."}},faq={{q="Wen suche ich?",a="Ihr sucht Kultisten des Twilight’s Hammer, die sich in einem Höhlennetz nahe der Feste Krol'dok verstecken.",al={"wer sind die kultisten","twilight hammer hier","ohren von kultisten"}},{q="Warum werden die Kultisten gejagt?",a="Der Auftraggeber sagt, die Kultisten hätten seinen Verbündeten Schmerz zugefügt und würden das Land für sich beanspruchen.",al={"warum rache","warum gegen sie kämpfen","was haben sie getan"}},{q="Was wissen die Späher?",a="Späher meldeten Bewegungen von Kultisten unter dem zerklüfteten Gelände, in einem verborgenen Höhlennetz im Norden.",al={"bericht der späher","wo sind die kultisten","bewegungen der kultisten"}},{q="Was soll ich zurückbringen?",a="Ihr sollt fünfzehn Cultist Ears vom Twilight’s Hammer bei der Feste Krol'dok sammeln.",al={"was soll ich sammeln","ohren quest","wie viele ohren"}}},fp="20,158,16.328.0,21.99.0,34.90.0,24.99.0,30.98.0"}
P.entries["quest:94978"] = {n="Taming the Beast",s="Quel'ana Quickgale lehrt Euch die Bindung zwischen Tier und Meister. Ihr beginnt damit, einen Windsong Crawler nahe den Gewässern von Zephras zu zähmen.",h="Quel'ana Quickgale lehrt Euch die Bindung zwischen Tier und Meister.",kw={"tiere zähmen","quel'ana quickgale","zähmerrute","taming the beast","valanaar","windsong crawler","zephras"},sec={{t="Die erste Bindung",b="Ihr habt die Zähmerrute und einen Windsong Crawler zu zähmen. Findet einen in der Nähe eines Gewässers und übt Eure Fähigkeiten. Bringt die Rute dann zu Quel'ana Quickgale in Valanaar zurück. Dieses Geschöpf ist Euer erster Schritt zur Meisterschaft."}},faq={{q="Was soll ich für Quel'ana zähmen?",a="Quel'ana bittet Euch, einen Windsong Crawler in der Nähe eines Gewässers auf Zephras zu zähmen.",al={"welches tier","zähmziel","crawler-quest"}},{q="Wozu dient die Zähmerrute?",a="Mit der Zähmerrute zähmt Ihr einen Windsong Crawler.",al={"wie die rute funktioniert","zähmwerkzeug","rutenquest"}},{q="Wo finde ich einen Windsong Crawler?",a="Windsong Crawlers leben in der Nähe von Gewässern auf Zephras.",al={"crawler-fundort","wo crawler","zephras tier"}},{q="Wer hat mir die Zähmerrute gegeben?",a="Quel'ana Quickgale gibt Euch die Zähmerrute in Valanaar.",al={"questgeber","wer ist quelana","quelana quickgale"}},{q="Warum lerne ich, ein Tier zu zähmen?",a="Die Bindung zwischen Tier und Meister kennenzulernen, ist der erste Schritt zur Meisterschaft in Eurer Klasse.",al={"warum crawler zähmen","tierbeherrschung","erstes zähmen"}}},fp="16,132,10.215.0,34.77.0,27.50.0,35.55.0,27.56.0,34.90.0"}
P.entries["quest:94979"] = {n="Taming the Beast",s="Im Böenbeerentiefland bittet Quel'ana Quickgale Euch, einen galestrider zu zähmen. Euer Können auf offenem Gelände bereitet Euch auf kommende Prüfungen vor.",h="Im Böenbeerentiefland bittet Quel'ana Quickgale Euch, einen galestrider zu zähmen.",kw={"galestrider","böenbeerentiefland","ornery galestrider","quel'ana quickgale","zähmerrute","taming the beast","valanaar","zephras"},sec={{t="Über die Ebenen",b="Ihr habt bereits gezeigt, dass Ihr den Kriecher des Flusses zähmen könnt. Nun gibt Quel'ana Quickgale Euch eine Zähmerrute und schickt Euch in die Tiefländer von Zephras. Dort läuft ein stolzer, geflügelter galestrider flink über die Ebenen. Gewinnt sein Vertrauen und übt Eure Fähigkeiten. Bringt die Rute dann zu Quel'ana in Valanaar zurück."}},faq={{q="Was soll ich für Quel'ana zähmen?",a="Quel'ana bittet Euch, einen Ornery Galestrider im Böenbeerentiefland zu zähmen.",al={"was zähmen","galestrider zähmen","welches wildtier"}},{q="Wo finde ich den galestrider?",a="Ihr findet den Ornery Galestrider im Böenbeerentiefland, in den Ebenen von Zephras.",al={"wo galestrider","galestrider fundort","wo tiefland"}},{q="Wozu dient die Zähmerrute?",a="Quel'ana gibt Euch die Zähmerrute, damit Ihr einen Ornery Galestrider zähmen könnt.",al={"zähmerrute verwenden","wozu die rute","wie wildtier zähmen"}},{q="Wer hat mir diesen Auftrag gegeben?",a="Quel'ana Quickgale in Valanaar bittet Euch, einen Ornery Galestrider zu zähmen und die Zähmerrute zurückzubringen.",al={"wer hat mich geschickt","wer ist quelana","quickgale"}}},fp="16,138,17.298.0,35.74.0,32.88.0,27.72.0,28.100.0"}
P.entries["quest:94980"] = {n="Krol'dok Moulding",s="Die Krol'dok-Gussform sieht aus, als gehöre sie zu einem Schlüssel. Vielleicht weiß jemand in Burg Farholde mehr darüber.",h="Die Krol'dok-Gussform sieht aus, als gehöre sie zu einem Schlüssel.",kw={"burg farholde","schlüssel","krol'dok-gussform","gussform"},sec={{t="Die Gussform eines Schlüssels",b="Ihr habt eine Gussform, die für einen Schlüssel bestimmt zu sein scheint. Vielleicht weiß jemand in Burg Farholde, wofür sie gedacht ist, und Ihr bringt sie dorthin, um mehr zu erfahren."}},faq={{q="Was ist die Krol'dok-Gussform?",a="Die Krol'dok-Gussform scheint für einen Schlüssel bestimmt zu sein.",al={"kroldok-gussform","krol'dok-gussform","was ist diese gussform"}},{q="Wer könnte etwas über die Gussform wissen?",a="Vielleicht weiß jemand in Burg Farholde etwas über die Gussform.",al={"wer kennt sich mit der gussform aus","gussform-experte","nach der gussform fragen"}},{q="Was passiert, wenn ich die Gussform hinbringe?",a="Die Person, zu der Ihr sie bringt, sagt, sie werde sehen, was sich damit machen lässt.",al={"ergebnis der gussform","was sagen sie","schlüsselgussform"}}},fp="17,107,13.146.0,30.46.0,31.50.0,39.71.0"}
P.entries["quest:94981"] = {n="Key Ingredients",s="Alphonse Dumas braucht Materialien, um aus einer groben Form einen Schlüssel zu fertigen. Ihr sollt ihm Thick Leather und Iron Bars bringen.",h="Alphonse Dumas braucht Materialien, um aus einer groben Form einen Schlüssel zu fertigen.",kw={"alphonse dumas","glut","iron bars","schlüssel","schlüsselzutaten","form","thick leather"},sec={{t="Materialien für den Schlüssel",b="Alphonse Dumas hält die Glut heiß, während Ihr alles Nötige sammelt. Die Form ist grob, doch mit den richtigen Materialien kann er vielleicht einen Schlüssel fertigen."}},faq={{q="Was braucht Alphonse?",a="Alphonse Dumas bittet Euch, vier Thick Leather und zwölf Iron Bars zu bringen.",al={"benötigte materialien","was bringen","schlüsselzutaten"}},{q="Was fertigt Alphonse an?",a="Alphonse hofft, aus einer groben Form mit den richtigen Materialien einen Schlüssel zu fertigen.",al={"was fertigt er an","wofür ist der schlüssel","schlüsselform"}},{q="Wohin bringe ich die Materialien?",a="Bringt Thick Leather und Iron Bars zu Alphonse Dumas.",al={"wer erhält die zutaten","wem die materialien bringen"}}},fp="15,126,21.141.0,24.73.0,24.80.0,30.56.0"}
P.entries["quest:94983"] = {n="Twilight Mementos",s="Sergeant Riftan schickt Euch nach Norden zur Feste Krol'dok, nachdem Kundschafter ein Versteck des Twilight's Hammer bestätigt haben. Er bittet Euch, Beweise für die Niederlage der Kultisten zurückzubringen.",h="Sergeant Riftan schickt Euch nach Norden zur Feste Krol'dok, nachdem Kundschafter ein Versteck des Twilight's...",kw={"höhle","armreifen der kultisten","versteck der kultisten","feste krol'dok","kundschafter","sergeant riftan","andenken des zwielichts","twilight's hammer"},sec={{t="Berichte der Kundschafter",b="Kundschafter haben Sergeant Riftan düstere Berichte über ein Versteck der Kultisten gebracht. Ihre Berichte bestätigen, was andere erzählt haben. Im Norden liegt eine Höhle, die von ihrer Umgebung verborgen wird, und Riftan glaubt, dass sie dem Kult einen Stützpunkt tief in den Bergen bietet. Er schickt Euch zur Feste Krol'dok, damit Ihr Beweise für die Niederlage der Kultisten des Twilight's Hammer zurückbringt."}},faq={{q="Wer schickt mich nach Norden?",a="Sergeant Riftan bittet Euch, die Kultisten des Twilight's Hammer bei der Feste Krol'dok aufzuspüren und mit Beweisen für ihre Niederlage zurückzukehren.",al={"wer hat mich geschickt","sergeant riftan"}},{q="Was haben die Kundschafter entdeckt?",a="Die Berichte der Kundschafter bestätigten die Meldungen über ein Versteck der Kultisten mit einer verborgenen Höhle im Norden.",al={"bericht der kundschafter","was haben sie entdeckt"}},{q="Wo befindet sich das Versteck?",a="Das Versteck liegt in einer Höhle im Norden, die von ihrer Umgebung verborgen wird. Riftan glaubt, dass sie ein Stützpunkt tief in den Bergen ist.",al={"kultistenhöhle","wo sind die kultisten"}},{q="Welche Beweise will Riftan?",a="Riftan bittet Euch, Beweise dafür zurückzubringen, dass die Kultisten bei der Feste Krol'dok besiegt wurden.",al={"welche beweise","beweise gegen kultisten"}},{q="Wer sind die Kultisten?",a="Sie sind Mitglieder des Twilight's Hammer, dessen Versteck durch die Berichte der Kundschafter bestätigt wurde.",al={"zwielichtkult","twilight's hammer"}}},fp="17,161,15.350.0,29.129.0,25.96.0,21.125.0,28.96.0,21.99.0"}
P.entries["quest:94992"] = {n="Rescue Roundup",s="Wheeler bittet Euch, sein verlorenes Pferd Biscuit zurück zur Wheeler's Grange zu bringen. Ihre Rückkehr bedeutet, dass der Betrieb wieder läuft.",h="Wheeler bittet Euch, sein verlorenes Pferd Biscuit zurück zur Wheeler's Grange zu bringen.",kw={"biscuit","demar","pferd","verlorenes pferd","rettungsaktion","stallgefährtinnen","wheeler's grange"},sec={{t="Biscuit kehrt zurück",b="Wheeler's verlorenes Pferd heißt Biscuit. Sie senkt den Kopf und stupst Euren Arm an. Ihr bringt sie zurück zur Wheeler's Grange. Wheeler ist froh, Biscuit wieder zu Hause zu haben, glaubt aber, dass das Pferd eine Weile allein sein wird. Die Grange ist wieder geöffnet."}},faq={{q="Wer ist Biscuit?",a="Biscuit ist Wheelers Pferd. Es ist verschwunden und muss zurück zur Wheeler's Grange gebracht werden.",al={"pferd biscuit","verlorenes pferd","wer ist biscuit"}},{q="Wohin muss Biscuit gebracht werden?",a="Biscuit muss zurück zur Wheeler's Grange gebracht werden.",al={"wohin pferd bringen","biscuit ort","ziel des pferdes"}},{q="Warum ist Wheeler dankbar?",a="Wheeler ist dankbar, weil Ihr Biscuit zurück zur Grange bringt.",al={"warum dank","biscuit gerettet","wheeler dank"}},{q="Ist Biscuit allein?",a="Wheeler sagt, Biscuit werde eine Weile allein sein, und hofft, einige ihrer Stallgefährtinnen zu finden.",al={"biscuit allein","wo stallgefährtinnen","andere pferde"}},{q="Ist Wheeler's Grange geöffnet?",a="Mit Biscuit zurück ist Wheeler's Grange wieder in Betrieb.",al={"grange geöffnet","wheeler betrieb","grange wieder geöffnet"}}},fp="14,125,15.260.0,15.95.0,30.53.0,24.65.0,17.90.0,25.56.0"}
P.entries["quest:94997"] = {n="Lingering Essence",s="Riftan bittet Euch, eine Tasche mit verfluchten Erinnerungsstücken zu Ashe Amberhall in Burg Farholde zu bringen. Er hofft, dass ihre Studien offenbaren, welche Energien in den Objekten stecken.",h="Riftan bittet Euch, eine Tasche mit verfluchten Erinnerungsstücken zu Ashe Amberhall in Burg Farholde zu...",kw={"ashe amberhall","kultisten","verfluchte erinnerungsstücke","energien","burg farholde","nachwirkende essenz","riftan","satchel of cursed mementos"},sec={{t="In Burg Farholde",b="In Burg Farholde nimmt Ashe Amberhall Euch die Tasche ab und erfährt, dass Riftan sie geschickt hat. Sie sagt, sein langer Kampf gegen die Kultisten lasse sie befürchten, dass Erschöpfung sein Urteilsvermögen trübt. Doch sie räumt ein, dass seine Bedenken begründet sein könnten, und widmet sich den Objekten."}},faq={{q="Wer bittet mich, die Tasche zu bringen?",a="Riftan bittet Euch, Satchel of Cursed Mementos zu Ashe Amberhall zu bringen.",al={"wer hat mich geschickt","riftans tasche","wer ist riftan"}},{q="Wer ist Ashe Amberhall?",a="Ashe Amberhall ist eine angesehene Gelehrte. Ihr Fachgebiet könnte ihr helfen, die Energien in den Objekten zu untersuchen.",al={"ashe wer","wer ist ashe","amberhall"}},{q="Wohin soll ich die Erinnerungsstücke bringen?",a="Bringt Satchel of Cursed Mementos zu Ashe Amberhall in Burg Farholde.",al={"wohin mit der tasche","burg farholde","ziel der tasche"}},{q="Was ist in der Tasche?",a="Die Tasche enthält verfluchte Erinnerungsstücke, und Riftan möchte, dass Ashe untersucht, welche Energien in ihnen stecken.",al={"was ist in der tasche","verfluchte erinnerungsstücke","tascheninhalt"}},{q="Warum möchte Riftan, dass Ashe sie untersucht?",a="Riftan hofft, dass Ashe durch ihre Studien herausfinden kann, welche Energien in den Objekten stecken.",al={"warum ashe","wozu ist die tasche","nachwirkende essenz"}},{q="Was hält Ashe von Riftans Bedenken?",a="Ashe befürchtet, dass die Erschöpfung durch Riftans langen Kampf gegen Kultisten seinen Verstand trüben könnte, sagt aber, dass seine Bedenken begründet sein könnten.",al={"vertraut ashe riftan","riftan erschöpft","ashes meinung"}}},fp="17,153,11.279.0,38.73.0,22.108.0,29.72.0,23.95.0,42.86.0,41.132.0"}
P.entries["quest:94998"] = {n="Curios of Curiosity",s="Ihr bringt Melanie Sable eine Tasche mit ungewöhnlichen Andenken. Ihre feine Verarbeitung könnte sie nützlich machen.",h="Ihr bringt Melanie Sable eine Tasche mit ungewöhnlichen Andenken.",kw={"verarbeitung","kuriositäten der neugier","melanie sable","andenken","überreste","tasche mit andenken"},sec={{t="Eine Tasche für Melanie",b="Jemand, der die Andenken untersucht hat, schickt Euch mit der Tasche zu Melanie Sable. Die Gegenstände seien sicher, doch ihre Herkunft sei unbekannt. Ihre Verarbeitung ist ungewöhnlich, und Melanie könnte eine Verwendung für sie finden."}},faq={{q="Wem soll ich die Andenken bringen?",a="Bringt Melanie Sable die Tasche mit den Andenken, wie die untersuchende Person Euch aufträgt.",al={"wohin mit der tasche","wer ist melanie sable"}},{q="Was sind das für Andenken?",a="Sie sind Überreste von etwas, doch die untersuchende Person weiß nicht genau, wovon.",al={"was ist in der tasche","was sind das für kuriositäten"}},{q="Warum sind die Andenken ungewöhnlich?",a="Ihre Verarbeitung wird als einzigartig und kunstvoll beschrieben.",al={"was ist daran besonders","verarbeitung der kuriositäten"}},{q="Sind die Andenken sicher?",a="Die untersuchende Person bittet Euch, Melanie zu sagen, dass die Andenken sicher sind.",al={"ist die tasche sicher","sind sie gefährlich"}}},fp="19,104,21.217.0,34.68.0,22.76.0,29.63.0,22.65.0"}
P.entries["quest:95"] = {n="Svens Rache",s="In Svens Rache treibt Trauer Sven Yorgen von seinem zerstörten Hof im südlichen Dämmerwald fort, um die Mörder zu jagen. Nun lagert er in den westlichen Hügeln und bittet Reisende, zum Gehöft zurückzukehren, wo ein Fremder etwas nahe der Scheune vergraben hat.",h="In Svens Rache treibt Trauer Sven Yorgen von seinem zerstörten Hof im südlichen Dämmerwald fort, um die...",kw={"dunkle reiter","gebirgspass der totenwinde","dämmerwald","haufen lockerer erde","baumstumpf","sven yorgen","svens rache","yorgens bauernhof"},ang={["class:Paladin"]="Als Paladin seht Ihr das Abschlachten Unschuldiger durch Mächte aus dem Gebirgspass der Totenwinde als einen Ruf nach Gerechtigkeit für die Toten.",["faction:Alliance"]="Das Abschlachten der Familie Yorgen zeigt, wie weit dunkle Mächte im abgeschiedenen Dämmerwald reichen, wo Patrouillen der Armee von Sturmwind selten sind."},sec={{t="Tragödie auf dem Gehöft",b="Verhüllte Dunkle Reiter kamen aus dem Gebirgspass der Totenwinde und griffen Sven Yorgens Hof im südöstlichen Dämmerwald an. Sven war fort, und sie töteten seine Familie. Als er zum Ort des Gemetzels zurückkehrte, sah er eine unbekannte Gestalt nahe der Scheune herumschleichen und hastig etwas vergraben. Sven ließ den Gegenstand verborgen und brach auf, um die Mörder zu jagen."},{t="Verborgene Geheimnisse",b="Sven Yorgen lagert in den westlichen Hügeln, von Zorn verzehrt, und sucht Hilfe für die Rückkehr zu seinem Gehöft. Zwischen dem Bauernhaus und der zerstörten Scheune kennzeichnet ein Haufen lockerer Erde hinter einem alten Baumstumpf die Stelle, an der hastig etwas vergraben wurde. Es zu bergen könnte erklären, warum die schattenhaften Reiter einen friedlichen Bauern aus dem Dämmerwald ins Visier nahmen."}},faq={{q="Wer ist Sven Yorgen?",a="Sven Yorgen war ein Bauer im südöstlichen Dämmerwald nahe der Grenze zum Gebirgspass der Totenwinde. Nachdem verhüllte Reiter seine Familie ermordet hatten, verließ er seinen Hof und wurde zu einem Einsiedler, der auf Rache sinnt.",al={"wer ist sven","svens geschichte","svens vorgeschichte"}},{q="Was geschah mit Svens Hof?",a="Dunkle Reiter aus dem Gebirgspass der Totenwinde griffen Sven Yorgens Gehöft an und töteten seine Familie. Das Anwesen lag in Trümmern, während Sven fort war.",al={"tragödie auf yorgens bauernhof","was geschah mit svens hof","warum ist svens hof zerstört"}},{q="Wer hat etwas hinter der Scheune vergraben?",a="Nach dem Massaker sah Sven eine schattenhafte Gestalt etwas nahe seiner Scheune vergraben. Er verfolgte die Dunklen Reiter, bevor er den Fremden stellen oder das Vergrabene freilegen konnte.",al={"wer hat den gegenstand vergraben","schattenhafte gestalt auf svens hof","wer hat den erdhaufen aufgeschüttet"}},{q="Wo liegt der Haufen lockerer Erde?",a="Auf Yorgens Bauernhof im südöstlichen Dämmerwald liegt ein Haufen lockerer Erde hinter einem alten Baumstumpf zwischen der Scheune und dem zerstörten Bauernhaus.",al={"wo ist der erdhaufen","standort des erdhaufens","wo ist der baumstumpf"}},{q="Wer sind die Dunklen Reiter?",a="Die Dunklen Reiter sind verhüllte Reiter, die aus dem Gebirgspass der Totenwinde kommen. Ihre Herkunft ist unbekannt, doch ihre Angriffe im Dämmerwald bringen Tod und Verwüstung.",al={"was sind die dunklen reiter","geschichte der dunklen reiter","reiter aus dem gebirgspass der totenwinde"}},{q="Warum hat Sven den vergrabenen Gegenstand nicht selbst ausgegraben?",a="Sven war von Trauer überwältigt, als er heimkehrte und eine Gestalt sah, die etwas vergrub. Er verfolgte sofort die sich zurückziehenden Dunklen Reiter und ließ den Gegenstand zurück.",al={"warum hat sven die erde nicht untersucht","warum ging sven fort"}}},fx={e064b97c={q="Warum möchte Sven Yorgen, dass der vergrabene Gegenstand geborgen wird?",a="Sven sucht Rache für das brutale Massaker an seiner Familie durch die mysteriösen Dunklen Reiter vom Gebirgspass der Totenwinde. Als er das Massaker entdeckte, sah er eine schattenhafte Gestalt, die hastig etwas bei seiner Scheune vergrub, bevor sie floh. Getrieben von Wut und dem Bedürfnis nach Antworten, glaubt Sven, dass das, was unter der Erde liegt, der Schlüssel dazu ist, aufzudecken, warum sein Hof ins Visier genommen wurde und wer bei der Zerstörung seiner Familie geholfen hat.",al={"warum will sven das","sven yorgen beweggrund","grund für sven rachequest"}}},fp="14,234,24.320.0,18.307.0,19.181.0,29.133.0,37.168.0,41.140.0,24.145.0,47.164.0"}
P.entries["quest:950"] = {n="Rückkehr zu Onu",s="Ihr bringt Onu in Dunkelküste eine herausgerissene Seite aus dem Twilight Tome. Mehr von den Schriften der Kultisten konntet Ihr ihrem Buch nicht entreißen, ohne den Verstand zu verlieren.",h="Ihr bringt Onu in Dunkelküste eine herausgerissene Seite aus dem Twilight Tome.",kw={"dunkelküste","der hain der uralten","irrsinniges gekritzel","old ones","onu","twilight tome","twilight's hammer"},ang={["class:Druid"]="Als Druide erkennt Ihr in der chaotischen, unnatürlichen Resonanz des Gekritzels einen Frevel an der natürlichen Ordnung, die Ihr gemeinsam mit Treants wie Onu schützt.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, die Aktivitäten des Kults entlang der Küste von Dunkelküste zu untersuchen und Nachtelfensiedlungen wie Auberdine vor verborgenen Bedrohungen zu schützen.",["race:NightElf"]="Als Nachtelf seht Ihr in der Entweihung der Küsten von Dunkelküste durch die Kultisten eine Bedrohung für das Gleichgewicht, das die Ancients of Lore bewahren. Onus Warnungen treffen die Kaldorei tief."},sec={{t="Ein Blick in den Wahnsinn",b="Der Twilight Tome überwältigt jeden, der ihn zu lesen versucht. Seine Worte verschwimmen auf der Seite, und seine kunstvollen Verzierungen winden sich zu grotesken Gestalten. Ihr reißt eine Seite voller Gekritzel heraus, bevor die Anstrengung Schwindel auslöst."},{t="Uralter Argwohn",b="Onu, der Ancient of Lore, erkennt eine seltsame Aura in der Seite, die Ihr ihm bringt. Ihre chaotische, urzeitliche Magie deutet auf uralte, schattenhafte Kräfte hin, die unter der Erde begraben liegen. Obwohl die Schrift schwer zu entziffern ist, zeigt sie, dass der Twilight's Hammer in Dunkelküste mehr als Banditentum betreibt."}},faq={{q="Was ist die Seite aus dem Twilight Tome?",a="Irrsinniges Gekritzel ist eine herausgerissene Seite aus dem Twilight Tome, dem heiligen Buch des Kults. Ihre sich wandelnde Schrift verursacht schwere geistige Qualen.",al={"irrsinniges gekritzel","was ist das gekritzel","seite aus dem twilight tome"}},{q="Wer ist Onu?",a="Onu ist ein Ancient of Lore im Hain der Uralten im Süden von Dunkelküste. Er ist ein betagter Wächter und Gelehrter, der Nachtelfen und Verbündete der Allianz im Kampf gegen die Verderbnis im Wald anleitet.",al={"wer ist onu","onu dunkelküste","treant onu"}},{q="Was erfährt Onu aus dem Gekritzel?",a="Onu spürt chaotische, urzeitliche Energie in der Seite und den Einfluss uralter, bösartiger Wesenheiten. Die Schriften deuten darauf hin, dass die Kultisten des Twilight's Hammer in ganz Dunkelküste nach Reliktstätten und verschütteten Mächten suchen.",al={"was hat onu entdeckt","bedeutung des gekritzels"}},{q="Warum ist der Twilight's Hammer in Dunkelküste?",a="Der Twilight's Hammer kam nach Dunkelküste, um verfallene Elfenstätten auszugraben und Spuren uralter Macht aufzudecken, die mit urzeitlicher Finsternis und den Old Gods verbunden ist. Das Chaos im Land hilft, ihre Riten zu verbergen.",al={"kultisten in dunkelküste","warum ist twilight's hammer hier"}},{q="Wohin führt diese Untersuchung als Nächstes?",a="Onu richtet seine Aufmerksamkeit auf die uralten elfischen Ruinen von Mathystra im Norden. Er weist Abenteurer an, die Relikte zu sichern, bevor die Kultisten sie an sich reißen können.",al={"welche quest kommt als nächstes","was kommt nach rückkehr zu onu"}},{q="Warum verursacht das Lesen des Folianten Schwindel?",a="Dunkle, wahnsinnig machende Magie erfüllt den Twilight Tome. Seine Glyphen verwirren den Geist der Sterblichen und verursachen Halluzinationen und Ohnmachtsanfälle, die Außenstehende daran hindern, seine Geheimnisse zu verstehen.",al={"warum schwindel beim folianten","wirkungen des twilight tome"}}},fp="13,134,22.216.0,18.276.1,46.130.0,11.190.0,39.209.0,42.194.0,40.157.1,42.166.0"}
P.entries["quest:95033"] = {n="On the Other Side",s="Tan'jani schickt Euch nach Camp Mojache in Feralas, damit Ihr Hexendoktor Uzer'i um Hilfe bittet. Uzer'i ist als Magiekundiger bekannt, aber auch ein Jäger.",h="Tan'jani schickt Euch nach Camp Mojache in Feralas, damit Ihr Hexendoktor Uzer'i um Hilfe bittet.",kw={"camp mojache","feralas","jäger","magie","auf der anderen seite","tan'jani","hexendoktor uzer'i"},sec={{t="Tan'janis Freund",b="Auf der anderen Seite von Feralas liegt Camp Mojache. Dort findet Ihr Hexendoktor Uzer'i, einen alten Freund von Tan'jani. Tan'jani sagt, Uzer'i wirke mit Magie, sei aber auch ein Jäger. Ihr sollt mit ihm sprechen und lasst die weiten Ebenen hinter Euch."}},faq={{q="Wer hat mich zu Uzer'i geschickt?",a="Tan'jani schickt Euch zu Hexendoktor Uzer'i, einem alten Freund.",al={"tan'jani hat mich geschickt","wer ist der alte tanjani"}},{q="Wo finde ich Uzer'i?",a="Hexendoktor Uzer'i ist in Camp Mojache in Feralas.",al={"uzer'is ort","wo ist der hexendoktor"}},{q="Warum soll ich zu Uzer'i gehen?",a="Tan'jani sagt, Uzer'i suche Hilfe, und bittet Euch, mit ihm zu sprechen.",al={"warum mit uzer'i sprechen","was möchte tanjani"}},{q="Was macht Uzer'i?",a="Hexendoktor Uzer'i wirkt mit Magie und ist auch ein Jäger.",al={"beruf von hexendoktor uzer'i","hexendoktor und jäger"}}},fp="17,137,17.228.0,22.57.0,24.50.0,30.72.0,20.58.0"}
P.entries["quest:95034"] = {n="The Debt",s="Lumina Windsinger im Grabmal berichtet von dem Angriff, bei dem Banon schwer verwundet wurde. Ihrem Bericht zufolge war es ein Worgen, der sie auf der Straße angriff.",h="Lumina Windsinger im Grabmal berichtet von dem Angriff, bei dem Banon schwer verwundet wurde.",kw={"banon","gnolle","lumina windsinger","angriff auf der straße","das grabmal","the debt","worgen"},sec={{t="Eine Wunde auf der Straße",b="Lumina Windsinger im Grabmal erzählt Euch, was auf der Straße geschah. Ein riesiger, wolfsähnlicher Worgen griff ihre Gruppe an und tötete ihre Wachen. Banon stellte sich zwischen die Kreatur und Lumina, die sie mit einem Zauber vertrieb. Da hatte Banon bereits schwere Bisswunden erlitten. Er drängte sie, ihn zurückzulassen, doch sie blieb, und die beiden humpelten weiter, bevor Gnolle sie fanden."},{t="Banons letzte Augenblicke",b="Banon im Grabmal wurde von vielen Gnollklingen durchbohrt, bevor er sich gegen Lumina wandte. Sie sah, dass er sie noch erkannte, obwohl er sich nicht beherrschen konnte. Lumina glaubt, dass der Worgen sein Schicksal besiegelt hat, und schwört, ihn zu töten, damit er keinem anderen Lebewesen denselben Schrecken zufügen kann."}},faq={{q="Wer griff Lumina und Banon auf der Straße an?",a="Ein riesiger, wolfsähnlicher Worgen griff Lumina und Banon auf der Straße an.",al={"was griff sie an","worgenangriff","angreifer auf der straße"}},{q="Was geschah mit den Wachen?",a="Der Worgen tötete die Wachen, die Lumina und Banon begleiteten.",al={"schicksal der wachen","was geschah mit den wachen","wachen auf der straße"}},{q="Wie vertrieb Lumina den Worgen?",a="Lumina gelang es, einen Zauber zu wirken, der den Worgen erschreckte und in die Flucht schlug.",al={"wie floh der worgen","luminas zauber","was erschreckte ihn"}},{q="Warum wurde Banon gebissen?",a="Banon warf sich dem Worgen in den Weg, um Lumina zu schützen, und die Kreatur fügte ihm schwere Bisswunden zu.",al={"banons bisswunde","wie wurde banon verletzt","was geschah mit banon"}},{q="Wo erzählt Euch Lumina, was geschehen ist?",a="Lumina Windsinger erzählt Euch ihre Geschichte im Grabmal.",al={"wo ist lumina zu finden","luminas aufenthaltsort","das grabmal"}}},fp="8,160,19.344.0,20.277.1,42.64.0,28.66.0,36.78.0,21.91.0,41.57.0"}
P.entries["quest:95036"] = {n="A Moon-Kissed Blade",s="Trevan warnt Euch, dass Worgen den Silberwald bedrohen. Old Fire-Eye widersetzt sich dem Tod durch unbekannte Magie, und Trevan bittet Euch herauszufinden, was für eine besondere Klinge benötigt wird.",h="Trevan warnt Euch, dass Worgen den Silberwald bedrohen.",kw={"a moon-kissed blade","materialien für die klinge","old fire-eye","silberwald","besondere waffe","trevan","worgen"},sec={{t="Die Liste eines Schmieds",b="Old Fire-Eye ist der Worgen, der Trevan und seine Gefährten angegriffen hat. Trevan wird Euch eine Liste mit Materialien für eine Waffe gegen ihn geben. Die Materialien sind gesammelt, und Trevan glaubt, einen Schmied zu kennen, der die Klinge anfertigen kann."}},faq={{q="Wer ist Old Fire-Eye?",a="Old Fire-Eye ist der größte und bösartigste der Worgen. Er hat Trevan und seine Gefährten angegriffen.",al={"old fire-eye","fire eye worgen","großer worgen"}},{q="Warum kehrt Old Fire-Eye immer wieder zurück?",a="Unbekannte Magie verhindert, dass Old Fire-Eye tot bleibt.",al={"warum stirbt fire-eye nicht","old fire eye magie","worgen der nicht tot bleibt"}},{q="Was braucht Trevan von mir?",a="Trevan wird Euch eine Liste mit Materialien geben, die zum Schmieden einer besonderen Waffe benötigt werden.",al={"was will trevan","trevans liste","materialien für die klinge"}},{q="Warum wird eine besondere Klinge benötigt?",a="Old Fire-Eye widersetzt sich dem Tod durch unbekannte Magie. Trevan sagt, dass eine besondere Waffe benötigt wird, um ihn zur Strecke zu bringen.",al={"moon kissed blade warum","waffe gegen old fire-eye","fire eye töten"}},{q="Wer kann die Klinge anfertigen?",a="Trevan glaubt, einen Schmied zu kennen, der die Klinge anfertigen kann.",al={"schmied für die klinge","wer fertigt moon blade","klingenschmied"}}},fp="19,170,14.223.0,20.93.0,39.51.0,30.74.0,30.105.0,24.55.0"}
P.entries["quest:95041"] = {n="Data Hoarders",s="Vor Gnomeregan sucht Jemma Quikswitch im Schnee nach verlorenen Lochkarten. Die im Exil lebende Gnomin wohnt in Eisenschmiede, und die Karten enthalten die Archive ihrer Familie, von U-Boot-Entwürfen bis hin zu Familienrezepten. Ohne sie bleiben die Aufzeichnungen, die sie noch hat, unlesbar.",h="Vor Gnomeregan sucht Jemma Quikswitch im Schnee nach verlorenen Lochkarten.",kw={"data hoarders","dun morogh","gnomeregan","eisenschmiede","jemma quikswitch","lochkarten","zweiter krieg","u-boot-rumpf"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr vertriebenen Gnomen helfen, technische Aufzeichnungen aus Kriegszeiten und das darin enthaltene Wissen der Allianz zu bewahren.",["profession:Cooking"]="Als Koch wisst Ihr Oma Quikswitchs Chilirezept zwischen den technischen Aufzeichnungen zu schätzen.",["profession:Engineering"]="Als Ingenieur erkennt Ihr den Wert der U-Boot-Baupläne aus dem Zweiten Krieg und der arkanotechnischen Gleichungen auf diesen Karten.",["race:Gnome"]="Als Gnom könnt Ihr durch die Bergung der Lochkarten helfen, Erfindungen und Familienerinnerungen aus Eurer Heimat zu bewahren."},sec={{t="Hastige Suche im Schnee",b="Als Troggs in Gnomeregan einfielen und die Strahlenkatastrophe eintrat, flohen Tausende Gnome mit allem, was sie tragen konnten. Aus einer beschädigten Tasche fielen mehrere von Jemmas Karten in den Schnee rund um die gefallene Stadt. Ohne sie sind ihre verbliebenen Aufzeichnungen unverständliches Kauderwelsch, und das Wissen ihrer Familie droht verloren zu gehen."},{t="Gleichungen und Chili",b="Die Archive der Familie Quikswitch enthalten arkanotechnische Feldgleichungen und Baupläne für U-Boot-Rümpfe aus dem Zweiten Krieg. Sie bewahren auch Oma Quikswitchs geheimes Chilirezept. Für Flüchtlinge in Eisenschmiede zählen die Annehmlichkeiten der Heimat ebenso viel wie technische Wunderwerke."}},faq={{q="Wer ist Jemma Quikswitch?",a="Jemma Quikswitch ist eine gnomische Geflüchtete, die dem Fall Gnomeregans entkam und nun in Eisenschmiede lebt.",al={"jemma quikswitch","wer vergibt data hoarders","questgeber data hoarders"}},{q="Welche Daten sind auf den verlorenen Karten gespeichert?",a="Die Lochkarten enthalten die Archive der Familie Quikswitch, darunter arkanotechnische Gleichungen, Baupläne für U-Boot-Rümpfe aus dem Zweiten Krieg und Oma Quikswitchs Chilirezept.",al={"was sind die lochkarten","was war auf den karten","quikswitch-archive"}},{q="Wo gingen die Datenkarten verloren?",a="Die Karten rutschten aus Jemmas Gepäck, als sie aus Gnomeregan floh. Sie liegen in Dun Morogh im Schnee direkt vor den Toren der Stadt.",al={"wo sind die karten","fundort der datenkarten","wo hat sie die karten verloren"}},{q="Warum kann Jemma die verbliebenen Karten ohne die fehlenden nicht lesen?",a="Jemma sagt, die Daten seien zu durcheinander, um sie ohne die fehlenden Lochkarten wiederherzustellen. Die Aufzeichnungen erklären nicht, wie die Karten diese Informationen kodieren oder ordnen.",al={"warum werden alle karten benötigt","durcheinandergeratene daten","lochkartendaten"}},{q="Welche Rolle spielten Gnome im Zweiten Krieg beim Einsatz von U-Booten?",a="Im Zweiten Krieg unterstützten Gnome die Allianz mit fortschrittlicher Ingenieurskunst. Sie entwarfen und steuerten Tauchboote, um den Seestreitkräften der Horde entgegenzutreten.",al={"gnomische u-boote zweiter krieg","entwürfe für u-boot-rümpfe"}},{q="Warum leben gnomische Flüchtlinge in Eisenschmiede?",a="Nachdem einfallende Troggs Gnomeregan zu Fall gebracht hatten und die Strahlenkatastrophe eingetreten war, flohen die überlebenden Gnome aus ihrer unterirdischen Heimat. König Magni Bronzebart bot ihnen Zuflucht in Eisenschmiede.",al={"warum sind gnome in eisenschmiede","gnome leben bei zwergen"}}},fp="13,256,22.294.0,19.259.0,24.95.0,38.177.0,34.125.0,66.158.0,65.158.0,45.172.0"}
P.entries["quest:95042"] = {n="Seeking the Kor Gem",s="Im Eschental sieht Ulric Frostveil Eure Suche nach einem Kor Gem als vertraute Arbeit für Zauberwirker der Allianz. Er weist Euch nach Norden zur Tiefschwarzen Grotte, wo die Naga die Edelsteine noch immer verwenden.",h="Im Eschental sieht Ulric Frostveil Eure Suche nach einem Kor Gem als vertraute Arbeit für Zauberwirker der...",kw={"eschental","tiefschwarze grotte","verlassene","kor gem","naga","ulric frostveil"},sec={{t="Ein Edelstein im Eschental",b="Ulric bittet Euch, ihm einen Kor Gem aus den Ruinen der Tiefschwarzen Grotte nördlich des Eschentals zu bringen. Die Naga dort unten verwenden die Edelsteine noch immer. Sie können magische Waffen und Werkzeuge verstärken, doch Ulric warnt Euch davor, allein aufzubrechen."},{t="Ulrics Interesse",b="Ulric Frostveil erkennt Verderbnis im Edelstein. Er sagt, er könne das Böse bannen, mit dem die Hexen der Naga ihn durchdrungen haben. Dann fragt er, ob Ihr ihm den Edelstein für seine akademischen Forschungen verkaufen würdet."}},faq={{q="Wer ist Ulric Frostveil?",a="Ulric Frostveil ist ein Verlassener im Eschental, der Euch bittet, ihm einen Kor Gem zu bringen.",al={"ulric frostveil","wer ist ulric","verlassener im eschental"}},{q="Wo finde ich einen Kor Gem?",a="Ulric weist Euch nach Norden zur Tiefschwarzen Grotte, wo die Naga noch immer Kor Gems verwenden.",al={"kor gem fundort","wo edelstein","tiefschwarze grotte edelstein"}},{q="Wofür werden Kor Gems verwendet?",a="Kor Gems können magische Waffen und Werkzeuge verstärken.",al={"kor gem verwendung","edelstein magie","was bewirkt kor gem"}},{q="Warum möchte Ulric einen Kor Gem?",a="Ulric bittet Euch, ihm einen Kor Gem zu bringen. Er sagt, er könnte für seine akademischen Forschungen von Wert sein.",al={"ulric will edelstein","warum edelstein","frostveil edelstein"}},{q="Wer verwendet noch Kor Gems?",a="Die Naga in der Tiefschwarzen Grotte verwenden noch immer Kor Gems.",al={"naga edelsteine","wer verwendet kor gems","tiefschwarze grotte naga"}}},fp="19,177,18.215.0,16.190.1,23.79.0,27.76.0,27.52.0,30.89.0,24.49.0"}
P.entries["quest:95059"] = {n="Frazzlespark's Crate",s="Ein Goblin hat eine Lieferung für Ritterkommandant Demar Brant auf Burg Farholde. Ihr sollt ihm Frazzlespark's Crate bringen.",h="Ein Goblin hat eine Lieferung für Ritterkommandant Demar Brant auf Burg Farholde.",kw={"kiste","demar brant","burg farholde","frazzlespark","frazzlesparks kiste","goblin-lieferung","ritterkommandant"},sec={{t="Eine Lieferung zur Burg",b="Frazzlespark schickt Euch nach Südwesten zur Burg Farholde, wo Ritterkommandant Demar Brant wartet. Die Kiste ist für ihn bestimmt, und der Goblin legt Wert darauf, seinen vollständigen Namen zu verwenden. Auf der Burg nennt Demar den Goblin ein Mittel zum Zweck, Teil der Geschäfte, die, wie er sagt, sein eigenes Volk sicher und erfolgreich halten."}},faq={{q="Wer wartet auf die Kiste?",a="Ritterkommandant Demar Brant wartet auf Frazzlespark's Crate auf Burg Farholde.",al={"wer will die kiste","lieferung an demar brant"}},{q="Wohin soll ich Frazzlespark's Crate bringen?",a="Bringt Frazzlespark's Crate zu Ritterkommandant Demar Brant auf Burg Farholde, südwestlich von Frazzlespark.",al={"standort der kiste","wo liegt burg farholde"}},{q="Warum will Demar, dass sein vollständiger Name verwendet wird?",a="Frazzlespark merkt an, dass Demar den Goblin stets seinen vollständigen Namen verwenden lässt, nennt aber keinen Grund dafür.",al={"demars vollständiger name","warum ritterkommandant"}},{q="Warum nennt Frazzlespark es eine besondere Lieferung?",a="Frazzlespark nennt es eine besondere Lieferung und sagt, dass Demar Brant auf Burg Farholde darauf wartet.",al={"kistenlieferung","was ist besonders an der kiste"}},{q="Warum ist diese Lieferung wichtig?",a="Demar Brant sagt, gewisse Geschäfte müssten getätigt werden, um die Sicherheit und den Erfolg seines Volkes zu gewährleisten, und nennt den Goblin nichts weiter als ein Mittel zum Zweck.",al={"warum die kiste liefern","sicherheit der goblins"}}},fp="20,126,19.303.0,29.82.0,37.102.0,39.95.0,49.98.0,30.152.0"}
P.entries["quest:95065"] = {n="Fishin' Time",s="Im Hafen von Sturmwind bleibt Gilbert Gray an seiner Angel, solange die Fische anbeißen. Seine Vorräte werden knapp, also bittet er Vorbeigehende, Nachtkriecher und ein glänzendes Schmuckstück aus einem Laden an den Canals der Stadt zu holen.",h="Im Hafen von Sturmwind bleibt Gilbert Gray an seiner Angel, solange die Fische anbeißen.",kw={"canals","catherine leland","fishin time","gilbert gray","nachtkriecher","glänzendes schmuckstück","hafen von sturmwind","der handelsdistrikt"},ang={["faction:Alliance"]="Als Bürger der Allianz stärkt Ihr das Leben und die Zuversicht in ganz Sturmwind, indem Ihr Gilbert Gray bei einem alltäglichen Anliegen helft.",["race:Human"]="Als Mensch, der in Sturmwind zu Hause ist, findet Ihr eine Pause von der Politik des Königreichs, indem Ihr einem älteren Mann einen ruhigen Angelnachmittag ermöglicht."},sec={{t="Ein Tag am Wasser",b="Gilbert Gray beobachtet, wie seine Pose auf dem Wasser tanzt. Der ältere Angler will seinen geliebten Angelplatz nicht verlassen, solange die Fische anbeißen. Seine Vorräte sind aufgebraucht, und er braucht Hilfe, damit er an seiner Angel bleiben kann, statt in die Stadt zurückzukehren."},{t="Vorräte an den Canals",b="Catherine Leland betreibt einen Laden für Angelbedarf an Sturmwinds steinernen Canals, direkt westlich des Handelsdistrikts. Fischer aus der ganzen Stadt kommen zu ihr, um Lockmittel und Köder zu kaufen. Ihr Laden kann die Vorräte auffüllen, die Gilbert Gray zum Weiterangeln braucht."}},faq={{q="Wer ist Gilbert Gray?",a="Gilbert Gray ist ein älterer Fischer im Hafen von Sturmwind. Er verbringt seine Tage damit, seine Angel ins Meer auszuwerfen, und bittet Vorbeigehende, Köder und Lockmittel zu holen, wenn seine Vorräte knapp werden.",al={"gilbert gray","alter gray","wer vergibt diese quest"}},{q="Wer ist Catherine Leland?",a="Catherine Leland betreibt einen Laden für Angelbedarf an den Canals der Stadt, direkt westlich des Handelsdistrikts. Sie verkauft Angelausrüstung und Köder an Sturmwinds Angler.",al={"catherine leland","angelhändler sturmwind","leland sturmwind"}},{q="Wo angelt Gilbert Gray?",a="Gilbert Gray angelt im Hafen von Sturmwind, wo er den freien Blick aufs Meer genießt.",al={"gilbert gray standort","wo ist gilbert gray","fischer im hafen"}},{q="Welche Vorräte braucht Gilbert Gray?",a="Gilbert Gray braucht Nachtkriecher als Köder und ein glänzendes Schmuckstück als Lockmittel. Catherine Leland verkauft beides an den Canals.",al={"questgegenstände fishin time","welchen köder will gray"}},{q="Warum holt Gilbert Gray die Vorräte nicht selbst?",a="Die Fische beißen an, und Gilbert Gray will seinen Platz nicht verlassen oder einen guten Fang verpassen, um in der Stadt Vorräte zu holen.",al={"warum kann gray keine köder kaufen","warum braucht gray hilfe"}},{q="Wo an den Canals liegt Catherine Lelands Laden?",a="Catherine Lelands Laden liegt an den Canals direkt westlich des Handelsdistrikts, neben den steinernen Gehwegen über den Wasserwegen der Stadt.",al={"catherine leland standort","wo ist lelands laden","handelsdistrikt canals"}}},fp="12,206,18.235.0,25.223.0,20.167.0,24.160.0,29.82.0,37.118.0,52.132.0,58.129.0"}
P.entries["quest:951"] = {n="Relikte von Mathystra",s="An der Nordostküste der Dunkelküste könnten Relikte von Mathystra zeigen, wie der Schattenhammer uralte Elfenmagie beugt. Onu, ein Urahne der Lehren im Hain der Uralten, sucht sie, um die Absichten des Kults zu ergründen.",h="An der Nordostküste der Dunkelküste könnten Relikte von Mathystra zeigen, wie der Schattenhammer uralte...",kw={"dunkelküste","der hain der uralten","die meistergleve","mathystra","onu","relikte","die ruinen von mathystra","schattenhammer"},ang={["class:Druid"]="Als Druide steht Ihr Onu bei, einem der größten uralten Wächter der Natur. Ihr helft, die uralte Geschichte der Dunkelküste vor finsteren Kultisten zu bewahren.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, das nördliche Kalimdor vor dunklen Mächten unter der Erde zu schützen, indem Ihr den Schattenhammer daran hindert, uralte Magie als Waffe einzusetzen.",["race:NightElf"]="Als Nachtelf seht Ihr, wie Relikte aus der glorreichen Zeit Eures Volkes vor der Zerschlagung aus der Erde geborgen werden. Sein Untergang ist eine düstere Mahnung, und der Einsatz der mächtigen Künste Eurer Ahnen durch den Schattenhammer ist ein alarmierendes Warnzeichen."},sec={{t="Eine beunruhigende Entdeckung",b="Nachdem Ihr ein verderbtes Pergament von Kultisten des Schattenhammers nahe der Meistergleve geborgen hattet, entschlüsselte Onu seine Bedeutung. Die Schrift stammte nicht vom Kult selbst. Es war ein verfluchtes Fragment uralter Nachtelfenschrift, besudelt vom Schattenhammer. Die Fanatiker nutzen vergessene Elfenmagie, um ihre uralten Meister zu erwecken oder in die sterbliche Welt zu beschwören."},{t="Die gefallene Bastion",b="Onu schickt Euch zu den Ruinen von Mathystra am nordöstlichen Ufer der Dunkelküste. Vor der Zerschlagung war Mathystra eine strahlende Bastion der Zivilisation der Hochgeborenen. Die Stadt verfiel zu Trümmern, Unkraut und Naga, doch ihre alten Verzauberungen überdauern in zerbrochenen Urnen und Relikten, die zwischen den Steinfundamenten verstreut liegen."},{t="Finsteren Plänen auf der Spur",b="Ihr sammelt erhaltene Relikte aus den grasbewachsenen Trümmern, damit die Verteidiger der Dunkelküste erfahren, welche Künste der Kult nutzen will. Onu untersucht die Magie, die in jedem Stück verblieben ist. Er muss die Pläne des Kults aufdecken, bevor der Schattenhammer uralte Zauberei der Kaldorei beugt, um seine unterirdischen Meister zu befreien."}},faq={{q="Was sind die Relikte von Mathystra?",a="Die Relikte von Mathystra sind Bruchstücke verzauberter Töpferwaren, Urnen und Artefakte aus den Ruinen. Sie wurden zur Blütezeit der uralten Nachtelfenzivilisation vor der Großen Zerschlagung geschaffen und bergen noch immer Reste von Magie.",al={"was sind die relikte","hintergrund der relikte von mathystra","elfenrelikte mathystra"}},{q="Warum will Onu diese Relikte?",a="Onu will die Relikte, weil der Schattenhammer uralte Elfenmagie nutzt, um seine dunklen Meister zurück in die Welt zu bringen. Indem er unversehrte Stücke aus Mathystra untersucht, hofft er zu erfahren, wie der Kult diese Macht einsetzen wird.",al={"warum will onu relikte","zweck der relikte von mathystra"}},{q="Wo befanden sich die Ruinen von Mathystra?",a="Die Ruinen von Mathystra liegen an der Nordostküste der Dunkelküste, nördlich von Ameth'Aran und Bashal'Aran und gleich hinter dem Turm von Althalaxx.",al={"wo ist mathystra","mathystra lage"}},{q="Wen versucht der Schattenhammer zurückzubringen?",a="Der Schattenhammer will seine uralten, bösartigen Meister zurückbringen. Onu warnt, dass der Kult uralte Elfenmagie nutzt, um sie nach Azeroth zurückzuholen.",al={"wer sind die meister des schattenhammers","kultmeister dunkelküste"}},{q="Was war Mathystra, bevor es zur Ruine wurde?",a="Mathystra war vor Tausenden von Jahren eine große Stadt und Bastion der Nachtelfen. Die Große Zerschlagung hinterließ nur Ruinen, und Wildnis, Geister und abscheuliche Strandbewohner wie die Naga nahmen sie in Besitz.",al={"geschichte von mathystra","was war mathystra"}},{q="Wer vergibt die Quest „Relikte von Mathystra“?",a="Onu gibt Euch nach Eurer Untersuchung der Meistergleve die Aufgabe „Relikte von Mathystra“. Er ist ein uralter Treant, der im Hain der Uralten im südlichen Zentrum der Dunkelküste verwurzelt ist.",al={"wer startet relikte von mathystra","questgeber relikte von mathystra"}}},fp="16,215,22.360.1,18.296.0,21.293.1,30.220.0,31.222.0,42.138.0,50.154.0,43.204.0,39.177.0"}
P.entries["quest:95111"] = {n="An Underrated Talent",s="Im Silberwald gibt Trevan Rol Ott die Chance, eine Klinge nach Euren Vorgaben zu fertigen. Otts schlichte Waffen haben bei den Schmieden in der Unterstadt Lob geerntet.",h="Im Silberwald gibt Trevan Rol Ott die Chance, eine Klinge nach Euren Vorgaben zu fertigen.",kw={"auftrag","klinge nach maß","ott","schmied","tarrens mühle","unterstadt","waffenschmied"},sec={{t="Die Chance des Schmieds",b="Trevan Rol bittet Euch, Materialien zu Ott nach Tarrens Mühle zu bringen und ihm einen Auftrag anzubieten. Ott verkauft schlichte Klingen an Reisende. Trevan kaufte eine und brachte sie später zur Wartung in die Unterstadt. Dort lobten die örtlichen Schmiede ihre Qualität und hielten sie für das Werk eines berühmten Meisters. Nun hat Ott die Chance, eine Klinge nach Euren Vorgaben zu schmieden."},{t="Otts Antwort",b="Ott sagt, dass ihn noch nie jemand gebeten hat, eine Waffe nach Maß anzufertigen. Für gewöhnlich fertigt er schlichte, zweckmäßige Waffen in seinem eigenen Stil und strebt nicht nach Anerkennung. Dennoch ist er bereit, es zu versuchen. Er fragt sich, warum Ihr ihn gewählt habt, wo doch auch Schmiede in der Unterstadt Sonderanfertigungen übernehmen."}},faq={{q="Wer ist Ott?",a="Ott ist ein Waffenschmied in Tarrens Mühle, der schlichte Klingen an Reisende verkauft.",al={"ott schmied","wer ist ott","tarrens mühle schmied"}},{q="Warum will der Schmied aus der Unterstadt, dass ich Ott finde?",a="Der Schmied kaufte eine von Otts Klingen und war überrascht, als Schmiede in der Unterstadt ihre Qualität lobten. Der Schmied möchte Ott die Chance geben, etwas Besonderes zu fertigen.",al={"warum ott","unterstadt schmied auftrag","ott auftrag"}},{q="Was bringe ich Ott?",a="Ihr bringt Materialien zu Ott nach Tarrens Mühle und bietet ihm einen Auftrag an, Eure Klinge zu schmieden.",al={"materialien für ott","was mitbringen","ott materialien"}},{q="Fertigt Ott Waffen nach Maß an?",a="Ott sagt, dass ihn noch nie jemand gebeten hat, eine Waffe nach Maß anzufertigen, aber er ist bereit, es zu versuchen.",al={"ott klinge nach maß","kann ott auf bestellung schmieden","ott aufträge"}},{q="Warum fragt Ott, weshalb ich ihn gewählt habe?",a="Ott sagt, dass Schmiede in der Unterstadt Sonderanfertigungen übernehmen, und fragt sich, warum Ihr stattdessen ihn aufgesucht habt.",al={"warum ott wählen","ott fragt sich warum","warum kein schmied aus der unterstadt"}}},fp="20,155,16.348.0,12.255.1,11.73.0,49.163.0,26.97.0,29.87.0,33.90.0"}
P.entries["quest:95118"] = {n="Saltwater Savages",s="Ein Hafenmeister bittet Euch, die Murlocs an der Eastwind Shore zu dezimieren. Seeleute, Fischer und seine Kinder beschweren sich ständig über die Plage.",h="Ein Hafenmeister bittet Euch, die Murlocs an der Eastwind Shore zu dezimieren.",kw={"eastwind shore","fischer","murloc","murloc-orakel","murloc-krieger","hafenmeister","seeleute","salzwasserbarbaren"},sec={{t="Beschwerden im Hafen",b="Der Hafenmeister hat genug Beschwerden von Seeleuten, Fischern und sogar seinen Kindern gehört. Die Murlocs machen ihm zu schaffen, doch er muss weiterhin den Hafen führen. Er bittet Euch, einige an der Eastwind Shore zu töten, in der Hoffnung, etwas Ruhe vor dem Lärm um ihn herum zu haben."}},faq={{q="Warum will der Hafenmeister, dass die Murlocs getötet werden?",a="Seeleute, Fischer und die Kinder des Hafenmeisters beschweren sich ständig über sie. Er nennt sie eine Plage und möchte etwas Ruhe, während er den Hafen führt.",al={"warum murlocs töten","murlocs belästigen hafen"}},{q="Welche Murlocs meint er?",a="Er bittet Euch, Murloc-Orakel und Murloc-Krieger an der Eastwind Shore zu töten.",al={"murloc-arten","orakel und krieger"}},{q="Wo sind die Murlocs?",a="Der Hafenmeister weist Euch zur Eastwind Shore.",al={"murlocs an der eastwind shore","wo murlocs"}},{q="Löst das Töten dieser Murlocs das Problem?",a="Der Hafenmeister rechnet damit, dass bald weitere Murlocs zurückkehren, hofft aber, dass ihr Tod ihm bis dahin etwas Ruhe verschafft.",al={"murlocs kehren zurück","ist es vorbei"}}},fp="17,152,22.244.0,49.149.0,33.76.0,22.45.0,45.118.0"}
P.entries["quest:95120"] = {n="WANTED: Old Rot-Chum",s="Wharfmaster Whizzbuzz setzt eine Belohnung für einen Beweis auf Old Rot-Chums Tod aus. Der aggressive Murloc greift kleine Schiffe in den südlichen Gewässern an.",h="Wharfmaster Whizzbuzz setzt eine Belohnung für einen Beweis auf Old Rot-Chums Tod aus.",kw={"murloc","murlocinseln","old rot-chum","ruderboote","kleine schiffe","südliche gewässer","wharfmaster whizzbuzz"},sec={{t="Eine Gefahr auf See",b="Seeleute und Schwimmer in den südlichen Gewässern werden auf Ruderbooten und anderen kleinen Schiffen angegriffen. Die einheimischen Fischer nennen den aggressiven Murloc dahinter Old Rot-Chum. Wharfmaster Whizzbuzz setzt eine Belohnung für einen Beweis aus, dass das Wesen tot ist, und bittet Euch, ihn ihm zu bringen."}},faq={{q="Wer ist Old Rot-Chum?",a="Old Rot-Chum ist der Spitzname, den einheimische Fischer einem besonders aggressiven Murloc gegeben haben.",al={"old rot-chum","rot-chum","wer ist rot-chum"}},{q="Wo wurde Old Rot-Chum gesichtet?",a="Old Rot-Chum wurde in den südlichen Gewässern gesichtet, nahe von Inseln, die von Murlocs verseucht sind.",al={"wo ist old rot-chum","rot-chums aufenthaltsort","wo ist der murloc"}},{q="Was hat Old Rot-Chum angegriffen?",a="Old Rot-Chum hat Ruderboote und andere kleine Schiffe angegriffen.",al={"was greift rot-chum an","bootsangriffe","murloc und ruderboote"}},{q="Wer setzt die Belohnung aus?",a="Wharfmaster Whizzbuzz setzt eine Belohnung für einen Beweis auf Old Rot-Chums Tod aus.",al={"wer will einen beweis für rot-chum","belohnung vom wharfmaster","wer zahlt für old rot-chum"}},{q="Welchen Beweis verlangt Whizzbuzz?",a="Wharfmaster Whizzbuzz bittet Euch, einen Beweis für Old Rot-Chums Tod zu bringen.",al={"welcher beweis für rot-chum","beweis bringen","proof of demise"}}},fp="20,154,15.274.0,20.82.0,33.90.0,37.65.0,22.87.0,34.73.0"}
P.entries["quest:95121"] = {n="A Taste of the Sea",s="Fimbo Greasemitz möchte frische Meeresfrüchte für einen neuen Eintopf in seinem Café am Wasser. Ihr sammelt Zutaten aus der Umgebung, um die Speisekarte aufzufrischen.",h="Fimbo Greasemitz möchte frische Meeresfrüchte für einen neuen Eintopf in seinem Café am Wasser.",kw={"strand","café","fimbo greasemitz","fisch","murloc-augen","gebratenes wildschwein","sand crawler fleisch","meeresfrüchteeintopf"},ang={["profession:Cooking"]="Als Koch erkennt Ihr, dass Fimbo frische Zutaten aus der Umgebung für einen Meeresfrüchteeintopf sucht."},sec={{t="Ein neues Gericht",b="Fimbo Greasemitz betreibt ein Café am Wasser, auf dessen Speisekarte täglich gebratenes Wildschwein und Fisch stehen. Er möchte einen Meeresfrüchteeintopf ausprobieren und bittet Euch, ihm Murloc-Augen und Sand-Crawler-Fleisch von den nahegelegenen Stränden zu bringen."}},faq={{q="Wer ist Fimbo Greasemitz?",a="Fimbo Greasemitz betreibt ein Café am Wasser und möchte Meeresfrüchteeintopf auf die Speisekarte setzen.",al={"wer ist fimbo","fimbo café","fimbo greasemitz"}},{q="Welche Zutaten braucht Fimbo?",a="Fimbo bittet um Murloc-Augen und Sand-Crawler-Fleisch für seinen Meeresfrüchteeintopf.",al={"zutaten für eintopf","welches fleisch","murloc-augen"}},{q="Warum möchte Fimbo Meeresfrüchte?",a="Er möchte mit einem neuen Rezept für Meeresfrüchteeintopf die tägliche Speisekarte des Cafés mit gebratenem Wildschwein und Fisch aufpeppen.",al={"warum eintopf","neue speisekarte","caféessen"}},{q="Wo findet Ihr die Zutaten?",a="Fimbo sagt, dass Ihr Murloc-Augen und Sand-Crawler-Fleisch an den nahegelegenen Stränden finden könnt.",al={"wo fleisch","wo zutaten","strandzeug"}}},fp="18,129,10.206.0,24.84.0,33.70.0,28.94.0,35.87.0"}
P.entries["quest:95125"] = {n="Otts Meisterwerk",s="Ott ist bereit, aus edlen Materialien eine Klinge für Euch zu schmieden. Ihr dürft ihm bei der Arbeit zusehen.",h="Ott ist bereit, aus edlen Materialien eine Klinge für Euch zu schmieden.",kw={"schmied","klinge","schmieden","meisterwerk","materialien","ott"},sec={{t="An der Schmiede",b="Ott schätzt die edlen Materialien und hofft, dass seine Arbeit Euren Erwartungen entspricht. Er schmiedet eine Klinge für Euch und bietet sie Euch dann für Eure Reisen an."}},faq={{q="Wer fertigt meine Klinge?",a="Ott schmiedet Eure Klinge aus den edlen Materialien, die Ihr bereitgestellt habt.",al={"wer schmiedet sie","otts klinge","ott schmied"}},{q="Kann ich Ott beim Schmieden zusehen?",a="Ott bittet Euch, zurückzutreten, während er mit dem Schmieden beginnt. Ihr werdet gebeten, ihm bei der Arbeit zuzusehen.",al={"ott beim schmieden zusehen","entstehung der klinge ansehen","schmiedevorgang"}},{q="Was sagt Ott, wenn die Klinge fertig ist?",a="Ott nennt die Klinge sein bestes Werk und hofft, dass sie Euch auf Euren Reisen gute Dienste leistet.",al={"ott fertigstellung","was sagt ott","klinge fertig"}}},fp="16,85,12.137.0,23.63.0,25.81.0,45.81.0"}
P.entries["quest:95126"] = {n="The Moonsilver Blade",s="Im Silberwald erwartet Trevan Rol die Klinge, die seine Arbeit vollenden wird, bevor er sich einem Biest stellt.",h="Im Silberwald erwartet Trevan Rol die Klinge, die seine Arbeit vollenden wird, bevor er sich einem Biest...",kw={"biest","lumina","mondsilberklinge","ott","ott's masterwork","silberwald","trevan rol"},sec={{t="Die Klinge",b="Ott dankt Euch für die Gelegenheit zu helfen und bittet Euch, Trevan seinen Dank auszurichten. Ihr bringt Ott's Masterwork zurück zu Trevan Rol im Silberwald."},{t="Trevans Zustimmung",b="Trevan Rol begutachtet die Klinge und ist mit Otts Arbeit zufrieden. Nur das Biest bleibt noch. Wenn Ihr bereit seid, weist er Euch an, mit Lumina zu sprechen."}},faq={{q="Wer hat Ott's Masterwork gefertigt?",a="Ott hat Ott's Masterwork gefertigt und es Euch für Trevan Rol mitgegeben.",al={"wer hat die klinge gefertigt","ott klinge","meisterwerk hersteller"}},{q="Wer ist Trevan Rol?",a="Trevan Rol nimmt Ott's Masterwork im Silberwald entgegen und begutachtet es.",al={"wer ist trevan","trevan klinge","trevan rol"}},{q="Wohin soll ich die Klinge bringen?",a="Bringt Ott's Masterwork zu Trevan Rol im Silberwald.",al={"wohin mit der klinge","ott's masterwork wohin bringen","klinge ziel"}},{q="Was hält Trevan von der Klinge?",a="Trevan Rol begutachtet die Klinge und sagt, sie werde gute Dienste leisten.",al={"gefällt trevan die klinge","ist otts klinge gut","trevans zustimmung"}},{q="Mit wem soll ich nach Trevan sprechen?",a="Wenn Ihr bereit seid, weist Trevan Rol Euch an, mit Lumina zu sprechen.",al={"was als nächstes","wer ist lumina","mit lumina sprechen"}}},fp="20,102,9.152.0,17.138.1,26.61.0,18.71.0,27.58.0,36.57.0,37.64.0"}
P.entries["quest:95140"] = {n="Old Fire-Eye",s="Lumina Windsinger schickt Euch mit der Mondsilberklinge auf die Jagd nach Old Fire-Eye im Silberwald. Die Windformer erwarten seinen Tod, und Lumina hofft, dass die Klinge Euch gut leiten wird.",h="Lumina Windsinger schickt Euch mit der Mondsilberklinge auf die Jagd nach Old Fire-Eye im Silberwald.",kw={"banon","gilneas","lumina windsinger","mondsilberklinge","old fire-eye","silberwald","windformer"},sec={{t="Der Zweck einer Klinge",b="Die Windformer haben Euch die Mondsilberklinge gegeben. Die Einheimischen sagen, Old Fire-Eye jage in einem weitläufigen Gebiet südlich von hier, meist nahe den Toren von Gilneas. Lumina bittet Euch, ihn zu finden und mit der Klinge zu töten. Die Dankbarkeit der Windformer hängt von seinem Tod ab."},{t="Nach der Jagd",b="Als Ihr zurückkehrt, dankt Lumina Euch und sagt, Banon könne in Frieden ruhen. Dann legt sie einen kleinen Teil der Magie ihres Volkes auf die blutbefleckte Klinge und hofft, dass die Winde sie gut leiten werden."}},faq={{q="Wer bittet mich, Old Fire-Eye zu jagen?",a="Lumina Windsinger bittet Euch, Old Fire-Eye mit der Mondsilberklinge zu jagen.",al={"wer hat mich geschickt","luminas auftrag","windsinger"}},{q="Wo kann ich Old Fire-Eye finden?",a="Die Einheimischen sagen, Old Fire-Eye jage in einem weitläufigen Gebiet südlich von Lumina, meist nahe den Toren von Gilneas.",al={"fire eye fundort","wo ist old fire-eye","tore von gilneas"}},{q="Was sollte ich gegen Old Fire-Eye einsetzen?",a="Lumina bittet Euch, Old Fire-Eye mit der Mondsilberklinge zu töten.",al={"klinge für fire-eye","mondsilberwaffe","welche waffe"}},{q="Warum will Lumina, dass Old Fire-Eye getötet wird?",a="Lumina sagt, die Windformer werden dankbar sein, wenn Old Fire-Eye tot ist.",al={"warum fire-eye töten","warum ihn jagen","fire-eye grund"}},{q="Wer ist Banon?",a="Lumina sagt, Banon könne in Frieden ruhen, nachdem Old Fire-Eye getötet wurde.",al={"banon wer","banon frieden","wer ist banon"}},{q="Was macht Lumina mit der Klinge?",a="Lumina legt einen kleinen Teil der Magie ihres Volkes auf die blutbefleckte Mondsilberklinge.",al={"klingenmagie","lumina verzaubert klinge","windmagie"}}},fp="12,175,17.261.0,14.186.1,38.74.0,30.100.0,39.64.0,40.71.0,13.64.0,35.89.0"}
P.entries["quest:95141"] = {n="Report to Rog'mar",s="Ein Orc schickt Euch nach Rog'mar, einem Außenposten in den umkämpften Flusslanden. Meldet Euch bei Krom'rosh, dessen Erfahrung dem Außenposten geholfen hat, wiederholten Angriffen standzuhalten.",h="Ein Orc schickt Euch nach Rog'mar, einem Außenposten in den umkämpften Flusslanden.",kw={"angriffe","ostküste","krom'rosh","außenposten","flusslande","rog'mar","steinard"},sec={{t="Ein Außenposten hält stand",b="Die Flusslande liegen nordöstlich von Steinard an der Ostküste. Viele haben versucht, das Land für sich zu beanspruchen, doch nur wenigen ist es gelungen. Rog'mar ist ein kleiner Außenposten, der zahllose Angriffe überstanden hat. Ihr werdet dorthin geschickt, um Euch bei Krom'rosh zu melden, einem alten Verbündeten, dessen Kampferfahrung dem Außenposten geholfen hat, standzuhalten."}},faq={{q="Wo liegt Rog'mar?",a="Rog'mar liegt in den Flusslanden, nordöstlich von Steinard an der Ostküste.",al={"rog'mar lage","wo liegt rogmar","rog'mar außenposten"}},{q="Bei wem soll ich mich melden?",a="Ihr sollt Euch bei Krom'rosh im Außenposten Rog'mar melden.",al={"bei wem melden","wer ist krom'rosh","kromrosh"}},{q="Was ist Rog'mar?",a="Rog'mar ist ein kleiner Außenposten in den Flusslanden, der zahllosen Angriffen standgehalten hat.",al={"was ist rogmar","flusslande außenposten","kleiner außenposten"}},{q="Warum ist Krom'rosh in Rog'mar?",a="Krom'roshs Erfahrung im Kampf gegen Feinde hat dem Außenposten geholfen, standzuhalten.",al={"warum ist kromrosh dort","krom'rosh rolle","wer leitet rogmar"}},{q="Was für ein Land sind die Flusslande?",a="Die Flusslande sind ein umkämpftes Land an der Ostküste, nordöstlich von Steinard.",al={"flusslande","wie sind die flusslande","umkämpftes land"}}},fp="17,157,18.302.0,17.78.0,22.54.0,16.81.0,28.70.0,38.84.0"}
P.entries["quest:95143"] = {n="Finding Tan'jani",s="Ein Reisender bittet Euch, seinen Bruder Tan'jani zu finden. Nachrichten verorten ihn südlich von Loch Modan. Die jüngste weist auf Rog'mar in den Flusslanden hin.",h="Ein Reisender bittet Euch, seinen Bruder Tan'jani zu finden.",kw={"blutbefleckter brief","loch modan","vermisster bruder","flusslande","rog'mar","tan jani","tan'jani"},sec={{t="Ein Bruder fehlt",b="Der Bruder eines Reisenden, Tan'jani, ist aufgebrochen, um nach etwas Unbekanntem zu suchen. Eine Nachricht verortet ihn irgendwo südlich von Loch Modan. Ein blutbefleckter Brief erwähnt die Flusslande und das weiter südlich gelegene Rog'mar. Der Reisende bittet Euch, ihn dort zu finden."}},faq={{q="Wer ist Tan'jani?",a="Tan'jani ist der Bruder des Reisenden, der Euch bittet, ihn zu finden.",al={"tan'jani","tan jani","vermisster bruder"}},{q="Wo wurde Tan'jani zuletzt erwähnt?",a="Ein blutbefleckter Brief erwähnt die Flusslande und Rog'mar, weiter südlich als Loch Modan.",al={"wo ist tan'jani","tan'janis aufenthaltsort","rog'mar"}},{q="Wonach suchte Tan'jani?",a="Tan'jani war immer auf der Suche nach etwas, doch sein Bruder weiß nicht, wonach.",al={"wonach hat er gesucht","tan'jani auf der suche","warum ist er fortgegangen"}},{q="Was steht in den Nachrichten?",a="Ein Reisender berichtete, Tan'jani irgendwo südlich von Loch Modan getroffen zu haben. Ein blutbefleckter Brief erwähnt die Flusslande und Rog'mar, doch der größte Teil ist unleserlich.",al={"nachrichten über tan'jani","blutbefleckter brief","was geschah mit dem brief"}}},fp="16,147,17.242.0,16.63.0,34.86.0,32.80.0,25.156.0"}
